(window.QUESTIONS_PARTS = window.QUESTIONS_PARTS || {})["md2"] = [{"id":"md2-105-1-1","subject":"md2","topic":"生理-心臟血管","meta":"105年第1次第1題","year":105,"session":1,"number":1,"question":"烏巴苷（ouabain）能抑制鈉－鉀腺苷三磷酸酶（Na+-K+ ATPase）。若將烏巴苷注射於實驗用小鼠之心臟，其心肌細胞膜上鈉－鈣交換器（Na+-Ca2+ exchanger）排除鈣離子的量為何？","options":["(A) 減少","(B) 增加","(C) 不變","(D) 先增加後減少"],"answer":0,"image":""},{"id":"md2-105-1-2","subject":"md2","topic":"生理-細胞神經肌肉","meta":"105年第1次第2題","year":105,"session":1,"number":2,"question":"下列有關中樞聽覺傳導路徑的敘述，何者最正確？","options":["(A) cochlear nuclei →inferior colliculus→medial geniculate body→auditory cortex","(B) cochlear nuclei→superior colliculus→medial geniculate body→auditory cortex","(C) cochlear nuclei→inferior colliculus→lateral geniculate body→auditory cortex","(D) cochlear nuclei→superior colliculus→lateral geniculate body→auditory cortex"],"answer":0,"image":""},{"id":"md2-105-1-3","subject":"md2","topic":"生理-細胞神經肌肉","meta":"105年第1次第3題","year":105,"session":1,"number":3,"question":"對於不同強度的感覺刺激，神經纖維的主要變化參數為何？","options":["(A) frequency of action potential","(B) amplitude of action potential","(C) duration of each action potential","(D) latency of receptor potential"],"answer":0,"image":""},{"id":"md2-105-1-4","subject":"md2","topic":"解剖-神經解剖","meta":"105年第1次第4題","year":105,"session":1,"number":4,"question":"背柱中央蹄系統（dorsal column-medial lemniscal system）中訊息經由first-order neuron，second-order neuron以及third-order neuron由周邊往中樞傳遞，對於這三類neurons之細胞體的可能所在位置之敘述，下列何者正確？","options":["(A) first-order neuron位於dorsal horn of the spinal cord","(B) second-order neuron位於brain stem","(C) third-order neuron位於hypothalamus","(D) third-order neuron位於substantial nigra"],"answer":1,"image":""},{"id":"md2-105-1-5","subject":"md2","topic":"生理-細胞神經肌肉","meta":"105年第1次第5題","year":105,"session":1,"number":5,"question":"下列何處受損，最可能導致病患喪失原先已經會使用刀叉吃東西的能力？","options":["(A) primary motor cortex","(B) supplementary motor area","(C) premotor cortex","(D) posterior parietal cortex"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第5題答Ａ、Ｂ、Ｃ、Ｄ給分 (原公告答案 D)"},{"id":"md2-105-1-6","subject":"md2","topic":"生理-細胞神經肌肉","meta":"105年第1次第6題","year":105,"session":1,"number":6,"question":"在運動控制的階層中，下列何者屬於最下階的執行層級？","options":["(A) 脊髓","(B) 基底核","(C) 小腦","(D) 大腦的初級運動皮層（primary motor cortex）"],"answer":0,"image":""},{"id":"md2-105-1-7","subject":"md2","topic":"生理-消化","meta":"105年第1次第7題","year":105,"session":1,"number":7,"question":"下列那一種肌細胞受到牽張（stretch）最可能會產生收縮？","options":["(A) 骨骼肌","(B) 心肌","(C) 小腸平滑肌","(D) 大動脈平滑肌"],"answer":2,"image":""},{"id":"md2-105-1-8","subject":"md2","topic":"病理-心血管血液","meta":"105年第1次第8題","year":105,"session":1,"number":8,"question":"下列何者是A型血友病（hemophilia A）的起因？","options":["(A) tissue factor pathway inhibitor過度產生","(B) prothrombin（factor II）基因缺陷","(C) factor X無法被鈣離子活化","(D) factor VIII基因缺陷"],"answer":3,"image":""},{"id":"md2-105-1-9","subject":"md2","topic":"生理-心臟血管","meta":"105年第1次第9題","year":105,"session":1,"number":9,"question":"心室肌細胞的動作電位變化，可分第零期：去極化（depolarization）；第一期：快速再極化（rapid repolarization）；第二期：持續的高原期（plateau）；第三期：最終的再極化（final repolarization）；第四期：靜止膜電位（resting membrane potential）。關於鉀離子通道角色的敘述，下列何者是正確的？","options":["(A) 第零期的機制之一是鉀離子通道的關閉","(B) 第一期的機制之一是鉀離子通道關閉","(C) 在第二期中，所有的鉀離子通道會完全關閉","(D) 引發第三期的主要因素是鉀離子通道開啟"],"answer":3,"image":""},{"id":"md2-105-1-10","subject":"md2","topic":"生理-心臟血管","meta":"105年第1次第10題","year":105,"session":1,"number":10,"question":"活化下列那一蛋白質可加速心肌的放鬆，使心室充血期時間比例增加？","options":["(A) 細胞膜上L-型鈣離子通道（L-type Ca2+ channels）","(B) 肌漿網上雷恩諾鹼受體（ryanodine receptors）","(C) 肌旋轉素（troponin）","(D) 肌漿網上鈣離子幫浦（Ca2+ ATPase）"],"answer":3,"image":""},{"id":"md2-105-1-11","subject":"md2","topic":"生理-心臟血管","meta":"105年第1次第11題","year":105,"session":1,"number":11,"question":"在心動週期（cardiac cycle）的那一期最可能觀察的主動脈壓（aortic pressure）出現短暫先降後升的重搏凹跡（dicrotic notch）現象？","options":["(A) 等容心室舒張期（isovolumetric ventricular relaxation）","(B) 心室充血期（ventricular filling）","(C) 等容心室收縮期（isovolumetric ventricular contraction）","(D) 心室射血期（ventricular ejection）"],"answer":0,"image":""},{"id":"md2-105-1-12","subject":"md2","topic":"生理-呼吸","meta":"105年第1次第12題","year":105,"session":1,"number":12,"question":"正常休息狀態下，周邊組織中的血液經過氣體交換後，離開組織時其內的血紅素氧飽和度（hemoglobin oxygen saturation）約為：","options":["(A) 90%","(B) 75%","(C) 50%","(D) 25%"],"answer":1,"image":""},{"id":"md2-105-1-13","subject":"md2","topic":"生理-呼吸","meta":"105年第1次第13題","year":105,"session":1,"number":13,"question":"體動脈血（systemic arterial blood）中二氧化碳分壓（PCO₂）升高時會刺激換氣（ventilation），最主要係透過下列何種機制？","options":["(A) 二氧化碳穿透血腦障壁進入延髓後，直接刺激中樞化學感受器（central chemoreceptor）","(B) 二氧化碳穿透血腦障壁進入延髓後，形成碳酸再產生氫離子，氫離子刺激中樞化學感受器（central chemoreceptor）","(C) 二氧化碳在體動脈血中形成碳酸再產生氫離子，氫離子穿透血腦障壁進入延髓後，刺激中樞化學感受器（central chemoreceptor）","(D) 二氧化碳在體動脈血中形成碳酸再產生氫離子，氫離子刺激周邊化學感受器（peripheral chemoreceptor）"],"answer":1,"image":""},{"id":"md2-105-1-14","subject":"md2","topic":"生理-呼吸","meta":"105年第1次第14題","year":105,"session":1,"number":14,"question":"吳先生因身體不適至醫院就診，體循環血液數值顯示：動脈血氧分壓（PaO₂）為55 mmHg，動脈血二氧化碳分壓（PaCO₂）為61 mmHg，酸鹼值為7.16，碳酸氫根為24.5 mEq/L。這名患者最可能的診斷為何？","options":["(A) 急性呼吸道阻塞","(B) 慢性呼吸道阻塞","(C) 腎衰竭","(D) 腎衰竭合併呼吸代償"],"answer":0,"image":""},{"id":"md2-105-1-15","subject":"md2","topic":"生理-消化","meta":"105年第1次第15題","year":105,"session":1,"number":15,"question":"下列何者屬於外胜肽酶（exopeptidase）？","options":["(A) 胺基胜肽酶（aminopeptidase）","(B) 胰凝乳蛋白酶（chymotrypsin）","(C) 彈性酶（elastase）","(D) 胰蛋白酶（trypsin）"],"answer":0,"image":""},{"id":"md2-105-1-16","subject":"md2","topic":"生理-消化","meta":"105年第1次第16題","year":105,"session":1,"number":16,"question":"各種消化道平滑肌收縮模式中，那一種是大腸特有的平滑肌收縮？","options":["(A) peristaltic wave","(B) segmentation contraction","(C) tonic contraction","(D) mass action contraction"],"answer":3,"image":""},{"id":"md2-105-1-17","subject":"md2","topic":"生理-腎臟","meta":"105年第1次第17題","year":105,"session":1,"number":17,"question":"葡萄糖分子在腎小管近端上皮細胞的再吸收，最主要是透過何種機制進行？","options":["(A) 次級主動運輸（secondary active transport）","(B) 二價鐵離子媒介之轉化作用（Fe2+-mediated conversion）","(C) 胞噬作用（phagocytosis）","(D) 氧化磷酸化作用（oxidative phosphorylation）"],"answer":0,"image":""},{"id":"md2-105-1-18","subject":"md2","topic":"生理-腎臟","meta":"105年第1次第18題","year":105,"session":1,"number":18,"question":"當尿液中X之濃度為36 mg/mL，血漿中X之濃度為0.25 mg/mL，若受測者尿量為1 mL/min，血比容（hematocrit）為50%，則X的血漿清除率（clearance）最接近多少mL/min？","options":["(A) 9","(B) 18","(C) 144","(D) 288"],"answer":2,"image":""},{"id":"md2-105-1-19","subject":"md2","topic":"生理-腎臟","meta":"105年第1次第19題","year":105,"session":1,"number":19,"question":"有關腎臟近端腎小管對於水的再吸收之敘述，下列何者錯誤？","options":["(A) 在接近近端腎小管末端內液體，滲透壓會上升至腎小球過濾液的2倍","(B) 近端腎小管上皮的頂膜與基底外側有第一型水通道（aquaporin-1）以協助管內水分被快速再吸收","(C) 近端腎小管約可再吸收腎小球過濾液60～70%的水分","(D) 高血糖（例如糖尿病）造成多尿症主要是透過影響近端腎小管水分吸收"],"answer":0,"image":""},{"id":"md2-105-1-20","subject":"md2","topic":"生理-內分泌代謝","meta":"105年第1次第20題","year":105,"session":1,"number":20,"question":"下列何者是活化態維生素D的分子結構？","options":["(A) 1, 25-dihydroxycholecalciferol","(B) 7-dehydrocholesterol","(C) 25-hydroxycholecalciferol","(D) cholecalciferol"],"answer":0,"image":""},{"id":"md2-105-1-21","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第1次第21題","year":105,"session":1,"number":21,"question":"下列何種症狀與佝僂症（rickets）最無關？","options":["(A) 兒童出現生長遲緩","(B) 智力發育遲緩","(C) 血中鈣濃度降低","(D) 牙齒發育不全"],"answer":1,"image":""},{"id":"md2-105-1-22","subject":"md2","topic":"生理-生殖","meta":"105年第1次第22題","year":105,"session":1,"number":22,"question":"有關調控人類月經週期之激素變化及其作用描述，下列何者錯誤？","options":["(A) 黃體促素（luteinizing hormone）在排卵前的大量分泌是造成排卵的主要原因","(B) 血漿中助孕酮（progesterone）只有在排卵後才會明顯升高","(C) 血漿中雌激素（estrogen）只會在排卵前有分泌增高的現象","(D) 濾泡（follicle）顆粒細胞（granulosa cell）分泌之雌激素（estrogen）與卵的發育成熟有關"],"answer":2,"image":""},{"id":"md2-105-1-23","subject":"md2","topic":"生理-內分泌代謝","meta":"105年第1次第23題","year":105,"session":1,"number":23,"question":"下列何種激素扮演促進胎兒時期中樞神經發育的關鍵角色？","options":["(A) 生長激素（growth hormone）","(B) 甲狀腺素（thyroxine）","(C) 腎上腺皮質醇（cortisol）","(D) 泌乳素（prolactin）"],"answer":[0,1],"image":"","answer_note":"更正:第23題答Ａ、Ｂ給分"},{"id":"md2-105-1-24","subject":"md2","topic":"生理-內分泌代謝","meta":"105年第1次第24題","year":105,"session":1,"number":24,"question":"承上題，罹患先天性缺乏此類激素之病患，臨床可見下列那些病徵？①生長遲緩 ②智能發育受損 ③低血鉀症 ④甲狀腺功能低下 ⑤性早熟","options":["(A) 僅①②③","(B) 僅①④⑤","(C) 僅①②④","(D) 僅②③⑤"],"answer":2,"image":""},{"id":"md2-105-1-25","subject":"md2","topic":"生理-內分泌代謝","meta":"105年第1次第25題","year":105,"session":1,"number":25,"question":"承上題，本症臨床上稱為什麼？","options":["(A) 呆小症（cretinism）","(B) 先天性腎上腺增生症（congenital adrenal hyperplasia）","(C) 生長激素缺乏性侏儒症（dwarfism）","(D) 普拉德－威利症候群（Prader-Willi syndrome）"],"answer":0,"image":""},{"id":"md2-105-1-26","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第1次第26題","year":105,"session":1,"number":26,"question":"蛋白質中的平行鏈（parallel β-stranded）結構比反平行鏈（antiparallel β-stranded）結構較不穩定，原因為何？","options":["(A) 平行鏈結構的横向相鄰鏈之間所形成的氫鍵鍵結較弱","(B) 平行鏈結構缺少雙硫鍵（disulfide bond）與鄰近的鏈鍵結","(C) 平行鏈結構不能如反平行鏈堆疊（stacking）成β-折疊層（β-sheet）","(D) 平行鏈結構缺少蛋白質-蛋白質結合區域（protein-protein binding domain）以穩定平行鏈結構"],"answer":0,"image":""},{"id":"md2-105-1-27","subject":"md2","topic":"藥理-化學治療","meta":"105年第1次第27題","year":105,"session":1,"number":27,"question":"青黴素（penicillin）的殺菌作用是因為它能抑制下列何種酵素的活性？","options":["(A) 內醯胺酶（β-lactamase）","(B) 轉肽基酶（transpeptidase）","(C) 接合酶（ligase）","(D) 醛縮酶（aldolase）"],"answer":1,"image":""},{"id":"md2-105-1-28","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第1次第28題","year":105,"session":1,"number":28,"question":"在水溶液的pH值低於胺基酸的pI值時，該胺基酸的主要性質為何？","options":["(A) 呈淨負電荷","(B) 呈淨正電荷","(C) 呈中性","(D) 呈正、負電荷等量"],"answer":1,"image":""},{"id":"md2-105-1-29","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第1次第29題","year":105,"session":1,"number":29,"question":"一位30歲女性主訴有牙齒鬆動、傷口不易癒合等症狀，口腔理學檢查發現牙齦浮腫、牙齦泛紫。根據病史，此病患最可能有下列何種維生素缺乏？","options":["(A) 維生素B1","(B) 維生素B12","(C) 維生素C","(D) 維生素A"],"answer":2,"image":""},{"id":"md2-105-1-30","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第1次第30題","year":105,"session":1,"number":30,"question":"RNA降解後，CMP與UMP主要會被代謝成下列那一個中間產物？","options":["(A) β-aminoisobutyrate","(B) thymine","(C) uracil","(D) hypoxanthine"],"answer":2,"image":""},{"id":"md2-105-1-31","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第1次第31題","year":105,"session":1,"number":31,"question":"核酸去嘌呤作用（depurination of nucleotides）是破壞在連接鹼基（base residues）與核糖（ribose）的化學鍵。這個化學鍵稱為：","options":["(A) 氫鍵（hydrogen bond）","(B) 糖苷鍵（N-β-glycosyl bond）","(C) 磷酸二酯鍵（phosphodiester bond）","(D) 醯胺鍵（amide bond）"],"answer":1,"image":""},{"id":"md2-105-1-32","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第1次第32題","year":105,"session":1,"number":32,"question":"艾姆氏測試法（Ames test）可用於評估：","options":["(A) 細菌之致病性","(B) DNA複製的速率","(C) 抗生素的藥效","(D) 化合物致突變性的能力"],"answer":3,"image":""},{"id":"md2-105-1-33","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第1次第33題","year":105,"session":1,"number":33,"question":"下列對Okazaki片段的敘述，何者正確？","options":["(A) 由於內切酶（endonuclease）作用後所產生的DNA片段","(B) 存在於30S核糖體次單元（ribosomal subunit）中的RNA片段","(C) 是DNA複製時發生在合成lagging strand的中間產物","(D) 意指由3'→ 5'合成的DNA片段"],"answer":2,"image":""},{"id":"md2-105-1-34","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第1次第34題","year":105,"session":1,"number":34,"question":"關於mRNA穩定性的描述，下列何者正確？","options":["(A) mRNA降解的程序主要是從5'到3'的方向","(B) 一般而言，細菌mRNA的半衰期較真核細胞mRNA長","(C) 一般而言，mRNA降解的速率最少10倍於其合成的速率","(D) 在真核細胞中，mRNA的5'cap和3'poly(A) tail可增加其穩定性"],"answer":3,"image":""},{"id":"md2-105-1-35","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第1次第35題","year":105,"session":1,"number":35,"question":"下列何種突變會使轉譯（translation）過程中蛋白質的合成提前結束？","options":["(A) silent mutation","(B) missense mutation","(C) suppressor mutation","(D) nonsense mutation"],"answer":3,"image":""},{"id":"md2-105-1-36","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第1次第36題","year":105,"session":1,"number":36,"question":"胺醯-tRNA合成酶（aminoacyl-tRNA synthetases）是一種活化胺基酸的酵素，其特徵為何？","options":["(A) 能辨認特定的tRNA及胺基酸，促進胺醯-tRNA的合成","(B) 需要會同其他酵素將胺基酸結合到特定的tRNA上","(C) 需要以GTP活化胺基酸後，始能進行胺醯-tRNA的合成","(D) 可以將胺基酸直接與tRNA 3'-端結合而形成胺醯-tRNA"],"answer":0,"image":""},{"id":"md2-105-1-37","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"105年第1次第37題","year":105,"session":1,"number":37,"question":"下列那一種蛋白質具有抑制細胞凋亡（apoptosis）之功能？","options":["(A) Bak","(B) Bax","(C) Bcl-2","(D) FASL"],"answer":2,"image":""},{"id":"md2-105-1-38","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第1次第38題","year":105,"session":1,"number":38,"question":"下列關於紅血球醣代謝之敘述，何者正確？","options":["(A) 由糖解作用（glycolysis）產生的ATP是紅血球主要的能量來源","(B) 紅血球中糖解作用（glycolysis）除用於產生能量外並無其他功能","(C) 克氏循環（TCA cycle）會消耗少部分紅血球所攜帶的氧氣","(D) 紅血球中五碳糖磷酸途徑（pentose phosphate pathway）係在粒線體中進行"],"answer":0,"image":""},{"id":"md2-105-1-39","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第1次第39題","year":105,"session":1,"number":39,"question":"用餐後血糖進入肝細胞及骨骼肌細胞轉換成肝糖（glycogen），葡萄糖以下列何種型式直接參與肝糖合成？","options":["(A) glucose 1-phosphate","(B) glucose 6-phosphate","(C) CMP-glucose","(D) UDP-glucose"],"answer":[0,1,3],"image":"","answer_note":"更正:第39題答Ａ、Ｂ、Ｄ給分"},{"id":"md2-105-1-40","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第1次第40題","year":105,"session":1,"number":40,"question":"百米選手在激烈運動下，骨骼肌內之糖解作用（glycolysis）所產生的NADH，最主要經由下列何種反應再氧化生成NAD+？","options":["(A) α-ketoglutarate反應成為succinyl-CoA","(B) pyruvate反應成為lactate","(C) coenzyme Q反應成為cytochrome b","(D) pyruvate反應成為acetyl-CoA"],"answer":1,"image":""},{"id":"md2-105-1-41","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第1次第41題","year":105,"session":1,"number":41,"question":"在胰臟β細胞中，下列那個酵素所催化的反應速率會隨血糖上升而明顯提高，且其下游產物能促進胰島素（insulin）的分泌？","options":["(A) glycogen synthase","(B) glucokinase（或稱hexokinase IV）","(C) phosphorylase kinase","(D) glycogen phosphorylase"],"answer":1,"image":""},{"id":"md2-105-1-42","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第1次第42題","year":105,"session":1,"number":42,"question":"下列何者與促進細胞攝取血液中膽固醇有關？","options":["(A) Apo B-100","(B) Apo C-I","(C) Apo C-II","(D) lipoprotein lipase"],"answer":0,"image":""},{"id":"md2-105-1-43","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第1次第43題","year":105,"session":1,"number":43,"question":"下列何者不屬於穿膜蛋白-細菌視紫蛋白（bacteriorhodopsin）的特性？","options":["(A) 它是利用7個α-螺旋結構形成的通道穿過細胞膜","(B) 它是利用單一的β-螺旋結構穿過細胞膜","(C) 它是藉由穿膜結構與retinal分子結合","(D) 它具有光驅動質子運輸（light-driven proton transport）的功能"],"answer":1,"image":""},{"id":"md2-105-1-44","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第1次第44題","year":105,"session":1,"number":44,"question":"一種體染色體顯性（autosomal dominant）遺傳疾病稱為familial hyper-cholesterolemia乃是因為low density lipoprotein（LDL）receptor突變所致。下列有關LDL的敘述，何者正確？","options":["(A) LDL receptor只存在肝細胞上","(B) LDL中的膽固醇經由LDL receptor之作用，可提供肝細胞合成bile salts","(C) LDL所含的脂肪以triglyceride為主","(D) LDL是直接由肝臟製造分泌"],"answer":1,"image":""},{"id":"md2-105-1-45","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第1次第45題","year":105,"session":1,"number":45,"question":"體內苯丙胺酸羥化酶（phenylalanine hydroxylase）活性的缺失會導致苯丙酮酸尿症（phenylketonuria），此疾病患者會出現下列何種症狀？","options":["(A) 患者無法自行合成足夠的酪胺酸（tyrosine）","(B) 患者尿液中會出現大量的色胺酸（tryptophan）","(C) 患者會對苯丙胺酸（phenylalanine）過敏","(D) 患者腸道無法吸收足夠的苯丙胺酸（phenylalanine）"],"answer":0,"image":""},{"id":"md2-105-1-46","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第1次第46題","year":105,"session":1,"number":46,"question":"下列那一種胺基酸是腎上腺素（epinephrine）和正腎上腺素（norepinephrine）生合成的前驅物？","options":["(A) arginine","(B) histidine","(C) tyrosine","(D) tryptophan"],"answer":2,"image":""},{"id":"md2-105-1-47","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第1次第47題","year":105,"session":1,"number":47,"question":"下列何者屬於脂溶性的電子傳遞者？","options":["(A) cytochrome c","(B) NADH","(C) FADH2","(D) coenzyme Q"],"answer":[0,3],"image":"","answer_note":"更正:第47題答Ａ、Ｄ給分"},{"id":"md2-105-1-48","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第1次第48題","year":105,"session":1,"number":48,"question":"原始致癌基因（proto-oncogenes）能夠透過下列機制轉變為致癌基因（oncogenes），何者除外？","options":["(A) 化學性誘導突變（chemical-induced mutation）","(B) 染色體重組","(C) 病毒感染","(D) 其啟動區（promoter region）發生突變導致該蛋白質合成量下降"],"answer":3,"image":""},{"id":"md2-105-1-49","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第1次第49題","year":105,"session":1,"number":49,"question":"有關胰島素（insulin）基因所合成的前激素原（preprohormone）之敘述，下列何者錯誤？","options":["(A) 胰島素的前激素原必須在內質網（endoplasmic reticulum）合成","(B) 胰島素之A鏈或B鏈分別由兩個基因轉錄轉譯而來","(C) 胰島素由多胜肽前驅物經蛋白裂解（proteolytic cleavage）產生","(D) 合成後進入分泌顆粒"],"answer":1,"image":""},{"id":"md2-105-1-50","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第1次第50題","year":105,"session":1,"number":50,"question":"下列那一種分析方法可用於研究蛋白質之交互作用？","options":["(A) DNA microarray analysis","(B) Northern blotting","(C) Southern blotting","(D) Two-hybrid analysis"],"answer":3,"image":""},{"id":"md2-105-1-51","subject":"md2","topic":"藥理-總論與自主神經","meta":"105年第1次第51題","year":105,"session":1,"number":51,"question":"下列何者不是Phase I的代謝反應？","options":["(A) Oxidation","(B) Hydrolysis","(C) Conjugation","(D) Reduction"],"answer":2,"image":""},{"id":"md2-105-1-52","subject":"md2","topic":"藥理-總論與自主神經","meta":"105年第1次第52題","year":105,"session":1,"number":52,"question":"下列何種藥物在肝臟的快速代謝，何者與肝血流量（blood flow-limited）無關？","options":["(A) Alprenolol","(B) Lidocaine","(C) Isoniazid","(D) Aspirin"],"answer":3,"image":""},{"id":"md2-105-1-53","subject":"md2","topic":"藥理-化學治療","meta":"105年第1次第53題","year":105,"session":1,"number":53,"question":"關於抗黴菌用藥ketoconazole與fluconazole之比較，下列敘述何者錯誤？","options":["(A) Ketoconazole會抑制人類cortisol之生成，fluconazole則較不會","(B) Ketoconazole可治療由黴菌引起的腦膜炎，fluconazole則無法治療中樞性黴菌感染","(C) Ketoconazole主要由肝臟代謝而失去藥效，fluconazole則由腎臟排出","(D) Ketoconazole會抑制人類肝臟cytochrome P450之活性，fluconazole則較不會"],"answer":1,"image":""},{"id":"md2-105-1-54","subject":"md2","topic":"藥理-化學治療","meta":"105年第1次第54題","year":105,"session":1,"number":54,"question":"林小妹罹患血癌，因長時間以傳統癌症治療藥物治療後，免疫力降低，為避免口腔內念珠菌之伺機性感染，常用下列何種藥物來預防？","options":["(A) Griseofulvin","(B) Miconazole","(C) Terbinafine","(D) Nystatin"],"answer":3,"image":""},{"id":"md2-105-1-55","subject":"md2","topic":"藥理-化學治療","meta":"105年第1次第55題","year":105,"session":1,"number":55,"question":"下列何種藥物與病毒包膜蛋白結合，使得病毒與宿主細胞膜無法融合？","options":["(A) Ribavirin","(B) Adefovir","(C) Enfuvirtide","(D) Abacavir"],"answer":2,"image":""},{"id":"md2-105-1-56","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"105年第1次第56題","year":105,"session":1,"number":56,"question":"Clopidogrel之拮抗血小板凝集作用經由何種機制？","options":["(A) 提升血小板胞內之c-AMP","(B) ADP receptor之拮抗","(C) Fibrinogen receptor（即醣蛋白IIb/IIIa）之拮抗","(D) Thromboxane receptor之拮抗"],"answer":1,"image":""},{"id":"md2-105-1-57","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"105年第1次第57題","year":105,"session":1,"number":57,"question":"下列何種藥物不屬於Fibrinolysis之拮抗劑？","options":["(A) Hirudin","(B) Aminocaproic acid","(C) Tranexamic acid","(D) Aprotinin"],"answer":0,"image":""},{"id":"md2-105-1-58","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第1次第58題","year":105,"session":1,"number":58,"question":"下列有關tamoxifen的藥理學作用描述，何者錯誤？","options":["(A) 為一種為非類固醇的抗雌激素，藉由與雌激素受體結合，進而抑制內生性雌激素作用","(B) 廣泛地被使用來治療乳癌患者","(C) 使用可導致停經後婦女之血中總膽固醇及低密度脂蛋白濃度升高","(D) 具有降低停經後婦女腰椎骨密度降低的風險"],"answer":2,"image":""},{"id":"md2-105-1-59","subject":"md2","topic":"生理-內分泌代謝","meta":"105年第1次第59題","year":105,"session":1,"number":59,"question":"5歲男童因嚴重腦部創傷後一年就診，小兒科醫師發現其嚴重地發育遲緩，並且生化檢測發現其明顯的生長激素（growth hormone）分泌不足，因此投予生長激素治療。在治療階段中發現其血中生長激素濃度已達正常，但生長遲緩情形未見改善，下列何者解釋可能可以用來說明生長激素替代治療無效的原因？","options":["(A) 其可能體制素（somatostatin）分泌過量","(B) 其可能生長激素受體的表現量不足","(C) 其可能發生繼發性甲狀腺機能減退（secondary hypothyroidism）","(D) 其可能生長激素在體內的代謝速率過快"],"answer":2,"image":""},{"id":"md2-105-1-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第1次第60題","year":105,"session":1,"number":60,"question":"下列有關治療甲狀腺功能低下症（hypothyroidism）藥物levothyroxine的藥理作用描述，何者錯誤？","options":["(A) Levothyroxine不能同時與鈣和含鋁類的制酸劑合併使用","(B) Levothyroxine對於藥物如amiodarone所引起的甲狀腺功能低下症治療效果不佳","(C) Levothyroxine可以使用於懷孕的甲狀腺功能低下症婦女","(D) 黏液性水腫昏迷（myxedema coma）可以利用levothyroxine來治療"],"answer":1,"image":""},{"id":"md2-105-1-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第1次第61題","year":105,"session":1,"number":61,"question":"格雷夫斯病（Graves' disease）可以選擇下列何種藥物來治療？","options":["(A) Levothyroxine","(B) Methimazole","(C) Propranolol","(D) Octreotide"],"answer":[1,2],"image":"","answer_note":"更正:第61題答Ｂ、Ｃ給分。"},{"id":"md2-105-1-62","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第1次第62題","year":105,"session":1,"number":62,"question":"下列何種藥物可以用來治療垂體性尿崩症（pituitary diabetes insipidus）？","options":["(A) Atosiban","(B) Desmopressin","(C) Conivaptan","(D) Oxytocin"],"answer":1,"image":""},{"id":"md2-105-1-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"105年第1次第63題","year":105,"session":1,"number":63,"question":"下列那一樣藥物會抑制Carbonic anhydrase而減少眼房液之形成？","options":["(A) Amiloride","(B) Dorzolamide","(C) Torsemide","(D) Bumetanide"],"answer":1,"image":""},{"id":"md2-105-1-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"105年第1次第64題","year":105,"session":1,"number":64,"question":"下列何者可藉由抑制磷酸雙酯酶（phosphodiesterase），而增加細胞內cGMP濃度，致使平滑肌舒張？","options":["(A) Misoprostol","(B) Nitroglycerine","(C) Sildenafil","(D) Theophylline"],"answer":2,"image":""},{"id":"md2-105-1-65","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"105年第1次第65題","year":105,"session":1,"number":65,"question":"下列藥物中何者可以降低腎素（renin）的活性，進而減少angiotensin II之生成？","options":["(A) Aliskiren","(B) Hydrochlorothiazide","(C) Losartan","(D) Ramipril"],"answer":0,"image":""},{"id":"md2-105-1-66","subject":"md2","topic":"藥理-總論與自主神經","meta":"105年第1次第66題","year":105,"session":1,"number":66,"question":"下列何種受體在交感神經末梢被活化後，會促進正腎上腺素的釋放？","options":["(A) α2","(B) β2","(C) Dopamine D2","(D) Muscarinic M2"],"answer":1,"image":""},{"id":"md2-105-1-67","subject":"md2","topic":"藥理-總論與自主神經","meta":"105年第1次第67題","year":105,"session":1,"number":67,"question":"下列何種藥物，最適合用於治療手術後尿滯留？","options":["(A) Atropine","(B) Bethanechol","(C) Pilocarpine","(D) Rivastigmine"],"answer":1,"image":""},{"id":"md2-105-1-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第1次第68題","year":105,"session":1,"number":68,"question":"下列何種藥物最不適合用於預防「運動引起的氣管痙攣（EIB）」？","options":["(A) Cromolyn","(B) Terbutaline","(C) Salmeterol","(D) Theophylline"],"answer":3,"image":""},{"id":"md2-105-1-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第1次第69題","year":105,"session":1,"number":69,"question":"下列何種藥物具有抑制xanthine oxidase，用於治療慢性痛風？","options":["(A) Febuxostat","(B) Probenecid","(C) Sulfinpyrazone","(D) Colchicine"],"answer":0,"image":""},{"id":"md2-105-1-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第1次第70題","year":105,"session":1,"number":70,"question":"下列何種藥物可作為墮胎藥？","options":["(A) Alprostadil","(B) Dinoprostone","(C) Epoprostenol","(D) Iloprost"],"answer":1,"image":""},{"id":"md2-105-1-71","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"105年第1次第71題","year":105,"session":1,"number":71,"question":"Carbidopa與Levodopa合併用藥的原因為何？","options":["(A) 抑制周邊Dopa decarboxylase","(B) 增加3-O-Methyldopa的量","(C) 增加Tyrosine hydroxylase的活性","(D) 抑制周邊COMT的活性"],"answer":0,"image":""},{"id":"md2-105-1-72","subject":"md2","topic":"藥理-總論與自主神經","meta":"105年第1次第72題","year":105,"session":1,"number":72,"question":"下列有關酒精藥理作用之描述，何者錯誤？","options":["(A) 酒精可以經由胃腸道完全吸收","(B) 經由靜脈注射的方式投與相同劑量的酒精時，女性血漿中的酒精濃度較男性高","(C) 酒精的代謝作用為零級反應（zero-order kinetics）","(D) Acetaldehyde為酒精代謝的初級產物"],"answer":1,"image":""},{"id":"md2-105-1-73","subject":"md2","topic":"藥理-化學治療","meta":"105年第1次第73題","year":105,"session":1,"number":73,"question":"下列何種藥物是屬於三價砷（arsenic），可用於治療advanced African trypanosomiasis？","options":["(A) Dimercaprol","(B) Succimer","(C) Melarsoprol","(D) Ferroxamine"],"answer":2,"image":""},{"id":"md2-105-1-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"105年第1次第74題","year":105,"session":1,"number":74,"question":"有一位6歲小女孩在上課時經常發生目光呆滯、凝視等現象，經神經科醫師以腦波檢查發現其腦波中會反覆性的出現spike-wave的波形。初步確認其為一種癲癇症兆，應選用下列何種藥物治療最適宜？","options":["(A) Carbamazepine","(B) Valproic acid","(C) Phenytoin","(D) Diazepam"],"answer":1,"image":""},{"id":"md2-105-1-75","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"105年第1次第75題","year":105,"session":1,"number":75,"question":"承上題，投予下列那一種抗癲癇藥物於此病童時，反而會增加其癲癇發作？","options":["(A) Valproic acid","(B) Lamotrigine","(C) Phenytoin","(D) Ethosuximide"],"answer":2,"image":""},{"id":"md2-105-1-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"105年第1次第76題","year":105,"session":1,"number":76,"question":"下列何種細胞不屬於永久性組織（nondividing or permanent tissues）?","options":["(A) 神經元（neurons）","(B) 骨骼肌細胞（skeletal muscle cells）","(C) 平滑肌細胞（smooth muscle cells）","(D) 心肌細胞（cardiac muscle cells）"],"answer":2,"image":""},{"id":"md2-105-1-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"105年第1次第77題","year":105,"session":1,"number":77,"question":"下列有關炎症反應與介質（mediator）的配對，何者錯誤？","options":["(A) 血管擴張（vasodilation）與TNF, IL-1","(B) 增加血管滲透性與C3a及C5a","(C) 發燒（fever）與前列腺素（prostaglandins）","(D) 疼痛（pain）與遲緩激肽（bradykinin）"],"answer":0,"image":""},{"id":"md2-105-1-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"105年第1次第78題","year":105,"session":1,"number":78,"question":"下列何者是第一期與第二期梅毒病灶中最主要的發炎反應細胞？","options":["(A) 淋巴球（lymphocyte）","(B) 嗜中性白血球（neutrophil）","(C) 漿細胞（plasma cell）","(D) 嗜酸性白血球（eosinophil）"],"answer":2,"image":""},{"id":"md2-105-1-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"105年第1次第79題","year":105,"session":1,"number":79,"question":"下列器官中，最少受到腮腺炎病毒侵襲，所以無顯病理變化的是：","options":["(A) 肝臟","(B) 中樞神經系統","(C) 睪丸","(D) 胰臟"],"answer":0,"image":""},{"id":"md2-105-1-80","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"105年第1次第80題","year":105,"session":1,"number":80,"question":"流行病學研究發現，移民美國第一代的日本人死於胃癌的比率小於原日本住民，但高於當地美國人；移民美國第二代的日本人死於胃癌的比率小於移民美國第一代的日本人，但仍高於當地美國人。由這研究結果所得到的推論，何者為最適當？","options":["(A) 癌症的發生僅與環境有關","(B) 癌症的發生僅與基因遺傳有關","(C) 環境與基因遺傳均可影響癌症的發生","(D) 年齡是影響癌症發生的因素"],"answer":2,"image":""},{"id":"md2-105-1-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"105年第1次第81題","year":105,"session":1,"number":81,"question":"下列何種致癌物最容易引起白血病及惡性淋巴瘤？","options":["(A) Asbestos","(B) Cadmium compounds","(C) Vinyl chloride","(D) Benzene"],"answer":3,"image":""},{"id":"md2-105-1-82","subject":"md2","topic":"病理-呼吸消化","meta":"105年第1次第82題","year":105,"session":1,"number":82,"question":"有關肺心症（cor pulmonale）的敘述，下列何者錯誤？","options":["(A) 在急性肺心症，右心室明顯肥厚","(B) 在急性肺心症，右心室擴張且呈卵圓形","(C) 在慢性肺心症，右心室壁增厚","(D) 在慢性肺心症，右心室壁的脂肪消失"],"answer":0,"image":""},{"id":"md2-105-1-83","subject":"md2","topic":"病理-心血管血液","meta":"105年第1次第83題","year":105,"session":1,"number":83,"question":"45歲男性胰臟腺癌末期患者，數度發生下肢短暫性靜脈血栓（evanescent phlebothrombosis），病人如同時發生腦梗塞，其最可能的心臟併發症為何？","options":["(A) 非細菌性血栓性心內膜炎（non-bacterial thrombotic endocarditis）","(B) Libman-Sacks氏心內膜炎（Libman-Sacks endocarditis）","(C) 急性感染性心內膜炎（acute infective endocarditis）","(D) 急性心肌梗塞（acute myocardial infarction）"],"answer":0,"image":""},{"id":"md2-105-1-84","subject":"md2","topic":"病理-心血管血液","meta":"105年第1次第84題","year":105,"session":1,"number":84,"question":"下列四種血液疾病中，那兩種疾病最常發生變異的基因相同？ ①增多性紅血球症（polycythemia vera） ②原發性血小板增多症（essential thrombocythemia） ③全身性肥大細胞增生症（systemic mastocytosis） ④急性淋巴性白血病（acute lymphoblastic leukemia）","options":["(A) ①②","(B) ①③","(C) ②③","(D) ③④"],"answer":0,"image":""},{"id":"md2-105-1-85","subject":"md2","topic":"病理-心血管血液","meta":"105年第1次第85題","year":105,"session":1,"number":85,"question":"5歲女童兩周來出現面色蒼白、精神不佳。血液中出現terminal deoxynucleotidyl transferase（TdT）、CD10、CD19染色陽性的原始細胞（blast cells）。染色體檢查發現腫瘤細胞有t（12;21）的染色體轉位。下列何者為最可能的診斷？","options":["(A) T細胞慢性淋巴母細胞白血病（T-cell chronic lymphoblastic leukemia）","(B) T細胞急性淋巴母細胞白血病（T-cell acute lymphoblastic leukemia）","(C) B細胞急性淋巴母細胞白血病（B-cell acute lymphoblastic leukemia）","(D) B細胞慢性淋巴母細胞白血病（B-cell chronic lymphoblastic leukemia）"],"answer":2,"image":""},{"id":"md2-105-1-86","subject":"md2","topic":"病理-呼吸消化","meta":"105年第1次第86題","year":105,"session":1,"number":86,"question":"下列何者為移植肺發生慢性排斥之最主要的病理變化？","options":["(A) 發炎細胞浸潤","(B) 瀰漫性肺泡傷害","(C) 阻塞性支氣管炎","(D) 巨細胞病毒感染"],"answer":2,"image":""},{"id":"md2-105-1-87","subject":"md2","topic":"病理-呼吸消化","meta":"105年第1次第87題","year":105,"session":1,"number":87,"question":"急性間質性肺炎與下列那一項較無關？","options":["(A) 吸入毒氣","(B) 過敏性反應","(C) 病毒性感染","(D) 吸入胃部內含異物"],"answer":3,"image":""},{"id":"md2-105-1-88","subject":"md2","topic":"病理-呼吸消化","meta":"105年第1次第88題","year":105,"session":1,"number":88,"question":"下列何種藥物造成的肝傷害以肝細胞壞死為主？","options":["(A) amiodarone","(B) acetaminophen","(C) phenothiazine","(D) methotrexate"],"answer":1,"image":""},{"id":"md2-105-1-89","subject":"md2","topic":"病理-呼吸消化","meta":"105年第1次第89題","year":105,"session":1,"number":89,"question":"24歲男性主訴過去一個星期腹痛、發燒及拉肚子，身體檢查發現右下腹有壓痛的情形，糞便檢查並有潛血反應。內視鏡下看見廻腸及升結腸的黏膜較為水腫，且有潰瘍的現象；但橫結腸及降結腸則為正常。他的升結腸切片檢查最有可能看到下列何種病理表現？","options":["(A) 隱窩膿瘍（crypt abscess）","(B) 腺癌（adenocarcinoma）","(C) 壞死性血管炎（necrotizing vasculitis）","(D) 非乾酪性肉芽腫（non-caseating granulomas）"],"answer":3,"image":""},{"id":"md2-105-1-90","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"105年第1次第90題","year":105,"session":1,"number":90,"question":"4週大的女嬰全身皮膚變黃，大便顏色由黃棕色逐漸變成淡黃色甚至灰白色。身體檢查發現女嬰有肝腫大的情形，肝臟切片檢查發現膽小管（bile ductule）增生，門脈區水腫及纖維化，肝細胞有明顯膽汁鬱積（cholestasis）。以下何者為最有可能的診斷？","options":["(A) 總膽管囊腫（choledochal cyst）","(B) 膽管炎（cholangitis）","(C) 膽道閉鎖（biliary atresia）","(D) 膽管癌（cholangiocarcinoma）"],"answer":2,"image":""},{"id":"md2-105-1-91","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"105年第1次第91題","year":105,"session":1,"number":91,"question":"下列何種疾病主要是因大腸桿菌產生之類志賀氏毒素（Shiga-like toxin）所導致？","options":["(A) 血栓性血小板減少性紫斑症（thrombotic thrombocytopenic purpura）","(B) 特發性血小板減少性紫斑症（idiopathic thrombocytopenic purpura）","(C) 典型溶血性尿毒症候群（typical hemolytic-uremic syndrome）","(D) 非典型溶血性尿毒症候群（atypical hemolytic-uremic syndrome）"],"answer":2,"image":""},{"id":"md2-105-1-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"105年第1次第92題","year":105,"session":1,"number":92,"question":"下列那一個基因的突變與甲狀腺髓質癌（medullary carcinoma）的形成最有關係？","options":["(A) RAS","(B) RET","(C) BRAF","(D) PTEN"],"answer":1,"image":""},{"id":"md2-105-1-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"105年第1次第93題","year":105,"session":1,"number":93,"question":"下列分子缺陷中，何者最常與偶發性（sporadic）副甲狀腺腺瘤有關？","options":["(A) cyclin D1","(B) calcium-sensing receptor","(C) vitamin D receptor","(D) parathyroid hormone"],"answer":0,"image":""},{"id":"md2-105-1-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"105年第1次第94題","year":105,"session":1,"number":94,"question":"生過3個小孩的26歲婦女在懷孕28週時發生自發性流產，其流產生出的男嬰比一般正常週數的胎兒要小，而且兩手的第三指和第四指有連在一起的畸形。胎盤除了比較小之外，還可以看到一些大小約0.8公分像葡萄狀的水泡。則這些胎盤組織最可能有下列那種染色體異常？","options":["(A) 69,XXY","(B) 46,XX","(C) 23,Y","(D) 47,XXY"],"answer":0,"image":""},{"id":"md2-105-1-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"105年第1次第95題","year":105,"session":1,"number":95,"question":"40歲男性發現在龜頭上數個亮紅色表面光滑的斑塊，病理診斷為”Erythroplasia of Queyrat”，則應如何向病人解釋此疾病？","options":["(A) 淋病，須以抗生素治療","(B) 尖頭濕疣（condyloma acuminatum）","(C) 原位癌，出現異生細胞","(D) 梅毒，須以抗生素治療"],"answer":2,"image":""},{"id":"md2-105-1-96","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"105年第1次第96題","year":105,"session":1,"number":96,"question":"有關軟骨肉瘤（chondrosarcoma）的敘述，下列何者正確？","options":["(A) 大多數病人的年齡為20幾歲","(B) 腫瘤內少有鈣化","(C) 第一級（grade 1）腫瘤的轉移機率約10%","(D) 見到第三級（grade 3）惡性軟骨之形態時，要先想到該腫瘤是否為軟骨母細胞骨肉瘤（chondroblastic osteosarcoma），因第三級軟骨肉瘤較少見"],"answer":3,"image":""},{"id":"md2-105-1-97","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"105年第1次第97題","year":105,"session":1,"number":97,"question":"一名小孩因感冒而服用阿斯匹林（aspirin），隨後發生了肝及腦的病變。肝臟變化如圖所示，他的腦部病變最有可能是：","options":["(A) 核黃疸（kernicterus）","(B) 點狀出血（petechial hemorrhage）","(C) 腦水腫（brain edema）","(D) 豆狀核變性（lenticular degeneration）"],"answer":2,"image":"md2-105-1-97.jpeg"},{"id":"md2-105-1-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"105年第1次第98題","year":105,"session":1,"number":98,"question":"病人因腦膿瘍顱內壓上升而發生經天幕腦脫疝（transtentorial herniation）時，會壓迫到那一條血管而造成局部缺血？","options":["(A) 前大腦動脈","(B) 中大腦動脈","(C) 後大腦動脈","(D) 基底動脈"],"answer":2,"image":""},{"id":"md2-105-1-99","subject":"md2","topic":"病理-呼吸消化","meta":"105年第1次第99題","year":105,"session":1,"number":99,"question":"有一農夫經常在稻穀收割期時發生急性發燒、咳嗽、呼吸困難，且血中白血球增高，其最可能的診斷為：","options":["(A) 支氣管肺炎","(B) 結核性肺炎","(C) 過敏性肺炎","(D) 成人呼吸窘迫症候群"],"answer":2,"image":""},{"id":"md2-105-1-100","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"105年第1次第100題","year":105,"session":1,"number":100,"question":"承上題，經由病理切片診斷，下列現象最可能發生？","options":["(A) 間質纖維化，淋巴球，漿細胞浸潤","(B) 間質纖維化，嗜酸性球浸潤","(C) 乾酪性壞死及肉芽腫","(D) 嗜中性白血球浸潤及化膿"],"answer":0,"image":""},{"id":"md2-105-2-1","subject":"md2","topic":"生理-血液","meta":"105年第2次第1題","year":105,"session":2,"number":1,"question":"氯-碳酸氫根交換器（Cl--HCO- exchanger）不參與下列何種生理現象？3","options":["(A) 二氧化碳在血中之運輸","(B) 胃酸分泌","(C) 細胞體積之調節","(D) 細胞膜電位（membrane potential）之調節"],"answer":3,"image":""},{"id":"md2-105-2-2","subject":"md2","topic":"生化-訊息傳遞荷爾蒙細胞週期","meta":"105年第2次第2題","year":105,"session":2,"number":2,"question":"下列有關一氧化氮（nitric oxide）之敘述，何者正確？","options":["(A) 是化學性傳遞物質（chemical messenger）可活化adenylate cyclase","(B) 由L-arginine與氧分子作用形成","(C) 可導致血管壁收縮（constriction of blood vessels）","(D) 是極安定之氣體分子"],"answer":1,"image":""},{"id":"md2-105-2-3","subject":"md2","topic":"生理-細胞神經肌肉","meta":"105年第2次第3題","year":105,"session":2,"number":3,"question":"感冒高燒不退，主要是因為下列那一腦區的活性被發炎物質干擾所致？","options":["(A) preoptic nucleus","(B) suprachiasmatic nucleus","(C) arcuate nucleus","(D) supraoptic nucleus"],"answer":0,"image":""},{"id":"md2-105-2-4","subject":"md2","topic":"生理-細胞神經肌肉","meta":"105年第2次第4題","year":105,"session":2,"number":4,"question":"下列何者是掌控與維持姿勢相關的中軸肌肉（axial muscles）收縮的最主要運動路徑？","options":["(A) 側皮質脊髓路徑（lateral corticospinal tract）","(B) 腹皮質脊髓路徑（ventral corticospinal tract）","(C) 網狀脊髓路徑（reticulospinal tract）","(D) 紅核脊髓路徑（rubrospinal tract）"],"answer":[1,2],"image":"","answer_note":"更正:第4題答Ｂ、Ｃ給分"},{"id":"md2-105-2-5","subject":"md2","topic":"生理-細胞神經肌肉","meta":"105年第2次第5題","year":105,"session":2,"number":5,"question":"下列何者並沒有參與瞳孔的光反射作用（light reflex）？","options":["(A) iris","(B) parasympathetic nerve","(C) medial geniculate body","(D) ciliary ganglion"],"answer":2,"image":""},{"id":"md2-105-2-6","subject":"md2","topic":"生理-細胞神經肌肉","meta":"105年第2次第6題","year":105,"session":2,"number":6,"question":"Unmyelinated C fibers主要與下列何種感覺有關？","options":["(A) pressure","(B) smell","(C) touch","(D) temperature"],"answer":[0,2,3],"image":"","answer_note":"更正:第6題答Ａ、Ｃ、Ｄ給分"},{"id":"md2-105-2-7","subject":"md2","topic":"生理-消化","meta":"105年第2次第7題","year":105,"session":2,"number":7,"question":"下列有關平滑肌之敘述，何者錯誤？","options":["(A) 具有終生分裂之能力","(B) thin actin-containing filament參與收縮功能","(C) 藉由sliding filament mechanism參與收縮功能","(D) dense body存在於細胞核中"],"answer":3,"image":""},{"id":"md2-105-2-8","subject":"md2","topic":"生理-血液","meta":"105年第2次第8題","year":105,"session":2,"number":8,"question":"在blood coagulation pathway的最後一步，促使fibrinogen轉化成fibrin的物質為何？","options":["(A) von Willebrand factor","(B) factor V","(C) thrombin","(D) plasminogen"],"answer":2,"image":""},{"id":"md2-105-2-9","subject":"md2","topic":"生理-心臟血管","meta":"105年第2次第9題","year":105,"session":2,"number":9,"question":"車禍大量失血時，於事發後的一小時，體內會藉由那些機制來維持血壓之恆定？①感壓反射（baroreflex） ②腎臟－血液容積壓力之調控（renal-blood volume pressure control） ③腎素－血管張力素－血管收縮作用（renin-angiotensin- vasoconstriction） ④體液回收至微血管（capillary fluid shift）","options":["(A) ①②④","(B) ①②③","(C) ①③④","(D) ②③④"],"answer":2,"image":""},{"id":"md2-105-2-10","subject":"md2","topic":"生理-心臟血管","meta":"105年第2次第10題","year":105,"session":2,"number":10,"question":"下列那些因素可導致腹腔靜脈壓（venous pressure）之增加？①靜脈的順應性（venous compliance）增加 ②投射至靜脈的交感神經活性（sympathetic activity）增加 ③吸氣活動（inspiration movements） ④全身血量（blood volume）增加","options":["(A) ①②③","(B) ①②④","(C) ②③④","(D) ①③④"],"answer":2,"image":""},{"id":"md2-105-2-11","subject":"md2","topic":"生理-心臟血管","meta":"105年第2次第11題","year":105,"session":2,"number":11,"question":"下列何者可解釋持續性心衰竭（persisting heart failure）的病人引起腿部或足部水腫的主要原因？","options":["(A) 靜脈壓增加","(B) 血漿蛋白濃度增加","(C) 淋巴流量增加","(D) 微血管通透性降低"],"answer":0,"image":""},{"id":"md2-105-2-12","subject":"md2","topic":"生理-血液","meta":"105年第2次第12題","year":105,"session":2,"number":12,"question":"下列何者可以增加氧氣和血紅素的結合量？①增加氧氣分壓（oxygen partial pressure） ②降低pH值 ③增加二氧化碳分壓 ④增加二磷酸甘油（2,3-diphosphoglycerate; 2,3-DPG）濃度","options":["(A) 僅①","(B) 僅②③","(C) 僅①④","(D) ②③④"],"answer":0,"image":""},{"id":"md2-105-2-13","subject":"md2","topic":"生理-血液","meta":"105年第2次第13題","year":105,"session":2,"number":13,"question":"劇烈運動時，體循環不會發生下列何種現象？","options":["(A) 紅血球內的重碳酸氫根離子（HCO-）進入血漿3","(B) 大部分溶解態的二氧化碳進入紅血球","(C) 碳酸（H2CO3）於紅血球中被合成及解離","(D) 血球內的氯離子進入血漿"],"answer":3,"image":""},{"id":"md2-105-2-14","subject":"md2","topic":"生理-呼吸","meta":"105年第2次第14題","year":105,"session":2,"number":14,"question":"平靜吸氣（quiet inspiration）過程中，不會發生下列何種現象？","options":["(A) 膈神經（phrenic nerve）興奮","(B) 內肋間肌（internal intercostal muscle）收縮","(C) 肋膜內壓（intrapleural pressure, Pip）下降","(D) 肺臟之彈性回復力（elastic recoil）增加"],"answer":1,"image":""},{"id":"md2-105-2-15","subject":"md2","topic":"生理-消化","meta":"105年第2次第15題","year":105,"session":2,"number":15,"question":"下列十二指腸內之何種狀況最容易抑制胃的排空（gastric empty）？","options":["(A) 低張性（hypotonicity）","(B) pH值偏高","(C) 高脂食糜","(D) 低蛋白食糜"],"answer":2,"image":""},{"id":"md2-105-2-16","subject":"md2","topic":"生理-消化","meta":"105年第2次第16題","year":105,"session":2,"number":16,"question":"下列那個情況會造成胃液分泌下降？","options":["(A) intrinsic factor分泌增加","(B) 迷走神經釋放乙醯膽鹼（ACh）","(C) 十二指腸的腸嗜鉻細胞（enterochromaffin cells）釋放血清素（serotonin）","(D) 食物從胃排空到十二指腸"],"answer":[2,3],"image":"","answer_note":"更正:第16題答Ｃ、Ｄ給分"},{"id":"md2-105-2-17","subject":"md2","topic":"生理-腎臟","meta":"105年第2次第17題","year":105,"session":2,"number":17,"question":"中樞神經系統中，偵測體液滲透壓，並參與調節抗利尿激素（anti-diuretic hormone）分泌的滲透壓性受器（osmoreceptor）之分布最接近下列何處？","options":["(A) 視上核（supraoptic nucleus）","(B) 錐體皮質（pyramidal cortex）","(C) 錐體交叉（pyramidal decussation）","(D) 內側蹄狀系統（medial lemniscus system）"],"answer":0,"image":""},{"id":"md2-105-2-18","subject":"md2","topic":"生理-腎臟","meta":"105年第2次第18題","year":105,"session":2,"number":18,"question":"下列何者不是腎臟分泌的？","options":["(A) 紅血球生成素（erythropoietin）","(B) 腎素（renin）","(C) 鈣三醇（calcitriol）","(D) 醛固酮（aldosterone）"],"answer":3,"image":""},{"id":"md2-105-2-19","subject":"md2","topic":"生理-腎臟","meta":"105年第2次第19題","year":105,"session":2,"number":19,"question":"關於集尿管（collecting duct）對於水分再吸收的描述，下列何者錯誤？","options":["(A) 剛進入集尿管的腎小管內液屬低張溶液（hypotonic solution）","(B) 集尿管受到抗利尿激素（antidiuretic hormone）作用而改變其對於水分的通透性與再吸收","(C) 集尿管主要利用第一型水通道（aquaporin-1）增加水分再吸收","(D) 在極需水分的狀況下，高達99.7%的水分可被再吸收回到體循環"],"answer":[0,2,3],"image":"","answer_note":"更正:第19題答Ａ、Ｃ、Ｄ給分"},{"id":"md2-105-2-20","subject":"md2","topic":"生理-內分泌代謝","meta":"105年第2次第20題","year":105,"session":2,"number":20,"question":"下列有關胰島素的描述，何者錯誤？","options":["(A) 腦神經細胞對葡萄糖的吸收需要依賴胰島素","(B) 胰島素敏感性細胞多含有第四型葡萄糖轉運蛋白（GLUT4）","(C) 胰島素可以增加脂肪細胞對葡萄糖的吸收作用","(D) 胰島素可以增加骨骼肌之肝醣合成作用"],"answer":0,"image":""},{"id":"md2-105-2-21","subject":"md2","topic":"生理-內分泌代謝","meta":"105年第2次第21題","year":105,"session":2,"number":21,"question":"下列何者是造成hyperthyroidism病症最常見的可能原因是？","options":["(A) Graves' disease","(B) Hashimoto's disease","(C) 碘攝取不足","(D) 腦部外傷"],"answer":0,"image":""},{"id":"md2-105-2-22","subject":"md2","topic":"生理-細胞神經肌肉","meta":"105年第2次第22題","year":105,"session":2,"number":22,"question":"下列與骨重塑作用（bone remodeling）之相關敘述，何者錯誤？","options":["(A) 是調節細胞外液鈣磷平衡的重要機轉","(B) 噬骨細胞（osteoclast）是從纖維母細胞（fibroblast）分化而來，具多核及吞噬功能","(C) 造骨細胞（osteoblast）會分泌製造第一型膠原蛋白","(D) 骨重塑作用會受到血中副甲狀腺濃度所調控"],"answer":1,"image":""},{"id":"md2-105-2-23","subject":"md2","topic":"生化-訊息傳遞荷爾蒙細胞週期","meta":"105年第2次第23題","year":105,"session":2,"number":23,"question":"下列何者並非由proopiomelanocortin（POMC）代謝所生成？","options":["(A) ACTH","(B) β-lipotropin","(C) α-MSH","(D) CRH"],"answer":3,"image":""},{"id":"md2-105-2-24","subject":"md2","topic":"生理-內分泌代謝","meta":"105年第2次第24題","year":105,"session":2,"number":24,"question":"下列造成庫欣氏症候群（Cushing syndrome）的成因中，何者與促腎上腺皮質激素（ACTH）的過度分泌無關？","options":["(A) 先天性腎上腺增生症（congenital adrenal hyperplasia）","(B) 腦下垂體前葉產生促腎上腺皮質激素分泌腫瘤（ACTH-secreting tumor）","(C) 下視丘促腎上腺皮質激素釋放激素（CRH）分泌過量","(D) 異位性促腎上腺皮質激素分泌過多症（ectopic ACTH syndrome）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第24題一律給分 (原公告答案 A)"},{"id":"md2-105-2-25","subject":"md2","topic":"生理-細胞神經肌肉","meta":"105年第2次第25題","year":105,"session":2,"number":25,"question":"為治療男性陰莖海綿體的勃起（erection）障礙，下列何者為最不可能採取的策略或方法？","options":["(A) 增加nitric oxide（NO）的合成量","(B) 活化guanylyl cyclase的活性","(C) 促進phosphodiesterase的活性","(D) 延長cyclic GMP（cGMP）存在的時間"],"answer":2,"image":""},{"id":"md2-105-2-26","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第2次第26題","year":105,"session":2,"number":26,"question":"當氧分子與血紅素（hemoglobin）結合時，此時血基質（heme）中Fe2+上的兩個開放配位鍵（open coordination bonds）與下列何組物質結合？","options":["(A) 一水分子與一胺基酸的側鏈","(B) 一氧分子與一胺基酸的側鏈","(C) 一氧分子與一水分子","(D) 兩個氧分子"],"answer":1,"image":""},{"id":"md2-105-2-27","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第2次第27題","year":105,"session":2,"number":27,"question":"組胺酸（histidine）有三個酸解離常數（pKa）值，分別為1.82、6.0、9.17。其中那個官能基團的pKa為1.82？","options":["(A) 胺基（-NH+）3","(B) 羧基（-COOH）","(C) 側鏈異吡唑基（side-chain imidazole group）","(D) α碳原子（α carbon）的氫原子"],"answer":1,"image":""},{"id":"md2-105-2-28","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第2次第28題","year":105,"session":2,"number":28,"question":"某酵素的k=500 s-１，K=5 mM，在受質濃度遠高於K的狀況下，此酵素反應的速率常數約為：catmm","options":["(A) 500 s-１","(B) 2,500 mM s-１","(C) 100 mM-１s-１","(D) 0.01 s mM-１"],"answer":0,"image":""},{"id":"md2-105-2-29","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第2次第29題","year":105,"session":2,"number":29,"question":"維生素C（ascorbic acid）缺乏會導致膠原蛋白（collagen）的修飾不全，是因為下列那個反應受到影響？","options":["(A) proline hydroxylation","(B) serine phosphorylation","(C) cysteine oxidation","(D) lysine methylation"],"answer":0,"image":""},{"id":"md2-105-2-30","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第2次第30題","year":105,"session":2,"number":30,"question":"5'-CCAAGTCCATGGACTTGG-3'DNA分子可以形成何種二級結構？","options":["(A) A form","(B) H form","(C) Z form","(D) cruciform"],"answer":3,"image":""},{"id":"md2-105-2-31","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第2次第31題","year":105,"session":2,"number":31,"question":"Lambda噬菌體DNA是藉由何種作用嵌入大腸桿菌的基因體DNA中？","options":["(A) 同源重組（homologous recombination）","(B) 轉位作用（transposition）","(C) 特定點重組（site-specific recombination）","(D) 非同源性末端接合（non-homologous end joining, NHEJ）"],"answer":2,"image":""},{"id":"md2-105-2-32","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第2次第32題","year":105,"session":2,"number":32,"question":"環丁烷嘧啶二聚體（cyclobutane pyrimidine dimer）修復時，下列何者為細菌DNA光解酶（photolyase）的輔助因子（cofactor）？","options":["(A) pyridoxal phosphate","(B) thiamine pyrophosphate","(C) FADH-","(D) coenzyme A"],"answer":2,"image":""},{"id":"md2-105-2-33","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第2次第33題","year":105,"session":2,"number":33,"question":"蛋白質最常經下列何種轉譯後修飾（post-translational modification），再送到溶酶體（lysosome）？","options":["(A) 糖基化（glycosylation）","(B) 磷酸化（phosphorylation）","(C) 蘇素化（sumoylation）","(D) 乙醯化（acetylation）"],"answer":0,"image":""},{"id":"md2-105-2-34","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第2次第34題","year":105,"session":2,"number":34,"question":"位在腫瘤中心的癌細胞，常處於缺氧的環境，這些細胞偏好利用下列那一種醣類代謝途徑獲取ATP？","options":["(A) ß-oxidation","(B) glycolysis","(C) tricarboxylic acid cycle","(D) pentose phosphate pathway"],"answer":1,"image":""},{"id":"md2-105-2-35","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第2次第35題","year":105,"session":2,"number":35,"question":"下列關於操縱子（operon）的敘述，何者錯誤？","options":["(A) 只在真核生物上發現","(B) 包含promoter","(C) 包含operator","(D) 包含structural genes"],"answer":0,"image":""},{"id":"md2-105-2-36","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第2次第36題","year":105,"session":2,"number":36,"question":"下列何者是蛋白質轉譯之起始胺基酸？","options":["(A) leucine","(B) cysteine","(C) methionine","(D) tyrosine"],"answer":2,"image":""},{"id":"md2-105-2-37","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第2次第37題","year":105,"session":2,"number":37,"question":"下列何者是Cori cycle的主要代謝角色？","options":["(A) 將乳酸（lactate）由骨骼肌運送至肝臟","(B) 將乳酸（lactate）由肝臟運送至骨骼肌","(C) 將葡萄糖由骨骼肌運送至肝臟","(D) 將葡萄糖與乳酸（lactate）由肝臟運送至骨骼肌"],"answer":0,"image":""},{"id":"md2-105-2-38","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第2次第38題","year":105,"session":2,"number":38,"question":"下列何種分子不會直接參與克式循環（Krebs cycle，亦稱citric acid cycle或TCA cycle）中的化學反應？","options":["(A) coenzyme A（CoA）","(B) ADP（或GDP）","(C) glutathione","(D) NAD+"],"answer":2,"image":""},{"id":"md2-105-2-39","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第2次第39題","year":105,"session":2,"number":39,"question":"肝糖磷解酶（glycogen phosphorylase）的活性受到phosphorylase kinase及phosphorylase phosphatase的調節，下列何者是其發揮調節作用的主要方式？","options":["(A) 影響酵素蛋白質分解（protein degradation）","(B) 磷酸化-去磷酸化作用（phosphorylation-dephosphorylation）","(C) 異位調節作用（allosteric regulation）","(D) 影響肝醣代謝酵素與調節蛋白質（regulatory protein）的結合作用"],"answer":1,"image":""},{"id":"md2-105-2-40","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第2次第40題","year":105,"session":2,"number":40,"question":"下列何者不屬於膜上蛋白質之脂質錨定（lipid anchor）？","options":["(A) glycosyl phosphatidylinositol anchor","(B) acetyl anchor","(C) myristoyl anchor","(D) thioether anchor"],"answer":1,"image":""},{"id":"md2-105-2-41","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第2次第41題","year":105,"session":2,"number":41,"question":"下列何者與主動運輸（active transport）中，提供運輸過程的熱力學驅動力（thermodynamic driving force）無關？","options":["(A) 光能的補獲","(B) 三磷酸腺苷（ATP）的水解作用","(C) 大分子的合成","(D) 離子梯度的消耗（depletion of ion gradient）"],"answer":2,"image":""},{"id":"md2-105-2-42","subject":"md2","topic":"生化-訊息傳遞荷爾蒙細胞週期","meta":"105年第2次第42題","year":105,"session":2,"number":42,"question":"下列那一類分子透過結合並活化peroxisome proliferator-activated recepter alpha（PPARα），以調控生酮作用（ketogenesis）相關基因的表現？","options":["(A) purine","(B) fatty acids","(C) glucose","(D) pyrimidine"],"answer":1,"image":""},{"id":"md2-105-2-43","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第2次第43題","year":105,"session":2,"number":43,"question":"克氏循環（TCA cycle）的中間產物可經由轉氨基作用（transamination）直接生成下列那兩種胺基酸？","options":["(A) 精胺酸（arginine）與組胺酸（histidine）","(B) 酪胺酸（tyrosine）與脯胺酸（proline）","(C) 麩胺酸（glutamate）與天冬胺酸（aspartate）","(D) 丙胺酸（alanine）與絲胺酸（serine）"],"answer":2,"image":""},{"id":"md2-105-2-44","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第2次第44題","year":105,"session":2,"number":44,"question":"Ammonium ion（NH+）可藉由下列何種方式，由骨骼肌細胞運送到肝細胞代謝？4","options":["(A) Krebs cycle","(B) glucose-alanine cycle","(C) urea cycle","(D) citric acid cycle"],"answer":1,"image":""},{"id":"md2-105-2-45","subject":"md2","topic":"生化-中間代謝與調控","meta":"105年第2次第45題","year":105,"session":2,"number":45,"question":"分析一個腎臟癌病人的腫瘤時，發現有延胡索酸酵素（fumarase）基因突變，下列敘述何者正確？","options":["(A) 延胡索酸（fumarate）因而會在腫瘤組織中大幅下降","(B) 缺氧性誘導轉錄因子（hypoxia inducible transcription factor-1, HIF-1）會跟著下降","(C) 缺氧性誘導轉錄因子（hypoxia inducible transcription factor-1, HIF-1）會刺激多種糖解酵素（glycolytic enzymes）的產生","(D) 缺氧性誘導轉錄因子（hypoxia inducible transcription factor-1, HIF-1）會抑制血管生成（angiogenesis）"],"answer":2,"image":""},{"id":"md2-105-2-46","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第2次第46題","year":105,"session":2,"number":46,"question":"Scatchard分析法能提供下列何種資訊？","options":["(A) 酵素的功能放大（enzyme cascades）","(B) 酵素的催化反應（catalytic reaction）過程","(C) 蛋白質磷酸化（protein phosphorylation）","(D) 受體與配體之交互作用（receptor-ligand interactions）"],"answer":3,"image":""},{"id":"md2-105-2-47","subject":"md2","topic":"生化-訊息傳遞荷爾蒙細胞週期","meta":"105年第2次第47題","year":105,"session":2,"number":47,"question":"下視丘疾病可造成gonadotropin releasing hormone（GnRH）分泌失調，致使腦下腺luteinizing hormorne（LH），follicle- stimulating hormone（FSH）亦分泌失調，可能造成女性不孕。GnRH作用於G protein coupled receptor後，主要可活化phospholipase C，下列敘述何者錯誤？","options":["(A) phospholipase C可分解phosphatidylinositol 4,5-bisphosphate（PIP2）","(B) phosphatidylinositol 4,5-bisphosphate（PIP2）被分解為inositol 1,4,5-trisphosphate（IP3）及diacylglycerol（DAG）","(C) diacylglycerol（DAG）可直接活化protein kinase A","(D) inositol 1,4,5-trisphosphate（IP）可使內質網內之Ca2+釋放3"],"answer":2,"image":""},{"id":"md2-105-2-48","subject":"md2","topic":"生化-訊息傳遞荷爾蒙細胞週期","meta":"105年第2次第48題","year":105,"session":2,"number":48,"question":"常見於癌細胞組織中的腫瘤基因（oncogene）所轉譯之ErbB蛋白質，是經由下列那一個受體（receptor）的訊息傳導路徑而進行作用？","options":["(A) insulin receptor","(B) platelet-derived growth factor（PDGF）receptor","(C) epidermal growth factor（EGF）receptor","(D) G-protein coupling receptor"],"answer":2,"image":""},{"id":"md2-105-2-49","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第2次第49題","year":105,"session":2,"number":49,"question":"除了啟動子（promoter）及多選殖位點（multiple cloning sites）外，下列何者是原核細胞表現載體（expression vector）的必要構造？","options":["(A) 促進子（enhancer）、操縱子（operator）","(B) 致弱子（attenuator）、抑制子（repressor）","(C) 促進子（enhancer）、核糖體結合區（ribosome binding site）","(D) 核糖體結合區（ribosome binding site）、轉錄終止序列（transcriptional termination sequence）"],"answer":3,"image":""},{"id":"md2-105-2-50","subject":"md2","topic":"生化-核酸與基因表現","meta":"105年第2次第50題","year":105,"session":2,"number":50,"question":"建立基因剔除鼠（knockout mouse）的過程中，一般以取出實驗動物之何種細胞進行基因剔除？","options":["(A) 卵細胞","(B) 精細胞","(C) 受精卵","(D) 胚胎幹細胞"],"answer":3,"image":""},{"id":"md2-105-2-51","subject":"md2","topic":"生化-訊息傳遞荷爾蒙細胞週期","meta":"105年第2次第51題","year":105,"session":2,"number":51,"question":"有關於細胞訊息傳遞之機轉，下列何者錯誤？","options":["(A) 脂溶性ligand可以直接穿越細胞膜，並且與細胞內receptor結合產生作用","(B) 有些transmembrane receptor本身即具有酵素活性，可以經由與ligand結合後活化","(C) 有些transmembrane receptor與ligand結合後，可以活化protein tyrosine kinase","(D) NMDA glutamate receptor屬於GPCR（G-protein coupled receptor）"],"answer":3,"image":""},{"id":"md2-105-2-52","subject":"md2","topic":"藥理-化學治療","meta":"105年第2次第52題","year":105,"session":2,"number":52,"question":"下列何種藥物不適用於vancomycin-resistant Enterococcus faecium之感染治療？","options":["(A) linezolid","(B) tigecycline","(C) quinupristin-dalfopristin","(D) teicoplanin"],"answer":3,"image":""},{"id":"md2-105-2-53","subject":"md2","topic":"藥理-化學治療","meta":"105年第2次第53題","year":105,"session":2,"number":53,"question":"下列抗癌藥中何者因可以和vascular endothelial growth factor（VEGF）結合，而抑制血管新生（angiogenesis），可作為治療metastatic colorectal cancer之藥物？","options":["(A) bevacizumab","(B) cetuximab","(C) gefitinib","(D) imatinib"],"answer":0,"image":""},{"id":"md2-105-2-54","subject":"md2","topic":"藥理-化學治療","meta":"105年第2次第54題","year":105,"session":2,"number":54,"question":"下列何者為使用sulfonamides最常見副作用？","options":["(A) 神經症狀如頭痛及嗜睡","(B) 新生兒黃疸","(C) 皮膚過敏反應","(D) 肝炎"],"answer":2,"image":""},{"id":"md2-105-2-55","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"105年第2次第55題","year":105,"session":2,"number":55,"question":"下列何種藥物主要抑制腸細胞對cholesterol攝取作用，可與statin類藥物合用，以降低LDL之加成藥效？","options":["(A) Gemfibrozil","(B) Niacin","(C) Ezetimibe","(D) Cholestyramine"],"answer":2,"image":""},{"id":"md2-105-2-56","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"105年第2次第56題","year":105,"session":2,"number":56,"question":"有關heparin之敘述，下列何者正確？","options":["(A) 具有溶血栓活性","(B) 可抑制血小板凝集反應","(C) 可結合至antithrombin III，以達抗凝血活性","(D) 可抑制肝臟中vitamin K之再生"],"answer":2,"image":""},{"id":"md2-105-2-57","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"105年第2次第57題","year":105,"session":2,"number":57,"question":"有關vitamin D的敘述，下列何者錯誤？","options":["(A) 主要經由皮膚在紫外線輻射下由7-脫氫膽固醇（7-dehydrocholesterol）轉化而來","(B) 其活性代謝產物會增加血漿中鈣離子濃度","(C) 其活性代謝產物會降低血漿中磷酸鹽（phosphate）濃度","(D) 其衍生物19-nor-1α,25-dihydroxyvitamin D2具有抑制副甲狀腺激素（parathyroid hormone ; PTH）的釋放作用"],"answer":2,"image":""},{"id":"md2-105-2-58","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第2次第58題","year":105,"session":2,"number":58,"question":"有關methimazole的藥理作用，下列何者錯誤？","options":["(A) 主要透過抑制甲狀腺過氧化物酶催化反應（thyroid peroxidase-catalytic reaction）及碘有機化（iodine organification）的作用，來抑制甲狀腺素（triiodothyronine及tetraiodothyronine）的合成","(B) 會抑制週邊組織，將triiodothyronine及tetraiodothyronine進行脫碘化作用（deiodination）","(C) 其藥效起始作用（onset）相當快速，通常在服藥後即可產生治療效果","(D) 使用最常產生的副作用是斑丘疹搔癢皮疹（maculopapular pruritic rash）"],"answer":[1,2],"image":"","answer_note":"更正:第58題答Ｂ、Ｃ給分。"},{"id":"md2-105-2-59","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第2次第59題","year":105,"session":2,"number":59,"question":"有關liotrix的藥理作用描述，下列何者錯誤？","options":["(A) 為L-thyroxine與liothyronine以10:1的比例組合而成的複合藥物","(B) 具有治療甲狀腺功能低下症的藥理作用","(C) 可以使用於懷孕婦女","(D) 口服有效"],"answer":0,"image":""},{"id":"md2-105-2-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第2次第60題","year":105,"session":2,"number":60,"question":"有關糖皮質激素（glucocorticoids）作用的敘述，下列何者錯誤？","options":["(A) 糖皮質激素具有增加血中葡萄糖與脂肪酸之作用","(B) 在空腹狀態糖皮質激素具有促進糖質新生（gluconeogenesis）的作用","(C) 投予短效型糖皮質激素會減少循環系統中的嗜中性白血球（neutrophils）的數目，反之，淋巴細胞（lymphocytes）的數目會增加","(D) 糖皮質激素直接塗抹在皮膚表面會造成局部血管收縮的作用"],"answer":2,"image":""},{"id":"md2-105-2-61","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"105年第2次第61題","year":105,"session":2,"number":61,"question":"若急性心衰竭病人同時有血鈉過低之症狀，則下列何種藥物是最佳選擇？","options":["(A) spironolactone","(B) losartan","(C) conivaptan","(D) eplerenone"],"answer":2,"image":""},{"id":"md2-105-2-62","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"105年第2次第62題","year":105,"session":2,"number":62,"question":"下列那一種利尿劑對腎因性尿崩症（nephrogenic diabetes insipidus）可減少其多尿及煩渴之症狀？","options":["(A) amiloride","(B) torsemide","(C) hydrochlorothiazide","(D) brinzolamide"],"answer":2,"image":""},{"id":"md2-105-2-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"105年第2次第63題","year":105,"session":2,"number":63,"question":"下列關於organic nitrates之敘述何者錯誤？","options":["(A) 可使心室ejection time增加","(B) 可能引發心搏過速，以及鈉離子和水分滯留問題","(C) 可使靜脈擴張，血液回流減少，降低心臟的前負荷（pre-load）","(D) 可使冠狀動脈擴張，血流重分布至缺血區，改善心絞痛症狀"],"answer":0,"image":""},{"id":"md2-105-2-64","subject":"md2","topic":"藥理-總論與自主神經","meta":"105年第2次第64題","year":105,"session":2,"number":64,"question":"副交感神經系統興奮會產生下列何種直接反應？","options":["(A) 支氣管舒張","(B) 骨骼肌血管舒張","(C) 眼睛睫狀肌收縮","(D) 皮膚豎毛肌收縮"],"answer":2,"image":""},{"id":"md2-105-2-65","subject":"md2","topic":"藥理-總論與自主神經","meta":"105年第2次第65題","year":105,"session":2,"number":65,"question":"下列何種藥物的藥理作用機轉，是抑制膽鹼性神經釋放乙醯膽鹼？","options":["(A) amphetamine","(B) botulinum toxin","(C) cocaine","(D) tubocurarine"],"answer":1,"image":""},{"id":"md2-105-2-66","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第2次第66題","year":105,"session":2,"number":66,"question":"下列何種藥物適合以靜脈注射方式，用於治療急性且嚴重的氣喘或是慢性肺阻塞（COPD）的病人？","options":["(A) cromolyn","(B) tiotropium","(C) montelukast","(D) methylprednisolone"],"answer":3,"image":""},{"id":"md2-105-2-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第2次第67題","year":105,"session":2,"number":67,"question":"小孩患有氣喘，當發作時，須使用吸入性藥物來緩解或控制時，通常不建議使用下列何種藥物，以免影響其生長？","options":["(A) β2-agonists","(B) corticosteroids","(C) leukotrienes antagonists","(D) antimuscarinic agents"],"answer":1,"image":""},{"id":"md2-105-2-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第2次第68題","year":105,"session":2,"number":68,"question":"下列何種non-steroid anti-inflammatory drugs（NSAIDs）藥物，主要是具有止痛作用，有時用來取代morphine，作為病人手術後的止痛劑？","options":["(A) indomethacin","(B) ibuprofen","(C) ketoprofen","(D) ketorolac"],"answer":3,"image":""},{"id":"md2-105-2-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"105年第2次第69題","year":105,"session":2,"number":69,"question":"下列non-steroid anti-inflammatory drugs（NSAIDs）藥物，何者不具有抗發炎作用？","options":["(A) acetaminophen","(B) etodolac","(C) ketoprofen","(D) naproxen"],"answer":0,"image":""},{"id":"md2-105-2-70","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"105年第2次第70題","year":105,"session":2,"number":70,"question":"下列何者非carbamazepine的臨床適應症？","options":["(A) 癲癇（epilepsy）","(B) 三叉神經痛（trigeminal neuralgia）","(C) 憂鬱症（depression）","(D) 躁狂症（mania）"],"answer":2,"image":""},{"id":"md2-105-2-71","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"105年第2次第71題","year":105,"session":2,"number":71,"question":"下列何者為benzodiazepine的競爭性拮抗劑？","options":["(A) pralidoxime","(B) guanethidine","(C) flumazenil","(D) paraldehyde"],"answer":2,"image":""},{"id":"md2-105-2-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"105年第2次第72題","year":105,"session":2,"number":72,"question":"使用下類那一種治療巴金森氏症藥物時，尿液及唾液經常會呈現褐色的狀況？","options":["(A) selegiline","(B) levodopa","(C) amantadine","(D) bromocriptine"],"answer":1,"image":""},{"id":"md2-105-2-73","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"105年第2次第73題","year":105,"session":2,"number":73,"question":"下列何者中毒時，在臨床上可用其抗體當作解毒劑？","options":["(A) cyanide","(B) benzodiazepines","(C) digoxin","(D) isoniazid"],"answer":2,"image":""},{"id":"md2-105-2-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"105年第2次第74題","year":105,"session":2,"number":74,"question":"60歲的癲癇病人，服用下列某一種抗癲癇藥物，在剛開始服用的前兩週其效果不錯，但服用四週後開始出現偶發性癲癇的發作，在進行血中藥物濃度檢測後，發現其藥物濃度隨服藥期間的延長而逐漸的遞減，可能服用下列那一種抗癲癇藥物？","options":["(A) gabapentin","(B) ethosuximide","(C) carbamazepine","(D) primidone"],"answer":2,"image":""},{"id":"md2-105-2-75","subject":"md2","topic":"藥理-總論與自主神經","meta":"105年第2次第75題","year":105,"session":2,"number":75,"question":"承上題，其發生的可能原因為何？","options":["(A) 個體對於此藥物的敏感性差異所產生之結果","(B) 此藥物在長期使用後可能因為體內作用之受體數目減少，因此藥效遞減","(C) 此藥物在長期使用後可能因為誘發肝臟代謝酵素活性的升高，因此藥效遞減","(D) 此藥物在長期使用後可能因為抑制代謝此藥物之體內酵素活性，因此藥效遞減"],"answer":2,"image":""},{"id":"md2-105-2-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"105年第2次第76題","year":105,"session":2,"number":76,"question":"下列有關急性炎症（acute inflammation）之血管反應，何者正確？","options":["(A) 自血管滲出之液體主要為漏出液（transudate）","(B) 血管擴張是由於組織胺（histamine）及一氧化氮（nitric oxide, NO）等作用在血管內皮（endothelium）所致","(C) 血管滲透性（permeability）增加的最常見機轉是血管內皮受損、細胞壞死及脫落所致","(D) 血管內皮細胞收縮導致血管滲漏是因為組織胺（histamine）、遲緩激肽（bradykinin）等物質所引起"],"answer":3,"image":""},{"id":"md2-105-2-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"105年第2次第77題","year":105,"session":2,"number":77,"question":"下列有關細胞壞死（necrosis）的敘述，何者錯誤？","options":["(A) 壞死細胞的細胞質在H＆E染色較正常細胞嗜鹼性（basophilia）","(B) 細胞質中出現液泡是因為細胞質中胞器被消化所致","(C) 細胞核凝縮（pyknosis）可見於細胞凋亡（apoptotic cell death）","(D) 髓鞘質像（myelin figures）的形成是來自破損的細胞膜"],"answer":0,"image":""},{"id":"md2-105-2-78","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"105年第2次第78題","year":105,"session":2,"number":78,"question":"人類乳突病毒（HPV）16及18型與子宮頸癌的發生有密切關係，病毒的E6及E7蛋白較不會抑制下列何種抑癌基因的功能？","options":["(A) p53","(B) RB","(C) p21","(D) BRCA1及BRCA2"],"answer":3,"image":""},{"id":"md2-105-2-79","subject":"md2","topic":"病理-心血管血液","meta":"105年第2次第79題","year":105,"session":2,"number":79,"question":"下肢深層靜脈栓塞（deep venous thrombosis）所導致的下肢水腫，其主要機轉為：","options":["(A) 靜水壓上升","(B) 血漿滲透壓下降","(C) 淋巴管阻塞","(D) 鈉與水的滯留"],"answer":0,"image":""},{"id":"md2-105-2-80","subject":"md2","topic":"病理-心血管血液","meta":"105年第2次第80題","year":105,"session":2,"number":80,"question":"有關肥厚性心肌病變（hypertrophic cardiomyopathy）的病理變化，下列何者錯誤？","options":["(A) 主動脈瓣下（subaortic region）心室中隔呈明顯肥厚","(B) 心室通常會明顯擴大","(C) 心肌細胞呈雜亂排列","(D) 心肌間質呈現纖維化"],"answer":1,"image":""},{"id":"md2-105-2-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"105年第2次第81題","year":105,"session":2,"number":81,"question":"有關淋巴癌的敘述，下列何者正確？","options":["(A) 一旦血液中發現淋巴腫瘤細胞，就應歸類為白血病（leukemia）而非淋巴癌","(B) 淋巴結外的被套細胞淋巴癌（mantle cell lymphoma）主要與幽門螺旋桿菌（Helicobacter pylori）有關","(C) 無論是T細胞或B細胞淋巴癌，淋巴癌常常都會有抗原受體（antigen receptor）基因重組的現象","(D) 在臺灣何杰金氏淋巴癌（Hodgkin lymphoma）較非何杰金氏淋巴癌（non-Hodgkin lymphoma）常見"],"answer":2,"image":""},{"id":"md2-105-2-82","subject":"md2","topic":"病理-呼吸消化","meta":"105年第2次第82題","year":105,"session":2,"number":82,"question":"下列有關肺隔離（pulmonary sequestration）之敘述，何者錯誤？","options":["(A) 肺組織與氣道系統無正常聯結","(B) 血流供應來自肺動脈","(C) 肺葉外肺隔離常合併其他先天異常","(D) 肺葉內肺隔離常合併感染"],"answer":1,"image":""},{"id":"md2-105-2-83","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"105年第2次第83題","year":105,"session":2,"number":83,"question":"下列有關塵肺症（pneumoconioses）的敘述，何者錯誤？","options":["(A) 吸入礦物塵埃、有機塵埃、化學煙霧或蒸氣引起","(B) 最易造成塵肺症的顆粒大小在5到10微米","(C) 體積較小之顆粒較易引起急性肺傷害","(D) 吸菸可加重吸入礦物塵埃造成的傷害"],"answer":1,"image":""},{"id":"md2-105-2-84","subject":"md2","topic":"病理-呼吸消化","meta":"105年第2次第84題","year":105,"session":2,"number":84,"question":"脫落性間質肺炎（desquamative interstitial pneumonia）病人肺泡內大量含有色素顆粒的細胞為：","options":["(A) 中性白血球","(B) 脫落之上皮細胞","(C) 巨噬細胞","(D) 活化之淋巴母細胞"],"answer":2,"image":""},{"id":"md2-105-2-85","subject":"md2","topic":"細菌學","meta":"105年第2次第85題","year":105,"session":2,"number":85,"question":"下列何種病原體通常引起非典型肺炎（atypical pneumonia）？","options":["(A) Streptococcus pneumoniae","(B) Mycobacterium avium-intracellulare","(C) Mycoplasma pneumoniae","(D) Nocardia"],"answer":2,"image":""},{"id":"md2-105-2-86","subject":"md2","topic":"病理-心血管血液","meta":"105年第2次第86題","year":105,"session":2,"number":86,"question":"65歲女性，兩側性肋膜積水，其所含蛋白質濃度較低。其最有可能診斷為下列何者？","options":["(A) 肺癌","(B) 細菌性肺炎","(C) 結核性肺炎","(D) 心臟衰竭"],"answer":3,"image":""},{"id":"md2-105-2-87","subject":"md2","topic":"病理-呼吸消化","meta":"105年第2次第87題","year":105,"session":2,"number":87,"question":"有關幽門桿菌性胃炎的敘述，下列何者最不適當？","options":["(A) 在竇部（antrum）比體部（body）嚴重","(B) 感染帶有CagA基因的細菌者，比較會產生胃癌","(C) 細菌較易出現在腸道化生（intestinal metaplasia）的部位","(D) 是胃淋巴瘤的主要成因"],"answer":2,"image":""},{"id":"md2-105-2-88","subject":"md2","topic":"病理-呼吸消化","meta":"105年第2次第88題","year":105,"session":2,"number":88,"question":"慢性胰臟炎最常見的原因為何？","options":["(A) 膽結石","(B) 長期酗酒","(C) 慢性肝炎","(D) CFTR基因突變"],"answer":1,"image":""},{"id":"md2-105-2-89","subject":"md2","topic":"病理-呼吸消化","meta":"105年第2次第89題","year":105,"session":2,"number":89,"question":"56歲男性皮膚及鞏膜泛黃，且有茶色尿及灰白便。下列敘述何者正確？","options":["(A) 此病人有溶血性黃疸","(B) 若摸到腫大的膽囊，病人肝外膽管阻塞","(C) 血中升高的膽紅素主要是非接合型膽紅素","(D) 肝癌細胞因為會製造過多膽紅素也特別容易出現此類黃疸"],"answer":1,"image":""},{"id":"md2-105-2-90","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"105年第2次第90題","year":105,"session":2,"number":90,"question":"5歲男孩，一週前出現頭痛、發燒及頸部僵硬而住院治療，腦脊椎液培養出奈瑟氏腦膜炎雙球菌（Neisseria meningitidis），入院後病患發生低血壓性休克及皮膚出現紫斑，此病患的腎上腺最有可能呈現何種病理變化？","options":["(A) 皮質細胞增生","(B) 髓質細胞增生","(C) 大量出血","(D) 功能性腺瘤的產生"],"answer":2,"image":""},{"id":"md2-105-2-91","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"105年第2次第91題","year":105,"session":2,"number":91,"question":"有關攝護腺結節狀增生（prostatic nodular hyperplasia）之敘述，下列何者錯誤？","options":["(A) Dihydrotestosterone可作用於細胞核的androgen receptor，只導致上皮細胞增生","(B) 主要發生的區域是移形區（transitional zone）","(C) 可用α-adrenergic receptor抑制劑降低平滑肌張力以緩解尿路阻塞的症狀","(D) 顯微鏡檢有時可在梗塞（infarct）附近發現上皮細胞有局部鱗狀化生"],"answer":0,"image":""},{"id":"md2-105-2-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"105年第2次第92題","year":105,"session":2,"number":92,"question":"42歲女性病人因胃癌手術進行mitomycin-C化學治療。三個月後發生急性腎臟衰竭，高血壓和全身水腫，實驗室數據顯示microangiopathic hemolytic anemia。下列敘述中何者最可能代表她腎絲球裡面的病理變化？","options":["(A) 血管內皮細胞腫脹及沉積纖維蛋白性小血栓","(B) 大量沉積免疫複合體","(C) 半月形細胞增生及壞死","(D) 細胞增生及中性球浸潤"],"answer":0,"image":""},{"id":"md2-105-2-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"105年第2次第93題","year":105,"session":2,"number":93,"question":"下列疾病與其病理特徵的組合，何者正確？","options":["(A) 疱疹（herpes）病毒感染與空洞細胞（koilocyte）","(B) 水泡狀胎塊（hydatidiform mole）與Call-Exner bodies","(C) 卵黃囊瘤（yolk sac tumor）與Birbeck granules","(D) 萊氏細胞瘤（Leydig cell tumor）與Reinke crystalloids"],"answer":3,"image":""},{"id":"md2-105-2-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"105年第2次第94題","year":105,"session":2,"number":94,"question":"功能不良性子宮出血（dysfunctional uterine bleeding）最常見的機轉為何？","options":["(A) 濾泡期太短（short follicular phase）","(B) 黃體期不足（inadequate luteal phase）","(C) 無排卵周期（anovulatory cycle）","(D) 外源性黃體激素（exogenous progesterone）"],"answer":2,"image":""},{"id":"md2-105-2-95","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"105年第2次第95題","year":105,"session":2,"number":95,"question":"56歲女性，大陰唇處有一個界限明顯、會癢、表面較紅且會結痂的病變。她接受切片檢查。圖示是病變區在顯微鏡下的變化。下列有關此病的敘述何者正確？","options":["(A) 由human papillomavirus所引起","(B) 是源自黑色素細胞的良性腫瘤","(C) 是原發性的鱗狀細胞癌","(D) 病變細胞的細胞質PAS染色為陽性"],"answer":3,"image":"md2-105-2-95.jpeg"},{"id":"md2-105-2-96","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"105年第2次第96題","year":105,"session":2,"number":96,"question":"70歲長者在大腿內側及前臂屈側、腋窩、腹股溝及下腹部之皮膚有多個水泡（bullae），組織切片呈現表皮下非棘層鬆解的水泡（subepidermal nonacantholytic blisters），免疫螢光檢查見免疫球蛋白及補體呈線形沉積於基底膜部位，其診斷為何？","options":["(A) 尋常性天疱瘡（pemphigus vulgaris）","(B) 紅斑性天疱瘡（pemphigus erythematosus）","(C) 大水泡性類天疱瘡（bullous pemphigoid）","(D) 疱疹性皮炎（dermatitis herpetiformis）"],"answer":2,"image":""},{"id":"md2-105-2-97","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"105年第2次第97題","year":105,"session":2,"number":97,"question":"34歲男性，因中樞神經系統症狀住院，腦部切片顯示多個髓鞘脫失（demyelination）病灶，其內之神經軸索（axons）數目略減，病灶邊緣之寡樹突膠質細胞核呈玻璃狀雙染的包涵物（glassy amphophilic inclusions），亦見到奇異且巨大的星狀膠原細胞（bizarre giant astrocytes），其診斷為何？","options":["(A) 人類免疫力不足病毒腦炎（human immunodeficiency virus encephalitis）","(B) 進行性多病灶腦白質病（progressive multifocal leukoencephalopathy）","(C) 亞急性硬化性全腦炎（subacute sclerosing panencephalitis）","(D) 第二型單純疱疹病毒腦炎（herpes simplex virus type 2 encephalitis）"],"answer":1,"image":""},{"id":"md2-105-2-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"105年第2次第98題","year":105,"session":2,"number":98,"question":"下列有關原發性中樞神經系統淋巴瘤的敘述，何者錯誤？","options":["(A) 此為免疫抑制病人最常見的中樞神經系統腫瘤","(B) 中樞神經系統以外的組織亦常被侵犯","(C) 絕大多數的腫瘤為B細胞淋巴瘤，且大多數細胞會表現BCL-6","(D) 血管內淋巴瘤（intravascular lymphoma）通常以廣泛的微小梗塞表現，而不是以腫塊表現"],"answer":1,"image":""},{"id":"md2-105-2-99","subject":"md2","topic":"病理-免疫感染遺傳","meta":"105年第2次第99題","year":105,"session":2,"number":99,"question":"55歲女性因眼睛容易感到疲勞、出現燒熱感前來就診。另外病人抱怨口腔內也會有燒熱感，咀嚼及吞嚥乾的食物時會有困難。身體檢查發現兩側耳下腺腫脹但不會感覺疼痛。血清檢查發現病人血中抗SS-A與抗SS-B抗體升高。有關此疾病之敘述，下列何者正確？","options":["(A) 唾液腺會有很多淋巴細胞（lymphocyte）浸潤，主要以CD8陽性T淋巴細胞為主","(B) 應立即進行腎臟切片檢查以評估疾病嚴重度","(C) 此類病人常會有類風濕因子（rheumatoid factor）升高現象","(D) 此類病人常會有抗染色體中節抗體（anti-centromere antibody）升高現象"],"answer":2,"image":""},{"id":"md2-105-2-100","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"105年第2次第100題","year":105,"session":2,"number":100,"question":"（承上題）病人日後較容易罹患下列何種淋巴癌？","options":["(A) 瀰漫型T淋巴細胞為主的淋巴癌（diffuse T-cell lymphoma）","(B) 周邊區域型淋巴癌（marginal zone lymphoma）","(C) 被套細胞淋巴癌（mantle cell lymphoma）","(D) 何杰金氏淋巴癌（Hodgkin lymphoma）"],"answer":1,"image":""},{"id":"md2-106-1-1","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"106年第1次第1題","year":106,"session":1,"number":1,"question":"關於細胞膜上的膽固醇（cholesterol）其結構及功能的敘述，下列何者正確？","options":["(A) 與細胞膜相較，胞器膜（membrane of the organelle）上的膽固醇含量較多","(B) 膽固醇帶極性的羥基（polar hydroxyl group）鑲嵌於細胞膜的雙脂層（lipid bilayers）夾層內部（interior）","(C) 膽固醇可幫助調節細胞膜的膜流動性（membrane fluidity）","(D) 膽固醇在細胞膜內外側的分布是對稱的（symmetric）"],"answer":2,"image":""},{"id":"md2-106-1-2","subject":"md2","topic":"解剖-神經解剖","meta":"106年第1次第2題","year":106,"session":1,"number":2,"question":"一位因中風（stroke）而導致左側腦視神經束（optic tract）受損的患者，下列何者為該患者最可能的視覺障礙？","options":["(A) 無法感知來自右眼的內外側視網膜（retina）上的影像","(B) 無法感知來自左眼的內外側視網膜（retina）上的影像","(C) 右眼的外側及左眼的內側視野(visual field)偏盲","(D) 兩眼的外側視野(visual field)偏盲"],"answer":2,"image":""},{"id":"md2-106-1-3","subject":"md2","topic":"藥理-總論與自主神經","meta":"106年第1次第3題","year":106,"session":1,"number":3,"question":"下列那一種神經元的軸突末端，不是以acetylcholine為其釋出的主要神經傳導物質？","options":["(A) alpha-motor neurons","(B) gamma-motor neurons","(C) preganglionic parasympathetic neurons","(D) postganglionic sympathetic neurons"],"answer":3,"image":""},{"id":"md2-106-1-4","subject":"md2","topic":"生理-細胞神經肌肉","meta":"106年第1次第4題","year":106,"session":1,"number":4,"question":"聲波震動在人類耳部的傳導順序，下列何者正確？①tympanic membrane ②middle-ear bones ③round window membrane ④basilar membrane ⑤oval window membrane","options":["(A) ①②③④⑤","(B) ②①④③⑤","(C) ①②③⑤④","(D) ①②⑤④③"],"answer":3,"image":""},{"id":"md2-106-1-5","subject":"md2","topic":"生理-細胞神經肌肉","meta":"106年第1次第5題","year":106,"session":1,"number":5,"question":"下列各種感覺及其受器，何者最不容易因持續刺激而發生傳導適應現象（adaptation）？","options":["(A) 壓覺；pacinian corpuscles","(B) 本體感覺；muscle spindles","(C) 嗅覺；olfactory receptor cells","(D) 聽覺；hair cell receptors"],"answer":1,"image":""},{"id":"md2-106-1-6","subject":"md2","topic":"生理-細胞神經肌肉","meta":"106年第1次第6題","year":106,"session":1,"number":6,"question":"下列小腦皮質部細胞中，何者屬於分泌glutamate的興奮性神經元？","options":["(A) Purkinje cells","(B) Golgi cells","(C) granule cells","(D) basket cells"],"answer":2,"image":""},{"id":"md2-106-1-7","subject":"md2","topic":"生理-細胞神經肌肉","meta":"106年第1次第7題","year":106,"session":1,"number":7,"question":"相較於維持姿勢的背部肌，下列有關操作精細動作的手指肌肉之敘述，何者正確？","options":["(A) 氧化能力（oxidative capacity）較高","(B) 肌凝蛋白ATP酶（myosin ATPase）的活性較高","(C) I型肌纖維（type I fibers）較多","(D) 紅肌（red muscles）較多"],"answer":1,"image":""},{"id":"md2-106-1-8","subject":"md2","topic":"生理-細胞神經肌肉","meta":"106年第1次第8題","year":106,"session":1,"number":8,"question":"下列有關骨骼肌與平滑肌的異同之敘述，何者正確？","options":["(A) 骨骼肌細胞actin固定在Z lines，而平滑肌細胞則固定在dense bodies","(B) 骨骼肌細胞具有較多的actin，而平滑肌細胞具有較多的myosin","(C) 骨骼肌細胞和平滑肌細胞皆具有troponin C","(D) 骨骼肌細胞具有tropomyosin而平滑肌細胞則無"],"answer":0,"image":""},{"id":"md2-106-1-9","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"106年第1次第9題","year":106,"session":1,"number":9,"question":"對吞噬細胞（phagocytes）的敘述，下列何者錯誤？","options":["(A) 巨噬細胞（macrophage）可被T淋巴球（lymphocytes）分泌的細胞激素（cytokines）所活化","(B) 肝臟的Kupffer cells是一種特化的巨噬細胞，可吞噬細菌亦可分泌細胞激素（cytokines）","(C) 嗜中性球（neutrophil）細胞內NADPH oxidase complex活化後會合成超氧化物（superoxidant）","(D) 巨噬細胞（macrophage）是由單核球（monocyte）受細菌刺激後分裂而成的"],"answer":3,"image":""},{"id":"md2-106-1-10","subject":"md2","topic":"生理-心臟血管","meta":"106年第1次第10題","year":106,"session":1,"number":10,"question":"比較血管系統中，動脈、微血管與靜脈等組織的結構與功能，下列敘述何者正確？","options":["(A) 動脈富彈性，所以其順應性（compliance）比靜脈好","(B) 平時約有60%血液停留在靜脈。所以靜脈是血管系統的「壓力儲存器」（pressure reservoir）","(C) 微血管有最大的總橫切面積與最低平均流速","(D) 血液在不同血管中的流速取決於距離心臟的遠近"],"answer":2,"image":""},{"id":"md2-106-1-11","subject":"md2","topic":"生理-心臟血管","meta":"106年第1次第11題","year":106,"session":1,"number":11,"question":"關於脈搏壓（pulse pressure）的敘述，下列何者正確？","options":["(A) 收縮壓（systolic pressure）增加時，脈搏壓一定會增加","(B) 脈搏壓的大小與動脈的順應性（compliance）無關","(C) 脈搏壓可能因心搏量（stroke volume）增加而上升","(D) 脈搏壓可能因舒張壓（diastolic pressure）的上升而上升"],"answer":2,"image":""},{"id":"md2-106-1-12","subject":"md2","topic":"生理-心臟血管","meta":"106年第1次第12題","year":106,"session":1,"number":12,"question":"若一受測者從臥姿突然站立時，因血壓降低而感到暈眩。此時身體會利用下列那一反應來幫助穩定動脈血壓？","options":["(A) 降低動脈感壓受器反射（arterial baroreceptors reflex）放電頻率","(B) 降低心跳速率","(C) 降低靜脈回流（venous return）","(D) 促使小動脈（arterioles）舒張"],"answer":0,"image":""},{"id":"md2-106-1-13","subject":"md2","topic":"生理-呼吸","meta":"106年第1次第13題","year":106,"session":1,"number":13,"question":"解剖無效腔（anatomic dead space）內氧氣（O2）與二氧化碳（CO2）之組成比例與下列何者最相近？","options":["(A) 肺泡（alveolus）內氣體","(B) 大氣（atmospheric gas）","(C) 肺泡微血管（alveolar capillary）內血液","(D) 周邊微血管（peripheral capillary）內血液"],"answer":1,"image":""},{"id":"md2-106-1-14","subject":"md2","topic":"生理-呼吸","meta":"106年第1次第14題","year":106,"session":1,"number":14,"question":"正常人站立時，其肺內何處的氧分壓（PO₂）顯著高於體動脈血（systemic arterial blood）的氧分壓，而且該處的二氧化碳分壓（PCO₂）顯著低於體動脈血的二氧化碳分壓？","options":["(A) 肺底（lung base）","(B) 肺中段（middle lung）","(C) 肺尖（lung apex）","(D) 肺內到處都如此"],"answer":2,"image":""},{"id":"md2-106-1-15","subject":"md2","topic":"生理-呼吸","meta":"106年第1次第15題","year":106,"session":1,"number":15,"question":"正常人呼吸時，下列何者測得的壓力於吸氣期和呼氣期最可能都是負壓（negative pressure）？","options":["(A) 肋膜內壓（intrapleural pressure）","(B) 肺泡壓（alveolar pressure）","(C) 肺泡壓－肋膜壓（transpulmonary pressure）","(D) 氣道壓（airway pressure）"],"answer":0,"image":""},{"id":"md2-106-1-16","subject":"md2","topic":"生理-消化","meta":"106年第1次第16題","year":106,"session":1,"number":16,"question":"新生兒缺乏下列何種細胞膜蛋白最容易引起嚴重下痢？","options":["(A) sodium-dependent glucose transporter 1（SGLT1）","(B) cystic fibrosis transmembrane conductance regulator（CFTR）","(C) aquaporin","(D) sodium-dependent glucose transporter 2（SGLT 2）"],"answer":[0,2],"image":"","answer_note":"更正:第16題答Ａ、Ｃ給分"},{"id":"md2-106-1-17","subject":"md2","topic":"生理-消化","meta":"106年第1次第17題","year":106,"session":1,"number":17,"question":"下列何者之分泌在進食後短時間內會受到抑制？","options":["(A) 膽囊收縮素（cholecystokinin）","(B) 胃泌素（gastrin）","(C) 運動素（motilin）","(D) 胰泌素（secretin）"],"answer":2,"image":""},{"id":"md2-106-1-18","subject":"md2","topic":"生理-腎臟","meta":"106年第1次第18題","year":106,"session":1,"number":18,"question":"在抗利尿激素發揮作用的狀況之下，下列那一段的腎小管腔內液體會達到最低的osmolarity？","options":["(A) 鮑氏囊（Bowman's capsule）","(B) 近端腎小管的末端（end of the proximal tubule）","(C) 亨利氏環上升段粗枝的末端（distal end of the thick ascending limb of the loop of Henle）","(D) 皮質集尿管的末端（end of the cortical collecting duct）"],"answer":2,"image":""},{"id":"md2-106-1-19","subject":"md2","topic":"生理-內分泌代謝","meta":"106年第1次第19題","year":106,"session":1,"number":19,"question":"在實驗中給予實驗鼠氯化鈣溶液灌注以提高其血鈣濃度，下列何者為最可能之預期變化？","options":["(A) 抑鈣素（calcitonin）分泌減少","(B) 骨質流失（bone demineralization）","(C) 減少噬骨細胞（osteoclast）的活性","(D) 減少凝血作用（blood coagulation）"],"answer":2,"image":""},{"id":"md2-106-1-20","subject":"md2","topic":"生化-訊息傳遞荷爾蒙細胞週期","meta":"106年第1次第20題","year":106,"session":1,"number":20,"question":"Prohormone轉化為hormone的過程，主要在何處進行？","options":["(A) Golgi apparatus","(B) mitochondrion","(C) peroxisome","(D) centriole"],"answer":0,"image":""},{"id":"md2-106-1-21","subject":"md2","topic":"生理-內分泌代謝","meta":"106年第1次第21題","year":106,"session":1,"number":21,"question":"下列何者屬於最典型的神經激素（neurohormone）？","options":["(A) vasopressin","(B) FSH（follicle stimulating hormone）","(C) thyroid hormone","(D) estrogen"],"answer":0,"image":""},{"id":"md2-106-1-22","subject":"md2","topic":"生理-內分泌代謝","meta":"106年第1次第22題","year":106,"session":1,"number":22,"question":"下列何種疾病與胰島素抗性（insulin resistance）的產生最無關？","options":["(A) 肥胖（obesity）","(B) 庫欣氏症候群（Cushing's syndrome）","(C) 腎上腺機能不全（adrenal insufficiency）","(D) 肢端肥大症（acromegaly）"],"answer":2,"image":""},{"id":"md2-106-1-23","subject":"md2","topic":"生理-腎臟","meta":"106年第1次第23題","year":106,"session":1,"number":23,"question":"關於醛固酮（aldosterone）分泌不足的生理變化，下列敘述何者錯誤？","options":["(A) 細胞外液之鉀離子濃度會顯著上升","(B) 細胞外液體積會顯著減少","(C) 心輸出量會顯著上升","(D) 總血量會顯著降低"],"answer":2,"image":""},{"id":"md2-106-1-24","subject":"md2","topic":"生理-生殖","meta":"106年第1次第24題","year":106,"session":1,"number":24,"question":"有關婦女停經（menopause）的敘述，下列何者錯誤？","options":["(A) 停經後會伴隨有血漿中濾泡促素（follicular stimulating hormone）和黃體促素（luteinizing hormone）的升高","(B) 停經後易造成骨質疏鬆（osteoporosis），與雌激素（estrogen）分泌減少有關","(C) 停經後，助孕酮（progesterone）的分泌不受影響","(D) 停經前經常會伴隨有月經週期不規則的產生"],"answer":2,"image":""},{"id":"md2-106-1-25","subject":"md2","topic":"生理-生殖","meta":"106年第1次第25題","year":106,"session":1,"number":25,"question":"有關睪丸的組織顯微結構與功能的配對，下列何者最為恰當？","options":["(A) Leydig cell位於曲細精管（seminiferous tubule）之內；分泌睪固酮（testosterone）","(B) Sertoli cell位於曲細精管（seminiferous tubule）之外；曲細精管收縮","(C) Sertoli cell位於曲細精管（seminiferous tubule）之內；精子（sperm）的分化和成熟","(D) Leydig cell位於曲細精管（seminiferous tubule）之內；精子（sperm）的營養供應"],"answer":2,"image":""},{"id":"md2-106-1-26","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"106年第1次第26題","year":106,"session":1,"number":26,"question":"若蛋白質A的正確摺疊（folding）需要另一蛋白質B的幫助，然而蛋白質B的正確摺疊不需要蛋白質A的幫忙。蛋白質B是屬於下列何種物質？","options":["(A) 配體（ligand）","(B) 分子伴護子（molecular chaperone）","(C) 蛋白質A的同功酶（isoenzyme）","(D) 結構基序（structural motif）"],"answer":1,"image":""},{"id":"md2-106-1-27","subject":"md2","topic":"生化-訊息傳遞荷爾蒙細胞週期","meta":"106年第1次第27題","year":106,"session":1,"number":27,"question":"下列那一類細胞的訊息受器（receptor）及其結合蛋白不具有酵素催化活性？","options":["(A) nuclear receptors","(B) receptor protein kinases","(C) G protein-coupled receptors","(D) chemokine/cytokine receptors"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第27題一律給分 (原公告答案 A)"},{"id":"md2-106-1-28","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"106年第1次第28題","year":106,"session":1,"number":28,"question":"有些蛋白質係由多條獨立的多肽鏈（或稱蛋白質次單元）組合而成，這些次單元間在三度空間中的排列方式稱為蛋白質的：","options":["(A) 二級結構（secondary structure）","(B) 超二級結構（supersecondary structure）","(C) 三級結構（tertiary structure）","(D) 四級結構（quaternary structure）"],"answer":3,"image":""},{"id":"md2-106-1-29","subject":"md2","topic":"生化-中間代謝與調控","meta":"106年第1次第29題","year":106,"session":1,"number":29,"question":"罕見的單基因（monogenic）糖尿病，其致病基因已有6種以上，其中一種是葡萄糖代謝相關的酶hexokinase IV（glucokinase）發生突變，關於該酶之敘述，下列何者錯誤？","options":["(A) 該酶作用參與糖解反應（glycolysis）","(B) 該酶基因突變會直接增加TCA cycle之反應速率","(C) 該酶基因突變會導致胰島細胞ATP生成減少","(D) 該酶會磷酸化葡萄糖"],"answer":1,"image":""},{"id":"md2-106-1-30","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"106年第1次第30題","year":106,"session":1,"number":30,"question":"催化轉胺反應（transamination）的酵素，需要利用下列何種維生素做為胺基暫時的攜帶者？","options":["(A) flavin adenine dinucleotide（vitamin B2）","(B) pyridoxal phosphate（vitamin B6）","(C) tetrahydrofolate（H4 folate）","(D) thiamin pyrophosphate（vitamin B1）"],"answer":1,"image":""},{"id":"md2-106-1-31","subject":"md2","topic":"生化-核酸與基因表現","meta":"106年第1次第31題","year":106,"session":1,"number":31,"question":"下列何者能與單股DNA序列（5'）AGACTGGTC（3'）最穩定的雜交（hybridization）？","options":["(A) （5'）CTGGTCAGA（3'）","(B) （5'）GACCAGTCT（3'）","(C) （5'）AGACTGGTC（3'）","(D) （5'）TCTGACCAG（3'）"],"answer":1,"image":""},{"id":"md2-106-1-32","subject":"md2","topic":"生化-中間代謝與調控","meta":"106年第1次第32題","year":106,"session":1,"number":32,"question":"5-phosphoribosyl-1-pyrophosphate（PRPP）合成inosine 5'-monophosphate（IMP）的核苷酸生合成途徑中，PRPP amidotransferase反應速率可受到下列那一個產物的直接負調控？","options":["(A) AMP","(B) CMP","(C) FAD","(D) malonyl-CoA"],"answer":0,"image":""},{"id":"md2-106-1-33","subject":"md2","topic":"生化-核酸與基因表現","meta":"106年第1次第33題","year":106,"session":1,"number":33,"question":"大腸桿菌DNA聚合酶I型（DNA polymerase I）的何種酵素活性會參與執行nick translation？","options":["(A) 聚合酶與5'核酸外切酶（polymerase and 5'→3'exonuclease）","(B) 聚合酶與3'核酸外切酶（polymerase and 3'→5'exonuclease）","(C) 5'與3'核酸外切酶（5'→3' and 3'→5'exonuclease）","(D) 聚合酶，5'與3'核酸外切酶（polymerase, 5'→3' and 3'→5'exonuclease）"],"answer":0,"image":""},{"id":"md2-106-1-34","subject":"md2","topic":"生化-核酸與基因表現","meta":"106年第1次第34題","year":106,"session":1,"number":34,"question":"聚合酶鏈鎖反應（Polymerase chain reaction, PCR）可以讓微量DNA在短時間內大量擴增，需要何種二價金屬離子以促進反應進行？","options":["(A) Ca2+","(B) Zn2+","(C) Mg2+","(D) Fe2+"],"answer":2,"image":""},{"id":"md2-106-1-35","subject":"md2","topic":"生化-核酸與基因表現","meta":"106年第1次第35題","year":106,"session":1,"number":35,"question":"下列何者是編碼子（codon）與反編碼子（anticodon）配對時，擺動假說（wobble hypothesis）的最佳詮釋？","options":["(A) 指每一tRNA都只能辨認一個特定的編碼子","(B) 指某些tRNA能辨認不同胺基酸的各種編碼子","(C) 指反編碼子上的第一個鹼基具有較彈性的配對能力","(D) 指反編碼子上的第三個鹼基只能作Watson-Crick式的配對"],"answer":2,"image":""},{"id":"md2-106-1-36","subject":"md2","topic":"生化-訊息傳遞荷爾蒙細胞週期","meta":"106年第1次第36題","year":106,"session":1,"number":36,"question":"AMP-activated protein kinase（AMPK）在活化後，主要會促進下列那一種反應途徑？","options":["(A) gluconeogenesis","(B) lipid biosynthesis","(C) glycolysis","(D) cholesterol synthesis"],"answer":2,"image":""},{"id":"md2-106-1-37","subject":"md2","topic":"免疫學","meta":"106年第1次第37題","year":106,"session":1,"number":37,"question":"下列關於抗體的敘述，何者錯誤？","options":["(A) 抗體IgG由兩個light chain（L）與兩個heavy chain（H）組成","(B) 抗體IgG有兩個抗原結合位","(C) 抗體N端的hypervariable loop region可與抗原專一性結合","(D) light chain與heavy chain結構以α-helix為主"],"answer":3,"image":""},{"id":"md2-106-1-38","subject":"md2","topic":"生化-中間代謝與調控","meta":"106年第1次第38題","year":106,"session":1,"number":38,"question":"下列何種物質無法作為葡萄糖生合成（gluconeogenesis）之前驅物？","options":["(A) 脂肪酸","(B) 胺基酸","(C) 甘油（glycerol）","(D) 草醯乙酸（oxaloacetate）"],"answer":0,"image":""},{"id":"md2-106-1-39","subject":"md2","topic":"生化-中間代謝與調控","meta":"106年第1次第39題","year":106,"session":1,"number":39,"question":"下列何者會增加肝臟肝醣分解（glycogenolysis）？","options":["(A) 抑制glycogen phosphorylase","(B) 活化phosphorylase b kinase","(C) 活化phosphorylase a phosphatase","(D) 抑制glycogen synthase kinase 3（GSK3）"],"answer":1,"image":""},{"id":"md2-106-1-40","subject":"md2","topic":"生化-中間代謝與調控","meta":"106年第1次第40題","year":106,"session":1,"number":40,"question":"在下列何種情況下，acetyl-CoA進入citric acid cycle會減少？","options":["(A) [AMP]/[ATP]高","(B) [ATP]/[ADP]高","(C) [NAD+]/[NADH]高","(D) [oxaloacetate]高"],"answer":[1,3],"image":"","answer_note":"更正:第40題答Ｂ、Ｄ給分"},{"id":"md2-106-1-41","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"106年第1次第41題","year":106,"session":1,"number":41,"question":"有關細胞膜上之脂膜筏（lipid raft），下列敘述何者正確？","options":["(A) 有較低量膽固醇（cholesterol）","(B) 有較低量鞘脂（sphingolipid）","(C) 不含有燒杯狀膜小囊蛋白（caveolin）","(D) 有較高量的糖基化磷脂醯肌醇（glycosylated derivative of phosphatidylinositol; GPI）結合蛋白質"],"answer":3,"image":""},{"id":"md2-106-1-42","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"106年第1次第42題","year":106,"session":1,"number":42,"question":"下列那一個運輸系統屬於P-type ATPase的作用機制？","options":["(A) 肌肉細胞內質網的鈣離子幫浦（Ca2+ pump）","(B) 紅血球上的葡萄糖運輸器（glucose transporter）","(C) 小腸黏膜細胞內的鈉離子-葡萄糖運輸器（Na+-glucose transporter）","(D) 紅血球上的氯離子-碳酸氫鹽交換器（chloride-bicarbonate exchanger）"],"answer":0,"image":""},{"id":"md2-106-1-43","subject":"md2","topic":"生化-中間代謝與調控","meta":"106年第1次第43題","year":106,"session":1,"number":43,"question":"關於脂肪組織之脂肪代謝，下列敘述何者錯誤？","options":["(A) 脂肪組織脂肪分解，釋放出來的脂肪酸，可供給其他組織產生能量","(B) 脂肪組織脂肪分解，分解出來的脂肪酸，釋放至血液與血清白蛋白（serum albumin）結合","(C) 脂肪組織脂肪分解，釋放出來的脂肪酸可送到肝臟內再合成三酸甘油酯，所以肥胖病患易合併脂肪肝","(D) 空腹時，釋放出來的脂肪酸送到肝臟內合成三酸甘油酯，包裝成乳糜微粒（chylomicron）分泌至血液中"],"answer":3,"image":""},{"id":"md2-106-1-44","subject":"md2","topic":"生化-中間代謝與調控","meta":"106年第1次第44題","year":106,"session":1,"number":44,"question":"腦中核酸分解所形成之氨（ammonia），主要轉化為下列何種物質，再經由血液運送至肝臟或腎臟？","options":["(A) 尿酸（uric acid）","(B) 尿素（urea）","(C) 天冬醯胺（asparagine）","(D) 麩胺醯胺（glutamine）"],"answer":3,"image":""},{"id":"md2-106-1-45","subject":"md2","topic":"生化-中間代謝與調控","meta":"106年第1次第45題","year":106,"session":1,"number":45,"question":"胺甲醯麩胺酸（carbamoyl glutamate）常用於治療醋醯麩胺酸合成酶（N-acetylglutamate synthetase）缺乏所造成的尿素循環（urea cycle）障礙疾病，其藥理作用主要為何？","options":["(A) 提供尿素循環所需的中間產物，增進整個尿素循環的效率","(B) 做為胺甲醯磷酸合成酶（carbamoyl phosphate synthetase I）的異位活化劑（allosteric activator），增進尿素循環的效率","(C) 與甘胺酸（glycine）和麩胺醯胺（glutamine）結合成衍生物排出體外，減少尿素循環的負擔","(D) 促進精胺酸（arginine）的合成，防止精胺酸缺乏"],"answer":1,"image":""},{"id":"md2-106-1-46","subject":"md2","topic":"生化-蛋白質酵素醣脂維生素","meta":"106年第1次第46題","year":106,"session":1,"number":46,"question":"Cytochromes含有那種金屬離子？","options":["(A) Fe2+","(B) Mg2+","(C) Co2+","(D) Ni2+"],"answer":0,"image":""},{"id":"md2-106-1-47","subject":"md2","topic":"生化-中間代謝與調控","meta":"106年第1次第47題","year":106,"session":1,"number":47,"question":"下列那一種酵素參與克式循環（Krebs cycle，亦稱citric acid cycle或TCA cycle）的反應，是位於粒線體內膜上且直接參與電子傳遞鏈？","options":["(A) succinate dehydrogenase","(B) isocitrate dehydrogenase","(C) alpha-ketoglutarate dehydrogenase complex","(D) malate dehydrogenase"],"answer":0,"image":""},{"id":"md2-106-1-48","subject":"md2","topic":"生化-訊息傳遞荷爾蒙細胞週期","meta":"106年第1次第48題","year":106,"session":1,"number":48,"question":"蛋白激酶A（Protein kinase A）具有下列何種特性？","options":["(A) 與cyclic AMP共價鍵結合而活化","(B) 與cyclic AMP共價鍵結合而抑制","(C) cyclic AMP與酵素的異位性結合位（allosteric site）結合而使酵素活化","(D) 受到cyclic AMP的競爭性抑制"],"answer":2,"image":""},{"id":"md2-106-1-49","subject":"md2","topic":"生化-訊息傳遞荷爾蒙細胞週期","meta":"106年第1次第49題","year":106,"session":1,"number":49,"question":"有關胰島素受體（insulin receptor）訊息傳遞的敘述，下列何者正確？","options":["(A) 胰島素受體是nuclear hormone receptor","(B) 胰島素受體利用cAMP進行訊息傳遞","(C) 胰島素受體會磷酸化自己及其受質（substrate）","(D) 胰島素受體在胰島素刺激前，是一種活化的磷酸激酶"],"answer":2,"image":""},{"id":"md2-106-1-50","subject":"md2","topic":"生化-核酸與基因表現","meta":"106年第1次第50題","year":106,"session":1,"number":50,"question":"利用polymerase chain reaction（PCR）技術放大DNA，在溫度循環過程中反應溫度高達95℃之目的為何？","options":["(A) 形成單股模板（template）DNA","(B) 使primer與模板（template）結合","(C) 增加DNA polymerase活性","(D) 便於產物之純化"],"answer":0,"image":""},{"id":"md2-106-1-51","subject":"md2","topic":"藥理-總論與自主神經","meta":"106年第1次第51題","year":106,"session":1,"number":51,"question":"有關藥物的代謝敘述，下列何者錯誤？","options":["(A) 葡萄柚汁會抑制triazolam在體內代謝","(B) cimetidine會抑制propranolol在體內代謝","(C) nortriptyline會抑制antipyrine在體內代謝","(D) spironolactone會抑制digoxin在體內代謝"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第51題一律給分 (原公告答案 B)"},{"id":"md2-106-1-52","subject":"md2","topic":"藥理-化學治療","meta":"106年第1次第52題","year":106,"session":1,"number":52,"question":"有關免疫抑制劑sirolimus（rapamycin）之敘述，下列何者錯誤？","options":["(A) 可結合到FK506-binding protein","(B) 如同tacrolimus可以抑制calcineurin作用","(C) 比cyclosporine較少有腎功能損傷不良作用","(D) 抑制mTOR而抑制蛋白合成"],"answer":1,"image":""},{"id":"md2-106-1-53","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第1次第53題","year":106,"session":1,"number":53,"question":"Thiazolidinediones類降血糖藥物的主要作用機轉為何？","options":["(A) 降低胰島素抗性（insulin resistance）的產生","(B) 促進胰島素的分泌作用","(C) 抑制胰島素被肝臟代謝分解作用","(D) 抑制peroxisome proliferator-activated receptor-gamma（PPAR-γ）受體的活性"],"answer":0,"image":""},{"id":"md2-106-1-54","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"106年第1次第54題","year":106,"session":1,"number":54,"question":"Eplerenone之藥理作用敘述，何者錯誤？","options":["(A) 會促進鹽分排除","(B) 會引起男性女乳症","(C) 會使血鉀增加","(D) 會抑制aldosterone之作用"],"answer":1,"image":""},{"id":"md2-106-1-55","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"106年第1次第55題","year":106,"session":1,"number":55,"question":"下列那一類藥物可以使血管擴張（vasodilation）？","options":["(A) endothelin antagonists","(B) kinin antagonists","(C) neurotensin antagonists","(D) vasopressin agonists"],"answer":0,"image":""},{"id":"md2-106-1-56","subject":"md2","topic":"藥理-總論與自主神經","meta":"106年第1次第56題","year":106,"session":1,"number":56,"question":"下列何者不是atropine的臨床用途？","options":["(A) 治療狹角青光眼","(B) 使眼睛睫狀肌麻痺","(C) 手術時減少支氣管分泌","(D) 急性有機磷中毒之解救"],"answer":0,"image":""},{"id":"md2-106-1-57","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第1次第57題","year":106,"session":1,"number":57,"question":"下列何種non-steroidal anti-inflammatory drugs (NSAIDs)藥物，同時具有抑制cyclooxygenase和lipoxygenase的作用？","options":["(A) aspirin","(B) etodolac","(C) ketoprofen","(D) naproxen"],"answer":2,"image":""},{"id":"md2-106-1-58","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"106年第1次第58題","year":106,"session":1,"number":58,"question":"下列那一種麻醉劑，在可產生外科麻醉的濃度下，所需要的誘導時間最短？","options":["(A) nitrous oxide","(B) benzodiazepines","(C) methoxyflurane","(D) halothane"],"answer":0,"image":""},{"id":"md2-106-1-59","subject":"md2","topic":"藥理-總論與自主神經","meta":"106年第1次第59題","year":106,"session":1,"number":59,"question":"下列何種受體的訊息傳遞不是經由GTP-binding protein（G protein）？","options":["(A) muscarinic receptor","(B) glucagon receptor","(C) histamine receptor","(D) NMDA receptor"],"answer":3,"image":""},{"id":"md2-106-1-60","subject":"md2","topic":"藥理-化學治療","meta":"106年第1次第60題","year":106,"session":1,"number":60,"question":"關於tetracyclines類抗生素之敘述，下列何者正確？","options":["(A) 可結合至細菌之50S核醣體，而干擾蛋白質合成","(B) 常與制酸劑併用，以預防胃部不適","(C) 治療立克次體感染的首選藥物","(D) doxycycline口服時，易受食物干擾吸收"],"answer":2,"image":""},{"id":"md2-106-1-61","subject":"md2","topic":"藥理-化學治療","meta":"106年第1次第61題","year":106,"session":1,"number":61,"question":"下列cephalosporins中，何者可做為手術前（如頭頸部、心臟血管及胸腔、開顱手術等）預防性感染的首選藥物？","options":["(A) cefazolin","(B) cefepime","(C) ceftazidime","(D) ceftriaxone"],"answer":0,"image":""},{"id":"md2-106-1-62","subject":"md2","topic":"藥理-化學治療","meta":"106年第1次第62題","year":106,"session":1,"number":62,"question":"下列何種抗生素不是藉由抑制細菌之transpeptidase而干擾細胞壁之生成？","options":["(A) aztreonam","(B) imipenem","(C) nafcillin","(D) bacitracin"],"answer":3,"image":""},{"id":"md2-106-1-63","subject":"md2","topic":"藥理-化學治療","meta":"106年第1次第63題","year":106,"session":1,"number":63,"question":"抗癌藥合併療法ABVD治療何杰金氏淋巴瘤（Hodgkin's lymphoma），其中何者可以明顯抑制癌細胞之topoisomerase II，而產生細胞毒殺作用？","options":["(A) bleomycin","(B) doxorubicin","(C) vincristine","(D) dacarbozine"],"answer":1,"image":""},{"id":"md2-106-1-64","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第1次第64題","year":106,"session":1,"number":64,"question":"有關免疫調節劑（immunomodulators）的作用機轉，下列何者不是TNF-α抑制劑？","options":["(A) infliximab","(B) abatacept","(C) etanercept","(D) adalimumab"],"answer":1,"image":""},{"id":"md2-106-1-65","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第1次第65題","year":106,"session":1,"number":65,"question":"一位60歲婦人因心跳過快、呼吸急促和胸部疼痛而被送到急診部，最近兩天有呼吸急促、下痢、出汗及焦慮的症狀。醫生發現她兩個星期前服用的methimazole已經沒有了，血中thyroid stimulating hormone（TSH）濃度小於0.04 mIU／mL（正常值為0.4 mIU/mL～4.0 mIU/mL），確認為甲狀腺風暴。下列何者為治療甲狀腺風暴的最佳藥物？","options":["(A) epinephrine","(B) propranolol","(C) radioactive iodine","(D) amiodarone"],"answer":1,"image":""},{"id":"md2-106-1-66","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第1次第66題","year":106,"session":1,"number":66,"question":"一位患有第一型糖尿病的12歲兒童，因頭暈而被送到醫院。臨床實驗診斷有嚴重高血糖、酮酸中毒和血液pH=7.15。必須立即靜脈注射下列何者來控制酮酸中毒的症狀？","options":["(A) glyburide","(B) tolbutamide","(C) insulin glargine","(D) crystalline zinc insulin"],"answer":3,"image":""},{"id":"md2-106-1-67","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"106年第1次第67題","year":106,"session":1,"number":67,"question":"可用於治療肺高壓（pulmonary hypertension）藥物的作用機轉，不包括下列何者？","options":["(A) endothelin antagonist","(B) phosphodiesterase E5 inhibitor","(C) soluble guanylyl cyclase activator","(D) calcitonin gene-related peptide（CGRP）antagonist"],"answer":[1,3],"image":"","answer_note":"更正:第67題答Ｂ、Ｄ給分。"},{"id":"md2-106-1-68","subject":"md2","topic":"藥理-總論與自主神經","meta":"106年第1次第68題","year":106,"session":1,"number":68,"question":"下列何者不是alpha-receptor-blocking drugs之臨床用途？","options":["(A) 高血壓（hypertension）","(B) 注意力不足過動症（attention deficit hyperactivity disorder）","(C) 雷諾氏現象（Raynaud's phenomenon）","(D) 良性攝護腺肥大（benign prostatic hypertrophy）"],"answer":1,"image":""},{"id":"md2-106-1-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第1次第69題","year":106,"session":1,"number":69,"question":"下列何者需要被吸收進入胃壁細胞並堆積在其小管內之後，其代謝轉換的產物才具有不可逆地抑制H+/K+-ATPase的藥理作用？","options":["(A) metoclopramide","(B) cimetidine","(C) diphenoxylate","(D) esomeprazole"],"answer":3,"image":""},{"id":"md2-106-1-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第1次第70題","year":106,"session":1,"number":70,"question":"下列藥物中何者可以靜脈給藥，而且最常用於手術後疼痛的治療？","options":["(A) ketorolac","(B) meloxicam","(C) sumatriptan","(D) dextromethorphan"],"answer":0,"image":""},{"id":"md2-106-1-71","subject":"md2","topic":"藥理-總論與自主神經","meta":"106年第1次第71題","year":106,"session":1,"number":71,"question":"關於骨骼肌肉鬆弛劑rocuronium的藥理作用，下列何者錯誤？","options":["(A) 可以經由口服投與","(B) 為非去極化肌肉鬆弛劑（nondepolarizing neuromuscular blocking drugs）","(C) 作用可以被neostigmine拮抗","(D) 可由肝臟代謝"],"answer":0,"image":""},{"id":"md2-106-1-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"106年第1次第72題","year":106,"session":1,"number":72,"question":"關於抗癲癇藥物valproic acid作用的敘述，下列何者正確？","options":["(A) 僅可用於失神發作，對其他類型的發作沒有效果","(B) 主要作用機轉為抑制鈉離子通道，與GABA系統無關","(C) 會增加許多抗癲癇藥物如phenytoin和carbamazepine的代謝","(D) 可用於治療躁鬱症以及預防偏頭痛"],"answer":3,"image":""},{"id":"md2-106-1-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"106年第1次第73題","year":106,"session":1,"number":73,"question":"下列何種藥物可減少levodopa被周邊組織的decarboxylase代謝，降低levodopa的使用劑量及副作用？","options":["(A) carbidopa","(B) ropinirole","(C) amantadine","(D) benztropine"],"answer":0,"image":""},{"id":"md2-106-1-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"106年第1次第74題","year":106,"session":1,"number":74,"question":"思覺失調症（schizophrenia）的治療藥物有許多副作用，下列何種副作用與dopamine receptor的阻斷有關？","options":["(A) 高泌乳素血症","(B) 口乾","(C) 姿勢性低血壓","(D) 視覺模糊"],"answer":0,"image":""},{"id":"md2-106-1-75","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"106年第1次第75題","year":106,"session":1,"number":75,"question":"下列何者可能會導致低血壓、急性腸胃炎，甚至休克及代謝性酸中毒（metabolic acidosis）等中毒症狀？","options":["(A) 急性無機砷中毒（acute inorganic arsenic poisoning）","(B) 急性無機汞中毒（acute inorganic mercury intoxication）","(C) 鉈鹽中毒（thallium salts intoxication）","(D) 放射性銫中毒（radioactive cesium（137Cs）intoxication）"],"answer":0,"image":""},{"id":"md2-106-1-76","subject":"md2","topic":"藥理-總論與自主神經","meta":"106年第1次第76題","year":106,"session":1,"number":76,"question":"下列有關血清素（serotonin）的敘述，何者錯誤？","options":["(A) 是一種血管活性的介質（vasoactive mediator）","(B) 主要存在於肥大細胞（mast cells）","(C) 可存在於胃腸道的神經內分泌細胞（neuroendocrine cells）","(D) 對血管的作用與組織胺（histamine）類似"],"answer":1,"image":""},{"id":"md2-106-1-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"106年第1次第77題","year":106,"session":1,"number":77,"question":"腦梗塞後，最容易造成下列何種壞死？","options":["(A) 液化性壞死","(B) 凝固性壞死","(C) 脂肪壞死","(D) 壞疽性壞死"],"answer":0,"image":""},{"id":"md2-106-1-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"106年第1次第78題","year":106,"session":1,"number":78,"question":"下列感染症中，何者可造成肝臟纖維化的病變？ ①梅毒（syphilis） ②血吸蟲病（schistosomiasis） ③痲瘋病（leprosy）","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":0,"image":""},{"id":"md2-106-1-79","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第1次第79題","year":106,"session":1,"number":79,"question":"39歲未婚婦女，自20歲即有性經驗，且換過幾位性伴侶，身體一向健康沒有任何不適。因響應政府衛生教育宣導6分鐘護一生，接受子宮頸抹片篩檢，結果發現上皮細胞有重度異生（severe dysplasia）。下列對病人的建議及處理，何者最適當？","options":["(A) 停止性接觸，3個月後再追蹤檢查一次","(B) 接受抗生素治療後，3個月再追蹤檢查一次","(C) 接受人類乳突病毒的偵測，並接受子宮全切除","(D) 先做子宮頸錐狀切片檢查，評估病情後再決定後續治療方法"],"answer":3,"image":""},{"id":"md2-106-1-80","subject":"md2","topic":"病理-心血管血液","meta":"106年第1次第80題","year":106,"session":1,"number":80,"question":"心肌中最容易並且最先因冠狀動脈血流減少而缺氧損傷的區域是：","options":["(A) 心內膜下區（subendocardial zone）","(B) 心外膜區（epicardial zone）","(C) 心肌中層（mid-myocardial zone）","(D) 整層心壁（transmural zone）"],"answer":0,"image":""},{"id":"md2-106-1-81","subject":"md2","topic":"病理-心血管血液","meta":"106年第1次第81題","year":106,"session":1,"number":81,"question":"85歲男性被發現左心室血液外流阻力增加及同心性左心肥大，病人因此接受主動脈瓣置換，病理檢查時在手術切除的瓣膜上發現有許多小結狀鈣化結構於sinus of Valsalva中。此病人主動脈瓣在未發生病變前的解剖構造最可能是：","options":["(A) three-cuspid valve","(B) two-cuspid valve","(C) un-commissural valve","(D) fissured valve"],"answer":0,"image":""},{"id":"md2-106-1-82","subject":"md2","topic":"病理-免疫感染遺傳","meta":"106年第1次第82題","year":106,"session":1,"number":82,"question":"下列三種淋巴癌中，何者與Epstein-Barr病毒有密切關係？ ① 鼻腔NK/T細胞淋巴癌（NK/T-cell lymphoma） ② 濾泡性淋巴癌（follicular lymphoma） ③ 後天免疫不全症候群合併之原發性中樞神經系統B細胞淋巴癌（B-cell lymphoma）","options":["(A) 僅①②","(B) 僅②③","(C) 僅①③","(D) ①②③"],"answer":2,"image":""},{"id":"md2-106-1-83","subject":"md2","topic":"病理-呼吸消化","meta":"106年第1次第83題","year":106,"session":1,"number":83,"question":"下列何種肺膨脹不全（atelectasis）通常為不可逆之變化？","options":["(A) 吸收性肺膨脹不全（resorption atelectasis）","(B) 阻塞性肺膨脹不全（obstruction atelectasis）","(C) 壓迫性肺膨脹不全（compression atelectasis）","(D) 收縮性肺膨脹不全（contraction atelectasis）"],"answer":3,"image":""},{"id":"md2-106-1-84","subject":"md2","topic":"病理-呼吸消化","meta":"106年第1次第84題","year":106,"session":1,"number":84,"question":"下列有關煤工塵肺症（coal worker pneumoconiosis）的敘述，何者錯誤？","options":["(A) 簡單型煤工塵肺症可見煤斑塊（coal macule）及煤結節（coal nodule）的病理變化","(B) 複雜型煤工塵肺症可見密集之膠原和色素沉積","(C) 煤工塵肺症患者較一般人易感染結核病","(D) 煤工塵肺症患者若無吸菸則發生癌症的機率與一般人相近"],"answer":2,"image":""},{"id":"md2-106-1-85","subject":"md2","topic":"病理-呼吸消化","meta":"106年第1次第85題","year":106,"session":1,"number":85,"question":"下列有關肺泡蛋白沉積症（alveolar proteinosis）的敘述，何者錯誤？","options":["(A) 病理變化為肺泡內充滿表面活性蛋白（surfactant）","(B) 大部分患者為後天型（acquired type）","(C) 抗GM-CSF抗體為可能之病因","(D) 臨床治療以手術切除病灶為主"],"answer":3,"image":""},{"id":"md2-106-1-86","subject":"md2","topic":"病理-呼吸消化","meta":"106年第1次第86題","year":106,"session":1,"number":86,"question":"50歲男性咳血，ㄧ週後產生急性腎衰竭，血中C-ANCA檢查陰性，肺部切片顯示肺泡壞死及出血，合併血鐵質（hemosiderin）沉積。此病人最有可能患有下列何種肺部出血疾病？","options":["(A) 肺出血腎炎（Goodpasture）症候群","(B) 原因不明肺部血鐵症（idiopathic pulmonary hemosiderosis）","(C) 韋格納氏肉芽腫（Wegener granulomatosis）","(D) 腎細胞癌轉移至肺部，合併出血"],"answer":0,"image":""},{"id":"md2-106-1-87","subject":"md2","topic":"病理-呼吸消化","meta":"106年第1次第87題","year":106,"session":1,"number":87,"question":"下列那項肺臟疾病，最有可能出現嗜中性白血球滲出物？","options":["(A) 病毒性肺炎","(B) 肺氣喘","(C) 細菌性肺炎","(D) 肺癌"],"answer":2,"image":""},{"id":"md2-106-1-88","subject":"md2","topic":"病理-呼吸消化","meta":"106年第1次第88題","year":106,"session":1,"number":88,"question":"55歲女性，長期有搔癢，疲倦和腹部不適。身體檢查發現病人有黃疸，皮膚有黃色瘤（xanthoma），肝臟切片檢查發現肝內小膽管被破壞，並在門脈區發現有非乾酪性肉芽腫（noncaseating granuloma），她血清中最可能出現下列何種抗體？","options":["(A) 抗平滑肌抗體（anti-smooth muscle antibody）","(B) 抗粒線體抗體（anti-mitochondrial antibody）","(C) 抗可溶性肝抗原／肝胰抗體（anti-soluable liver antigen/liver pancreas antigen antibody）","(D) 抗肝腎微小體-1抗體（anti-liver kidney microsome-1 antibody）"],"answer":1,"image":""},{"id":"md2-106-1-89","subject":"md2","topic":"病理-呼吸消化","meta":"106年第1次第89題","year":106,"session":1,"number":89,"question":"48歲男性B型肝炎患者，腹部超音波發現一大型肝臟腫瘤，且主要肝門靜脈也有腫瘤栓塞，顯微鏡下腫瘤細胞含有膽色素，則下列敘述何者為最有可能的診斷？","options":["(A) 膽管癌","(B) 肝臟血管瘤","(C) 肝細胞癌","(D) 轉移性膽囊癌"],"answer":2,"image":""},{"id":"md2-106-1-90","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第1次第90題","year":106,"session":1,"number":90,"question":"有關腦下腺促皮質素腺瘤（corticotroph adenoma）的敘述，下列何者錯誤？","options":["(A) 在診斷時常以巨腺瘤（macroadenoma）呈現","(B) 大部分屬於嗜鹼性腺瘤（basophilic），只有少數為難染色性腺瘤（chromophobic）","(C) Periodic-acid-Schiff（PAS）染色呈陽性反應","(D) 易導致庫欣氏症候群（Cushing syndrome）"],"answer":0,"image":""},{"id":"md2-106-1-91","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第1次第91題","year":106,"session":1,"number":91,"question":"下列有關黏液浮腫（myxedema）的敘述，何者最不適當？","options":["(A) 發生於甲狀腺機能不足的成人或較大的孩童","(B) 皮膚、皮下或某些內臟貯積glycosaminoglycans及hyaluronic acid","(C) 所有病人的血清TSH均上升","(D) 所有病人的血清T4下降"],"answer":2,"image":""},{"id":"md2-106-1-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第1次第92題","year":106,"session":1,"number":92,"question":"圖示為50歲女性甲狀腺腫瘤之病理切片。下列敘述何者最不符合此腫瘤的臨床或病理特徵？","options":["(A) 細胞核常有溝狀特徵（nuclear grooving）","(B) 發生在40歲之前者預後極好","(C) 常有PAX-PPAR γ 1染色體轉位（translocation）","(D) 腫瘤細胞呈高柱狀者較具侵犯性"],"answer":2,"image":"md2-106-1-92.jpeg"},{"id":"md2-106-1-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第1次第93題","year":106,"session":1,"number":93,"question":"28歲女性，出現多毛，聲音沙啞，和經期不順等症狀，腹部超音波檢查發現一卵巢腫瘤，最可能的診斷是：","options":["(A) 顆粒細胞瘤（granulosa cell tumor）","(B) 濾泡膜細胞瘤（thecoma）","(C) 索特利－萊汀細胞瘤（Sertoli-Leydig cell tumor）","(D) 布雷納氏腫瘤（Brenner tumor）"],"answer":2,"image":""},{"id":"md2-106-1-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第1次第94題","year":106,"session":1,"number":94,"question":"關於子宮內膜增生（endometrial hyperplasia），一般認為與下列何種基因最有關？","options":["(A) PTEN","(B) BRCA1","(C) HER2","(D) BRCA2"],"answer":0,"image":""},{"id":"md2-106-1-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第1次第95題","year":106,"session":1,"number":95,"question":"有關睪丸炎（orchitis）與副睪丸炎（epididymitis）的描述，下列何者錯誤？","options":["(A) 淋病與結核病的感染常先發生於睪丸，而梅毒則常從副睪丸開始","(B) 腮腺炎的感染好發於學齡兒童，這個年齡群極少有睪丸炎的併發症發生","(C) 35歲以上的年齡群副睪丸炎以大腸桿菌與綠膿桿菌的感染為主","(D) 梅毒的感染可於顯微鏡下觀察到大量漿細胞與淋巴球的浸潤"],"answer":0,"image":""},{"id":"md2-106-1-96","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"106年第1次第96題","year":106,"session":1,"number":96,"question":"有關化膿性骨髓炎（pyogenic osteomyelitis）的敘述，下列何者錯誤？","options":["(A) 在兒童引發此病的原因可能只是黏膜的輕微受損","(B) 金黃色葡萄球菌（Staphylococcus aureus）為最常被培養出來的細菌","(C) 在兒童，典型的病灶是在長骨的幹骺端（metaphysis）","(D) 一般而言，能培養出細菌的機率為80-90 %"],"answer":3,"image":""},{"id":"md2-106-1-97","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"106年第1次第97題","year":106,"session":1,"number":97,"question":"周邊神經因創傷而橫斷所發生的變化，下列敘述何者正確？","options":["(A) 軸索（axon）被破壞，髓鞘一般仍維持完好","(B) 橫斷近端（近神經細胞體）之神經纖維發生華勒氏變性（Wallerian degeneration）","(C) 創傷性神經瘤（traumatic neuroma）是因神經再生而形成，它的成分是軸索，但不含其他支持細胞如許旺氏細胞（Schwann cell），纖維組織母細胞（fibroblasts）等","(D) 被切斷的神經之近端退化，一般只影響2-3結間節的距離"],"answer":3,"image":""},{"id":"md2-106-1-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"106年第1次第98題","year":106,"session":1,"number":98,"question":"有關弗克斯氏內皮失養症（Fuchs endothelial dystrophy）的敘述，下列何者錯誤？","options":["(A) 是角膜移植的常見原因","(B) 角膜基質水腫","(C) 水泡形角膜病變（bullous keratopathy）","(D) Guttata是角膜Bowman層不正常的物質沉著"],"answer":3,"image":""},{"id":"md2-106-1-99","subject":"md2","topic":"病理-免疫感染遺傳","meta":"106年第1次第99題","year":106,"session":1,"number":99,"question":"20歲女性，過去兩周持續性的低度發燒。病人兩側臉頰出現紅斑，口腔有一無痛性潰瘍。尿液出現紅血球圓柱（erythrocyte casts）。血液中抗細胞核抗體（antinuclear antibody）、抗雙股去氧核醣核酸抗體（anti-double stranded DNA antibody）、抗史密斯抗原（anti-Smith antigen）抗體、類風濕因子（rheumatoid factor）呈陽性反應；抗染色體中節抗體（anti- centromere antibody）、抗Scl-70抗體，抗SS-A抗體、抗SS-B抗體等則呈現陰性反應。此疾病主要的致病機轉，與引起下列何種疾病的免疫過度反應（hypersensitivity）最接近？","options":["(A) 多發性硬化症（multiple sclerosis）","(B) 急性風濕熱（acute rheumatic fever）","(C) 鏈球菌感染後腎絲球腎炎（poststreptococcal glomerulonephritis）","(D) 重症肌無力（myasthenia gravis）"],"answer":2,"image":""},{"id":"md2-106-1-100","subject":"md2","topic":"病理-免疫感染遺傳","meta":"106年第1次第100題","year":106,"session":1,"number":100,"question":"（承上題）此病人罹患的疾病是造成下列何項檢驗偽陽性的常見的原因之一？","options":["(A) 肺炎黴漿菌（Mycoplasma pneumoniae）抗體試驗","(B) 退伍軍人菌（Legionella pneumophila）抗體試驗","(C) 肺炎披衣菌（Chlamydia pneumoniae）IgG抗體試驗","(D) 梅毒血清VDRL試驗"],"answer":3,"image":""},{"id":"md2-106-2-1","subject":"md2","topic":"病毒學","meta":"106年第2次第1題","year":106,"session":2,"number":1,"question":"有關肝炎病毒中，下列何者與黃熱病毒（yellow fever virus）屬同一科？","options":["(A) Hepatitis A virus","(B) Hepatitis B virus","(C) Hepatitis C virus","(D) Hepatitis D virus"],"answer":2,"image":""},{"id":"md2-106-2-2","subject":"md2","topic":"細菌學","meta":"106年第2次第2題","year":106,"session":2,"number":2,"question":"有關炭疽桿菌（Bacillus anthracis）的敘述，下列何者錯誤？","options":["(A) 由多胜肽（polypeptide）所組成的莢膜為重要的毒力因子（virulence factor）","(B) 為毛工病（wool-sorter's disease）的致病菌","(C) 在含血液培養盤上可形成大型β-溶血菌落","(D) 炭疽毒素（anthrax toxin）的基因位於質體上"],"answer":2,"image":""},{"id":"md2-106-2-3","subject":"md2","topic":"細菌學","meta":"106年第2次第3題","year":106,"session":2,"number":3,"question":"肺結核患者的致病菌，能藉由抑制宿主細胞之早期內體自體抗原1（early endosomal autoantigen 1, EEA1），以阻止下列那一種現象的發生？","options":["(A) 溶小體（lysosome）與吞噬體（phagosome）的融合","(B) 巨噬細胞（macrophage）分泌介白質11（interleukin-11）","(C) 巨噬細胞（macrophage）內的環單磷酸腺苷（cAMP）濃度上升","(D) 丙型丁胺酸（gamma-aminobutyric acid, GABA）的釋放"],"answer":0,"image":""},{"id":"md2-106-2-4","subject":"md2","topic":"細菌學","meta":"106年第2次第4題","year":106,"session":2,"number":4,"question":"關於Q熱（Q fever）致病菌之相改變（phase transition）現象的敘述，下列何者正確？","options":["(A) 相改變是因為此菌的鞭毛（flagellum）基因發生突變所造成","(B) 當此菌處於第一相（phase I）時，其細胞壁（cell wall）不含O抗原醣（O-antigen sugars）","(C) 當此菌處於第二相（phase II）時，能抑制吞噬體（phagosome）與溶小體（lysosome）的融合","(D) 急性期時，病人體內產生的IgM及IgG抗體主要是對抗第二相的抗原"],"answer":3,"image":""},{"id":"md2-106-2-5","subject":"md2","topic":"細菌學","meta":"106年第2次第5題","year":106,"session":2,"number":5,"question":"某求診男性，經診斷患有尿道炎（urethritis）和結膜炎（conjunctivitis）。下列何者最有可能是其致病菌？","options":["(A) 埃及嗜血桿菌（Haemophilus aegyptius）","(B) 立氏立克次體（Rickettsia rickettsii）","(C) 人類黴漿菌（Mycoplasma hominis）","(D) 砂眼披衣菌（Chlamydia trachomatis）"],"answer":3,"image":""},{"id":"md2-106-2-6","subject":"md2","topic":"藥理-化學治療","meta":"106年第2次第6題","year":106,"session":2,"number":6,"question":"下列那一種抗生素，適合用來治療嗜肺性退伍軍人菌（Legionella pneumophila）所引起的肺炎？","options":["(A) 克林達黴素（clindamycin）","(B) 阿奇黴素（azithromycin）","(C) 安比西林（ampicillin）","(D) 兩性黴素B（amphotericin B）"],"answer":[0,1],"image":"","answer_note":"更正:第6題答Ａ、Ｂ給分"},{"id":"md2-106-2-7","subject":"md2","topic":"細菌學","meta":"106年第2次第7題","year":106,"session":2,"number":7,"question":"關於致病菌與疾病的配對，下列何者錯誤？","options":["(A) 肺炎克雷白氏桿菌（Klebsiella pneumoniae）– 肝膿瘍（liver abscess）","(B) 創傷弧菌（Vibrio vulnificus）– 敗血症（septicemia）","(C) 空腸彎曲桿菌（Campylobacter jejuni）– 腸胃炎（gastroenteritis）","(D) 鼠疫桿菌（Yersinia pestis）–萊姆病（Lyme disease）"],"answer":3,"image":""},{"id":"md2-106-2-8","subject":"md2","topic":"細菌學","meta":"106年第2次第8題","year":106,"session":2,"number":8,"question":"下列何者最不常用在以細菌來進行的基因工程技術中？","options":["(A) DNA gyrase","(B) Restriction enzyme","(C) DNA ligase","(D) Cloning vector"],"answer":0,"image":""},{"id":"md2-106-2-9","subject":"md2","topic":"病毒學","meta":"106年第2次第9題","year":106,"session":2,"number":9,"question":"下列那一種造成呼吸道感染的病毒，可不經由反轉錄作用（reverse transcription），而直接以polymerase chain reaction（PCR）檢測？","options":["(A) 腺病毒（adenovirus）","(B) A型流感病毒（influenza A virus）","(C) 中東呼吸症候群冠狀病毒（MERS-CoV）","(D) 呼吸道細胞融合病毒（respiratory syncytial virus）"],"answer":0,"image":""},{"id":"md2-106-2-10","subject":"md2","topic":"病毒學","meta":"106年第2次第10題","year":106,"session":2,"number":10,"question":"有關人類乳突瘤病毒（Human Papillomavirus, HPV）的敘述，下列何者錯誤？","options":["(A) HPV-6和HPV-11是引起子宮頸癌的低危險病毒株","(B) E5病毒蛋白質會與p53結合","(C) E7病毒蛋白質會與p105RB蛋白質結合","(D) E1蛋白質與病毒的複製有關"],"answer":1,"image":""},{"id":"md2-106-2-11","subject":"md2","topic":"病毒學","meta":"106年第2次第11題","year":106,"session":2,"number":11,"question":"下列何種病毒，通常不經過垂直感染傳給胎兒？","options":["(A) 德國麻疹病毒（Rubella virus）","(B) 巨細胞病毒（Cytomegalovirus）","(C) 呼腸病毒（Reovirus）","(D) 單純疱疹病毒（Herpes simplex virus）"],"answer":2,"image":""},{"id":"md2-106-2-12","subject":"md2","topic":"病毒學","meta":"106年第2次第12題","year":106,"session":2,"number":12,"question":"下列何種病毒複製時，會在細胞質產生一種稱為內基氏小體（Negri body）的包涵體？","options":["(A) 天花病毒（variola virus）","(B) 狂犬病病毒（rabies virus）","(C) 人類巨細胞病毒（human cytomegalovirus）","(D) 水痘–帶狀疱疹病毒（varicella-zoster virus）"],"answer":1,"image":""},{"id":"md2-106-2-13","subject":"md2","topic":"病毒學","meta":"106年第2次第13題","year":106,"session":2,"number":13,"question":"人類腺病毒（adenovirus）與下列何種病毒使用相同的細胞受器（receptor）？","options":["(A) B型克沙奇病毒（Coxsackie B virus）","(B) 諾羅病毒（Norovirus）","(C) 巨細胞病毒（Cytomegalovirus）","(D) 流感病毒（Influenza virus）"],"answer":0,"image":""},{"id":"md2-106-2-14","subject":"md2","topic":"真菌學","meta":"106年第2次第14題","year":106,"session":2,"number":14,"question":"下列那種黴菌會引起全身性感染，且其酵母菌型常呈現舵輪（mariner's wheel）樣之多重出芽生殖?","options":["(A) 粗球黴菌（Coccidioides immitis）","(B) 巴西副球黴菌（Paracoccidioides brasiliensis）","(C) 莢膜組織胞漿菌（Histoplasma capsulatum）","(D) 皮炎芽生菌（Blastomyces dermatitidis）"],"answer":1,"image":""},{"id":"md2-106-2-15","subject":"md2","topic":"真菌學","meta":"106年第2次第15題","year":106,"session":2,"number":15,"question":"下列何者為具厚壁球形體（spherules）以及關節孢子（arthroconidia）之真菌？","options":["(A) 鬚髮癬菌（Trichophyton mentagrophytes）","(B) 申克孢子絲菌（Sporothrix schenckii）","(C) 莢膜組織胞漿菌（Histoplasma capsulatum）","(D) 粗球孢子菌（Coccidioides immitis）"],"answer":3,"image":""},{"id":"md2-106-2-16","subject":"md2","topic":"細菌學","meta":"106年第2次第16題","year":106,"session":2,"number":16,"question":"3歲男童，因為咽喉疼痛伴隨吞嚥與呼吸困難送至急診室，經醫師檢查，發現他在每次吸氣時都出現明顯阻塞的聲音，側頸X光（lateral neck x-ray）報告顯示會厭軟骨腫脹（swollen epiglottis），此最有可能是下列何種細菌感染所造成？","options":["(A) b型流感嗜血桿菌（Haemophilus influenzae type b）","(B) 無乳鏈球菌（Streptococcus agalactiae）","(C) 奈瑟氏腦膜炎球菌（Neisseria meningitidis）","(D) 單核球增多性李斯特菌（Listeria monocytogenes）"],"answer":0,"image":""},{"id":"md2-106-2-17","subject":"md2","topic":"細菌學","meta":"106年第2次第17題","year":106,"session":2,"number":17,"question":"承上題，下列何者為該細菌最重要的致病因子（virulence factor）？","options":["(A) 細菌表面的線毛（pili）","(B) 細菌表面的多醣體莢膜（polysaccharide capsule）","(C) 細胞毒素（cytotoxin）","(D) 細胞壁的胜肽聚醣（peptidoglycan）"],"answer":1,"image":""},{"id":"md2-106-2-18","subject":"md2","topic":"免疫學","meta":"106年第2次第18題","year":106,"session":2,"number":18,"question":"下列何種產物具有調理作用（opsonization），可增強macrophage、neutrophils的吞噬作用？","options":["(A) Interferon","(B) IL-1","(C) TNF-α","(D) complement"],"answer":3,"image":""},{"id":"md2-106-2-19","subject":"md2","topic":"免疫學","meta":"106年第2次第19題","year":106,"session":2,"number":19,"question":"成熟的B細胞可以同時表現IgD與IgM兩種免疫球蛋白於細胞表面上，其主要的分子機制為何？","options":["(A) RNA多樣裁接（alternative splicing）","(B) 對偶基因排除（allelic exclusion）","(C) V(D)J片段重組（recombination）","(D) 基因轉換（gene conversion）"],"answer":0,"image":""},{"id":"md2-106-2-20","subject":"md2","topic":"免疫學","meta":"106年第2次第20題","year":106,"session":2,"number":20,"question":"B細胞被抗原刺激後，細胞膜上之免疫球蛋白可轉變成分泌型抗體，其機制為何？","options":["(A) DNA重組（DNA recombination）","(B) RNA剪接（RNA splicing）","(C) 蛋白分解酶（protease）切割","(D) 蛋白激酶（protein kinase）修飾"],"answer":1,"image":""},{"id":"md2-106-2-21","subject":"md2","topic":"免疫學","meta":"106年第2次第21題","year":106,"session":2,"number":21,"question":"有關細胞激素的功能，下列敘述何者錯誤？","options":["(A) 調節性T細胞（regulatory T cell）可以分泌TGF-β來抑制效應性T細胞（effector T cell）之功能","(B) + IL-6與TGF-β可以幫助CD4T細胞分化變成第十七型輔助性T細胞（T17）H","(C) IL-17主要的功能為吸引嗜酸性白血球","(D) IL-4與IL-5主要由第二型輔助性T細胞（T2）分泌而來，可以一起幫助B細胞產生IgE抗體H"],"answer":2,"image":""},{"id":"md2-106-2-22","subject":"md2","topic":"免疫學","meta":"106年第2次第22題","year":106,"session":2,"number":22,"question":"人類與小鼠的腸道中，寄生有上千種的共生菌，但是正常個體並不會對這些共生菌產生免疫反應，下列敘述何者錯誤？","options":["(A) 共生菌不像致病菌會利用毒性因子，破壞上皮細胞或是引起發炎細胞激素之分泌","(B) 與共生菌存在的上皮細胞會分泌TGF-β等細胞激素","(C) 腸道的免疫系統主要會產生IgA與共生菌結合，而後引起補體的活化清除共生菌","(D) 腸道的上皮細胞在接觸共生菌的表面，並不會表現Toll-like receptors及CD14，因此較不易產生發炎反應"],"answer":[2,3],"image":"","answer_note":"更正:第22題答Ｃ、Ｄ給分"},{"id":"md2-106-2-23","subject":"md2","topic":"免疫學","meta":"106年第2次第23題","year":106,"session":2,"number":23,"question":"最近新上市一種抗氣喘藥物，您發現氣喘病人治療幾個月後，不僅相關臨床症狀消失，檢測血液中抗原特異 + 性IgE抗體效價也降低，而且也偵測不到抗原特異性CD4T細胞分泌的IL-4、IL-5及IL-13，這種抗氣喘藥物可能具有調節免疫反應的功能，下列那種細胞最不可能與這種治療效果有關？","options":["(A) 第一型輔助性T細胞（T1）H","(B) T1細胞R","(C) 第十七型輔助性T細胞（T17）H","(D) + + CD4CD25T細胞"],"answer":[0,2],"image":"","answer_note":"更正:第23題答Ａ、Ｃ給分"},{"id":"md2-106-2-24","subject":"md2","topic":"免疫學","meta":"106年第2次第24題","year":106,"session":2,"number":24,"question":"最常導致超高IgE症候群（hyper IgE syndrome）的基因突變是位在下列那一個基因？","options":["(A) STAT1","(B) JAK1","(C) NEMO","(D) STAT3"],"answer":3,"image":""},{"id":"md2-106-2-25","subject":"md2","topic":"免疫學","meta":"106年第2次第25題","year":106,"session":2,"number":25,"question":"小玉每年在晚秋時常發作氣喘，醫師建議進行抽血來檢測過敏原，主要是檢查血清中對過敏原具特異性之何種抗體？","options":["(A) IgM","(B) IgG","(C) IgE","(D) IgA"],"answer":2,"image":""},{"id":"md2-106-2-26","subject":"md2","topic":"免疫學","meta":"106年第2次第26題","year":106,"session":2,"number":26,"question":"對抗細胞表面受體（cell surface receptors）的抗體，能夠引起器官破壞的自體免疫病，例如抗乙醯膽鹼受體抗體（anti-acetylcholine receptor antibody）能夠引起下列那一種疾病？","options":["(A) 重症肌無力（myasthenia gravis）","(B) 尋常天疱瘡（pemphigus vulgaris）","(C) 多發性硬化症（multiple sclerosis）","(D) 紅斑性狼瘡（systemic lupus erythematosus）"],"answer":0,"image":""},{"id":"md2-106-2-27","subject":"md2","topic":"免疫學","meta":"106年第2次第27題","year":106,"session":2,"number":27,"question":"下列那一項敘述與腫瘤細胞逃避免疫系統監測無關？","options":["(A) 抗體導致腫瘤細胞表面抗原的內吞（endocytosis）作用","(B) 腫瘤細胞促進調節性T細胞（regulatory T cells）的浸潤","(C) 腫瘤細胞分泌TGF-β細胞激素","(D) 腫瘤細胞會活化抗原呈現細胞（antigen-presenting cell），並促進其co-stimulatory signals的大量表現"],"answer":3,"image":""},{"id":"md2-106-2-28","subject":"md2","topic":"免疫學","meta":"106年第2次第28題","year":106,"session":2,"number":28,"question":"豬心移植於靈長類動物將發生超急性排斥（hyperacute rejection），此現象可以透過基因轉殖下列何種人類基因而減緩？","options":["(A) 免疫球蛋白-G（immunoglobulin-G）","(B) 補體（complement）","(C) CD（clusters of differentiation）52","(D) CD（clusters of differentiation）59"],"answer":3,"image":""},{"id":"md2-106-2-29","subject":"md2","topic":"寄生蟲學","meta":"106年第2次第29題","year":106,"session":2,"number":29,"question":"班氏絲蟲（Wuchereria bancrofti）之患者服用下列何種藥物有助於白天採血檢查微絲蟲（microfilaria）？","options":["(A) albendazole","(B) diethylcarbamazine","(C) praziquantel","(D) metronidazole"],"answer":1,"image":""},{"id":"md2-106-2-30","subject":"md2","topic":"寄生蟲學","meta":"106年第2次第30題","year":106,"session":2,"number":30,"question":"下列何種人體寄生蟲可因入侵生殖系統進入腹腔（peritoneal cavity）而導致慢性骨盆腔腹膜炎（chronic pelvic peritonitis）？","options":["(A) 蟯蟲（Enterobius vermicularis）","(B) 鞭蟲（Trichuris trichiura）","(C) 旋毛蟲（Trichinella spiralis）","(D) 蛔蟲（Ascaris lumbricoides）"],"answer":0,"image":""},{"id":"md2-106-2-31","subject":"md2","topic":"寄生蟲學","meta":"106年第2次第31題","year":106,"session":2,"number":31,"question":"衛氏肺吸蟲（Paragonimus westermani）的感染途徑為：","options":["(A) 生食含囊狀幼蟲（metacercaria）的淡水魚","(B) 生食含囊狀幼蟲（metacercaria）的水生植物","(C) 生食含囊狀幼蟲（metacercaria）的淡水螃蟹","(D) 由尾動幼蟲（cercaria）鑽入皮膚感染"],"answer":2,"image":""},{"id":"md2-106-2-32","subject":"md2","topic":"寄生蟲學","meta":"106年第2次第32題","year":106,"session":2,"number":32,"question":"李姓學童日前於居家附近池塘游泳返家後，陸續出現發燒、頭痛、鼻塞及嗅覺失常等症狀，經住院檢查發現白血球高達24,000/cmm（>90%為嗜中性白血球）、頸部僵硬及凱尼格氏徵象（Kernig’s sign），並於住院五天後死亡。依據上述結果，李姓學童最可能感染何種寄生蟲？","options":["(A) 福氏內格里阿米巴（Naegleria fowleri）","(B) 痢疾阿米巴（Entamoeba histolytica）","(C) 棘阿米巴（Acanthamoeba spp.）","(D) 大腸阿米巴（Entamoeba coli）"],"answer":0,"image":""},{"id":"md2-106-2-33","subject":"md2","topic":"寄生蟲學","meta":"106年第2次第33題","year":106,"session":2,"number":33,"question":"陳先生到印度鄉野自助旅行數月，回來後出現腹瀉、發燒、貧血等症狀，之後並出現肝脾腫大（hepatosplenomegaly）現象，骨髓穿刺在其巨噬細胞中發現無鞭毛體（amastigotes），血液及糞便檢查沒有其他發現，他最可能感染的寄生蟲病是：","options":["(A) 黑水熱（blackwater fever）","(B) 黑熱病（black fever）","(C) 絲蟲症（filariasis）","(D) 卡格氏症（Chagas’disease）"],"answer":1,"image":""},{"id":"md2-106-2-34","subject":"md2","topic":"寄生蟲學","meta":"106年第2次第34題","year":106,"session":2,"number":34,"question":"下列有關痢疾阿米巴（Entamoeba histolytica）的敘述中，何者正確？","options":["(A) 阿米巴肝膿瘍（amebic liver abscess）常發生在左葉肝臟","(B) 在膿瘍的中央採檢體，檢出其滋養體（trophozoites）的機會比較大","(C) 阿米巴肝膿瘍（amebic liver abscess）的第一線用藥為mebendazole","(D) 阿米巴腫（ameboma）常易被誤診為惡性腫瘤"],"answer":3,"image":""},{"id":"md2-106-2-35","subject":"md2","topic":"寄生蟲學","meta":"106年第2次第35題","year":106,"session":2,"number":35,"question":"下列何種節肢動物，主要以機械性傳播（mechanical transmission）方式媒介病原體？","options":["(A) 蚊（mosquito）","(B) 家蠅（house fly）","(C) 跳蚤（flea）","(D) 體蝨（body louse）"],"answer":1,"image":""},{"id":"md2-106-2-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"106年第2次第36題","year":106,"session":2,"number":36,"question":"為研究大腸癌病人術前準備情況與術後併發症的關係，某研究收集6位術前準備情況較好之大腸癌病人與4位術前準備情況較差者，術後兩組發生倂發症的人數分別為1位與3位。下列何種統計方法最恰當？","options":["(A) 費雪恰當檢定（Fisher’s exact test）","(B) 獨立樣本t檢定（Independent sample t-test）","(C) 卡方檢定（Chi-square test）","(D) McNemar檢定(McNemar test)"],"answer":0,"image":""},{"id":"md2-106-2-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"106年第2次第37題","year":106,"session":2,"number":37,"question":"某研究者想檢定新藥是否有降血壓效果，對20隻大鼠在餵食新藥前後分別測量血壓值，對於兩次血壓測量值的比較，下列統計分析方法何者最恰當？","options":["(A) 線性迴歸（Linear regression）","(B) 獨立樣本t檢定（Independent sample t-test）","(C) 配對t檢定（Paired t-test）","(D) 列聯表分析（Contingency table）"],"answer":2,"image":""},{"id":"md2-106-2-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"106年第2次第38題","year":106,"session":2,"number":38,"question":"測量一群兒童的血中鉛濃度（blood lead level, 單位µg/dl）與尿中古丁尼濃度（cotinine level, 單位ng/ml）的資料，今欲比較血中鉛濃度與尿中古丁尼濃度何者變異較大，下列何種統計量最合適？","options":["(A) 標準差（standard deviation）","(B) 變異數（variance）","(C) 變異係數（coefficient of variation）","(D) 全距（range）"],"answer":2,"image":""},{"id":"md2-106-2-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"106年第2次第39題","year":106,"session":2,"number":39,"question":"一個臨床試驗評估密集運動計畫擬探討初次發病存活至少30天的心肌梗塞病人的有效性，初次發病存活至少30天的心肌梗塞病人被隨機分配至密集運動計畫或一般照護（usual care）。在100名一般照護的病人中，30名病人在三年的追蹤期間死亡；在100名密集運動計畫的病人中，50名病人在三年的追蹤期間死亡。密集運動計畫組相較於一般照護組的死亡相對危險性（relative risk of death）為何？","options":["(A) 0.60","(B) 0.03","(C) 0.50","(D) 1.67"],"answer":3,"image":""},{"id":"md2-106-2-40","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"106年第2次第40題","year":106,"session":2,"number":40,"question":"有一臨床研究，預計二年內收集200名病例及200名對照，進行某生長激素研究，醫師甲提議每收集一個病例即開具檢驗單，由檢驗室測量血中該生長激素的量；醫師乙提議先冷凍貯存病人血液樣本，再由檢驗室根據其日處理80個檢體的能量，於5個工作日全數測量完畢。下列何者正確？","options":["(A) 醫師甲的計畫較容易出現選擇偏差","(B) 醫師乙的計畫較容易出現選擇偏差","(C) 醫師甲的計畫較容易出現測量誤差","(D) 醫師乙的計畫較容易出現測量誤差"],"answer":2,"image":""},{"id":"md2-106-2-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"106年第2次第41題","year":106,"session":2,"number":41,"question":"何種水中污染物會造成幼兒「藍嬰症」（methemoglobenemia）問題？","options":["(A) 硫酸鹽","(B) 硝酸鹽","(C) 磷酸鹽","(D) 碳酸鹽"],"answer":1,"image":""},{"id":"md2-106-2-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"106年第2次第42題","year":106,"session":2,"number":42,"question":"下列何者屬於非游離輻射？","options":["(A) 宇宙射線","(B) X光射線（X ray）","(C) 迦馬射線（Gamma ray）","(D) 紅外線（infrared radiation）"],"answer":3,"image":""},{"id":"md2-106-2-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"106年第2次第43題","year":106,"session":2,"number":43,"question":"下列何者不屬於廢棄物之物理處理？","options":["(A) 離子交換","(B) 過濾","(C) 浮除","(D) 磁性分離"],"answer":0,"image":""},{"id":"md2-106-2-44","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"106年第2次第44題","year":106,"session":2,"number":44,"question":"我國法ࡘ規定所稱之「日時߉平均容許່Ä濃ล」係指工作多少小時之平均容許່Ä濃ล？","options":["(A) 最高15分鐘","(B) 每日4小時","(C) 每日8小時","(D) 每週40小時"],"answer":2,"image":""},{"id":"md2-106-2-45","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"106年第2次第45題","year":106,"session":2,"number":45,"question":"工人的白指病是由於下列何種工作或暴露所引起的？","options":["(A) 振動工作","(B) 苯作業","(C) 甲苯作業","(D) 微波作業"],"answer":0,"image":""},{"id":"md2-106-2-46","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"106年第2次第46題","year":106,"session":2,"number":46,"question":"在一個以預防吸菸為主題的健康教育活動中，老師運用價值澄清、影片欣賞、角色扮演等不同的教學方法幫助學生熟習「拒絕的技巧」，日後學生遇到類似如別人勸酒或邀約吸毒的情境時，可以運用學會的拒絕技巧，是應用下列何種行為改變的技術？","options":["(A) 互相抵制原理","(B) 逐減敏感原理","(C) 類化原理","(D) 增強原理"],"answer":2,"image":""},{"id":"md2-106-2-47","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"106年第2次第47題","year":106,"session":2,"number":47,"question":"下列那一項不是世界衛生組織頒布的渥太華健康促進宣言所強調的策略？","options":["(A) 建立支持性的環境","(B) 推動社區健康行動","(C) 擬定健康政策","(D) 重視醫療技能"],"answer":3,"image":""},{"id":"md2-106-2-48","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"106年第2次第48題","year":106,"session":2,"number":48,"question":"利用Precede-Proceed模式研擬病人高血壓衛生教育計畫時，評估病人對高血壓的認知、態度，是屬於下列何者因素評估？","options":["(A) 前傾因素（predisposing factor）","(B) 增強因素（reinforcing factor）","(C) 使能因素（enabling factor）","(D) 教育因素（educational factor）"],"answer":0,"image":""},{"id":"md2-106-2-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"106年第2次第49題","year":106,"session":2,"number":49,"question":"關於臺灣全民健康保險對醫療服務供給影響的敘述，下列何者錯誤？","options":["(A) 規劃初期即確立保險的本質是社會性與商業性並重","(B) 目前逐步推動以診斷關係群（diagnosis-related group, DRG）為依據的住院服務論病例計酬支付基準","(C) 醫療服務供給者在保險未介入前，有優勢主導病人的醫療利用","(D) 總額預算制是全民健保控制醫療支出成長的策略之一"],"answer":0,"image":""},{"id":"md2-106-2-50","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"106年第2次第50題","year":106,"session":2,"number":50,"question":"有關成本效用分析（cost-utility analysis），下列敘述何者較不正確？","options":["(A) 常以健康人年（quality-adjusted life year，簡寫為QALY）來測量病人治療的結果","(B) 屬於成本效益分析法（cost-effectiveness analysis）的一種特殊類型","(C) 以金錢價值衡量醫療之產出","(D) 醫學及公共衛生用來評估治療成效的方法之一"],"answer":2,"image":""},{"id":"md2-106-2-51","subject":"md2","topic":"藥理-化學治療","meta":"106年第2次第51題","year":106,"session":2,"number":51,"question":"關於抗病毒藥物acyclovir之敘述，下列何者正確？","options":["(A) 為adenosine衍生物","(B) 須被宿主細胞之thymidine kinase加入第一個磷酸根後才易被活化產生藥效","(C) 只會作用於被病毒感染細胞，不會影響其他正常細胞","(D) 用於治療人類免疫缺乏病毒（human immunodeficiency virus）感染所引起之疾病"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第51題一律給分 (原公告答案 C)"},{"id":"md2-106-2-52","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"106年第2次第52題","year":106,"session":2,"number":52,"question":"有關高分子量之unfractionated heparin（UFH）與低分子量LMW heparin之敘述，下列何者錯誤？","options":["(A) 兩者皆可預防和治療肺栓塞","(B) UFH可有效中和factor Xa和thrombin，但LMW heparin對thrombin有較高之中和能力","(C) LMW heparin較少引發thrombocytopenia現象","(D) 臨床上LMW heparin之劑量較好控制"],"answer":1,"image":""},{"id":"md2-106-2-53","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第2次第53題","year":106,"session":2,"number":53,"question":"下列何者為抗甲狀腺機能亢進藥物perchlorate主要的作用機轉？","options":["(A) 阻斷甲狀腺攝取碘離子（thyroidal uptake of iodide）的作用","(B) 抑制甲狀腺過氧化物酶催化反應（thyroid peroxidase-catalytic reaction）","(C) 其促進周邊將triiodothyronine（T）及tetraiodothyronine（T）進行脫碘化作用（deiodination）34","(D) 其具有抑制碘有機化（iodine organification）及減少triiodothyronine（T）及tetraiodothyronine（T）釋放34的作用"],"answer":0,"image":""},{"id":"md2-106-2-54","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"106年第2次第54題","year":106,"session":2,"number":54,"question":"肝硬化引起的水腫對下列何種藥物之反應最佳？","options":["(A) mannitol","(B) eplerenone","(C) bumetanide","(D) thiazide"],"answer":1,"image":""},{"id":"md2-106-2-55","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"106年第2次第55題","year":106,"session":2,"number":55,"question":"下列那一種利尿劑最適用於急性肺水腫病人？","options":["(A) thiazide","(B) ethacrynic acid","(C) acetazolamide","(D) spironolactone"],"answer":1,"image":""},{"id":"md2-106-2-56","subject":"md2","topic":"藥理-總論與自主神經","meta":"106年第2次第56題","year":106,"session":2,"number":56,"question":"過量neostigmine中毒，不會產生下列何種作用？","options":["(A) 腹瀉","(B) 流汗","(C) 散瞳","(D) 排尿"],"answer":2,"image":""},{"id":"md2-106-2-57","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第2次第57題","year":106,"session":2,"number":57,"question":"下列何者不是治療氣喘的藥物？","options":["(A) cromolyn","(B) propranolol","(C) zileuton","(D) beclomethasone"],"answer":1,"image":""},{"id":"md2-106-2-58","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"106年第2次第58題","year":106,"session":2,"number":58,"question":"有關中樞神經興奮劑cocaine的敘述，下列何者錯誤？","options":["(A) 具局部麻醉及血管收縮作用","(B) 與海洛因（heroin）會產生交互依賴（cross dependence）的作用","(C) 具有阻斷多巴胺（dopamine）再回收系統作用，因此會增加腦中局部多巴胺濃度","(D) 具有降低食慾的作用"],"answer":1,"image":""},{"id":"md2-106-2-59","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"106年第2次第59題","year":106,"session":2,"number":59,"question":"下列那一種鎮靜安眠藥物不會產生具有生物活性的代謝產物？","options":["(A) flurazepam","(B) diazepam","(C) lorazepam","(D) chlordiazepoxide"],"answer":2,"image":""},{"id":"md2-106-2-60","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"106年第2次第60題","year":106,"session":2,"number":60,"question":"下列那一種鎮靜安眠藥物的半衰期最短？","options":["(A) alprazolam","(B) triazolam","(C) quazepam","(D) diazepam"],"answer":1,"image":""},{"id":"md2-106-2-61","subject":"md2","topic":"藥理-總論與自主神經","meta":"106年第2次第61題","year":106,"session":2,"number":61,"question":"有關藥物作用活性的敘述，下列何者正確？","options":["(A) efficacy越大的藥物其potency也越大","(B) 若10 mg藥物A與100 mg藥物B的作用程度相同時，藥物A的therapeutic index較藥物B大","(C) 作用在同一受體的藥物會因受體組織分布的不同而產生不同的療效與毒性","(D) spare receptor是藥物產生毒性的主要原因"],"answer":2,"image":""},{"id":"md2-106-2-62","subject":"md2","topic":"藥理-總論與自主神經","meta":"106年第2次第62題","year":106,"session":2,"number":62,"question":"有關藥物動力學的敘述，下列何者正確？","options":["(A) 鹼性藥物較酸性藥物，易由胃部吸收","(B) 在血液中鹼性藥物較酸性藥物，易與白蛋白結合","(C) 鹼性藥物較酸性藥物，易由乳汁排出","(D) 由腎臟排出時，鹼性藥物較酸性藥物，易由腎小管再吸收回到血液中"],"answer":2,"image":""},{"id":"md2-106-2-63","subject":"md2","topic":"藥理-化學治療","meta":"106年第2次第63題","year":106,"session":2,"number":63,"question":"下列抗生素中何者之脂溶性最大，最容易通過血腦屏障（blood brain barrier）進入中樞神經以治療腦膜炎？","options":["(A) cefazolin","(B) erythromycin","(C) gentamicin","(D) rifampin"],"answer":3,"image":""},{"id":"md2-106-2-64","subject":"md2","topic":"藥理-化學治療","meta":"106年第2次第64題","year":106,"session":2,"number":64,"question":"Vancomycin為methicillin-resistant staphylococcal infection（MRSI）之首選用藥，制菌機轉與下列何者有關，進而抑制細菌之細胞壁生成？","options":["(A) 抑制細菌之transpeptidase","(B) 和細菌細胞壁成分胜肽醣酐鍊（peptidoglycan）上之D-alanin-D-alanin（D-Ala-D-Ala）緊密結合","(C) 抑制合成細胞壁所需原料D-Ala之生成","(D) 抑制細胞膜上脂溶性載體bactoprenol之去磷酸化作用"],"answer":1,"image":""},{"id":"md2-106-2-65","subject":"md2","topic":"藥理-化學治療","meta":"106年第2次第65題","year":106,"session":2,"number":65,"question":"下列抗癌藥物中，何者可以和血管內皮生長因子A（vascular endothelial growth factor-A）結合，而抑制腫瘤之血管新生（angiogenesis），達到抗癌作用？","options":["(A) bevacizumab","(B) cetuximab","(C) panitumumab","(D) trastuzumab"],"answer":0,"image":""},{"id":"md2-106-2-66","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"106年第2次第66題","year":106,"session":2,"number":66,"question":"下列何者經由抑制vitamin K epoxide reductase，而減少凝血因子製造？","options":["(A) heparin","(B) warfarin","(C) tPA（tissue plasminogen activator）","(D) melagartran"],"answer":1,"image":""},{"id":"md2-106-2-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第2次第67題","year":106,"session":2,"number":67,"question":"一位患結節性甲狀腺腫瘤的老伯，已經安排要做甲狀腺切除手術。在手術前兩星期服用下列何者，可以減少甲狀腺的血管分布？","options":["(A) radioactive iodine","(B) levothyroxine","(C) iodides","(D) liothyroine"],"answer":2,"image":""},{"id":"md2-106-2-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第2次第68題","year":106,"session":2,"number":68,"question":"下列何者常被加入鈣離子補充劑和牛奶中，預防兒童佝僂症及成年人骨軟化症？","options":["(A) calcitriol","(B) cholecalciferol","(C) gallium nitrate","(D) sevelamer"],"answer":1,"image":""},{"id":"md2-106-2-69","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"106年第2次第69題","year":106,"session":2,"number":69,"question":"Ranolazine為一新穎抗心絞痛藥物，其作用機轉為何？","options":["(A) + 抑制late component of the Na current","(B) + 活化rapid component of the delayed rectifier K current","(C) nitric oxide donor","(D) alpha-1 adrenergic receptor blocker"],"answer":0,"image":""},{"id":"md2-106-2-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第2次第70題","year":106,"session":2,"number":70,"question":"下列何種藥物屬於長效型β-adrenergic agonist，不得用於急性氣喘發作？2","options":["(A) salbutamol","(B) salmeterol","(C) terbutaline","(D) metaproterenol"],"answer":1,"image":""},{"id":"md2-106-2-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"106年第2次第71題","year":106,"session":2,"number":71,"question":"當偏頭痛（migraine）患者出現輕微到中度的頭痛症狀時，下列何者可以作為第一線的治療藥物？","options":["(A) acetaminophen","(B) allopurinol","(C) celecoxib","(D) naproxen"],"answer":[0,3],"image":"","answer_note":"更正:第71題答Ａ、Ｄ給分"},{"id":"md2-106-2-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"106年第2次第72題","year":106,"session":2,"number":72,"question":"下列那一個神經—肌肉阻斷劑，在治療劑量下作用時間（duration of action）最短？","options":["(A) succinylcholine","(B) cisatracurium","(C) pancuronium","(D) vecuronium"],"answer":0,"image":""},{"id":"md2-106-2-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"106年第2次第73題","year":106,"session":2,"number":73,"question":"下列那一個抗憂鬱藥物抑制serotonin和norepinephrine的再回收，較沒有抗膽鹼（anticholinergic）以及α腎上腺素阻斷（α-adrenergic blocking）的副作用？","options":["(A) amitriptyline","(B) venlafaxine","(C) fluoxetine","(D) selegiline"],"answer":1,"image":""},{"id":"md2-106-2-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"106年第2次第74題","year":106,"session":2,"number":74,"question":"下列吸入性麻醉劑中，何者的最小肺泡濃度（minimal alveolar concentration; MAC）數值最大？","options":["(A) sevoflurane","(B) nitrous oxide","(C) halothane","(D) desflurane"],"answer":1,"image":""},{"id":"md2-106-2-75","subject":"md2","topic":"藥理-總論與自主神經","meta":"106年第2次第75題","year":106,"session":2,"number":75,"question":"Dimercaprol（又稱British anti-lewisite, BAL）可用來治療急性有機或無機砷中毒的機轉，不包括下列何者：","options":["(A) 避免砷抑制sulfhydryl-containing enzymes","(B) 逆轉被砷所抑制的sulfhydryl-containing enzymes","(C) 增加砷的排出速率","(D) 還原砷成無毒性代謝物"],"answer":3,"image":""},{"id":"md2-106-2-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"106年第2次第76題","year":106,"session":2,"number":76,"question":"血管擴張、水腫、纖維蛋白（fibrin）出現，是下列何項之特徵？","options":["(A) 急性發炎","(B) 慢性發炎","(C) 乾性壞疽","(D) 肉芽腫性發炎"],"answer":0,"image":""},{"id":"md2-106-2-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"106年第2次第77題","year":106,"session":2,"number":77,"question":"細胞缺氧時，最不可能出現下列何種變化？","options":["(A) 鈉和水進入細胞","(B) 細胞內pH值下降","(C) 鈣離子由細胞內流出","(D) 細胞內ATP下降"],"answer":2,"image":""},{"id":"md2-106-2-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"106年第2次第78題","year":106,"session":2,"number":78,"question":"下列何者是組織結構蛋白（structural proteins）缺損引起的遺傳性疾病？","options":["(A) 埃勒斯－當洛症候群（Ehlers-Danlos syndrome）","(B) 黏多醣貯積症（mucopolysaccharidoses）","(C) 高雪氏症（Gaucher disease）","(D) 戴－薩克斯症（Tay-Sachs disease）"],"answer":0,"image":""},{"id":"md2-106-2-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"106年第2次第79題","year":106,"session":2,"number":79,"question":"抗酸性染色（acid-fast stain）不適用於下列那一種疾病的診斷？","options":["(A) 癩瘤性痲瘋（lepromatous leprosy）","(B) Mycobacterium tuberculosis感染","(C) Mycobacterium avium-intracellulare complex感染","(D) Cryptococcus neoformans感染"],"answer":3,"image":""},{"id":"md2-106-2-80","subject":"md2","topic":"病理-免疫感染遺傳","meta":"106年第2次第80題","year":106,"session":2,"number":80,"question":"梅毒病變中，最顯著且多量的浸潤細胞是：","options":["(A) 漿細胞","(B) 淋巴球","(C) 巨噬細胞","(D) 嗜伊紅性白血球"],"answer":0,"image":""},{"id":"md2-106-2-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"106年第2次第81題","year":106,"session":2,"number":81,"question":"培養正常的纖維母細胞，經過放射線照射後，再測其細胞週期的變化，經分析後發現80％的細胞週期停留在G phase。細胞週期的變化與下列何者關係最少？1","options":["(A) 細胞的DNA破壞","(B) p21的活化","(C) Cyclin D/cdk 4被抑制","(D) Cyclin A/cdk 1被活化"],"answer":3,"image":""},{"id":"md2-106-2-82","subject":"md2","topic":"病理-心血管血液","meta":"106年第2次第82題","year":106,"session":2,"number":82,"question":"在續發性高血液凝固狀態（hypercoagulable states）的因素中，下列何者發生血栓的風險相對性最低？","options":["(A) 長期臥床","(B) 心肌梗塞","(C) 心房顫動","(D) 抽菸"],"answer":3,"image":""},{"id":"md2-106-2-83","subject":"md2","topic":"病理-心血管血液","meta":"106年第2次第83題","year":106,"session":2,"number":83,"question":"30歲男性，長期有大量吸菸習慣，最近發現左側下肢疼痛並有間歇跛行，戒菸後明顯減少發作次數，下列何者為最有可能的診斷？","options":["(A) 顯微型多發性血管炎（microscopic polyangiitis）","(B) 結節性多發性動脈炎（polyarteritis nodosa）","(C) 堵塞性血栓血管炎（thromboangiitis obliterans）","(D) 韋氏多發性肉芽腫（Wegener granulomatosis）"],"answer":2,"image":""},{"id":"md2-106-2-84","subject":"md2","topic":"病理-心血管血液","meta":"106年第2次第84題","year":106,"session":2,"number":84,"question":"33 60歲男性因喉嚨疼痛與潰瘍在就醫時被發現血中白血球增加（50×10/µL；參考區間為4.8-10.8×10/µL），紅血球、血小板數目減少。骨髓切片顯示骨髓中細胞佔70-80%，大部分都是中等大小原始細胞（blast cells），細胞質中有非常多火紅顆粒及針狀小體。染色體檢查發現有t（15;17）的染色體轉位。下列何者為最可能的診斷？","options":["(A) 骨髓化生不良症候群（myelodysplastic syndrome）","(B) 蘭格罕組織球增生症（Langerhans cell histiocytosis）","(C) 慢性骨髓性白血病（chronic myeloid leukemia）","(D) 急性骨髓性白血病（acute myeloid leukemia）"],"answer":3,"image":""},{"id":"md2-106-2-85","subject":"md2","topic":"病理-呼吸消化","meta":"106年第2次第85題","year":106,"session":2,"number":85,"question":"下列何種腫瘤最少見於前縱隔腔？","options":["(A) 何杰金氏淋巴瘤（Hodgkin lymphoma）","(B) 生殖細胞腫瘤（germ cell tumor）","(C) 副甲狀腺瘤（parathyroid adenoma）","(D) 節細胞神經母細胞瘤（ganglioneuroblastoma）"],"answer":3,"image":""},{"id":"md2-106-2-86","subject":"md2","topic":"病理-呼吸消化","meta":"106年第2次第86題","year":106,"session":2,"number":86,"question":"下列有關石棉塵肺症（asbestosis）的敘述，何者錯誤？","options":["(A) 閃石石棉（amphibole）較溫石棉（chrysotile）易引起間皮瘤","(B) 病人罹患肺癌的機率比一般人高","(C) 病理可見石棉小體（asbestos body），為石棉纖維經中性白血球吞噬所產生","(D) 接觸石棉是造成間皮瘤最主要的原因"],"answer":2,"image":""},{"id":"md2-106-2-87","subject":"md2","topic":"病理-免疫感染遺傳","meta":"106年第2次第87題","year":106,"session":2,"number":87,"question":"對於免疫力低落的病人，下列何者最少感染其肺部？","options":["(A) 細胞巨大型病毒（Cytomegalovirus）","(B) 肺囊蟲（Pneumocystis）","(C) 麴菌（Aspergillus）","(D) 弓漿蟲（Toxoplasma）"],"answer":3,"image":""},{"id":"md2-106-2-88","subject":"md2","topic":"病理-呼吸消化","meta":"106年第2次第88題","year":106,"session":2,"number":88,"question":"肺鱗狀上皮細胞癌之特徵與下列那一項最不相關？","options":["(A) 抽菸","(B) 常發生於支氣管","(C) 常發生於肺門","(D) 常產生神經內分泌物質"],"answer":3,"image":""},{"id":"md2-106-2-89","subject":"md2","topic":"病理-呼吸消化","meta":"106年第2次第89題","year":106,"session":2,"number":89,"question":"62歲女性，有多年的腸胃症狀，內視鏡檢查發現有萎縮性胃炎（atrophic gastritis），特別是在體部較嚴重，血清學檢查發現有抗壁細胞抗體（anti-parietal cell antibody），此病人同時有貧血。她的貧血最可能是：","options":["(A) 惡性貧血（pernicious anemia）","(B) 再生不良性貧血（aplastic anemia）","(C) 溶血性貧血（hemolytic anemia）","(D) 缺鐵性貧血（iron deficiency anemia）"],"answer":0,"image":""},{"id":"md2-106-2-90","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"106年第2次第90題","year":106,"session":2,"number":90,"question":"腸胃道基質瘤（gastrointestinal stromal tumor, GIST）最常見的突變基因是：","options":["(A) KRAS","(B) c-KIT","(C) BRAF","(D) Her2/Neu"],"answer":1,"image":""},{"id":"md2-106-2-91","subject":"md2","topic":"病理-呼吸消化","meta":"106年第2次第91題","year":106,"session":2,"number":91,"question":"闌尾（appendix）最常見的腫瘤為：","options":["(A) 黏液性腺癌（mucinous adenocarcinoma）","(B) 漿液性腺癌（serous adenocarcinoma）","(C) 管狀腺瘤（tubular adenoma）","(D) 類癌（carcinoid tumor）"],"answer":3,"image":""},{"id":"md2-106-2-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第2次第92題","year":106,"session":2,"number":92,"question":"60歲男性，最近出現腰痛及血尿，電腦斷層發現左腎有一個4公分大小的腫瘤，腫瘤的手術標本切面呈黃色且有壞死區域，顯微變化如圖示。此種腫瘤最不可能發生下列何者基因異常？","options":["(A) 第三對染色體短臂有缺失（3p-）","(B) 第三對染色體發生不平衡易位","(C) VHL基因發生體細胞突變（somatic mutation）","(D) VHL基因發生低甲基化（hypomethylation）"],"answer":3,"image":"md2-106-2-92.jpeg"},{"id":"md2-106-2-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第2次第93題","year":106,"session":2,"number":93,"question":"下列何種膀胱腫瘤的病理變化，為扁平病灶，可見惡性細胞散布於形態正常的尿道上皮細胞中，以帕哲氏病樣形式擴展（pagetoid spread）？","options":["(A) 原位癌（carcinoma in situ）","(B) 低度惡性傾向性乳突狀尿道上皮腫瘤（papillary urothelial neoplasm of low malignant potential）","(C) 低組織分級乳突狀尿道上皮癌（low-grade papillary urothelial carcinoma）","(D) 高組織分級乳突狀尿道上皮癌（high-grade papillary urothelial carcinoma）"],"answer":0,"image":""},{"id":"md2-106-2-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第2次第94題","year":106,"session":2,"number":94,"question":"下列副甲狀腺疾病，最常造成原發性副甲狀腺機能亢進（primary hyperparathyroidism）的病變是：","options":["(A) 腺瘤","(B) 增生","(C) 腺癌","(D) 發炎"],"answer":0,"image":""},{"id":"md2-106-2-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第2次第95題","year":106,"session":2,"number":95,"question":"下列四種細胞，何者最不易出現於正常之子宮內膜中？","options":["(A) 嗜中性白血球（neutrophils）","(B) 巨噬細胞（macrophages）","(C) 漿細胞（plasma cells）","(D) 淋巴球（lymphocytes）"],"answer":2,"image":""},{"id":"md2-106-2-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第2次第96題","year":106,"session":2,"number":96,"question":"20歲女性，發現右側乳房外上方有一個2公分大小，界限明顯且能移動的腫瘤。下列何者是最可能的診斷？","options":["(A) 慢性乳房炎（chronic mastitis）","(B) 纖維腺瘤（fibroadenoma）","(C) 管內乳突瘤（intraductal papilloma）","(D) 侵襲性管腺癌（invasive ductal carcinoma）"],"answer":1,"image":""},{"id":"md2-106-2-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"106年第2次第97題","year":106,"session":2,"number":97,"question":"36歲女性20年來每天抽一包菸，發現自己右側乳房乳暈旁皮膚紅腫熱痛，乳暈下有一腫塊，做切片檢查發現乳小管上皮有明顯鱗狀上皮化生，乳小管被角質堵塞而擴張成囊狀，乳小管旁有明顯肉芽腫樣發炎反應。則下列何者為最可能之診斷？","options":["(A) 管內乳突狀瘤（intraductal papilloma）","(B) 急性乳房炎（acute mastitis）","(C) 分枝桿菌感染（mycobacterial infection）","(D) 周邊乳腺管性乳房炎（periductal mastitis）"],"answer":3,"image":""},{"id":"md2-106-2-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"106年第2次第98題","year":106,"session":2,"number":98,"question":"8歲男孩罹患麻疹一星期，突然昏迷而死亡。解剖診斷為急性瀰漫性腦脊髓炎（acute disseminated encephalomyelitis），下列有關這種形式腦脊髓炎的敘述，何者正確？","options":["(A) 是傳染性疾病","(B) 是髓鞘脫失疾病（demyelinating disease）","(C) 以破壞軸突（axon）為主","(D) 以破壞星狀細胞（astrocyte）為主"],"answer":1,"image":""},{"id":"md2-106-2-99","subject":"md2","topic":"病理-免疫感染遺傳","meta":"106年第2次第99題","year":106,"session":2,"number":99,"question":"一名罹患慢性白血病的女孩化療並未完全得到緩解，六個月後，X光檢查發現右中肺葉浸潤。接著大腦出現壞死，其鏡下所見如圖，則所見到的是：","options":["(A) 細菌","(B) 黴菌","(C) 病毒","(D) 白血病細胞"],"answer":1,"image":"md2-106-2-99.jpeg"},{"id":"md2-106-2-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"106年第2次第100題","year":106,"session":2,"number":100,"question":"下列那一種疾病不會有代償性水腦症（hydrocephalus ex vacuo）？","options":["(A) Alzheimer氏病","(B) Huntington氏舞蹈症","(C) 腦挫傷","(D) 全身輕性麻痺（general paresis of the insane）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第100題一律給分。 (原公告答案 C)"},{"id":"md2-107-1-1","subject":"md2","topic":"細菌學","meta":"107年第1次第1題","year":107,"session":1,"number":1,"question":"下列何者非鬆脆類桿菌（Bacteroides fragilis）之特徵？","options":["(A) 能水解七葉苷（esculin）","(B) 能生長於含20%膽鹽（bile salt）的培養基","(C) 能產生芽胞（spore）","(D) 屬革蘭氏陰性桿菌"],"answer":2,"image":""},{"id":"md2-107-1-2","subject":"md2","topic":"藥理-化學治療","meta":"107年第1次第2題","year":107,"session":1,"number":2,"question":"有關達托黴素（Daptomycin）之敘述，下列何者錯誤？","options":["(A) 作用在細胞膜上","(B) 屬脂胜肽（lipopeptides）藥物","(C) 對多重抗藥性之嗜麥芽窄食單胞菌(Stenotrophomonas maltophilia）有效","(D) 可以治療抗萬古黴素（Vancomycin）之金黃色葡萄球菌（Staphylococcus aureus）所引起的疾病"],"answer":2,"image":""},{"id":"md2-107-1-3","subject":"md2","topic":"病理-免疫感染遺傳","meta":"107年第1次第3題","year":107,"session":1,"number":3,"question":"有關類結核型痲瘋病（tuberculoid leprosy）及癩瘤型痲瘋病（lepromatous leprosy）的敘述，下列何者正確？","options":["(A) 類結核型痲瘋病病灶組織中可以觀察到泡沫巨噬細胞（foamy macrophages），是癩瘤型痲瘋病所沒有的特徵","(B) 類結核型痲瘋病患的細胞性免疫反應（cellular immune reaction）較癩瘤型痲瘋病患為強","(C) 類結核型痲瘋病的傳染力較癩瘤型痲瘋病為高","(D) 癩瘤型痲瘋病患之皮膚對麻瘋菌素（lepromin）測試呈陽性反應"],"answer":1,"image":""},{"id":"md2-107-1-4","subject":"md2","topic":"病理-免疫感染遺傳","meta":"107年第1次第4題","year":107,"session":1,"number":4,"question":"因感染結核分枝桿菌（Mycobacterium tuberculosis）而在肺部形成的肉芽腫（granuloma）中，主要可以觀察到下列那一種細胞？","options":["(A) 滋養細胞（trophocyte）","(B) 小膠質細胞（microglial cell）","(C) 空泡細胞（koilocyte）","(D) 蘭氏巨細胞（Langhans giant cell）"],"answer":3,"image":""},{"id":"md2-107-1-5","subject":"md2","topic":"細菌學","meta":"107年第1次第5題","year":107,"session":1,"number":5,"question":"關於幽門螺旋桿菌（Helicobacter pylori）的敘述，下列何者錯誤？","options":["(A) 人類為其主要的貯存宿主（reservoir），糞口途徑（fecal-oral route）為可能的傳染方式","(B) 此菌可能會導致胃潰瘍（gastric ulcer）或十二指腸潰瘍（duodenal ulcer）","(C) cagA（cytotoxin-associated gene A）陽性細菌的感染被認為與導致胃癌的高風險有關","(D) 尿素呼氣試驗（urea breath test）是一種非侵入性的檢驗方法，但其敏感度與專一性都比傳統細菌培養差"],"answer":3,"image":""},{"id":"md2-107-1-6","subject":"md2","topic":"細菌學","meta":"107年第1次第6題","year":107,"session":1,"number":6,"question":"關於蠟狀桿菌（Bacillus cereus）的敘述，下列何者錯誤？","options":["(A) 耐熱的（heat-stable）毒素可造成嘔吐型食物中毒","(B) 大多數環境中可發現此菌","(C) 產生超級抗原（superantigen），可造成嚴重組織壞死（necrosis）","(D) 可造成眼球感染，例如桿菌型全眼球炎（Bacillus panophthalmitis）"],"answer":2,"image":""},{"id":"md2-107-1-7","subject":"md2","topic":"細菌學","meta":"107年第1次第7題","year":107,"session":1,"number":7,"question":"下列那種細菌在培養基上生長有遊走（swarming）的特徵，且與腎臟結石（renal stones）生成最有關？","options":["(A) 奇異變形桿菌（Proteus mirabilis）","(B) 黏質沙雷氏菌（Serratia marcescens）","(C) 產氣腸桿菌（Enterobacter aerogenes）","(D) 肺炎克雷伯氏桿菌（Klebsiella pneumoniae）"],"answer":0,"image":""},{"id":"md2-107-1-8","subject":"md2","topic":"細菌學","meta":"107年第1次第8題","year":107,"session":1,"number":8,"question":"關於放線菌（Actinomyces）的敘述，下列何者錯誤？","options":["(A) 生長快速，且需要有氧的環境","(B) 會形成含有硫磺狀顆粒（sulfur granules）的肉芽腫病變","(C) 多數的感染始於頸顏部（cervicofacial area）","(D) 可造成胸、腹部、骨盆腔、中樞神經系統的放線菌病（actinomycosis）"],"answer":0,"image":""},{"id":"md2-107-1-9","subject":"md2","topic":"藥理-化學治療","meta":"107年第1次第9題","year":107,"session":1,"number":9,"question":"有關抗生素之敘述，下列何者正確？","options":["(A) 克拉維酸（Clavulanic acid）通常被單獨使用","(B) 甲氧葉酸嘧啶（Trimethoprim）抑制葉酸生成","(C) 紅黴素（Erythromycin）抑制細胞壁的合成","(D) 磺胺（Sulfonamide）抑制DNA旋轉酶（gyrase）"],"answer":1,"image":""},{"id":"md2-107-1-10","subject":"md2","topic":"病毒學","meta":"107年第1次第10題","year":107,"session":1,"number":10,"question":"本雅病毒（Bunyaviruses）大多藉由節肢動物傳播，然而下列何者例外？","options":["(A) 漢坦病毒（Hantaan virus）","(B) 裂谷熱病毒（Rift valley fever virus）","(C) 加利福尼亞腦炎病毒（California encephalitis virus）","(D) 克里米亞-剛果出血熱病毒（Crimean-Congo hemorrhagic fever virus）"],"answer":0,"image":""},{"id":"md2-107-1-11","subject":"md2","topic":"免疫學","meta":"107年第1次第11題","year":107,"session":1,"number":11,"question":"帶有下列那一種基因之同合子（homozygous）缺陷的人，對於人類免疫缺陷病毒（HIV）感染相對地具有抗性？","options":["(A) 17p（p53）","(B) HLA-B 5701","(C) CCR5-delta 32","(D) t（11；22）（q24；q12）"],"answer":2,"image":""},{"id":"md2-107-1-12","subject":"md2","topic":"病毒學","meta":"107年第1次第12題","year":107,"session":1,"number":12,"question":"關於小兒麻痺病毒（poliovirus）的敘述，下列何者正確？","options":["(A) 其基因體是由雙股RNA所組成","(B) 病毒套膜（envelope）上的醣蛋白質（glycoprotein）不容易產生突變","(C) 病毒顆粒很穩定，可以透過下水道系統汙染水源造成感染","(D) 沙克（Salk）減毒疫苗和沙賓（Sabin）死毒疫苗，常被用來預防其所引起的疾病"],"answer":2,"image":""},{"id":"md2-107-1-13","subject":"md2","topic":"病毒學","meta":"107年第1次第13題","year":107,"session":1,"number":13,"question":"下列何種人類病毒最適合生長於攝氏33-35度，所以通常感染上呼吸道。不過，動物來源的此類病毒卻能生長在攝氏37度，因此能造成全身性感染？","options":["(A) 間質肺炎病毒（Metapneumovirus）","(B) 腺病毒（Adenovirus）","(C) 呼吸道細胞融合病毒（Respiratory syncytial virus）","(D) 冠狀病毒（Coronavirus）"],"answer":3,"image":""},{"id":"md2-107-1-14","subject":"md2","topic":"病毒學","meta":"107年第1次第14題","year":107,"session":1,"number":14,"question":"有關病毒與其細胞受器（cell receptor）的配對，下列何者錯誤？","options":["(A) EB病毒（Epstein-Barr virus）- CD21","(B) 流感病毒（Influenza virus）- 水楊酸（sialic acid）","(C) B19病毒（B19 virus） - 紅血球M抗原（erythrocyte M antigen）","(D) 鼻病毒（Rhinovirus）- ICAM-1"],"answer":[1,2,3],"image":"","answer_note":"更正:第14題答Ｂ、Ｃ、Ｄ給分"},{"id":"md2-107-1-15","subject":"md2","topic":"病毒學","meta":"107年第1次第15題","year":107,"session":1,"number":15,"question":"有關人類多瘤病毒（Human polyomavirus）的敘述，下列何者錯誤？","options":["(A) 包括BK病毒及JC病毒","(B) 不具有外套膜（envelope）","(C) JC病毒感染免疫不全病人，常造成去髓鞘（demyelination）病變","(D) T抗原可以活化p53，促進細胞死亡"],"answer":3,"image":""},{"id":"md2-107-1-16","subject":"md2","topic":"真菌學","meta":"107年第1次第16題","year":107,"session":1,"number":16,"question":"下列何者為麴菌（Aspergillus spp.）之型態特徵？","options":["(A) 具假根（rhizoid）","(B) 具厚壁孢子（chlamydospores）","(C) 菌絲（hyphae）無分隔","(D) 具瓶狀（flask-shaped）孢子梗（phialides）"],"answer":3,"image":""},{"id":"md2-107-1-17","subject":"md2","topic":"藥理-化學治療","meta":"107年第1次第17題","year":107,"session":1,"number":17,"question":"下列那一種抗真菌（anti-fungal）藥物的抗藥機制，是在合成葡聚醣（glucan）的相關基因上產生突變？","options":["(A) 氟胞嘧啶（Flucytosine）","(B) 棘白素類（Echinocandins）","(C) 丙烯胺類（Allylamines）","(D) 兩性黴素B（Amphotericin B）"],"answer":1,"image":""},{"id":"md2-107-1-18","subject":"md2","topic":"免疫學","meta":"107年第1次第18題","year":107,"session":1,"number":18,"question":"下列那一種分子在人類所有具有細胞核的細胞中都會表現？","options":["(A) IL-1","(B) IL-2","(C) MHC-I","(D) MHC-II"],"answer":2,"image":""},{"id":"md2-107-1-19","subject":"md2","topic":"免疫學","meta":"107年第1次第19題","year":107,"session":1,"number":19,"question":"下列那一項為免疫球蛋白（immunoglobulin）基因重組（gene rearrangement）的起始步驟？","options":["(A) 重鏈（heavy chain）之V,J剪接","(B) 重鏈（heavy chain）之V,D剪接","(C) 重鏈（heavy chain）之D,J剪接","(D) 輕鏈（light chain）之V,J剪接"],"answer":2,"image":""},{"id":"md2-107-1-20","subject":"md2","topic":"免疫學","meta":"107年第1次第20題","year":107,"session":1,"number":20,"question":"+ 有關不同CD4T細胞亞群（subset）的功能，下列敘述何者錯誤？","options":["(A) 第一型輔助性T細胞（T1）不會幫助巨噬細胞活化，及抗體之產生H","(B) 第二型輔助性T細胞（T2）主要幫助B細胞產生抗體，以及幫助寄生蟲之清除H","(C) 調節性T細胞可藉由抑制抗原呈現細胞之功能，來抑制免疫反應之強度","(D) 第十七型輔助性T細胞（T17）會藉由幫助嗜中性白血球的趨化與活化，來控制早期的感染H"],"answer":0,"image":""},{"id":"md2-107-1-21","subject":"md2","topic":"免疫學","meta":"107年第1次第21題","year":107,"session":1,"number":21,"question":"下列有關自體耐受性（self tolerance）的觀念何者錯誤？","options":["(A) 胸腺與骨髓是維持自我耐受性的重要器官","(B) T淋巴細胞自胸腺成熟後，仍有調控機制在維持其周邊耐受性","(C) 自胸腺分化來的調節性T細胞（regulatory T cell），可以抑制自體反應性T細胞的活性","(D) 調節性T細胞（regulatory T cell）可有效清除腫瘤細胞"],"answer":3,"image":""},{"id":"md2-107-1-22","subject":"md2","topic":"免疫學","meta":"107年第1次第22題","year":107,"session":1,"number":22,"question":"關於免疫球蛋白（抗體），下列敘述何者錯誤？","options":["(A) 成熟的B淋巴球可製造特異性的免疫球蛋白","(B) IgＭ能通過胎盤使新生兒獲得抗體","(C) IgE濃度增加代表個體產生過敏反應或受寄生蟲感染","(D) 每個抗體分子均由二對多肽鏈組成，共包含兩條重鏈與兩條輕鏈"],"answer":1,"image":""},{"id":"md2-107-1-23","subject":"md2","topic":"病毒學","meta":"107年第1次第23題","year":107,"session":1,"number":23,"question":"人類免疫缺乏病毒（HIV）經由CD4分子進入白血球時，經常利用下列何者當作共同接受體？","options":["(A) CD40","(B) CD40 ligand","(C) CXCR4","(D) CCR4"],"answer":2,"image":""},{"id":"md2-107-1-24","subject":"md2","topic":"病理-免疫感染遺傳","meta":"107年第1次第24題","year":107,"session":1,"number":24,"question":"因為22對染色體部分缺損（22q11.2）而造成的DiGeorge症候群，下列何者不屬於其常見症狀？","options":["(A) 甲狀腺發育不全","(B) 胸腺發育不全","(C) 先天性心臟病","(D) 臉型異常"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第24題一律給分 (原公告答案 A)"},{"id":"md2-107-1-25","subject":"md2","topic":"免疫學","meta":"107年第1次第25題","year":107,"session":1,"number":25,"question":"人體內T細胞大量分泌那些細胞激素，與引發遲發型（delayed-type）過敏反應的臨床症狀最相關？","options":["(A) IL-4 + IL-5","(B) IL-5 + IL-17","(C) IL-17 + IFN-γ","(D) IFN-γ + IL-4"],"answer":2,"image":""},{"id":"md2-107-1-26","subject":"md2","topic":"免疫學","meta":"107年第1次第26題","year":107,"session":1,"number":26,"question":"許多新的生物製劑及擬人化的單株抗體已經被發展出來，以治療自體免疫病，但不包括下列那一項？","options":["(A) 抗CD20抗體（CD20-specific monoclonal antibody）治療類風濕性關節炎（rheumatoid arthritis）及紅斑性狼瘡（systemic lupus erythematosus）","(B) 抗CD3抗體（CD3-specific monoclonal antibody）治療第一型糖尿病（type 1 diabetes mellitus）","(C) 抗腫瘤壞死因子抗體（anti-TNF-α antibody）治療類風濕性關節炎","(D) 抗DNA helicase抗體（anti-DNA helicase monoclonal antibody）治療紅斑性狼瘡"],"answer":3,"image":""},{"id":"md2-107-1-27","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"107年第1次第27題","year":107,"session":1,"number":27,"question":"腫瘤細胞有多種方式逃避免疫系統的偵查及消滅，而得以繼續長大，但不包括下列那一項？","options":["(A) 不表現黏著分子（adhesion molecules）及共同刺激分子（co-stimulatory molecules）","(B) 升高抗IgG抗體（anti-IgG antibody）之風濕因子（rheumatoid factor）以自我保護","(C) 分泌出抑制T細胞作用的因子","(D) 分泌出物質包裹自己，形成免疫優勢場所（tumor-induced privileged site）"],"answer":1,"image":""},{"id":"md2-107-1-28","subject":"md2","topic":"藥理-化學治療","meta":"107年第1次第28題","year":107,"session":1,"number":28,"question":"下列何種免疫調節劑是影響到適應性免疫反應（adaptive immune responses），而不同於一般細胞毒性藥物（cytotoxic agent）主要作用於所有正在分裂的細胞？","options":["(A) Azathioprine","(B) Cyclophosphamide","(C) Mycophenolate","(D) Rapamycin"],"answer":3,"image":""},{"id":"md2-107-1-29","subject":"md2","topic":"寄生蟲學","meta":"107年第1次第29題","year":107,"session":1,"number":29,"question":"下列那些寄生蟲會造成患者之自體感染（autoinfection）？①短小包膜絛蟲（Hymenolepis nana） ②菲律賓毛線蟲（Capillaria philippinensis） ③隱胞子蟲（Cryptosporidium parvum） ④糞小桿線蟲（Strongyloides stercoralis）","options":["(A) 1種","(B) 2種","(C) 3種","(D) 4種"],"answer":3,"image":""},{"id":"md2-107-1-30","subject":"md2","topic":"寄生蟲學","meta":"107年第1次第30題","year":107,"session":1,"number":30,"question":"罹患內臟幼蟲移行症（visceral larva migrans）的病患通常有下列特徵，何者除外？","options":["(A) 犬蛔蟲（Toxocara canis）為主要病原體","(B) 常見肝腫大","(C) 常見嗜酸性白血球增多","(D) 大多發生於成年人"],"answer":3,"image":""},{"id":"md2-107-1-31","subject":"md2","topic":"寄生蟲學","meta":"107年第1次第31題","year":107,"session":1,"number":31,"question":"下列絛蟲中，何者之成蟲體型最小？","options":["(A) 多胞絛蟲（Echinococcus multilocularis）","(B) 短小包膜絛蟲（Hymenolepis nana）","(C) 縮小包膜絛蟲（Hymenolepis diminuta）","(D) 犬複殖器絛蟲（Dipylidium caninum）"],"answer":0,"image":""},{"id":"md2-107-1-32","subject":"md2","topic":"寄生蟲學","meta":"107年第1次第32題","year":107,"session":1,"number":32,"question":"節肢動物可當下列那些絛蟲的中間宿主？①豬肉絛蟲（Taenia solium） ②犬複殖器絛蟲（Dipylidium caninum） ③縮小包膜絛蟲（Hymenolepis diminuta） ④單胞絛蟲（Echinococcus granulosus）","options":["(A) ①③","(B) ①④","(C) ②③","(D) ②④"],"answer":2,"image":""},{"id":"md2-107-1-33","subject":"md2","topic":"寄生蟲學","meta":"107年第1次第33題","year":107,"session":1,"number":33,"question":"下列敘述，何者錯誤？","options":["(A) 齒齦阿米巴（Entamoeba gingivalis）的滋養體（trophozoites）會吞噬紅血球","(B) 嗜碘阿米巴（Iodamoeba bütschlii）的滋養體具有一個很大的肝醣泡（glycogen vacuole）","(C) 大腸纖毛蟲（Balantidium coli）是體型最大的人體寄生性原蟲","(D) 大腸纖毛蟲（Balantidium coli）具有大核及小核"],"answer":1,"image":""},{"id":"md2-107-1-34","subject":"md2","topic":"寄生蟲學","meta":"107年第1次第34題","year":107,"session":1,"number":34,"question":"下列何者不屬於蜱媒介人畜共通感染症（tick-borne zoonoses）？","options":["(A) 萊姆病（Lyme disease）","(B) 西尼羅病毒症（West Nile）","(C) 巴貝氏原蟲症（babesiosis）","(D) 落磯山斑疹熱（Rocky Mountain spotted fever）"],"answer":1,"image":""},{"id":"md2-107-1-35","subject":"md2","topic":"寄生蟲學","meta":"107年第1次第35題","year":107,"session":1,"number":35,"question":"下列何種疾病之病原體是經由體蝨（body louse）傳播？","options":["(A) 流行性斑疹傷寒（epidemic typhus）","(B) 地方性斑疹傷寒（endemic typhus）","(C) 落磯山斑疹熱（Rocky mountain spotted fever）","(D) 恙蟲病（scrub typhus）"],"answer":0,"image":""},{"id":"md2-107-1-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第1次第36題","year":107,"session":1,"number":36,"question":"某一世代型研究法不以暴露組與非暴露組選取研究對象，而以選取一個界定明確的群體為研究對象。此研究取樣方法最大的優點為何？","options":["(A) 可以同時研究多個暴露因子","(B) 可以降低研究成本","(C) 可以較快完成研究工作","(D) 可以完全解決干擾因素的影響"],"answer":0,"image":""},{"id":"md2-107-1-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第1次第37題","year":107,"session":1,"number":37,"question":"為了探討某社區之吸菸盛行狀況，由此社區隨機選取100位居民，發現其中30位居民具有吸菸習慣。在5% 的誤差水準下，此社區吸菸率的95％信賴區間之上限值為何？","options":["(A) 0.32","(B) 0.35","(C) 0.39","(D) 0.42"],"answer":2,"image":""},{"id":"md2-107-1-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第1次第38題","year":107,"session":1,"number":38,"question":"某研究者想探討酒駕與死亡車禍的關係，所以在某縣市統計半年的車禍資料，將車禍分為是否有人員24小時內死亡，並調查每次車禍中開車者是否有酒駕行為，下列統計分析方法何者最恰當？","options":["(A) 線性迴歸（Linear regression）","(B) 獨立樣本t檢定（Independent sample t-test）","(C) 配對t檢定（Paired t-test）","(D) 卡方檢定（Chi-square test）"],"answer":3,"image":""},{"id":"md2-107-1-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第1次第39題","year":107,"session":1,"number":39,"question":"二次侵襲率主要用以測量下列何種疾病分布狀況？","options":["(A) 暴露於特定病原後而罹患疾病之個案分布","(B) 接觸罹病個案後而染病之個案分布","(C) 暴露於特定病原後而罹患疾病者於群體之百分比","(D) 接觸罹病個案後染病者於所有接觸罹病個案之百分比"],"answer":3,"image":""},{"id":"md2-107-1-40","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第1次第40題","year":107,"session":1,"number":40,"question":"某國際性研究調查全世界50個國家的女性（15－49歲）生育率（fertility rate, 以Y表示）與已婚婦女避孕率（percentage contraception, 以X表示）的關係，利用簡單線性迴歸得到Y＝6.8-0.08X，且Y與X的Pearson相關係數為 -0.4，下列敘述何者正確？","options":["(A) 已婚婦女避孕率每增加一單位，平均生育率的值會增加6.8","(B) 生育率的變異有40% 可以被已婚婦女避孕率解釋","(C) 生育率的變異有16% 可以被已婚婦女避孕率解釋","(D) 已婚婦女避孕率每增加一單位，平均生育率的值會降低0.4"],"answer":2,"image":""},{"id":"md2-107-1-41","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第1次第41題","year":107,"session":1,"number":41,"question":"進行統計檢定，當根據數據計算所得之p值＞α（顯著水準）時，下列敘述何者正確？","options":["(A) 可以正確推翻虛無假設","(B) 證據不足以推翻虛無假設","(C) 可以正確接受虛無假設","(D) 可能犯型I錯誤"],"answer":1,"image":""},{"id":"md2-107-1-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"107年第1次第42題","year":107,"session":1,"number":42,"question":"受重金屬污染的土壤，不適合使用那個整治技術？","options":["(A) 蒸氣萃取法","(B) 氧化還原法","(C) 土壤淋洗法","(D) 生物處理法"],"answer":0,"image":""},{"id":"md2-107-1-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"107年第1次第43題","year":107,"session":1,"number":43,"question":"水中那一個物質的存在最能代表最近剛受到糞便的污染？","options":["(A) NH-N 3 -","(B) NO-N 2 -","(C) NO-N 3","(D) NO-N 25"],"answer":0,"image":""},{"id":"md2-107-1-44","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"107年第1次第44題","year":107,"session":1,"number":44,"question":"一般而言，針對每項污染物，空氣品質標準常有長時間值與短時間值（例：日平均值與小時平均值），二者何者較低？","options":["(A) 一樣","(B) 長時間值","(C) 短時間值","(D) 依污染物不同改變"],"answer":1,"image":""},{"id":"md2-107-1-45","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"107年第1次第45題","year":107,"session":1,"number":45,"question":"國際癌症研究機構（International Agency for Research on Cancer，簡稱IARC）將紫外線歸類為何種致癌物質？","options":["(A) 已知（known）人類致癌物質","(B) 極可能（probable）人類致癌物質","(C) 疑似（possible）人類致癌物質","(D) 無法歸類（not classifiable）之人類致癌物質"],"answer":0,"image":"","answer_note":"更正:第45題答Ａ給分 (原公告答案 B)"},{"id":"md2-107-1-46","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"107年第1次第46題","year":107,"session":1,"number":46,"question":"造成大氣臭氧層破洞，地球生物圈會暴露更多輻射線，增加人類的皮膚癌。為了避免臭氧層被破壞應管制排放的氣體是：","options":["(A) 一氧化碳","(B) 氟氯化碳","(C) 二氧化氮","(D) 二氧化硫"],"answer":1,"image":""},{"id":"md2-107-1-47","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第1次第47題","year":107,"session":1,"number":47,"question":"社會流行病學的研究取向，不具下述那一項特點？","options":["(A) 個人行為的社會性分析（social characteristics）","(B) 高風險個體預防策略（high-risk preventive strategy）","(C) 群體預防策略（population preventive strategy）","(D) 關心疾病的遠因（distal causes）或根本原因（root causes）"],"answer":1,"image":""},{"id":"md2-107-1-48","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"107年第1次第48題","year":107,"session":1,"number":48,"question":"與精神醫學相比較，公共心理衛生具有何種特性？","options":["(A) 強調症狀治療與病情改變","(B) 注重個人遺傳與生物因素","(C) 重視社區組織和社區參與","(D) 加強隔離病人以保護社區"],"answer":2,"image":""},{"id":"md2-107-1-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"107年第1次第49題","year":107,"session":1,"number":49,"question":"醫師法所稱之醫師不包括下列那一項？","options":["(A) 中醫師","(B) 獸醫師","(C) 醫師","(D) 牙醫師"],"answer":1,"image":""},{"id":"md2-107-1-50","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第1次第50題","year":107,"session":1,"number":50,"question":"目前臺灣是一「高齡化、少子化」的社會，此敘述反應出下列何種人口金字塔？","options":["(A) 都市型","(B) 農村型","(C) 靜止型","(D) 減少型"],"answer":3,"image":""},{"id":"md2-107-1-51","subject":"md2","topic":"藥理-總論與自主神經","meta":"107年第1次第51題","year":107,"session":1,"number":51,"question":"關於藥物動力學的敘述，下列何者錯誤？","options":["(A) 親脂性藥物較親水性藥物容易被身體快速吸收","(B) 藥物可藉由細胞與細胞之間的水性孔（aqueous pores）進行被動滲透，可容許的最大分子量為不超過1,000","(C) 藥物可藉由與細胞膜上特定載體結合而通過細胞膜進入細胞","(D) 藥物可以藉由胞吞作用（endocytosis）進入細胞"],"answer":1,"image":""},{"id":"md2-107-1-52","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"107年第1次第52題","year":107,"session":1,"number":52,"question":"下列何種抗凝血劑屬於直接作用於thrombin之抑制劑？","options":["(A) heparin","(B) enoxaparin","(C) fondaparinux","(D) argatroban"],"answer":[0,3],"image":"","answer_note":"更正:第52題答Ａ、Ｄ給分。"},{"id":"md2-107-1-53","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第1次第53題","year":107,"session":1,"number":53,"question":"下列何種藥物，可以用於男性性慾過強之治療？","options":["(A) cyproterone","(B) clomiphene","(C) danazol","(D) goserelin"],"answer":0,"image":""},{"id":"md2-107-1-54","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第1次第54題","year":107,"session":1,"number":54,"question":"下列何種合成的雌激素，可以作為口服避孕藥（oral contraceptives）使用？","options":["(A) danazol","(B) desogestrel","(C) mestranol","(D) letrozole"],"answer":2,"image":""},{"id":"md2-107-1-55","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"107年第1次第55題","year":107,"session":1,"number":55,"question":"那一種利尿劑會使病人血鉀增加？","options":["(A) spironolactone","(B) bumetanide","(C) acetazolamide","(D) furosemide"],"answer":0,"image":""},{"id":"md2-107-1-56","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第1次第56題","year":107,"session":1,"number":56,"question":"下列何種毒物，會阻斷鈉離子通道而抑制神經動作電位之傳導？","options":["(A) botulinum toxin","(B) ω-conotoxin GVIA","(C) α-latrotoxin","(D) tetrodotoxin"],"answer":3,"image":""},{"id":"md2-107-1-57","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第1次第57題","year":107,"session":1,"number":57,"question":"下列何種藥物除了常用於治療痛風外，對新生兒動脈導管閉鎖不全也有促進其關閉的作用？","options":["(A) indomethacin","(B) etodolac","(C) ketoprofen","(D) naproxen"],"answer":0,"image":""},{"id":"md2-107-1-58","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第1次第58題","year":107,"session":1,"number":58,"question":"下列那一種症狀不屬於長期吸食鴉片類藥物的戒斷現象？","options":["(A) 流淚（lacrimation）","(B) 心跳及血壓下降","(C) 精神亢奮（agitation）","(D) 失眠症（insomnia）"],"answer":1,"image":""},{"id":"md2-107-1-59","subject":"md2","topic":"藥理-化學治療","meta":"107年第1次第59題","year":107,"session":1,"number":59,"question":"下列何種藥物主要是用於治療銅（copper）中毒？","options":["(A) dimercaprol","(B) penicillamine","(C) melarsoprol","(D) deferoxamine"],"answer":1,"image":""},{"id":"md2-107-1-60","subject":"md2","topic":"藥理-總論與自主神經","meta":"107年第1次第60題","year":107,"session":1,"number":60,"question":"下列投藥路徑，何者較易產生首渡效應（first-pass effect）？","options":["(A) 直腸給藥（rectal）","(B) 經皮吸收（transdermal patch）","(C) 舌下給藥（sublingual）","(D) 口服給藥（oral）"],"answer":3,"image":""},{"id":"md2-107-1-61","subject":"md2","topic":"藥理-化學治療","meta":"107年第1次第61題","year":107,"session":1,"number":61,"question":"Sulbactam與下列何種抗生素合併使用，可以避免該抗生素被細菌所產生的β-lactamases酵素破壞結構而失效，因此二者併用可產生抗菌之協同作用？","options":["(A) ampicillin","(B) chloramphenicol","(C) sulfamethoxazole","(D) tetracycline"],"answer":0,"image":""},{"id":"md2-107-1-62","subject":"md2","topic":"藥理-化學治療","meta":"107年第1次第62題","year":107,"session":1,"number":62,"question":"Gentamicin與下列何種抗生素合併使用時，最易對腎臟產生加成性（potentiation）的毒性作用？","options":["(A) amphotericin B","(B) ceftriaxone","(C) doxycyclin","(D) nafcillin"],"answer":0,"image":""},{"id":"md2-107-1-63","subject":"md2","topic":"藥理-化學治療","meta":"107年第1次第63題","year":107,"session":1,"number":63,"question":"下列何種抗生素，可抑制細菌合成葉酸過程中所需酵素dihydrofolate reductase，故可和sulfonamides併用產生協同作用？","options":["(A) tazobactam","(B) teicoplanin","(C) tobramycin","(D) trimethoprim"],"answer":3,"image":""},{"id":"md2-107-1-64","subject":"md2","topic":"藥理-化學治療","meta":"107年第1次第64題","year":107,"session":1,"number":64,"question":"王先生因肺炎住院，經檢驗為綠膿桿菌（Pseudomonas aeruginosa）感染所引起，下列何者為antipseudomonal penicillin，可以和aminoglycoside合併治療以加強療效？","options":["(A) ampicillin","(B) nafcillin","(C) ticarcillin","(D) penicillin G"],"answer":2,"image":""},{"id":"md2-107-1-65","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"107年第1次第65題","year":107,"session":1,"number":65,"question":"下列抗血小板凝集藥物，何者作用機轉為阻斷glycoprotein IIb/IIIa？","options":["(A) clopidogrel","(B) dipyridamole","(C) abciximab","(D) aspirin"],"answer":2,"image":""},{"id":"md2-107-1-66","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第1次第66題","year":107,"session":1,"number":66,"question":"3歲女童有多毛症、乳房增大，身高和骨架看起來猶如十歲的孩童，臨床診斷為早熟的青春期症。下列何者較適合用來治療此種症狀？","options":["(A) pegvisomant","(B) follitropin","(C) octreotide","(D) leuprolide"],"answer":3,"image":""},{"id":"md2-107-1-67","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第1次第67題","year":107,"session":1,"number":67,"question":"Modafinil屬於擬交感神經作用劑（sympathomimetics），可用於下列何種疾病？","options":["(A) 休克（shock）","(B) 高血壓（hypertension）","(C) 氣喘（asthma）","(D) 嗜睡症（narcolepsy）"],"answer":3,"image":""},{"id":"md2-107-1-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第1次第68題","year":107,"session":1,"number":68,"question":"下列何者比較適合被用來預防或避免因化學治療藥物所引起的嘔吐及噁心的副作用？","options":["(A) levodopa","(B) misoprostol","(C) sucralfate","(D) ondansetron"],"answer":3,"image":""},{"id":"md2-107-1-69","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第1次第69題","year":107,"session":1,"number":69,"question":"下列何種藥物具有作用在melatonin（MT）和MT的受體，但不具有成癮性，可以用來治療失眠的病人？12","options":["(A) ketanserin","(B) lorcaserin","(C) ramelteon","(D) repinotan"],"answer":2,"image":""},{"id":"md2-107-1-70","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第1次第70題","year":107,"session":1,"number":70,"question":"Ethosuximide可抑制T型鈣離子通道，主要用於治療下列何種癲癇發作？","options":["(A) 全面強直陣攣發作（generalized tonic-clonic seizure）","(B) 失神發作（absence seizure）","(C) 部份發作（partial seizure）","(D) 肌陣攣發作（myoclonic seizure）"],"answer":1,"image":""},{"id":"md2-107-1-71","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第1次第71題","year":107,"session":1,"number":71,"question":"吸入性麻醉劑halothane合併肌肉鬆弛劑succinylcholine，可能引起惡性高熱症（malignant hyperthermia），下列何種藥物可緩解？","options":["(A) dantrolene","(B) isoflurane","(C) diazepam","(D) theophylline"],"answer":0,"image":""},{"id":"md2-107-1-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第1次第72題","year":107,"session":1,"number":72,"question":"下列何種安眠藥物的作用機轉不是直接作用於GABA的神經傳導？","options":["(A) ramelteon","(B) clonazepam","(C) midazolam","(D) phenobarbital"],"answer":0,"image":""},{"id":"md2-107-1-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第1次第73題","year":107,"session":1,"number":73,"question":"下列何者不是大麻的藥理作用？","options":["(A) 緩解疼痛","(B) 降低食慾","(C) 欣快感（euphoria）和放鬆","(D) 減少噁心"],"answer":1,"image":""},{"id":"md2-107-1-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第1次第74題","year":107,"session":1,"number":74,"question":"下列那一個鴉片類藥物相較於morphine有較高的口服生體可用率（bioavailability），且產生依賴性的時程較慢，可用於鴉片類藥物成癮之替代療法？","options":["(A) nalbuphine","(B) fentanyl","(C) methadone","(D) hydromorphine"],"answer":2,"image":""},{"id":"md2-107-1-75","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第1次第75題","year":107,"session":1,"number":75,"question":"下列何種思覺失調症（schizophrenia）的治療藥物，較無錐體外症候群(extrapyramidal syndrome)的副作用，但可能造成顆粒性白血球缺乏症（agranulocytosis）？","options":["(A) clozapine","(B) haloperidol","(C) chlorpromazine","(D) aripiprazole"],"answer":0,"image":""},{"id":"md2-107-1-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"107年第1次第76題","year":107,"session":1,"number":76,"question":"下列有關色素（pigments）的敘述，何者錯誤？","options":["(A) 皮膚刺青（tattoo）的色素是存在於表皮（epidermis）","(B) 刺青色素（tattoo）通常不會引起炎症反應","(C) 脂褐質（lipofuscin）並不會傷害細胞或影響它的功能","(D) 脂褐質（lipofuscin）的出現是顯示游離基損傷（free radical injury）及脂質過氧化作用（peroxidation）"],"answer":0,"image":""},{"id":"md2-107-1-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"107年第1次第77題","year":107,"session":1,"number":77,"question":"下列有關組織胺（histamine）在炎症反應的敘述，何者正確？","options":["(A) 主要來源是白血球（leukocytes）及內皮（endothelium）","(B) 可經由創傷、冷或熱等損傷釋放","(C) 引起微血管（capillaries）擴張及增加其滲透性","(D) 與血管內皮之H受體（H receptors）結合導致血管擴大22"],"answer":1,"image":""},{"id":"md2-107-1-78","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"107年第1次第78題","year":107,"session":1,"number":78,"question":"細胞傷害中，鈣離子流入細胞內，不會引起那一項變化？","options":["(A) 磷脂酶活化性降低","(B) 蛋白質磷酸化","(C) 細胞骨架分離","(D) 細胞膜受損"],"answer":0,"image":""},{"id":"md2-107-1-79","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"107年第1次第79題","year":107,"session":1,"number":79,"question":"下列三類病毒，何者可在神經系統造成如圖箭頭所指的病變？ ①水痘－帶狀疱疹病毒（Varicella-zoster virus） ②腸病毒（Enterovirus genus） ③西尼羅河病毒（West Nile virus）","options":["(A) 僅①","(B) 僅②","(C) 僅①②","(D) ①②③"],"answer":3,"image":"md2-107-1-79.jpeg"},{"id":"md2-107-1-80","subject":"md2","topic":"病理-免疫感染遺傳","meta":"107年第1次第80題","year":107,"session":1,"number":80,"question":"恙蟲病（scrub typhus）是由具有傳染性的恙蟎叮咬後造成的疾病，患者在叮咬處會形成特有的洞穿式皮膚潰瘍型焦痂（escar）。此焦痂形成的主要原因為：","options":["(A) 立克次體感染血管內皮細胞引起血管炎與血管栓塞","(B) 立克次體感染皮膚上皮細胞，造成上皮細胞壞死，形成潰瘍","(C) 立克次體感染皮膚上皮細胞，造成上皮細胞壞死，引起繼發性細菌感染","(D) 立克次體感染皮膚皮下神經元細胞，造成痛覺喪失，引起繼發性細菌感染"],"answer":0,"image":""},{"id":"md2-107-1-81","subject":"md2","topic":"細菌學","meta":"107年第1次第81題","year":107,"session":1,"number":81,"question":"下列細菌中，何者最常引起燒傷所致的敗血症？","options":["(A) Pseudomonas aeruginosa","(B) E. coli","(C) Proteus mirabilis","(D) Klebsiella pneumoniae"],"answer":0,"image":""},{"id":"md2-107-1-82","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"107年第1次第82題","year":107,"session":1,"number":82,"question":"下列何者與細胞週期G phase進到S phase的調控關係（modulation）最少？1","options":["(A) cyclin D/cdk 4","(B) cyclin E/cdk 2","(C) RB phosphorylation","(D) cyclin B/cdk 1"],"answer":3,"image":""},{"id":"md2-107-1-83","subject":"md2","topic":"病理-心血管血液","meta":"107年第1次第83題","year":107,"session":1,"number":83,"question":"有關穩定性（stable）與脆弱性（vulnerable）動脈硬化斑（atherosclerotic plaque）之比較，下列敘述何者錯誤？","options":["(A) 穩定性斑塊的脂質核心較大","(B) 穩定性斑塊較少發炎細胞浸潤","(C) 脆弱性斑塊含大量泡沫狀細胞","(D) 脆弱性斑塊的纖維帽較薄"],"answer":0,"image":""},{"id":"md2-107-1-84","subject":"md2","topic":"病理-心血管血液","meta":"107年第1次第84題","year":107,"session":1,"number":84,"question":"下列何種疾病的病人較可能會有巨大的脾腫大達3000公克以上？","options":["(A) 髓纖維化（myelofibrosis）","(B) 肝門脈高血壓（portal hypertension）","(C) 感染性單核球症（infectious mononucleosis）","(D) 血色素沉積症（hemochromatosis）"],"answer":0,"image":""},{"id":"md2-107-1-85","subject":"md2","topic":"病理-免疫感染遺傳","meta":"107年第1次第85題","year":107,"session":1,"number":85,"question":"10歲小孩有一個下頷腫塊。病理切片如圖，腫瘤細胞較小，核不分葉，常見細胞分裂。則下列敘述何者錯誤？","options":["(A) 有EB病毒感染","(B) 此病好發於非洲兒童","(C) 此腫瘤屬T-細胞來源","(D) 腫瘤之成長雖極快，但少見轉化為白血病"],"answer":2,"image":"md2-107-1-85.jpeg"},{"id":"md2-107-1-86","subject":"md2","topic":"病理-呼吸消化","meta":"107年第1次第86題","year":107,"session":1,"number":86,"question":"下列何者是診斷急性肺傷害引起之急性呼吸窘迫症候群最重要的病理特徵？","options":["(A) 透明膜（hyaline membrane）","(B) 第二型肺細胞增生（type II pneumocyte proliferation）","(C) 肺泡壁及肺泡空腔內肉芽組織（granulation tissue in alveolar wall and spaces）","(D) 肺泡中隔纖維化增厚（fibrotic thickening of alveolar septa）"],"answer":0,"image":""},{"id":"md2-107-1-87","subject":"md2","topic":"病理-呼吸消化","meta":"107年第1次第87題","year":107,"session":1,"number":87,"question":"下列有關特發性肺纖維化（idiopathic pulmonary fibrosis）的病理變化的敘述，何者錯誤？","options":["(A) 非特異性間質肺炎（non-specific interstitial pneumonia）","(B) 區塊狀間質纖維化（patchy interstitial fibrosis）","(C) 纖維母細胞增生病灶（fibroblastic focus）","(D) 蜂巢狀纖維化（honeycomb fibrosis）"],"answer":0,"image":""},{"id":"md2-107-1-88","subject":"md2","topic":"病理-心血管血液","meta":"107年第1次第88題","year":107,"session":1,"number":88,"question":"下列有關肺部血流疾病之敘述，何者正確？","options":["(A) 肺部大血管內產生血塊大部分是血栓形成（thrombosis）","(B) 肺部栓塞（embolism）的栓子（embolus）主要來自腿部靜脈","(C) 肺動脈栓塞可引起左心急性衰竭，造成病人死亡","(D) 大部分的肺部栓塞可引起肺梗塞（infarct）"],"answer":1,"image":""},{"id":"md2-107-1-89","subject":"md2","topic":"病理-呼吸消化","meta":"107年第1次第89題","year":107,"session":1,"number":89,"question":"女性的肺癌以下列何種組織型態最常見？","options":["(A) 腺癌","(B) 鱗狀上皮細胞癌","(C) 小細胞癌","(D) 大細胞癌"],"answer":0,"image":""},{"id":"md2-107-1-90","subject":"md2","topic":"病理-呼吸消化","meta":"107年第1次第90題","year":107,"session":1,"number":90,"question":"有關克隆氏病（Crohn disease）的敘述，下列何者錯誤？","options":["(A) 好發於直腸","(B) 常出現跳躍性病灶（skip lesion）","(C) 病理特徵是非乾酪性肉芽腫（noncaseating granuloma）","(D) 腸道狹窄是常見的併發症"],"answer":0,"image":""},{"id":"md2-107-1-91","subject":"md2","topic":"病理-呼吸消化","meta":"107年第1次第91題","year":107,"session":1,"number":91,"question":"一名媽媽發現她10個月大，一向很健康的女嬰腹部腫脹且一整天未解便而就醫。身體檢查發現女嬰腹部有明顯壓痛且腸音幾乎消失。腹部X光檢查發現小腸明顯擴張，但無游離空氣的存在。下列何種情況最可能發生在女嬰身上？","options":["(A) 十二指腸閉鎖（duodenal atresia）","(B) 赫希普氏病（Hirschsprung disease）","(C) 腸套疊（intussusception）","(D) 梅克爾氏憩室（Meckel diverticulum）"],"answer":2,"image":""},{"id":"md2-107-1-92","subject":"md2","topic":"病理-免疫感染遺傳","meta":"107年第1次第92題","year":107,"session":1,"number":92,"question":"40歲男性因肝硬化接受肝臟移植，移植手術過程順利，目前服用抗排斥藥。則肝臟移植急性排斥主要病理變化之描述，下列何者錯誤？","options":["(A) 急性排斥常在術後前兩個月內發生","(B) 門脈區、中心靜脈區發炎，內皮細胞腫脹","(C) 膽小管被破壞","(D) 細胞浸潤主要在門脈區，以多形核白血球為主"],"answer":3,"image":""},{"id":"md2-107-1-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"107年第1次第93題","year":107,"session":1,"number":93,"question":"有關次發性副甲狀腺功能亢進所導致的病理變化，下列何者錯誤？","options":["(A) 副甲狀腺內主細胞（chief cells）增生為主","(B) 造成囊狀纖維性骨炎（osteitis fibrosa cystica）","(C) 副甲狀腺內的脂肪細胞增多","(D) 在多處組織器官可見轉移性鈣化（metastatic calcification）"],"answer":2,"image":""},{"id":"md2-107-1-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"107年第1次第94題","year":107,"session":1,"number":94,"question":"附圖顯示一位40歲病人的睪丸腫瘤之局部，下列有關敘述，何者最不適當？","options":["(A) 臨床表現常為惡性","(B) 常合併其他惡性生殖細胞瘤","(C) 血中的腫瘤標記AFP及β-HCG可能上升","(D) 此腫瘤為表皮囊腫"],"answer":3,"image":"md2-107-1-94.jpeg"},{"id":"md2-107-1-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"107年第1次第95題","year":107,"session":1,"number":95,"question":"下列何種卵巢癌最常伴隨子宮內膜異位（endometriosis）？","options":["(A) 漿液性癌（serous carcinoma）","(B) 黏液性癌（mucinous carcinoma）","(C) 亮細胞癌（clear cell carcinoma）","(D) 絨毛癌（choriocarcinoma）"],"answer":2,"image":""},{"id":"md2-107-1-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"107年第1次第96題","year":107,"session":1,"number":96,"question":"侵襲性小葉癌（invasive lobular carcinoma）主要的分子特徵為何？","options":["(A) 不表現E-cadherin","(B) Her2基因增幅（amplification）","(C) BRCA1基因突變","(D) 上皮生長因子受體（epidermal growth factor receptor）過度表現"],"answer":0,"image":""},{"id":"md2-107-1-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"107年第1次第97題","year":107,"session":1,"number":97,"question":"32歲女性近2個月月經週期紊亂，一個月來潮兩次但經血量卻很少，體重增加3公斤，臉上毛髮增多，超音波下發現兩側卵巢有許多囊狀濾泡。關於此疾病，下列敘述何者錯誤？","options":["(A) 又稱作史雷二氏症候群（Stein-Leventhal syndrome）","(B) 組織學檢查以stromal hyperthecosis的現象為主","(C) 會分泌過量的雄性素","(D) 和第二型糖尿病一樣與胰島素抗性有關"],"answer":1,"image":""},{"id":"md2-107-1-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"107年第1次第98題","year":107,"session":1,"number":98,"question":"有關骨肉瘤（osteosarcoma）的敘述，下列何者正確？","options":["(A) 此腫瘤好發於年輕人及老年人，他們的發生率相當","(B) 在成人，此腫瘤主要是發生在長骨（long bone），發生在平骨（flat bone）的機率約為長骨的一半","(C) 腫瘤細胞除產生骨母質（bone matrix）外，亦可產生軟骨母質（cartilage matrix）","(D) 在長骨的好發部位為骺部（epiphyseal region）"],"answer":2,"image":""},{"id":"md2-107-1-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"107年第1次第99題","year":107,"session":1,"number":99,"question":"有關中樞神經系統星狀膠原細胞（astrocyte）對損傷之反應，下列何者正確？","options":["(A) 膠樣變性（gliosis）只有星狀膠原細胞的增生（hyperplasia）而無肥大（hypertrophy）","(B) 阿滋海默第二型（Alzheimer type Ⅱ）星狀膠原細胞主要見於阿滋海默病（Alzheimer disease）","(C) 羅森賽氏纖維（Rosenthal fibers）常見於毛狀細胞星細胞瘤（pilocytic astrocytoma）","(D) 澱粉小體（corpora amylacea）在不同年齡病人所見到的機率大致相同"],"answer":2,"image":""},{"id":"md2-107-1-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"107年第1次第100題","year":107,"session":1,"number":100,"question":"下列有關一氧化碳中毒之腦部變化，何者錯誤？","options":["(A) 大腦皮質第三層及第五層之神經元受損最嚴重","(B) 小腦受損最嚴重的細胞為普金奇氏細胞（Purkinje cells）","(C) 最常見有雙側殼（putamen）壞死","(D) 長期存活的病人，可能會有白質的髓鞘脫失（demyelination）"],"answer":2,"image":""},{"id":"md2-107-2-1","subject":"md2","topic":"細菌學","meta":"107年第2次第1題","year":107,"session":2,"number":1,"question":"金黃色葡萄球菌（Staphylococcus aureus）是根據其菌體的那種成分被區分成11種血清型（serotypes）？","options":["(A) 胜肽聚醣（peptidoglycan）","(B) 蛋白質A（Protein A）","(C) 脫皮毒素（Exfoliative toxins）","(D) 莢膜多醣體（capsular polysaccharide）"],"answer":3,"image":""},{"id":"md2-107-2-2","subject":"md2","topic":"病毒學","meta":"107年第2次第2題","year":107,"session":2,"number":2,"question":"下列疾病中，何者與Epstein-Barr病毒的感染最無關？","options":["(A) 鼻咽癌（nasopharyngeal carcinoma）","(B) 慢性骨髓性白血病（chronic myelogenous leukemia）","(C) 霍金氏疾病（Hodgkin's disease）","(D) 布奇氏淋巴瘤（Burkitt's lymphoma）"],"answer":1,"image":""},{"id":"md2-107-2-3","subject":"md2","topic":"細菌學","meta":"107年第2次第3題","year":107,"session":2,"number":3,"question":"下列細菌何者與食入受汙染的米飯而引起的食物中毒最為相關？","options":["(A) 腸炎沙門氏菌（Salmonella enterica）","(B) 創傷弧菌（Vibrio vulnificus）","(C) 臘狀桿菌（Bacillus cereus）","(D) 大腸桿菌（Escherichia coli）"],"answer":2,"image":""},{"id":"md2-107-2-4","subject":"md2","topic":"細菌學","meta":"107年第2次第4題","year":107,"session":2,"number":4,"question":"關於產志賀毒素大腸桿菌（Shiga toxin-producing Escherichia coli）的敘述，下列何者錯誤？","options":["(A) 會導致經由食物傳播（food-borne）的疾病","(B) 常引起人類嚴重感染症的血清型為O157:H7","(C) 疾病嚴重時可能會引起血性腹瀉（bloody diarrhea）","(D) 不產生stx1或stx2毒素"],"answer":3,"image":""},{"id":"md2-107-2-5","subject":"md2","topic":"細菌學","meta":"107年第2次第5題","year":107,"session":2,"number":5,"question":"15歲男生是學校游泳隊的成員，每日至少泳訓2小時，因左耳疼痛難耐而至耳鼻喉科就診，醫師檢查發現外耳發炎。經微生物培養鑑定為β型溶血，不發酵葡萄糖的細菌。最有可能是被下列何種細菌所感染？","options":["(A) 草綠群鏈球菌（Viridans streptococci）","(B) 表皮葡萄球菌（Staphylococcus epidermidis）","(C) 肺炎鏈球菌（Streptococcus pneumoniae）","(D) 綠膿桿菌（Pseudomonas aeruginosa）"],"answer":3,"image":""},{"id":"md2-107-2-6","subject":"md2","topic":"細菌學","meta":"107年第2次第6題","year":107,"session":2,"number":6,"question":"下列那一種微生物主要在人類細胞內繁殖，且可引起透過性行為傳染的疾病？","options":["(A) 傷寒桿菌（Salmonella Typhi）","(B) 杜克氏嗜血桿菌（Haemophilus ducreyi）","(C) 普氏立克次體（Rickettsia prowazekii）","(D) 砂眼披衣菌（Chlamydia trachomatis）"],"answer":3,"image":""},{"id":"md2-107-2-7","subject":"md2","topic":"細菌學","meta":"107年第2次第7題","year":107,"session":2,"number":7,"question":"40歲男性有肝硬化病史，至海邊釣魚，因赤腳，右腳皮膚不慎被石頭割破流血，翌日在傷口附近出現紅腫與水泡（bullae），覺得疼痛難耐，經醫師診斷為傷口感染所引起的組織壞死（tissue necrosis），他最有可能被下列何種細菌感染？","options":["(A) 傷寒沙門氏桿菌（Salmonella Typhi）","(B) 鮑曼不動桿菌（Acinetobacter baumannii）","(C) 霍亂弧菌（Vibrio cholerae）","(D) 創傷弧菌（Vibrio vulnificus）"],"answer":3,"image":""},{"id":"md2-107-2-8","subject":"md2","topic":"細菌學","meta":"107年第2次第8題","year":107,"session":2,"number":8,"question":"有關非密螺旋體（nontreponemal）及密螺旋體（treponemal）梅毒血清學試驗結果的判讀，下列敘述何者錯誤？","options":["(A) 有些紅斑性狼瘡（SLE）患者會出現長期非密螺旋體試驗偽陽性反應","(B) 愛滋病（AIDS）患者以密螺旋體試驗為陰性反應時，仍無法排除感染梅毒螺旋體（Treponema pallidum）的可能性","(C) 患者的生殖器出現潰瘍時，若非密螺旋體試驗結果為陰性，則可排除梅毒螺旋體感染的可能","(D) 監測治療梅毒過程，密螺旋體試驗相對於非密螺旋體試驗較不易受到治療的影響"],"answer":2,"image":""},{"id":"md2-107-2-9","subject":"md2","topic":"細菌學","meta":"107年第2次第9題","year":107,"session":2,"number":9,"question":"關於肺炎黴漿菌（Mycoplasma pneumoniae）所引起的肺炎，下列何者正確？","options":["(A) 患者可使用青黴素（penicillin）、頭芽孢素（cephalosporin）或萬古黴素（vancomycin）類抗生素治療","(B) 此菌具有P1黏附蛋白（P1 adhesin），能導致呼吸道中具有纖毛的上皮細胞（ciliated epithelial cells）遭致破壞","(C) 可將患者痰液以革蘭氏染色（Gram stain）後，進行顯微鏡觀察是否有分枝纖細狀桿菌","(D) 可藉由吸入受感染鳥類的乾燥糞便或其呼吸道分泌物而得到感染"],"answer":1,"image":""},{"id":"md2-107-2-10","subject":"md2","topic":"細菌學","meta":"107年第2次第10題","year":107,"session":2,"number":10,"question":"下列何者非葡萄球菌菌種（Staphylococcus species）所造成的主要疾病？","options":["(A) 食物中毒（food poisoning）","(B) 膿皰瘡（impetigo）","(C) 皮膚燙傷樣綜合徵狀（scalded skin syndrome）","(D) 胃潰瘍（gastric ulcer）"],"answer":3,"image":""},{"id":"md2-107-2-11","subject":"md2","topic":"免疫學","meta":"107年第2次第11題","year":107,"session":2,"number":11,"question":"下列那一項臨床檢驗項目，是常規做為評估以高效能雞尾酒治療愛滋病（AIDS）效果的主要指標？","options":["(A) p24抗原（antigen）之測定","(B) CD4:CD8 T-cell比例之測定","(C) 血漿中人類免疫缺陷病毒（HIV）病毒量之測定","(D) HIV抗原/抗體（antigen/antibody）組合測試（combo test）"],"answer":2,"image":""},{"id":"md2-107-2-12","subject":"md2","topic":"病毒學","meta":"107年第2次第12題","year":107,"session":2,"number":12,"question":"在器官移植之後，下列那一種病毒最可能造成器官移植感染，且對於抗病毒藥物很容易產生抗藥性？","options":["(A) 腺病毒（Adenovirus）","(B) 人類巨細胞病毒（Cytomegalovirus）","(C) B型肝炎病毒（Hepatitis B virus）","(D) 冠狀病毒SARS CoV"],"answer":[1,2],"image":"","answer_note":"更正:第12題答Ｂ、Ｃ給分"},{"id":"md2-107-2-13","subject":"md2","topic":"病毒學","meta":"107年第2次第13題","year":107,"session":2,"number":13,"question":"下列何種病毒，最不會經由性接觸而傳染？","options":["(A) 第一型人類嗜Ｔ淋巴球病毒（Human T-cell lymphotropic virus-1, HTLV-1）","(B) 巨細胞病毒（Cytomegalovirus, CMV）","(C) A型肝炎病毒（Hepatitis A virus, HAV）","(D) C型肝炎病毒（Hepatitis C virus, HCV）"],"answer":2,"image":""},{"id":"md2-107-2-14","subject":"md2","topic":"病毒學","meta":"107年第2次第14題","year":107,"session":2,"number":14,"question":"關於腮腺炎（mumps）的敘述，下列何者錯誤？","options":["(A) 是透過呼吸道上皮細胞傳染的疾病","(B) 感染都只有呼吸道症狀，不會造成全身性的感染","(C) 腮腺炎病毒可以存在尿液中","(D) 腮腺炎病毒減毒疫苗的效果很好，是目前使用的三合一疫苗中的一種成分"],"answer":1,"image":""},{"id":"md2-107-2-15","subject":"md2","topic":"病毒學","meta":"107年第2次第15題","year":107,"session":2,"number":15,"question":"有關病毒（viruses）複製的敘述，下列何者錯誤？","options":["(A) 具外套膜（envelope）的病毒一般對環境的抗性較低","(B) RNA病毒之複製大部分是在細胞質中進行","(C) RNA病毒之複製大部分不需要宿主細胞的酵素","(D) 具有外套膜的病毒主要藉由細胞溶解（lysis）而釋出細胞外"],"answer":[2,3],"image":"","answer_note":"更正:第15題答Ｃ、Ｄ給分"},{"id":"md2-107-2-16","subject":"md2","topic":"真菌學","meta":"107年第2次第16題","year":107,"session":2,"number":16,"question":"巴西副球黴菌（Paracoccidioides brasiliensis）酵母細胞之細胞壁中，下列那一種組成的含量和致病力最有關？","options":["(A) 1,3-α-葡聚醣（1,3-α-glucan）","(B) 1,3-β-葡聚醣（1,3-β-glucan）","(C) 半乳甘露聚醣（Galactomannan）","(D) 幾丁質（Chitin）"],"answer":0,"image":""},{"id":"md2-107-2-17","subject":"md2","topic":"真菌學","meta":"107年第2次第17題","year":107,"session":2,"number":17,"question":"下列那一種感染症最易於組織中見到厚壁、棕色之硬化體（sclerotic bodies）？","options":["(A) 黑癬（Tinea nigra）","(B) 孢子絲菌病（Sporotrichosis）","(C) 產色芽生黴菌症（Chromoblastomycosis）","(D) 皮下黑化真菌病（Subcutaneous phaeohyphomycosis）"],"answer":2,"image":""},{"id":"md2-107-2-18","subject":"md2","topic":"免疫學","meta":"107年第2次第18題","year":107,"session":2,"number":18,"question":"下列那一種黏著分子（adhesion molecules）能存在於白血球上，使得白血球可以黏附於血管內皮（blood vessel endothelium）上？","options":["(A) E-selectins","(B) ICAMs","(C) Integrins","(D) Fibronectin"],"answer":2,"image":""},{"id":"md2-107-2-19","subject":"md2","topic":"免疫學","meta":"107年第2次第19題","year":107,"session":2,"number":19,"question":"T細胞受器（T cell receptor, TCR）向細胞內傳遞訊息主要依賴下列那一種分子？","options":["(A) TCR","(B) MHC","(C) CD2","(D) CD3"],"answer":3,"image":""},{"id":"md2-107-2-20","subject":"md2","topic":"免疫學","meta":"107年第2次第20題","year":107,"session":2,"number":20,"question":"有位感染Mycobacterium leprae（M. leprae）的病人前來就診，經過檢驗發現血液中對抗M. leprae的抗體效價很高，而寄生在巨噬細胞內的M. leprae很多，臨床症狀顯示有嚴重的組織破壞，下列那種細胞的活化最有可能與病人臨床症狀有關？","options":["(A) 第一型輔助性T細胞（T1）H","(B) 第二型輔助性T細胞（T2）H","(C) 第三型輔助性T細胞（T3）H","(D) 調節性T細胞（regulatory T cell）"],"answer":1,"image":""},{"id":"md2-107-2-21","subject":"md2","topic":"細菌學","meta":"107年第2次第21題","year":107,"session":2,"number":21,"question":"臨床上對預防肺結核病仍沒有令人滿意的疫苗。關於卡介苗的敘述下列何者錯誤？","options":["(A) 是活的分枝桿菌","(B) 無法引發細胞免疫反應","(C) 是我國的免費例行疫苗之一","(D) 施打後會增加結核菌素測驗的偽陽性率"],"answer":1,"image":""},{"id":"md2-107-2-22","subject":"md2","topic":"免疫學","meta":"107年第2次第22題","year":107,"session":2,"number":22,"question":"有一位免疫缺損的病患，他的吞噬細胞的細胞游走正常，吞噬細菌的能力也優良，但吞噬後無法將細菌殺死而經常引起明顯的組織發炎反應。下列疾病何者合乎這個敘述？","options":["(A) 白血球黏著缺損（leukocyte adhesion deficiency）","(B) 慢性肉芽腫病（chronic granulomatous disease）","(C) Wiskott-Aldrich syndrome","(D) DiGeorge syndrome"],"answer":1,"image":""},{"id":"md2-107-2-23","subject":"md2","topic":"免疫學","meta":"107年第2次第23題","year":107,"session":2,"number":23,"question":"傳統補體路徑（classical complement pathways）早期之補體如C1，C2，C4缺乏時，會產生下列何種現象？","options":["(A) 影響到mannose-binding lectin之缺乏，易有兒童時期之感染","(B) 無法清除immune complex，而有immune complex disease","(C) 易有pyogenic bacteria之感染","(D) 易有Pneumocystis jirovecii（先前稱Pneumocystis carinii）感染"],"answer":[0,1,2],"image":"","answer_note":"更正:第23題答Ａ、Ｂ、Ｃ給分"},{"id":"md2-107-2-24","subject":"md2","topic":"免疫學","meta":"107年第2次第24題","year":107,"session":2,"number":24,"question":"關於嗜伊紅性白血球和嗜中性白血球的異同，下列敘述何者正確？","options":["(A) 嗜中性白血球含有過氧化酶，但嗜伊紅性白血球不含此酶","(B) IL-5主要促進嗜伊紅性白血球的生成","(C) 真核寄生蟲感染時嗜中性白血球反應較強","(D) CCR3在嗜中性白血球表現較多"],"answer":1,"image":""},{"id":"md2-107-2-25","subject":"md2","topic":"免疫學","meta":"107年第2次第25題","year":107,"session":2,"number":25,"question":"目前分析人類基因（variant alleles）與自體免疫疾病致病性之相關，是查出此基因在某自體免疫疾病病患者中的存在比例，再與根據於一般族群之期望值做比較，而得到本基因（variant alleles）在自體免疫致病性之「相對危險值」（relative risk）。目前查出有較高的「相對危險值」的基因類別為下列那一項？","options":["(A) 人類白血球抗原（human leukocyte antigens）基因","(B) GM-CSF基因","(C) CD4基因","(D) Small GTP-binding protein cdc42基因"],"answer":0,"image":""},{"id":"md2-107-2-26","subject":"md2","topic":"病理-免疫感染遺傳","meta":"107年第2次第26題","year":107,"session":2,"number":26,"question":"50餘歲女性出現多個關節腫脹、疼痛，主要在雙手近端指間關節（PIPs）、腕關節、膝關節等，檢查結果為類風濕性關節炎（rheumatoid arthritis），其特性為何？","options":["(A) 為關節組織受侵犯，因自體免疫性淋巴細胞反應及自體免疫抗體所致","(B) 因巨噬細胞功能低下所致之關節病變","(C) 為風濕熱（rheumatic fever）表現之一部分","(D) 為感染症之直接後遺症，引起全身關節受犯"],"answer":0,"image":""},{"id":"md2-107-2-27","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"107年第2次第27題","year":107,"session":2,"number":27,"question":"下列有關「腫瘤細胞逃避宿主CD8淋巴細胞攻擊」的敘述，那一項錯誤？","options":["(A) 腫瘤細胞抑制本身MHC（major histocompatibility complex）class II分子的表現","(B) 腫瘤細胞不表現可引發免疫反應的抗原","(C) 腫瘤細胞可分泌抑制T細胞活化的細胞激素","(D) 腫瘤細胞群能形成特殊環境不讓CD8淋巴細胞浸潤"],"answer":0,"image":""},{"id":"md2-107-2-28","subject":"md2","topic":"免疫學","meta":"107年第2次第28題","year":107,"session":2,"number":28,"question":"目前使用單株抗體的生物製劑治療多種自體免疫病及其他多種疾病，都有長足的進步。不過這些單株抗體製劑都要有擬人化（humanized）的步驟，才能用於人體。這個步驟為何？","options":["(A) 先與人類補體結合，是為擬人化步驟","(B) 先通過存有移除型抗體（depleting antibodies）的介面做為純化步驟，才得到擬人化的單株抗體","(C) 通過存有抗淋巴球球蛋白（anti-lymphocyte globulin）的介面做為純化步驟","(D) 將其他物種單株抗體基因的互補決定區域（complementary-determining regions, CDRs）部分，轉殖到人類單株抗體基因的互補決定區域（CDRs）部分"],"answer":3,"image":""},{"id":"md2-107-2-29","subject":"md2","topic":"寄生蟲學","meta":"107年第2次第29題","year":107,"session":2,"number":29,"question":"蘇先生因個人養身因素而食用醃漬蝸牛及生蝸牛多年，日前急診就醫因疑似腦炎或腦膜腦炎而住院，經脊髓穿刺發現腦脊髓液（CSF）內有高數量白血球（1500/µL），並伴隨有嗜酸性白血球增多症（eosinophilia）。依據上述結果，蘇先生最可能感染下列何種寄生蟲？","options":["(A) 旋毛蟲（Trichinella spiralis）","(B) 廣節裂頭絛蟲（Diphyllobothrium latum）","(C) 棘顎口線蟲（Gnathostoma spinigerum）","(D) 廣東住血線蟲（Angiostrongylus cantonensis）"],"answer":3,"image":""},{"id":"md2-107-2-30","subject":"md2","topic":"寄生蟲學","meta":"107年第2次第30題","year":107,"session":2,"number":30,"question":"做皮下切片（skin snips）檢查微絲蟲（microfilaria）是診斷下列何種寄生蟲感染的重要依據？","options":["(A) 羅阿絲蟲（Loa loa）","(B) 蟠尾絲蟲（Onchocerca volvulus）","(C) 麥地那線蟲（Dracunculus medinensis）","(D) 馬來亞絲蟲（Brugia malayi）"],"answer":1,"image":""},{"id":"md2-107-2-31","subject":"md2","topic":"寄生蟲學","meta":"107年第2次第31題","year":107,"session":2,"number":31,"question":"下列有關曼氏血吸蟲（Schistosoma mansoni）感染之敘述，那些是錯誤的？①可由糞便檢查到具尾刺（terminal spine）的蟲卵而確診 ②病患在慢性感染期較易引起左葉肝臟腫大 ③病患可能因生食水螺，其囊幼（metacercaria）進入體內而感染","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":1,"image":""},{"id":"md2-107-2-32","subject":"md2","topic":"寄生蟲學","meta":"107年第2次第32題","year":107,"session":2,"number":32,"question":"人類食用未熟或生的帶蟲豬肉，最不可能罹患以下何種寄生蟲病？","options":["(A) 旋毛蟲症（trichinellosis）","(B) 囊蟲症（cysticercosis）","(C) 肺吸蟲症（paragonimiasis）","(D) 包蟲症（hydatid disease）"],"answer":3,"image":"","answer_note":"更正:第32題答Ｄ給分 (原公告答案 C)"},{"id":"md2-107-2-33","subject":"md2","topic":"寄生蟲學","meta":"107年第2次第33題","year":107,"session":2,"number":33,"question":"下列之寄生蟲配對中，何者在患者組織切片皆可能檢出其囊體期（cyst stage）？","options":["(A) 哈氏阿米巴（Entamoeba hartmanni）及棘阿米巴（Acanthamoeba spp.）","(B) 棘阿米巴（Acanthamoeba spp.）及痢疾阿米巴（Entamoeba histolytica）","(C) 棘阿米巴（Acanthamoeba spp.）及巴氏阿米巴（Balamuthia mandrillaris）","(D) 棘阿米巴（Acanthamoeba spp.）及福氏內格里阿米巴（Naegleria fowleri）"],"answer":2,"image":""},{"id":"md2-107-2-34","subject":"md2","topic":"寄生蟲學","meta":"107年第2次第34題","year":107,"session":2,"number":34,"question":"人類感染恙蟲病（scrub typhus）主要是經由下列何者之叮咬而感染？","options":["(A) 感染性成蜱（tick）","(B) 感染性幼蜱（tick）","(C) 感染性成蟎（mite）","(D) 感染性幼蟎（mite）"],"answer":3,"image":""},{"id":"md2-107-2-35","subject":"md2","topic":"寄生蟲學","meta":"107年第2次第35題","year":107,"session":2,"number":35,"question":"下列何種病媒滋生感染症較易藉由輸血途徑而造成人傳人感染？","options":["(A) 巴西利什曼原蟲病（leishmaniasis braziliensis）","(B) 萊姆病（Lyme disease）","(C) 恙蟲病（scrub typhus）","(D) 巴貝氏原蟲症（babesiosis）"],"answer":3,"image":""},{"id":"md2-107-2-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第2次第36題","year":107,"session":2,"number":36,"question":"下列何者不是中央極限定理（central limit theorem）的涵義？","options":["(A) 隨機樣本平均值（sample mean）之統計分布接近常態分布（normal distribution）","(B) 隨機樣本平均值（sample mean）之統計分布接近布阿松分布（Poisson distribution）","(C) 所有可能的隨機樣本平均值（sample mean）之平均值等於母群體（original population）平均值","(D) 標準誤（standard error）取決於母群體（original population）標準差與樣本的大小（size of sample）"],"answer":1,"image":""},{"id":"md2-107-2-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第2次第37題","year":107,"session":2,"number":37,"question":"對無母數分析的描述下列何者錯誤？","options":["(A) 對資料的極端數值較為敏感","(B) 不需假設資料呈常態分布","(C) 統計檢定力較有母數分析低","(D) 適合處理小樣本的分析"],"answer":[0,2],"image":"","answer_note":"更正:第37題答Ａ、Ｃ給分"},{"id":"md2-107-2-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第2次第38題","year":107,"session":2,"number":38,"question":"醫師判讀一項檢查結果時必須知道該檢查的敏感度（sensitivity）。何謂敏感度？","options":["(A) 檢查結果為陽性的病人中，確實有該項疾病的機率","(B) 檢查結果為陰性的病人中，確實沒有該項疾病的機率","(C) 有該項疾病的病人中，檢查結果為陽性的機率","(D) 沒有該項疾病的病人中，檢查結果為陰性的機率"],"answer":2,"image":""},{"id":"md2-107-2-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第2次第39題","year":107,"session":2,"number":39,"question":"病例對照研究中，吸菸對口腔癌發生之勝算比值（odds ratio）為2.0倍。若健康對照個案之中有25% 個案吸菸，則400名罹患口腔癌病患之中有多少名病患吸菸？","options":["(A) 100","(B) 160","(C) 200","(D) 240"],"answer":1,"image":""},{"id":"md2-107-2-40","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第2次第40題","year":107,"session":2,"number":40,"question":"關於篩檢的描述何者錯誤？","options":["(A) 公費篩檢政策實施當年，癌症的發生率通常會較往年上升","(B) 推行子宮頸抹片篩檢會有效降低子宮頸癌死亡率","(C) 癌症盛行率會高於發生率","(D) 為減少癌症死亡率，應對各種癌症進行公費篩檢"],"answer":3,"image":""},{"id":"md2-107-2-41","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第2次第41題","year":107,"session":2,"number":41,"question":"某研究收集30人的收縮壓（mmHg）及年齡的隨機樣本資料，計算皮爾森氏相關係數（Pearson’s correlation coefficient）得0.7。假若同樣的資料，以血壓當依變項（Y；dependent variable），以年齡當自變項（X；independent variable），可得到直線迴歸線Ŷ＝a＋bX。下列何者正確？","options":["(A) b一定大於零","(B) a一定小於零","(C) 血壓的變化有70%可被年齡的變異所解釋","(D) 平均每增加一歲，則收縮壓就增加0.7mmHg"],"answer":0,"image":""},{"id":"md2-107-2-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"107年第2次第42題","year":107,"session":2,"number":42,"question":"自來水中之消毒副產物，主要為所加之氯與下列何類物質作用所產生？","options":["(A) 有機物","(B) 砷","(C) 鉛","(D) 硝酸鹽"],"answer":0,"image":""},{"id":"md2-107-2-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"107年第2次第43題","year":107,"session":2,"number":43,"question":"空氣污染指標（PSI）與下列那五種不同污染物的濃度有關？","options":["(A) SO、CO、O、NO、PM 33210","(B) SO、CO、O、NO、PM 222210","(C) SO、CO、O、NO、PM 2231.0","(D) SO、CO、O、NO、PM 23210"],"answer":3,"image":""},{"id":"md2-107-2-44","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"107年第2次第44題","year":107,"session":2,"number":44,"question":"關於臭氧敘述，下列何者錯誤？","options":["(A) 大多為直接由污染源排放之一級污染物","(B) 夏天午後空氣中的臭氧濃度較其他時間高，尤其在工業區與都會區更為明顯","(C) 平流層臭氧濃度太低，會增加紫外線暴露","(D) 可以用於室內空氣品質之改善"],"answer":[0,3],"image":"","answer_note":"更正:第44題答Ａ、Ｄ給分"},{"id":"md2-107-2-45","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"107年第2次第45題","year":107,"session":2,"number":45,"question":"國際癌症研究機構（IARC）將流病資料不充分且動物資料有限之可能致癌物，列為那一類？","options":["(A) 1","(B) 2A","(C) 2B","(D) 3"],"answer":2,"image":""},{"id":"md2-107-2-46","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"107年第2次第46題","year":107,"session":2,"number":46,"question":"關於劑量反應評估之敘述，下列何者錯誤？","options":["(A) 致癌性與非致癌性之劑量反應關係應分開描述","(B) 致癌效應與非致癌效應皆有其閾值（threshold）","(C) 致癌之效應以風險作為呈現","(D) 閾值以下之劑量，預期將不會造成顯著損害"],"answer":1,"image":""},{"id":"md2-107-2-47","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"107年第2次第47題","year":107,"session":2,"number":47,"question":"目前我國心理衛生工作主要的法源依據為何？","options":["(A) 心理衛生法","(B) 公共心理衛生法","(C) 精神衛生法","(D) 社區精神醫療保健法"],"answer":2,"image":""},{"id":"md2-107-2-48","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"107年第2次第48題","year":107,"session":2,"number":48,"question":"社會流行病學強調疾病多層次的社會機制，研究設計時常需同時考慮「個體」與「群體」分析單位。此種同時考慮「個體」與「群體」的研究設計，可以避免下述何種研究上的謬誤或偏誤？","options":["(A) 辛普森詭論（Simpson’s paradox）","(B) 生態謬誤（ecological fallacy）","(C) 選擇偏誤（selection bias）","(D) 干擾偏誤（confounding bias）"],"answer":1,"image":""},{"id":"md2-107-2-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"107年第2次第49題","year":107,"session":2,"number":49,"question":"依全民健康保險法第48條之規定，保險對象有下列情形之一者，免依全民健康保險法規定自行負擔費用，下列何者不在此範圍內？","options":["(A) 重大傷病","(B) 分娩","(C) 中低收入戶","(D) 山地離島地區之就醫"],"answer":2,"image":""},{"id":"md2-107-2-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"107年第2次第50題","year":107,"session":2,"number":50,"question":"以下關於醫療機構／醫院分類的敘述何者錯誤？","options":["(A) 依所有權分為公立醫療機構、私立醫療機構、醫療法人及法人附設醫療機構四類","(B) 依主治醫師雇用方式分為開放性醫院及閉鎖性醫院兩類","(C) 依服務項目分為醫院、診所及其他醫療機構三類","(D) 依是否具教學功能分為教學醫院及非教學醫院兩類"],"answer":1,"image":""},{"id":"md2-107-2-51","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第2次第51題","year":107,"session":2,"number":51,"question":"下列何種藥物作用於dihydroorotate dehydrogenase而抑制pyrimidine合成，用於類風濕性關節炎（rheumatoid arthritis）治療？","options":["(A) leflunomide","(B) mycophenolic acid","(C) azathioprine","(D) methotrexate"],"answer":0,"image":""},{"id":"md2-107-2-52","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第2次第52題","year":107,"session":2,"number":52,"question":"有關糖皮質激素（glucocorticoids）所產生的副作用描述，下列何者錯誤？","options":["(A) 會透過干擾鈣離子的代謝作用，進而引起骨質疏鬆（osteoporosis）的現象","(B) 具有促進成骨細胞（osteoblast）的形成及活性","(C) 具有增加消化性潰瘍（peptic ulcer）發生的作用","(D) 長期使用會抑制生長激素的分泌作用"],"answer":1,"image":""},{"id":"md2-107-2-53","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第2次第53題","year":107,"session":2,"number":53,"question":"有關雌激素（estrogen）用於停經婦女的補充治療之敘述，下列何者正確？","options":["(A) 會使骨質疏鬆症（osteoporosis）惡化","(B) 會增加子宮內膜癌（endometrial carcinoma）發生的機率","(C) 會誘發熱潮紅（hot flushes）的產生","(D) 會增加血漿中低密度脂蛋白膽固醇（low-density lipoprotein cholesterol; LDL）和減少高密度脂蛋白膽固醇（high-density lipoprotein cholesterol; HDL）濃度"],"answer":1,"image":""},{"id":"md2-107-2-54","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第2次第54題","year":107,"session":2,"number":54,"question":"降血糖藥物acarbose的主要作用機轉為何？","options":["(A) 減少胰島素被肝臟代謝分解作用","(B) 抑制腸道中α-葡萄糖苷酶（α-glucosidases）的活性，干擾碳水化合物的消化及減慢醣類吸收速率","(C) 促進胰臟胰島素的分泌作用","(D) 增加肝醣的生合成（glycogen synthesis）"],"answer":1,"image":""},{"id":"md2-107-2-55","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"107年第2次第55題","year":107,"session":2,"number":55,"question":"有關nesiritide用於治療急性代償性功能失常之心衰竭病人之藥理作用敘述，下列何者錯誤？","options":["(A) 使cyclic AMP增加","(B) 活化brain natriuretic peptide（BNP）receptor","(C) 使血管放鬆","(D) 產生利尿作用"],"answer":0,"image":""},{"id":"md2-107-2-56","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第2次第56題","year":107,"session":2,"number":56,"question":"下列何種藥物可作為早期墮胎藥（early abortion）？","options":["(A) alprostadil","(B) treprostinil","(C) mifepristone","(D) iloprost"],"answer":2,"image":""},{"id":"md2-107-2-57","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第2次第57題","year":107,"session":2,"number":57,"question":"下列何種藥物作用於GABA receptor？B","options":["(A) baclofen","(B) diazepam","(C) tizanidine","(D) dantrolene"],"answer":0,"image":""},{"id":"md2-107-2-58","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第2次第58題","year":107,"session":2,"number":58,"question":"有關naloxone藥理作用之敘述，下列何者正確？","options":["(A) 口服有效","(B) 具有提高疼痛閾值（threshold）的作用","(C) 可以拮抗morphine所引起的呼吸抑制作用","(D) 可以拮抗barbiturates藥物所引起的呼吸抑制作用"],"answer":[0,2],"image":"","answer_note":"更正:第58題答Ａ、Ｃ給分"},{"id":"md2-107-2-59","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第2次第59題","year":107,"session":2,"number":59,"question":"單一靜脈注射thiopental在人體內的作用時間非常短暫，其主要原因是具有下列何項性質？","options":["(A) 在腸胃道之吸收緩慢","(B) 不經由肝臟代謝而直接由腎臟排出","(C) 易由大腦再到脂肪組織重新分布","(D) 在肝臟很快被代謝成不活性物質"],"answer":2,"image":""},{"id":"md2-107-2-60","subject":"md2","topic":"藥理-化學治療","meta":"107年第2次第60題","year":107,"session":2,"number":60,"question":"下列何種藥物需要併用pyridoxine來預防神經發炎的副作用？","options":["(A) daptomycin","(B) meropenem","(C) isoniazid","(D) teicoplanin"],"answer":2,"image":""},{"id":"md2-107-2-61","subject":"md2","topic":"藥理-化學治療","meta":"107年第2次第61題","year":107,"session":2,"number":61,"question":"下列何種抗生素不經由肝臟代謝或膽汁排出，因此不會干擾其他藥物的代謝作用？","options":["(A) chloramphenicol","(B) erythromycin","(C) gentamicin","(D) rifampin"],"answer":2,"image":""},{"id":"md2-107-2-62","subject":"md2","topic":"藥理-化學治療","meta":"107年第2次第62題","year":107,"session":2,"number":62,"question":"關於penicillins之藥物動力學的敘述，下列何者正確？","options":["(A) ticarcillin可以經腸胃道吸收，因此可以口服方式治療感染","(B) probenecid可以抑制penicillins由腎小管過濾方式排至尿中","(C) benzathine penicillin相對其他penicillin藥物有較長的半衰期，約可長達14天","(D) amoxicillin口服吸收效果易受食物干擾而降低藥效"],"answer":2,"image":""},{"id":"md2-107-2-63","subject":"md2","topic":"藥理-化學治療","meta":"107年第2次第63題","year":107,"session":2,"number":63,"question":"下列抗癌藥物中何者號稱為紡錘體的毒藥（mitotic spindle poison），讓紡錘絲之tubulin穩定聚合不易散去，進而破壞有絲分裂（mitosis）過程？","options":["(A) busulfan","(B) cisplatin","(C) 6-mercaptopurine","(D) paclitaxel"],"answer":3,"image":""},{"id":"md2-107-2-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"107年第2次第64題","year":107,"session":2,"number":64,"question":"下列何者可拮抗plasminogen活化成plasmin？","options":["(A) urokiase","(B) vasopressin","(C) tPA（tissue plasminogen activator）","(D) tranexamic acid"],"answer":3,"image":""},{"id":"md2-107-2-65","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"107年第2次第65題","year":107,"session":2,"number":65,"question":"下列治療血脂異常（dyslipidemia）的藥物，何者是透過抑制腸道NPC1L1 sterol transporter，而減少膽固醇（cholesterol）的吸收？","options":["(A) cholestyramine","(B) gemfibrozil","(C) ezetimibe","(D) simvastatin"],"answer":2,"image":""},{"id":"md2-107-2-66","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"107年第2次第66題","year":107,"session":2,"number":66,"question":"Ivabradine用以治療心搏過速，且不影響心肌收縮力、心室再極化和心內傳導，其作用機制為何？","options":["(A) funny current（I）blocker f","(B) L-Type calcium channel blocker","(C) T-Type calcium channel blocker","(D) beta blocker"],"answer":0,"image":""},{"id":"md2-107-2-67","subject":"md2","topic":"藥理-總論與自主神經","meta":"107年第2次第67題","year":107,"session":2,"number":67,"question":"Galantamine屬於膽鹼酯酶抑制劑（cholinesterase inhibitors），最適合用於治療下列何種疾病？","options":["(A) 重症肌無力（myasthenia gravis）","(B) 帕金森氏症（Parkinson's disease）","(C) 青光眼（glaucoma）","(D) 阿茲海默症（Alzheimer's disease）"],"answer":3,"image":""},{"id":"md2-107-2-68","subject":"md2","topic":"藥理-總論與自主神經","meta":"107年第2次第68題","year":107,"session":2,"number":68,"question":"下列何者不是蕈毒鹼受體阻斷劑（muscarinic receptor-blocking drugs）之臨床用途？","options":["(A) 青光眼（glaucoma）","(B) 動暈症（motion sickness）","(C) 支氣管擴張（bronchodilation）","(D) 帕金森氏症（Parkinson's disease）"],"answer":0,"image":""},{"id":"md2-107-2-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第2次第69題","year":107,"session":2,"number":69,"question":"一位60歲的婦人患有第一型糖尿病已逾40年，餐後常有嚴重的胃部脹氣，經診斷後確認為糖尿病併發的胃癱軟無力（gastroparesis）。下列何者為可用來治療此症狀的prokinetic藥物？","options":["(A) alosetron","(B) metoclopramide","(C) loperamide","(D) sucralfate"],"answer":1,"image":""},{"id":"md2-107-2-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第2次第70題","year":107,"session":2,"number":70,"question":"有位20歲的大學生因服用過量的藥品，引發癲癇而被送到急診部，她的室友描述該生曾經口服某種藥物會造成失眠。下列何者被用來治療氣喘病人的氣管痙孿，且易引發失眠及癲癇？","options":["(A) ipratropium","(B) theophylline","(C) cromolyn","(D) metaproterenol"],"answer":1,"image":""},{"id":"md2-107-2-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"107年第2次第71題","year":107,"session":2,"number":71,"question":"有位病人因下肢趾頭關節處腫脹疼痛無法行走，被送至醫院急診室，經抽血檢查發現是xanthine oxidase活性極高所引起的痛風，醫師做了緊急處理緩解後，建議病人服用下列何種藥物控制尿酸濃度最為合適？","options":["(A) ibuprofen","(B) indomethacin","(C) allopurinol","(D) aspirin"],"answer":2,"image":""},{"id":"md2-107-2-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第2次第72題","year":107,"session":2,"number":72,"question":"下列何者為治療succinylcholine引起的惡性高溫（malignant hyperthermia）最適當的藥物？","options":["(A) dantrolene","(B) baclofen","(C) rocuronium","(D) diazepam"],"answer":0,"image":""},{"id":"md2-107-2-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第2次第73題","year":107,"session":2,"number":73,"question":"Memantine可用於治療阿兹海默症（Alzheimer's disease），下列何者為該藥可能的藥理作用機轉？","options":["(A) 抑制muscarine受體","(B) 抑制dopamine受體","(C) 抑制NMDA受體","(D) 抑制GABA受體A"],"answer":2,"image":""},{"id":"md2-107-2-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"107年第2次第74題","year":107,"session":2,"number":74,"question":"抗癲癇的藥物中，下列何者的作用機轉與阻斷鈉離子管道最不具關連性？","options":["(A) phenytoin","(B) carbamazepine","(C) lamotrigine","(D) levetiracetam"],"answer":3,"image":""},{"id":"md2-107-2-75","subject":"md2","topic":"藥理-化學治療","meta":"107年第2次第75題","year":107,"session":2,"number":75,"question":"下列何種藥物口服可治療鐵中毒？","options":["(A) deferoxamine","(B) deferasirox","(C) D-dimethylcysteine","(D) Prussian blue"],"answer":1,"image":""},{"id":"md2-107-2-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"107年第2次第76題","year":107,"session":2,"number":76,"question":"為了瞭解不同物質是否有助於上皮細胞的生長而進行一項實驗。在含有上皮細胞的細胞培養中，加入表皮細胞生長因子（epidermal growth factor）時，它會與細胞表面的受器（receptor）結合，導致RAS蛋白活化，造成轉錄因子（transcription factor）活化。上述實驗對上皮細胞的作用，主要是經由下列何種細胞內的途徑進行？","options":["(A) Cyclic AMP","(B) Cyclin-dependent kinases","(C) JAK/STAT system","(D) Mitogen-activated protein kinase"],"answer":3,"image":""},{"id":"md2-107-2-77","subject":"md2","topic":"病理-免疫感染遺傳","meta":"107年第2次第77題","year":107,"session":2,"number":77,"question":"8歲男孩出現發燒、喉嚨痛症狀，身體檢查發現兩側頸部淋巴腺腫大，咽喉與扁桃腺發炎。常規血液檢查發現白血球數上升，其中70%為淋巴細胞，淋巴細胞之中30%為非典型淋巴細胞。血中IgM嗜異性抗體（IgM heterophil antibody）與抗Epstein -Barr病毒IgM抗體呈陽性反應。此非典型淋巴細胞最可能是下列何種細胞？","options":["(A) CD4陽性的T淋巴細胞","(B) CD8陽性的T淋巴細胞","(C) NK-T細胞","(D) B淋巴細胞"],"answer":1,"image":""},{"id":"md2-107-2-78","subject":"md2","topic":"病毒學","meta":"107年第2次第78題","year":107,"session":2,"number":78,"question":"下列那一項不是腮腺炎（mumps）的合併症？","options":["(A) 睪丸炎（orchitis）","(B) 胰臟炎（pancreatitis）","(C) 感染後腦炎（postinfectious encephalitis）","(D) 進行性多灶性白質腦病（progressive multifocal leukoencephalopathy）"],"answer":3,"image":""},{"id":"md2-107-2-79","subject":"md2","topic":"細菌學","meta":"107年第2次第79題","year":107,"session":2,"number":79,"question":"下列有關痲瘋的敘述，何者錯誤？","options":["(A) 癩瘤型痲瘋（lepromatous leprosy）病變組織中可以發現有極多的痲瘋桿菌","(B) 在癩瘤型痲瘋，是由於細胞性及體液性（humoral）免疫反應兩者均有缺失的緣故","(C) 在類結核型痲瘋（tuberculoid leprosy），是由於細胞性免疫反應太強的緣故，其肉芽腫中較難發現細菌","(D) 痲瘋桿菌經由人與人之間散布，可能由呼吸傳染"],"answer":1,"image":""},{"id":"md2-107-2-80","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"107年第2次第80題","year":107,"session":2,"number":80,"question":"有關癌細胞常見之基本生理特性，下列敘述何者錯誤？","options":["(A) 自發性生長訊息（self-sufficiency in growth signals）","(B) DNA修復缺陷及不引發細胞凋亡（defects in DNA repair and evasion of apoptosis）","(C) 具侵襲和轉移能力（ability to invade and metastasize）","(D) 需大量生長因子（growth factors）"],"answer":3,"image":""},{"id":"md2-107-2-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"107年第2次第81題","year":107,"session":2,"number":81,"question":"60歲男性，因為車禍造成脾臟破裂失血，臨床表現皮膚乾燥、無尿、血壓下降，經手術、輸血及體液補充後，症狀改善，在病程中所導致的器官變化，下列何者最易發生？","options":["(A) 肝臟廣泛性壞死","(B) 急性腎小管壞死","(C) 瀰漫性肺泡壞死","(D) 腎上腺皮質細胞中脂肪堆積"],"answer":1,"image":""},{"id":"md2-107-2-82","subject":"md2","topic":"病理-心血管血液","meta":"107年第2次第82題","year":107,"session":2,"number":82,"question":"42歲女性突發呼吸困難、嘔吐、胸骨後疼痛並且延伸到上顎部。病人最後陷入意識不清及暈厥。影像學檢查發現升主動脈（ascending aorta）中度擴張，內膜出現裂口（tear）。身體檢查顯示此病人身長高於同年齡者，上肢水平長度亦大於身高。下列何者最能代表其主動脈病變？","options":["(A) 囊狀中膜變性併主動脈剝離","(B) 嚴重粥狀硬化併動脈瘤","(C) 主動脈炎併有淋巴球及漿細胞浸潤","(D) 粥腫併化膿性感染"],"answer":0,"image":""},{"id":"md2-107-2-83","subject":"md2","topic":"病理-心血管血液","meta":"107年第2次第83題","year":107,"session":2,"number":83,"question":"下列何種血液性疾病主要的特徵是骨髓造血功能旺盛，造成骨髓明顯擴張？","options":["(A) 地中海貧血（thalassemia）","(B) 再生不良性貧血（aplastic anemia）","(C) 免疫性血小板缺乏紫斑症（immune thrombocytopenic purpura）","(D) 急性骨髓性白血病（acute myelogenous leukemia）"],"answer":0,"image":""},{"id":"md2-107-2-84","subject":"md2","topic":"病理-心血管血液","meta":"107年第2次第84題","year":107,"session":2,"number":84,"question":"30歲男性病人因一個月以來咳嗽逐漸加劇而求診。病人腋窩有數個小淋巴結節，脾尖可以摸到。血色素10.2 g/dl稍低，白血球甚高，血小板下降。血液抹片如附圖。最可能的診斷為：","options":["(A) 急性骨髓性白血病（acute myelogenous leukemia）","(B) 漿細胞性白血病（plasma cell leukemia）","(C) 慢性淋巴球性白血病（chronic lymphocytic leukemia）","(D) 急性淋巴母細胞白血病（acute lymphoblastic leukemia）"],"answer":0,"image":"md2-107-2-84.jpeg"},{"id":"md2-107-2-85","subject":"md2","topic":"病理-呼吸消化","meta":"107年第2次第85題","year":107,"session":2,"number":85,"question":"下列有關矽肺症（silicosis）的敘述，何者錯誤？","options":["(A) 盛行率最高的塵肺症","(B) 即使患者停止接觸二氧化矽疾病仍可以持續進展","(C) 患者感染結核病的機率與一般人相近","(D) 疾病晚期可見進展性大量纖維化（progressive massive fibrosis）"],"answer":[0,2],"image":"","answer_note":"更正:第85題答Ａ、Ｃ給分。"},{"id":"md2-107-2-86","subject":"md2","topic":"病理-呼吸消化","meta":"107年第2次第86題","year":107,"session":2,"number":86,"question":"肺小細胞癌之特徵，與下列那一項最無關？","options":["(A) 可能分泌ACTH","(B) 形成蜂巢肺","(C) 常會轉移至腎上腺","(D) 咳血，呼吸困難"],"answer":1,"image":""},{"id":"md2-107-2-87","subject":"md2","topic":"病理-呼吸消化","meta":"107年第2次第87題","year":107,"session":2,"number":87,"question":"有關波雷特氏食道（Barrett esophagus）的敘述，下列何者錯誤？","options":["(A) 是逆流性食道炎（reflux esophagitis）的併發症","(B) 好發於白人男性","(C) 是食道腺癌（adenocarcinoma）的危險因子之一","(D) 組織學特徵是在食道壁看見壁細胞（parietal cell）和主細胞（chief cell）"],"answer":3,"image":""},{"id":"md2-107-2-88","subject":"md2","topic":"病理-呼吸消化","meta":"107年第2次第88題","year":107,"session":2,"number":88,"question":"有關肝臟疾病，下列敘述何者錯誤？","options":["(A) 黃麴毒素（aflatoxin）是肝細胞癌的危險因子","(B) 結節性再生性增生（nodular regenerative hyperplasia）中央有星狀的纖維化區域","(C) 肝腺瘤（hepatic adenoma）可能破裂，造成腹腔內出血","(D) 肝母細胞瘤（hepatoblastoma）可出現間質分化（mesenchymal differentiation），例如類骨質，橫紋肌，軟骨等成分"],"answer":1,"image":""},{"id":"md2-107-2-89","subject":"md2","topic":"病理-呼吸消化","meta":"107年第2次第89題","year":107,"session":2,"number":89,"question":"在生產過程中，從母親傳給嬰兒的肝炎病毒，下列何者最常見？","options":["(A) A型","(B) B型","(C) C型","(D) D型"],"answer":1,"image":""},{"id":"md2-107-2-90","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"107年第2次第90題","year":107,"session":2,"number":90,"question":"下列何種腎絲球疾病的顯微變化，經銀染色可見腎絲球微血管壁呈現雙層（double contour）或車軌（tram- track）的形式？","options":["(A) 微小變化腎病（minimal change disease）","(B) 膜性腎絲球腎炎（membranous glomerulonephritis）","(C) 局部分葉性腎絲球硬化（focal segmental glomerulosclerosis）","(D) 膜增殖性腎絲球腎炎（membranoproliferative glomerulonephritis）"],"answer":3,"image":""},{"id":"md2-107-2-91","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"107年第2次第91題","year":107,"session":2,"number":91,"question":"45歲女性，有間歇性恥骨上方疼痛、頻尿、血尿及排尿疼痛。病理顯微變化可見膀胱黏膜有慢性潰瘍，膀胱壁有慢性發炎細胞浸潤及纖維化。下列何者為最可能的診斷？","options":["(A) 息肉狀膀胱炎","(B) 濾泡性膀胱炎","(C) 間質性膀胱炎","(D) 出血性膀胱炎"],"answer":2,"image":""},{"id":"md2-107-2-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"107年第2次第92題","year":107,"session":2,"number":92,"question":"有關睪丸的精細胞瘤（seminoma）之敘述，下列何者錯誤？","options":["(A) 類似腫瘤也可發生在卵巢或中樞神經系統","(B) 常發生在嬰兒","(C) 是對放射治療敏感的腫瘤","(D) 腫瘤細胞通常不含α-fetoprotein"],"answer":1,"image":""},{"id":"md2-107-2-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"107年第2次第93題","year":107,"session":2,"number":93,"question":"有關子宮內膜癌的敘述，下列何者錯誤？","options":["(A) 第一型與動情素（estrogen）的刺激較有關","(B) 漿液性癌（serous carcinoma）屬於第一型","(C) 第二型的預後較不好","(D) 子宮內膜增生是第一型的前驅病灶"],"answer":1,"image":""},{"id":"md2-107-2-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"107年第2次第94題","year":107,"session":2,"number":94,"question":"31歲女性，在懷孕第35週時出現高血壓，水腫，蛋白尿，和肝功能異常。下列有關此病的敘述何者錯誤？","options":["(A) 此病較易發生在多次懷孕的婦女","(B) 病人易有血小板低下","(C) 肝臟會出現纖維蛋白血栓（fibrin thrombi）","(D) 引產是對此病人的合適治療方法"],"answer":0,"image":""},{"id":"md2-107-2-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"107年第2次第95題","year":107,"session":2,"number":95,"question":"30歲女性，最近幾天發覺右側乳頭有血樣分泌物而就醫。身體檢查發現乳頭並無凹陷，乳房皮膚亦無異常，觸診時並未發現有腫塊存在，腋下淋巴結無腫大現象。她月經週期正常且以口服避孕藥避孕。她的乳房切片檢查最可能出現何種形態變化？","options":["(A) 乳突狀構造","(B) 嗜中性白血球浸潤","(C) 乳頭表皮出現惡性細胞浸潤","(D) 多發性乳管囊狀擴張及乳管周圍組織纖維化"],"answer":0,"image":""},{"id":"md2-107-2-96","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"107年第2次第96題","year":107,"session":2,"number":96,"question":"8歲女童，有一小腦囊性腫瘤（cystic tumor），腫瘤細胞為（gliofibrillary acidic protein, GFAP）陽性之毛狀星狀膠原細胞，細胞排列呈兩相型（biphasic pattern），下列敘述何者正確？","options":["(A) 腫瘤生長迅速","(B) 同類腫瘤亦常見於老年人的大腦","(C) 常見到羅森賽纖維（Rosenthal fibers）","(D) 腫瘤細胞廣泛浸潤於周圍的腦組織"],"answer":2,"image":""},{"id":"md2-107-2-97","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"107年第2次第97題","year":107,"session":2,"number":97,"question":"下列有關腦部小窩性梗塞（lacunar infarcts）的敘述，何者錯誤？","options":["(A) 最常出現於高血壓","(B) 最常出現在基底核","(C) 不超過15毫米","(D) 係播散性血管內凝血（DIC）的結果"],"answer":3,"image":""},{"id":"md2-107-2-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"107年第2次第98題","year":107,"session":2,"number":98,"question":"一名不足1000公克的早產兒以高濃度氧氣治療，常見的後遺症之一是：","options":["(A) 原發性青光眼（primary glaucoma）","(B) 霰粒腫（chalazion）","(C) 交感性眼炎（sympathetic ophthalmia）","(D) 水晶體後纖維增生（retrolental fibroplasia）"],"answer":3,"image":""},{"id":"md2-107-2-99","subject":"md2","topic":"病理-呼吸消化","meta":"107年第2次第99題","year":107,"session":2,"number":99,"question":"誤食農藥，造成呼吸困難，肺部彈性降低（low compliance），X光顯示瀰漫性肺陰影。其診斷最有可能是：","options":["(A) 成人呼吸窘迫症候群（ARDS）","(B) 肺氣腫（pulmonary emphysema）","(C) 急性氣管炎（acute bronchitis）","(D) Wegener氏肉芽腫病（Wegener's granulomatosis）"],"answer":0,"image":""},{"id":"md2-107-2-100","subject":"md2","topic":"病理-呼吸消化","meta":"107年第2次第100題","year":107,"session":2,"number":100,"question":"承上題，上述病症最有可能的組織變化為：","options":["(A) 瀰漫性肺泡傷害","(B) 肺泡擴大","(C) 肉芽腫性血管炎","(D) 嗜中性白血球浸潤"],"answer":0,"image":""},{"id":"md2-108-1-1","subject":"md2","topic":"細菌學","meta":"108年第1次第1題","year":108,"session":1,"number":1,"question":"肺炎鏈球菌（Streptococcus pneumoniae）對青黴素（penicillin）產⽣抗性之原因，主要為下列何者？","options":["(A) 產⽣青黴素分解酶（penicillinase）","(B) 青黴素結合蛋⽩質（penicillin-binding protein）改變","(C) 阻擋青黴素進入菌體","(D) 細胞壁結構改變"],"answer":1,"image":""},{"id":"md2-108-1-2","subject":"md2","topic":"藥理-化學治療","meta":"108年第1次第2題","year":108,"session":1,"number":2,"question":"對受到禽型分枝桿菌群（Mycobacterium avium Complex, MAC）感染的病患，建議使⽤下列那⼀種藥物合併 ⼄胺丁醇（ethambutol）及利福布丁（rifabutin）進⾏治療？","options":["(A) 阿奇黴素（azithromycin）","(B) 硝基甲嘧唑⼄醇（metronidazole）","(C) 克拉維酸（clavulanic acid）","(D) 棘⽩菌素（echinocandin）"],"answer":0,"image":""},{"id":"md2-108-1-3","subject":"md2","topic":"細菌學","meta":"108年第1次第3題","year":108,"session":1,"number":3,"question":"有關細菌抗藥性之敘述，下列何者錯誤？","options":["(A) 廣泛抗藥性結核桿菌（XDR-TB）比多重抗藥性結核桿菌（MDR-TB）抗更多種藥物","(B) 厭氧菌通常對胺基糖苷類（aminoglycosides）藥物具感受性","(C) 具新德⾥⾦屬β-內酰胺酶（NDM）之細菌，對⼤多β-內酰胺（β-lactams）有抗藥性","(D) 細菌青黴素結合蛋⽩質（penicillin-binding protein）之改變會導致對青黴素（penicillin）產⽣抗性"],"answer":1,"image":""},{"id":"md2-108-1-4","subject":"md2","topic":"細菌學","meta":"108年第1次第4題","year":108,"session":1,"number":4,"question":"關於細菌致病島（pathogenicity island）之敘述，下列何者錯誤？","options":["(A) 可位於細菌的染⾊體（chromosome）或質體（plasmid）中","(B) 不存在於轉位⼦（transposon）之中","(C) 可被單⼀因⼦活化，例如：溫度或pH值的改變","(D) 由多數基因所組成，可製造多種致病因⼦（virulence factors）"],"answer":1,"image":""},{"id":"md2-108-1-5","subject":"md2","topic":"細菌學","meta":"108年第1次第5題","year":108,"session":1,"number":5,"question":"關於單核細胞增多性李斯特菌（Listeria monocytogenes）的敘述，下列何者錯誤？","options":["(A) 是具運動性（motile）的⾰蘭⽒陽性菌","(B) 可在細胞質內複製，且利⽤肌動蛋⽩（actin）移動⾄鄰近細胞","(C) 主要感染⽅式為吃進受此菌汙染的食物","(D) 此菌能形成內芽胞（endospores）在低溫存活"],"answer":3,"image":""},{"id":"md2-108-1-6","subject":"md2","topic":"細菌學","meta":"108年第1次第6題","year":108,"session":1,"number":6,"question":"對於細菌莢膜（capsule）之敘述，下列何者正確？","options":["(A) 主要成分為胜肽聚醣（peptidoglycan）","(B) 所有細菌皆有多醣類莢膜","(C) 導致⾰蘭⽒染⾊（Gram stain）反應的主要原因","(D) 能幫助細菌抵抗吞噬作⽤（phagocytosis）"],"answer":3,"image":""},{"id":"md2-108-1-7","subject":"md2","topic":"細菌學","meta":"108年第1次第7題","year":108,"session":1,"number":7,"question":"對於⾁毒桿菌（Clostridium botulinum）的敘述，下列何者錯誤？","options":["(A) ⾁毒素（Botulinum toxin）主要使細胞內的Rho-GTPase失去活性","(B) 食入受此菌汙染的罐頭食品會造成⾁毒症","(C) 嬰兒食入受到此菌芽胞污染的食物會造成⾁毒症","(D) ⾁毒素可做為⽣化武器，造成吸入性⾁毒症（inhalation botulism）"],"answer":0,"image":""},{"id":"md2-108-1-8","subject":"md2","topic":"細菌學","meta":"108年第1次第8題","year":108,"session":1,"number":8,"question":"關於韋爾病（Weil disease）的敘述，下列何者錯誤？","options":["(A) 其致病菌屬螺旋體（spirochete）","(B) 包括黃疸、腎衰竭、廣泛⾎管炎、⼼肌炎等臨床症狀","(C) 多數感染與從事⽔中活動或接觸動物有關","(D) 常由患者糞便中分離到致病菌"],"answer":3,"image":""},{"id":"md2-108-1-9","subject":"md2","topic":"藥理-化學治療","meta":"108年第1次第9題","year":108,"session":1,"number":9,"question":"有關細菌23S rRNA甲基化（methylation）會導致對下列那種藥物產⽣抗性？","options":["(A) 慶⼤黴素（Gentamicin）","(B) 磺胺甲基異唑（Sulfamethoxazole）","(C) 四環黴素（Tetracycline）","(D) 克林黴素（Clindamycin）"],"answer":3,"image":""},{"id":"md2-108-1-10","subject":"md2","topic":"病毒學","meta":"108年第1次第10題","year":108,"session":1,"number":10,"question":"下列那⼀種病毒有兩條單股RNA基因體，其中⼀條為雙義（ambisense）RNA？","options":["(A) 拉薩病毒（Lassa virus）","(B) 登⾰病毒（Dengue virus）","(C) 中東呼吸症候群冠狀病毒（MERS-CoV）","(D) 克⾥米亞-剛果出⾎熱病毒（Crimean-Congo hemorrhagic fever virus）"],"answer":0,"image":""},{"id":"md2-108-1-11","subject":"md2","topic":"病毒學","meta":"108年第1次第11題","year":108,"session":1,"number":11,"question":"關於EB病毒的敘述，下列何者正確？","options":["(A) 受EB病毒感染的成⼈，通常會出現帶狀疱疹","(B) 在愛滋病⼈體內，EB病毒主要感染T細胞，造成T細胞的過度增⽣","(C) 在⿐咽癌病⼈⾎液中，會偵測到抗EB病毒蛋⽩質的抗體⼒價上升","(D) EB病毒感染B細胞之後，會進入潛伏狀態，完全不表現任何病毒RNA或蛋⽩質，以躲避免疫系統攻擊"],"answer":2,"image":""},{"id":"md2-108-1-12","subject":"md2","topic":"病毒學","meta":"108年第1次第12題","year":108,"session":1,"number":12,"question":"有關傳染性蛋⽩質（Prion）的敘述，下列何者正確？","options":["(A) 具有抗原性","(B) 可被福⾺林及紫外線去除活性","(C) 無法有效刺激宿主產⽣⼲擾素（interferon）","(D) 會造成肺泡細胞堅實化病變"],"answer":2,"image":""},{"id":"md2-108-1-13","subject":"md2","topic":"病毒學","meta":"108年第1次第13題","year":108,"session":1,"number":13,"question":"下列何種流感病毒蛋⽩質是屬於質⼦通道（proton channel），與病毒釋放到細胞質有關？","options":["(A) 基質蛋⽩質（matrix protein, M1）","(B) 膜蛋⽩質（membrane protein, M2）","(C) 核殼體蛋⽩質（nucleocapsid protein, NP）","(D) RNA聚合酶（polymerase, PA）"],"answer":1,"image":""},{"id":"md2-108-1-14","subject":"md2","topic":"病毒學","meta":"108年第1次第14題","year":108,"session":1,"number":14,"question":"對於痘科病毒（Poxvirus）的敘述，下列何者正確？","options":["(A) 天花的撲滅，是因為全⾯接種猴痘科（monkeypox）病毒的死毒疫苗","(B) 天花的撲滅，是因為全⾯接種天花病毒（variola virus）的減毒疫苗","(C) 猴痘科病毒對動物的感染⽬前仍然流傳於非洲，但不會感染⼈類","(D) 痘科病毒感染細胞後的複製過程在細胞質內進⾏，不需要宿主的DNA複製系統協助"],"answer":3,"image":""},{"id":"md2-108-1-15","subject":"md2","topic":"病毒學","meta":"108年第1次第15題","year":108,"session":1,"number":15,"question":"關於嬰兒玫瑰疹（roseola）的敘述，下列何者錯誤？","options":["(A) 可由⼈類疱疹第六型病毒（human herpesvirus 6）感染所造成","(B) 被感染的成⼈有可能產⽣單核球增多症（mononucleosis）","(C) 被感染的幼兒通常不會發燒","(D) 病⼈體內的病毒會在Ｔ細胞內造成潛伏性感染（latent infection）"],"answer":2,"image":""},{"id":"md2-108-1-16","subject":"md2","topic":"真菌學","meta":"108年第1次第16題","year":108,"session":1,"number":16,"question":"有關⾺爾尼菲青黴菌（Talaromyces marneffer; formerly Penicillium memeffei）之敘述，下列何者正確？","options":["(A) 37℃呈絲狀菌（hyphae）形態","(B) 具關節孢⼦（arthroconidia）","(C) 不會呈現類酵⺟菌（yeast-like）型態","(D) 主要感染途徑為呼吸道（respiratory tract）"],"answer":[1,3],"image":"","answer_note":"更正:第16題答Ｂ、Ｄ給分"},{"id":"md2-108-1-17","subject":"md2","topic":"真菌學","meta":"108年第1次第17題","year":108,"session":1,"number":17,"question":"培養莢膜組織胞漿菌（Histoplasma capsulatum）時，為防⽌其他汙染真菌之⼲擾，通常於培養基中加入下列何者？","options":["(A) 環絲胺酸（Cycloserine）","(B) 放線菌酮（Cycloheximide）","(C) 氯法⿑明（Clofazimine）","(D) 奎奴普丁（Quinupristin）"],"answer":1,"image":""},{"id":"md2-108-1-18","subject":"md2","topic":"免疫學","meta":"108年第1次第18題","year":108,"session":1,"number":18,"question":"巨噬細胞（macrophage）和嗜中性球（neutrophil）是體內最主要的吞噬細胞，它們都具有吞噬（phagocytosis）並殺死病原的能⼒，有關這兩群細胞的敘述何者錯誤？","options":["(A) 當嗜中性球被細菌活化後，會進⾏⼀種特殊的細胞死亡的過程，把核內的染⾊質（chromatin）釋放到細胞外的空間形成neutrophil extracellular traps（NETs），有效的抓住微⽣物","(B) 這兩群細胞在受到細菌刺激後都會進⾏所謂的呼吸爆發（respiratory burst）的現象，這是因為胞內酵素的作⽤，導致超氧離⼦（superoxide）的⽣成與⼆氧化碳⼤量釋出，藉以殺死細菌","(C) 巨噬細胞在各個器官及組織都存在，比如在肝臟的庫⽒細胞（Kupffer cell）及神經組織中的⼩神經膠質細胞（microglia）等都是特化的巨噬細胞","(D) 如果NADPH氧化酶（oxidase）的基因發⽣突變⽽失去功能，會導致這兩群主要的吞噬細胞不能有效地殺死病原，結果造成慢性⾁芽腫病（chronic granulomatous disease, CGD）"],"answer":1,"image":""},{"id":"md2-108-1-19","subject":"md2","topic":"免疫學","meta":"108年第1次第19題","year":108,"session":1,"number":19,"question":"⼤部分⼈體內成熟T細胞上之TCR為α-chain及β-chain所組成，故稱為αβ T cells。當比對TCR α-chain及β- chain的DNA序列時，發現β-chain比α-chain多出了下列何種基因片段？","options":["(A) V","(B) D","(C) J","(D) C"],"answer":1,"image":""},{"id":"md2-108-1-20","subject":"md2","topic":"免疫學","meta":"108年第1次第20題","year":108,"session":1,"number":20,"question":"成熟的淋巴球在發育過程中會利⽤各種機制來達成⾃我耐受性（self-tolerance），下列何者和達成⾃我耐受性有直接的相關性？①AIRE基因②CTLA-4基因③Fas基因④正向選擇（positive selection）⑤負向選擇（negative selection）⑥regulatory T細胞形成","options":["(A) ①②③④⑥","(B) ①②③⑤⑥","(C) 僅②③⑤⑥","(D) 僅①②③⑤"],"answer":1,"image":""},{"id":"md2-108-1-21","subject":"md2","topic":"免疫學","meta":"108年第1次第21題","year":108,"session":1,"number":21,"question":"下列何種細胞素，並非毒殺性CD8 T細胞（cytotoxic CD8 T cells）所分泌來執⾏細胞毒殺功能？","options":["(A) TNF-α","(B) TGF-β","(C) LT-α","(D) IFN-γ"],"answer":1,"image":""},{"id":"md2-108-1-22","subject":"md2","topic":"免疫學","meta":"108年第1次第22題","year":108,"session":1,"number":22,"question":"胸腺依賴性（thymus-dependent）抗原活化B細胞需要輔助型T細胞的參與，⽽且這兩種細胞所辨識的抗原是存在⼀種相關性辨識（linked recognition）的關係，有關相關性辨識的敘述，何者錯誤？","options":["(A) 如果⼀個B細胞的抗原接受器是辨識⼀種病毒的表⾯蛋⽩，⽽輔助型T細胞的抗原接受器是辨識此病毒內部的核⼼蛋⽩，這個輔助型T細胞是無法協助前述B細胞的活化","(B) 相關性辨識可以確保⾃我耐受性（self-tolerance）的產⽣，因為對⾃體有反應的（self-reactive）T細胞必須碰到對⾃體有反應的B細胞才能引起⾃體抗體（autoantibody）的產⽣，⽽這種機率相當低","(C) 我們可以利⽤相關性辨識的概念來設計疫苗幫助嬰兒產⽣有效的抗體，去對付具有莢膜構造的病菌，比如流感嗜⾎桿菌（Haemophilus influenzae）","(D) 很多⼈對盤尼⻄林（penicillin）過敏的原因是因為盤尼⻄林注射到體內會和⾃體的蛋⽩形成聚合物，此聚合物會誘發T2細胞的⽣成，再藉著相關性辨識去活化B細胞產⽣IgE引起過敏反應H"],"answer":0,"image":""},{"id":"md2-108-1-23","subject":"md2","topic":"免疫學","meta":"108年第1次第23題","year":108,"session":1,"number":23,"question":"在黏膜產⽣的分泌型IgA（secretary IgA）⼤部分為：","options":["(A) 單體（monomer）","(B) ⼆聚體（dimer）","(C) 三聚體（trimer）","(D) 五聚體（pentamer）"],"answer":1,"image":""},{"id":"md2-108-1-24","subject":"md2","topic":"免疫學","meta":"108年第1次第24題","year":108,"session":1,"number":24,"question":"⾼免疫球蛋⽩M症候群（hyper-IgM syndrome）是⼀種罕⾒的先天性免疫不全疾病，患者⾎清中除了IgM之外其他類型，例如IgG和IgA數值明顯低於平均值，造成病患容易感染。B細胞中特定基因的缺陷會造成B細胞無法產⽣類型轉換（class switching），但是T細胞的基因突變也可以導致相同的疾病。以下那個蛋⽩質缺陷會造成T細胞無法幫助B細胞類型轉換？","options":["(A) AID（activation-induced cytidine deaminase）","(B) CD40","(C) CD40 ligand","(D) NEMO（NF-κB essential modulator，或稱IKK γ）"],"answer":2,"image":""},{"id":"md2-108-1-25","subject":"md2","topic":"免疫學","meta":"108年第1次第25題","year":108,"session":1,"number":25,"question":"針對可以引起氣喘等第⼀型過敏性疾病之過敏原，下列那⼀項敘述最正確？","options":["(A) 與⼀般抗原相同，都需經抗原呈獻細胞作⽤來活化T細胞","(B) 同卵雙胞胎對特定過敏原都會有相同的反應","(C) 都具有蛋⽩⽔解酶（protease）的功能","(D) 病⼈體內都可以檢測出對過敏原具特異性的IgE"],"answer":0,"image":""},{"id":"md2-108-1-26","subject":"md2","topic":"免疫學","meta":"108年第1次第26題","year":108,"session":1,"number":26,"question":"下列⾃體免疫疾病中，何者侵犯不⽌⼀處組織，屬於系統性疾病？","options":["(A) ⾃體溶⾎性貧⾎（autoimmune hemolytic anemia）","(B) ⾃體免疫愛迪森疾患（autoimmune Addison's disease）","(C) Hashimoto's thyroiditis","(D) 類風濕性關節炎（rheumatoid arthritis）"],"answer":3,"image":""},{"id":"md2-108-1-27","subject":"md2","topic":"免疫學","meta":"108年第1次第27題","year":108,"session":1,"number":27,"question":"下列⽤來治療癌症的抗體，何者屬於checkpoint blockade療法？","options":["(A) Avastin（anti-VEGF antibody）","(B) Pembrolizumab（anti-PD-1 antibody）","(C) Rituximab（anti-CD20 antibody）","(D) Trastuzumab（anti-HER2/neu antibody）"],"answer":1,"image":""},{"id":"md2-108-1-28","subject":"md2","topic":"免疫學","meta":"108年第1次第28題","year":108,"session":1,"number":28,"question":"藉由抑制破骨細胞（osteoclast cell）的活化，可以改善骨質流失的藥物為何？","options":["(A) Infliximab（anti-TNF-α）","(B) Denosumab（anti-RANK-L）","(C) Daclizumab（anti-IL-2R）","(D) Belimumab（anti-BLyS）"],"answer":1,"image":""},{"id":"md2-108-1-29","subject":"md2","topic":"寄生蟲學","meta":"108年第1次第29題","year":108,"session":1,"number":29,"question":"下列有關⼈體感染海獸胃線蟲（Anisakis spp.）的敘述，何者錯誤？","options":["(A) 必須經過在2種中間宿主中發育後，才具有感染⼈之能⼒","(B) 必須檢查糞便內蟲卵才能確認感染","(C) 通常吃海⽔⿂⽣⿂片⽽感染","(D) 感染後常引起急性腹痛"],"answer":1,"image":""},{"id":"md2-108-1-30","subject":"md2","topic":"寄生蟲學","meta":"108年第1次第30題","year":108,"session":1,"number":30,"question":"有關班⽒絲蟲（Wuchereria bancrofti）的感染，下列敘述何者錯誤？","options":["(A) 病媒蚊吸⾎時直接將微絲蟲（microfilaria）注入⼈體","(B) 蟲體在淋巴管發育為成蟲","(C) 只有在夜間微絲蟲（microfilaria）才會⼤量出現在末梢⾎液","(D) 在乳糜尿（chyluria）中也可能發現微絲蟲（microfilaria）"],"answer":0,"image":""},{"id":"md2-108-1-31","subject":"md2","topic":"寄生蟲學","meta":"108年第1次第31題","year":108,"session":1,"number":31,"question":"于先⽣因嗜愛美食⽽食⽤浸酒⽑蟹（醉蟹）多年，⽇前因不明原因發燒、咳嗽、胸痛及⼤量帶⾎絲濃痰（blood-tinged sputum）⽽就醫，經醫院檢查發現痰液內有許多深褐⾊蟲卵及卡格⾥登結晶（Charcot- Leyden crystals)，胸部X光顯⽰有斑狀浸潤及結節狀囊體陰影，並有胸膜積⽔（pleural effusion）及嗜酸性 ⽩⾎球增多（eosinophilia）現象。依據以上敘述，于先⽣最可能感染何種寄⽣蟲？","options":["(A) 異形吸蟲（Heterophyes heterophyes）","(B) ⽇本⾎吸蟲（Schistosoma japonicum）","(C) 薑片蟲（Fasciolopsis buski）","(D) 衛⽒肺吸蟲（Paragonimus westermani）"],"answer":3,"image":""},{"id":"md2-108-1-32","subject":"md2","topic":"寄生蟲學","meta":"108年第1次第32題","year":108,"session":1,"number":32,"question":"下列有關⼈罹患豬囊尾幼蟲症（cysticercosis cellulosae）的敘述，何者錯誤？","options":["(A) 食入未熟帶蟲之豬⾁，其囊蟲侵犯內臟器官致病","(B) 也會在肌⾁致病","(C) 病患可能發⽣癲癇（epilepsy）","(D) ⾎清抗體檢查有助於診斷"],"answer":0,"image":""},{"id":"md2-108-1-33","subject":"md2","topic":"寄生蟲學","meta":"108年第1次第33題","year":108,"session":1,"number":33,"question":"下列有關寄⽣蟲之敘述中，何者錯誤？","options":["(A) 瘧疾發作（paroxysm）之過程依序為：惡寒（chill）、發燒（fever）、發汗（sweat）","(B) 三⽇瘧原蟲（Plasmodium malariae）較喜侵入成熟的紅⾎球中分裂增殖","(C) 卵形瘧原蟲（Plasmodium ovale）之鑑定，常視患者⾎液抹片是否有帶狀型滋養體（band form trophozoites）","(D) 在瘧疾流⾏地區，六個⽉以下的嬰兒常因為得⾃⺟體抗體的保護作⽤，甚少罹患瘧疾"],"answer":2,"image":""},{"id":"md2-108-1-34","subject":"md2","topic":"寄生蟲學","meta":"108年第1次第34題","year":108,"session":1,"number":34,"question":"下列有關阿米巴之敘述中，何者正確？","options":["(A) 嗜碘阿米巴（Iodamoeba bütschlii）的滋養體（trophozoites）具有⼀個很⼤的肝醣泡（glycogen vacuole）","(B) 哈⽒阿米巴（Entamoeba hartmanni）的滋養體（trophozoites）也會吞噬紅⾎球","(C) 痢疾阿米巴（Entamoeba histolytica）感染之⾼危險群包括男同性戀者及啟智、精神教養院⽣","(D) 痢疾阿米巴（Entamoeba histolytica）的囊體中的類染⾊體（chromatoid bodies）之成分是DNA"],"answer":2,"image":""},{"id":"md2-108-1-35","subject":"md2","topic":"寄生蟲學","meta":"108年第1次第35題","year":108,"session":1,"number":35,"question":"有關蠅蛆症（myiasis）之敘述，下列何者錯誤？","options":["(A) ⼈膚蠅（Dermatobia hominis）產卵於吸⾎性蚊/蠅之腹部⽽致孵化之幼蟲鑽入宿主⽪膚傷⼝","(B) 院內蠅蛆症（nosocomial myiasis）常發⽣於⻑期臥床且有開放性傷⼝病患","(C) ⽿部蠅蛆症（aural myiasis）病患常有蟲體爬動感、雜⾳及惡臭分泌物","(D) ⼈膚蠅（Dermatobia hominis）傳播之蠅蛆症經常發⽣於亞洲地區"],"answer":3,"image":""},{"id":"md2-108-1-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"108年第1次第36題","year":108,"session":1,"number":36,"question":"關於測量尺度（measurement scale）的敘述，下列何者正確？","options":["(A) ⾎型為序位尺度（ordinal scale）","(B) 膽固醇值（mg／100 ml）為等比尺度（ratio scale）","(C) 體溫（攝⽒度C）為等比尺度（ratio scale）","(D) 癌症分期為等距尺度（interval scale）"],"answer":1,"image":""},{"id":"md2-108-1-37","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"108年第1次第37題","year":108,"session":1,"number":37,"question":"下⾯的傳染病中，何者是臺灣傳染病通報分級中的第⼀類（必須立即通報）？","options":["(A) 狂⽝病","(B) ⽇本腦炎","(C) 瘧疾","(D) 梅毒"],"answer":0,"image":""},{"id":"md2-108-1-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"108年第1次第38題","year":108,"session":1,"number":38,"question":"⼀研究想比較抽菸者與非抽菸者的⾎膽固醇濃度，下列敘述何者錯誤？","options":["(A) 檢定時犯下型⼀錯誤（type I error）的機率，即為研究者設定的顯著⽔準","(B) 若顯著⽔準不變，欲增加統計檢定⼒，可以增加樣本數","(C) 型⼀錯誤是抽菸者與非抽菸者的⾎膽固醇濃度沒差異，但檢定時卻誤判有差異的情形","(D) 型⼀錯誤加型⼆錯誤的機率和為1"],"answer":3,"image":""},{"id":"md2-108-1-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"108年第1次第39題","year":108,"session":1,"number":39,"question":"疾病篩檢以平⾏檢定（Simultaneous Testing）為之，對篩檢效度有何影響？","options":["(A) 淨敏感度（Net sensitivity）增加","(B) 淨特異度（Net specificity）增加","(C) 淨特異度（Net specificity）減少","(D) 偽陽性率（False positive rate）增加"],"answer":0,"image":""},{"id":"md2-108-1-40","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"108年第1次第40題","year":108,"session":1,"number":40,"question":"某研究想探討吸菸與肺功能值的關係，將受試者依吸菸狀況分為五組：①本⼈不吸菸⼯作環境也無⼈吸菸② 本⼈不吸菸但⼯作環境很多⼈吸菸③本⼈吸菸程度輕微④本⼈吸菸程度中等⑤本⼈吸菸程度嚴重。每組找100⼈，測量每個⼈的某肺功能指標。假如我們要檢定這五種吸菸狀況下的肺功能平均值是否不同，下列那 ⼀種統計分析⽅法最適當？","options":["(A) 獨立t檢定","(B) 配對t檢定","(C) ⽪爾森⽒卡⽅檢定","(D) 單因⼦變異數分析"],"answer":3,"image":""},{"id":"md2-108-1-41","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"108年第1次第41題","year":108,"session":1,"number":41,"question":"研究臺灣各鄉鎮市區空氣污染與癌症發⽣之關係，空氣污染資料來⾃環保署，⽽癌症發⽣資料來⾃衛⽣福利部，這些資料除了性別與年齡外無個⼈⽣活相關資料，則該研究屬何種？","options":["(A) 個案報告（case report）","(B) ⽣態學研究（ecological study）","(C) 病例對照研究（case-control study）","(D) 世代研究（cohort study）"],"answer":1,"image":""},{"id":"md2-108-1-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第1次第42題","year":108,"session":1,"number":42,"question":"那些空氣污染物會造成酸雨效應？①⼀氧化碳②臭氧③硫氧化物④氮氧化物","options":["(A) 僅①②","(B) ①②③","(C) 僅③④","(D) ②③④"],"answer":2,"image":""},{"id":"md2-108-1-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第1次第43題","year":108,"session":1,"number":43,"question":"下列那⼀選項，最適⽤於描述非致癌物之風險評估？","options":["(A) 劑量反應假設具有閾值存在","(B) 使⽤斜率因⼦進⾏風險計算","(C) -6量化結果⼀般與10比較，以判定風險是否可接受","(D) 不適合進⾏不確定性分析"],"answer":0,"image":""},{"id":"md2-108-1-44","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第1次第44題","year":108,"session":1,"number":44,"question":"傳染登⾰熱的病媒蚊是下列何者？","options":["(A) 熱帶家蚊、⽩腹叢蚊","(B) 埃及斑蚊、⽩線斑蚊","(C) ⽩腹叢蚊、⼩⿊蚊","(D) 中華瘧蚊、熱帶家蚊"],"answer":1,"image":""},{"id":"md2-108-1-45","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第1次第45題","year":108,"session":1,"number":45,"question":"某勞⼯每⽇⼯作八⼩時，假設每⼀個⼩時之前10分鐘暴露於60 ppm之甲苯，後50分鐘則未暴露，其八⼩時時量平均暴露濃度為何？","options":["(A) 10 ppm","(B) 15 ppm","(C) 20 ppm","(D) 60 ppm"],"answer":0,"image":""},{"id":"md2-108-1-46","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第1次第46題","year":108,"session":1,"number":46,"question":"⼯⼈⻑期暴露在有機溶劑環境中，會產⽣許多危害，⻑期暴露於苯，最可能會發⽣那種癌症？","options":["(A) ⾎癌","(B) 肝癌","(C) 腎癌","(D) ⽪膚癌"],"answer":0,"image":""},{"id":"md2-108-1-47","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第1次第47題","year":108,"session":1,"number":47,"question":"根據衛⽣福利部定義我國成⼈肥胖的BMI（Body Mass Index）切點為何？","options":["(A) 25","(B) 27","(C) 29","(D) 31"],"answer":1,"image":""},{"id":"md2-108-1-48","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第1次第48題","year":108,"session":1,"number":48,"question":"下列那個模式最適合⽤來解釋「在有可能罹患癌症的⾼危險群中，為何有些⼈會去使⽤癌症篩檢的服務，⽽ 有些⼈卻不會去使⽤」之⾏為？","options":["(A) 跨理論模式（the transtheoretical model）","(B) 社會⾏銷（social marketing）","(C) 健康信念模式（health belief model）","(D) 創新擴散理論（diffusion of innovations）"],"answer":2,"image":""},{"id":"md2-108-1-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"108年第1次第49題","year":108,"session":1,"number":49,"question":"醫療費⽤的成⻑率跟下列那⼀個因素關聯性較⼩？","options":["(A) ⼈⼝老化","(B) 所得增加","(C) 醫療科技進步","(D) 醫病資訊不對稱"],"answer":3,"image":""},{"id":"md2-108-1-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"108年第1次第50題","year":108,"session":1,"number":50,"question":"原開發廠的新藥成本較⾼，售價昂貴的原因，以下那⼀項因素的影響較⼩？","options":["(A) 研究及發展費⽤","(B) 專利權的保護","(C) 臨床試驗的花費","(D) ⽣產製造的成本"],"answer":3,"image":""},{"id":"md2-108-1-51","subject":"md2","topic":"藥理-化學治療","meta":"108年第1次第51題","year":108,"session":1,"number":51,"question":"下列何者不是抗⽣素metronidazole之臨床⽤途？","options":["(A) 腹腔內厭氧菌感染，例如：C. difficile感染","(B) 陰道滴蟲（T. vaginalis）引起之感染","(C) 淋病球菌（N. gonorrhoeae）引起之感染","(D) 阿米巴原蟲（E. histolytica）引起之結腸發炎"],"answer":2,"image":""},{"id":"md2-108-1-52","subject":"md2","topic":"藥理-化學治療","meta":"108年第1次第52題","year":108,"session":1,"number":52,"question":"王⼩姐45歲，未婚，最近發現左側乳房有⼩塊腫瘤，經醫師診斷為乳癌，進⾏⼿術切除後，並給予cyclophosphamide, methotrexate及5-fluorouracil癌症化學治療，下列藥物與機轉之配對何者正確？","options":["(A) cyclophosphamide & methotrexate：抑制topoisomerase II","(B) methotrexate & 5-fluorouracil：抑制有絲分裂（mitosis）","(C) methotrexate & 5-fluorouracil：抗代謝藥物（anti-metabolites）","(D) cyclophosphamide & 5-fluorouracil：DNA烷基化物（DNA alkylating agents）"],"answer":2,"image":""},{"id":"md2-108-1-53","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"108年第1次第53題","year":108,"session":1,"number":53,"question":"下列何種藥物不是⾎⼩板凝集之拮抗劑？","options":["(A) dipyridamole","(B) aspirin","(C) heparin","(D) ticlopidine"],"answer":2,"image":""},{"id":"md2-108-1-54","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第1次第54題","year":108,"session":1,"number":54,"question":"有關多巴胺受體作⽤劑（dopamine receptor agonist）bromocriptine的作⽤敘述，下列何者錯誤？","options":["(A) 在臨床上可以⽤來治療⾼泌乳素⾎症（hyperprolactinemia），主要係透過減少泌乳素的分泌作⽤","(B) 在臨床上可以使⽤於巴⾦森⽒症（Parkinson's disease）的病⼈，改善其運動功能的障礙","(C) 可以有效改善肢端肥⼤症（acromegaly）病⼈的臨床症狀，主要係透過增加體制素（somatostatin）的分泌作⽤","(D) 可以有效改善婦女產後乳房腫脹及泌乳過量的情形"],"answer":2,"image":""},{"id":"md2-108-1-55","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第1次第55題","year":108,"session":1,"number":55,"question":"有關⾎管加壓素（vasopressin）的描述，下列何者錯誤？","options":["(A) 主要由腦下垂體後葉（posterior pituitary）所分泌，具有促進⾎管收縮的作⽤","(B) 於腸胃道中容易被破壞，因此⼝服無效","(C) 可以⽤來治療垂體性尿崩症（pituitary diabetes insipidus）","(D) 具有利尿的作⽤，因此會造成⽔分與鈉離⼦流失"],"answer":3,"image":""},{"id":"md2-108-1-56","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"108年第1次第56題","year":108,"session":1,"number":56,"question":"下列那⼀種利尿劑合併⽣理食鹽⽔注射投與，⽤於治療⾎鈣過⾼之症狀效果最好？","options":["(A) furosemide","(B) hydrochlorothiazide","(C) amiloride","(D) conivaptan"],"answer":0,"image":""},{"id":"md2-108-1-57","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"108年第1次第57題","year":108,"session":1,"number":57,"question":"下列藥物中何者之主要臨床副作⽤為類紅斑性狼瘡症狀？","options":["(A) sotalol","(B) disopyramide","(C) amiodarone","(D) procainamide"],"answer":3,"image":""},{"id":"md2-108-1-58","subject":"md2","topic":"藥理-總論與自主神經","meta":"108年第1次第58題","year":108,"session":1,"number":58,"question":"活化下列何種⾃主神經傳遞物質作⽤的受體，通常會抑制adenylyl cyclase的活性？","options":["(A) muscarinic M cholinoceptor 2","(B) muscarinic M cholinoceptor 3","(C) βadrenoceptor 1","(D) β adrenoceptor 3"],"answer":0,"image":""},{"id":"md2-108-1-59","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"108年第1次第59題","year":108,"session":1,"number":59,"question":"下列藥物何者為PGI致效劑，可⽤於治療肺⾼壓（pulmonary hypertension）？2","options":["(A) treprostinil","(B) alprostadil","(C) misoprostol","(D) latanoprost"],"answer":0,"image":""},{"id":"md2-108-1-60","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"108年第1次第60題","year":108,"session":1,"number":60,"question":"下列何種藥物是作⽤於dopaminergic D receptor⽤於治療帕⾦森⽒症（Parkinsonism）？2","options":["(A) pramipexole","(B) bromocriptine","(C) flurazepam","(D) selegiline"],"answer":1,"image":""},{"id":"md2-108-1-61","subject":"md2","topic":"藥理-化學治療","meta":"108年第1次第61題","year":108,"session":1,"number":61,"question":"下列何者屬於antipseudomonal penicilins，可與aminoglycoside併⽤以治療綠膿桿菌（P. aeruginosa）所引起的感染？","options":["(A) amoxicillin","(B) dicloxacillin","(C) nafcillin","(D) ticarcillin"],"answer":3,"image":""},{"id":"md2-108-1-62","subject":"md2","topic":"藥理-化學治療","meta":"108年第1次第62題","year":108,"session":1,"number":62,"question":"關於抗⽣素ceftriaxone之敘述，下列何者正確？","options":["(A) 為淋病球菌（N. gonorrhoeae）感染的⾸選⽤藥","(B) 屬於第四代cephalosporins","(C) 常和clavulanate併⽤以增強其抗菌效果","(D) 腎衰竭病⼈使⽤此藥時，應降低劑量⾄原治療劑量之⼀半"],"answer":0,"image":""},{"id":"md2-108-1-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"108年第1次第63題","year":108,"session":1,"number":63,"question":"下列何者無助於改善貧⾎？","options":["(A) ⼝服ferrous fumarate","(B) 注射iron dextran","(C) 注射deferoxamine","(D) 補充維⽣素B及葉酸（folic acid）12"],"answer":2,"image":""},{"id":"md2-108-1-64","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第1次第64題","year":108,"session":1,"number":64,"question":"⼀位18歲少女當⽉經來潮時會有腹部疼痛的症狀，醫師詳細檢查發現有骨盆腹膜⼦宮內膜異位的病變。下列何者較適合被⽤來治療這位病⼈？","options":["(A) ⼝服flutamide","(B) 肌⾁注射medroxyprogesterone","(C) 靜脈注射oxandrolone","(D) ⼝服raloxifene"],"answer":1,"image":""},{"id":"md2-108-1-65","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第1次第65題","year":108,"session":1,"number":65,"question":"⼀位40歲男性患有肢端肥⼤的症狀，放射學診斷發現有腦下垂體腫瘤，除了外科⼿術切除腫瘤外。下列何者可以被⽤來治療此種疾病？","options":["(A) desmopressin","(B) octreotide","(C) leuprolide","(D) somatropin"],"answer":1,"image":""},{"id":"md2-108-1-66","subject":"md2","topic":"藥理-總論與自主神經","meta":"108年第1次第66題","year":108,"session":1,"number":66,"question":"下列何種降⾎壓藥物，在⻑期服⽤⾼劑量治療時，若立即停藥會因為強烈增加交感神經活性，可能引發致命性⾼⾎壓？","options":["(A) clonidine","(B) nifedipine","(C) hydralazine","(D) captopril"],"answer":0,"image":""},{"id":"md2-108-1-67","subject":"md2","topic":"藥理-總論與自主神經","meta":"108年第1次第67題","year":108,"session":1,"number":67,"question":"下列何者是直接作⽤型蕈毒鹼致效劑（direct-acting muscarinic agonist），可⽤於治療薛格連⽒症候群（Sjögren's syndrome）或放射線治療引起的⼝乾症？","options":["(A) atropine","(B) cevimeline","(C) neostigmine","(D) succinylcholine"],"answer":1,"image":""},{"id":"md2-108-1-68","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"108年第1次第68題","year":108,"session":1,"number":68,"question":"當偏頭痛患者出現噁⼼、嘔吐等症狀時，下列何者是最佳的治療藥物？","options":["(A) acetaminophen","(B) allopurinol","(C) sumatriptan","(D) sulindac"],"answer":2,"image":""},{"id":"md2-108-1-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第1次第69題","year":108,"session":1,"number":69,"question":"病⼈做化療（chemotherapy）或⼿術後所引起的噁⼼、嘔吐症狀，可以預先使⽤下列何種藥物來緩解，其作 ⽤機轉是透過拮抗neurokinin（NK）的受體？1","options":["(A) riociguat","(B) fasudil","(C) bosentan","(D) aprepitant"],"answer":3,"image":""},{"id":"md2-108-1-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第1次第70題","year":108,"session":1,"number":70,"question":"下列何種減肥藥是作⽤在腸胃道，可減少脂肪的吸收？","options":["(A) phentermine","(B) topiramate","(C) orlistat","(D) lorcaserin"],"answer":2,"image":""},{"id":"md2-108-1-71","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"108年第1次第71題","year":108,"session":1,"number":71,"question":"靜脈注射型⿇醉劑ketamine的主要作⽤機轉為何？","options":["(A) 活化GABA受體A","(B) 抑制GABA受體A","(C) 活化NMDA受體","(D) 抑制NMDA受體"],"answer":3,"image":""},{"id":"md2-108-1-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"108年第1次第72題","year":108,"session":1,"number":72,"question":"關於levetiracetam為部分癲癇發作（partial seizure）治療藥物，下列敘述何者錯誤？","options":["(A) 可經由⼝服給藥","(B) 選擇性的結合突觸⼩泡蛋⽩SVA 2","(C) 影響神經傳遞物質如glutamate和GABA的釋放","(D) 主要經由肝臟代謝"],"answer":3,"image":""},{"id":"md2-108-1-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"108年第1次第73題","year":108,"session":1,"number":73,"question":"下列藥物之中樞鎮靜作⽤可被flumazenil拮抗，何者為誤？","options":["(A) zolpidem","(B) lorazapam","(C) alcohol","(D) aplrazolam"],"answer":2,"image":""},{"id":"md2-108-1-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"108年第1次第74題","year":108,"session":1,"number":74,"question":"下列何種思覺失調症（schizophrenia）的治療藥物，與serotonin (5-HT) receptor有⾼的親和⼒，較不會引2起錐體外症候群（extrapyramidal symptoms），但有QT延⻑（QT prolongation）的風險？","options":["(A) ziprasidone","(B) clozapine","(C) chlorpromazine","(D) haloperidol"],"answer":[0,1],"image":"","answer_note":"更正:第74題答Ａ、Ｂ給分。"},{"id":"md2-108-1-75","subject":"md2","topic":"藥理-化學治療","meta":"108年第1次第75題","year":108,"session":1,"number":75,"question":"137下列何者可⽤於治療放射性銫（radioactive cesium，Cs）污染或鉈鹽（thallium salts）中毒？","options":["(A) EDTA","(B) unithiol","(C) deferasirox","(D) prussian blue"],"answer":3,"image":""},{"id":"md2-108-1-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"108年第1次第76題","year":108,"session":1,"number":76,"question":"74歲男性，發燒咳嗽，右下肺葉有⼀個圓形病灶，內含很多中性球、壞死細胞的黏稠液，此病灶最可能為：","options":["(A) 肥厚性瘢痕（hypertrophic scar）","(B) 膿瘍（abscess）","(C) ⾎腫（hematoma）","(D) 結核（tuberculosis）"],"answer":1,"image":""},{"id":"md2-108-1-77","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第1次第77題","year":108,"session":1,"number":77,"question":"懷孕時乳房最可能發⽣何種變化？","options":["(A) 間質纖維化（stromal fibrosis）","(B) 乳管上⽪鱗狀化⽣（ductal epithelium squamous metaplasia）","(C) 腺泡細胞異⽣（acinic cell dysplasia）","(D) ⼩葉增⽣（lobular hyperplasia）"],"answer":3,"image":""},{"id":"md2-108-1-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"108年第1次第78題","year":108,"session":1,"number":78,"question":"在產前染⾊體檢查分析的20個⽺⽔細胞中，發現5個細胞有46條正常染⾊體，15個細胞多了⼀條第21號染⾊ 體。下列何者為最可能的診斷？","options":["(A) 無分離（nondisjunction）型唐⽒症候群（Down syndrome）","(B) 無分離（nondisjunction）型愛德華⽒症候群（Edwards syndrome）","(C) 轉位（translocation）型愛德華⽒症候群（Edwards syndrome）","(D) 異常細胞鑲嵌（mosaicism）型唐⽒症候群（Down syndrome）"],"answer":3,"image":""},{"id":"md2-108-1-79","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"108年第1次第79題","year":108,"session":1,"number":79,"question":"關於類澱粉沉積症（amyloidosis）的敘述，下列何者正確？","options":["(A) 阿茲海默症（Alzheimer disease）沉積的類澱粉，主要是屬AA（amyloid-associated）型澱粉樣蛋⽩","(B) 甲狀腺髓質癌（medullary thyroid cancer）造成的類澱粉沉積主要因癌細胞產⽣的降鈣素（calcitonin）所致","(C) 剛果紅（Congo red）染⾊只適合⽤來診斷輕鏈蛋⽩相關之類澱粉沉積症，無法偵測非原發性的類澱粉沉積","(D) 交叉α折疊（crossed α-pleated）結構是剛果紅染⾊陽性的原因"],"answer":1,"image":""},{"id":"md2-108-1-80","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"108年第1次第80題","year":108,"session":1,"number":80,"question":"關於癌症病⼈的惡體質（cachexia），下列何者為最可能之原因？①TNF produced by macrophages ②TNF produced by tumor cells③IL-10 produced by macrophages④IL-10 produced by tumor cells","options":["(A) ①②","(B) ②③","(C) ①④","(D) ③④"],"answer":0,"image":""},{"id":"md2-108-1-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"108年第1次第81題","year":108,"session":1,"number":81,"question":"70歲男性因為⼼臟衰竭與⼼律不整住院，⼼臟內膜與⼼肌切片（endomyocardial biopsy）顯⽰有粉紅⾊物質沉積於⼼肌細胞之間，這些物質⽤剛果紅（Congo red）染⾊於偏光顯微鏡下呈現蘋果綠的顏⾊；病⼈經檢查沒有惡性腫瘤、慢性發炎疾病、腎臟疾病或是神經病變，下列何者是最可能堆積的物質？","options":["(A) 免疫球蛋⽩（immunoglobulin）","(B) β2-microglobulin","(C) transthyretin","(D) calcitonin"],"answer":2,"image":""},{"id":"md2-108-1-82","subject":"md2","topic":"病理-心血管血液","meta":"108年第1次第82題","year":108,"session":1,"number":82,"question":"下列何者會出現溶⾎性貧⾎（hemolytic anemia）、⾎⼩板低下與⾎液抹片出現碎裂紅⾎球（schistocytes）？①栓塞性⾎⼩板低下紫斑（thrombotic thrombocytopenic purpura）②巨⼤的⾎管瘤（hemangioma）③瀰漫性⾎管內凝⾎（disseminated intravascular coagulation）④免疫性⾎⼩板低下紫斑（immune thrombocytopenic purpura）","options":["(A) 僅①②","(B) 僅①③","(C) ①②③","(D) ②③④"],"answer":2,"image":""},{"id":"md2-108-1-83","subject":"md2","topic":"病理-心血管血液","meta":"108年第1次第83題","year":108,"session":1,"number":83,"question":"下列物質於⾎液中的濃度上升與粥狀動脈硬化（atherosclerosis）發⽣有關，但何者除外？","options":["(A) C-reactive protein","(B) ⾼密度脂蛋⽩（high-density lipoprotein）","(C) 同半胱胺酸（homocysteine）","(D) ⾎糖"],"answer":1,"image":""},{"id":"md2-108-1-84","subject":"md2","topic":"病理-心血管血液","meta":"108年第1次第84題","year":108,"session":1,"number":84,"question":"下列何者是成年⼈最常⾒的惡性淋巴瘤？","options":["(A) 瀰漫⼤B細胞淋巴瘤（diffuse large B-cell lymphoma）","(B) 未特指周邊T細胞淋巴瘤（peripheral T-cell lymphoma, unspecified）","(C) 退⾏性⼤細胞淋巴瘤（anaplastic large cell lymphoma）","(D) 被套細胞淋巴瘤（mantle cell lymphoma）"],"answer":0,"image":""},{"id":"md2-108-1-85","subject":"md2","topic":"病理-心血管血液","meta":"108年第1次第85題","year":108,"session":1,"number":85,"question":"9歲男孩⾃上週以來四肢瘀傷。⾝體檢查：四肢瘀傷及出⾎斑點；⾎⾊素、⾎容積比、平均紅⾎球體積（MCV）及⽩⾎球計數正常，⾎⼩板明顯降低。病⼈3週前曾有呼吸道融合病毒（respiratory syncytial virus）感染。病⼈狀況經使⽤類固醇治療後緩和。下列何者為此病⼈出⾎傾向之最可能原因？","options":["(A) 抗⾎⼩板抗體（anti-platelet antibodies）","(B) 骨髓造⾎不良","(C) 醣蛋⽩IIb-IIIa功能不全","(D) vWF⾦屬酵素缺乏（vWF metalloprotease deficiency）"],"answer":0,"image":""},{"id":"md2-108-1-86","subject":"md2","topic":"病理-呼吸消化","meta":"108年第1次第86題","year":108,"session":1,"number":86,"question":"上呼吸道腫瘤利⽤免疫組織化學染⾊，發現腫瘤細胞表現synaptophysin與chromogranin抗原時，下列何者為最可能的診斷？","options":["(A) ⿐咽上⽪細胞癌","(B) 嗅⺟神經胚細胞癌（olfactory neuroblastoma）","(C) 喉頭上⽪細胞癌","(D) NUT中線癌（NUT midline carcinoma）"],"answer":1,"image":""},{"id":"md2-108-1-87","subject":"md2","topic":"病理-呼吸消化","meta":"108年第1次第87題","year":108,"session":1,"number":87,"question":"下列有關類⾁瘤（sarcoidosis）的敘述，何者錯誤？","options":["(A) ⼤多數的病⼈表現雙側肺⾨淋巴結腫⼤","(B) CD4陽性T細胞所驅動之免疫反應","(C) 病理變化為壞死性⾁芽腫","(D) 病灶可在肺、脾、肝等器官發現"],"answer":2,"image":""},{"id":"md2-108-1-88","subject":"md2","topic":"病理-心血管血液","meta":"108年第1次第88題","year":108,"session":1,"number":88,"question":"⼤學⽣騎機⾞不幸發⽣⾞禍，造成左⼩腿複雜性骨折，經開⼑固定後，病情穩定。數⽇後胸痛、呼吸困難，轉入加護病房，其診斷最可能為：","options":["(A) 敗⾎症","(B) 肺栓塞","(C) 顱內出⾎","(D) 細菌性肺炎"],"answer":1,"image":""},{"id":"md2-108-1-89","subject":"md2","topic":"病理-呼吸消化","meta":"108年第1次第89題","year":108,"session":1,"number":89,"question":"以下何種肝炎病毒常是造成旅⾏者肝炎（traveler hepatitis）的元凶，並且懷孕婦女感染有將近20%的死亡率？","options":["(A) A型肝炎病毒","(B) B型肝炎病毒","(C) D型肝炎病毒","(D) E型肝炎病毒"],"answer":3,"image":""},{"id":"md2-108-1-90","subject":"md2","topic":"病理-呼吸消化","meta":"108年第1次第90題","year":108,"session":1,"number":90,"question":"關於纖維薄層型肝細胞癌（fibrolamellar carcinoma），下列敘述何者錯誤？","options":["(A) 好發於年輕⼈","(B) 背景肝臟通常已有嚴重纖維化或肝硬化","(C) 腫瘤細胞為含有許多粒線體的oncocytes，由緻密的纖維帶分開","(D) 通常預後較好"],"answer":1,"image":""},{"id":"md2-108-1-91","subject":"md2","topic":"病理-呼吸消化","meta":"108年第1次第91題","year":108,"session":1,"number":91,"question":"下列那⼀項不是潰瘍性結腸炎（ulcerative colitis）的特徵？","options":["(A) ⼤部分（＞50％）的潰瘍性結腸炎患者也患有原發性硬化性膽管炎（primary sclerosing cholangitis）","(B) 可⾒pseudopolyps，嚴重時可造成toxic megacolon","(C) 它通常影響直腸並向近端延伸","(D) 發炎通常侷限於黏膜層及表淺的黏膜下層"],"answer":0,"image":""},{"id":"md2-108-1-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第1次第92題","year":108,"session":1,"number":92,"question":"以下病理變化在⾼⾎壓性腎硬化（hypertensive nephrosclerosis）病灶中最不可能發⽣的是：","options":["(A) 腎⼩球硬化（glomerulosclerosis）","(B) ⼩動脈硬化（arteriosclerosis）","(C) 細動脈硬化（arteriolosclerosis）","(D) 靜脈硬化（phlebosclerosis）"],"answer":3,"image":""},{"id":"md2-108-1-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第1次第93題","year":108,"session":1,"number":93,"question":"腦下垂體中風（pituitary apoplexy）最常⾒的原因為：","options":["(A) 嚴重之腦下垂體出⾎","(B) ⾎管之阻塞導致缺⾎性壞死","(C) 膿瘍之產⽣","(D) 惡性腫瘤細胞之侵犯"],"answer":0,"image":""},{"id":"md2-108-1-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第1次第94題","year":108,"session":1,"number":94,"question":"45歲女性，甲狀腺呈結節性、對稱性腫⼤，與四周組織無沾黏。實驗室檢查發現⾎中有抗微粒體抗體（antimicrosomal antibody）。病理顯微變化如圖⽰，下列何者為最有可能的診斷？","options":["(A) 橋本⽒甲狀腺炎（Hashimoto thyroiditis）","(B) 亞急性甲狀腺炎（subacute thyroiditis）","(C) 雷得⽒甲狀腺炎（Riedel thyroiditis）","(D) 慢性纖維性甲狀腺炎（chronic fibrosing thyroiditis）"],"answer":0,"image":"md2-108-1-94.jpeg"},{"id":"md2-108-1-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第1次第95題","year":108,"session":1,"number":95,"question":"下列有關⼦宮頸上⽪內瘤變／鱗狀上⽪內病灶（cervical intraepithelial neoplasia/squamous intraepithelial lesions）的敘述，何者較不正確？","options":["(A) ⼤部分的低度鱗狀上⽪內病灶（low-grade squamous intraepithelial lesion, LSIL）會持續存在⽽不會回復（regress）","(B) 約有10%的低度鱗狀上⽪內病灶（low-grade squamous intraepithelial lesion, LSIL）會進展（progress）成 ⾼度鱗狀上⽪內病灶（high-grade squamous intraepithelial lesion, HSIL）","(C) 少數⾼度鱗狀上⽪內病灶（high-grade squamous intraepithelial lesion, HSIL）會回復（regress）","(D) ⼤部分⾼度鱗狀上⽪內病灶（high-grade squamous intraepithelial lesion, HSIL）會持續存在（persist）"],"answer":0,"image":""},{"id":"md2-108-1-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第1次第96題","year":108,"session":1,"number":96,"question":"下列有關前列腺炎（prostatitis）的敘述，何者較不正確？","options":["(A) 急性細菌性前列腺炎（acute bacterial prostatitis），其致病病原菌通常與引起泌尿道感染的病原菌類似","(B) 慢性細菌性前列腺炎（chronic bacterial prostatitis）⼀般不易診斷與治療，病⼈常有反覆泌尿道感染的病史","(C) 在美國，最常引起⾁芽腫性前列腺炎（granulomatous prostatitis）的原因是使⽤Bacillus Calmette-Guérin（BCG）治療表⾯性膀胱癌（superficial bladder cancer）","(D) 慢性非細菌性前列腺炎（chronic abacterial prostatitis）的病⼈⼀般沒有反覆泌尿道感染的病史，其發⽣率是各種前列腺炎中最低的"],"answer":3,"image":""},{"id":"md2-108-1-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第1次第97題","year":108,"session":1,"number":97,"question":"下列有關睪丸精⺟細胞瘤（testicular seminoma）的敘述，何者較不正確？","options":["(A) 常⾒的染⾊體變化為第⼗⼆條染⾊體短臂的等臂染⾊體（isochromosome 12p）","(B) 腫瘤細胞會表現OCT3/4與NANOG","(C) 常常發⽣在嬰兒時期（infant）","(D) 部分腫瘤會有KIT gene的活化性突變（activating mutations）"],"answer":2,"image":""},{"id":"md2-108-1-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"108年第1次第98題","year":108,"session":1,"number":98,"question":"病理診斷狂⽝病（Rabies）的最主要依據是觀察到：","options":["(A) Lewy body","(B) Kuru plaque","(C) Negri body","(D) Stress granules"],"answer":2,"image":""},{"id":"md2-108-1-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"108年第1次第99題","year":108,"session":1,"number":99,"question":"⾁芽腫性葡萄膜炎（granulomatous uveitis）是下列何種疾病的常⾒併發症？","options":["(A) 惡性⿊⾊素瘤（malignant melanoma）","(B) 惡性淋巴瘤（malignant lymphoma）","(C) 類⾁瘤病（sarcoidosis）","(D) 紅斑性狼瘡（lupus erythematosus）"],"answer":2,"image":""},{"id":"md2-108-1-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"108年第1次第100題","year":108,"session":1,"number":100,"question":"50歲男性，患胃炎且常嘔吐，亦有記憶衰退及虛談（confabulation），病理解剖發現腦部乳頭體（mamillary bodies）及第三及第四腦室壁出⾎及壞死，其腦部病變與下列何種維⽣素（vitamin）缺乏有關？","options":["(A) A","(B) B 1","(C) B 6","(D) B 12"],"answer":1,"image":""},{"id":"md2-108-2-1","subject":"md2","topic":"細菌學","meta":"108年第2次第1題","year":108,"session":2,"number":1,"question":"關於奴卡氏菌屬（Nocardia species）之敘述，下列何者正確？","options":["(A) 為革蘭氏陰性桿菌","(B) 較少引起肺部及皮膚感染","(C) 為細胞壁含黴菌酸（mycolic acid）之需氧菌","(D) 不會產生索狀因子（cord factor）"],"answer":2,"image":""},{"id":"md2-108-2-2","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第2題","year":108,"session":2,"number":2,"question":"下列何種藥物最適合治療肺炎黴漿菌（Mycoplasma pneumoniae）所引起之肺炎？","options":["(A) 青黴素（Penicillin）","(B) 碳青黴烯（Carbapenem）","(C) 頭孢子素（Cephalosporin）","(D) 紅黴素（Erythromycin）"],"answer":3,"image":""},{"id":"md2-108-2-3","subject":"md2","topic":"細菌學","meta":"108年第2次第3題","year":108,"session":2,"number":3,"question":"關於分枝桿菌（Mycobacteria）之敘述，下列何者正確？","options":["(A) 堪薩斯分枝桿菌（Mycobacterium kansasii）為非致病之正常菌叢","(B) 鳥型分枝桿菌（Mycobacterium avium）常見於感染愛滋病病人","(C) 海洋分枝桿菌（Mycobacterium marinum）不會造成人類感染","(D) 牛型分枝桿菌（Mycobacterium bovis）非人類致病菌"],"answer":1,"image":""},{"id":"md2-108-2-4","subject":"md2","topic":"細菌學","meta":"108年第2次第4題","year":108,"session":2,"number":4,"question":"糞腸球菌（Enterococcus faecalis）最有可能引發下列那種疾病？","options":["(A) 肺炎（pneumonia）","(B) 腦膜炎（meningitis）","(C) 食物中毒（food poisoning）","(D) 泌尿道感染（urinary tract infection）"],"answer":3,"image":""},{"id":"md2-108-2-5","subject":"md2","topic":"細菌學","meta":"108年第2次第5題","year":108,"session":2,"number":5,"question":"有關A群鏈球菌（Group A Streptococci）之溶血素O（streptolysin O）的敘述，下列何者錯誤？","options":["(A) 對氧氣敏感（oxygen-labile）","(B) 其所引起的抗體（ASO）之效價，是診斷鏈球菌咽喉炎所引起的風濕熱（rheumatic fever）的重要依據","(C) 在此菌所引起的膿皮症（pyoderma）病患中容易測得高效價的抗體（ASO）","(D) 與肺炎鏈球菌（S. pneumoniae）所產生之對氧氣敏感的毒素之抗原性相關"],"answer":2,"image":""},{"id":"md2-108-2-6","subject":"md2","topic":"細菌學","meta":"108年第2次第6題","year":108,"session":2,"number":6,"question":"金黃色葡萄球菌（Staphylococcus aureus）最不可能產生下列那種酵素？","options":["(A) 玻尿酸酶（Hyaluronidase）","(B) 纖溶酶（Fibrinolysin）","(C) 凝固酶（Coagulase）","(D) C5a蛋白酶（C5a peptidase）"],"answer":3,"image":""},{"id":"md2-108-2-7","subject":"md2","topic":"細菌學","meta":"108年第2次第7題","year":108,"session":2,"number":7,"question":"下列何種分枝桿菌（Mycobacteria）屬於慢速生長型（slow-growing）？","options":["(A) 龜分枝桿菌（Mycobacterium chelonae）","(B) 結核分枝桿菌（Mycobacterium tuberculosis）","(C) 偶發分枝桿菌（Mycobacterium fortuitum）","(D) 膿瘍分枝桿菌（Mycobacterium abscessus）"],"answer":1,"image":""},{"id":"md2-108-2-8","subject":"md2","topic":"病毒學","meta":"108年第2次第8題","year":108,"session":2,"number":8,"question":"一名受EB病毒（Epstein-Barr virus, EBV）感染的病人，其血清學檢查如下：anti-VCA IgM (+)、anti-VCA IgG (+)、anti-EA (+/-)、anti-EBNA (-)，此病人的情況屬於下列何者？[VCA：病毒殼蛋白質抗原（viral capsid antigen）；EA：早期抗原（early antigen）; EBNA：EB病毒核抗原（Epstein-Barr nuclear antigen）]","options":["(A) EB病毒感染的急性期（acute primary infection）","(B) EB病毒慢性感染期（chronic primary infection）","(C) 曾被EB病毒感染（past infection）","(D) 曾被EB病毒感染，現在病毒再活化（reactivation）"],"answer":0,"image":""},{"id":"md2-108-2-9","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第9題","year":108,"session":2,"number":9,"question":"下列何者不屬於目前美國食品與藥物管理局（FDA）認可的HIV抗病毒藥物？","options":["(A) 蛋白酶抑制劑（protease inhibitor）","(B) 嵌入酶抑制劑（integrase inhibitor）","(C) 核苷類似物反轉錄酶抑制劑（nucleoside analog RT inhibitor）","(D) 病毒出芽抑制劑（budding inhibitor）"],"answer":3,"image":""},{"id":"md2-108-2-10","subject":"md2","topic":"病毒學","meta":"108年第2次第10題","year":108,"session":2,"number":10,"question":"下列病毒中，現在何種能以施打減毒疫苗方式進行最佳預防？","options":["(A) 單純疱疹病毒（Herpes simplex virus）","(B) 第八型人類疱疹病毒（Human herpesvirus-8）","(C) EB病毒（Epstein-Barr virus）","(D) 水痘-帶狀疱疹病毒（Varicella-zoster virus）"],"answer":3,"image":""},{"id":"md2-108-2-11","subject":"md2","topic":"病毒學","meta":"108年第2次第11題","year":108,"session":2,"number":11,"question":"下列何種病毒最常造成先天性疾病，並影響新生兒聽力與智能發展？","options":["(A) 麻疹病毒（Measles virus）","(B) 單純疱疹病毒（Herpes simplex virus）","(C) 巨細胞病毒（Cytomegalovirus）","(D) B19細小病毒（Parvovirus B19）"],"answer":2,"image":""},{"id":"md2-108-2-12","subject":"md2","topic":"病毒學","meta":"108年第2次第12題","year":108,"session":2,"number":12,"question":"感染下列何種病毒，若自行服用阿司匹靈（Aspirin）等水楊酸類（salicylates）退燒藥物後，最易增加兒童罹患雷氏症候群（Reye syndrome）的風險？","options":["(A) 德國麻疹病毒（Rubella virus）","(B) 麻疹病毒（Measles virus）","(C) 流感病毒（Influenza virus）","(D) 狂犬病病毒（Rabies virus）"],"answer":2,"image":""},{"id":"md2-108-2-13","subject":"md2","topic":"病毒學","meta":"108年第2次第13題","year":108,"session":2,"number":13,"question":"人類是下列何種病毒中，最明確的天然宿主？","options":["(A) 辛德畢斯病毒（Sindbis virus）","(B) 塞姆利基森林病毒（Semliki Forest virus）","(C) 西尼羅腦炎病毒（West Nile encephalitis virus）","(D) 基孔肯雅病毒（Chikungunya virus）"],"answer":3,"image":""},{"id":"md2-108-2-14","subject":"md2","topic":"真菌學","meta":"108年第2次第14題","year":108,"session":2,"number":14,"question":"有關花斑癬（pityriasis versicolor）之敘述，下列何者錯誤？","options":["(A) 最常見於年輕人","(B) 致病原為粃糠馬拉色菌綜合菌（Malassezia furfur complex）","(C) 致病原未歸類為自然界腐生菌","(D) 無法由檢體直接做鏡檢診斷"],"answer":3,"image":""},{"id":"md2-108-2-15","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第15題","year":108,"session":2,"number":15,"question":"制黴菌素（Nystatin）之作用機轉，與下列何種藥物一樣？","options":["(A) 氟胞嘧啶（Flucytosine）","(B) 兩性黴素（Amphotericin B）","(C) 卡泊芬淨（Caspofungin）","(D) 糞殼菌素（Sordarin）"],"answer":1,"image":""},{"id":"md2-108-2-16","subject":"md2","topic":"病毒學","meta":"108年第2次第16題","year":108,"session":2,"number":16,"question":"治療愛滋病（AIDS）的藥物疊氮胸苷（azidothymidine, AZT），是針對病毒那個基因的產物？","options":["(A) env","(B) gag","(C) tat","(D) pol"],"answer":3,"image":""},{"id":"md2-108-2-17","subject":"md2","topic":"真菌學","meta":"108年第2次第17題","year":108,"session":2,"number":17,"question":"真菌之無性孢子（asexual spores）可分成那兩大類？","options":["(A) 分生孢子（conidia）及囊孢子（sporangiospores）","(B) 瓶孢子（phialides）及分節孢子（arthrospores）","(C) 厚膜孢子（chlamydospores）及分節孢子（arthrospores）","(D) 分節孢子（arthrospores）及芽生孢子（blastospores）"],"answer":0,"image":""},{"id":"md2-108-2-18","subject":"md2","topic":"免疫學","meta":"108年第2次第18題","year":108,"session":2,"number":18,"question":"下列何種細胞一般不被歸類為先天免疫細胞？","options":["(A) macrophage","(B) B cell","(C) neutrophil","(D) dendritic cell"],"answer":1,"image":""},{"id":"md2-108-2-19","subject":"md2","topic":"免疫學","meta":"108年第2次第19題","year":108,"session":2,"number":19,"question":"進入組織之單核球（monocytes），經下列何種細胞素[cytokine(s)]刺激，可以分化成樹突細胞（dendritic cells）？","options":["(A) M-CSF","(B) M-CSF＋TNF-α","(C) IL-1β","(D) GM-CSF＋IL-4"],"answer":3,"image":""},{"id":"md2-108-2-20","subject":"md2","topic":"免疫學","meta":"108年第2次第20題","year":108,"session":2,"number":20,"question":"下列何種細胞的抗原接受器（antigen receptor）會進行體細胞高度突變（somatic hypermutation）？","options":["(A) T細胞","(B) B細胞","(C) 巨噬細胞","(D) 自然殺手細胞"],"answer":1,"image":""},{"id":"md2-108-2-21","subject":"md2","topic":"免疫學","meta":"108年第2次第21題","year":108,"session":2,"number":21,"question":"下列有關pre-T細胞抗原接受器（pre-T cell receptor）的敘述，何者最正確？","options":["(A) 具有TCR α鏈（TCR α chain）","(B) 具有TCR β鏈（TCR β chain）","(C) 可以辨識外來抗原","(D) 此階段的細胞大部分都可以辨識自己的主要組織相容性抗原（MHC）"],"answer":1,"image":""},{"id":"md2-108-2-22","subject":"md2","topic":"免疫學","meta":"108年第2次第22題","year":108,"session":2,"number":22,"question":"下列有關調節型T細胞（regulatory T cells, Treg）的敘述何者正確？","options":["(A) 腫瘤可以調控microenvironment的T細胞分化成Treg細胞，以逃脫免疫系統的追殺","(B) Treg細胞的功能的過度活化，是許多自體免疫疾病發病的重要因素","(C) Treg細胞都是在周邊淋巴組織分化而成","(D) Treg細胞表面帶有CD8的標記，可以幫助清除胞內病原感染"],"answer":0,"image":""},{"id":"md2-108-2-23","subject":"md2","topic":"免疫學","meta":"108年第2次第23題","year":108,"session":2,"number":23,"question":"T follicular helper（T）細胞對於體液免疫反應（humoral immune response）非常重要，關於T的描述何者FHFH錯誤？","options":["(A) T細胞位在germinal center的淺色區（light zone）FH","(B) T細胞的分化需要Bcl-6轉錄因子FH","(C) T細胞可以分泌IL-21和其他的細胞激素，IL-21促進漿細胞分化FH","(D) 小鼠B細胞在體外培養時利用加入LPS、IL-2、及IL-21，可以替代T細胞功能來刺激IgG1抗體產生FH"],"answer":3,"image":""},{"id":"md2-108-2-24","subject":"md2","topic":"細菌學","meta":"108年第2次第24題","year":108,"session":2,"number":24,"question":"有關腸道細菌的敘述，下列何者錯誤？","options":["(A) 廣效型抗生素可殺死腸道細菌，長期使用可保持腸道健康","(B) 腸道的共生細菌（commensal bacteria）對腸道有益","(C) 腸道共生細菌（commensal bacteria）的不同組成與代謝疾病有相關性","(D) 使用免疫抑制劑可能造成腸道嚴重感染"],"answer":0,"image":""},{"id":"md2-108-2-25","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"108年第2次第25題","year":108,"session":2,"number":25,"question":"如果吞噬性白血球將微生物吞食後無法及時有效地將其殺死並且分解，免疫細胞將會聚集起來形成肉芽腫（granuloma）。肉芽腫的中心經常被有一層排列整齊的單核白血球包圍。這層細胞是下列何者？","options":["(A) 上皮細胞（epithelial cells）","(B) 類上皮細胞（epithelioid cells）","(C) 漿細胞（plasma cells）","(D) 壞死嗜中性白血球細胞及微生物"],"answer":1,"image":""},{"id":"md2-108-2-26","subject":"md2","topic":"免疫學","meta":"108年第2次第26題","year":108,"session":2,"number":26,"question":"下列何者不是身體達成免疫系統自體耐受性（self-tolerance）的機轉？","options":["(A) 周邊不反應（peripheral anergy）","(B) 株落刪除（clonal deletion）","(C) 株落增殖（clonal proliferation）","(D) 中樞耐受性（central tolerance）"],"answer":2,"image":""},{"id":"md2-108-2-27","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第2次第27題","year":108,"session":2,"number":27,"question":"用於免疫抑制作用的類固醇（corticosteroid）有下列各項作用，何者除外？","options":["(A) 降低IL-1, TNF α, IL-4, IL-5等之生成","(B) 降低prostaglandins, leukotrienes等之生成","(C) 降低黏著分子（adhesion molecules）等之生成","(D) 降低內核酸酵素（endonucleases）等之生成"],"answer":3,"image":""},{"id":"md2-108-2-28","subject":"md2","topic":"免疫學","meta":"108年第2次第28題","year":108,"session":2,"number":28,"question":"Natalizumab [anti-α4 integrin (anti-VLA-4) monoclonal antibody]目前已證實可以用來治療何種疾病？","options":["(A) multiple sclerosis","(B) metastatic melanoma","(C) chronic myeloid leukemia","(D) chronic asthma"],"answer":0,"image":""},{"id":"md2-108-2-29","subject":"md2","topic":"寄生蟲學","meta":"108年第2次第29題","year":108,"session":2,"number":29,"question":"有關鉤蟲（hookworm）感染的敘述，下列選項何者錯誤？①十二指腸鉤蟲（Ancylostoma duodenale）僅經皮膚感染人體②重度感染且鐵質之攝取量不足，常引起缺鐵性貧血（iron deficiency anemia）③感染後最早發生的症狀為嗜伊紅性白血球增多","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":1,"image":""},{"id":"md2-108-2-30","subject":"md2","topic":"寄生蟲學","meta":"108年第2次第30題","year":108,"session":2,"number":30,"question":"下列何種寄生蟲感染會導致皮膚幼蟲移行症（cutaneous larva migrans）？","options":["(A) 犬心絲蟲（Dirofilaria immitis）","(B) 犬鉤蟲（Ancylostoma caninum）","(C) 犬蛔蟲（Toxocara canis）","(D) 肝毛細線蟲（Capillaria hepatica）"],"answer":1,"image":""},{"id":"md2-108-2-31","subject":"md2","topic":"寄生蟲學","meta":"108年第2次第31題","year":108,"session":2,"number":31,"question":"下列寄生蟲中，何者感染不會導致患者腦部病變？","options":["(A) 日本血吸蟲（Schistosoma japonicum）","(B) 豬肉絛蟲（Taenia solium）","(C) 單胞絛蟲（Echinococcus granulosus）","(D) 棘口吸蟲（Echinostoma spp.）"],"answer":3,"image":""},{"id":"md2-108-2-32","subject":"md2","topic":"寄生蟲學","meta":"108年第2次第32題","year":108,"session":2,"number":32,"question":"下列何種絛蟲的蟲卵具有卵蓋（operculum）？","options":["(A) 單胞絛蟲（Echinococcus granulosus）","(B) 牛肉絛蟲（Taenia saginata）","(C) 廣節裂頭絛蟲（Diphyllobothrium latum）","(D) 短小包膜絛蟲（Hymenolepis nana）"],"answer":2,"image":""},{"id":"md2-108-2-33","subject":"md2","topic":"寄生蟲學","meta":"108年第2次第33題","year":108,"session":2,"number":33,"question":"下列有關寄生蟲之敘述中，何者錯誤？","options":["(A) 蘇丹境內同時有羅得西亞錐蟲（Trypanosoma brucei rhodesiense）及岡比亞錐蟲（T. b. gambiense）的分布","(B) 有些黑熱病（kala-azar）患者如果治療不當，在一、兩年後同樣的病原蟲可能在皮膚產生病灶","(C) 美國境內也曾有本土性枯西氏錐蟲（Trypanosoma cruzi）人體感染的病例","(D) 歐美人士至東非野生動物保護區旅行，曾有因此感染羅得西亞錐蟲（Trypanosoma brucei rhodesiense）的病例發生"],"answer":0,"image":""},{"id":"md2-108-2-34","subject":"md2","topic":"寄生蟲學","meta":"108年第2次第34題","year":108,"session":2,"number":34,"question":"下列各病症與其病原蟲之配對中，何者錯誤？","options":["(A) Romaña's sign－枯西氏錐蟲（Trypanosoma cruzi）","(B) Winterbottom's sign－岡比亞錐蟲（Trypanosoma brucei gambiense）","(C) Megaesophagus－杜氏利什曼原蟲（Leishmania donovani）","(D) Espundia－巴西利什曼原蟲（Leishmania braziliensis）"],"answer":2,"image":""},{"id":"md2-108-2-35","subject":"md2","topic":"寄生蟲學","meta":"108年第2次第35題","year":108,"session":2,"number":35,"question":"有關蜱媒介人巴貝氏原蟲病（human babesiosis）之敘述，下列何者錯誤？","options":["(A) 巴貝氏原蟲（Babesia）感染宿主後主要寄生在紅血球內","(B) 患者常呈現無症狀感染（asymptomatic infection）之高度寄生蟲血症（heavy parasitemia）","(C) 感染致死之病例通常發生在脾臟切除（splenectomized）病人","(D) 臨床感染診斷則以血液抹片配合免疫螢光抗體試驗（IFA）為主"],"answer":1,"image":""},{"id":"md2-108-2-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"108年第2次第36題","year":108,"session":2,"number":36,"question":"統計假說檢定（statistical hypothesis testing）時，何謂型一錯誤（type I error）？","options":["(A) 兩組實際上無差異，分析結果推翻虛無假說（null hypothesis）","(B) 兩組實際上無差異，分析結果支持虛無假說（null hypothesis）","(C) 兩組實際上有差異，分析結果推翻虛無假說（null hypothesis）","(D) 兩組實際上有差異，分析結果支持虛無假說（null hypothesis）"],"answer":0,"image":""},{"id":"md2-108-2-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"108年第2次第37題","year":108,"session":2,"number":37,"question":"有關單尾與雙尾假說檢定的敘述，下列何者正確？","options":["(A) 單尾與雙尾假說檢定的p值算法相同","(B) 相對於雙尾假說檢定，單尾假說檢定比較不易拒絕虛無假說","(C) 單尾與雙尾假說檢定的顯著水準（α）相同","(D) 相對於雙尾假說檢定，單尾假說檢定比較常被使用"],"answer":2,"image":""},{"id":"md2-108-2-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"108年第2次第38題","year":108,"session":2,"number":38,"question":"有關X和Y的一個簡單的線性迴歸模型的迴歸係數估計值b與X和Y的皮爾森（Pearson）相關係數估值r的敘述，下列何者錯誤？","options":["(A) 一個大的|b|與|r|值並不能確認X對Y的因果關係","(B) r值一定介於-1與1之間","(C) b與r值一定同正或同負（不會一正一負）","(D) 如果Y和X反應變項與解釋變項的角色互換仍然有相同的b與r值"],"answer":3,"image":""},{"id":"md2-108-2-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"108年第2次第39題","year":108,"session":2,"number":39,"question":"某研究比較四組不同年齡層的病人之平均血壓值達統計顯著差異，進一步進行多重比較方法檢定所有可能的兩兩組別比較，假設犯型一錯誤的總機率為0.05，則利用Bonferroni法修正每一個別檢定的顯著性水準為：","options":["(A) 0.05","(B) 0.05/4","(C) 0.05/6","(D) 0.05/12"],"answer":2,"image":""},{"id":"md2-108-2-40","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"108年第2次第40題","year":108,"session":2,"number":40,"question":"某病例對照研究（case-control study）研究吸菸與某疾病之關係，資料如以下列聯表：若要就吸菸與得該疾病的關係做統計檢定，下列何種方法最適當？","options":["(A) 獨立t檢定（two-sample t-test）","(B) 配對t檢定（paired t-test）","(C) McNemar卡方檢定（McNemar Chi-square test）","(D) 費雪恰當檢定（Fisher’s exact test）"],"answer":3,"image":"md2-108-2-40.jpeg"},{"id":"md2-108-2-41","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"108年第2次第41題","year":108,"session":2,"number":41,"question":"若甲乙兩地各年齡層年齡別死亡率完全相同，下列敘述何者最正確？","options":["(A) 甲乙兩地之粗死亡率必定相同","(B) 甲乙兩地之年齡標準化死亡率必定相同","(C) 甲地人口比乙地老化，則甲地之粗死亡率必小於乙地","(D) 甲乙兩地間年齡標準化死亡率之差異，不會隨標準人口年齡組成不同而有變異"],"answer":[1,3],"image":"","answer_note":"更正:第41題答Ｂ、Ｄ給分。"},{"id":"md2-108-2-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第2次第42題","year":108,"session":2,"number":42,"question":"下列何者不屬於空氣污染物中所謂的粒狀污染物？","options":["(A) 黑煙（soot）","(B) 酸霧（acid mist）","(C) 油煙（oil smoke）","(D) 揮發性有機物（VOCs）"],"answer":3,"image":""},{"id":"md2-108-2-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第2次第43題","year":108,"session":2,"number":43,"question":"風險評估中所使用之危害商數（hazard quotient），主要用於下列那一評估步驟？","options":["(A) 危害辨識（hazard identification）","(B) 劑量反應評估","(C) 暴露評估","(D) 風險特徵描述"],"answer":3,"image":""},{"id":"md2-108-2-44","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第2次第44題","year":108,"session":2,"number":44,"question":"下列那一項情況，較不適合使用整體換氣系統？","options":["(A) 保持工作環境的濕度","(B) 稀釋污染物的濃度","(C) 降低工作環境的溫度","(D) 調整工作環境的氣壓"],"answer":3,"image":""},{"id":"md2-108-2-45","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第2次第45題","year":108,"session":2,"number":45,"question":"臺灣中部地區曾發生的油症兒事件，是由於那一種物質的暴露所引起的？","options":["(A) 靈丹（lindane）","(B) 多氯聯苯（PCB）","(C) 甲苯（toluene）","(D) 有機汞（organic mercury）"],"answer":1,"image":""},{"id":"md2-108-2-46","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"108年第2次第46題","year":108,"session":2,"number":46,"question":"自從SARS之後，醫護人員的職業性感染問題受到很大的關注。請依院內感染控制的觀念，對於職業性肺結核的認定，下列何者正確？","options":["(A) 員工就職時的肺部X光檢查是職業性肺結核認定的重要比較資料之一","(B) 由於肺結核也屬於法定傳染病，因此依據勞工保險條例，不得同時加以認定為職業病，因此也得不到勞保給付","(C) 由於患者四處走動，醫院中各部門員工感染肺結核的危險性皆相同","(D) 醫護人員得到肺結核都是職業病"],"answer":0,"image":""},{"id":"md2-108-2-47","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"108年第2次第47題","year":108,"session":2,"number":47,"question":"社會支持對健康行為具正向影響，如果小青提供家裡的桌球室讓鄰居來打球運動，是提供下列那一種社會支持？","options":["(A) 工具性支持","(B) 情感性支持","(C) 資訊性支持","(D) 評價性支持"],"answer":0,"image":""},{"id":"md2-108-2-48","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"108年第2次第48題","year":108,"session":2,"number":48,"question":"若執行一個衛生計畫中，擬評估「民眾參與率是否達到預期值？」「資源運用是否理想？」「執行者的投入是否符合角色？」等問題，是屬於那一種評價工作？","options":["(A) 過程評價","(B) 結果評價","(C) 衝擊評價","(D) 形式評價"],"answer":0,"image":""},{"id":"md2-108-2-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"108年第2次第49題","year":108,"session":2,"number":49,"question":"下列關於醫院所採行的整體策略何者錯誤？","options":["(A) 可包含成長策略、穩定策略、緊縮策略及混合策略","(B) 垂直整合屬於穩定策略","(C) 作業流程的再造與合理化屬於穩定策略","(D) 混合策略可以是內科部採成長策略，小兒科部採緊縮策略"],"answer":1,"image":""},{"id":"md2-108-2-50","subject":"md2","topic":"藥理-總論與自主神經","meta":"108年第2次第50題","year":108,"session":2,"number":50,"question":"新藥上市前，在臨床試驗階段，其受試對象在1000～3000名，屬於第幾階段的臨床試驗？","options":["(A) 第四階段","(B) 第三階段","(C) 第二階段","(D) 第一階段"],"answer":1,"image":""},{"id":"md2-108-2-51","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第51題","year":108,"session":2,"number":51,"question":"有位女士自助旅行回來發生下痢，給與止瀉藥物無法改善症狀，此患者可能因感染革蘭氏陰性桿菌所引起，下列何者為治療此患者之首選藥物？","options":["(A) levofloxacin","(B) sulfacetamide","(C) trimethoprim","(D) vancomycin"],"answer":0,"image":""},{"id":"md2-108-2-52","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第2次第52題","year":108,"session":2,"number":52,"question":"下列何種免疫抑制劑亦可用於冠狀動脈支架之包覆，藉其抑制細胞增生作用來防治術後冠狀動脈之再狹窄（restenosis）？","options":["(A) cyclosporine","(B) tacrolimus（FK 506）","(C) sirolimus（rapamycin）","(D) azathioprine"],"answer":2,"image":""},{"id":"md2-108-2-53","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第2次第53題","year":108,"session":2,"number":53,"question":"Sulfonylureas類治療糖尿病藥物的主要作用機轉為何？","options":["(A) 抑制胰島素被肝臟代謝分解","(B) 促進胰島素的生合成及敏感性","(C) 增加細胞的胰島素受體數目","(D) 促進胰島素的分泌"],"answer":3,"image":""},{"id":"md2-108-2-54","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"108年第2次第54題","year":108,"session":2,"number":54,"question":"+- 那一種利尿劑會抑制遠端彎曲小管（distal convoluted tubule）Na/Cl transporter而產生利尿作用？","options":["(A) acetazolamide","(B) triamterene","(C) thiazide","(D) bumetanide"],"answer":2,"image":""},{"id":"md2-108-2-55","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第2次第55題","year":108,"session":2,"number":55,"question":"下列何種治療氣喘的藥物，只適合用於預防性給藥，若氣喘已發作，給與此藥則無療效？","options":["(A) albuterol","(B) theophylline","(C) salmeterol","(D) nedocromil"],"answer":3,"image":""},{"id":"md2-108-2-56","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"108年第2次第56題","year":108,"session":2,"number":56,"question":"下列何種藥物無法預防或治療急性偏頭痛？","options":["(A) buspirone","(B) sumatriptan","(C) propranolol","(D) dihydroergotamine"],"answer":0,"image":""},{"id":"md2-108-2-57","subject":"md2","topic":"病理-呼吸消化","meta":"108年第2次第57題","year":108,"session":2,"number":57,"question":"下列那一種器官對於由乙醇引起的病變程度最為重要？","options":["(A) 胰臟","(B) 心臟","(C) 肺臟","(D) 肝臟"],"answer":3,"image":""},{"id":"md2-108-2-58","subject":"md2","topic":"藥理-總論與自主神經","meta":"108年第2次第58題","year":108,"session":2,"number":58,"question":"有關partial agonist的敘述，下列何者正確？","options":["(A) partial agonist對受體的binding affinity小於full agonist","(B) partial agonist對受體的intrinsic efficacy小於full agonist","(C) partial agonist與full agonist一起合用時efficacy會相加成","(D) partial agonist較full agonist不易受拮抗劑的抑制"],"answer":1,"image":""},{"id":"md2-108-2-59","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第59題","year":108,"session":2,"number":59,"question":"關於isoniazid之敘述，下列何者正確？","options":["(A) 抑制結核分枝桿菌細胞膜之生成","(B) 只能以靜脈注射方式治療肺結核","(C) 主要由肝臟之N-acetyltransferase代謝","(D) 易產生視神經病變的副作用"],"answer":2,"image":""},{"id":"md2-108-2-60","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第60題","year":108,"session":2,"number":60,"question":"孕婦不可使用下列抗生素的原因，下列何者正確？","options":["(A) erythromycin estolate易使胎兒第八對腦神經受損","(B) streptomycin易導致嬰兒軟骨受損","(C) sulfonamides易導致缺乏glucose-6-phosphate dehydrogenase之新生兒溶血作用而引起核黃疸","(D) tetracycline會導致灰嬰症候群（gray baby syndrome）"],"answer":2,"image":""},{"id":"md2-108-2-61","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第61題","year":108,"session":2,"number":61,"question":"下列何種抗生素可增加肝臟代謝速率，而使其他藥物之藥效降低？","options":["(A) chloramphenicol","(B) erythromycin","(C) ketoconazole","(D) rifampin"],"answer":3,"image":""},{"id":"md2-108-2-62","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第62題","year":108,"session":2,"number":62,"question":"下列何者會先被病毒的thymidine kinase磷酸化而干擾病毒複製，因此對被感染的細胞具選擇性，主要用於治療疱疹病毒（herpes viruses）的感染？","options":["(A) abacavir","(B) acyclovir","(C) amantadine","(D) azidothymidine"],"answer":1,"image":""},{"id":"md2-108-2-63","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第2次第63題","year":108,"session":2,"number":63,"question":"有位60歲停經的婦人，到醫院做腰椎、股骨、頸骨和髖骨的骨質密度檢查，結果發現這些骨骼都有低骨密度的現象。下列何者最可能因慢性使用，而導致婦人的骨質疏鬆症？","options":["(A) lovastatin","(B) metformin","(C) propranolol","(D) prednisone"],"answer":3,"image":""},{"id":"md2-108-2-64","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第2次第64題","year":108,"session":2,"number":64,"question":"55歲男性被診斷出攝護腺腫大和血中攝護腺特有抗原（prostate specific antigen）上升，核磁共振檢查顯示在下腹部有許多擴大的淋巴結，X光照射發現骨盆有兩個蝕骨性的病變。下列何者較適合被用來治療攝護腺腫瘤？","options":["(A) oxandrolone","(B) desogestrel","(C) anastrozole","(D) flutamide"],"answer":3,"image":""},{"id":"md2-108-2-65","subject":"md2","topic":"藥理-總論與自主神經","meta":"108年第2次第65題","year":108,"session":2,"number":65,"question":"下列藥物何者適於治療隅角開放型青光眼（open-angle glaucoma）？","options":["(A) atropine","(B) betaxolol","(C) phentolamine","(D) tropicamide"],"answer":1,"image":""},{"id":"md2-108-2-66","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"108年第2次第66題","year":108,"session":2,"number":66,"question":"經臨床使用藥物的分析調查後發現，小孩因病毒感染而使用某種藥物作為退燒時，易伴隨有Reye syndrome的副作用。下列何種藥物產生此副作用的可能性最高？","options":["(A) acetaminophen","(B) aspirin","(C) sulindac","(D) ibuprofen"],"answer":1,"image":""},{"id":"md2-108-2-67","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"108年第2次第67題","year":108,"session":2,"number":67,"question":"關於抗帕金森病藥物（antiparkinson's drug）的敘述，下列何者正確？","options":["(A) carbidopa是dopamine的前驅藥物","(B) rasagiline是B型單胺氧化酶（monoamine oxidase B）的抑制劑","(C) pramipexole抑制dopamine受體","(D) benztropine促進神經末梢dopamine的釋放"],"answer":1,"image":""},{"id":"md2-108-2-68","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第68題","year":108,"session":2,"number":68,"question":"乙醇（酒精）可用於治療甲醇中毒，下列何者為最可能的機制？","options":["(A) 加速甲醇從腎臟排除","(B) 抑制甲醇毒性代謝物質的產生","(C) 加速甲醇從肝臟代謝","(D) 加速甲醇從呼吸道排除"],"answer":1,"image":""},{"id":"md2-108-2-69","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"108年第2次第69題","year":108,"session":2,"number":69,"question":"下列何者不是鴉片類藥物（opioids）的作用？","options":["(A) 抗痙攣","(B) 抑制咳嗽","(C) 便秘","(D) 瞳孔縮小"],"answer":0,"image":""},{"id":"md2-108-2-70","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第70題","year":108,"session":2,"number":70,"question":"下列藥物可用於治療急性無機汞鹽（inorganic mercury salts）中毒，何者錯誤？","options":["(A) unithiol","(B) dimercaprol","(C) succimer","(D) D-dimethylcysteine"],"answer":3,"image":""},{"id":"md2-108-2-71","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第71題","year":108,"session":2,"number":71,"question":"下列抗癌藥物中，何者可抑制血管內皮生長因子（vascular endothelial growth factor）受體的活化而抑制癌細胞生長及轉移？","options":["(A) cetuximab","(B) erlotinib","(C) sunitinib","(D) panitumumab"],"answer":2,"image":""},{"id":"md2-108-2-72","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第72題","year":108,"session":2,"number":72,"question":"臨床上使用G-CSF治療多發性骨髓瘤（multiple myeloma）過程中，可併服造血性幹細胞穩定藥物plerixafor，以達較佳療效。試問此穩定藥物之作用機制為何？","options":["(A) 強化JAK/STAT訊息活化","(B) 促進G-CSF釋出","(C) 抑制CXC chemokine receptor 4（CXCR4）","(D) 提高G-CSF與接受體之結合效益"],"answer":2,"image":""},{"id":"md2-108-2-73","subject":"md2","topic":"藥理-化學治療","meta":"108年第2次第73題","year":108,"session":2,"number":73,"question":"在針對癌症治療之免疫療法上，下列藥物何者主要以單株抗體抑制腫瘤細胞表面PD-L1並能干擾T淋巴細胞內PD-1之訊息作用，進而誘導上述淋巴細胞活化，提升監控及攻擊癌細胞等能力？","options":["(A) atezolizumab","(B) panitumumab","(C) ramucirumab","(D) rituximab"],"answer":0,"image":""},{"id":"md2-108-2-74","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"108年第2次第74題","year":108,"session":2,"number":74,"question":"反股寡核甘酸（antisense oligonucleotide）藥物mipomersen其主要用於治療同型性家族性高膽固醇血症（homozygous familial hypercholesterolemia），藉由降低血中low density lipoprotein (LDL)含量以達降血脂療效，下列何者為其主要之抑制標的？","options":["(A) PCSK9","(B) apoC-III","(C) apoB-100","(D) apoA-I"],"answer":2,"image":""},{"id":"md2-108-2-75","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"108年第2次第75題","year":108,"session":2,"number":75,"question":"降血脂藥Ezetimibe可抑制小腸吸收膽固醇（cholesterol），進而減少血中LDL含量。下列何者為此藥物之作用標的？","options":["(A) HMG-CoA reductase","(B) apoB-100","(C) transport protein NPC1L1","(D) microsomal triglyceride transfer protein（MTP）"],"answer":2,"image":""},{"id":"md2-108-2-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"108年第2次第76題","year":108,"session":2,"number":76,"question":"骨化性肌炎（myositis ossificans）病灶中的骨頭組織，最可能為何種變化？","options":["(A) 異生（dysplasia）","(B) 增生（hyperplasia）","(C) 萎縮（atrophy）","(D) 化生（metaplasia）"],"answer":3,"image":""},{"id":"md2-108-2-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"108年第2次第77題","year":108,"session":2,"number":77,"question":"漿細胞（plasma cell）內堆積大量免疫球蛋白，所形成的細胞內粉紅色物質，稱為：","options":["(A) Russell body","(B) amyloid","(C) Mallory-Denk body","(D) psammoma body"],"answer":0,"image":""},{"id":"md2-108-2-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"108年第2次第78題","year":108,"session":2,"number":78,"question":"下列疾病患者在使用小兒麻痺口服沙賓活病毒疫苗後，其中何者引起癱瘓性脊髓灰質炎（poliomyelitis）的風險較高？","options":["(A) 狄喬治氏症候群（DiGeorge syndrome）","(B) Bruton氏病（性聯丙種免疫球蛋白缺乏血症）（X-linked agammaglobulinemia [Bruton disease]）","(C) 慢性肉芽腫疾病（chronic granulomatous disease）","(D) 威斯科特－奧爾德里奇症候群（Wiskott-Aldrich syndrome）"],"answer":1,"image":""},{"id":"md2-108-2-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"108年第2次第79題","year":108,"session":2,"number":79,"question":"下列疾病中，何者致病機轉主要跟自體抗體（autoantibody）的產生有關？①尋常型天皰瘡（pemphigus vulgaris）②多發性結節性動脈炎（polyarteritis nodosa）③惡性貧血（pernicious anemia）","options":["(A) ①②③","(B) 僅①②","(C) 僅②③","(D) 僅①③"],"answer":3,"image":""},{"id":"md2-108-2-80","subject":"md2","topic":"病理-呼吸消化","meta":"108年第2次第80題","year":108,"session":2,"number":80,"question":"臨床上高度懷疑是肺癌的病人，同時呈現高血鈣（hypercalcemia）之現象時，則其肺部腫瘤之病理切片結果最可能是：","options":["(A) Adenocarcinoma","(B) Pleomorphic carcinoma","(C) Small cell carcinoma","(D) Squamous cell carcinoma"],"answer":3,"image":""},{"id":"md2-108-2-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"108年第2次第81題","year":108,"session":2,"number":81,"question":"Li-Fraumeni症候群之特性為平均發病年齡比正常族群低，且可同時發生一種以上的癌症。它與下列何種基因的變異關係最高？","options":["(A) RB","(B) TP53","(C) WT-1","(D) BRCA-1及BRCA-2"],"answer":1,"image":""},{"id":"md2-108-2-82","subject":"md2","topic":"病理-心血管血液","meta":"108年第2次第82題","year":108,"session":2,"number":82,"question":"下列血管炎中，何者與吸菸的關係最為密切，在疾病早期階段，戒菸可以緩解疾病的惡化？","options":["(A) Churg-Strauss syndrome","(B) 結節性多動脈炎（polyarteritis nodosa）","(C) 血栓閉塞性血管炎（thromboangiitis obliterans）","(D) Henoch-Schönlein purpura"],"answer":2,"image":""},{"id":"md2-108-2-83","subject":"md2","topic":"病理-心血管血液","meta":"108年第2次第83題","year":108,"session":2,"number":83,"question":"下列何種先天性心臟病必須保持開放的動脈導管（ductus arteriosus），否則嬰兒出生後通常很快致命？","options":["(A) 心室中隔缺損（ventricular septal defect）","(B) 主動脈縮窄（coarctation of aorta）","(C) 心房中隔缺損（atrial septal defect）","(D) 主動脈閉鎖（aortic atresia）"],"answer":3,"image":""},{"id":"md2-108-2-84","subject":"md2","topic":"病理-心血管血液","meta":"108年第2次第84題","year":108,"session":2,"number":84,"question":"有關何杰金氏淋巴瘤（Hodgkin lymphoma）的敘述，下列何者正確？","options":["(A) 整體來說，治療效果與存活率低於非何杰金氏淋巴瘤（non-Hodgkin lymphoma）","(B) 大多數發生在淋巴結以外的器官","(C) 典型腫瘤中，腫瘤細胞只占所有細胞的小部分","(D) 病理亞型比臨床分期對存活率影響較大"],"answer":2,"image":""},{"id":"md2-108-2-85","subject":"md2","topic":"病理-心血管血液","meta":"108年第2次第85題","year":108,"session":2,"number":85,"question":"下列有關單株丙型球蛋白病變（monoclonal gammopathy）之敘述，何者錯誤？","options":["(A) 常見於急性發炎之病人","(B) 不一定會有Bence-Jones蛋白尿現象","(C) 可能只含有免疫球蛋白之重鏈","(D) 不一定會有漿細胞瘤或多發性骨髓瘤"],"answer":0,"image":""},{"id":"md2-108-2-86","subject":"md2","topic":"病理-呼吸消化","meta":"108年第2次第86題","year":108,"session":2,"number":86,"question":"下列有關機化性肺炎（organizing pneumonia）的敘述，何者錯誤？","options":["(A) 肺泡中塞滿球狀之纖維母細胞增生（Masson body）","(B) 病變不涉及小支氣管","(C) 通常無間質性纖維化","(D) 通常無蜂巢狀纖維化"],"answer":1,"image":""},{"id":"md2-108-2-87","subject":"md2","topic":"病理-呼吸消化","meta":"108年第2次第87題","year":108,"session":2,"number":87,"question":"急性氣管炎合併肺部瀰漫性間質發炎，最可能是下列那一類感染引起？","options":["(A) 病毒","(B) 肺炎雙球菌","(C) 葡萄球菌","(D) 黴菌"],"answer":0,"image":""},{"id":"md2-108-2-88","subject":"md2","topic":"病理-呼吸消化","meta":"108年第2次第88題","year":108,"session":2,"number":88,"question":"肺膨脹不全（atelectasis）最少見於：","options":["(A) 氣道阻塞","(B) 肋膜腔積水","(C) 肺泡表面張力素不足","(D) 急性肺炎"],"answer":3,"image":""},{"id":"md2-108-2-89","subject":"md2","topic":"病理-呼吸消化","meta":"108年第2次第89題","year":108,"session":2,"number":89,"question":"關於酒精性肝炎之敘述，何者錯誤？","options":["(A) AST通常比ALT高約兩倍以上","(B) 典型可見肝臟脂肪堆積，Mallory-Denk bodies，嗜中性白血球（neutrophils）浸潤","(C) 纖維化通常由portal areas開始，之後往central vein延伸","(D) 酗酒而言，女性似乎比男性更容易受到肝臟損傷"],"answer":2,"image":""},{"id":"md2-108-2-90","subject":"md2","topic":"病理-呼吸消化","meta":"108年第2次第90題","year":108,"session":2,"number":90,"question":"下列關於hepatocellular adenoma的敘述何者錯誤？","options":["(A) 為良性肝細胞的增生","(B) 與maturity onset diabetes of the young type 3（MODY-3）有關的是HNF1-alpha inactivated hepatocellular adenoma","(C) beta-catenin activated adenoma在所有hepatocellular adenoma型別中，惡性化風險（risk for malignant transformation）最低","(D) gp130的突變出現在inflammatory type adenoma"],"answer":2,"image":""},{"id":"md2-108-2-91","subject":"md2","topic":"病理-呼吸消化","meta":"108年第2次第91題","year":108,"session":2,"number":91,"question":"關於自身免疫性胃炎（autoimmune gastritis）何者錯誤？","options":["(A) 針對壁細胞和內在因子的自體抗體（antibodies to parietal cells & intrinsic factor）可在血清及胃液中測得","(B) 維生素B缺乏（vitamin B deficiency）1212","(C) 胃酸分泌不足，胃泌素（gastrin）分泌增加","(D) 胃竇（antrum）內分泌細胞減少"],"answer":3,"image":""},{"id":"md2-108-2-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第2次第92題","year":108,"session":2,"number":92,"question":"以下何種膀胱病灶最常發生FGFR3基因突變？","options":["(A) 非侵襲性低惡性度泌尿上皮癌（noninvasive low-grade papillary urothelial carcinoma）","(B) 非侵襲性高惡性度泌尿上皮癌（noninvasive high-grade papillary urothelial carcinoma）","(C) 原位癌（carcinoma in situ）","(D) 侵襲性高惡性度泌尿上皮癌（invasive high-grade papillary urothelial carcinoma）"],"answer":0,"image":""},{"id":"md2-108-2-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第2次第93題","year":108,"session":2,"number":93,"question":"在原發性膜性腎病變（primary membranous nephropathy）沉積在腎小球最主要的免疫球蛋白為：","options":["(A) IgG1","(B) IgG2","(C) IgG3","(D) IgG4"],"answer":3,"image":""},{"id":"md2-108-2-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第2次第94題","year":108,"session":2,"number":94,"question":"亞急性肉芽腫性甲狀腺炎（subacute granulomatous thyroiditis）之致病機轉尚未完全清楚，但是目前認為此疾病最可能是由下列何種感染所引發的？","options":["(A) 細菌感染（bacterial infection）","(B) 黴菌感染（fungal infection）","(C) 病毒感染（viral infection）","(D) 結核菌感染（tuberculosis）"],"answer":2,"image":""},{"id":"md2-108-2-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第2次第95題","year":108,"session":2,"number":95,"question":"下列何者不是前列腺癌（prostate cancer）較常見的基因變化？","options":["(A) TMPRSS2-ERG或TMPRSS2-ETV1基因融合（gene fusions）","(B) 染色體8q24缺失（deletion）","(C) PTEN基因缺失（deletion）","(D) TP53基因缺失（deletion）或突變（mutation）"],"answer":1,"image":""},{"id":"md2-108-2-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第2次第96題","year":108,"session":2,"number":96,"question":"下列有關成人睪丸生殖細胞腫瘤（testicular germ cell tumor）的敘述，何者較不正確？","options":["(A) 卵黃囊腫瘤（yolk sac tumor）常常為單一組織學型態，很少與其他組織學型態如胚胎癌（embryonal carcinoma）混合","(B) 精母細胞瘤（seminoma）是最常見的組織學型態","(C) 胚胎癌（embryonal carcinoma）的腫瘤生物特性較精母細胞瘤（seminoma）更具侵襲性","(D) 由絨毛膜癌（choriocarcinoma）單一組織學型態所組成的睪丸腫瘤相當罕見"],"answer":0,"image":""},{"id":"md2-108-2-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"108年第2次第97題","year":108,"session":2,"number":97,"question":"50歲女性因例行性子宮頸抹片結果異常，接受進一步子宮頸切片檢查，發現異生的細胞取代了整層原有的子宮上皮細胞，以原位雜交法（in situ hybridization）發現在這些異生的細胞有人類乳突病毒（human papillomavirus）第16型的DNA，則下列何者為最可能之診斷？","options":["(A) 尖形濕疣（condyloma acuminatum）","(B) 慢性子宮頸炎併鱗狀細胞化生（chronic cervicitis with squamous metaplasia）","(C) 子宮頸上皮內贅生第三級（cervical intraepithelial neoplasia III）","(D) 子宮頸息肉（cervical polyp）"],"answer":2,"image":""},{"id":"md2-108-2-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"108年第2次第98題","year":108,"session":2,"number":98,"question":"有關發育不良痣（dysplastic nevi）的敘述，下列何者正確？","options":["(A) 通常較一般的痣（nevi）小，常小於5mm","(B) 只見於曬到陽光的皮膚","(C) 組織形態通常是皮內痣（intradermal nevi）","(D) 大部分此類病灶都不會轉變成黑色素瘤（melanoma）"],"answer":3,"image":""},{"id":"md2-108-2-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"108年第2次第99題","year":108,"session":2,"number":99,"question":"鏡下描述牛皮癬（psoriasis）有所謂的角化不全（parakeratosis），這是指下列何種表皮角質層的變化而言？","options":["(A) 增厚","(B) 形成玻璃質樣物質","(C) 角質並不成熟，仍有細胞核存在","(D) 變薄"],"answer":2,"image":""},{"id":"md2-108-2-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"108年第2次第100題","year":108,"session":2,"number":100,"question":"惡性貧血（pernicious anemia）患者所伴隨發生的特殊神經病理學病變是在何部位？","options":["(A) 大腦白質","(B) 脊髓","(C) 大腦皮質","(D) 小腦"],"answer":1,"image":""},{"id":"md2-109-1-1","subject":"md2","topic":"細菌學","meta":"109年第1次第1題","year":109,"session":1,"number":1,"question":"有關氣性壞疽（gas gangrene）之敘述，下列何者錯誤？","options":["(A) 最常見之致病菌為化膿性鏈球菌（Streptococcus pyogenes）","(B) 是經由傷口感染之急性肌肉壞死性疾病，感染會急速往周邊擴散而使病灶擴大","(C) 治療方法包括清創術（debridement）、抗生素治療及傷口高壓氧治療（hyperbaric oxygen therapy）","(D) 目前尚無有效的疫苗（vaccine）"],"answer":0,"image":""},{"id":"md2-109-1-2","subject":"md2","topic":"細菌學","meta":"109年第1次第2題","year":109,"session":1,"number":2,"question":"有關白喉桿菌（Corynebacterium diphtheriae）的敘述，下列何者正確？","options":["(A) 耐酸性染色陽性為一重要診斷依據","(B) 人類是唯一的天然宿主","(C) 攜帶白喉毒素（diphtheria toxin）的基因位於質體上","(D) 還沒有疫苗可預防"],"answer":1,"image":""},{"id":"md2-109-1-3","subject":"md2","topic":"細菌學","meta":"109年第1次第3題","year":109,"session":1,"number":3,"question":"利用早期分泌抗原標的-6（ESAT-6）及培養過濾蛋白-10（CFP-10），做為抗原以偵測病患的T細胞所產生的丙型干擾素（IFN-γ），其目的是檢驗病患受到下列那一種微生物的感染？","options":["(A) 立氏立克次體（Rickettsia rickettsii）","(B) 煙麴霉菌（Aspergillus fumigatus）","(C) 肺炎黴漿菌（Mycoplasma pneumoniae）","(D) 結核分枝桿菌（Mycobacterium tuberculosis）"],"answer":3,"image":""},{"id":"md2-109-1-4","subject":"md2","topic":"細菌學","meta":"109年第1次第4題","year":109,"session":1,"number":4,"question":"關於人類單核細胞艾利希體症（human monocytic ehrlichiosis）的敘述，下列何者錯誤？","options":["(A) 以青黴素（penicillin）、氨基糖苷（aminoglycosides）、大環內酯（macrolides）等類藥物治療有效","(B) 其致病菌可在血液單核球（monocyte）和巨噬細胞（macrophage）內進行繁殖","(C) 多數病患會有血清轉胺酶（serum transaminase）升高及血小板減少（thrombocytopenia）的情況","(D) 臨床主要以核酸增幅法（nucleic acid amplification）或血清學檢驗（serological test）確認此疾病"],"answer":0,"image":""},{"id":"md2-109-1-5","subject":"md2","topic":"細菌學","meta":"109年第1次第5題","year":109,"session":1,"number":5,"question":"關於肺炎鏈球菌（Streptococcus pneumoniae）的敘述，下列何者錯誤？","options":["(A) 所產生的莢膜（capsule）能抵抗吞噬作用（phagocytosis）","(B) 此菌於肺泡腔（alveolar spaces）大量生長，可造成肺炎（pneumonia）","(C) 透過台口酸（teichoic acid）和胜肽聚醣（peptidoglycan）碎片，可誘發替代型補體活化路徑（alternative complement pathway）","(D) 多價疫苗（polyvalent vaccine）是由常見的血清型菌株所產生的體表蛋白質（surface proteins）所製備的"],"answer":3,"image":""},{"id":"md2-109-1-6","subject":"md2","topic":"細菌學","meta":"109年第1次第6題","year":109,"session":1,"number":6,"question":"關於腸內桿菌科（Enterobacteriaceae）O抗原（O antigen）的敘述，下列何者正確？","options":["(A) 是控制物質進出細菌的通道","(B) 具有鞭毛蛋白（flagellin）","(C) 細菌細胞壁脂多醣體（lipopolysaccharide）的一部分","(D) 含胜肽聚醣（peptidoglycan），可用來維持細菌細胞壁的形態"],"answer":2,"image":""},{"id":"md2-109-1-7","subject":"md2","topic":"細菌學","meta":"109年第1次第7題","year":109,"session":1,"number":7,"question":"關於艱難梭狀芽胞桿菌（Clostridium difficile）的敘述，下列何者正確？","options":["(A) 疾病經常是因長期使用抗生素，造成腸道菌群改變所引起","(B) 可用安比西林（ampicillin）和克林黴素（clindamycin）治療","(C) 會產生腸毒素（enterotoxin），造成肌肉痙攣","(D) 會產生α毒素（α toxin），造成嚴重的軟組織壞死"],"answer":0,"image":""},{"id":"md2-109-1-8","subject":"md2","topic":"細菌學","meta":"109年第1次第8題","year":109,"session":1,"number":8,"question":"下列那些致病菌主要透過節肢動物（arthropods）的叮咬而傳染，並能在人類細胞內繁殖？①宋內志賀氏菌（Shigella sonnei）②馬爾他布魯氏菌（Brucella melitensis）③土拉弗朗西斯菌（Francisella tularensis） ④嗜吞噬細胞無形體（Anaplasma phagocytophilum）","options":["(A) ①②","(B) ③④","(C) ②④","(D) ①③"],"answer":1,"image":""},{"id":"md2-109-1-9","subject":"md2","topic":"細菌學","meta":"109年第1次第9題","year":109,"session":1,"number":9,"question":"下列何者並非金黃色葡萄球菌（Staphylococcus aureus）常見的致病因子（virulence factor）？","options":["(A) 凝固酶（coagulase）","(B) 毒性休克症候毒素-1（toxic shock syndrome toxin-1）","(C) 水腫因子（edema factor）","(D) 蛋白質A（protein A）"],"answer":2,"image":""},{"id":"md2-109-1-10","subject":"md2","topic":"病毒學","meta":"109年第1次第10題","year":109,"session":1,"number":10,"question":"有關腺病毒（adenovirus）的敘述，下列何者正確？","options":["(A) 病毒蛋白質E6和E7會抑制p53的作用","(B) 感染上皮細胞，會在細胞核內形成包涵體（inclusion body）","(C) 具有線型雙股DNA，並含有外套膜（envelope）","(D) 在淋巴組織造成溶解性感染（lytic infection）"],"answer":1,"image":""},{"id":"md2-109-1-11","subject":"md2","topic":"病毒學","meta":"109年第1次第11題","year":109,"session":1,"number":11,"question":"下列那一種病毒會以反轉錄酶（reverse transcriptase）複製病毒基因體？","options":["(A) 乳突瘤病毒（papillomavirus）","(B) 西尼羅河病毒（West Nile virus）","(C) B型肝炎病毒（hepatitis B virus）","(D) 呼吸道細胞融合病毒（respiratory syncytial virus）"],"answer":2,"image":""},{"id":"md2-109-1-12","subject":"md2","topic":"病毒學","meta":"109年第1次第12題","year":109,"session":1,"number":12,"question":"抗病毒藥物奧斯他偉（oseltamivir），主要是抑制病毒的那一種酵素？","options":["(A) 蛋白酶（protease）","(B) 神經氨酸酶（neuraminidase）","(C) 胸腺嘧啶激酶（thymidine kinase）","(D) 反轉錄酶（reverse transcriptase）"],"answer":1,"image":""},{"id":"md2-109-1-13","subject":"md2","topic":"病毒學","meta":"109年第1次第13題","year":109,"session":1,"number":13,"question":"下列何種病毒會在宿主細胞內造成內格里小體（Negri bodies）的產生？","options":["(A) 狂犬病病毒（Rabies virus）","(B) 單純疱疹病毒（Herpes-simplex virus, HSV）","(C) 痘病毒（Poxvirus）","(D) B型肝炎病毒（Hepatitis B virus）"],"answer":0,"image":""},{"id":"md2-109-1-14","subject":"md2","topic":"病毒學","meta":"109年第1次第14題","year":109,"session":1,"number":14,"question":"有關抑制病毒的藥物中，下列何者是胜肽類的藥物？","options":["(A) 恩夫韋（enfuvirtide）","(B) 丙氧鳥苷（ganciclovir）","(C) 拉米夫定（lamivudine）","(D) 奧斯他偉（oseltamivir）"],"answer":0,"image":""},{"id":"md2-109-1-15","subject":"md2","topic":"病毒學","meta":"109年第1次第15題","year":109,"session":1,"number":15,"question":"有關德國麻疹病毒（rubella virus）的敘述，下列何者錯誤？","options":["(A) 人類為唯一宿主","(B) 只有一種血清型","(C) 可施打MMR疫苗預防感染","(D) 常規以喉頭拭子（throat swab）培養病毒，做為診斷感染的根據"],"answer":3,"image":""},{"id":"md2-109-1-16","subject":"md2","topic":"真菌學","meta":"109年第1次第16題","year":109,"session":1,"number":16,"question":"培養糠秕馬拉癬菌（Malassezia furfur）時，為提高培養率，最常於培養基中加入下列何者？","options":["(A) 澱粉（Starch）","(B) L-半胱胺酸（L-cysteine）","(C) 橄欖油（Olive oil）","(D) N-乙醯葡萄胺糖（N-acetylglucosamine）"],"answer":2,"image":""},{"id":"md2-109-1-17","subject":"md2","topic":"真菌學","meta":"109年第1次第17題","year":109,"session":1,"number":17,"question":"下列那一種真菌（fungi）通常不形成菌絲（hyphae）構造？","options":["(A) 熱帶念珠菌（Candida tropicalis）","(B) 白色念珠菌（Candida albicans）","(C) 光滑念珠菌（Candida glabrata）","(D) 近平滑念珠菌（Candida parapsilosis）"],"answer":2,"image":""},{"id":"md2-109-1-18","subject":"md2","topic":"免疫學","meta":"109年第1次第18題","year":109,"session":1,"number":18,"question":"位於腸道底層免疫組織中之M細胞的主要免疫功能為：","options":["(A) 直接殺菌","(B) 製造抗體","(C) 捕捉及轉運腸道中的抗原至下層的淋巴組織","(D) 保護周邊的腸道表皮細胞"],"answer":2,"image":""},{"id":"md2-109-1-19","subject":"md2","topic":"免疫學","meta":"109年第1次第19題","year":109,"session":1,"number":19,"question":"模式辨識受體（pattern recognition receptors, PRRs）是先天免疫系統用來識別病原相關分子模式（pathogen- associated molecular patterns, PAMPs）的抗原受體，在所有先天免疫細胞都會表現。有關模式辨識受體的敘述何者錯誤？","options":["(A) 模式辨識受體中的類鐸受體（Toll-like receptors）是演化上古老而保守的病原辨識受體，即便在無脊椎動物也有表現","(B) 類鐸受體（Toll-like receptors）中TLR3和TLR7分別辨識源自於病毒的雙股及單股RNA","(C) 模式辨識受體中的類NOD受體（nod-like receptors）主要是辨識胞內的病原菌，如沙門氏菌（Salmonella）及李斯特菌（Listeria）的細胞壁成分","(D) 模式辨識受體中的類RIG-I受體（RIG-I-like receptors）是辨識DNA病毒的DNA，而且免疫細胞的類RIG-I受體和DNA結合後的訊息傳遞結果會產生第一型干擾素"],"answer":3,"image":""},{"id":"md2-109-1-20","subject":"md2","topic":"免疫學","meta":"109年第1次第20題","year":109,"session":1,"number":20,"question":"TCR為T細胞辨識外來抗原之主要分子，但TCR本身並不足以執行訊息傳遞的功能。TCR必須與CD3 complex組合為TCR complex以達到專一辨識抗原及訊息傳遞作用。下列原因何者錯誤？","options":["(A) TCR的α-chain及β-chain的cytoplasmic domain非常短，無法進行signal transduction","(B) TCR與CD3 complex結合而表現在細胞表面","(C) CD3 complex的膜蛋白分子具有immunoreceptor tyrosine-based activation motifs（ITAMs），故能促進胞內訊息傳遞","(D) CD3 complex的膜蛋白分子具有immunoreceptor tyrosine-based inhibition motifs（ITIMs），故能促進胞內訊息傳遞"],"answer":3,"image":""},{"id":"md2-109-1-21","subject":"md2","topic":"免疫學","meta":"109年第1次第21題","year":109,"session":1,"number":21,"question":"具有前期B細胞抗原接受器（pre-B cell receptor）之B型細胞具有下列那一項生物特性？","options":["(A) 輕鏈基因重組（light chain gene rearrangement）","(B) 細胞表面具IgM分子","(C) 快速細胞分裂","(D) 接受專一性抗原刺激"],"answer":2,"image":""},{"id":"md2-109-1-22","subject":"md2","topic":"免疫學","meta":"109年第1次第22題","year":109,"session":1,"number":22,"question":"成熟的CD4 T細胞在活化後，可以分化為不同的effector T細胞，其中可以分泌IL-17的CD4 T細胞主要功能是：","options":["(A) 清除胞內病原的感染","(B) 清除胞外細菌的感染","(C) 毒殺胞外的寄生蟲","(D) 抑制T細胞過度的發炎反應"],"answer":1,"image":""},{"id":"md2-109-1-23","subject":"md2","topic":"病理-免疫感染遺傳","meta":"109年第1次第23題","year":109,"session":1,"number":23,"question":"下列有關遺傳性免疫缺失疾病（immunodeficiency diseases）的敘述，何者錯誤？","options":["(A) autoimmune polyendocrinopathy-candidiasis-ectodermal dystrophy（APECED）是因為AIRE基因缺陷所造成","(B) bare lymphocyte syndrome的病人是因為MHC class II無法表現，所以體內CD4 T細胞數目雖正常但表面沒有MHC class II","(C) Omenn syndrome常因為是RAG1或RAG2基因突變","(D) 如果是白血球先天性缺陷造成的疾病，造血幹細胞移植是可行的療法"],"answer":1,"image":""},{"id":"md2-109-1-24","subject":"md2","topic":"免疫學","meta":"109年第1次第24題","year":109,"session":1,"number":24,"question":"腸胃道中含有大量IgA，在黏膜免疫反應中可以有效阻斷病原菌入侵人體，相關的敘述何者最正確？","options":["(A) 血清與腸胃道中2種IgA亞型的抗體比例一致","(B) 細胞激素IL-12可以促進B細胞分泌IgA","(C) 分泌型IgA上的分泌片段（secretory component）是由上皮細胞合成的","(D) 病原菌抗原結合IgA，可以有效啟動補體古典活化路徑"],"answer":2,"image":""},{"id":"md2-109-1-25","subject":"md2","topic":"免疫學","meta":"109年第1次第25題","year":109,"session":1,"number":25,"question":"家豪對塵蟎過敏，常常在秋冬換季時出現流鼻水、打噴嚏、眼睛癢等症狀，在發作時他的免疫反應相較於正常人最可能出現下列何種現象？","options":["(A) T細胞分泌較高量的TGF-β細胞激素","(B) 有明顯遲發性過敏反應（delayed type hypersensitivity）","(C) 出現很高量對塵蟎具特異性的IgA","(D) 活化的肥大細胞（mast cell）釋放發炎介質"],"answer":3,"image":""},{"id":"md2-109-1-26","subject":"md2","topic":"免疫學","meta":"109年第1次第26題","year":109,"session":1,"number":26,"question":"臨床上成功應用於breast cancer免疫療法的單株抗體trastuzumab（Herceptin）是針對下列那一個分子？","options":["(A) Her-2/neu","(B) MAG-1","(C) MUC-1","(D) CD-20"],"answer":0,"image":""},{"id":"md2-109-1-27","subject":"md2","topic":"免疫學","meta":"109年第1次第27題","year":109,"session":1,"number":27,"question":"以下方法均可減少植體抗宿主疾病（graft-versus-host disease, GVHD），下列何者除外？","options":["(A) 以alemtuzumab處理預植入的造血幹細胞，經由拮抗CD52的作用，使得成熟的T淋巴球數目減少","(B) 將預植入的造血幹細胞實行淋巴球混合作用（mixed lymphocyte reaction），以減低T淋巴球的數目","(C) 選擇MHC class I及MHC class II配合的植體，以降低植入後成熟T淋巴球的抗宿主反應","(D) 使用抗胸腺球蛋白（anti-thymoglobulin）預處理植入的細胞，減低T淋巴球及白血球的數目"],"answer":1,"image":""},{"id":"md2-109-1-28","subject":"md2","topic":"免疫學","meta":"109年第1次第28題","year":109,"session":1,"number":28,"question":"腫瘤細胞缺乏下列何種分子時，NK細胞有更好的毒殺腫瘤細胞能力？","options":["(A) MHC class I","(B) MHC class II","(C) T1","(D) HER-2/neu"],"answer":0,"image":""},{"id":"md2-109-1-29","subject":"md2","topic":"寄生蟲學","meta":"109年第1次第29題","year":109,"session":1,"number":29,"question":"罹患瀰漫性糞小桿線蟲症（disseminated strongyloidiasis stercoralis）的病患，通常有下列那些現象？①蟲體僅侵犯腸道及肺臟②容易發生在免疫缺陷的病人③嗜酸性白血球增加不明顯","options":["(A) 僅①②","(B) 僅①③","(C) 僅②③","(D) ①②③"],"answer":2,"image":""},{"id":"md2-109-1-30","subject":"md2","topic":"寄生蟲學","meta":"109年第1次第30題","year":109,"session":1,"number":30,"question":"下列有關廣東住血線蟲（Angiostrongylus cantonensis）感染人體的敘述，有幾項敘述是正確的？①人因食入未熟帶蟲的蝸牛而感染②人體為終宿主（final host）③蟲體只侵犯人體腦脊髓④引起嗜酸性白血球明顯增加","options":["(A) 1項","(B) 2項","(C) 3項","(D) 4項"],"answer":1,"image":""},{"id":"md2-109-1-31","subject":"md2","topic":"寄生蟲學","meta":"109年第1次第31題","year":109,"session":1,"number":31,"question":"下列何者與日本血吸蟲（Schistosoma japonicum）或其在患者引起的疾病無關？","options":["(A) 尾幼（cercariae）","(B) 囊幼（metacercariae）","(C) 肉芽腫（granulomas）","(D) 片山熱（Katayama fever）"],"answer":1,"image":""},{"id":"md2-109-1-32","subject":"md2","topic":"寄生蟲學","meta":"109年第1次第32題","year":109,"session":1,"number":32,"question":"下列何種絛蟲之受孕節片具有卵囊（egg capsules）？","options":["(A) 犬複殖器絛蟲（Dipylidium caninum）","(B) 牛肉絛蟲（Taenia saginata）","(C) 縮小包膜絛蟲（Hymenolepis diminuta）","(D) 廣節裂頭絛蟲（Diphyllobothrium latum）"],"answer":0,"image":""},{"id":"md2-109-1-33","subject":"md2","topic":"寄生蟲學","meta":"109年第1次第33題","year":109,"session":1,"number":33,"question":"陳小姐因愛美而配戴隱形眼鏡多年，日前因眼睛刺痛、紅腫而求助於眼科醫師，經診斷罹患嚴重角膜炎（keratitis），並於角膜刮取物抹片鏡檢時發現有角狀雙層壁囊體。依據上述結果，陳小姐最可能感染何種寄生蟲？","options":["(A) 大腸阿米巴（Entamoeba coli）","(B) 痢疾阿米巴（Entamoeba histolytica）","(C) 福氏內格里阿米巴（Naegleria fowleri）","(D) 棘阿米巴（Acanthamoeba spp.）"],"answer":3,"image":""},{"id":"md2-109-1-34","subject":"md2","topic":"寄生蟲學","meta":"109年第1次第34題","year":109,"session":1,"number":34,"question":"下列有關利什曼原蟲之敘述中，何者正確？","options":["(A) 慢性感染巴西利什曼原蟲（Leishmania braziliensis）之患者，其耳朵軟骨常被侵蝕造成chiclero's ulcer","(B) 嬰兒利什曼原蟲（Leishmania infantum）能侵入人體所有的有核細胞中分裂增殖","(C) 杜氏利什曼原蟲（Leishmania donovani）是黑熱病（kala-azar）的致病原","(D) 熱帶利什曼原蟲（Leishmania tropica）從未有導致內臟利什曼原蟲症（visceral leishmaniasis）的人體病例報告"],"answer":2,"image":""},{"id":"md2-109-1-35","subject":"md2","topic":"寄生蟲學","meta":"109年第1次第35題","year":109,"session":1,"number":35,"question":"有關病媒（vector）及其媒介疾病之關係，下列何者錯誤？","options":["(A) 埃及斑蚊（Aedes aegypti）傳播黃熱病（yellow fever）","(B) 蚋（Simulium spp.）傳播河川盲（river blindness）","(C) 采采蠅（tsetse fly）傳播卡格氏症（Chagas’disease）","(D) 白蛉（sandfly）傳播利什曼原蟲症（leishmaniasis）"],"answer":2,"image":""},{"id":"md2-109-1-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第1次第36題","year":109,"session":1,"number":36,"question":"假設有抽菸族群的血中古丁尼濃度（ng/ml）為常態分配（平均值=11, 變異數=16），無抽菸族群的血中古丁尼濃度則為常態分配（平均值=6, 變異數=16）。某研究提出可利用血中古丁尼濃度大於7判定為有抽菸者，此規則所犯的偽陽率（false positive rate）為0.25，偽陰率（false negative rate）為0.15。若將判定抽菸標準提高到血中古丁尼濃度大於8.5，偽陽率與敏感度（sensitivity）會如何改變？","options":["(A) 偽陽率下降，敏感度下降","(B) 偽陽率下降，敏感度上升","(C) 偽陽率上升，敏感度下降","(D) 偽陽率上升，敏感度上升"],"answer":0,"image":""},{"id":"md2-109-1-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第1次第37題","year":109,"session":1,"number":37,"question":"某研究者想檢定來自北中南部的男大學生的平均身高是否一樣，在某大學隨機抽取來自北中南部男大學生各200名，下列統計分析方法何者最恰當？","options":["(A) Z檢定（Z test）","(B) 變異數分析（ANOVA）","(C) 配對t檢定（Paired t-test）","(D) 列聯表分析（Contingency table）"],"answer":1,"image":""},{"id":"md2-109-1-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第1次第38題","year":109,"session":1,"number":38,"question":"某研究者想檢定某基因多型性（AA／AG組相對GG組）是否與口腔癌的發生有關，在某醫院有200名口腔癌患者參與此研究，每位口腔癌患者都配對1名沒有口腔癌的健康者，分別測量其基因型，下列統計分析方法何者最恰當？","options":["(A) 線性迴歸","(B) 獨立樣本之卡方檢定","(C) 配對t檢定","(D) McNemar卡方檢定"],"answer":3,"image":""},{"id":"md2-109-1-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第1次第39題","year":109,"session":1,"number":39,"question":"有一研究發現具有AA基因型的病人相較於其他基因型病人，對相同治療藥物的反應較佳，則AA基因型扮演下列何種角色？","options":["(A) 干擾因子","(B) 拮抗因子","(C) 修飾因子","(D) 分化因子"],"answer":2,"image":""},{"id":"md2-109-1-40","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第1次第40題","year":109,"session":1,"number":40,"question":"有關描述變項的性質，下列敘述何者正確？","options":["(A) 標準誤（standard error）適合描述常態連續資料的分散情況","(B) 幾何平均值（geometric mean）適合描述類別資料的集中趨勢","(C) 標準差（standard deviation）適合描述類別資料的集中趨勢","(D) th第50百分位數（the 50 percentile）適合描述連續資料的集中趨勢"],"answer":3,"image":""},{"id":"md2-109-1-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"109年第1次第41題","year":109,"session":1,"number":41,"question":"下列那一項不屬於溫室效應氣體（green house gases）？","options":["(A) NO 2","(B) CO 2","(C) CH 4","(D) NH 3"],"answer":3,"image":""},{"id":"md2-109-1-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"109年第1次第42題","year":109,"session":1,"number":42,"question":"雞肉必須煮熟食用，是屬於「食品安全管制系統」（HACCP）的那個原則？","options":["(A) 危害評估","(B) 決定管制重點","(C) 針對管制重點設置管制程序與標準","(D) 建立管制監測系統"],"answer":1,"image":""},{"id":"md2-109-1-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"109年第1次第43題","year":109,"session":1,"number":43,"question":"下列何種金屬過量暴露吸收，會造成人體出現振顫（tremor）和動作不協調（ataxia）等水俣病症狀？","options":["(A) 汞","(B) 鉈","(C) 鎘","(D) 鋁"],"answer":0,"image":""},{"id":"md2-109-1-44","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"109年第1次第44題","year":109,"session":1,"number":44,"question":"下列那一項工作不屬於塵肺症之危險族群？","options":["(A) 報社印刷工人暴露紙屑纖維","(B) 噴砂工人暴露二氧化矽的粉塵","(C) 耐火磚製造工人暴露石棉","(D) 造船工人暴露石棉"],"answer":0,"image":""},{"id":"md2-109-1-45","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"109年第1次第45題","year":109,"session":1,"number":45,"question":"某勞工於甲、乙、丙場所分別工作2.5、3、2.5小時，若其甲苯濃度分別為40、150、20 ppm，其時量平均濃度（TWA）為何？","options":["(A) 70 ppm","(B) 74 ppm","(C) 75 ppm","(D) 80 ppm"],"answer":2,"image":""},{"id":"md2-109-1-46","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"109年第1次第46題","year":109,"session":1,"number":46,"question":"暴露於下列何種危害物最可能造成鼻中膈穿孔？","options":["(A) 四氯化碳","(B) 二甲機甲醯胺","(C) 鉻酸","(D) 有機磷"],"answer":2,"image":""},{"id":"md2-109-1-47","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第1次第47題","year":109,"session":1,"number":47,"question":"針對青少年處於不同階段，而採取不同步驟與策略協助其戒菸，例如若吸菸者缺乏戒菸意願，應教導吸菸害處以強化戒菸動機，若吸菸者打算近期內戒菸，可提供其戒菸計畫與方法，這是應用那一種理論或模式來改變行為？","options":["(A) 社會學習理論","(B) 健康信念模式","(C) 操作性制約理論","(D) 跨理論模式"],"answer":3,"image":""},{"id":"md2-109-1-48","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第1次第48題","year":109,"session":1,"number":48,"question":"下列那一項不是世界衛生組織所提出的健康城市的健康指標？","options":["(A) 低出生體重比率","(B) 嬰兒死亡率","(C) 墮胎率（相對於每一個活產數）","(D) 總死亡率"],"answer":2,"image":""},{"id":"md2-109-1-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"109年第1次第49題","year":109,"session":1,"number":49,"question":"有關以公權力推動強制性的衛生政策之倫理原則，下列敘述何者錯誤？","options":["(A) 所採用的手段必須能夠達到政策目的","(B) 所要達成的公共利益與所犧牲的個人利益之間要符合比例","(C) 即使必須犧牲個人利益，仍應採取最小侵害手段","(D) 即使某些衛生政策可能犧牲個人自由，但為了當事人的健康，也為了國民健康，衛生主管機關仍然應該毫無例外地推動這些政策"],"answer":3,"image":""},{"id":"md2-109-1-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"109年第1次第50題","year":109,"session":1,"number":50,"question":"為深入瞭解醫院內外部處境，醫院管理實務上常使用「SWOT」方法來做策略分析（strategic analysis），這四個字母的“O”是指：","options":["(A) opportunity","(B) opponent","(C) optimum","(D) operation"],"answer":0,"image":""},{"id":"md2-109-1-51","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"109年第1次第51題","year":109,"session":1,"number":51,"question":"有關fondaparinux敘述，下列何者錯誤？","options":["(A) 主要作用為抑制凝血因子thrombin","(B) 透過antithrombin III結合作用來中和factor Xa","(C) 採用皮下注射，每天一次","(D) 腎臟疾病患者，不宜使用"],"answer":0,"image":""},{"id":"md2-109-1-52","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第1次第52題","year":109,"session":1,"number":52,"question":"下列何種藥物不具有改善骨質疏鬆的效果？","options":["(A) vitamin D","(B) alendronate","(C) raloxifene","(D) danazol"],"answer":3,"image":""},{"id":"md2-109-1-53","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第1次第53題","year":109,"session":1,"number":53,"question":"下列何項藥物可用以治療佩吉特氏病（Paget's disease）？","options":["(A) thyroxine","(B) exenatide","(C) calcitonin","(D) rosiglitazone"],"answer":2,"image":""},{"id":"md2-109-1-54","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"109年第1次第54題","year":109,"session":1,"number":54,"question":"那一種藥物臨床上最適用於治療心房心律不整及防止心肌梗塞之復發與突發性死亡？","options":["(A) verapamil","(B) quinidine","(C) propranolol","(D) flecainide"],"answer":2,"image":""},{"id":"md2-109-1-55","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"109年第1次第55題","year":109,"session":1,"number":55,"question":"下列降血壓藥物中，何者使血管舒張的機轉主要是抑制鈣離子內流入平滑肌細胞？","options":["(A) aliskiren","(B) carvedilol","(C) doxazosin","(D) felodipine"],"answer":3,"image":""},{"id":"md2-109-1-56","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第1次第56題","year":109,"session":1,"number":56,"question":"長期服用下列何種藥物來治療胃潰瘍時，易導致陽痿？","options":["(A) omeprazole","(B) cimetidine","(C) nizatidine","(D) ranitidine"],"answer":1,"image":""},{"id":"md2-109-1-57","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第1次第57題","year":109,"session":1,"number":57,"question":"一早產兒發生動脈導管閉鎖不全，可以使用下列何種藥物來使其關閉？","options":["(A) diclofenac","(B) ibuprofen","(C) rofecoxib","(D) sulindac"],"answer":1,"image":""},{"id":"md2-109-1-58","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"109年第1次第58題","year":109,"session":1,"number":58,"question":"有關抗癲癇藥物作用的敘述，下列何者錯誤？","options":["(A) ethosuximide主要透過阻斷T-type鈣離子通道來產生抗癲癇作用","(B) tiagabine主要透過阻斷GABA轉運子（transporter）的作用來產生抗癲癇作用","(C) topiramate透過阻斷glutamate轉運子（transporter）的作用來產生抗癲癇作用","(D) valproic acid可透過阻斷鈉離子通道來產生抗癲癇作用"],"answer":2,"image":""},{"id":"md2-109-1-59","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"109年第1次第59題","year":109,"session":1,"number":59,"question":"下列止痛藥，何者的作用機制不是經由活化μ receptor？","options":["(A) nalbuphine","(B) morphine","(C) methadone","(D) fentanyl"],"answer":0,"image":""},{"id":"md2-109-1-60","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"109年第1次第60題","year":109,"session":1,"number":60,"question":"下列何種藥物，不會增加細胞中的cyclic GMP含量？","options":["(A) isoproterenol","(B) sodium nitroprusside","(C) sildenafil","(D) atrial natriuretic peptide"],"answer":0,"image":""},{"id":"md2-109-1-61","subject":"md2","topic":"藥理-總論與自主神經","meta":"109年第1次第61題","year":109,"session":1,"number":61,"question":"酸性藥物中毒時，給與NaHCO的主要原因為何？3","options":["(A) 增加酸性藥物在肝臟代謝的速率","(B) 改變酸性藥物在血液中的穩定度","(C) 增加藥物在血液中的free form，利於腎絲球的過濾","(D) 減少藥物在腎小管的再回收"],"answer":3,"image":""},{"id":"md2-109-1-62","subject":"md2","topic":"藥理-化學治療","meta":"109年第1次第62題","year":109,"session":1,"number":62,"question":"下列何種抗生素須併用cilastatin，以避免被腎臟之dehydropeptidase水解破壞？","options":["(A) imipenem","(B) minocycline","(C) sulfamethoxazole","(D) tobramycin"],"answer":0,"image":""},{"id":"md2-109-1-63","subject":"md2","topic":"藥理-化學治療","meta":"109年第1次第63題","year":109,"session":1,"number":63,"question":"Cefepime可增加下列何種藥物進入細菌（例如：enterococci）的濃度，因此二者併用可增加抗菌作用？","options":["(A) amantadine","(B) amikacin","(C) azlocillin","(D) aztreonam"],"answer":1,"image":""},{"id":"md2-109-1-64","subject":"md2","topic":"藥理-化學治療","meta":"109年第1次第64題","year":109,"session":1,"number":64,"question":"下列抗癌藥物中何者會被xanthine oxidase代謝，若同時服用xanthine oxidase抑制劑allopurinol時，可能會增加其毒性？","options":["(A) 5-fluorouracil","(B) 6-mercaptopurine","(C) methotrexate","(D) 6-thioguanin"],"answer":1,"image":""},{"id":"md2-109-1-65","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第1次第65題","year":109,"session":1,"number":65,"question":"下列何者因可抑制calcineurin phosphatase，可減少器官移植後的排斥反應？","options":["(A) basilixmab","(B) methylprednisolone","(C) cyclosporine","(D) orthoclone OKT3"],"answer":2,"image":""},{"id":"md2-109-1-66","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第1次第66題","year":109,"session":1,"number":66,"question":"下列何者為長期服用glucocorticoid藥物最可能造成的副作用？","options":["(A) 類紅斑性狼瘡","(B) 骨質疏鬆","(C) 肝臟中毒","(D) 腎上腺腫瘤"],"answer":1,"image":""},{"id":"md2-109-1-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第1次第67題","year":109,"session":1,"number":67,"question":"5歲男童因為生長激素受體的基因突變，造成新陳代謝障礙，所以無法長大。下列何者最適合改善此種症狀？","options":["(A) somatropin","(B) octreotide","(C) atosiban","(D) mecasermin"],"answer":3,"image":""},{"id":"md2-109-1-68","subject":"md2","topic":"藥理-總論與自主神經","meta":"109年第1次第68題","year":109,"session":1,"number":68,"question":"下列何者屬於M蕈毒鹼受體（Mmuscarinic receptor）拮抗劑，臨床上用於治療膀胱過動症（overactive 33 bladder）？","options":["(A) pirenzepine","(B) trihexyphenidyl","(C) ipratropium","(D) oxybutynin"],"answer":3,"image":""},{"id":"md2-109-1-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第1次第69題","year":109,"session":1,"number":69,"question":"下列藥物中，何者是屬於serotonin（5-HT）的拮抗劑，用於預防因做化療（chemotherapy）時或手術後所引3起的噁心、嘔吐？","options":["(A) methysergide","(B) ketanserin","(C) cyproheptadine","(D) ondensetron"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第69題一律給分 (原公告答案 D)"},{"id":"md2-109-1-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第1次第70題","year":109,"session":1,"number":70,"question":"小孩因病毒感染而引起發燒反應，首選退燒藥物應是下列何者？","options":["(A) aspirin","(B) acetaminophen","(C) etodolac","(D) celecoxib"],"answer":1,"image":""},{"id":"md2-109-1-71","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"109年第1次第71題","year":109,"session":1,"number":71,"question":"下列何者為GABA受體的致效劑（agonist），主要作用於中樞神經系統，用於治療肌肉疼痛和痙攣？B","options":["(A) dantrolene","(B) baclofen","(C) rocuronium","(D) tizanidine"],"answer":1,"image":""},{"id":"md2-109-1-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"109年第1次第72題","year":109,"session":1,"number":72,"question":"相較於haloperidol，非典型抗精神病藥物olanzapine比較不會造成錐體外症候群（extrapyramidal symptoms），下列何者為其可能的作用原因？","options":["(A) olanzapine活化α-adrenergic receptor","(B) olanzapine抑制突觸前dopamine釋放","(C) olanzapine與D dopamine receptor的親和力較低2","(D) olanzapine對D dopamine receptor的親和力較高1"],"answer":2,"image":""},{"id":"md2-109-1-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"109年第1次第73題","year":109,"session":1,"number":73,"question":"乙醇（酒精）與下列何者併用會造成乙醛（acetaldehyde）蓄積，導致噁心、嘔吐及低血壓等身體不適的反應？","options":["(A) disulfiram","(B) acamprosate","(C) naltrexone","(D) baclofen"],"answer":0,"image":""},{"id":"md2-109-1-74","subject":"md2","topic":"藥理-化學治療","meta":"109年第1次第74題","year":109,"session":1,"number":74,"question":"下列何者可用於治療急性與慢性無機砷中毒（inorganic arsenic poisoning）的螫合劑（chelating agent）？","options":["(A) unithiol","(B) penicillamine","(C) deferoxamine","(D) prussian blue"],"answer":0,"image":""},{"id":"md2-109-1-75","subject":"md2","topic":"藥理-化學治療","meta":"109年第1次第75題","year":109,"session":1,"number":75,"question":"下列具細胞週期專一性之抗癌藥物（cell cycle-specific agents）中，藥物與其所抑制細胞週期之配對，何者正確？","options":["(A) capecitabine－mitosis（M）期","(B) irinotecan－DNA synthesis（S）期","(C) ixabepilone－M期","(D) vincristine－S期"],"answer":[1,2],"image":"","answer_note":"更正:第75題答Ｂ、Ｃ給分。"},{"id":"md2-109-1-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"109年第1次第76題","year":109,"session":1,"number":76,"question":"黃瘤（xanthoma）病灶中，foamy cells細胞質堆積的物質，最可能為：","options":["(A) 磷酸鈣","(B) 膽固醇","(C) Mallory-Denk body","(D) 尿酸"],"answer":1,"image":""},{"id":"md2-109-1-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"109年第1次第77題","year":109,"session":1,"number":77,"question":"下列有關萎縮（atrophy）的敘述，何者錯誤？","options":["(A) 在胚胎時期，某些組織已開始萎縮","(B) 萎縮是組織或器官的細胞變小，但細胞數目並不會減少","(C) 老年人腦部萎縮（senile atrophy）的主要原因是由於血液供應減少","(D) 脂褐質（lipofuscin）可見於某些器官的萎縮"],"answer":1,"image":""},{"id":"md2-109-1-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"109年第1次第78題","year":109,"session":1,"number":78,"question":"下列關於染色體22q11.2缺失症候群（chromosome 22q11.2 deletion syndrome）的敘述，何者正確？","options":["(A) 免疫系統主要會有B淋巴細胞的功能異常","(B) 內分泌系統主要是腦下腺發育不良的問題","(C) 多數的個案其染色體的缺失或突變是隨機的發生在生殖細胞（精或卵）形成的過程","(D) 必須靠傳統染色體核型分析（karyotyping）才能確診"],"answer":2,"image":""},{"id":"md2-109-1-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"109年第1次第79題","year":109,"session":1,"number":79,"question":"下列感染性疾病，何者的典型病理變化會出現小血管炎？①第一、二、三期梅毒②斑疹傷寒（typhus） ③壞疽性臁瘡（ecthyma gangrenosum）","options":["(A) ①②③","(B) 僅①②","(C) 僅②③","(D) 僅①③"],"answer":0,"image":""},{"id":"md2-109-1-80","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"109年第1次第80題","year":109,"session":1,"number":80,"question":"關於鉛（lead）中毒的相關症狀與病變，下列何者較不常見？","options":["(A) 溶血性貧血（hemolytic anemia）","(B) 擴張性心肌病變（dilated cardiomyopathy）","(C) 周邊神經脫髓鞘性病變（peripheral demyelinating neuropathy）","(D) 痛風（gout）"],"answer":1,"image":""},{"id":"md2-109-1-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"109年第1次第81題","year":109,"session":1,"number":81,"question":"相對而言，下列何者較少發生BRAF V600E mutation？","options":["(A) Breast cancer","(B) Colon cancer","(C) Malignant melanoma","(D) Papillary thyroid carcinoma"],"answer":0,"image":""},{"id":"md2-109-1-82","subject":"md2","topic":"病理-心血管血液","meta":"109年第1次第82題","year":109,"session":1,"number":82,"question":"下列身體水腫（edema）與積液的情況中，何者致病機制與其他三者不同？","options":["(A) 血絲蟲感染引起的象皮病（elephantiasis）","(B) 乳糜胸（chylothorax）","(C) 乳癌病患接受乳房切除與腋下淋巴結清除後引起的上肢水腫","(D) 肺梗塞（lung infarct）引起的肋膜積水（pleural effusion）"],"answer":3,"image":""},{"id":"md2-109-1-83","subject":"md2","topic":"病理-心血管血液","meta":"109年第1次第83題","year":109,"session":1,"number":83,"question":"有關肥厚型心肌病變（hypertrophic cardiomyopathy）的特徵，何者錯誤？","options":["(A) β–myosin heavy chain的基因產生突變是最常見的原因","(B) 年輕人猝死的常見原因之一","(C) 左心室游離壁（left ventricular free wall）增厚程度比心室中隔（ventricular septum）增厚程度要來得明顯","(D) 主動脈開口附近心室變厚導致左心室流出通道阻塞（left ventricular outflow tract obstruction）是常見的特徵"],"answer":2,"image":""},{"id":"md2-109-1-84","subject":"md2","topic":"病理-心血管血液","meta":"109年第1次第84題","year":109,"session":1,"number":84,"question":"有關慢性骨髓性白血病（chronic myelogenous leukemia）的敘述，下列何者正確？","options":["(A) 病人多數為兒童及青少年","(B) 骨髓中的細胞量明顯比正常減少（hypocellular marrow）","(C) 病人血液中的骨髓母細胞（myeloblasts）占比超過20%","(D) 腫瘤細胞有第9對及第22對染色體轉位，造成BCR-ABL融合基因"],"answer":3,"image":""},{"id":"md2-109-1-85","subject":"md2","topic":"病理-呼吸消化","meta":"109年第1次第85題","year":109,"session":1,"number":85,"question":"下列何者是最常見的胸腺癌（thymic carcinoma）？","options":["(A) 腺癌（adenocarcinoma）","(B) 淋巴上皮瘤樣癌（lymphoepithelioma-like carcinoma）","(C) 神經內分泌癌（neuroendocrine carcinoma）","(D) 鱗狀細胞癌（squamous cell carcinoma）"],"answer":3,"image":""},{"id":"md2-109-1-86","subject":"md2","topic":"病理-呼吸消化","meta":"109年第1次第86題","year":109,"session":1,"number":86,"question":"關於鼻腔血管纖維瘤（angiofibroma）的敘述，下列何者正確？","options":["(A) 最常發生在中老年男性","(B) 一般相信是從鼻腔後側壁的富含纖維血管的間質長出來的","(C) 是造成鼻腔中隔壞死性潰瘍最常見的原因","(D) 屬良性腫瘤，不會復發或造成病患死亡"],"answer":1,"image":""},{"id":"md2-109-1-87","subject":"md2","topic":"病理-呼吸消化","meta":"109年第1次第87題","year":109,"session":1,"number":87,"question":"下列何種疾病的發生與石棉塵肺症（asbestosis）較沒有相關？","options":["(A) 纖維疤塊（fibrous plaque）","(B) 肺淋巴瘤","(C) 肺上皮癌","(D) 間皮瘤（mesothelioma）"],"answer":1,"image":""},{"id":"md2-109-1-88","subject":"md2","topic":"病理-呼吸消化","meta":"109年第1次第88題","year":109,"session":1,"number":88,"question":"下列何種肺癌相對其它選項較常具有表皮生長因子受體（epidermal growth factor receptor）基因的突變？","options":["(A) 腺癌","(B) 鱗狀上皮細胞癌","(C) 小細胞癌","(D) 大細胞癌"],"answer":0,"image":""},{"id":"md2-109-1-89","subject":"md2","topic":"病理-呼吸消化","meta":"109年第1次第89題","year":109,"session":1,"number":89,"question":"關於原發性硬化性膽管炎（primary sclerosing cholangitis），下列敘述何者錯誤？","options":["(A) 肝內及肝外膽管會有閉塞性纖維化（obliterative fibrosis）和節段性擴張（segmental dilatation）","(B) 與HLA-B8相關","(C) 常伴隨炎症性腸病（inflammatory bowel disease）","(D) 發生於女性較男性多，會出現疲勞，搔癢和黃疸"],"answer":3,"image":""},{"id":"md2-109-1-90","subject":"md2","topic":"病理-呼吸消化","meta":"109年第1次第90題","year":109,"session":1,"number":90,"question":"關於胰臟腫瘤下列敘述何者正確？","options":["(A) 卵巢間質（ovarian stroma）結構常見於黏液性囊腺瘤（mucinous cystadenoma）","(B) 固體假乳頭狀腫瘤（solid-pseudopapillary neoplasm）是良性腫瘤，通常發生在年輕男性","(C) 漿液性囊性腫瘤（serous cystic neoplasm）於男性較常見，約為女性的兩倍","(D) 管內乳頭狀黏液性腫瘤（intraductal papillary mucinous neoplasm）組成包括柱狀、含黏液（mucin）的上皮細胞，與胰管系統沒有流通"],"answer":0,"image":""},{"id":"md2-109-1-91","subject":"md2","topic":"病理-呼吸消化","meta":"109年第1次第91題","year":109,"session":1,"number":91,"question":"下列何種口腔病灶最容易演變為鱗狀細胞癌（squamous cell carcinoma）？","options":["(A) 白斑（leukoplakia）","(B) 紅斑（erythroplakia）","(C) 毛狀白斑（hairy leukoplakia）","(D) 口瘡性潰瘍（aphthous ulcer）"],"answer":1,"image":""},{"id":"md2-109-1-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"109年第1次第92題","year":109,"session":1,"number":92,"question":"沉積在腎上腺微結節性增生（micronodular hyperplasia）最主要的色素為：","options":["(A) 黑色素","(B) 血鐵素","(C) 血色素","(D) 脂褐質"],"answer":3,"image":""},{"id":"md2-109-1-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"109年第1次第93題","year":109,"session":1,"number":93,"question":"在嗜鉻細胞瘤（pheochromocytoma）中的支持細胞（sustentacular cells）最有可能以下列何種免疫組織化學染色標記將其突顯出來？","options":["(A) 嗜鉻粒蛋白（chromogranin）","(B) S100蛋白（S100）","(C) 突觸素（synaptophysin）","(D) 神經元特異性烯醇化酶（neuron specific enolase）"],"answer":1,"image":""},{"id":"md2-109-1-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"109年第1次第94題","year":109,"session":1,"number":94,"question":"關於纖維肌肉發育不良（fibromuscular dysplasia）所導致之腎動脈狹窄，以下何者最不可能發生？","options":["(A) 女性較多","(B) 好發年齡為20至40歲","(C) 僅會侵犯血管中層","(D) 腎臟呈現缺血性萎縮"],"answer":2,"image":""},{"id":"md2-109-1-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"109年第1次第95題","year":109,"session":1,"number":95,"question":"下列有關外陰部乳房外柏哲德氏病（extramammary Paget disease）的敘述，何者較不正確？","options":["(A) 此罕見病灶的臨床表徵與乳房的柏哲德氏病相似","(B) 與乳頭的柏哲德氏病相同，外陰部乳房外柏哲德氏病大多數有伴隨的潛在侵襲癌","(C) 該疾病的腫瘤細胞–柏哲德氏細胞（Paget cell）常常表現cytokeratin 7","(D) 柏哲德氏細胞可能向周邊上皮蔓延，超越外觀上肉眼可以辨識的區域，所以有時無法將病灶完全切除而導致復發"],"answer":1,"image":""},{"id":"md2-109-1-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"109年第1次第96題","year":109,"session":1,"number":96,"question":"下列有關卵巢生殖細胞瘤（germ cell tumor）的敘述，何者較不正確？","options":["(A) 良性囊性畸胎瘤（benign cystic teratoma）為最常見的卵巢生殖細胞瘤","(B) 無性細胞瘤（dysgerminoma）為最常見的惡性卵巢生殖細胞瘤","(C) 大部分的無性細胞瘤（dysgerminoma）發生在10歲以下","(D) 卵黃囊腫瘤（yolk sac tumor）為第二常見的惡性卵巢生殖細胞瘤，其腫瘤細胞會分泌alpha-fetoprotein"],"answer":2,"image":""},{"id":"md2-109-1-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"109年第1次第97題","year":109,"session":1,"number":97,"question":"下列有關葡萄胎（hydatidiform mole）的敘述，何者較不正確？","options":["(A) 完全性葡萄胎（complete mole）意指合子的遺傳物質皆為父源","(B) 不完全性葡萄胎（partial mole）患者比完全性葡萄胎患者有較高危險性發生絨毛膜癌（choriocarcinoma）","(C) 完全性葡萄胎（complete mole）患者比不完全性葡萄胎患者有較高危險性發生侵入性葡萄胎（invasive mole）","(D) 不完全性葡萄胎（partial mole）意指合子的遺傳物質為母源加父源"],"answer":1,"image":""},{"id":"md2-109-1-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"109年第1次第98題","year":109,"session":1,"number":98,"question":"退化性關節炎（osteoarthritis）主要的致病機轉是：","options":["(A) 關節軟骨下之成骨細胞（subchondral osteocyte）因年紀累積之過度使用而損傷，引起該關節發炎反應","(B) 關節滑液膜細胞（synoviocyte）退化，導致淋巴球浸潤該關節，引起發炎反應","(C) 關節軟骨退化（articular cartilage degeneration）和軟骨細胞異常的修復能力（disordered repair of chondrocytes）","(D) 關節滑液膜細胞（synoviocyte）損傷退化，導致synoviocyte因修復而過度增生，阻礙關節附近組織之血管通透性及養分供給"],"answer":2,"image":""},{"id":"md2-109-1-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"109年第1次第99題","year":109,"session":1,"number":99,"question":"下列有關大腦類澱粉血管病變（cerebral amyloid angiopathy, CAA）的描述何者正確？①CAA是造成lobar hemorrhage的危險因子之一②導因於中小型腦膜或皮質腦動脈血管壁有包含tau蛋白之類澱粉沉積③CAA致病率與ApoE基因（與阿茲海默症有因果關聯的基因）多形性變異（polymorphism）有關④CAA血管病變常會引起血管纖維化（arteriolar sclerosis/fibrosis）","options":["(A) ①②","(B) ①③","(C) ②③","(D) ②④"],"answer":1,"image":""},{"id":"md2-109-1-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"109年第1次第100題","year":109,"session":1,"number":100,"question":"髓芽細胞瘤（medulloblastoma, WHO grade IV）是一好發於兒童小腦，分化差之中樞神經腫瘤。其腫瘤分子分類（molecular subtype）中，何者預後最佳？","options":["(A) the WNT type","(B) the SHH type","(C) group 3 medulloblastoma","(D) group 4 medulloblastoma"],"answer":0,"image":""},{"id":"md2-109-2-1","subject":"md2","topic":"病毒學","meta":"109年第2次第1題","year":109,"session":2,"number":1,"question":"在12月中旬，一位5歲男童出現發燒、頭痛、喉嚨痛、流鼻水、打噴嚏、無痰性乾咳、肌肉痛不舒服等症狀，病情持續4天沒有好轉，卻進一步發展為細菌性肺炎（pneumonia）及肌炎（myositis），與該男童同住之家人一星期後亦出現類似症狀，此男童最可能受下列何種病原感染？","options":["(A) 麻疹病毒（Measles virus）","(B) 呼吸道細胞融合病毒（Respiratory syncytial virus）","(C) 流行性感冒病毒（Influenza virus）","(D) 腸病毒71型（Enterovirus 71）"],"answer":2,"image":""},{"id":"md2-109-2-2","subject":"md2","topic":"細菌學","meta":"109年第2次第2題","year":109,"session":2,"number":2,"question":"診斷結核分枝桿菌（Mycobacterium tuberculosis）感染症時，DNA技術（DNA technologies）與傳統培養法比較，其優點不包括下列何者？","options":["(A) 增加鑑定菌種之專一性","(B) 敏感度較高","(C) 可快速診斷","(D) 可以精確且完整判讀對抗生素的抗藥性"],"answer":3,"image":""},{"id":"md2-109-2-3","subject":"md2","topic":"藥理-化學治療","meta":"109年第2次第3題","year":109,"session":2,"number":3,"question":"有關B級β-內酰胺酶（class B β-lactamase）之敘述，下列何者錯誤？","options":["(A) 同屬於蛋白酶（protease）家族","(B) 作用時需金屬離子","(C) 無法分解carbapenems","(D) 基因多位於質體上"],"answer":2,"image":""},{"id":"md2-109-2-4","subject":"md2","topic":"藥理-化學治療","meta":"109年第2次第4題","year":109,"session":2,"number":4,"question":"針對治療非多重抗藥性結核分枝桿菌（Mycobacterium tuberculosis）所引起的結核病，下列那些藥物是屬於世界衛生組織（WHO）建議的第一線藥物？ ①異菸鹼醯（isoniazid） ② 硫胂密胺（melarsporol） ③ 兩性黴素B（amphotericin B） ④ 乙胺丁醇（ethambutol）","options":["(A) ①③","(B) ②③","(C) ①④","(D) ②④"],"answer":2,"image":""},{"id":"md2-109-2-5","subject":"md2","topic":"細菌學","meta":"109年第2次第5題","year":109,"session":2,"number":5,"question":"有關傷寒沙門氏桿菌（Salmonella Typhi）的敘述，下列何者錯誤？","options":["(A) 主要的傳染途徑為糞口傳染（fecal-oral spread）","(B) 大多由帶菌的家禽或家畜直接傳染給人","(C) 細菌會感染腸道，也會感染肝臟與脾臟","(D) 少數病人為無症狀帶原者，細菌通常潛伏在膽囊（gall bladder）"],"answer":1,"image":""},{"id":"md2-109-2-6","subject":"md2","topic":"細菌學","meta":"109年第2次第6題","year":109,"session":2,"number":6,"question":"下列何者無法將金黃色葡萄球菌（Staphylococcus aureus）與表皮葡萄球菌（Staphylococcus epidermidis）區分出來？","options":["(A) 產生凝固酶（coagulase）的能力","(B) 醱酵甘露醇（mannitol）的能力","(C) 溶血（hemolysis）型態","(D) 觸酶（catalase）試驗"],"answer":3,"image":""},{"id":"md2-109-2-7","subject":"md2","topic":"細菌學","meta":"109年第2次第7題","year":109,"session":2,"number":7,"question":"有關細菌基因表現的敘述，下列何者錯誤？","options":["(A) 一條mRNA可以轉譯出多種蛋白質","(B) 基因進行轉錄時，可同時進行轉譯工作","(C) lac操縱子基因表現主要受到定額感應系統（quorum-sensing system）的直接調控","(D) 在色胺酸（tryptophan）操縱子（trp operon）的調控機制中，色胺酸是共同抑制子（co-repressor）"],"answer":2,"image":""},{"id":"md2-109-2-8","subject":"md2","topic":"細菌學","meta":"109年第2次第8題","year":109,"session":2,"number":8,"question":"對於厭氧性革蘭氏陽性球菌（anaerobic Gram-positive cocci）的敘述，下列何者錯誤？","options":["(A) 都不會產生芽胞（spores）","(B) 可使用氨基醣苷類藥物（aminoglycosides）治療其感染症","(C) 通常棲居於口腔、腸胃道、泌尿道以及皮膚","(D) 多屬於伺機性（opportunistic）感染菌"],"answer":[0,1],"image":"","answer_note":"更正:第8題答Ａ、Ｂ給分"},{"id":"md2-109-2-9","subject":"md2","topic":"細菌學","meta":"109年第2次第9題","year":109,"session":2,"number":9,"question":"下列何者不是炭疽桿菌（Bacillus anthracis）常引起的疾病？","options":["(A) 腸胃型炭疽（Gastrointestinal anthrax）","(B) 肌肉壞死型炭疽（Myonecrotic anthrax）","(C) 皮膚型炭疽（Cutaneous anthrax）","(D) 吸入性炭疽（Inhalation anthrax）"],"answer":1,"image":""},{"id":"md2-109-2-10","subject":"md2","topic":"細菌學","meta":"109年第2次第10題","year":109,"session":2,"number":10,"question":"下列何者非化膿性鏈球菌（Streptococcus pyogenes）常見的致病因子（virulence factor）？","options":["(A) 耐熱（Heat-stable）毒素STa和STb","(B) 鏈球菌溶血素（Streptolysin O）","(C) M蛋白質（M protein）","(D) 莢膜（Capsule）"],"answer":0,"image":""},{"id":"md2-109-2-11","subject":"md2","topic":"病毒學","meta":"109年第2次第11題","year":109,"session":2,"number":11,"question":"在愛滋病（AIDS）患者常見的卡波西肉瘤（Kaposi sarcoma），是由下列那種致病原伺機性感染所造成？","options":["(A) 白色念珠菌（Candida albicans）","(B) 人類黴漿菌（Mycoplasma hominis）","(C) 第八型人類疱疹病毒（Human herpesvirus 8）","(D) 新型隱球菌（Cryptococcus neoformans）"],"answer":2,"image":""},{"id":"md2-109-2-12","subject":"md2","topic":"病毒學","meta":"109年第2次第12題","year":109,"session":2,"number":12,"question":"關於小DNA病毒（Parvovirus）的敘述，下列何者錯誤？","options":["(A) 其基因體（genome）是線型雙股DNA","(B) 小朋友如果感染小DNA病毒（Parvovirus）B19，會在兩側臉頰產生整片發紅的現象，俗稱巴掌臉（slapped- cheek）","(C) 在免疫缺乏的病人身上，B19會造成慢性貧血","(D) 病毒本身不帶有DNA聚合酶（polymerase），因此只能在生長中的細胞裏複製"],"answer":0,"image":""},{"id":"md2-109-2-13","subject":"md2","topic":"病毒學","meta":"109年第2次第13題","year":109,"session":2,"number":13,"question":"有關流感病毒減毒疫苗（live attenuated influenza vaccine）的敘述，下列何者錯誤？","options":["(A) 適當生長溫度是攝氏25度","(B) 大部分在鼻咽部感染","(C) 容易刺激IgA抗體的產生","(D) 適用於60歲以上之成人"],"answer":3,"image":""},{"id":"md2-109-2-14","subject":"md2","topic":"病毒學","meta":"109年第2次第14題","year":109,"session":2,"number":14,"question":"腸病毒71型（Enterovirus EV71）造成死亡主要的原因是：","options":["(A) 侵犯腸胃道，造成腸道細胞脫落，及嚴重的電解質不平衡","(B) 感染後可以持續潛伏在腸道M細胞中，多次不斷再活化，因而造成持續性症狀","(C) 侵犯不同部位的組織，尤其是神經系統","(D) 病人體內產生的抗體可以和病毒結合，增加病毒的感染力"],"answer":2,"image":""},{"id":"md2-109-2-15","subject":"md2","topic":"病毒學","meta":"109年第2次第15題","year":109,"session":2,"number":15,"question":"有關JC病毒（JC virus, JCV）的敘述，下列何者錯誤？","options":["(A) 會感染神經膠狀細胞（glial cell）","(B) 其T（large T）抗原與DNA複製有關","(C) 其t（small t）抗原與抑制p53及p105RB之功能有關","(D) 在免疫不全病人能造成進行性多灶性白質腦病（progressive multifocal leukoencephalopathy, PML）"],"answer":2,"image":""},{"id":"md2-109-2-16","subject":"md2","topic":"真菌學","meta":"109年第2次第16題","year":109,"session":2,"number":16,"question":"下列何者被人體吸入後，在肺部產生含許多內孢子（endospore）的球形體（spherule），並造成全身性黴菌感染症（systemic mycoses）？","options":["(A) 巴西副球黴菌（Paracoccidioides brasiliensis）","(B) 莢膜組織胞漿菌（Histoplasma capsulatum）","(C) 皮炎芽生菌（Blastomyces dermatitidis）","(D) 粗球孢子菌（Coccidioides immitis）"],"answer":3,"image":""},{"id":"md2-109-2-17","subject":"md2","topic":"藥理-化學治療","meta":"109年第2次第17題","year":109,"session":2,"number":17,"question":"抗真菌（anti-fungal）藥物中，下列何者之作用機轉非抑制麥角固醇（ergosterol）之合成？","options":["(A) 多烯類（Polyenes）","(B) 烯丙胺類（Allylamines）","(C) 咪唑類（Imidazoles）","(D) 三唑類（Triazoles）"],"answer":0,"image":""},{"id":"md2-109-2-18","subject":"md2","topic":"免疫學","meta":"109年第2次第18題","year":109,"session":2,"number":18,"question":"下列有關干擾素-alpha（interferon-α）之特性，何者正確？","options":["(A) 屬於趨化激素（chemokine）","(B) 使正常細胞不易被病毒感染","(C) 屬於適應性免疫力（adaptive immunity）","(D) 主要由活化T細胞產生"],"answer":1,"image":""},{"id":"md2-109-2-19","subject":"md2","topic":"免疫學","meta":"109年第2次第19題","year":109,"session":2,"number":19,"question":"先天免疫細胞主要利用下列何者之刺激活化以遷移至感染區，進行免疫功能？","options":["(A) T cell receptors","(B) B cell receptors","(C) chemokine receptors","(D) Toll-like receptors"],"answer":2,"image":""},{"id":"md2-109-2-20","subject":"md2","topic":"免疫學","meta":"109年第2次第20題","year":109,"session":2,"number":20,"question":"下列關於MHC class II的敘述何者錯誤？","options":["(A) CD4 T細胞主要辨識由MHC class II所呈獻之抗原","(B) MHC class II可呈獻較長的胜肽，約含有13-17胺基酸","(C) MHC class II分子主要表現於嗜中性白血球（neutrophil）","(D) MHC class II分子可表現於胸腺上皮細胞（epithelial cells of thymus）"],"answer":2,"image":""},{"id":"md2-109-2-21","subject":"md2","topic":"免疫學","meta":"109年第2次第21題","year":109,"session":2,"number":21,"question":"抗體多變區（variable domain）基因V(D)J片段重組（recombination）是產生多樣性抗體的主要機制，下列那一種酵素沒有參與這一部分抗體基因重組的過程？","options":["(A) activation-induced cytidine deaminase（AID）","(B) DNA-dependent protein kinase（DNA-PK）","(C) recombination-activating gene（RAG）","(D) DNA ligase IV"],"answer":0,"image":""},{"id":"md2-109-2-22","subject":"md2","topic":"免疫學","meta":"109年第2次第22題","year":109,"session":2,"number":22,"question":"下列分子何者與毒殺性T細胞（cytotoxic T lymphocyte, CTL）的毒殺作用沒有直接關聯？","options":["(A) FasL","(B) Perforin","(C) Granzyme","(D) IFN-γ"],"answer":3,"image":""},{"id":"md2-109-2-23","subject":"md2","topic":"免疫學","meta":"109年第2次第23題","year":109,"session":2,"number":23,"question":"親合力成熟作用（affinity maturation）是抗體對抗原的親合力增強的主要原因，有關親合力成熟作用的敘述，何者錯誤？","options":["(A) 活化的B細胞在生發中心（germinal center）進行體細胞超突變（somatic hypermutation），在Ig基因的變異區（variable region）和固定區（constant region）造成胺基酸序列的改變","(B) 體細胞超突變（somatic hypermutation）需要AID（activation-induced cytidine deaminase）一種脫胺酵素的參與，主要是作用在胞嘧啶（cytosine, C）上使之轉變為尿嘧啶（uridine, U），再經過DNA修復作用引起突變","(C) 活化的B細胞的抗原接受器（BCR）會因為超突變的結果造成對抗原親合力的改變，可能會減弱BCR對抗原的結合力，但也可能會增加親合力","(D) 經過濾泡樹突細胞（follicular dendritic cell）上抗原的篩選後，只有親合力高的B細胞存活並大量增生，其餘親合力弱的B細胞則由於缺乏抗原刺激而凋亡"],"answer":0,"image":""},{"id":"md2-109-2-24","subject":"md2","topic":"病毒學","meta":"109年第2次第24題","year":109,"session":2,"number":24,"question":"下列對於小兒麻痺疫苗（polio vaccines）的描述何者錯誤？","options":["(A) 小兒麻痺疫苗（polio vaccines）可分為去活性（inactivated）與減毒疫苗（live-attenuated）二種型式","(B) 小兒麻痺病毒可感染人類與牛隻","(C) 在臺灣小兒麻痺所推薦的疫苗以去活性（inactivated）疫苗為主","(D) 口服小兒麻痺疫苗是由三種減毒（live-attenuated）的病毒株所組成"],"answer":1,"image":""},{"id":"md2-109-2-25","subject":"md2","topic":"免疫學","meta":"109年第2次第25題","year":109,"session":2,"number":25,"question":"下列關於衛生假說（hygiene hypothesis）與過敏疾病之關係的敘述何者錯誤？","options":["(A) 先進國家衛生環境好，過敏疾病患者比率較高","(B) 長期使用驅蟲藥治療寄生蟲感染較易得到過敏反應","(C) 小孩早期有較多感染可預防過敏之產生","(D) 小孩長期使用抗生素可減少氣喘發生"],"answer":3,"image":""},{"id":"md2-109-2-26","subject":"md2","topic":"免疫學","meta":"109年第2次第26題","year":109,"session":2,"number":26,"question":"身體達成免疫反應的自體耐受性（self-tolerance）的機轉之一是中樞耐受性（central tolerance），它的特性為何？","options":["(A) 在淋巴結消除自體反應性淋巴細胞","(B) 由中樞淋巴系統如胸腺，呈獻許多種周邊組織抗原，由此消除自體反應性淋巴細胞","(C) 由中樞淋巴系統控制細胞激素生成（cytokine deviation），使淋巴細胞趨向於生成TH2細胞激素，而避免了破壞器官的自體免疫疾病","(D) 因組織的隔絕性使淋巴細胞不能碰到某些器官的抗原，如胰臟抗原，因此達到自體耐受性"],"answer":1,"image":""},{"id":"md2-109-2-27","subject":"md2","topic":"免疫學","meta":"109年第2次第27題","year":109,"session":2,"number":27,"question":"T淋巴球能夠辨識腫瘤細胞並殺死腫瘤細胞，下列何者與腫瘤中T淋巴球辨識腫瘤抗原的情況最有關？","options":["(A) 腫瘤細胞常有許多基因變異，因而表現出其他組織器官的分子，例如睪丸的蛋白質，此時便無法產生辨識這些蛋白質抗原的T淋巴球","(B) 黑色素瘤常見的腫瘤抗原之一是由酪氨酸酶（tyrosinase）衍生的胜肽，因為非常高量的胜肽：MHC表現而產生出了辨識腫瘤的T淋巴球","(C) 腫瘤內部的T淋巴球偶有表現PD-L1或PD-L2分子，因而能夠辨識含有突變序列的腫瘤抗原","(D) 多種腺癌表現出高量的HER-2/neu，是一種受體酪氨酸激酶（receptor tyrosine kinase），可直接抑制T淋巴球對腫瘤抗原的辨識因而無法引發腫瘤毒殺作用"],"answer":1,"image":""},{"id":"md2-109-2-28","subject":"md2","topic":"免疫學","meta":"109年第2次第28題","year":109,"session":2,"number":28,"question":"下列何者與器官移植後的排斥作用不相關？","options":["(A) MHC class I分子","(B) MHC class II分子","(C) 次要組織吻合抗原（minor histocompatibility antigen）","(D) 一種多型變異（polymorphic）較少的MHC class I分子：HLA-G"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第28題一律給分 (原公告答案 D)"},{"id":"md2-109-2-29","subject":"md2","topic":"寄生蟲學","meta":"109年第2次第29題","year":109,"session":2,"number":29,"question":"下列何者與人體感染菲律賓毛線蟲（Capillaria philippinensis）無關？","options":["(A) 因食入被蟲卵污染的魚肉而感染","(B) 在腸道可能發生自體感染（autoinfection）","(C) 可能引起低蛋白血症","(D) 腹瀉病患必須補充電解質"],"answer":0,"image":""},{"id":"md2-109-2-30","subject":"md2","topic":"寄生蟲學","meta":"109年第2次第30題","year":109,"session":2,"number":30,"question":"片山熱（Katayama fever）是由下列何種寄生蟲引致？","options":["(A) 中華肝吸蟲（Clonorchis sinensis）","(B) 日本血吸蟲（Schistosoma japonicum）","(C) 伊羅棘口吸蟲（Echinostoma ilocanum）","(D) 槍狀肝吸蟲（Dicrocoelium dendriticum）"],"answer":1,"image":""},{"id":"md2-109-2-31","subject":"md2","topic":"寄生蟲學","meta":"109年第2次第31題","year":109,"session":2,"number":31,"question":"有關絛蟲「成蟲」之敘述，下列何者正確？","options":["(A) 體型相當大，容易對宿主腸道造成刺激及全身症狀","(B) 經由皮層（tegument）自中間宿主腸道攝取營養","(C) 雌雄同體，行無性生殖","(D) 頭節上具有用來定位及附著的器官"],"answer":3,"image":""},{"id":"md2-109-2-32","subject":"md2","topic":"寄生蟲學","meta":"109年第2次第32題","year":109,"session":2,"number":32,"question":"有關瘧疾（malaria）致病機轉的敘述，下列何者錯誤？","options":["(A) 局部組織血液流量減少係因惡性瘧原蟲（Plasmodium falciparum）的細胞附著現象（cytoadherence）所引起","(B) 被瘧原蟲寄生的紅血球表面會產生結合體（ligand）蛋白，並與內皮細胞上的特定受體形成複合物（ligand- receptor complex）造成細胞附著能力增加","(C) 患者自體的血小板凝集蛋白（thrombospondin）受到抑制，造成受到瘧原蟲寄生的紅血球集結成團，進而影響血流","(D) 造成患者貧血的部分原因，為體內未受瘧原蟲感染的紅血球被活化並遭受破壞"],"answer":2,"image":""},{"id":"md2-109-2-33","subject":"md2","topic":"寄生蟲學","meta":"109年第2次第33題","year":109,"session":2,"number":33,"question":"下列寄生蟲中，何者之成熟囊體（mature cyst）的平均體型（average size）最大？","options":["(A) 嗜碘阿米巴（Iodamoeba bütschlii）","(B) 哈氏阿米巴（Entamoeba hartmanni）","(C) 大腸阿米巴（Entamoeba coli）","(D) 痢疾阿米巴（Entamoeba histolytica）"],"answer":2,"image":""},{"id":"md2-109-2-34","subject":"md2","topic":"寄生蟲學","meta":"109年第2次第34題","year":109,"session":2,"number":34,"question":"病媒蜱（vector tick）可以藉由叮咬而傳播下列何種人類感染症？","options":["(A) 黑熱病（kala-azar）","(B) 戰壕熱（trench fever）","(C) 黃熱病（yellow fever）","(D) 回歸熱（relapsing fever）"],"answer":3,"image":""},{"id":"md2-109-2-35","subject":"md2","topic":"寄生蟲學","meta":"109年第2次第35題","year":109,"session":2,"number":35,"question":"恙蟎（chigger mite）可以傳播下列何種人類感染症？","options":["(A) 落磯山斑疹熱（Rocky Mountain spotted fever）","(B) 流行性斑疹傷寒（epidemic typhus）","(C) 地方性斑疹傷寒（endemic typhus）","(D) 叢林斑疹傷寒（scrub typhus）"],"answer":3,"image":""},{"id":"md2-109-2-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第2次第36題","year":109,"session":2,"number":36,"question":"處理2x2 列聯表數據之統計分析，若其中一個細格的期望值小於5，此時應使用下列何種方法執行統計學檢定較為恰當？","options":["(A) 卡方檢定（Chi-square test）","(B) 費雪恰當檢定（Fisher’s exact test）","(C) Yates校正之卡方檢定法（Yates correction Chi-square test）","(D) McNemar檢定法（McNemar Chi-square test）"],"answer":1,"image":""},{"id":"md2-109-2-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第2次第37題","year":109,"session":2,"number":37,"question":"假設已知男性肺癌患者五年存活率為15%，若欲檢定女性肺癌患者五年存活率與男性肺癌患者是否相同（顯著水準設定為0.05），今採用簡單隨機抽樣52位女性肺癌患者，追蹤5年後只有6位存活，經計算其95% 信賴區間為（0.028, 0.202），下列敘述何者正確？","options":["(A) 男女性的五年存活率差異達統計顯著","(B) 男女性的五年存活率差異未達統計顯著","(C) 女性族群的五年存活率有5%機率小於0.028","(D) 應該採用變異數分析（ANOVA）"],"answer":1,"image":""},{"id":"md2-109-2-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第2次第38題","year":109,"session":2,"number":38,"question":"一項研究持續觀察1400名無肺癌者5年後，其中700名抽菸者70位罹患肺癌，另700名不抽菸者中26位罹患肺癌，這屬於下列那一種研究法？","options":["(A) 世代研究","(B) 病例對照研究","(C) 生態研究","(D) 橫斷式研究"],"answer":0,"image":""},{"id":"md2-109-2-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第2次第39題","year":109,"session":2,"number":39,"question":"假設有一個疾病為顯性遺傳病，得病者父母親中，其中有一位有病，另一位則無。這種疾病每位子女遺傳的機率1/2，一個有2個小孩的家庭，兩個小孩皆得病的機率為何？","options":["(A) 0","(B) 1/2","(C) 1/4","(D) 1/8"],"answer":2,"image":""},{"id":"md2-109-2-40","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第2次第40題","year":109,"session":2,"number":40,"question":"某項針對臺灣各縣市進行的調查研究發現：民眾年平均香菸攝取量越高的縣市，該縣市居民的冠心症發生率就越高，欲解釋此一現象時應特別注意是否有下列那項情形？","options":["(A) 生態謬誤","(B) 家族聚集","(C) 共同感染","(D) 世代效應"],"answer":0,"image":""},{"id":"md2-109-2-41","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第2次第41題","year":109,"session":2,"number":41,"question":"以水銀血壓計測量病人血壓，某醫師操作袖帶解壓（cuff deflation）的速度，有時快過2毫米汞柱/秒，有時卻慢於2毫米汞柱/秒。下列敘述何者正確？","options":["(A) 可能發生選擇偏差，無法得到真正血壓值","(B) 可能發生回憶偏差，無法得到真正血壓值","(C) 可能發生隨機誤差，得到真正血壓值的機會大","(D) 可能發生隨機誤差，無法保證得到真正的血壓值"],"answer":3,"image":""},{"id":"md2-109-2-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"109年第2次第42題","year":109,"session":2,"number":42,"question":"經高溫油炸的澱粉食品，最可能產生下列那種有害物質？","options":["(A) 苯甲酸鹽","(B) 多氯聯苯","(C) 黃麴毒素","(D) 丙烯醯胺"],"answer":3,"image":""},{"id":"md2-109-2-43","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第2次第43題","year":109,"session":2,"number":43,"question":"傳染病監測金字塔，包括：①醫檢結果確定為陽性之個案數②症狀個案數③臨床醫師診療個案數④感染人數。依人數多寡之排序（人數由多到少）為下列何者？","options":["(A) ①②③④","(B) ④②③①","(C) ④②①③","(D) ①④②③"],"answer":1,"image":""},{"id":"md2-109-2-44","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"109年第2次第44題","year":109,"session":2,"number":44,"question":"我國環境影響評估法的主要精神，並不包括下列何者？","options":["(A) 事先預防","(B) 開發承諾","(C) 開發否決","(D) 媒體參與"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第44題一律給分 (原公告答案 D)"},{"id":"md2-109-2-45","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"109年第2次第45題","year":109,"session":2,"number":45,"question":"造成惡性間皮細胞瘤（mesothelioma）最常見之職業暴露因子為何？","options":["(A) 石棉","(B) 鎘","(C) 矽塵","(D) 甲苯"],"answer":0,"image":""},{"id":"md2-109-2-46","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"109年第2次第46題","year":109,"session":2,"number":46,"question":"電弧焊接最易造成下列何類物理性危害？","options":["(A) 微波","(B) 紅外線","(C) 紫外線","(D) 射頻輻射"],"answer":2,"image":""},{"id":"md2-109-2-47","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第2次第47題","year":109,"session":2,"number":47,"question":"小克是典型的三高，即血糖高、血壓高、血脂高，但他完全沒有想過要運動改變生活型態，根據跨理論模式，下列那一種改變過程較能幫助小克產生運動等健康行為？","options":["(A) 意識覺醒","(B) 自我解放","(C) 反制約","(D) 刺激控制"],"answer":0,"image":""},{"id":"md2-109-2-48","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"109年第2次第48題","year":109,"session":2,"number":48,"question":"下列何者是屬於健康行為科學理論中與人際互動層面（interpersonal level）有關的理論？","options":["(A) 跨理論模式","(B) 社會認知理論","(C) 生態模式","(D) 組織發展理論"],"answer":1,"image":""},{"id":"md2-109-2-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"109年第2次第49題","year":109,"session":2,"number":49,"question":"基於醫療需求中有強烈的資訊不對等問題，病人對醫療知識所知遠不如醫療供給者，因此其所需購買的醫療服務項目，常由醫師主導與決定。在某些情況下，醫師可能誘導病人多消費，稱為下列何項需求？","options":["(A) 供給者誘發需求","(B) 消費者誘發需求","(C) 引伸需求","(D) 資訊需求"],"answer":0,"image":""},{"id":"md2-109-2-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"109年第2次第50題","year":109,"session":2,"number":50,"question":"臺灣全民健康保險具有下列那一項特色？","options":["(A) 全民自由納保","(B) 公共單一支付制度","(C) 醫療保健支出佔生產毛額比率比美國低，但高於英國","(D) 消弭不同社經族群之健康差距"],"answer":1,"image":""},{"id":"md2-109-2-51","subject":"md2","topic":"藥理-總論與自主神經","meta":"109年第2次第51題","year":109,"session":2,"number":51,"question":"有關藥物在身體內進行生物轉換（biotransformation），下列何者為最主要目的？","options":["(A) 促進藥物通過血腦障壁","(B) 使親脂性藥物轉具水溶性","(C) 延長水溶性藥物的半衰期","(D) 減少藥物自腎臟排泄"],"answer":1,"image":""},{"id":"md2-109-2-52","subject":"md2","topic":"藥理-化學治療","meta":"109年第2次第52題","year":109,"session":2,"number":52,"question":"關於B型肝炎病毒（HBV）用藥，下列敘述何者正確？","options":["(A) interferon alfa-2a可適用於肝功能代償不足（hepatic decompensation）的肝炎病患","(B) 口服adefovir dipivoxil可有效產生HBeAg血清轉換（seroconversion）","(C) 在對lamivudine產生抗藥性的HBV病患可使用entecavir","(D) 長期使用tenofovir目前尚無抗藥性產生，但對adefovir產生抗藥性病患其效用較差"],"answer":3,"image":""},{"id":"md2-109-2-53","subject":"md2","topic":"藥理-化學治療","meta":"109年第2次第53題","year":109,"session":2,"number":53,"question":"有關化療藥物作用，下列敘述何者正確？","options":["(A) carboplatin作用在DNA上，為細胞週期專一性（cell cycle-specific）抗癌藥物","(B) 5-fluorouracil的作用為阻斷細胞週期的M期","(C) cyclophosphamide須經由肝臟細胞色素P450代謝才能毒殺癌細胞","(D) procarbazine為COP合併用藥之一，能有效抑制monoamine oxidase"],"answer":2,"image":""},{"id":"md2-109-2-54","subject":"md2","topic":"藥理-化學治療","meta":"109年第2次第54題","year":109,"session":2,"number":54,"question":"抗癌藥物bevacizumab為單株抗體藥物，因可與下列何者結合，進而抑制腫瘤之發展？","options":["(A) 上皮生長因子（epidermal growth factor）","(B) 纖維母細胞生長因子（fibroblast growth factor）","(C) 血管內皮生長因子（vascular endothelial growth factor）","(D) 血小板衍生生長因子（platelet-derived growth factor）"],"answer":2,"image":""},{"id":"md2-109-2-55","subject":"md2","topic":"藥理-化學治療","meta":"109年第2次第55題","year":109,"session":2,"number":55,"question":"陳小姐得到human epidermal growth factor receptor 2（HER-2）-positive乳癌，下列何者可抑制HER-2受體的活化，在適當條件下，最適合用於治療此種乳癌？","options":["(A) gefitinib","(B) erlotinib","(C) lapatinib","(D) sorafenib"],"answer":2,"image":""},{"id":"md2-109-2-56","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第2次第56題","year":109,"session":2,"number":56,"question":"關於免疫抑制劑sirolimus的相關毒性及副作用，下列敘述何者錯誤？","options":["(A) 具明顯骨髓抑制作用","(B) 可能引起高血脂症","(C) 不可與cyclosporine併用","(D) 併用tacrolimus可能引發hemolytic-uremic syndrome"],"answer":2,"image":""},{"id":"md2-109-2-57","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第2次第57題","year":109,"session":2,"number":57,"question":"有關干擾素（interferon, IFN）的特性與臨床使用，下列敘述何者錯誤？","options":["(A) IFN-α可治療多種腫瘤及病毒性肝炎","(B) IFN-β可治療多發性硬化症（multiple sclerosis, MS）","(C) IFN-β可治療慢性肉芽腫病變（chronic granulomatous disease）","(D) IFN-α與IFN-β皆可抑制細胞增殖"],"answer":2,"image":""},{"id":"md2-109-2-58","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"109年第2次第58題","year":109,"session":2,"number":58,"question":"下列藥物何者為血小板表面醣蛋白GP IIb/IIIa及vitronectin受體拮抗劑，可運用於急性冠狀動脈症候群（acute coronary syndromes）？","options":["(A) abciximab","(B) dipyridamole","(C) cilostazol","(D) prasugrel"],"answer":0,"image":""},{"id":"md2-109-2-59","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第2次第59題","year":109,"session":2,"number":59,"question":"下列何種藥物的主要作用標的為雌激素受體（estrogen receptor），用於誘發卵巢排卵？","options":["(A) progesterone","(B) ketoconazole","(C) tamoxifen","(D) clomiphene"],"answer":3,"image":""},{"id":"md2-109-2-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第2次第60題","year":109,"session":2,"number":60,"question":"下列何種藥物比較不適合在高血鈣時使用？","options":["(A) pamidronate","(B) vitamin D3","(C) calcitonin","(D) prednisolone"],"answer":1,"image":""},{"id":"md2-109-2-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第2次第61題","year":109,"session":2,"number":61,"question":"下列何種口服降血糖藥的主要效果，是刺激胰臟分泌更多的胰島素？","options":["(A) acarbose","(B) metformin","(C) glimepiride","(D) rosiglitazone"],"answer":2,"image":""},{"id":"md2-109-2-62","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"109年第2次第62題","year":109,"session":2,"number":62,"question":"下列何者的作用機轉是經由活化brain natriuretic peptide（BNP）receptors，用於治療心臟衰竭？","options":["(A) dobutamine","(B) milrinone","(C) nesiritide","(D) sacubitril"],"answer":2,"image":""},{"id":"md2-109-2-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"109年第2次第63題","year":109,"session":2,"number":63,"question":"下列何者不是經由強心作用，來治療心臟衰竭？","options":["(A) digoxin","(B) dobutamine","(C) milrinone","(D) sacubitril"],"answer":3,"image":""},{"id":"md2-109-2-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"109年第2次第64題","year":109,"session":2,"number":64,"question":"下列關於molsidomine的敘述，何者錯誤？","options":["(A) 是一種prodrug","(B) 可以提供nitric oxide","(C) 可使cAMP濃度上升","(D) 可用於治療心絞痛"],"answer":2,"image":""},{"id":"md2-109-2-65","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"109年第2次第65題","year":109,"session":2,"number":65,"question":"下列藥物中，何者最適合用於治療注意力不足過動症（attention deficit hyperactivity disorder）？","options":["(A) duloxetine","(B) milnacipran","(C) sibutramine","(D) methylphenidate"],"answer":3,"image":""},{"id":"md2-109-2-66","subject":"md2","topic":"藥理-總論與自主神經","meta":"109年第2次第66題","year":109,"session":2,"number":66,"question":"下列何者不是擬交感神經作用劑（sympathomimetic drugs）之臨床用途？","options":["(A) 睫狀肌麻痺（cycloplegia）","(B) 過敏性休克（anaphylactic shock）","(C) 氣喘（asthma）","(D) 抑制早產（suppress premature labor）"],"answer":0,"image":""},{"id":"md2-109-2-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第2次第67題","year":109,"session":2,"number":67,"question":"下列何者是cromolyn sodium治療氣喘之主要作用機制？","options":["(A) 降低迷走神經活性，解除支氣管平滑肌過度收縮","(B) 活化腺苷酸環化酶（adenylyl cyclase）使cAMP量上升","(C) 抑制磷酸二酯酶（phosphodiesterase）使cGMP量上升","(D) 抑制肥大細胞去顆粒化（mast cell degranulation）"],"answer":3,"image":""},{"id":"md2-109-2-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第2次第68題","year":109,"session":2,"number":68,"question":"Glucocorticoids可抑制發炎物質的合成，且具有誘發抗發炎蛋白的作用，而該抗發炎蛋白具有抑制phospholipase A2的作用，此抗發炎蛋白是：","options":["(A) trypsin","(B) leptin","(C) lipocortin","(D) leukotriene"],"answer":2,"image":""},{"id":"md2-109-2-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第2次第69題","year":109,"session":2,"number":69,"question":"當病人罹患發作性睡病（narcolepsy）時，使用下列何種藥物可以減低其睡意，而該藥物是一種inverse H3 agonist？","options":["(A) triprolidine","(B) tiotidine","(C) pitolisant","(D) cetirizine"],"answer":2,"image":""},{"id":"md2-109-2-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第2次第70題","year":109,"session":2,"number":70,"question":"患者罹患腦下垂瘤（pituitary tumor）導致泌乳素（prolactin）大量產生，使用下列何種藥物的治療效果最佳？","options":["(A) ergonovine","(B) bromocriptine","(C) methysergide","(D) ketanserin"],"answer":1,"image":""},{"id":"md2-109-2-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"109年第2次第71題","year":109,"session":2,"number":71,"question":"下列何種藥物的降眼壓效果最明顯？","options":["(A) selexipag","(B) iloprost","(C) alprostadil","(D) bimatoprost"],"answer":3,"image":""},{"id":"md2-109-2-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"109年第2次第72題","year":109,"session":2,"number":72,"question":"Baclofen為中樞性肌肉鬆弛劑，下列何者為該藥物在中樞神經系統的作用機制？","options":["(A) 活化GABAB受體","(B) 抑制GABAB受體","(C) 活化α2-腎上腺素受體","(D) 抑制α2-腎上腺素受體"],"answer":0,"image":""},{"id":"md2-109-2-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"109年第2次第73題","year":109,"session":2,"number":73,"question":"下列那一個鴉片類藥物的止痛強度（potency）最高？","options":["(A) fentanyl","(B) morphine","(C) methadone","(D) meperidine"],"answer":0,"image":""},{"id":"md2-109-2-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"109年第2次第74題","year":109,"session":2,"number":74,"question":"關於吸入性麻醉藥物nitrous oxide與halothane作用的比較，下列敘述何者錯誤？","options":["(A) nitrous oxide最小肺泡濃度（MAC）值比halothane小","(B) nitrous oxide的麻醉強度（potency）比halothane弱","(C) nitrous oxide血液／氣體分配係數（blood：gas partition coefficient）值比halothane小","(D) nitrous oxide麻醉誘導及恢復速度比halothane快"],"answer":0,"image":""},{"id":"md2-109-2-75","subject":"md2","topic":"藥理-化學治療","meta":"109年第2次第75題","year":109,"session":2,"number":75,"question":"Penicillamine可用來治療重金屬中毒，但不包括下列何者？","options":["(A) 銅中毒","(B) 威爾森氏症（Wilson's disease）","(C) 汞中毒","(D) 砷中毒"],"answer":3,"image":""},{"id":"md2-109-2-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"109年第2次第76題","year":109,"session":2,"number":76,"question":"下列有關脂肪變性（steatosis）的敘述，何者錯誤？","options":["(A) 脂肪變性是指在實質細胞（parenchymal cell）內膽固醇（cholesterol）不正常的積聚","(B) 肝臟脂肪變性常見於糖尿病患者","(C) NADH的量上升是酒精造成脂肪變性的機制之一","(D) 蛋白質營養不良，亦常見肝臟脂肪變性"],"answer":0,"image":""},{"id":"md2-109-2-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"109年第2次第77題","year":109,"session":2,"number":77,"question":"下列那一項與慢性發炎之組織表現相關性最低？","options":["(A) 淋巴球和漿細胞","(B) 巨噬細胞","(C) 纖維化","(D) 水腫"],"answer":3,"image":""},{"id":"md2-109-2-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"109年第2次第78題","year":109,"session":2,"number":78,"question":"有關全身性紅斑性狼瘡（systemic lupus erythematosus）之敘述，下列何者正確？","options":["(A) 容易引起腎絲球腎炎，其病理變化極具特異性，可據以直接診斷紅斑性狼瘡","(B) 引起的腎絲球腎炎中，最嚴重的病理型態為膜狀腎絲球腎炎（membranous glomerulonephritis）","(C) 是造成非細菌性疣贅性心內膜炎（nonbacterial verrucous endocarditis）的成因之一","(D) 引起的血管炎是造成壞疽性臁瘡（ecthyma gangrenosum）的主要成因"],"answer":2,"image":""},{"id":"md2-109-2-79","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"109年第2次第79題","year":109,"session":2,"number":79,"question":"下列腫瘤之發生何者與Epstein-Barr病毒的相關性最低？","options":["(A) 子宮頸癌","(B) 鼻咽癌","(C) 伯基特氏淋巴瘤（Burkitt lymphoma）","(D) 何杰金氏淋巴瘤（Hodgkin lymphoma）"],"answer":0,"image":""},{"id":"md2-109-2-80","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"109年第2次第80題","year":109,"session":2,"number":80,"question":"下列何者最常於惡性腫瘤細胞中出現基因靜默（gene silencing）之現象？","options":["(A) CDK4","(B) MDM2","(C) p16","(D) EWS"],"answer":2,"image":""},{"id":"md2-109-2-81","subject":"md2","topic":"病理-心血管血液","meta":"109年第2次第81題","year":109,"session":2,"number":81,"question":"有關肺臟血栓性栓塞症（pulmonary thromboembolism）的特徵，下列何者錯誤？","options":["(A) 下肢的表層靜脈曲張（varicosis of superficial veins）的血栓比深層靜脈血栓（deep vein thrombosis）更容易引起肺臟血栓性栓塞症","(B) 大部分的肺臟血栓性栓塞症沒有明顯臨床症狀","(C) 慢性肺臟血栓性栓塞症會引起肺動脈高壓（pulmonary hypertension）","(D) 肺出血比肺梗塞（pulmonary infarct）常見"],"answer":0,"image":""},{"id":"md2-109-2-82","subject":"md2","topic":"病理-心血管血液","meta":"109年第2次第82題","year":109,"session":2,"number":82,"question":"腹主動脈瘤（abdominal aortic aneurysm）最可能出現的病因為何？","options":["(A) 巨細胞動脈炎（giant cell arteritis）","(B) IgG4相關疾病（IgG4-related disease）","(C) 粥狀動脈硬化（atherosclerosis）","(D) 第三期梅毒（tertiary syphilis）"],"answer":2,"image":""},{"id":"md2-109-2-83","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"109年第2次第83題","year":109,"session":2,"number":83,"question":"小動脈受損時會因神經性的反應機制而發生短暫收縮，下列何種物質最有可能會加強此種收縮反應？","options":["(A) 組織型胞漿素原活化因子（tissue-type plasminogen activator）","(B) 組織因子（tissue factor）","(C) 凝血酵素（thrombin）","(D) 內皮素（endothelin）"],"answer":3,"image":""},{"id":"md2-109-2-84","subject":"md2","topic":"病理-心血管血液","meta":"109年第2次第84題","year":109,"session":2,"number":84,"question":"有關血栓性血小板減少性紫斑症（thrombotic thrombocytopenic purpura）的敘述，下列何者正確？","options":["(A) 病人通常症狀輕微，即使不接受治療也很少造成死亡","(B) 以血漿置換術（plasma exchange）治療對大多數病人有效","(C) 病人血漿中的ADAMTS13酵素活性過高，促進血栓生成","(D) 病人血漿中有異常巨大的第九因子（factor IX）多聚體（multimer）"],"answer":1,"image":""},{"id":"md2-109-2-85","subject":"md2","topic":"病理-免疫感染遺傳","meta":"109年第2次第85題","year":109,"session":2,"number":85,"question":"下列有關非何杰金氏淋巴癌（non-Hodgkin lymphoma）的腫瘤細胞來源，何者正確？","options":["(A) 成人型T細胞白血病／淋巴瘤（adult T cell leukemia/lymphoma）主要被歸類為自然殺手T細胞（natural killer T lymphocyte）","(B) 蕈狀肉芽腫（mycosis fungoides）主要被歸類為記憶B細胞（memory B lymphocyte）","(C) 異生性大細胞淋巴瘤（anaplastic large cell lymphoma）主要被歸類為毒殺型T細胞（cytotoxic T lymphocyte）","(D) Burkitt氏淋巴癌主要被歸類為純真B細胞（naive B cell）"],"answer":2,"image":""},{"id":"md2-109-2-86","subject":"md2","topic":"病理-呼吸消化","meta":"109年第2次第86題","year":109,"session":2,"number":86,"question":"關於鼻腔鼻竇Schneiderian乳頭狀瘤（sinonasal Schneiderian papilloma）的敘述，下列何者正確？","options":["(A) 依組織型態可分為倒生型（inverted）、外生型（exophytic）、圓柱型（cylindrical），其中圓柱型腫瘤最常見，與第6及第11型人類乳突病毒（human papillomavirus）關係最密切","(B) 倒生型的腫瘤如果只有進行局部腫瘤切除，容易切不乾淨而復發","(C) 外生型腫瘤好發於20～30歲性活躍的年輕男性，為最常見的亞型","(D) 此類腫瘤屬良性腫瘤，無轉化惡性之虞"],"answer":1,"image":""},{"id":"md2-109-2-87","subject":"md2","topic":"病理-呼吸消化","meta":"109年第2次第87題","year":109,"session":2,"number":87,"question":"下列有關氣喘的病理變化的敘述，何者錯誤？","options":["(A) 基底膜下纖維化","(B) 黏膜下腺體肥大","(C) 血管增生","(D) 支氣管壁肌肉萎縮"],"answer":3,"image":""},{"id":"md2-109-2-88","subject":"md2","topic":"病理-呼吸消化","meta":"109年第2次第88題","year":109,"session":2,"number":88,"question":"下列何種疾病與吸菸較無相關？","options":["(A) 脫落性間質肺炎（desquamative interstitial pneumonia）","(B) 呼吸小支氣管炎相關之肺間質疾病（respiratory bronchiolitis-associated interstitial lung disease）","(C) 類肉瘤（sarcoidosis）","(D) 肺癌（lung carcinoma）"],"answer":2,"image":""},{"id":"md2-109-2-89","subject":"md2","topic":"病毒學","meta":"109年第2次第89題","year":109,"session":2,"number":89,"question":"D型肝炎病毒（HDV）是一種有缺陷的病毒。下列那種肝炎病毒對肝細胞中HDV的複製至關重要？","options":["(A) A型肝炎病毒","(B) B型肝炎病毒","(C) C型肝炎病毒","(D) E型肝炎病毒"],"answer":1,"image":""},{"id":"md2-109-2-90","subject":"md2","topic":"病理-呼吸消化","meta":"109年第2次第90題","year":109,"session":2,"number":90,"question":"有關家族性結腸息肉病（familial adenomatous polyposis）的敘述，下列何者錯誤？","options":["(A) 體染色體顯性遺傳（autosomal dominant）","(B) 大腸腺瘤息肉（adenomas）通常在出生時就已存在","(C) APC基因突變與Gardner syndrome及Turcot syndrome有關","(D) 未治療的患者產生大腸腺癌的機率幾乎是100%"],"answer":1,"image":""},{"id":"md2-109-2-91","subject":"md2","topic":"病理-呼吸消化","meta":"109年第2次第91題","year":109,"session":2,"number":91,"question":"關於急性膽囊炎，以下敘述何者錯誤？","options":["(A) 約90%為急性結石性膽囊炎，因膽囊頸部或膽囊管阻塞造成","(B) 前列腺素（prostaglandin）的釋放與發炎有關","(C) 急性非結石性膽囊炎主要與缺血有關","(D) 急性非結石性膽囊炎主要的風險因子包括敗血症及喝酒"],"answer":3,"image":""},{"id":"md2-109-2-92","subject":"md2","topic":"病理-免疫感染遺傳","meta":"109年第2次第92題","year":109,"session":2,"number":92,"question":"關於Waterhouse-Friderichsen症候群的敘述，下列何者錯誤？","options":["(A) 常合併腦膜炎雙球菌（Neisseria meningitidis）敗血症","(B) 嚴重之低血壓","(C) 常併發瀰漫性血管內凝血","(D) 腎上腺自周邊之皮質開始出血，之後擴展至髓質"],"answer":3,"image":""},{"id":"md2-109-2-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"109年第2次第93題","year":109,"session":2,"number":93,"question":"在藥物或毒物所引起的腎小管間質性腎炎，在間質中浸潤的炎症細胞主要為：","options":["(A) 淋巴球及巨噬細胞","(B) 嗜酸性白血球","(C) 漿細胞","(D) 肥大細胞"],"answer":0,"image":""},{"id":"md2-109-2-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"109年第2次第94題","year":109,"session":2,"number":94,"question":"下列何者不是甲狀腺乳突狀癌（papillary carcinoma）之典型細胞核變化？","options":["(A) Ground-glass nuclei","(B) Intranuclear pseudo-inclusions","(C) Giant and red nucleoli","(D) Intranuclear grooves"],"answer":2,"image":""},{"id":"md2-109-2-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"109年第2次第95題","year":109,"session":2,"number":95,"question":"下列有關異位妊娠（ectopic pregnancy）的敘述，何者較不正確？","options":["(A) 最常見異位妊娠的著床位置為卵巢","(B) 最重要的誘發因素（predisposing factor）是骨盆腔發炎","(C) 相關因子包括子宮內膜異位症（endometriosis）或之前開刀的病史","(D) 異位妊娠的著床位置有可能產生蛻膜變化（decidual changes）"],"answer":0,"image":""},{"id":"md2-109-2-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"109年第2次第96題","year":109,"session":2,"number":96,"question":"下列有關良性前列腺增生症（benign prostatic hyperplasia, BPH）的敘述，何者較不正確？","options":["(A) 是50歲以上男性最常見良性前列腺疾病","(B) 組織學上可見前列腺上皮與間質的結節性增生（nodular hyperplasia）","(C) 其致病機轉，主要是上皮細胞的大量增生","(D) 雄性素（androgen）在良性前列腺增生症的形成很重要"],"answer":2,"image":""},{"id":"md2-109-2-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"109年第2次第97題","year":109,"session":2,"number":97,"question":"下列有關隱睪症（cryptorchidism）的敘述，何者較不正確？","options":["(A) 睪丸的下移可以分為兩個時期，在第一時期，腹部位移時期（transabdominal phase），主要是受穆勒氏管抑制素（müllerian-inhibiting substance）的控制","(B) 睪丸的下移可以分為兩個時期，在第二時期，腹股溝陰囊時期（inguinoscrotal phase），主要是受雄性素（androgen）的控制","(C) 未下降的睪丸，如未及時治療，比正常下降的睪丸有更高發生睪丸癌的危險性","(D) 腹腔是睪丸未能按照正常發育程序從腰部腹膜後下降至陰囊而停留（arrest）的最常見位置"],"answer":3,"image":""},{"id":"md2-109-2-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"109年第2次第98題","year":109,"session":2,"number":98,"question":"成骨不全症（osteogenesis imperfecta）其基本缺陷是第幾型膠原蛋白（collagen）合成異常？","options":["(A) 第一型","(B) 第二型","(C) 第三型","(D) 第四型"],"answer":0,"image":""},{"id":"md2-109-2-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"109年第2次第99題","year":109,"session":2,"number":99,"question":"神經退化性疾病（neurodegenerative diseases）的共同病理表徵是蛋白質異常堆積（protein aggregates），下列疾病與蛋白質堆積的配對，何者錯誤？","options":["(A) Frontotemporal lobar dementia；TDP-43","(B) Alzheimer disease；Aβ","(C) Amyotrophic lateral sclerosis；Tau","(D) Parkinson disease；α-synuclein"],"answer":2,"image":""},{"id":"md2-109-2-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"109年第2次第100題","year":109,"session":2,"number":100,"question":"下列何種細胞易受JC polyomavirus感染？","options":["(A) 寡樹突神經膠細胞（oligodendrocyte）","(B) 星狀神經膠細胞（astrocyte）","(C) 微膠細胞（microglia）","(D) 神經元細胞（neuron）"],"answer":[0,1],"image":"","answer_note":"更正:第100題答Ａ、Ｂ給分。"},{"id":"md2-110-1-1","subject":"md2","topic":"細菌學","meta":"110年第1次第1題","year":110,"session":1,"number":1,"question":"關於金黃色葡萄球菌（Staphylococcus aureus）致病因子的敘述，下列何者錯誤？","options":["(A) 蛋白質A（protein A）可與免疫球蛋白IgG之Fc結合，抑制宿主之調理及吞噬作用","(B) 腸毒素（enterotoxins）和中毒休克症候群毒素-1（toxic shock syndrome toxin-1）為超級抗原（superantigens）","(C) 脫皮毒素（exfoliative toxin）會引起表皮燙傷症候群（scalded skin syndrome）","(D) 葡萄球菌激酶（staphylokinase）促進纖維蛋白質（fibrin）的形成，阻礙吞噬細胞作用"],"answer":3,"image":""},{"id":"md2-110-1-2","subject":"md2","topic":"細菌學","meta":"110年第1次第2題","year":110,"session":1,"number":2,"question":"關於細菌膜孔蛋白質（porins）之敘述，下列何者正確？","options":["(A) 主要位於內膜（inner membrane）","(B) 可讓親水性分子通過","(C) 與內毒素（endotoxin）功能相似","(D) 屬於纖毛（fimbriae）蛋白質"],"answer":1,"image":""},{"id":"md2-110-1-3","subject":"md2","topic":"細菌學","meta":"110年第1次第3題","year":110,"session":1,"number":3,"question":"關於單核球增生李斯特菌（Listeria monocytogenes）之敘述，下列何者正確？","options":["(A) 具運動性之革蘭氏陽性菌","(B) 絕對（obligate）胞內寄生","(C) 於攝氏4度時無法生長","(D) 主要經由飛沫（aerosol）傳染"],"answer":0,"image":""},{"id":"md2-110-1-4","subject":"md2","topic":"細菌學","meta":"110年第1次第4題","year":110,"session":1,"number":4,"question":"治療由化膿性鏈球菌（Streptococcus pyogenes）所引起的軟組織（soft tissue）病變時，下列何者是醫護人員會面臨的最大挑戰？","options":["(A) 此病菌對青黴素（Penicillin）有抗藥性","(B) 此感染症常包含多種細菌感染（mixed infection），不易治療","(C) 受感染組織的迅速壞死，進一步引起敗血症（septicemia）","(D) 此病菌常造成持續性感染（persistent infection），不易根除"],"answer":2,"image":""},{"id":"md2-110-1-5","subject":"md2","topic":"細菌學","meta":"110年第1次第5題","year":110,"session":1,"number":5,"question":"關於炭疽桿菌（Bacillus anthracis）的敘述，下列何者錯誤？","options":["(A) 莢膜（Capsule）是毒力因子之一，具有抗吞噬作用","(B) 其保護性抗原（Protective antigen, PA）當作免疫原（immunogen）的效力，較水腫因子（edema factor）或致死因子（lethal factor）差","(C) 致死毒素（Lethal toxin）具金屬蛋白酶（metalloprotease）活性","(D) 水腫毒素（Edema toxin）具腺苷酸環化酶（adenylate cyclase）活性"],"answer":1,"image":""},{"id":"md2-110-1-6","subject":"md2","topic":"細菌學","meta":"110年第1次第6題","year":110,"session":1,"number":6,"question":"有一病人因久咳且痰中帶有血絲而就診，經醫師採集其痰液進行細菌培養檢測後，發現結核分枝桿菌（Mycobacterium tuberculosis）。有關此病菌特性的敘述，下列何者錯誤？","options":["(A) 該菌為抗酸性染色（acid-fast stain）陽性","(B) 該菌染色體DNA之G+C含量較大腸桿菌（Escherichia coli）為高","(C) 該菌細胞壁富含黴菌酸（mycolic acids）","(D) 此菌在人體內主要引起Th-2型免疫反應"],"answer":3,"image":""},{"id":"md2-110-1-7","subject":"md2","topic":"細菌學","meta":"110年第1次第7題","year":110,"session":1,"number":7,"question":"辨識具有毒力，所謂神奈川試驗陽性（Kanagawa-positive）之副溶血弧菌（Vibrio parahaemolyticus），通常是依據此菌所產生的下列那種成分？","options":["(A) 莢膜多醣體（capsular polysaccharides）","(B) 熱不安定性腸毒素（heat-labile enterotoxin）","(C) 熱安定性溶血素（thermo-stable direct hemolysin）","(D) 脂多醣體（lipopolysaccharides）"],"answer":2,"image":""},{"id":"md2-110-1-8","subject":"md2","topic":"病毒學","meta":"110年第1次第8題","year":110,"session":1,"number":8,"question":"關於第一型人類嗜T淋巴球病毒（Human T-cell lymphotropic virus type 1, HTLV-1）引起之人類急性T細胞白血病（adult acute T-cell lymphocytic leukemia, ATLL）的敘述，下列何者錯誤？","options":["(A) 可由輸血、性交以及哺乳傳染","(B) 約一半的感染者會產生此病","(C) 治療多用疊氮胸苷（azidothymidine, AZT）與甲型干擾素（interferon-α）","(D) 此病之預後（prognosis）很差"],"answer":1,"image":""},{"id":"md2-110-1-9","subject":"md2","topic":"病毒學","meta":"110年第1次第9題","year":110,"session":1,"number":9,"question":"下列何者不屬於反轉錄病毒科（Retrovirus family）？","options":["(A) 腫瘤病毒亞科（Oncovirinae）","(B) 環狀病毒亞科（Orbivirinae）","(C) 慢病毒亞科（Lentivirinae）","(D) 泡沫病毒亞科（Spumavirinae）"],"answer":1,"image":""},{"id":"md2-110-1-10","subject":"md2","topic":"病毒學","meta":"110年第1次第10題","year":110,"session":1,"number":10,"question":"下列何種方法，最不能去除外科器械上的傳染性蛋白質（prion）之感染能力？","options":["(A) 高壓滅菌121℃，1個小時","(B) 浸泡於5%次氯酸（hypochlorite）溶液","(C) 浸泡於1 M氫氧化鈉（NaOH）溶液","(D) 紫外線消毒"],"answer":3,"image":""},{"id":"md2-110-1-11","subject":"md2","topic":"病毒學","meta":"110年第1次第11題","year":110,"session":1,"number":11,"question":"關於人類乳突瘤病毒（Human papillomavirus, HPV）的敘述，下列何者錯誤？","options":["(A) 可以感染皮膚以及黏膜組織","(B) 沒有外套膜（envelope）","(C) 其E1A與E1B蛋白質可以活化致癌基因","(D) HPV-16和HPV-18常與癌症的形成有關"],"answer":2,"image":""},{"id":"md2-110-1-12","subject":"md2","topic":"病毒學","meta":"110年第1次第12題","year":110,"session":1,"number":12,"question":"關於肝炎病毒（hepatitis viruses）之敘述，下列何者錯誤？","options":["(A) A型肝炎病毒與C型肝炎病毒皆為正股RNA病毒","(B) B型肝炎病毒與C型肝炎病毒皆有外套膜（envelope）","(C) A型肝炎病毒與E型肝炎病毒常透過血液傳染","(D) B型肝炎病毒在宿主細胞核內複製"],"answer":2,"image":""},{"id":"md2-110-1-13","subject":"md2","topic":"病毒學","meta":"110年第1次第13題","year":110,"session":1,"number":13,"question":"下列何者為人類免疫缺陷病毒（Human immunodeficiency virus, HIV）之套膜蛋白質（envelope protein）？","options":["(A) gp120","(B) gp21","(C) p66","(D) p55"],"answer":0,"image":""},{"id":"md2-110-1-14","subject":"md2","topic":"真菌學","meta":"110年第1次第14題","year":110,"session":1,"number":14,"question":"關於致病性皮癬菌（Dermatophytes）之敘述，下列何者正確？","options":["(A) 不會人傳人","(B) 表皮癬菌屬（Epidermophyton）不產生小分生孢子（microconidia）","(C) 小孢癬菌屬（Microsporum）極少產生大分生孢子（macroconidia）","(D) 毛癬菌屬（Trichophyton）產生大量大分生孢子（macroconidia）"],"answer":1,"image":""},{"id":"md2-110-1-15","subject":"md2","topic":"真菌學","meta":"110年第1次第15題","year":110,"session":1,"number":15,"question":"下列何者為多烯類（polyenes）藥物抑制真菌之主要機轉？","options":["(A) 直接與麥角固醇（ergosterol）結合，破壞細胞膜，造成細胞質電解質不平衡","(B) 抑制14-α-脫甲基酶（Demethylase），使羊毛甾醇（lanosterol）無法進行C14位置之脫甲基反應","(C) 抑制鯊烯環氧酶（squalene epoxidase），使鯊烯（squalene）無法進行閉環以形成羊毛甾醇","(D) 抑制1,3-β-葡聚醣（1,3-β-glucans）之合成"],"answer":0,"image":""},{"id":"md2-110-1-16","subject":"md2","topic":"真菌學","meta":"110年第1次第16題","year":110,"session":1,"number":16,"question":"真菌菌絲（hyphae）之兩種基本形態為何？","options":["(A) 隔菌絲（septate hyphae）和多核體菌絲（coenocytic hyphae）","(B) 隔菌絲和發芽管（germ tube）","(C) 假菌絲（pseudohyphae）和多核體菌絲","(D) 假菌絲和鎖狀連接菌絲（clamp connection hyphae）"],"answer":0,"image":""},{"id":"md2-110-1-17","subject":"md2","topic":"細菌學","meta":"110年第1次第17題","year":110,"session":1,"number":17,"question":"目前預防博德氏百日咳桿菌（Bordetella pertussis）的疫苗，主要組成為何？","options":["(A) 無細胞疫苗（acellular vaccines）","(B) 脂多醣體（lipopolysaccharides）","(C) 減毒疫苗（attenuated vaccines）","(D) 莢膜多醣體（capsular polysaccharides）"],"answer":0,"image":""},{"id":"md2-110-1-18","subject":"md2","topic":"免疫學","meta":"110年第1次第18題","year":110,"session":1,"number":18,"question":"阿吉最近得了流行性感冒，他聽老師說病毒感染沒有特效藥可以吃，於是他就決定做一個實驗，不看醫生也不吃藥，結果在兩個星期後，真的自然好了，所有流鼻涕、咳嗽及發燒的症狀都消失。有關這段時間中阿吉體內的免疫反應之敘述何者錯誤？","options":["(A) 在病毒感染的幾個小時內，阿吉的肺部會有大量的細胞激素（cytokines），包含第一及第三型干擾素（interferons）的產生，並且讓肺部的細胞進入抗病毒狀態","(B) 在病毒感染的幾個小時到幾天內，阿吉肺部的自然殺手細胞（natural killer cell, NK cell）會開始作用，殺死被病毒感染的細胞","(C) 在病毒感染的幾天後，CD8 T細胞會在淋巴結中被活化並進行抗體依賴性的細胞毒殺作用（ADCC），進一步殺死被病毒感染的細胞，並清除病毒","(D) 在病毒感染的幾天後，B細胞會被活化，並進一步分化成漿細胞（plasma cell）而分泌抗體，抗體可以經由血液循環去中和病毒來防止病毒擴散到全身"],"answer":2,"image":""},{"id":"md2-110-1-19","subject":"md2","topic":"免疫學","meta":"110年第1次第19題","year":110,"session":1,"number":19,"question":"下列何種補體調控蛋白（complement-regulatory proteins）是直接干擾C9的聚合化以抑制膜攻擊複合物（membrane attack complex, MAC）的形成？","options":["(A) CD59","(B) membrane cofactor of proteolysis（MCP, CD46）","(C) decay-accelerating factor（DAF, CD55）","(D) C1 inhibitor"],"answer":0,"image":""},{"id":"md2-110-1-20","subject":"md2","topic":"免疫學","meta":"110年第1次第20題","year":110,"session":1,"number":20,"question":"大部分的專業性吞噬細胞也同時可執行專業性抗原呈獻細胞（antigen-presenting cells）的功能，將抗原呈獻給CD4 T細胞。其主要的原因是這群專業性抗原呈獻細胞大量表現：","options":["(A) MHC class I分子","(B) MHC class II分子","(C) MHC class III分子","(D) pattern recognition receptors"],"answer":1,"image":""},{"id":"md2-110-1-21","subject":"md2","topic":"免疫學","meta":"110年第1次第21題","year":110,"session":1,"number":21,"question":"抗體多樣性（antibody diversity）的機制是抗體可辨識各式各樣抗原的主要原因，有關抗體多樣性的敘述何者錯誤？","options":["(A) Susumu Tonegawa教授因發現抗體多樣性的遺傳及分子作用原理獲得諾貝爾醫學獎","(B) 抗體多樣性是在B細胞的發育過程所產生的結果","(C) 在B細胞發育過程所造成的抗體多樣性包含組合多樣性（combinatorial diversity）及連接多樣性（junctional diversity）","(D) 當活化的B細胞進行抗體轉換（isotype switching）時也會貢獻抗體多樣性"],"answer":3,"image":""},{"id":"md2-110-1-22","subject":"md2","topic":"免疫學","meta":"110年第1次第22題","year":110,"session":1,"number":22,"question":"2018年諾貝爾醫學獎頒發給2位對癌症免疫療法有重大貢獻的科學家，James P. Allison與Tasuku Honjo因開發CTLA-4與PD-1在癌症治療的應用而獲獎。下列有關免疫系統和腫瘤細胞交互作用的敘述，何者錯誤？","options":["(A) 腫瘤細胞如果表現腫瘤特定抗原，可以引發專一性的毒殺性T細胞（cytotoxic T cells）來清除腫瘤","(B) 腫瘤細胞如果累積突變，可以表現CTLA-4在其細胞表面，因此抑制T細胞的反應","(C) 除了毒殺性T細胞（cytotoxic T cells）之外，自然殺手細胞（natural killer cells）也會清除腫瘤","(D) 讓癌症病人施打對抗CTLA-4或PD-1的抗體是一種癌症的免疫療法，可以阻斷抑制訊號，進而活化T細胞來清除腫瘤"],"answer":1,"image":""},{"id":"md2-110-1-23","subject":"md2","topic":"免疫學","meta":"110年第1次第23題","year":110,"session":1,"number":23,"question":"不同的抗體類型（class或稱isotype）具有不同功能是因為抗體的Fc能夠藉由與Fc受體（Fc receptor）的結合去啟動不同免疫細胞的反應，下列有關Fc受體的敘述何者錯誤？","options":["(A) Fc受體可以是單體（monounit）或是以複合體（multisubunit complex）的形式存在細胞表面","(B) 不同亞型（subclasses）的抗體可以和同一種的Fc受體結合，而且它們和Fc受體的親合力也都一樣","(C) 處於自由狀態的抗體（free antibody）可以和Fc受體結合，經抗原結合後的抗體會傳遞訊號去活化或抑制表現Fc受體的免疫細胞的功能","(D) 大部分表現Fc受體都是具有吞噬能力的細胞如巨噬細胞和嗜中性球，而且當細菌同時被抗體和補體結合後，吞噬細胞的Fc受體和補體受體CR1的同時作用會引發更強烈的吞噬反應"],"answer":1,"image":""},{"id":"md2-110-1-24","subject":"md2","topic":"免疫學","meta":"110年第1次第24題","year":110,"session":1,"number":24,"question":"黏膜（mucosa）組織對食物抗原例如麩質蛋白（gluten）所產生的抗體主要種類為：","options":["(A) IgG","(B) IgA","(C) IgM","(D) IgD"],"answer":1,"image":""},{"id":"md2-110-1-25","subject":"md2","topic":"免疫學","meta":"110年第1次第25題","year":110,"session":1,"number":25,"question":"下列何種作用最適合描述結核桿菌（Mycobacterium tuberculosis）的免疫逃脫（immune evasion）機制？","options":["(A) antigenic drift（gene mutation）","(B) gene conversion（gene rearrangement）","(C) 阻斷MHC class I pathway","(D) 抑制吞噬體（phagosome）與溶酶體（lysosome）的融合"],"answer":3,"image":""},{"id":"md2-110-1-26","subject":"md2","topic":"免疫學","meta":"110年第1次第26題","year":110,"session":1,"number":26,"question":"有關tumor immunoediting的敘述，下列何者錯誤？","options":["(A) 免疫監測系統會導致腫瘤細胞產生突變","(B) 免疫監測系統會導致腫瘤細胞產生的抗原表現消失","(C) 免疫監測系統會導致腫瘤細胞產生的細胞特性改變","(D) 促進T細胞對腫瘤細胞的毒殺能力，導致腫瘤縮小"],"answer":3,"image":""},{"id":"md2-110-1-27","subject":"md2","topic":"免疫學","meta":"110年第1次第27題","year":110,"session":1,"number":27,"question":"當病人接受腎臟移植後10分鐘內就發生排斥，其主要原因是：","options":["(A) MHC class I不合","(B) MHC class II不合","(C) 病人體內已存有對抗移植物的抗體","(D) H抗原不合"],"answer":2,"image":""},{"id":"md2-110-1-28","subject":"md2","topic":"免疫學","meta":"110年第1次第28題","year":110,"session":1,"number":28,"question":"用來治療non-Hodgkin's lymphoma的Rituximab（anti-CD20 monoclonal antibody）主要可以剔除何種免疫細胞？","options":["(A) CD4 T cell","(B) CD8 T cell","(C) B cell","(D) dendritic cell"],"answer":2,"image":""},{"id":"md2-110-1-29","subject":"md2","topic":"寄生蟲學","meta":"110年第1次第29題","year":110,"session":1,"number":29,"question":"張先生嗜吃生魚片，最近常出現腹部絞痛、腹鳴（borborygmus）、腹瀉、厭食、噁心、嘔吐及低血壓等症狀，並伴隨有低蛋白血症、低血鉀及低血鈣等嚴重電解質失衡病症，張先生最有可能感染下列何種寄生蟲？","options":["(A) 菲律賓毛線蟲（Capillaria philippinensis）","(B) 海獸胃線蟲（Anisakis spp.）","(C) 旋毛蟲（Trichinella spiralis）","(D) 有棘頜口線蟲（Gnathostoma spinigerum）"],"answer":0,"image":""},{"id":"md2-110-1-30","subject":"md2","topic":"寄生蟲學","meta":"110年第1次第30題","year":110,"session":1,"number":30,"question":"關於廣東住血線蟲（Angiostrongylus cantonensis）之敘述，下列何者錯誤？","options":["(A) 感染人體會引起嗜伊紅性腦膜炎（eosinophilic meningitis）","(B) 確認診斷是在腦脊髓液中發現蟲體","(C) 吃生菜沙拉不會感染","(D) 患者腦脊髓液中嗜酸性白血球（eosinophil）異常增加"],"answer":2,"image":""},{"id":"md2-110-1-31","subject":"md2","topic":"寄生蟲學","meta":"110年第1次第31題","year":110,"session":1,"number":31,"question":"有關人類感染顆粒性包生絛蟲（Echinococcus granulosus）之敘述，下列何者正確？","options":["(A) 人類係食入生的或未煮熟的羊肉而感染","(B) 會在患者肝臟形成包生囊（hydatid cyst）","(C) 病灶區切面呈現肺泡狀囊（alveolar cyst），並有許多空腔","(D) 可在患者糞便中檢出六鉤幼蟲（oncosphere）卵"],"answer":1,"image":""},{"id":"md2-110-1-32","subject":"md2","topic":"寄生蟲學","meta":"110年第1次第32題","year":110,"session":1,"number":32,"question":"下列何種寄生蟲感染，最不可能在人類腦部造成異位病變（ectopic lesion），引起嚴重的臨床症狀？","options":["(A) 日本血吸蟲（Schistosoma japonicum）","(B) 衛氏肺吸蟲（Paragonimus westermani）","(C) 薑片蟲（Fasciolopsis buski）","(D) 異形異形吸蟲（Heterophyes heterophyes）"],"answer":2,"image":""},{"id":"md2-110-1-33","subject":"md2","topic":"寄生蟲學","meta":"110年第1次第33題","year":110,"session":1,"number":33,"question":"有關罹患瘧疾（malaria）後產生併發症的敘述，下列何者正確？","options":["(A) 腎絲球性腎炎（glomerulonephritis）：係因三日瘧原蟲（Plasmodium malariae）感染後，過多的原蟲沉積在腎絲球所造成的病變","(B) 黑水熱（blackwater fever）：和自體免疫有關，患者產生抗體攻擊受瘧原蟲感染的紅血球，導致破裂而造成","(C) 熱帶脾腫大症候群（tropical splenomegaly syndrome）：患者體內T淋巴球的大量增生所致","(D) 低血糖症（hypoglycemia）：特別是在惡性瘧原蟲（Plasmodium falciparum）發作時，血壓快速降低並伴隨高寄生蟲血症（hyperparasitemia）有關"],"answer":1,"image":""},{"id":"md2-110-1-34","subject":"md2","topic":"寄生蟲學","meta":"110年第1次第34題","year":110,"session":1,"number":34,"question":"人類因誤食受感染之貓（狗）蚤（flea），最可能感染下列何種寄生蟲？","options":["(A) 犬蛔蟲（Toxocara canis）","(B) 犬複殖器絛蟲（Dipylidium caninum）","(C) 犬鉤蟲（Ancylostoma caninum）","(D) 菲律賓毛線蟲（Capillaria philippinensis）"],"answer":1,"image":""},{"id":"md2-110-1-35","subject":"md2","topic":"寄生蟲學","meta":"110年第1次第35題","year":110,"session":1,"number":35,"question":"采采蠅（tsetse fly）可經叮咬而傳播下列何種人類寄生蟲？","options":["(A) 熱帶利什曼原蟲（Leishmania tropica）","(B) 杜氏利什曼原蟲（Leishmania donovani）","(C) 岡比亞錐蟲（Trypanosoma brucei gambiense）","(D) 枯西氏錐蟲（Trypanosoma cruzi）"],"answer":2,"image":""},{"id":"md2-110-1-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"110年第1次第36題","year":110,"session":1,"number":36,"question":"相較於世代追蹤研究，下列何者為病例對照研究的缺點？","options":["(A) 容易產生選擇性偏差","(B) 需要更長研究時間","(C) 需要更多樣本數","(D) 無法探討多重病因"],"answer":0,"image":""},{"id":"md2-110-1-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"110年第1次第37題","year":110,"session":1,"number":37,"question":"如果想要比較年輕人與老年人的流感罹患率，王醫師隨機收集100位年輕人與100位老年人民眾，詢問其過去一個月是否罹患流感，其中有42位年輕人及22位老年人回答有，因此估計年輕人流感罹患率為0.42，老年人流感罹患率為0.22。下列何者最不恰當？","options":["(A) 王醫師的隨機抽樣必須排除有可能互相傳染的樣本，才能得到這些估計值","(B) 王醫師的估計值0.42，必須假設每個年輕人得流感的機率都是一樣且互相獨立，才能成立","(C) 王醫師的老年人樣本如果源自1000床的老人安養中心的隨機抽樣，則可能因為群聚效應，不宜視為獨立樣本","(D) 王醫師可以合併樣本，利用200人當中有42+22=64位得到流感，來估計人口中得流感的機率為0.32"],"answer":3,"image":""},{"id":"md2-110-1-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"110年第1次第38題","year":110,"session":1,"number":38,"question":"A、B、C、D四校學生智商量表測驗分數平均值之95% 信賴區間分別為，A校：94～98分；B校：98～106分；C校：100～106分；D校：104～108分。若統計顯著水準為0.05，則下列那兩個學校之間的智商分數具有顯著差異？","options":["(A) A校與B校","(B) A校與C校","(C) B校與D校","(D) C校與D校"],"answer":1,"image":""},{"id":"md2-110-1-39","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"110年第1次第39題","year":110,"session":1,"number":39,"question":"關於全球暖化，下列敘述何者最不恰當？","options":["(A) 在各種溫室氣體中，除水蒸氣外以二氧化碳（CO2）為最重要","(B) 懸浮微粒對氣溫的影響與CO2對氣溫的影響一致，並有相互加成作用","(C) 全球暖化對健康的威脅是全球環境變遷的重要議題","(D) 京都議定書（Kyoto Protocol）主要宗旨為削減溫室氣體排放量"],"answer":1,"image":""},{"id":"md2-110-1-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"110年第1次第40題","year":110,"session":1,"number":40,"question":"下列有關於砷暴露的敘述，何者最不恰當？","options":["(A) 臺灣西南沿海曾發生烏腳病的流行，其原因可能與地河井水含砷有關","(B) 砷暴露也可能有較高風險罹患膀胱癌、肝癌、肺癌及腎癌","(C) 人或動物的毛髮或指甲可作為分析環境暴露程度的工具","(D) 臺灣自從提供自來水後，砷暴露的風險即明顯下降"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第40題一律給分 (原公告答案 D)"},{"id":"md2-110-1-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"110年第1次第41題","year":110,"session":1,"number":41,"question":"在門診中看到病人患有肝血管肉瘤，最可能的職業暴露為何？","options":["(A) 黏扣帶中的二異氰酸甲苯暴露","(B) 錳鐵熔煉暴露","(C) 石化工廠氯乙烯暴露","(D) 鉛蓄電池回收暴露"],"answer":2,"image":""},{"id":"md2-110-1-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"110年第1次第42題","year":110,"session":1,"number":42,"question":"職業衛生中8小時日時量平均容許濃度，是指該濃度，在下列何種情況大部分的工作人員，終其一生不會發生不良健康效應的濃度？","options":["(A) 每週工作48小時，每週工作6天","(B) 每週工作44小時，每週工作5天","(C) 每週工作40小時，每週工作5天","(D) 每週工作42小時，每週工作5天"],"answer":2,"image":""},{"id":"md2-110-1-43","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"110年第1次第43題","year":110,"session":1,"number":43,"question":"有關健康城市，下列敘述何者最不恰當？","options":["(A) 健康城市是一種結果，與過程無關","(B) 健康城市的行動方案是根據城市自己的優先次序","(C) 城市及鄉鎮間能相互支持、合作、學習及文化交流","(D) 健康城市關心世界資源公平分配"],"answer":0,"image":""},{"id":"md2-110-1-44","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"110年第1次第44題","year":110,"session":1,"number":44,"question":"某職場雇主基於上班族經常坐在辦公室工作，因此想推動職場健康促進計畫，人資部就先去調查職場員工的運動習慣，發現I.大部分員工都有想運動只是尚未行動、II.少數員工已經開始買了運動器材，但尚未規律進行運動。以上敘述I.與II.，各指的是員工那一個行為改變階段？","options":["(A) I.懵懂期（pre-contemplation phase）、II.準備期（preparation phase）","(B) I.準備期（preparation phase）、II.行動期（action phase）","(C) I.沉思期（contemplation phase）、II.準備期（preparation phase）","(D) I.沉思期（contemplation phase）、II.行動期（action phase）"],"answer":2,"image":""},{"id":"md2-110-1-45","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"110年第1次第45題","year":110,"session":1,"number":45,"question":"有關非法藥物（毒品）防制，下列敘述何者最不恰當？","options":["(A) 根據最新毒品危害防制條例對毒品的分級，K他命為第三級","(B) 比起性格較內向保守，外向且偏好追求刺激與新奇事物的青少年在接觸或嘗試毒品的機會相對較高","(C) 使用第一級、第二級或第三級毒品者，一旦被查獲，一律會被檢察官起訴","(D) 海洛因成癮者為戒除毒癮，定期前往指定機構進行美沙冬（methadone）治療，此為替代性藥物療法"],"answer":2,"image":""},{"id":"md2-110-1-46","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"110年第1次第46題","year":110,"session":1,"number":46,"question":"有一種看法，認為大眾媒體（如電影、電視或社交媒體）常常出現暴力的英雄主義鏡頭，青少年長期觀看這些媒體之後，認為媒體描繪情境是反映了社會真實，導致其暴力行為產生。上述是應用何種傳播理論影響青少年的健康行為？","options":["(A) 創新擴散（diffusion of innovation）","(B) 媒體倡導（media advocacy）","(C) 涵化理論（cultivation theory）","(D) 知溝理論（knowledge gap theory）"],"answer":2,"image":""},{"id":"md2-110-1-47","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"110年第1次第47題","year":110,"session":1,"number":47,"question":"下列有關傷害防制（injury prevention and control）的敘述，何者最不恰當？","options":["(A) 傷害防制是預防有人蓄意，如家暴、兒虐、自殺等所造成的傷害","(B) 傷害防制必須有各種專業領域來共同參與努力，包括醫學、公共衛生、交通、警政、教育和媒體等","(C) 流行病學的疾病三角模式〔宿主（host）–作因（agent）–環境（environment）〕，也可以用來解釋傷害產生的危險因子，以擬定傷害防制的策略","(D) 傷害防制是對會造成傷亡的事故來找出原因，並將傷害控制在最小範圍"],"answer":0,"image":""},{"id":"md2-110-1-48","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"110年第1次第48題","year":110,"session":1,"number":48,"question":"下列何種支付制度的基準單位最大，對醫療服務提供者的節約誘因最大？","options":["(A) 論量（論項）計酬","(B) 論日計酬","(C) 論病例計酬","(D) 論人計酬"],"answer":3,"image":""},{"id":"md2-110-1-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"110年第1次第49題","year":110,"session":1,"number":49,"question":"關於世界衛生組織（World Health Organization），下列敘述何者最不恰當？","options":["(A) 世界衛生組織的最高權力單位是世界衛生大會（World Health Assembly）","(B) 世界衛生組織的主要功能不包含技術合作","(C) 世界衛生組織是聯合國體系內的專門機構","(D) 經費短缺與組織效率不彰是世界衛生組織面臨的重大挑戰"],"answer":1,"image":""},{"id":"md2-110-1-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"110年第1次第50題","year":110,"session":1,"number":50,"question":"關於平衡計分卡（balanced scorecard），下列敘述何者最不恰當？","options":["(A) 基本精神在於將策略轉換成具體行動","(B) 一般包含財務、顧客、企業內部流程、企業學習與成長等四個構面","(C) 其中財務構面為領先指標（leading indicator）","(D) 在非營利事業單位，可以增加員工被授權程度之第五構面"],"answer":2,"image":""},{"id":"md2-110-1-51","subject":"md2","topic":"藥理-化學治療","meta":"110年第1次第51題","year":110,"session":1,"number":51,"question":"下列何者在用藥前須檢測HLA（human leukocyte antigen）-B*5701基因型，避免藥物造成廣泛性皮膚紅疹與水疱？","options":["(A) amoxicillin","(B) carbamazepine","(C) abacavir","(D) allopurinol"],"answer":2,"image":""},{"id":"md2-110-1-52","subject":"md2","topic":"藥理-化學治療","meta":"110年第1次第52題","year":110,"session":1,"number":52,"question":"關於抗生素之敘述，下列何者正確？","options":["(A) ampicillin和amoxicillin的吸收不會受到飲食的影響","(B) dicloxacillin吸收效果差是因為在酸性環境中不穩定","(C) amoxicillin的抗藥性產生主要是因為β-內醯胺酶（β-lactamase）的產生","(D) nafcillin主要由腎臟排泄"],"answer":2,"image":""},{"id":"md2-110-1-53","subject":"md2","topic":"藥理-化學治療","meta":"110年第1次第53題","year":110,"session":1,"number":53,"question":"關於單株抗體（monoclonal antibody）用於腫瘤治療之敘述，下列何者正確？","options":["(A) 使用alemtuzumab治療慢性淋巴細胞性白血病較無引發淋巴細胞減少（lymphopenia）的疑慮","(B) bevacizumab可抑制VEGF對內皮細胞的功能，適用於手術後即時投藥治療","(C) catumaxomab可同時作用在腫瘤及T細胞上而發揮療效","(D) cetuximab與ramucirumab的作用機轉同樣都是阻斷腫瘤細胞的EGFR活性"],"answer":2,"image":""},{"id":"md2-110-1-54","subject":"md2","topic":"藥理-化學治療","meta":"110年第1次第54題","year":110,"session":1,"number":54,"question":"下列抗癌藥物中，何者可抑制topoisomerase II，導致癌細胞之DNA斷裂而產生抗癌作用？","options":["(A) busulfan","(B) cyclophosphamide","(C) idarubicin","(D) methotrexate"],"answer":2,"image":""},{"id":"md2-110-1-55","subject":"md2","topic":"藥理-化學治療","meta":"110年第1次第55題","year":110,"session":1,"number":55,"question":"下列何者為抗癌合併療法CMF治療乳癌藥物，且屬於pyrimidine類似物，其活性代謝產物可抑制thymidylate synthase？","options":["(A) 5-fluorouracil","(B) cytarabine","(C) methotrexate","(D) vincristine"],"answer":0,"image":""},{"id":"md2-110-1-56","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"110年第1次第56題","year":110,"session":1,"number":56,"question":"關於治療偏頭痛藥物sumatriptan之敘述，下列何者錯誤？","options":["(A) 其作用機制在於拮抗5-HT1B/1D","(B) 與抗憂鬱藥SSRI併用可能導致serotonin syndrome","(C) 冠狀動脈疾病（coronary artery disease）病人為使用禁忌","(D) 可引起腦部血管收縮"],"answer":0,"image":""},{"id":"md2-110-1-57","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"110年第1次第57題","year":110,"session":1,"number":57,"question":"關於fenofibrate之敘述，下列何者錯誤？","options":["(A) 可活化肝臟脂肪酸氧化反應","(B) 可活化PPAR-α受體","(C) 主要副作用為肌肉病變及肝功能異常","(D) 具抑制lipoprotein lipase活性"],"answer":3,"image":""},{"id":"md2-110-1-58","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第1次第58題","year":110,"session":1,"number":58,"question":"東京奧林匹克運動會針對運動員之禁藥檢驗，其中erythropoietin（EPO）被列為重要篩檢項目，下列有關EPO之敘述何者錯誤？","options":["(A) darbepoetin alfa為EPO類似物","(B) 常見副作用為高血壓及血栓症","(C) 受體活化ERK訊息","(D) 刺激紅血球幹細胞增殖及分化"],"answer":2,"image":""},{"id":"md2-110-1-59","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"110年第1次第59題","year":110,"session":1,"number":59,"question":"有關desmopressin促進凝血作用的機轉，下列何者正確？","options":["(A) 促進plasminogen活化","(B) 調節凝血因子factor VIII的釋放","(C) 增加cyclic AMP的分解","(D) 活化ADP receptor"],"answer":1,"image":""},{"id":"md2-110-1-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第1次第60題","year":110,"session":1,"number":60,"question":"李太太最近半年出現心悸、手抖、凸眼等症狀，到醫院就診後發現有甲狀腺機能亢進（hyperthyroidism）的情況。下列藥物那一種比較不適合她？","options":["(A) propylthiouracil","(B) levothyroxine","(C) Lugol's solution","(D) propranolol"],"answer":1,"image":""},{"id":"md2-110-1-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第1次第61題","year":110,"session":1,"number":61,"question":"下列何種降血糖藥，較適合用於第一型糖尿病？","options":["(A) dapagliflozin","(B) sitagliptin","(C) insulin","(D) glipizide"],"answer":2,"image":""},{"id":"md2-110-1-62","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第1次第62題","year":110,"session":1,"number":62,"question":"下列何種疾病比較不適合使用類固醇／糖皮質激素治療？","options":["(A) 愛迪生氏病（Addison's disease）","(B) 發炎性腸道疾病（inflammatory bowel disease）","(C) 消化性潰瘍（peptic ulcer）","(D) 氣喘（asthma）"],"answer":2,"image":""},{"id":"md2-110-1-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"110年第1次第63題","year":110,"session":1,"number":63,"question":"下列何者為D1-dopamine receptor agonist，可以做為降血壓藥物？","options":["(A) clonidine","(B) diazoxide","(C) fenoldopam","(D) ketanserin"],"answer":2,"image":""},{"id":"md2-110-1-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"110年第1次第64題","year":110,"session":1,"number":64,"question":"下列有關acetazolamide利尿劑的敘述，何者正確？","options":["(A) 作用於遠曲小管位置","(B) 可用於治療青光眼","(C) 易造成耳毒性","(D) 會引起高血鉀"],"answer":1,"image":""},{"id":"md2-110-1-65","subject":"md2","topic":"藥理-總論與自主神經","meta":"110年第1次第65題","year":110,"session":1,"number":65,"question":"活化alpha-1交感受體（alpha-1 adrenoceptor）可能引起人體產生的反應中，下列何者錯誤？","options":["(A) 膀胱逼尿肌（detrusor muscle）收縮","(B) 豎毛肌（pilomotor muscle）收縮","(C) 骨骼肌中血管收縮","(D) 心肌收縮力增強"],"answer":0,"image":""},{"id":"md2-110-1-66","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第1次第66題","year":110,"session":1,"number":66,"question":"下列抗蕈毒性藥物（antimuscarinic drug）中，何者不易通過血腦屏障（blood-brain barrier），因此其吸入性（inhalational）劑型適合用於舒張慢性阻塞性肺病（chronic obstructive pulmonary disease）患者之氣管，且半衰期可長達25小時？","options":["(A) tropicamide","(B) ipratropium","(C) tiotropium","(D) benztropine"],"answer":2,"image":""},{"id":"md2-110-1-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第1次第67題","year":110,"session":1,"number":67,"question":"下列何種吸入型氣喘藥物，透過計量吸入器（metered-dose inhaler）使用時，主要只作用在肺臟，短效且幾乎無生體可用率（bioavailability）？","options":["(A) albuterol","(B) montelukast","(C) flunisolide","(D) tiotropium"],"answer":0,"image":""},{"id":"md2-110-1-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第1次第68題","year":110,"session":1,"number":68,"question":"下列H2受體拮抗劑（H2-receptor antagonist）間的作用強度（potency）差異可達50倍，其中何者抑制胃酸分泌的作用強度最強？","options":["(A) cimetidine","(B) ranitidine","(C) nizatidine","(D) famotidine"],"answer":3,"image":""},{"id":"md2-110-1-69","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"110年第1次第69題","year":110,"session":1,"number":69,"question":"睡眠失調的病人，可以使用下列何種藥物來治療，該藥物是MT1和MT2的致效劑（agonist）？","options":["(A) tasimelteon","(B) sumatriptan","(C) repinotan","(D) orlistat"],"answer":0,"image":""},{"id":"md2-110-1-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第1次第70題","year":110,"session":1,"number":70,"question":"下列何種藥物最適合用來治療隅角開放性青光眼（open-angle glaucoma）？","options":["(A) alprostadil","(B) latanoprost","(C) misoprostol","(D) dinoprostone"],"answer":1,"image":""},{"id":"md2-110-1-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第1次第71題","year":110,"session":1,"number":71,"question":"下列何種藥物可以有效治療痛風病人的慢性高尿酸血症（chronic hyperuricemia）？","options":["(A) tramadol","(B) rilonacept","(C) ketorolac","(D) febuxostat"],"answer":3,"image":""},{"id":"md2-110-1-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"110年第1次第72題","year":110,"session":1,"number":72,"question":"治療思覺失調症（schizophrenia）的藥物，下列何者有最顯著的錐體外症候群（extrapyramidal syndrome）的副作用？","options":["(A) haloperidol","(B) clozapine","(C) olanzapine","(D) aripiprazole"],"answer":0,"image":""},{"id":"md2-110-1-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"110年第1次第73題","year":110,"session":1,"number":73,"question":"下列藥物何者不易造成精神依賴性（psychological dependence）？","options":["(A) cocaine","(B) psilocybin","(C) ketamine","(D) naloxone"],"answer":3,"image":""},{"id":"md2-110-1-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"110年第1次第74題","year":110,"session":1,"number":74,"question":"關於抗焦慮藥物buspirone的作用，下列敘述何者錯誤？","options":["(A) 沒有抗抽搐或肌肉鬆弛的作用","(B) 主要作用在腦部的GABAA受體","(C) 不會增強酒精的作用","(D) 服用數週後抗焦慮作用才會顯現"],"answer":1,"image":""},{"id":"md2-110-1-75","subject":"md2","topic":"藥理-總論與自主神經","meta":"110年第1次第75題","year":110,"session":1,"number":75,"question":"對於過量propranolol導致低血壓和心跳過慢，下列何種解毒劑（antidote）效果最佳？","options":["(A) glucagon","(B) atropine","(C) digoxin","(D) pralidoxime"],"answer":0,"image":""},{"id":"md2-110-1-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"110年第1次第76題","year":110,"session":1,"number":76,"question":"類纖維蛋白性壞死（fibrinoid necrosis）最常出現於下列何種情況？","options":["(A) 結核（tuberculosis）","(B) 腦梗塞（brain infarct）","(C) 血管炎（vasculitis）","(D) 急性胰臟炎（acute pancreatitis）"],"answer":2,"image":""},{"id":"md2-110-1-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"110年第1次第77題","year":110,"session":1,"number":77,"question":"受傷後，纖維母細胞（fibroblast）及微血管增生於疏鬆的間質組織中，並混合著發炎細胞，為下列何者的組織學特徵？","options":["(A) 肉芽腫（granuloma）","(B) 肉芽組織（granulation tissue）","(C) 蟹足腫（keloid）","(D) 類澱粉（amyloid）"],"answer":1,"image":""},{"id":"md2-110-1-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"110年第1次第78題","year":110,"session":1,"number":78,"question":"關於全身性紅斑性狼瘡（systemic lupus erythematosus），下列敘述何者正確？","options":["(A) 腎絲球病變主要是因為對抗腎絲球基底膜（basement membrane）自體抗體的產生","(B) 急性血管炎併有血管壁出現類纖維蛋白性壞死（fibrinoid necrosis）為典型的病變之一","(C) 在皮膚組織裡，自體抗體最主要沉積在鱗狀上皮細胞膜周圍，這是引起水泡的主因","(D) 紅色鐵絲環構造形成（wire-loop formation）是膜性病變型狼瘡腎絲球腎炎（membranous lupus glomerulonephritis）的典型變化之一"],"answer":1,"image":""},{"id":"md2-110-1-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"110年第1次第79題","year":110,"session":1,"number":79,"question":"鏈球菌感染較少引起下列那一個病變？","options":["(A) 大葉性肺炎","(B) 壞死性腸炎","(C) 猩紅熱","(D) 腎小球腎炎"],"answer":1,"image":""},{"id":"md2-110-1-80","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"110年第1次第80題","year":110,"session":1,"number":80,"question":"黃麴毒素（aflatoxin B1）之致癌機制，主要是造成下列何者之基因突變？","options":["(A) MYC","(B) RAS","(C) RB","(D) TP53"],"answer":3,"image":""},{"id":"md2-110-1-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"110年第1次第81題","year":110,"session":1,"number":81,"question":"下列何者為最常於造血系統惡性腫瘤活化致癌基因之染色體核型改變（karyotypic change）？","options":["(A) Translocation","(B) Deletion","(C) Gene amplification","(D) Aneuploidy"],"answer":0,"image":""},{"id":"md2-110-1-82","subject":"md2","topic":"病理-呼吸消化","meta":"110年第1次第82題","year":110,"session":1,"number":82,"question":"一個過去身體健康的成年病人，因為呼吸困難求醫，醫師發現病人有明顯的胸水（pleural effusion），抽出的胸水呈現乳白色混濁樣，胸水經生化檢查分析含有高濃度的三酸甘油脂（triglyceride），下列何者是造成病人胸水的最可能原因？","options":["(A) 心臟衰竭","(B) 淋巴管阻塞","(C) 肺梗塞（lung infarct）","(D) 下腔靜脈阻塞"],"answer":1,"image":""},{"id":"md2-110-1-83","subject":"md2","topic":"病理-心血管血液","meta":"110年第1次第83題","year":110,"session":1,"number":83,"question":"70歲女性，心臟超音波檢查發現二尖瓣出現鈣化的現象，心臟科醫師認為與退化有關，下列有關此病變的敘述何者錯誤？","options":["(A) 鈣化最容易出現在二尖瓣連合處（commissure of mitral valve）","(B) 通常沒有瓣膜功能的異常","(C) 感染性心內膜炎（infectious endocarditis）的風險增加","(D) 引起血栓（thrombus）的機會增加"],"answer":0,"image":""},{"id":"md2-110-1-84","subject":"md2","topic":"病理-心血管血液","meta":"110年第1次第84題","year":110,"session":1,"number":84,"question":"有關慢性免疫性血小板減少性紫斑症（chronic immune thrombocytopenic purpura）的敘述，下列何者正確？","options":["(A) 好發於60歲以上的老年女性","(B) 病人血漿中有對抗血小板的自體抗體","(C) 骨髓切片可見巨核細胞（megakaryocytes）顯著減少","(D) 多數病人對醣皮質類固醇（glucocorticoid）治療缺乏反應"],"answer":1,"image":""},{"id":"md2-110-1-85","subject":"md2","topic":"病理-心血管血液","meta":"110年第1次第85題","year":110,"session":1,"number":85,"question":"有關慢性淋巴球性白血病（chronic lymphocytic leukemia）的敘述，下列何者正確？","options":["(A) 是一種T淋巴球的惡性腫瘤","(B) 好發於20歲以下的兒童及年輕人","(C) 典型腫瘤細胞會表現CD20、CD5及CD23","(D) 大多數腫瘤會有BCL2基因的轉位，造成BCL2的過度表現"],"answer":2,"image":""},{"id":"md2-110-1-86","subject":"md2","topic":"病理-呼吸消化","meta":"110年第1次第86題","year":110,"session":1,"number":86,"question":"關於鼻咽上皮細胞癌的敘述，下列何者正確？","options":["(A) 世界衛生組織依其組織形態，主要分為角化型鱗狀上皮細胞癌、非角化型上皮細胞癌、分化不良型腺癌三種","(B) 利用EBER-1原位雜交法，偵測病理切片中腫瘤細胞核內含有Epstein-Barr病毒的DNA，是目前主要用來病理診斷鼻咽上皮細胞癌的主要工具之一","(C) 一般認為病人預後與組織形態型別無關","(D) 角化型鱗狀上皮細胞癌對放射治療的反應較非角化型的腫瘤差"],"answer":3,"image":""},{"id":"md2-110-1-87","subject":"md2","topic":"病理-呼吸消化","meta":"110年第1次第87題","year":110,"session":1,"number":87,"question":"破壞肺泡壁彈性纖維（elastin）而造成肺氣腫（emphysema）的蛋白酶主要來自：","options":["(A) 嗜中性白血球","(B) 淋巴球","(C) 嗜酸性白血球","(D) 嗜鹼性白血球"],"answer":0,"image":""},{"id":"md2-110-1-88","subject":"md2","topic":"病理-呼吸消化","meta":"110年第1次第88題","year":110,"session":1,"number":88,"question":"原發性纖毛運動障礙（primary ciliary dyskinesia）較常引起下列何種肺部疾病？","options":["(A) 慢性支氣管炎","(B) 支氣管擴張","(C) 氣喘","(D) 肺氣腫"],"answer":[0,1],"image":"","answer_note":"更正:第88題答Ａ、Ｂ給分。"},{"id":"md2-110-1-89","subject":"md2","topic":"病毒學","meta":"110年第1次第89題","year":110,"session":1,"number":89,"question":"下列那一種肝炎病毒為去氧核醣核酸病毒（DNA virus）？","options":["(A) A型肝炎病毒","(B) B型肝炎病毒","(C) C型肝炎病毒","(D) D型肝炎病毒"],"answer":1,"image":""},{"id":"md2-110-1-90","subject":"md2","topic":"病理-呼吸消化","meta":"110年第1次第90題","year":110,"session":1,"number":90,"question":"關於偽膜性腸炎（pseudomembranous colitis）的描述，下列何者錯誤？","options":["(A) 與抗生素使用有關","(B) 它通常是由艱難梭菌（Clostridium difficile）引起的","(C) 在顯微鏡下，pseudomembrane由破壞的腺體、黏蛋白和許多嗜中性白血球組成","(D) 通常需要細菌培養來做診斷"],"answer":3,"image":""},{"id":"md2-110-1-91","subject":"md2","topic":"病理-呼吸消化","meta":"110年第1次第91題","year":110,"session":1,"number":91,"question":"以下關於胃癌的敘述何者錯誤？","options":["(A) 胃癌的發病率有地域上的差異，在日本的發生率比北美高","(B) 家族性胃癌與腫瘤抑制基因CDH1的突變有密切相關","(C) 瀰漫性型胃癌（diffuse gastric cancer）較腸型胃癌（intestinal type gastric cancer）和幽門桿菌有密切相關","(D) IL-1β，TNF，IL-10，IL-8和TLR4的基因變異與幽門桿菌胃炎相關的胃癌風險升高有關"],"answer":2,"image":""},{"id":"md2-110-1-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第1次第92題","year":110,"session":1,"number":92,"question":"外因性之皮質醇增多症，腎上腺最有可能的病理變化為：","options":["(A) 皮質萎縮","(B) 瀰漫性增生","(C) 微結節性增生","(D) 巨結節性增生"],"answer":0,"image":""},{"id":"md2-110-1-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第1次第93題","year":110,"session":1,"number":93,"question":"黃色肉芽腫性腎盂腎炎（xanthogranulomatous pyelonephritis）最常見的致病菌為：","options":["(A) 變形桿菌（Proteus）","(B) 糞鏈球菌（Streptococcus faecalis）","(C) 克雷白氏桿菌（Klebsiella）","(D) 金黃色葡萄球菌（Staphylococcus aureus）"],"answer":0,"image":""},{"id":"md2-110-1-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第1次第94題","year":110,"session":1,"number":94,"question":"甲狀腺髓質癌（medullary carcinoma）其腫瘤細胞的來源為何？在腫瘤細胞之間常可見到何種變化？","options":["(A) 甲狀腺C細胞（C-cell）；砂樣小體（psammoma bodies）","(B) 甲狀腺C細胞（C-cell）；類澱粉沉積（amyloid deposits）","(C) 甲狀腺濾泡細胞（follicular cell）；砂樣小體（psammoma bodies）","(D) 甲狀腺濾泡細胞（follicular cell）；類澱粉沉積（amyloid deposits）"],"answer":1,"image":""},{"id":"md2-110-1-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第1次第95題","year":110,"session":1,"number":95,"question":"下列有關卵巢性索間質瘤（sex cord stromal tumor）的敘述，何者較不正確？","options":["(A) 成人型顆粒細胞瘤（adult granulosa cell tumor）的臨床表現為良性腫瘤","(B) 成人型顆粒細胞瘤（adult granulosa cell tumor）可能會分泌動情激素（estrogen），而與增生性乳房疾病（proliferative breast disease）、子宮內膜增生（endometrial hyperplasia）等相關","(C) 支持間質細胞瘤（Sertoli-Leydig cell tumor）通常具有荷爾蒙功能性（functional），導致男性化（masculinization）或去女性化（defeminization）","(D) 一半以上的支持間質細胞瘤（Sertoli-Leydig cell tumor）病例，其腫瘤細胞具有DICER1基因的突變"],"answer":0,"image":""},{"id":"md2-110-1-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第1次第96題","year":110,"session":1,"number":96,"question":"下列有關睪丸（testis）與附睪（epididymis）發炎的敘述，何者較不正確？","options":["(A) 附睪（epididymis）發炎比睪丸（testis）發炎更常見","(B) 因結核病（tuberculosis）引起的發炎，最先起於睪丸","(C) 因淋病（gonorrhea）引起的發炎，最先起於附睪","(D) 因梅毒（syphilis）引起的發炎，最先起於睪丸"],"answer":1,"image":""},{"id":"md2-110-1-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第1次第97題","year":110,"session":1,"number":97,"question":"下列睪丸腫瘤，何者最常見於三歲以下的小孩？","options":["(A) 精細胞瘤（seminoma）","(B) 卵黃囊瘤（yolk sac tumor）","(C) 絨毛癌（choriocarcinoma）","(D) 胚胎癌（embryonal carcinoma）"],"answer":1,"image":""},{"id":"md2-110-1-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"110年第1次第98題","year":110,"session":1,"number":98,"question":"下列有關骨肉瘤（osteosarcoma）的描述何者錯誤？","options":["(A) 大多數的low-grade osteosarcoma因第12對染色體之12q13-q15 amplification，致使MYC蛋白過度表現","(B) 原發性骨肉瘤（primary osteosarcoma）好發於10～20歲青少年","(C) 李–佛美尼症候群（Li-Fraumeni syndrome）患者，因帶有germ-line TP53 gene mutations，故罹患骨肉瘤的發生率較一般人為高","(D) 骨肉瘤之病理診斷主要依據是在切片上確切觀察到惡性細胞能產生類骨組織（osteoid）"],"answer":0,"image":""},{"id":"md2-110-1-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"110年第1次第99題","year":110,"session":1,"number":99,"question":"下列何者是阿茲海默症（Alzheimer disease）患者大腦主要的病理變化？①neuritic plaque ②neurofibrillary tangle ③nemaline rods ④Lewy body","options":["(A) ①②","(B) ①③","(C) ②③","(D) ②④"],"answer":0,"image":""},{"id":"md2-110-1-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"110年第1次第100題","year":110,"session":1,"number":100,"question":"下列何項描述較不可能在第一型單純疱疹病毒腦炎被觀察到？","options":["(A) Cowdry type A intranuclear inclusion","(B) perivascular lymphocytic cuff","(C) microglial nodule","(D) caseous necrotizing granuloma"],"answer":3,"image":""},{"id":"md2-110-2-1","subject":"md2","topic":"細菌學","meta":"110年第2次第1題","year":110,"session":2,"number":1,"question":"患者經電腦斷層掃描發現肝膿瘍（liver abscesses），從膿瘍處培養出一株厭氧性革蘭氏陰性菌，具多形性（pleomorphic）的形態，此菌會產生一種外毒素（exotoxin）屬於鋅螯合蛋白酶（Zinc metalloprotease）。最可能是下列何種菌株？","options":["(A) 痤瘡丙酸桿菌（Propionibacterium acnes）","(B) 動物雙岐桿菌（Bifidobacterium animalis）","(C) 脆弱擬桿菌（Bacteroides fragilis）","(D) 牙齦紫質單胞菌（Porphyromonas gingivalis）"],"answer":2,"image":""},{"id":"md2-110-2-2","subject":"md2","topic":"病理-免疫感染遺傳","meta":"110年第2次第2題","year":110,"session":2,"number":2,"question":"下列何種類型的痲瘋病主要會造成臉部損害變形？","options":["(A) 類結核型痲瘋病（tuberculoid leprosy）","(B) 中間型痲瘋病（intermediate leprosy）","(C) 腫瘤型痲瘋病（lepromatous leprosy）","(D) 丘疹型痲瘋病（papular leprosy）"],"answer":2,"image":""},{"id":"md2-110-2-3","subject":"md2","topic":"藥理-化學治療","meta":"110年第2次第3題","year":110,"session":2,"number":3,"question":"磺胺類藥物（sulfonamides）能選擇性抑制細菌生長，對哺乳類細胞不具有明顯毒性之原因為：","options":["(A) 哺乳類細胞無胜肽聚糖結構（peptidoglycan）","(B) 哺乳類細胞膜不含固醇（sterols）","(C) 哺乳類細胞不合成葉酸（folic acid）","(D) 哺乳類細胞具有核糖體（ribosome）"],"answer":2,"image":""},{"id":"md2-110-2-4","subject":"md2","topic":"細菌學","meta":"110年第2次第4題","year":110,"session":2,"number":4,"question":"下列有關革蘭氏陰性細菌之敘述，何者最適當？","options":["(A) 不具有胜肽聚醣（Peptidoglycan）之結構","(B) 革蘭氏染色結果呈藍色","(C) 不會產生孢子","(D) 利用有性生殖及無性生殖進行複製"],"answer":2,"image":""},{"id":"md2-110-2-5","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"110年第2次第5題","year":110,"session":2,"number":5,"question":"因突變造成序列出現停止密碼（stop codon）而提早終止蛋白質的合成稱之為：","options":["(A) 緘默突變（silent mutation）","(B) 無效突變（null mutation）","(C) 無意義突變（nonsense mutation）","(D) 錯義突變（missense mutation）"],"answer":2,"image":""},{"id":"md2-110-2-6","subject":"md2","topic":"細菌學","meta":"110年第2次第6題","year":110,"session":2,"number":6,"question":"關於斑疹傷寒（Scrub typhus）之敘述，下列何者錯誤？","options":["(A) 病原菌為Orientia tsutsugamushi","(B) 人類是透過帶菌的體蝨（body louse）叮咬致病","(C) 症狀包括頭疼、發燒、肌肉疼痛、皮疹等","(D) doxycycline為治療的首選藥物"],"answer":1,"image":""},{"id":"md2-110-2-7","subject":"md2","topic":"細菌學","meta":"110年第2次第7題","year":110,"session":2,"number":7,"question":"一位患者隔餐食用放在室溫含有雞蛋的馬鈴薯沙拉，隔天中午開始發燒、腹痛、上吐下瀉，排出的糞便不含血。下列那一株細菌是最有可能造成食物中毒的原因？","options":["(A) 痢疾志賀桿菌（Shigella dysenteriae）","(B) 產生志賀毒素的大腸桿菌（Shiga toxin-producing Escherichia coli）","(C) 霍亂弧菌（Vibrio cholerae）","(D) 傷寒沙門氏桿菌（Salmonella Typhi）"],"answer":3,"image":""},{"id":"md2-110-2-8","subject":"md2","topic":"細菌學","meta":"110年第2次第8題","year":110,"session":2,"number":8,"question":"下列何種革蘭氏陽性絕對厭氧菌會造成婦女陰道感染？","options":["(A) 無乳鏈球菌（Streptococcus agalactiae）","(B) 動彎桿菌（Mobiluncus curtisii）","(C) 鬆脆類桿菌（Bacteroides fragilis）","(D) 白色念珠菌（Candida albicans）"],"answer":1,"image":""},{"id":"md2-110-2-9","subject":"md2","topic":"細菌學","meta":"110年第2次第9題","year":110,"session":2,"number":9,"question":"下列有關肉毒桿菌毒素（botulinum toxin）之敘述，何者最適當？","options":["(A) 作用於神經細胞","(B) 造成痙攣性癱瘓（spastic paralysis）","(C) 耐熱性毒素（heat-resistant toxin）","(D) 為革蘭氏陰性菌分泌之外毒素（exotoxin）"],"answer":0,"image":""},{"id":"md2-110-2-10","subject":"md2","topic":"病毒學","meta":"110年第2次第10題","year":110,"session":2,"number":10,"question":"以細胞學方式鑑定病毒，下列何種病毒感染細胞後會引發細胞融合（syncytia）並形成巨大細胞？","options":["(A) 腸病毒（enterovirus）","(B) 登革病毒（dengue virus）","(C) 人類免疫缺失病毒（human immunodeficiency virus）","(D) 狂犬病病毒（rabies virus）"],"answer":[2,3],"image":"","answer_note":"更正:第10題答Ｃ、Ｄ給分"},{"id":"md2-110-2-11","subject":"md2","topic":"病毒學","meta":"110年第2次第11題","year":110,"session":2,"number":11,"question":"下列何種病毒感染最容易引起嬰兒先天性白內障（congenital cataract）之病徵？","options":["(A) 單純疱疹病毒（herpes simplex virus）","(B) 腸病毒（enterovirus）","(C) 腺病毒（adenovirus）","(D) 德國麻疹病毒（rubella virus）"],"answer":3,"image":""},{"id":"md2-110-2-12","subject":"md2","topic":"病毒學","meta":"110年第2次第12題","year":110,"session":2,"number":12,"question":"下列病毒，那幾種最可能經由性行為感染？①肝炎病毒A型（HAV） ②單純疱疹病毒（herpes simplex virus） ③茲卡病毒（Zika virus） ④麻疹病毒（measles virus）","options":["(A) ①②","(B) ②③","(C) ③④","(D) ①③"],"answer":[0,1,3],"image":"","answer_note":"更正:第12題答Ａ、Ｂ、Ｄ給分"},{"id":"md2-110-2-13","subject":"md2","topic":"藥理-化學治療","meta":"110年第2次第13題","year":110,"session":2,"number":13,"question":"目前對愛滋病的治療用藥不包含下列何種類型的藥物？","options":["(A) Reverse transcriptase inhibitor","(B) Protease inhibitor","(C) Integrase inhibitor","(D) Neuraminidase inhibitor"],"answer":3,"image":""},{"id":"md2-110-2-14","subject":"md2","topic":"病毒學","meta":"110年第2次第14題","year":110,"session":2,"number":14,"question":"下列有關副黏液病毒（paramyxovirus）的敘述，何者最適當？","options":["(A) 病毒基因體（genome）即是mRNA，可以被直接轉譯成蛋白質","(B) 病毒顆粒中並未包裹RNA聚合酶（RNA polymerase）","(C) 病毒感染後引發細胞融合（syncytium）","(D) 在病毒複製過程中，所有病毒蛋白的產量是一致的"],"answer":2,"image":""},{"id":"md2-110-2-15","subject":"md2","topic":"病毒學","meta":"110年第2次第15題","year":110,"session":2,"number":15,"question":"下列何種病毒不屬於小RNA病毒科（Picornaviridae）？","options":["(A) A型肝炎病毒（hepatitis A virus）","(B) 腸病毒（enterovirus）","(C) 鼻病毒（rhinovirus）","(D) 冠狀病毒（coronavirus）"],"answer":3,"image":""},{"id":"md2-110-2-16","subject":"md2","topic":"病毒學","meta":"110年第2次第16題","year":110,"session":2,"number":16,"question":"下列有關絲狀病毒（filovirus）的敘述，何者正確？","options":["(A) 病毒可經由蝙蝠及猴子感染人類，也可以人傳人","(B) 2018年的伊波拉（Ebola）病毒大流行發生在海地","(C) 病毒基因為正股(+)RNA","(D) 伊波拉（Ebola）病毒的顆粒是子彈型"],"answer":0,"image":""},{"id":"md2-110-2-17","subject":"md2","topic":"真菌學","meta":"110年第2次第17題","year":110,"session":2,"number":17,"question":"關於格特隱球菌（Cryptococcus gattii）之敘述，下列何者錯誤？","options":["(A) 為具有莢膜（capsule）的酵母菌","(B) 主要的環境棲地（habitat）為尤加利樹（Eucalyptus tree）","(C) 較常感染健全免疫（immunocompetent）的患者","(D) 造成的臨床神經學症狀較輕微"],"answer":3,"image":""},{"id":"md2-110-2-18","subject":"md2","topic":"免疫學","meta":"110年第2次第18題","year":110,"session":2,"number":18,"question":"有關補體系統（complement system）的敘述，下列何者錯誤？","options":["(A) 補體系統是諾貝爾獎得主Jules Bordet在血清中所發現一種對熱不穩定而且具有殺菌功能的物質","(B) 補體系統所包含30幾種血漿蛋白主要由脾臟產生。平常這些蛋白以活化狀態存在，一旦有病原菌入侵可立即反應","(C) 補體系統可以經由傳統途徑（classical pathway）、替代途徑（alternative pathway）或凝集素（lectin pathway）來啟動一系列蛋白酶的反應","(D) 補體活化後的產物可具備調理作用（opsonization）、趨化作用（chemotaxis）、促進吞噬作用及發炎反應"],"answer":1,"image":""},{"id":"md2-110-2-19","subject":"md2","topic":"免疫學","meta":"110年第2次第19題","year":110,"session":2,"number":19,"question":"下列關於MHC class I的敘述何者錯誤？","options":["(A) MHC class I的功能主要為呈獻內源性抗原，並激活CD8 T淋巴細胞","(B) MHC class I比MHC class II呈獻較長的胜肽（約13～17個胺基酸）","(C) MHC class I輕鏈為β2-microglobulin","(D) MHC class I主要的胜肽接合處位於α1與α2 domain"],"answer":1,"image":""},{"id":"md2-110-2-20","subject":"md2","topic":"免疫學","meta":"110年第2次第20題","year":110,"session":2,"number":20,"question":"V(D)J重組的過程有許多蛋白參與，下列有關這些蛋白和其功能的敘述何者錯誤？","options":["(A) RAG-1和RAG-2：辨識recombination signal sequences（RSS）之後產生DNA斷裂","(B) DNA ligase IV和XRCC4：連結DNA的斷裂點","(C) Artemis：具有nuclease activity可以打開DNA hairpin結構，產生P-nucleotide","(D) TdT：和Ku蛋白結合後，可以標記DNA的斷裂點或異常的結構"],"answer":3,"image":""},{"id":"md2-110-2-21","subject":"md2","topic":"免疫學","meta":"110年第2次第21題","year":110,"session":2,"number":21,"question":"利用免疫檢查點，細胞毒素的T淋巴細胞關聯蛋白質4（CTLA-4, CD152）可藉由競爭何種T淋巴細胞活化路徑，達到免疫抑制，而有助腫瘤細胞免疫逃脫？","options":["(A) CD28 - B7.1","(B) OX40 - OX40 ligand","(C) CD8 - MHC class I","(D) LFA-1- ICAM-1"],"answer":0,"image":""},{"id":"md2-110-2-22","subject":"md2","topic":"免疫學","meta":"110年第2次第22題","year":110,"session":2,"number":22,"question":"下列何種細胞激素並非由TH2細胞（TH2 cell）所分泌？","options":["(A) IL-4","(B) IL-5","(C) IL-12","(D) IL-13"],"answer":2,"image":""},{"id":"md2-110-2-23","subject":"md2","topic":"免疫學","meta":"110年第2次第23題","year":110,"session":2,"number":23,"question":"下列有關B細胞活化的敘述，何者錯誤？","options":["(A) 胸腺依賴型（thymus-dependent）抗原是蛋白質，在和BCR結合後經由胞吞作用分解成peptides抗原呈獻給T細胞，活化T細胞表現CD19 ligand結合到B細胞，傳遞第二訊號來促進B細胞的完全活化","(B) LPS為thymus-independent抗原，可以在缺乏T細胞的小鼠中刺激B細胞活化及細胞分裂，也可促進漿細胞分化，分泌IgM抗體","(C) B型嗜血桿菌（Haemophilus influenza, type b）疫苗的組成包含細菌的莢膜多醣體結合載體蛋白（carrier proteins），莢膜多醣體由B細胞辨識，T細胞辨識蛋白質部分，但遺傳性免疫缺失疾病Wiskott-Aldrich syndrome病人因為T細胞和B細胞交互作用有問題，導致B細胞無法順利分化成漿細胞，因此抗莢膜多醣體的專一性抗體產量很低，無法達到保護效果","(D) B型嗜血桿菌（Haemophilus influenza, type b）疫苗的組成包含細菌的莢膜多醣體結合載體蛋白（carrier proteins），這樣的設計是因為莢膜多醣體為thymus-independent抗原，單獨使用無法刺激良好的免疫反應"],"answer":0,"image":""},{"id":"md2-110-2-24","subject":"md2","topic":"免疫學","meta":"110年第2次第24題","year":110,"session":2,"number":24,"question":"疫苗的開發大幅度減少了感染症對人類的威脅，有關疫苗的敘述何者最不適當？","options":["(A) 疫苗有減毒疫苗（attenuated vaccine）及非活性疫苗（killed vaccine）。雖然減毒疫苗的效果較好，它的風險也比較大","(B) 不論任何途徑給與疫苗都不會影響免疫反應的效果，因此大多數的疫苗都是用肌肉注射的方式","(C) 通常有效的疫苗都會引起抗體反應去阻止病原的入侵或是中和毒素的作用","(D) 以蛋白或胜肽為主的疫苗（protein or peptide-based vaccine）通常需要佐劑（adjuvant）去加強免疫反應，而佐劑的作用主要是活化先天免疫反應"],"answer":1,"image":""},{"id":"md2-110-2-25","subject":"md2","topic":"免疫學","meta":"110年第2次第25題","year":110,"session":2,"number":25,"question":"關於臺灣重要過敏原之敘述，下列何者正確？","options":["(A) 貓狗等寵物產生的過敏原屬於此類","(B) 在乾燥高溫的環境裡容易滋長","(C) 節肢動物的排泄物是重要的過敏原","(D) 致敏生物的體型微小，需要電子顯微鏡才可以看見"],"answer":[0,2],"image":"","answer_note":"更正:第25題答Ａ、Ｃ給分"},{"id":"md2-110-2-26","subject":"md2","topic":"免疫學","meta":"110年第2次第26題","year":110,"session":2,"number":26,"question":"下列何種自體免疫疾病最不可能因母親的自體抗體經由穿過胎盤導致新生兒產生相關疾病？","options":["(A) Graves' disease","(B) Ｍyasthenia gravis","(C) thrombocytopenic purpura","(D) type 1 DM（diabetes mellitus）"],"answer":3,"image":""},{"id":"md2-110-2-27","subject":"md2","topic":"免疫學","meta":"110年第2次第27題","year":110,"session":2,"number":27,"question":"2018年諾貝爾獎頒給開發以CTLA-4及PD-1分子為基礎的癌症免疫治療學者。阻斷個體內CTLA-4及PD-1分子的作用對於腫瘤細胞的主要影響是：","options":["(A) 抑制了間質細胞及自然殺手細胞的作用，而增加腫瘤細胞的生長及移轉","(B) 抑制腫瘤內B淋巴球的磷酸酶活性，而增加腫瘤細胞的生長及移轉","(C) 經由抑制淋巴球活化時的負性調控作用，增加抗腫瘤T淋巴球的活性，進而殺死腫瘤細胞","(D) 經由活化含有ITIMs（immunoreceptor tyrosine-based inhibitory motifs）結構的分子作用，抑制腫瘤細胞的生長及分化"],"answer":2,"image":""},{"id":"md2-110-2-28","subject":"md2","topic":"免疫學","meta":"110年第2次第28題","year":110,"session":2,"number":28,"question":"移植物對抗宿主病（graft-versus-host disease）最常發生在：","options":["(A) 造血幹細胞移植（hematopoietic stem cell transplantation）","(B) 腎移植（kidney transplantation）","(C) 肝移植（liver transplantation）","(D) 心臟移植（heart transplantation）"],"answer":0,"image":""},{"id":"md2-110-2-29","subject":"md2","topic":"寄生蟲學","meta":"110年第2次第29題","year":110,"session":2,"number":29,"question":"關於蟠尾絲蟲（Onchocerca volvulus）的敘述，下列何者錯誤？","options":["(A) 微絲蟲會侵犯患者眼睛造成失明","(B) 自皮膚切片（skin snips）發現微絲蟲為主要診斷方法","(C) 患者可能出現鼠蹊懸垂（hanging groin）","(D) 患者常會出現肺部結節（pulmonary nodules）"],"answer":3,"image":""},{"id":"md2-110-2-30","subject":"md2","topic":"寄生蟲學","meta":"110年第2次第30題","year":110,"session":2,"number":30,"question":"下列何者不適用於旋毛蟲（Trichinella spiralis）感染的診斷？","options":["(A) 檢查患者糞便中之蟲卵","(B) 特異性抗體檢查","(C) 臨床症狀","(D) 骨骼肌切片檢查（biopsy of skeletal muscle）"],"answer":0,"image":""},{"id":"md2-110-2-31","subject":"md2","topic":"寄生蟲學","meta":"110年第2次第31題","year":110,"session":2,"number":31,"question":"下列何種寄生蟲的幼蟲可以在人體小腸絨毛內發育，並完成生活史？","options":["(A) 短小包膜絛蟲（Hymenolepis nana）","(B) 豬肉絛蟲（Taenia solium）","(C) 多房性包生絛蟲（Echinococcus multilocularis）","(D) 曼森裂頭絛蟲（Spirometra mansonoides）"],"answer":0,"image":""},{"id":"md2-110-2-32","subject":"md2","topic":"寄生蟲學","meta":"110年第2次第32題","year":110,"session":2,"number":32,"question":"有關瘧原蟲（Plasmodium spp.）生活史與形態的敘述，下列何者正確？","options":["(A) 人體內裂殖子（merozoite）會轉變成為大 ／小配子母細胞（macro- / micro-gametocyte）","(B) 大 ／小配子母細胞受精後，會被瘧蚊攝入體內，變成卵動子（ookinete），進行減數分裂後，產生孢子體（sporozoite）","(C) 造成復發的主因是因為孢子體進入肝臟細胞後，轉變成為休眠之裂殖生殖期（schizogony）所致","(D) 瘧色素（hemozoin）是一種含鐵的蛋白質，係由瘧原蟲產生，主要原料源自於宿主的乳鐵蛋白（lactoferrin）"],"answer":0,"image":""},{"id":"md2-110-2-33","subject":"md2","topic":"寄生蟲學","meta":"110年第2次第33題","year":110,"session":2,"number":33,"question":"有關隱孢子蟲症（cryptosporidiosis）的敘述，下列何者正確？","options":["(A) 患者有嚴重腹瀉，並伴隨乳糜瀉（celiac disease）發生","(B) 蟲體會入侵小腸的肌肉層（muscularis）進行兩次無性生殖，待孢子成熟後再入侵上皮細胞的刷狀緣（brush border）發育","(C) 愛滋病患常見的伺機性（opportunistic）寄生蟲感染症之一","(D) 發育中的卵囊為紡錘形，未成熟卵囊只見一個孢子母細胞（sporoblast），會在體外繼續發育為兩個孢子細胞（sporocyst）"],"answer":2,"image":""},{"id":"md2-110-2-34","subject":"md2","topic":"寄生蟲學","meta":"110年第2次第34題","year":110,"session":2,"number":34,"question":"白蛉（sandfly）為下列何種人類寄生蟲病之主要傳播病媒？","options":["(A) 黑水熱（blackwater fever）","(B) 黑死病（black death）","(C) 黑熱病（kala-azar）","(D) 斷骨熱（breakbone fever）"],"answer":2,"image":""},{"id":"md2-110-2-35","subject":"md2","topic":"寄生蟲學","meta":"110年第2次第35題","year":110,"session":2,"number":35,"question":"下列何者為傳播人巴貝氏原蟲症（human babesiosis）之主要病媒？","options":["(A) 革蜱屬（Dermacentor spp.）","(B) 硬蜱屬（Ixodes spp.）","(C) 花蜱屬（Amblyomma spp.）","(D) 血蜱屬（Haemaphysalis spp.）"],"answer":1,"image":""},{"id":"md2-110-2-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"110年第2次第36題","year":110,"session":2,"number":36,"question":"為檢定機器人輔助式（robot-assisted）手術與傳統手術於術後發生併發症之關聯，收集10位接受機器人輔助式手術及12位進行傳統手術病人的資料，兩種手術發生術後併發症人數分別為1、2人。應該採用下列何者統計方法分析最恰當？","options":["(A) 簡單線性迴歸（Simple linear regression）","(B) 對數等級檢定（Log rank test）","(C) 卡方檢定（Chi-square test）","(D) 費雪精確檢定（Fisher exact test）"],"answer":3,"image":""},{"id":"md2-110-2-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"110年第2次第37題","year":110,"session":2,"number":37,"question":"下列何種流行病學研究設計屬於雙向研究法？","options":["(A) 橫斷研究（cross-sectional study）","(B) 世代研究（cohort study）","(C) 病例對照研究（case-control study）","(D) 巢疊病例對照研究（nested case-control study）"],"answer":3,"image":""},{"id":"md2-110-2-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"110年第2次第38題","year":110,"session":2,"number":38,"question":"某分析流行病學研究在選取暴露組與非暴露組的研究對象時針對性別、年齡、居住地以及收案時間等變項進行匹配（matching），使這些變項在暴露組與非暴露組的分布相近。進行匹配的最主要目的為何？","options":["(A) 避免干擾","(B) 增加樣本的異質性","(C) 提高研究結果的外推性","(D) 降低樣本的不回應率"],"answer":0,"image":""},{"id":"md2-110-2-39","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"110年第2次第39題","year":110,"session":2,"number":39,"question":"有關環境毒物對人體產生效應，下列敘述何者最不恰當？","options":["(A) 如人體長時間暴露在高溫、高濕度環境，會造成皮膚對毒性物質之吸收量增加","(B) 人體對環境毒性物質的易感受性，一般而言，小孩高於成人","(C) 鉛的慢性暴露會使近端腎小管表皮細胞之核內產生含鉛包含體，引起糖尿、蛋白尿","(D) 鉛暴露在人體的半衰期約為200天"],"answer":[2,3],"image":"","answer_note":"更正:第39題答Ｃ、Ｄ給分"},{"id":"md2-110-2-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"110年第2次第40題","year":110,"session":2,"number":40,"question":"下列有關臺灣重金屬暴露危害，何者敘述最不恰當？","options":["(A) 鎘金屬因熔點低的特點，而作為銲接所用的銲料","(B) 銀樓黃金回收業者，有汞金屬暴露風險","(C) 電鍍工廠勞工發生鼻中膈穿孔的風險較高，最可能是因為硫酸暴露所引起","(D) 鉛蓄電池勞工暴露鉛危害，可能導致其所生嬰兒認知發展受損"],"answer":[1,2],"image":"","answer_note":"更正:第40題答Ｂ、Ｃ給分"},{"id":"md2-110-2-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"110年第2次第41題","year":110,"session":2,"number":41,"question":"下列何者不屬於職業安全衛生或事故傷害預防中的3E介入策略？","options":["(A) 教育（education）","(B) 工程（engineering）","(C) 執法（enforcement）","(D) 賦權（empowerment）"],"answer":3,"image":""},{"id":"md2-110-2-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"110年第2次第42題","year":110,"session":2,"number":42,"question":"夏日時，世界上大多數主要城市常深受光化煙霧（photochemical smog）之害。下列那一項污染物常被認為是其主要原因？","options":["(A) SO2","(B) PM2.5","(C) O3","(D) Pb"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第42題一律給分。 (原公告答案 C)"},{"id":"md2-110-2-43","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"110年第2次第43題","year":110,"session":2,"number":43,"question":"關於當前重要公共衛生倫理議題的敘述，下列何者最不恰當？","options":["(A) 在高齡化、少子化的人口結構下，存在「世代公平」（intergenerational equity）的公共衛生倫理問題","(B) 吸菸（smoking）是自主性行為，不存在公共衛生倫理的問題","(C) 氣候變遷（climate change）產生新的致病機轉，存在公共衛生倫理的問題","(D) 疫苗（vaccination）施打是預防疾病傳播的重要措施，存在公共衛生倫理的問題"],"answer":1,"image":""},{"id":"md2-110-2-44","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"110年第2次第44題","year":110,"session":2,"number":44,"question":"在應用社會學習理論設計糖尿病病人衛生教育，提升病人飲食習慣改變的自覺能力，下列何項策略最不恰當？","options":["(A) 提供其他糖尿病病人的成功經驗","(B) 提供知名偶像飲食習慣改變的經驗","(C) 強化病人飲食習慣改變的正向經驗","(D) 與主要照顧者溝通，改變病人的飲食"],"answer":3,"image":""},{"id":"md2-110-2-45","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"110年第2次第45題","year":110,"session":2,"number":45,"question":"創新擴散（diffusion of innovation）已被應用在公共衛生的許多健康議題上，是指社會體系的成員之間經過某種管道相互傳遞「創新的」訊息。關於提高「創新」成功的機會，下列敘述何者最不恰當？","options":["(A) 具有高度彈性（flexibility）","(B) 具有高度可逆性（reversibility）","(C) 具有高度複雜性（complexity）","(D) 與所處的社會經濟或價值體系具有相容性（compatibility）"],"answer":2,"image":""},{"id":"md2-110-2-46","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"110年第2次第46題","year":110,"session":2,"number":46,"question":"醫療糾紛指醫病之間因為醫療傷害所生之責任歸屬的爭執，而醫療傷害可區分為「因過失引起之醫療傷害」和「非因過失引起之醫療傷害」。下列何者為「非因過失引起之醫療傷害」？","options":["(A) 醫師診斷錯誤以致延誤病情","(B) 手術併發症","(C) 護理人員打錯針劑","(D) 院內感染管控之疏失"],"answer":1,"image":""},{"id":"md2-110-2-47","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"110年第2次第47題","year":110,"session":2,"number":47,"question":"關於藥事法對於藥物及藥品的敘述，下列何者最不恰當？","options":["(A) 藥事法中對於藥品定義，其中之一款為載於中華藥典或經中央衛生主管機關認定之其他各國藥典、公定之國家處方集或各該補充典籍之藥品","(B) 所含有效成分之質、量或強度，與核准不符者稱為劣藥","(C) 藥事法中藥物之定義，不包括醫療器材","(D) 標明成藥許可證字號的藥品不須經過醫師指示，即供治療疾病之用"],"answer":2,"image":""},{"id":"md2-110-2-48","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"110年第2次第48題","year":110,"session":2,"number":48,"question":"健康轉型期（health transition）或流行病學轉型（epidemiological transition）包含四個階段：①大流行及飢荒期（the age of pestilence and famine） ②流行減退期（the age of receding pandemics） ③延後退化期（the age of delayed degenerative diseases）④退化及人為疾病期（the age of degenerative and man-made diseases）。其先後順序何者正確？","options":["(A) ①②③④","(B) ①②④③","(C) ①④③②","(D) ①④②③"],"answer":1,"image":""},{"id":"md2-110-2-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"110年第2次第49題","year":110,"session":2,"number":49,"question":"醫療支出成長快速的主要因素不包括下列何項？","options":["(A) 醫療科技快速發展","(B) 醫療糾紛事件的增加","(C) 民眾對健保的期望與日俱增","(D) 人口老化"],"answer":1,"image":""},{"id":"md2-110-2-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"110年第2次第50題","year":110,"session":2,"number":50,"question":"有關長期照護的敘述，下列何者最不恰當？","options":["(A) 服務對象為因慢性傷病或老衰導致身心功能障礙者","(B) 目的在促進或維持身體功能，增進獨立自主的正常生活能力","(C) 是急性醫療照護的延伸，只能由醫療專業人員提供服務","(D) 日常生活活動照顧（如準備食物、清潔、交通接送等）屬長期照護的服務範疇"],"answer":2,"image":""},{"id":"md2-110-2-51","subject":"md2","topic":"藥理-化學治療","meta":"110年第2次第51題","year":110,"session":2,"number":51,"question":"下列何種藥物在蠶豆症（glucose-6-phosphate dehydrogenase deficiency）患者中使用，可能會導致溶血？","options":["(A) simvastatin","(B) rasburicase","(C) clopidogrel","(D) carbamazepine"],"answer":1,"image":""},{"id":"md2-110-2-52","subject":"md2","topic":"藥理-化學治療","meta":"110年第2次第52題","year":110,"session":2,"number":52,"question":"關於抗疱疹病毒藥acyclovir之敘述，下列何者正確？","options":["(A) 可有效作用在潛伏期病毒","(B) 此藥物須經由病毒特定胸苷激酶（virus-specified thymidine kinase）將其磷酸化才具活性","(C) 抗藥性的發生可因為病毒中的DNA聚合酶產生變異，與病人免疫功能低下無關","(D) 對acyclovir產生抗藥性時，替代藥物valacyclovir會比trifluridine適合"],"answer":1,"image":""},{"id":"md2-110-2-53","subject":"md2","topic":"藥理-化學治療","meta":"110年第2次第53題","year":110,"session":2,"number":53,"question":"有關抗巨細胞病毒（cytomegalovirus, CMV）感染使用的藥物，下列敘述何者錯誤？","options":["(A) ganciclovir抗CMV的活性遠高於acyclovir","(B) foscarnet不僅能抑制疱疹病毒中的DNA聚合酶與RNA聚合酶，也能抑制HIV反轉錄酶","(C) cidofovir、foscarnet、ganciclovir皆需要經由磷酸化才能進一步產生作用","(D) cidofovir不適合與NSAID藥物併用，主要考量是因為腎毒性的副作用"],"answer":2,"image":""},{"id":"md2-110-2-54","subject":"md2","topic":"藥理-化學治療","meta":"110年第2次第54題","year":110,"session":2,"number":54,"question":"關於抑制細菌蛋白質合成類的抗生素應用，下列敘述何者正確？","options":["(A) clindamycin可抑制細菌蛋白質合成，並可治療大部分的革蘭氏陰性好氧菌感染","(B) clindamycin能與cephalosporin併用治療骨盆膿瘍及敗血性流產","(C) quinupristin-dalfopristin可用於治療革蘭氏陽性菌與具內源性抗藥性之糞腸球菌（E faecalis）感染","(D) tedizolid可用於治療革蘭氏陽性菌感染，但對於抗藥性金黃葡萄球菌（methicillin-resistant S aureus）無治療效益"],"answer":1,"image":""},{"id":"md2-110-2-55","subject":"md2","topic":"藥理-化學治療","meta":"110年第2次第55題","year":110,"session":2,"number":55,"question":"有關抗代謝（antimetabolites）抗癌藥物之敘述，下列何者錯誤？","options":["(A) methotrexate應避免與非類固醇消炎藥物合用，以免影響methotrexate的吸收","(B) pemetrexed主要作用是抑制胸苷酸合成酶（thymidylate synthase），並可使用vitamin B12以減輕毒性","(C) cytarabine（ara-C）主要作用是抑制DNA聚合酶α（DNA polymerase-α）與DNA聚合酶β（DNA polymerase- β），不適用於治療實質固態瘤（solid tumor）","(D) allopurinol會經由抑制黃嘌呤氧化酶（xanthine oxidase）而導致6-mercaptopurine過多毒性（excessive toxicity）產生，因此選用6-thioguanine可避免上述問題"],"answer":0,"image":""},{"id":"md2-110-2-56","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第2次第56題","year":110,"session":2,"number":56,"question":"2019年底爆發的新型冠狀病毒感染，患者為逃避發燒篩檢隔離而服用ibuprofen。此藥物主要作用於腦部減少何種自泌素（autacoids）的生成？","options":["(A) PGD2","(B) PGF2","(C) PGE2","(D) PGI2"],"answer":2,"image":""},{"id":"md2-110-2-57","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第2次第57題","year":110,"session":2,"number":57,"question":"關於多發性硬化症（multiple sclerosis）用藥fingolimod hydrochloride之敘述，下列何者錯誤？","options":["(A) 主要透過影響S1P受體而發揮作用","(B) 促進淋巴細胞由淋巴結釋放至循環系統","(C) 可減少淋巴細胞在腦部的數量","(D) 可導致嚴重的心臟毒性"],"answer":1,"image":""},{"id":"md2-110-2-58","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"110年第2次第58題","year":110,"session":2,"number":58,"question":"臨床上針對血小板缺乏症（thrombocytopenia），目前有血小板生成素（thrombopoietin）相關藥物可加以運用，下列敘述何者錯誤？","options":["(A) romiplostim及eltrombopag均為G-CSF受體致效劑","(B) 口服eltrombopag適用於初期干擾素治療且患有血小板缺乏症的C肝病人","(C) eltrombopag可能有嚴重肝毒性，須進行病況監控","(D) thrombopoietin及interleukin-11均為內生性血小板生成之調節成分"],"answer":0,"image":""},{"id":"md2-110-2-59","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"110年第2次第59題","year":110,"session":2,"number":59,"question":"下列何者適用於改善腎衰竭導致的貧血？","options":["(A) erythropoietin","(B) azathioprine","(C) coumarin","(D) zidovudine"],"answer":0,"image":""},{"id":"md2-110-2-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第2次第60題","year":110,"session":2,"number":60,"question":"下列何種狀況比較不適合用生長激素（growth hormone/somatotropin）治療？","options":["(A) 肢端肥大症（acromegaly）","(B) 小胖威利症候群（Prader-Willi syndrome）","(C) 透納氏症候群（Turner syndrome）","(D) 生長激素缺乏症（growth hormone deficiency）"],"answer":0,"image":""},{"id":"md2-110-2-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第2次第61題","year":110,"session":2,"number":61,"question":"下列何種藥物主要透過抑制蝕骨細胞（osteoclast）的活性，達到降血鈣與增加骨密度的效果？","options":["(A) sucralfate","(B) acetaminophen","(C) warfarin","(D) alendronate"],"answer":3,"image":""},{"id":"md2-110-2-62","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第2次第62題","year":110,"session":2,"number":62,"question":"55歲婦人經乳房X光攝影發現有腫瘤，醫生進行乳房腫瘤切除手術，病理切片分析顯示此腫瘤有estrogen和progesterone的受體。下列何者較適合用來治療婦人的乳房腫瘤？","options":["(A) flutamide","(B) mifepristone","(C) tamoxifen","(D) danazol"],"answer":2,"image":""},{"id":"md2-110-2-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"110年第2次第63題","year":110,"session":2,"number":63,"question":"下列何者為neprilysin抑制劑，因而增加atrial natriuretic peptide（ANP）和brain natriuretic peptide（BNP）的作用，可用於治療心衰竭疾病？","options":["(A) flunarizine","(B) nesiritide","(C) ranolazine","(D) sacubitril"],"answer":3,"image":""},{"id":"md2-110-2-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"110年第2次第64題","year":110,"session":2,"number":64,"question":"下列那一種藥物，因藥效短而最適用於手術期間（或急性）引起之心律不整？","options":["(A) esmolol","(B) dofetilide","(C) propafenone","(D) dronedarone"],"answer":0,"image":""},{"id":"md2-110-2-65","subject":"md2","topic":"藥理-總論與自主神經","meta":"110年第2次第65題","year":110,"session":2,"number":65,"question":"下列有關mirabegron的敘述，何者正確？","options":["(A) 是一種選擇性beta-3交感受體拮抗劑（beta-3 adrenoceptor antagonist）","(B) 可使尿道括約肌（urethral sphincter）舒張","(C) 臨床上可用於改善膀胱過動（overactive bladder）症狀","(D) 其主要副作用為低血壓（hypotension）"],"answer":2,"image":""},{"id":"md2-110-2-66","subject":"md2","topic":"藥理-總論與自主神經","meta":"110年第2次第66題","year":110,"session":2,"number":66,"question":"下列何者活化菸鹼性受體（nicotinic receptor）的作用最弱，且最不易被膽鹼酯酶（cholinesterase）分解？","options":["(A) acetylcholine","(B) methacholine","(C) carbachol","(D) bethanechol"],"answer":3,"image":""},{"id":"md2-110-2-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第2次第67題","year":110,"session":2,"number":67,"question":"下列何者不是ipratropium治療氣喘的主要作用？","options":["(A) 減少呼吸道黏液分泌","(B) 鬆弛支氣管平滑肌","(C) 抑制細胞激素（cytokines）和趨化素（chemokines）生合成","(D) 拮抗乙醯膽鹼（acetylcholine）作用"],"answer":2,"image":""},{"id":"md2-110-2-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第2次第68題","year":110,"session":2,"number":68,"question":"下列有關misoprostol藥理性質之敘述，何者正確？","options":["(A) 是prostaglandin I2的結構類似物","(B) 口服可被迅速吸收，其代謝產物具有藥理活性","(C) 血中半衰期（half-life）長達20小時","(D) 只能抑制胃酸分泌，沒有胃黏膜保護作用"],"answer":1,"image":""},{"id":"md2-110-2-69","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"110年第2次第69題","year":110,"session":2,"number":69,"question":"下列何種藥物是急性嚴重偏頭痛發作時的第一線用藥，但患者如果有冠狀動脈疾病則禁止使用？","options":["(A) lorcaserin","(B) aspirin","(C) phentermine","(D) sumatriptan"],"answer":3,"image":""},{"id":"md2-110-2-70","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"110年第2次第70題","year":110,"session":2,"number":70,"question":"下列何種藥物最適合用來治療肺高壓（pulmonary hypertension）？","options":["(A) latanoprost","(B) zileuton","(C) iloprost","(D) dinoprostone"],"answer":2,"image":""},{"id":"md2-110-2-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"110年第2次第71題","year":110,"session":2,"number":71,"question":"下列何者是新型的降尿酸藥物，用於治療難治性慢性痛風（refractory chronic gout）的病人？","options":["(A) pegloticase","(B) ketorolac","(C) tramadol","(D) anakinra"],"answer":0,"image":""},{"id":"md2-110-2-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"110年第2次第72題","year":110,"session":2,"number":72,"question":"Morphine在治療劑量下除具止痛效果外還有其他藥理作用，但不包括下列何者？","options":["(A) 瞳孔擴大","(B) 抑制咳嗽","(C) 減緩腸道蠕動","(D) 鎮靜作用"],"answer":0,"image":""},{"id":"md2-110-2-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"110年第2次第73題","year":110,"session":2,"number":73,"question":"吸入性麻醉劑的血液氣體分配係數（blood：gas partition coefficient）數值越大時，其代表涵義下列何者正確？","options":["(A) 藥物起始作用（onset）快、恢復（recovery）快","(B) 藥物起始作用（onset）慢、恢復（recovery）快","(C) 藥物起始作用（onset）快、恢復（recovery）慢","(D) 藥物起始作用（onset）慢、恢復（recovery）慢"],"answer":3,"image":""},{"id":"md2-110-2-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"110年第2次第74題","year":110,"session":2,"number":74,"question":"下列那個藥物的化學結構與amphetamine類似，可抑制norepinephrine和dopamine的再回收，除用於憂鬱症的治療外，亦做為戒菸的輔助治療藥物？","options":["(A) bupropion","(B) imipramine","(C) trazodone","(D) fluoxetine"],"answer":0,"image":""},{"id":"md2-110-2-75","subject":"md2","topic":"藥理-化學治療","meta":"110年第2次第75題","year":110,"session":2,"number":75,"question":"下列何種解毒劑，主要作用是螯合單價重金屬離子，並促進其與重金屬形成之複合物自腸道排出？","options":["(A) penicillamine","(B) prussian blue","(C) succimer","(D) deferoxamine"],"answer":1,"image":""},{"id":"md2-110-2-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"110年第2次第76題","year":110,"session":2,"number":76,"question":"炎症反應中所釋出的組織胺（histamine），與下列何者最有關？","options":["(A) 白血球黏附至血管內皮細胞（endothelium）","(B) 白血球在血管內皮細胞（endothelium）上滾動","(C) 血管擴張及其滲透性增加","(D) 血管收縮及促進血小板凝聚"],"answer":2,"image":""},{"id":"md2-110-2-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"110年第2次第77題","year":110,"session":2,"number":77,"question":"細胞發生不可逆變化，與下列何種現象最有關？","options":["(A) 細胞內鈉（sodium）增加","(B) 細胞核碎裂（karyorrhexis）","(C) 細胞內pH值降低","(D) 細胞膜出現水泡（bleb）"],"answer":1,"image":""},{"id":"md2-110-2-78","subject":"md2","topic":"免疫學","meta":"110年第2次第78題","year":110,"session":2,"number":78,"question":"全血丙型干擾素檢驗（interferon-gamma release assay）可用來診斷潛伏肺結核菌感染。此檢驗主要運用的原理，是在高特異性的結核菌抗原刺激下，血液中的何種細胞被活化後產生丙型干擾素？","options":["(A) T淋巴細胞","(B) B淋巴細胞","(C) 單核球","(D) 嗜中性白血球"],"answer":0,"image":""},{"id":"md2-110-2-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"110年第2次第79題","year":110,"session":2,"number":79,"question":"下列各項梅毒期別與病變的組合中，那一個組合正確？","options":["(A) 第一期梅毒及下疳（chancre）","(B) 第二期梅毒及脊髓癆（tabes dorsalis）","(C) 第三期梅毒及Hutchinson齒","(D) 先天性梅毒及扁平濕疣（condyloma latum）"],"answer":0,"image":""},{"id":"md2-110-2-80","subject":"md2","topic":"病理-呼吸消化","meta":"110年第2次第80題","year":110,"session":2,"number":80,"question":"因為缺乏菸鹼素（niacin）所引起之臨床症狀，下列何者較不常見？","options":["(A) 憩室炎（diverticulitis）","(B) 失智（dementia）","(C) 皮膚炎（dermatitis）","(D) 腹瀉（diarrhea）"],"answer":0,"image":""},{"id":"md2-110-2-81","subject":"md2","topic":"病理-心血管血液","meta":"110年第2次第81題","year":110,"session":2,"number":81,"question":"一個病人表現黃疸、中風、意識模糊與腹痛，血液檢查顯示血小板低下與碎裂的紅血球（schistocytes），凝血酶原時間（prothrombin time）與部分凝血活酶時間（partial thromboplastin time）正常，經過血漿置換術（plasma exchange）之後，病人的病情獲得改善，下列何者是最可能的解釋？","options":["(A) 血漿置換術可以清除攻擊ADAMTS13的抗體與補充ADAMTS13","(B) 血漿置換術用以清除攻擊von Willebrand factor的抗體與補充von Willebrand factor","(C) 診斷是瀰漫性血管內凝血（disseminated intravascular coagulation）","(D) 診斷是A型血友病（hemophilia A）"],"answer":0,"image":""},{"id":"md2-110-2-82","subject":"md2","topic":"病理-心血管血液","meta":"110年第2次第82題","year":110,"session":2,"number":82,"question":"一個長期抽菸的60歲男性，他有高血壓與糖尿病但沒有接受治療，某日他在吃飯時突然失去意識，30分鐘後救護人員到達時他已經死亡，法醫初步認為他是心臟猝死（sudden cardiac death），心臟猝死最常見的法醫檢查結果為何？","options":["(A) 冠狀動脈疾病","(B) 心室壁破裂","(C) 心肌炎","(D) 肺動脈高壓"],"answer":0,"image":""},{"id":"md2-110-2-83","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第2次第83題","year":110,"session":2,"number":83,"question":"下列何者最不常見腎臟細動脈玻璃樣增厚（hyaline thickening of the walls of arterioles）？","options":["(A) 老年人","(B) 長期高血壓病人","(C) 糖尿病病人","(D) 年輕病人患有腎上腺嗜鉻細胞瘤"],"answer":3,"image":""},{"id":"md2-110-2-84","subject":"md2","topic":"病理-心血管血液","meta":"110年第2次第84題","year":110,"session":2,"number":84,"question":"下列何種維生素缺乏，最可能導致巨母紅血球性貧血（megaloblastic anemia）？","options":["(A) 維生素B1","(B) 維生素B2","(C) 維生素B6","(D) 維生素B12"],"answer":3,"image":""},{"id":"md2-110-2-85","subject":"md2","topic":"病理-心血管血液","meta":"110年第2次第85題","year":110,"session":2,"number":85,"question":"99 40歲女性在懷孕末期時出現血小板數目低下（24×10/L，參考值156-369×10/L）的情形。病人在輸完血小板後立即接受剖腹生產，生產後有輕微溶血性貧血。病人於是接受血漿置換術，但情況並無改善。流式細胞儀分析（flow cytometry）顯示病人紅血球偵測不到CD55與CD59。下列何種基因異常最可能導致此病人的情況？","options":["(A) c-KIT","(B) PIGA","(C) MPL","(D) JAK2"],"answer":1,"image":""},{"id":"md2-110-2-86","subject":"md2","topic":"病理-呼吸消化","meta":"110年第2次第86題","year":110,"session":2,"number":86,"question":"下列何者不是引起肺高血壓（pulmonary hypertension）的主要原因？","options":["(A) 慢性阻塞性肺病","(B) 慢性間質性肺病","(C) 反覆發生肺部血栓栓塞（thromboembolism）","(D) 心臟三尖瓣狹窄"],"answer":3,"image":""},{"id":"md2-110-2-87","subject":"md2","topic":"病理-呼吸消化","meta":"110年第2次第87題","year":110,"session":2,"number":87,"question":"下列有關間皮瘤（mesothelioma）的敘述，何者錯誤？","options":["(A) 間皮瘤大多數發生在大量接觸石棉的人","(B) 從開始接觸石棉到發生間皮瘤的潛伏期可以長達數十年","(C) Amphiboles比chrysotiles型的石棉更易造成間皮瘤","(D) 大部分間皮瘤的腫瘤組織可發現石棉小體（asbestos body）的存在"],"answer":3,"image":""},{"id":"md2-110-2-88","subject":"md2","topic":"病理-呼吸消化","meta":"110年第2次第88題","year":110,"session":2,"number":88,"question":"肺部有一局部圓形病灶，中間形成空腔，且含有濃稠黃色液體，外圍有約0.6 mm厚的纖維壁。其診斷最可能為：","options":["(A) 肺炎","(B) 肺癌","(C) 肺結核","(D) 肺膿瘍"],"answer":3,"image":""},{"id":"md2-110-2-89","subject":"md2","topic":"病理-呼吸消化","meta":"110年第2次第89題","year":110,"session":2,"number":89,"question":"關於威爾森氏症（Wilson disease），下列何者錯誤？","options":["(A) 通常發生於6歲到40歲之間","(B) 血清ceruloplasmin下降","(C) 常伴隨基底核病變","(D) ATP8A基因突變"],"answer":3,"image":""},{"id":"md2-110-2-90","subject":"md2","topic":"病理-呼吸消化","meta":"110年第2次第90題","year":110,"session":2,"number":90,"question":"關於遺傳性血鐵沉著症（hemochromatosis），下列何者錯誤？","options":["(A) 可導致肝硬化及增加肝癌風險","(B) 可造成糖尿病（diabetes）及心臟病變","(C) 最常發病於兒童時期","(D) 最常見為HFE基因變異"],"answer":2,"image":""},{"id":"md2-110-2-91","subject":"md2","topic":"病理-呼吸消化","meta":"110年第2次第91題","year":110,"session":2,"number":91,"question":"關於原發性膽汁肝硬化（primary biliary cirrhosis），下列何者錯誤？","options":["(A) 其特徵為肝內膽管破壞，洋蔥皮樣的膽管纖維化（onion skin fibrosis）為其病理特徵","(B) 病理切片下可見膽小管增生（ductular reaction）及膽管消失（loss of small bile ducts）","(C) 常發生於中年婦女","(D) 常伴隨Sjögren syndrome，甲狀腺炎（thyroiditis）及scleroderma"],"answer":0,"image":""},{"id":"md2-110-2-92","subject":"md2","topic":"病理-呼吸消化","meta":"110年第2次第92題","year":110,"session":2,"number":92,"question":"作為預測胰臟內分泌腫瘤良惡性的判定指標，以下何者最不準確？","options":["(A) 腫瘤細胞的轉移","(B) 血管的侵犯","(C) 向周遭組織浸潤性生長","(D) 腫瘤細胞呈現多形性"],"answer":3,"image":""},{"id":"md2-110-2-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第2次第93題","year":110,"session":2,"number":93,"question":"以下何者最不可能是糖尿病引起的腎病變？","options":["(A) 結節性腎小球硬化症（nodular glomerulosclerosis）","(B) 微細管間腎小球硬化症（intercapillary glomerulosclerosis）","(C) 瀰漫性腎間質硬化症（diffuse mesangial sclerosis）","(D) 特發性局灶節段性腎小球硬化症（idiopathic focal segmental glomerulosclerosis）"],"answer":3,"image":""},{"id":"md2-110-2-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第2次第94題","year":110,"session":2,"number":94,"question":"依腎細胞癌最常見的侵犯及散播途徑，以下何者的管腔最不可能出現腫瘤細胞團塊？","options":["(A) 腎靜脈","(B) 腎動脈","(C) 下腔靜脈","(D) 右心房"],"answer":1,"image":""},{"id":"md2-110-2-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第2次第95題","year":110,"session":2,"number":95,"question":"下列有關外陰部鱗狀上皮癌（squamous cell carcinoma）的敘述，何者較不正確？","options":["(A) 主要可以分為兩群：角化性（keratinizing）與類基底性及疣狀（basaloid and warty）","(B) 角化性鱗狀上皮癌較常發生在長期罹患硬化性苔蘚（lichen sclerosus）或鱗狀上皮增殖（squamous cell hyperplasia）的病人","(C) 角化性鱗狀上皮癌的前驅病灶（precursor lesion）為分化型外陰上皮內瘤變（differentiated vulvar intraepithelial neoplasia），與高危險性人類乳突狀病毒（high-risk human papillomavirus）的感染高度相關","(D) 類基底性及疣狀（basaloid and warty）鱗狀上皮癌發生的比例較角化性鱗狀上皮癌為低"],"answer":2,"image":""},{"id":"md2-110-2-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第2次第96題","year":110,"session":2,"number":96,"question":"下列有關胎盤滋養層細胞腫瘤（placental site trophoblastic tumor, PSTT）的敘述，何者較不正確？","options":["(A) 為絨毛外（extravillous）中間滋養層細胞（intermediate trophoblastic cells）的腫瘤性增生（neoplastic proliferation）","(B) 絨毛外（extravillous）中間滋養層細胞（intermediate trophoblastic cells）會分泌人類胎盤催乳素（human placental lactogen, HPL）","(C) 這一類患者，血液中的人類絨毛膜性腺激素（human chorionic gonadotropin, hCG）會升高","(D) 此腫瘤患者有50%以上的死亡率"],"answer":3,"image":""},{"id":"md2-110-2-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"110年第2次第97題","year":110,"session":2,"number":97,"question":"30歲男性，最近三個月來覺得右側陰囊漸漸變大有下墜感，但不會有疼痛現象。圖為他睪丸切除手術標本的顯微鏡下變化。下列何者是最可能的診斷？","options":["(A) 精細胞瘤（seminoma）","(B) 畸胎瘤（teratoma）","(C) 結核病（tuberculosis）","(D) 卵黃囊瘤（yolk sac tumor）"],"answer":0,"image":"md2-110-2-97.jpeg"},{"id":"md2-110-2-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"110年第2次第98題","year":110,"session":2,"number":98,"question":"一名眼球癆（phthisis bulbi）的患者做了眼球摘除送病理檢查，則該病患應是：","options":["(A) 眼球的末期病變","(B) 先天性的小眼睛","(C) 葡萄腫（staphyloma）","(D) 巨大的眼球腫瘤"],"answer":0,"image":""},{"id":"md2-110-2-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"110年第2次第99題","year":110,"session":2,"number":99,"question":"高血壓性腦出血的病人，腦部常見何種血管變化？","options":["(A) Charcot-Bouchard微小動脈瘤","(B) 漿果樣動脈瘤（berry aneurysm）","(C) 類澱粉血管病（amyloid angiopathy）","(D) 中膜缺損（medial defect）"],"answer":0,"image":""},{"id":"md2-110-2-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"110年第2次第100題","year":110,"session":2,"number":100,"question":"病人35歲，長有腦瘤（如圖），顯微鏡下觀察很像釉胚（enamel organ）長出的腫瘤。其診斷應是：","options":["(A) 多形性神經芽細胞瘤（glioblastoma multiforme）","(B) 聽神經瘤（acoustic neuroma）","(C) 顱咽管瘤（craniopharyngioma）","(D) 髓芽細胞瘤（medulloblastoma）"],"answer":2,"image":"md2-110-2-100.jpeg"},{"id":"md2-111-1-1","subject":"md2","topic":"細菌學","meta":"111年第1次第1題","year":111,"session":1,"number":1,"question":"下列何者不是分枝桿菌屬（Mycobacterium）細菌的特點？","options":["(A) 細胞壁具有分枝桿菌酸（mycolic acid）","(B) 生長速度較大腸桿菌緩慢","(C) 可以使用抗酸性染色法（acid fast stain）染色觀察","(D) 染色體G+C的比例（GC ratio）較低"],"answer":3,"image":""},{"id":"md2-111-1-2","subject":"md2","topic":"細菌學","meta":"111年第1次第2題","year":111,"session":1,"number":2,"question":"培養下列何種微生物只能在含氮氣的操作箱中操作，或以厭氧系統培養才可生長？","options":["(A) 仙人掌桿菌（Bacillus cereus）","(B) 破傷風桿菌（Clostridium tetani）","(C) 金黃色葡萄球菌（Staphylococcus aureus）","(D) 李斯特菌（Listeria monocytogenes）"],"answer":1,"image":""},{"id":"md2-111-1-3","subject":"md2","topic":"細菌學","meta":"111年第1次第3題","year":111,"session":1,"number":3,"question":"白喉桿菌（Corynebacterium diphtheriae）的白喉毒素的B次單元與宿主細胞接受器結合，接著A次單元進入細胞，與細胞的那一個蛋白質結合，進而抑制蛋白質合成？","options":["(A) 核糖體（Ribosome）40S次單元（subunit）","(B) 核糖體（Ribosome）60S次單元（subunit）","(C) 延長因子（Elongation factor）-2（EF-2）","(D) 延長因子（Elongation factor）-3（EF-3）"],"answer":2,"image":""},{"id":"md2-111-1-4","subject":"md2","topic":"藥理-化學治療","meta":"111年第1次第4題","year":111,"session":1,"number":4,"question":"下列何種抗生素不是經由抑制細菌蛋白質生合成，達到抑制細菌生長或殺菌之作用？","options":["(A) 卡納黴素（kanamycin）","(B) 克林黴素（clindamycin）","(C) 硝基甲嘧唑乙醇（metronidazole）","(D) 四環素（tetracycline）"],"answer":2,"image":""},{"id":"md2-111-1-5","subject":"md2","topic":"細菌學","meta":"111年第1次第5題","year":111,"session":1,"number":5,"question":"下列何種生物細胞之細胞膜不含固醇（sterols）？","options":["(A) 哺乳類動物","(B) 結核分枝桿菌（Mycobacterium tuberculosis）","(C) 肺炎黴漿菌（Mycoplasma pneumoniae）","(D) 黴菌（Fungus）"],"answer":1,"image":""},{"id":"md2-111-1-6","subject":"md2","topic":"細菌學","meta":"111年第1次第6題","year":111,"session":1,"number":6,"question":"遊走性紅斑（erythema migrans）是何種微生物感染的特殊皮膚表現？","options":["(A) Coxiella burnetii","(B) Leptospira interrogans","(C) Rickettsia rickettsii","(D) Borrelia burgdorferi"],"answer":3,"image":""},{"id":"md2-111-1-7","subject":"md2","topic":"細菌學","meta":"111年第1次第7題","year":111,"session":1,"number":7,"question":"下列何菌較常感染免疫缺陷的病人，會在組織上形成生物膜，具有高度抗藥性，可存活在膽鹽及高鹽環境？","options":["(A) 肺炎鏈球菌（Streptococcus pneumoniae）","(B) 化膿鏈球菌（Streptococcus pyogenes）","(C) 轉糖鏈球菌（Streptococcus mutans）","(D) 糞腸球菌（Enterococcus faecalis）"],"answer":3,"image":""},{"id":"md2-111-1-8","subject":"md2","topic":"細菌學","meta":"111年第1次第8題","year":111,"session":1,"number":8,"question":"關於無乳鏈球菌（Streptococus agalactiae）的敘述，下列何者錯誤？","options":["(A) 屬於A群的鏈球菌","(B) 具有Christie, Atkins, Much-Petersen（CAMP）測試陽性的特性","(C) 通常會無症狀的聚落生長在腸胃道或者生殖泌尿道","(D) 會引起新生兒腦膜炎及肺炎"],"answer":0,"image":""},{"id":"md2-111-1-9","subject":"md2","topic":"細菌學","meta":"111年第1次第9題","year":111,"session":1,"number":9,"question":"有關嗜肺退伍軍人桿菌（Legionella pneumophila）的敘述，下列何者錯誤？","options":["(A) 此菌於自然界可生存於阿米巴原蟲（amebae）體內","(B) 此菌培養時需添加L-cysteine與iron","(C) 宿主對此菌之免疫力主要藉由抗莢膜之抗體","(D) 使用抗生素macrolides或fluoroquinolones治療其感染症"],"answer":2,"image":""},{"id":"md2-111-1-10","subject":"md2","topic":"免疫學","meta":"111年第1次第10題","year":111,"session":1,"number":10,"question":"病毒感染寄主會引發免疫致病性（immunopathogenesis），下列何項因子最有可能造成第四型過敏及發炎反應（type IV hypersensitivity and inflammation）？","options":["(A) 病毒抗體","(B) 干擾素","(C) 多形核白血球（polymorphonuclear leukocyte）","(D) 細胞激素（cytokine）"],"answer":[1,2,3],"image":"","answer_note":"更正:第10題，答Ｂ或Ｃ或Ｄ或BC或BD或CD或BCD者均給分"},{"id":"md2-111-1-11","subject":"md2","topic":"病毒學","meta":"111年第1次第11題","year":111,"session":1,"number":11,"question":"下列何種細胞不是愛滋病毒（HIV）主要感染的對象？","options":["(A) CD4 T細胞","(B) 嗜中性白血球（neutrophil）","(C) 巨噬細胞（macrophage）","(D) 樹突細胞（dendritic cells）"],"answer":1,"image":""},{"id":"md2-111-1-12","subject":"md2","topic":"藥理-化學治療","meta":"111年第1次第12題","year":111,"session":1,"number":12,"question":"新型抗流感病毒藥物紓伏效（baloxavir marboxil）抑制對象為何？","options":["(A) PB2","(B) M2","(C) HA","(D) NA"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第12題，一律給分 (原公告答案 A)"},{"id":"md2-111-1-13","subject":"md2","topic":"病毒學","meta":"111年第1次第13題","year":111,"session":1,"number":13,"question":"有關疱疹病毒（Herpesvirus）與其相關疾病之配對，下列何者錯誤？","options":["(A) 單純疱疹病毒一型（HSV-1）：疱疹性腦炎（herpes encephalitis）","(B) EB病毒（Epstein-Barr virus）：單核球增多症（mononucleosis）","(C) 水痘病毒（VZV）：帶狀疱疹","(D) 人類疱疹病毒六型（HHV-6）：疱疹性咽峽炎（herpangina）"],"answer":3,"image":""},{"id":"md2-111-1-14","subject":"md2","topic":"病毒學","meta":"111年第1次第14題","year":111,"session":1,"number":14,"question":"有關伊波拉病毒（Ebola virus）的敘述，下列何者錯誤？","options":["(A) 病毒穩定，主要透過腸胃道傳染","(B) 病毒可以感染內皮細胞、單核球（monocyte）和其它細胞，並快速複製，造成多種細胞壞死","(C) 病毒感染細胞之後，會引起細胞激素風暴（cytokine storm）","(D) 病毒感染內皮細胞之後，使細胞失去附著性，導致血管通透性增加，造成內出血"],"answer":0,"image":""},{"id":"md2-111-1-15","subject":"md2","topic":"病毒學","meta":"111年第1次第15題","year":111,"session":1,"number":15,"question":"有關登革病毒（dengue virus）的敘述，下列何者正確？","options":["(A) 無法以乙醚或氯仿去其活性（inactivate）","(B) 與C型肝炎病毒同屬於黃病毒科（Flaviviridae）","(C) 可以血球凝集抑制實驗，區分四種登革病毒型別","(D) 臨床上已有抗登革熱藥物可供使用"],"answer":1,"image":""},{"id":"md2-111-1-16","subject":"md2","topic":"真菌學","meta":"111年第1次第16題","year":111,"session":1,"number":16,"question":"下列何種藥物的作用機轉為阻斷真菌微小管（microtubule）？","options":["(A) itraconazole","(B) griseofulvin","(C) nystatin","(D) terbinafine"],"answer":1,"image":""},{"id":"md2-111-1-17","subject":"md2","topic":"真菌學","meta":"111年第1次第17題","year":111,"session":1,"number":17,"question":"新型隱球菌（Cryptococcus neoformans）在何種培養基生長時菌落呈咖啡色，可藉以和其它不產色的酵母菌區分？","options":["(A) buffered charcoal yeast extract agar","(B) CHROMagar","(C) cornmeal agar","(D) niger seed agar"],"answer":3,"image":""},{"id":"md2-111-1-18","subject":"md2","topic":"免疫學","meta":"111年第1次第18題","year":111,"session":1,"number":18,"question":"對於免疫系統消滅病原體的描述何者錯誤？","options":["(A) 自然殺手細胞（natural killer cell）可藉由抗原特異性受體直接辨識抗原並清除病毒","(B) 巨噬細胞（macrophage）可以吞噬細菌並利用溶酶體（lysosome）的酵素分解細菌","(C) 被活化後的補體（complement）可以結合到細菌的細胞壁上穿孔並造成細菌死亡","(D) 抗體可以阻斷病毒和細胞結合的接受器來防止病毒對細胞的感染"],"answer":0,"image":""},{"id":"md2-111-1-19","subject":"md2","topic":"免疫學","meta":"111年第1次第19題","year":111,"session":1,"number":19,"question":"濾泡輔助性T細胞（T follicular helper cells, TFH cells）主要分泌的細胞素為何？","options":["(A) IL-21","(B) IL-22","(C) IL-23","(D) IL-27"],"answer":0,"image":""},{"id":"md2-111-1-20","subject":"md2","topic":"免疫學","meta":"111年第1次第20題","year":111,"session":1,"number":20,"question":"腫瘤免疫學是研究免疫系統和癌細胞之間的交互作用，希望發現可以用來發展治療癌症的新療法。關於免疫系統和腫瘤的互動，下列那個敘述最不適當？","options":["(A) 健康人體內腫瘤細胞形成時通常可以被T細胞和自然殺手細胞辨識之後清除","(B) 傳統治療方法中有單株抗體藥物，例如rituximab或trastuzumab（Herceptin）在體內結合到癌細胞後，可以啟動補體活化或是ADCC（antibody-dependent cell-mediated cytotoxicity）來清除腫瘤細胞","(C) chimeric antigen receptor (CAR)-T療法是取出健康人的T細胞，培養並改造這些T細胞使其表現專一性對抗腫瘤的CARs，再打回癌症病人來攻擊清除腫瘤細胞","(D) checkpoint blockade療法是要干擾在T細胞上的抑制受體，利用anti-CTLA-4或anti-PD-1抗體來喚醒免疫系統的T細胞攻擊腫瘤"],"answer":2,"image":""},{"id":"md2-111-1-21","subject":"md2","topic":"免疫學","meta":"111年第1次第21題","year":111,"session":1,"number":21,"question":"腫瘤細胞會表現下列何種分子以抑制宿主免疫反應？","options":["(A) CD28","(B) PD-L1","(C) PD-1","(D) CTLA-4"],"answer":1,"image":""},{"id":"md2-111-1-22","subject":"md2","topic":"免疫學","meta":"111年第1次第22題","year":111,"session":1,"number":22,"question":"調理作用（opsonization）產生原因之一是因為吞噬細胞（phagocytic cell）表面上具有下列何種受體，以辨識附著於病菌上的調理素（opsonin）？","options":["(A) Toll-like receptors","(B) complement receptors","(C) lectin-like receptors","(D) chemokine receptors"],"answer":1,"image":""},{"id":"md2-111-1-23","subject":"md2","topic":"免疫學","meta":"111年第1次第23題","year":111,"session":1,"number":23,"question":"共濟失調微血管擴張症候群（ataxia-telangiectasia）會出現免疫系統異常，導致B細胞與T細胞數量減少。主要因為下列何種機轉所致？","options":["(A) V(D)J重組過程出現缺陷","(B) 無法產生IgM抗體","(C) MHC class I辨識產生缺陷","(D) MHC class II辨識產生缺陷"],"answer":0,"image":""},{"id":"md2-111-1-24","subject":"md2","topic":"免疫學","meta":"111年第1次第24題","year":111,"session":1,"number":24,"question":"B細胞抗原接受器的基因重組（gene rearrangement）對B細胞早期發育十分重要，有關B細胞抗原接受器也就是免疫球蛋白（immunoglobulin）的基因重組，下列敘述何者錯誤？","options":["(A) 免疫球蛋白基因重組是發生在B細胞發育的早期，而且先從重鏈基因的D和J片段開始重組，接著才是V-DJ的片段重組","(B) 免疫球蛋白基因的輕鏈先從κ輕鏈基因做V及J片段的重組，如果兩個染色體都重組失敗才會做λ輕鏈基因的重組","(C) VDJ或VJ片段重組的交接位置所做出來的蛋白剛好就是在重鏈或輕鏈CDR1、CDR2及CDR3的位置，因此這三個區域的胺基酸序列的歧異度最大，也是抗原的結合位","(D) 當第一條染色體的免疫球蛋白基因的重鏈或輕鏈基因完成重組後，第二條染色體的免疫球蛋白基因就停止重組，因此一個B細胞只會表現一種抗原受體，這種機制稱為對偶基因排除現象（allelic exclusion）"],"answer":2,"image":""},{"id":"md2-111-1-25","subject":"md2","topic":"免疫學","meta":"111年第1次第25題","year":111,"session":1,"number":25,"question":"成熟的CD4 T細胞活化後，不同轉錄因子可調控細胞分化為不同的effector T細胞，不同effector T細胞可以產出特定的細胞激素，下列轉錄因子和細胞激素的配對，那一組相關性最低？","options":["(A) GATA3：IL-4","(B) Foxp3：TGF-β","(C) RORγT：IL-12","(D) T-bet：IFN-γ"],"answer":2,"image":""},{"id":"md2-111-1-26","subject":"md2","topic":"免疫學","meta":"111年第1次第26題","year":111,"session":1,"number":26,"question":"2018年諾貝爾醫學獎得主Tasuku Honjo因為發現PD-1分子而獲獎，他另外一個著名的發現是AID（activation- induced cytidine deaminase）分子，下列有關AID的敘述何者錯誤？","options":["(A) AID在germinal center B細胞表現量高，可促進somatic hypermutation","(B) B細胞所產生的抗體轉換為IgE時，也是由AID分子調控","(C) class switch recombination（CSR）起因為AID將cytosine轉變成uridine，之後的DNA修復過程產生DNA雙股斷裂，最後造成DNA重組","(D) class switch recombination由特定的DNA序列recombination signal sequence（RSS）所主導，造成抗體重鏈的固定區（constant region of heavy chain）從IgM轉換成其他類型"],"answer":3,"image":""},{"id":"md2-111-1-27","subject":"md2","topic":"免疫學","meta":"111年第1次第27題","year":111,"session":1,"number":27,"question":"小明每年到了秋冬交換之際總會罹患流行性感冒，他很納悶去年才得到流感，為何今年又再感染，下列何者是最有可能的原因或情況？","options":["(A) 流感病毒可能潛伏在神經節裡面，每當冬天來臨時，因為免疫力的降低使得流感病毒從神經節中出來感染肺部細胞","(B) 流感病毒是RNA病毒，當病毒複製時會產生點突變，即便同型流感病毒，也會因為點突變造成抗原轉移（antigenic shift）使免疫系統無法完全辨認，讓病毒有機可乘","(C) 小明受流感病毒感染後所產生的抗原原罪（original antigenic sin）現象，造成抗體負回饋調控免疫反應，讓B細胞無法做新的抗體去對付已經變種的流感病毒，因此再度感染","(D) 只要小明每年施打流感疫苗就可以完全不會罹患流行性感冒"],"answer":2,"image":""},{"id":"md2-111-1-28","subject":"md2","topic":"免疫學","meta":"111年第1次第28題","year":111,"session":1,"number":28,"question":"T細胞與B細胞都參與氣喘或是異位性皮膚炎等過敏性疾病的病理機制，此類病人體內最常檢測到：","options":["(A) 高比例可分泌IL-5的T細胞與血清中高濃度IgA","(B) 高比例可分泌IL-5的T細胞與血清中高濃度IgE","(C) 高比例可分泌IFN-γ的T細胞與血清中高濃度IgA","(D) 高比例可分泌IFN-γ的T細胞與血清中高濃度IgE"],"answer":1,"image":""},{"id":"md2-111-1-29","subject":"md2","topic":"寄生蟲學","meta":"111年第1次第29題","year":111,"session":1,"number":29,"question":"林先生之前到中國旅遊時吃了淡水魚的生魚片，不久後出現腹痛，回國後眼眶附近浮腫，很幸運的在浮腫部位摘除將近4 mm大小的蟲體，林先生最有可能感染下列何種寄生蟲？","options":["(A) 蟠尾絲蟲（Onchocerca volvulus）","(B) 有棘頜口線蟲（Gnathostoma spinigerum）","(C) 東方眼蟲（Thelazia callipaeda）","(D) 麥地那線蟲（Dracunculus medinensis）"],"answer":1,"image":""},{"id":"md2-111-1-30","subject":"md2","topic":"寄生蟲學","meta":"111年第1次第30題","year":111,"session":1,"number":30,"question":"有關鞭蟲（Trichuris trichiura）感染人體的敘述，下列何者錯誤？","options":["(A) 幼蟲直接在腸道發育為成蟲","(B) 成蟲主要寄生在大腸","(C) 會引起自體感染（autoinfection）","(D) 幼童重度感染可能會引起脫肛（rectum prolapse）"],"answer":2,"image":""},{"id":"md2-111-1-31","subject":"md2","topic":"寄生蟲學","meta":"111年第1次第31題","year":111,"session":1,"number":31,"question":"詹先生近年來因愛好生態攝影而經常前往北歐之瑞典及芬蘭等國旅遊，期間曾多次品嚐當地之醃魚特產，日前因腹部不適及出現貧血病症而就醫，經醫院檢查發現有嚴重維他命B12缺乏，並於其空腸（jejunum）近端發現有帶狀蟲體寄生。依據以上敘述，詹先生最可能感染何種寄生蟲？","options":["(A) 中華肝吸蟲（Clonorchis sinensis）","(B) 橫川吸蟲（Metagonimus yokogawai）","(C) 廣節裂頭絛蟲（Diphyllobothrium latum）","(D) 增生性裂頭幼蟲（Sparganum proliferum）"],"answer":2,"image":""},{"id":"md2-111-1-32","subject":"md2","topic":"寄生蟲學","meta":"111年第1次第32題","year":111,"session":1,"number":32,"question":"人類感染下列何種寄生蟲，最常造成神經性囊尾幼蟲症（neurocysticercosis）？","options":["(A) 旋毛蟲（Trichinella spiralis）","(B) 牛肉絛蟲（Taenia saginata）","(C) 豬肉絛蟲（Taenia solium）","(D) 亞洲無鈎絛蟲（Taenia saginata asiatica）"],"answer":2,"image":""},{"id":"md2-111-1-33","subject":"md2","topic":"寄生蟲學","meta":"111年第1次第33題","year":111,"session":1,"number":33,"question":"下列何者為瘧疾（malaria）患者發燒週期之最可能原因？","options":["(A) 瘧原蟲入侵紅血球內，因為產生裂殖子（merozoite）而自紅血球內排出代謝產物所致","(B) 除惡性瘧原蟲（Plasmodium falciparum）外，原蟲感染的細胞狀態是同步，所以發燒會呈現週期且有規律性","(C) 間日瘧原蟲（P. vivax）感染之發燒週期一般為48小時，可能因不同次族群（sub-population）感染，造成不規則的發燒週期","(D) 相較於惡性瘧原蟲（Plasmodium falciparum），三日瘧原蟲（P. malariae）的潛伏期較間日瘧原蟲（P. vivax）為短"],"answer":2,"image":""},{"id":"md2-111-1-34","subject":"md2","topic":"寄生蟲學","meta":"111年第1次第34題","year":111,"session":1,"number":34,"question":"下列何種病症通常與杜氏利什曼原蟲（Leishmania donovani）之感染無關？","options":["(A) 腹瀉（diarrhea）","(B) 貧血（anemia）","(C) 黑水熱（blackwater fever）","(D) 肝脾腫大（hepatosplenomegaly）"],"answer":2,"image":""},{"id":"md2-111-1-35","subject":"md2","topic":"寄生蟲學","meta":"111年第1次第35題","year":111,"session":1,"number":35,"question":"下列有關鼠蚤（Xenopsylla cheopis）傳播之鼠疫（plague）敘述，何者錯誤？","options":["(A) 人類感染初期會呈現腋窩（axilla）腫大之腺鼠疫（bubonic plague）","(B) 人類感染後期呈現人傳播人之肺鼠疫（pneumonic plague）","(C) 感染性鼠蚤藉由嘔吐作用（vomiting）污染叮咬傷口而感染人類","(D) 主要致病原為鼠疫桿菌（Yersinia pestis），屬於格蘭氏陰性菌"],"answer":2,"image":""},{"id":"md2-111-1-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第1次第36題","year":111,"session":1,"number":36,"question":"如果要在顯著水準為α的情況下，利用變異數分析來檢定三組資料，下列何者最恰當？","options":["(A) 必須假設三組資料來源的三個母體的變異數皆相等","(B) 如果要利用兩兩比較的t檢定來代替變異數分析，必須將每個t檢定的顯著水準改成α/6","(C) 此變異數分析的檢定統計量會服從t分配","(D) 此變異數分析也可利用迴歸分析來取代，只要加入一個解釋變數，定義數值1、2、3代表三組，再檢定該解釋變數是否顯著即可"],"answer":0,"image":""},{"id":"md2-111-1-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第1次第37題","year":111,"session":1,"number":37,"question":"下列有關簡單線性迴歸（simple linear regression）分析中，依變項（dependent variable）Y與自變項（independent variable）X的敘述，何者最不恰當？","options":["(A) 探討的是X與Y之間是否有線性關係","(B) 依變項Y通常為常態分布","(C) 結果可以說明X與Y之間的線性因果關係","(D) 只處理單一個自變項"],"answer":2,"image":""},{"id":"md2-111-1-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第1次第38題","year":111,"session":1,"number":38,"question":"研究發現女性體脂率越高則乳癌風險越高，此發現較符合因果關係判斷的那一個條件？","options":["(A) 相關特異性（specificity）","(B) 因果時序性（temporality）","(C) 劑量效應（dose-response effect）","(D) 生物學贊同性（biologic plausibility）"],"answer":2,"image":""},{"id":"md2-111-1-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第1次第39題","year":111,"session":1,"number":39,"question":"某新興傳染病爆發後，受感染的重症患者會有嚴重肺炎、肺部纖維化甚至死亡的危險性。某郵輪的其中一位旅客發現受感染時，所有船上3,711位旅客和船員，全部皆進行船隻隔離檢疫，在屆滿14天隔離期後有621人確診，621人中重症者24人、死亡者2人。此一傳染病的病例致死率（case-fatality）為何？","options":["(A) 2/24","(B) 2/621","(C) 2/3711","(D) 2/(621-2)"],"answer":1,"image":""},{"id":"md2-111-1-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"111年第1次第40題","year":111,"session":1,"number":40,"question":"全球暖化與氣候變遷對臺灣公共衛生造成的衝擊，下列敘述何者最不恰當？","options":["(A) 可能改變病媒及病原微生物的地區生存與繁殖","(B) 在較高的氣溫下，二次空氣污染物的濃度不會增加，但大氣中的化學反應可能加速","(C) 可能改變降雨量及其分布","(D) 二次空氣污染物濃度的升高，可能會增加呼吸道及心血管疾病的住院風險"],"answer":1,"image":""},{"id":"md2-111-1-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"111年第1次第41題","year":111,"session":1,"number":41,"question":"有關UV-A、UV-B、UV-C三種室外紫外光的敘述，下列何者最不恰當？","options":["(A) UV-C能量最大，所以對地表生物傷害最大","(B) UV-A的波長最長","(C) 過度暴露於UV-B會增加皮膚癌發生的機會","(D) 平流層臭氧稀薄會導致更多紫外光進入對流層，造成對流層臭氧濃度增加"],"answer":0,"image":""},{"id":"md2-111-1-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"111年第1次第42題","year":111,"session":1,"number":42,"question":"職業環境中毒性物質進入人體的途徑，下列何者較不常見？","options":["(A) 呼吸（inhalation）","(B) 皮膚吸收（skin absorption）","(C) 食入攝取（ingestion）","(D) 滲入（infiltration）"],"answer":3,"image":""},{"id":"md2-111-1-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"111年第1次第43題","year":111,"session":1,"number":43,"question":"細懸浮微粒（PM2.5）係指粒徑小於下列何者之空氣微粒？","options":["(A) 2.5微米","(B) 2.5奈米","(C) 2.5公分","(D) 2.5公釐"],"answer":0,"image":""},{"id":"md2-111-1-44","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第1次第44題","year":111,"session":1,"number":44,"question":"社會流行病學會應用「社會資本（social capital）」及「集體效能（collective efficacy）」理論去探討群體健康的社會決定因子。若應用社會資本及集體效能理論於社會環境的理解，下列敘述何者最不恰當？","options":["(A) 非正式社會控制（informal social control）","(B) 居民的個人知識","(C) 社會凝聚力（social cohesion）","(D) 人們的互信程度"],"answer":1,"image":""},{"id":"md2-111-1-45","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第1次第45題","year":111,"session":1,"number":45,"question":"關於社會變遷對公共衛生的影響，下列敘述何者最不恰當？","options":["(A) 國民教育水準及所得大幅提升，醫療保健服務需求隨之降低","(B) 人口結構逐漸老化，醫療保健需求隨之增加","(C) 地區社會經濟發展異質性增加，衛生問題隨之複雜化","(D) 婦女就業率提高，兒童的預防保健工作須更仰賴學校或育幼機構"],"answer":0,"image":""},{"id":"md2-111-1-46","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第1次第46題","year":111,"session":1,"number":46,"question":"關於藥物濫用的預防和治療策略，下列敘述何者最不恰當？","options":["(A) 在學校對青少年只要單獨進行「知識傳遞或情感性教育」，就可以有效延遲或降低青少年使用非法藥物","(B) 從社會控制角度來預防藥物濫用，介入管道包括司法體系、運動員藥檢或反毒政策等","(C) 物質濫用的藥物治療，包括替代性藥物（如美沙冬計畫）和拮抗劑（如納曲酮naltrexone、戒酒發泡錠）等","(D) 提供藥癮者接觸乾淨針頭的管道，是從減害的觀點來降低毒品使用帶來的傷害"],"answer":0,"image":""},{"id":"md2-111-1-47","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第1次第47題","year":111,"session":1,"number":47,"question":"關於物質使用（substance use）疾患的自然史發展的敘述，下列何者最不恰當？","options":["(A) 物質使用相關疾患發展史的起始點是因為物質濫用或依賴","(B) 降低藥物或物質暴露機會可避免物質使用相關疾患","(C) 個體在物質使用疾患自然史過程發生的傷害，如物質使用過量（overdose），可透過藥物或物質可近性降低或制約情境改變而緩解","(D) 診斷物質使用疾患應考量較長時間的使用型態，而非單次的使用"],"answer":0,"image":""},{"id":"md2-111-1-48","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"111年第1次第48題","year":111,"session":1,"number":48,"question":"下列何種健康照護體系財源制度，其所得重分配與社會互助的作用最小？","options":["(A) 一般稅（general tax）","(B) 社會保險費（social insurance premium）","(C) 指定用途稅（dedicated tax）","(D) 醫療儲蓄帳戶（medical saving account）"],"answer":3,"image":""},{"id":"md2-111-1-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"111年第1次第49題","year":111,"session":1,"number":49,"question":"醫院的市場行為可視為醫院的生產決策過程，下列何者不是學者常提出來解釋醫院市場行為的模式？","options":["(A) 價值極大化（value maximization）","(B) 利潤極大化（profit maximization）","(C) 效用極大化（utility maximization）","(D) 服務量極大化（service maximization）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第49題，一律給分。。 (原公告答案 A)"},{"id":"md2-111-1-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"111年第1次第50題","year":111,"session":1,"number":50,"question":"下列活動那一項不屬於執行日常生活活動（activities of daily living, ADLs）測量項目？","options":["(A) 洗澡","(B) 穿衣","(C) 洗衣","(D) 進食"],"answer":2,"image":""},{"id":"md2-111-1-51","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"111年第1次第51題","year":111,"session":1,"number":51,"question":"下列何者是全身麻醉劑thiopental的特性？","options":["(A) 因在體內有再分布的情形，具有長效的作用","(B) 屬於速效型（rapid onset）麻醉藥","(C) 因脂溶性低不易口服吸收","(D) 會在肝臟快速代謝成有效代謝物，而延長作用時間"],"answer":1,"image":""},{"id":"md2-111-1-52","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"111年第1次第52題","year":111,"session":1,"number":52,"question":"慢性長期巴拉刈（paraquat）暴露與下列那種神經退化症最相關？","options":["(A) 帕金森氏症","(B) 阿茲海默症","(C) 肌萎縮性脊髓側索硬化症（amyotrophic lateral sclerosis）","(D) 亨丁頓舞蹈症"],"answer":0,"image":""},{"id":"md2-111-1-53","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第1次第53題","year":111,"session":1,"number":53,"question":"下列用於免疫調節及抗發炎藥物，何者的作用機轉非經由阻斷介白素（interleukin）功能？","options":["(A) canakinumab","(B) etanercept","(C) tocilizumab","(D) ustekinumab"],"answer":1,"image":""},{"id":"md2-111-1-54","subject":"md2","topic":"藥理-化學治療","meta":"111年第1次第54題","year":111,"session":1,"number":54,"question":"關於抗生素抗藥性的成因及對抗策略，下列敘述何者錯誤？","options":["(A) 對vancomycin產生抗藥性的主要因素，是失去與細菌細胞壁肽聚醣（peptidoglycan）結合的能力","(B) vancomycin合併cefotaxime可治療對penicillin產生抗藥性的肺炎鏈球菌（pneumococcus）感染","(C) telavancin可治療對vancomycin產生耐受性的革蘭氏陽性菌感染","(D) dalbavancin可治療對vancomycin產生抗藥性的腸球菌（enterococci）感染"],"answer":3,"image":""},{"id":"md2-111-1-55","subject":"md2","topic":"藥理-化學治療","meta":"111年第1次第55題","year":111,"session":1,"number":55,"question":"關於化療藥busulfan之敘述，下列何者錯誤？","options":["(A) 作用於DNA而抑制癌細胞增生與複製","(B) 與cyclophosphamide同屬於烷化劑（alkylating agent），常用於治療乳癌","(C) glutathione S-transferase活性增加時易引起抗藥性","(D) 常見副作用為噁心、嘔吐"],"answer":1,"image":""},{"id":"md2-111-1-56","subject":"md2","topic":"藥理-化學治療","meta":"111年第1次第56題","year":111,"session":1,"number":56,"question":"下列何種藥物對於細菌之dihydrofolic acid reductase具有專一性的高親和力？","options":["(A) sulfamethoxazole","(B) trimethoprim","(C) pyrimethamine","(D) methotrexate"],"answer":1,"image":""},{"id":"md2-111-1-57","subject":"md2","topic":"藥理-總論與自主神經","meta":"111年第1次第57題","year":111,"session":1,"number":57,"question":"下列藥物何者為H1拮抗劑，也適合用於緩解藥物引起的錐體外症狀（extrapyramidal symptoms）？","options":["(A) famotidine","(B) haloperidol","(C) diphenhydramine","(D) cetirizine"],"answer":2,"image":""},{"id":"md2-111-1-58","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第1次第58題","year":111,"session":1,"number":58,"question":"有關血栓溶解藥物之敘述，下列何者錯誤？","options":["(A) streptokinase比tissue plasminogen activator（t-PA）易產生過敏反應","(B) streptokinase與plasminogen形成複合物才將plasminogen轉換成plasmin","(C) plasmin可經由全身性靜脈注射有效應用於血栓溶解","(D) t-PA對結合fibrin的plasminogen有較高親和力"],"answer":2,"image":""},{"id":"md2-111-1-59","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第1次第59題","year":111,"session":1,"number":59,"question":"下列降血脂藥物何者藉由活化PPAR-α而促進細胞lipoprotein lipase（LPL）及apoA表現，以提高脂肪酸在骨骼肌及肝臟的氧化反應，進而降低血中VLDL含量？","options":["(A) gemfibrozil","(B) simvastatin","(C) colestipol","(D) ezetimibe"],"answer":0,"image":""},{"id":"md2-111-1-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第1次第60題","year":111,"session":1,"number":60,"question":"王先生因甲狀腺癌接受手術切除後，出現倦怠、嗜睡、水腫等現象。在醫院抽血檢查發現有甲狀腺機能低下（hypothyroidism）的情況，並有上呼吸道感染造成的輕微發燒與咳嗽。依據上述情形，他比較不適合使用下列那一種藥物？","options":["(A) levothyroxine","(B) dextromethorphan","(C) methimazole","(D) acetaminophen"],"answer":2,"image":""},{"id":"md2-111-1-61","subject":"md2","topic":"藥理-總論與自主神經","meta":"111年第1次第61題","year":111,"session":1,"number":61,"question":"下列何種藥物的主要作用受體不位在細胞膜上，而是在細胞內部？","options":["(A) erlotinib","(B) metoclopramide","(C) prednisolone","(D) diphenhydramine"],"answer":2,"image":""},{"id":"md2-111-1-62","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第1次第62題","year":111,"session":1,"number":62,"question":"RU-486亦即mifepristone，被用於墮胎主要是因為下列何種作用機轉？","options":["(A) 拮抗糖皮質激素受體的作用，進而使得受孕無法維持","(B) 抑制雌激素的分泌作用，進而使懷孕中止","(C) 是PGI2的拮抗劑，造成子宮早期收縮","(D) 拮抗黃體素（progesterone）的作用，進而使得受孕無法維持"],"answer":3,"image":""},{"id":"md2-111-1-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第1次第63題","year":111,"session":1,"number":63,"question":"下列有關chlorothiazide利尿劑的敘述，何者錯誤？","options":["(A) 可抑制鈉和氯離子再吸收","(B) 可用於原發性高鈣尿（idiopathic hypercalciuria）","(C) 會引起高血糖","(D) 會引起高血鉀"],"answer":3,"image":""},{"id":"md2-111-1-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第1次第64題","year":111,"session":1,"number":64,"question":"+ 下列抗心律不整藥物，何者不抑制Nachannel作用？","options":["(A) adenosine","(B) amiodarone","(C) flecainide","(D) mexiletine"],"answer":0,"image":""},{"id":"md2-111-1-65","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第1次第65題","year":111,"session":1,"number":65,"question":"下列關於nicorandil的敘述，何者錯誤？","options":["(A) 可使nitric oxide釋放","(B) 可使sodium channel打開","(C) 可降低細胞內鈣離子濃度","(D) 可用於治療心絞痛"],"answer":1,"image":""},{"id":"md2-111-1-66","subject":"md2","topic":"藥理-總論與自主神經","meta":"111年第1次第66題","year":111,"session":1,"number":66,"question":"下列交感受體拮抗劑（adrenoceptor antagonist）中，何者具有最明顯的alpha受體（alpha-receptor）阻斷作用？","options":["(A) atenolol","(B) labetalol","(C) propranolol","(D) pindolol"],"answer":1,"image":""},{"id":"md2-111-1-67","subject":"md2","topic":"藥理-總論與自主神經","meta":"111年第1次第67題","year":111,"session":1,"number":67,"question":"下列膽鹼酯酶抑制劑（cholinesterase inhibitors），何者不適合用於治療重症肌無力（myasthenia gravis）？","options":["(A) pyridostigmine","(B) physostigmine","(C) neostigmine","(D) ambenonium"],"answer":1,"image":""},{"id":"md2-111-1-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第1次第68題","year":111,"session":1,"number":68,"question":"下列何種治療氣喘藥物可與病人血中IgE形成複合體，由肝臟吞噬細胞清除？","options":["(A) mepolizumab","(B) tocilizumab","(C) omalizumab","(D) efalizumab"],"answer":2,"image":""},{"id":"md2-111-1-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第1次第69題","year":111,"session":1,"number":69,"question":"下列用於治療慢性阻塞性肺病（COPD）病人的藥物中，何者是屬於muscarinic receptor antagonists，而且是長效型？","options":["(A) atropine","(B) ipratropium","(C) tiotropium","(D) formoterol"],"answer":2,"image":""},{"id":"md2-111-1-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第1次第70題","year":111,"session":1,"number":70,"question":"下列何種抗噁心嘔吐藥物最適合用於懷孕的婦女，其作用機轉是透過拮抗H1 receptor？","options":["(A) ondansetron","(B) ranitidine","(C) tiprolisant","(D) Diclegis"],"answer":3,"image":""},{"id":"md2-111-1-71","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第1次第71題","year":111,"session":1,"number":71,"question":"患者罹患低血鈉症（hyponatremia），可以使用下列何種藥物來治療，該藥物是一選擇性V2 antagonist？","options":["(A) selepressin","(B) terlipressin","(C) conivaptan","(D) tolvaptan"],"answer":3,"image":""},{"id":"md2-111-1-72","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第1次第72題","year":111,"session":1,"number":72,"question":"下列何種藥物可以有效治療cryopyrin-associated periodic syndrome（CAPS），特別是CAPS subtype的familial cold autoinflammatory syndrome？","options":["(A) ketorolac","(B) rilonacept","(C) secukinumab","(D) tramadol"],"answer":1,"image":""},{"id":"md2-111-1-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"111年第1次第73題","year":111,"session":1,"number":73,"question":"下列那一個抗帕金森氏症藥物，不適合用於排尿不順的老年患者？","options":["(A) benztropine","(B) ropinirole","(C) selegiline","(D) levodopa"],"answer":0,"image":""},{"id":"md2-111-1-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"111年第1次第74題","year":111,"session":1,"number":74,"question":"Methadone可用於鴉片類藥物成癮的治療，關於該藥物的藥理特性，下列敘述何者正確？","options":["(A) 可以經由口服投與","(B) 沒有成癮性","(C) 為鴉片類受體的拮抗劑","(D) 不會產生戒斷症狀"],"answer":0,"image":""},{"id":"md2-111-1-75","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"111年第1次第75題","year":111,"session":1,"number":75,"question":"下列安眠藥物，何者作用迅速且半衰期最短，用於改善入睡困難？","options":["(A) zaleplon","(B) flurazepam","(C) diazepam","(D) chlordiazepoxide"],"answer":0,"image":""},{"id":"md2-111-1-76","subject":"md2","topic":"病理-免疫感染遺傳","meta":"111年第1次第76題","year":111,"session":1,"number":76,"question":"產生interleukin-17的T淋巴球缺乏，此狀況與下列何種病灶最有關？","options":["(A) 很多嗜中性白血球（neutrophils）浸潤的炎症","(B) 尋常型天皰瘡（pemphigus vulgaris）","(C) 類天皰瘡（bullous pemphigoid）","(D) 冷膿瘍（cold abscess）"],"answer":3,"image":""},{"id":"md2-111-1-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"111年第1次第77題","year":111,"session":1,"number":77,"question":"胃食道逆流患者，於食道末端做切片檢查，發現良性柱狀上皮細胞，最可能為何種變化？","options":["(A) 異生（dysplasia）","(B) 增生（hyperplasia）","(C) 轉移（metastasis）","(D) 化生（metaplasia）"],"answer":3,"image":""},{"id":"md2-111-1-78","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"111年第1次第78題","year":111,"session":1,"number":78,"question":"下列何種染色體／基因異常變化，常見於大部分的Ewing sarcoma family tumors（ESFT），並可據此作為分子診斷ESFT？","options":["(A) trisomy 22","(B) (11;22)(q24;q12) translocation","(C) 1p19q co-deletion","(D) N-MYC amplification"],"answer":1,"image":""},{"id":"md2-111-1-79","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"111年第1次第79題","year":111,"session":1,"number":79,"question":"7歲小男孩平時健康，最近因不小心跌倒，右腿呈現瘀傷疼痛。X光檢查發現右側遠端股骨（distal femur）有一約0.3公分、偏離中軸且呈多葉狀（eccentric and lobulated）、放射線通透（radiolucency）之疑似腫瘤病灶。根據上述，該病人最可能罹患的疾病是：","options":["(A) fibrous cortical defect","(B) fibrous dysplasia","(C) giant cell tumor","(D) chondrosarcoma"],"answer":0,"image":""},{"id":"md2-111-1-80","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"111年第1次第80題","year":111,"session":1,"number":80,"question":"下述疾病何者少見於腦外傷引起的後遺症？","options":["(A) 精神疾病（psychiatric disorder）","(B) 癲癇（epilepsy）","(C) 水腦（hydrocephalus）","(D) 脫髓鞘性病變（demyelinating disease）"],"answer":3,"image":""},{"id":"md2-111-1-81","subject":"md2","topic":"病理-免疫感染遺傳","meta":"111年第1次第81題","year":111,"session":1,"number":81,"question":"一般而言，下列那些腫瘤與DNA病毒有關，且被認為在愛滋病（acquired immune deficiency syndrome）患者比在正常人容易得到？①腦部原發性B細胞淋巴癌 ②子宮頸鱗狀上皮細胞癌 ③卡波西氏肉瘤（Kaposi sarcoma）","options":["(A) ①②③","(B) 僅①②","(C) 僅②③","(D) 僅①③"],"answer":0,"image":""},{"id":"md2-111-1-82","subject":"md2","topic":"真菌學","meta":"111年第1次第82題","year":111,"session":1,"number":82,"question":"關於鼻腦白黴菌病（rhinocerebral mucormycosis）的敘述，下列何者正確？","options":["(A) 病菌產生外毒素傷害眼眶及腦部組織，是其快速造成這些感染部位壞死的最主要原因","(B) 病菌的典型型態是菌絲體分節清楚，銳角分枝及較固定的寬度","(C) 病菌屬雙態性真菌（dimorphic fungi），所以檢體送培養時需要特別告知實驗室需要延長培養時間","(D) 易感因素（predisposing factors）包括嗜中性粒細胞低下（neutropenia）、使用類固醇與糖尿病等"],"answer":3,"image":""},{"id":"md2-111-1-83","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"111年第1次第83題","year":111,"session":1,"number":83,"question":"遺傳性的視網膜母細胞瘤（familial retinoblastoma）之病患，最常繼發下列那一種惡性腫瘤？","options":["(A) Leukemia","(B) Lymphoma","(C) Osteosarcoma","(D) Hepatoblastoma"],"answer":2,"image":""},{"id":"md2-111-1-84","subject":"md2","topic":"病理-心血管血液","meta":"111年第1次第84題","year":111,"session":1,"number":84,"question":"最常見的全身性血栓栓塞（systemic thromboembolism）栓子來源為：","options":["(A) 下肢深層靜脈","(B) 左心室壁梗塞處","(C) 主動脈動脈瘤","(D) 下肢淺層靜脈"],"answer":1,"image":""},{"id":"md2-111-1-85","subject":"md2","topic":"病理-心血管血液","meta":"111年第1次第85題","year":111,"session":1,"number":85,"question":"10歲男童，三週前發生咽炎，實驗室檢查發現anti-streptolysin O的效價升高，臨床表現為發燒、心臟炎、關節痛及四肢有皮下結節；在此病患的心臟病灶中的那一種細胞對此病的診斷最具特異性？","options":["(A) Anitschkow細胞","(B) Reed-Sternberg細胞","(C) Cajal細胞","(D) Purkinje細胞"],"answer":0,"image":""},{"id":"md2-111-1-86","subject":"md2","topic":"病理-心血管血液","meta":"111年第1次第86題","year":111,"session":1,"number":86,"question":"48歲男性因進展性心臟衰竭接受換心手術，切除下來的心臟呈擴大狀且重達600公克，病理檢查發現心臟四個腔室都擴大，但兩側心室並無特別肥厚，冠狀動脈亦無狹窄。下列病理組織變化中，何者最不常見於此類心臟中？","options":["(A) myocyte hypertrophy","(B) interstitial fibrosis","(C) small subendocardial scars","(D) myofiber disarray"],"answer":3,"image":""},{"id":"md2-111-1-87","subject":"md2","topic":"病理-心血管血液","meta":"111年第1次第87題","year":111,"session":1,"number":87,"question":"有關濾泡性淋巴瘤（follicular lymphoma）的敘述，下列何者正確？","options":["(A) 是一種自然殺手細胞（natural killer cell）淋巴瘤","(B) 典型腫瘤細胞會表現CD20、CD5及cyclin D1","(C) 大多數腫瘤會有BCL2基因的轉位，造成BCL2的過度表現","(D) 組成細胞為副免疫母細胞（paraimmunoblasts）及前淋巴細胞（prolymphocytes）"],"answer":2,"image":""},{"id":"md2-111-1-88","subject":"md2","topic":"病理-心血管血液","meta":"111年第1次第88題","year":111,"session":1,"number":88,"question":"有關缺鐵性貧血（iron deficiency anemia）的敘述，下列何者正確？","options":["(A) 紅血球會比正常小且顏色較淺","(B) 較常發生於男性","(C) 在西方國家，最常見的原因是飲食攝取不足","(D) 血漿的總鐵結合力（total iron-binding capacity）會降低"],"answer":0,"image":""},{"id":"md2-111-1-89","subject":"md2","topic":"病理-呼吸消化","meta":"111年第1次第89題","year":111,"session":1,"number":89,"question":"下列何者為雙側胸膜積水（hydrothorax）最常見的原因？","options":["(A) 肺癌（lung cancer）","(B) 鬱血性心衰竭（congestive heart failure）","(C) 惡性間皮瘤（malignant mesothelioma）","(D) 呼吸窘迫（respiratory distress）"],"answer":1,"image":""},{"id":"md2-111-1-90","subject":"md2","topic":"病理-呼吸消化","meta":"111年第1次第90題","year":111,"session":1,"number":90,"question":"下列有關小細胞肺癌（small cell carcinoma）的敘述何者錯誤？","options":["(A) 與抽菸關聯性不大","(B) 通常發生於肺部中央位置","(C) 常表現神經內分泌標記","(D) 常有縱隔腔淋巴結轉移"],"answer":0,"image":""},{"id":"md2-111-1-91","subject":"md2","topic":"病理-呼吸消化","meta":"111年第1次第91題","year":111,"session":1,"number":91,"question":"下列何者為引起急性呼吸窘迫症候群（ARDS）最常見的原因？","options":["(A) 外物吸入（aspiration）","(B) 外傷（trauma）","(C) 輸血反應（transfusion reaction）","(D) 肺炎（pneumonia）"],"answer":3,"image":""},{"id":"md2-111-1-92","subject":"md2","topic":"病理-呼吸消化","meta":"111年第1次第92題","year":111,"session":1,"number":92,"question":"何種胃部疾病和幽門桿菌（H. pylori）最無直接關係？","options":["(A) 胃底腺息肉（Fundic gland polyp）","(B) 慢性消化性潰瘍（chronic peptic ulcer）","(C) 胃上皮癌（gastric carcinoma）","(D) 胃淋巴瘤（gastric MALT lymphoma）"],"answer":0,"image":""},{"id":"md2-111-1-93","subject":"md2","topic":"病理-呼吸消化","meta":"111年第1次第93題","year":111,"session":1,"number":93,"question":"關於炎症性腸病（inflammatory bowel disease）之敘述，何者錯誤？","options":["(A) 克隆氏症（Crohn disease）又稱區域性腸炎（regional enteritis）","(B) 克隆氏症（Crohn disease）為全壁性發炎","(C) 跳躍式病灶（skip lesion）為潰瘍性結腸炎（ulcerative colitis）的特徵","(D) 潰瘍性結腸炎（ulcerative colitis）病人罹患大腸癌的機會比正常人高"],"answer":2,"image":""},{"id":"md2-111-1-94","subject":"md2","topic":"病理-呼吸消化","meta":"111年第1次第94題","year":111,"session":1,"number":94,"question":"酗酒的40歲男性，酒後因上腹痛且反射到後背來急診，病人血清消化酶（amylase）及脂肪酶（lipase）升高，且有低血鈣情形，則病人最有可能出現下列何種病理變化？","options":["(A) 胰臟出血性壞死","(B) 心臟廣泛性壞死","(C) 胃潰瘍穿孔","(D) 肝臟大塊性壞死"],"answer":0,"image":""},{"id":"md2-111-1-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"111年第1次第95題","year":111,"session":1,"number":95,"question":"以下何者補體系統成分在緻密物沉積病（dense deposit disease）病人的血清中最有可能是維持在正常值？","options":["(A) 補體C3（complement C3）","(B) 補體C1（complement C1）","(C) B因子（factor B）","(D) 血清滅菌蛋白（properdin）"],"answer":1,"image":""},{"id":"md2-111-1-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"111年第1次第96題","year":111,"session":1,"number":96,"question":"典型溶血性尿毒症（typical hemolytic-uremic syndrome）最常見之致病菌為：","options":["(A) A群貝他溶血型鏈球菌（Group A β hemolytic Streptococci）","(B) 大腸桿菌O157:H7型（E. coli O157:H7）","(C) b型嗜血流行性感冒桿菌（Hemophilus influenza b）","(D) 草綠色鏈球菌（Streptococcus viridans）"],"answer":1,"image":""},{"id":"md2-111-1-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"111年第1次第97題","year":111,"session":1,"number":97,"question":"副甲狀腺瘤（parathyroid adenoma）與副甲狀腺癌（parathyroid carcinoma）通常並不好區別，目前認為診斷副甲狀腺癌最可靠的條件是：","options":["(A) 腫瘤轉移（tumor metastasis）","(B) 頻繁的有絲分裂（frequent mitosis）","(C) 大核仁（large nucleoli）","(D) 腫瘤壞死（tumor necrosis）"],"answer":0,"image":""},{"id":"md2-111-1-98","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"111年第1次第98題","year":111,"session":1,"number":98,"question":"有關乳房疾病，下列何者正確？","options":["(A) 非增生性的乳房囊腫（non-proliferative breast cyst），會增加2.5倍罹患乳癌的機率","(B) 非典型乳管增生（atypical ductal hyperplasia）者，日後發生乳癌機率約為一般女性的4～5倍","(C) 臺灣國民健康署使用超音波（sonography）作為乳癌主要的篩檢工具","(D) 纖維腺瘤（fibroadenoma）常合併乳頭分泌物（nipple discharge）"],"answer":1,"image":""},{"id":"md2-111-1-99","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"111年第1次第99題","year":111,"session":1,"number":99,"question":"下列有關子宮頸癌（cervical carcinoma）的敘述，何者較不正確？","options":["(A) 最常見的組織學分類為鱗狀上皮癌（squamous cell carcinoma）","(B) 第二常見的組織學分類為腺癌（adenocarcinoma）","(C) 部分子宮頸癌與高危險性人類乳突狀病毒（high-risk human papillomavirus）的感染有關，包括腺鱗癌（adenosquamous carcinoma）與神經內分泌癌（neuroendocrine carcinoma）","(D) 一般而言腺鱗癌（adenosquamous carcinoma）與神經內分泌癌（neuroendocrine carcinoma）從原位癌發展到侵襲癌的時間較長於鱗狀上皮癌（squamous cell carcinoma）"],"answer":3,"image":""},{"id":"md2-111-1-100","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"111年第1次第100題","year":111,"session":1,"number":100,"question":"72歲婦女因下腹脹痛來門診。超音波顯示，左右兩側骨盆腔有實質性卵巢腫瘤，其顯微鏡下腫瘤特徵如附圖，則該卵巢有可能是下列何種診斷？","options":["(A) 類癌（carcinoid）","(B) 克魯肯氏瘤（Krukenberg tumor）","(C) 布雷納氏瘤（Brenner tumor）","(D) 甲狀腺腫狀腺瘤（struma ovarii）"],"answer":1,"image":"md2-111-1-100.jpeg"},{"id":"md2-111-2-1","subject":"md2","topic":"細菌學","meta":"111年第2次第1題","year":111,"session":2,"number":1,"question":"一位船員皮膚上有傷口化膿且周邊紅斑，經鑑定發現是一株好氧，且具有觸酶（catalase）和凝集酶（coagulase）活性，同時可以存活在高鹽培養基的細菌。依據前述，該菌最可能是：","options":["(A) 創傷弧菌（Vibrio vulnificus）","(B) 腸炎弧菌（Vibrio parahaemolyticus）","(C) 金黃色葡萄球菌（Staphylococcus aureus）","(D) 表皮葡萄球菌（Staphylococcus epidermidis）"],"answer":2,"image":""},{"id":"md2-111-2-2","subject":"md2","topic":"藥理-化學治療","meta":"111年第2次第2題","year":111,"session":2,"number":2,"question":"下列何者為治療花柳性淋巴肉芽腫（lymphogranuloma venereum）的首選藥物？","options":["(A) metronidazole","(B) penicillin","(C) doxycycline","(D) isoniazid"],"answer":2,"image":""},{"id":"md2-111-2-3","subject":"md2","topic":"細菌學","meta":"111年第2次第3題","year":111,"session":2,"number":3,"question":"胜肽聚醣（Peptidoglycan）為革蘭氏陽性細菌細胞壁之主要成分，下列那一隻細菌除外？","options":["(A) 砂眼披衣菌（Chlamydia trachomatis）","(B) 糞腸球菌（Enterococcus faecalis）","(C) 仙人掌桿菌（Bacillus cereus）","(D) 單核細胞增多性李斯特菌（Listeria monocytogenes）"],"answer":0,"image":""},{"id":"md2-111-2-4","subject":"md2","topic":"細菌學","meta":"111年第2次第4題","year":111,"session":2,"number":4,"question":"有關細菌質體（plasmid）之敘述，下列何者最適當？","options":["(A) 可在細菌間傳遞帶有抗藥性相關基因","(B) 與細菌染色體同步進行複製","(C) 多為存在於細胞質內之線狀RNA","(D) 僅存在於革蘭氏陰性菌之細胞質中"],"answer":0,"image":""},{"id":"md2-111-2-5","subject":"md2","topic":"細菌學","meta":"111年第2次第5題","year":111,"session":2,"number":5,"question":"當細菌培養液只含有乳糖，此時抑制子（repressor）和代謝基因活化蛋白質（catabolite gene-activator protein , CAP）之活性，以及調節乳糖操縱子（lac operon）表現的敘述，下列何者正確？","options":["(A) 抑制子的功能被抑制，且CAP不活化，促使乳糖操縱子表現","(B) 抑制子的功能被抑制，且CAP不活化，導致乳糖操縱子不表現","(C) 抑制子的功能被抑制，且CAP被活化，導致乳糖操縱子不表現","(D) 抑制子的功能被抑制，且CAP被活化，促使乳糖操縱子表現"],"answer":3,"image":""},{"id":"md2-111-2-6","subject":"md2","topic":"細菌學","meta":"111年第2次第6題","year":111,"session":2,"number":6,"question":"有關無乳鏈球菌（Streptococcus agalactiae）的敘述，下列何者錯誤？","options":["(A) 屬於B群鏈球菌（Group B streptococci）","(B) 血清學鑑定的三個主要標誌為Lancefield group B抗原（antigen）、型特異性莢膜多醣體（type-specific capsular polysaccharides）、表面蛋白質（surface proteins）","(C) 主要棲居在人體上呼吸道","(D) 此菌可經由產婦生產時感染嬰兒"],"answer":2,"image":""},{"id":"md2-111-2-7","subject":"md2","topic":"細菌學","meta":"111年第2次第7題","year":111,"session":2,"number":7,"question":"關於白喉桿菌（Corynebacterium diphtheriae）的敘述，下列何者錯誤？","options":["(A) 主要的致病因子為白喉毒素（diptheria toxin），作用於轉譯延長因子（elongation factor-2 , EF-2）","(B) 造成疾病的主要生物型（biotype）是gravis biotype","(C) 細胞壁上含有短鏈分枝菌酸（short-chain mycolic acids）","(D) 主要造成呼吸道或皮膚的疾病"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第7題一律給分 (原公告答案 B)"},{"id":"md2-111-2-8","subject":"md2","topic":"細菌學","meta":"111年第2次第8題","year":111,"session":2,"number":8,"question":"關於鬆脆類桿菌（Bacteroides fragilis）的敘述，下列何者錯誤？","options":["(A) 是少數沒有莢膜（capsule）的病原菌之一","(B) 可產生不耐熱（heat-labile）的鋅金屬蛋白酶（zinc metalloprotease）毒素造成腹瀉","(C) 其脂多醣體（lipopolysaccharides, LPS）具微毒性或無毒性","(D) 可產生β-內酰胺酶（β-lactamases），使其對青黴素（penicillin）具抗藥性"],"answer":0,"image":""},{"id":"md2-111-2-9","subject":"md2","topic":"細菌學","meta":"111年第2次第9題","year":111,"session":2,"number":9,"question":"關於尿素分解尿漿菌（Ureaplasma urealyticum）的敘述，下列何者正確？","options":["(A) 其細胞膜富含固醇類（sterols）","(B) 主要引起皮膚病灶（skin lesions）","(C) 為降低罹患產後熱（postpartum fever）的風險，建議預備懷孕的婦女應施打此菌之疫苗","(D) 常使用盤尼西林（penicillin）治療此菌引起的感染症"],"answer":0,"image":""},{"id":"md2-111-2-10","subject":"md2","topic":"病毒學","meta":"111年第2次第10題","year":111,"session":2,"number":10,"question":"下列有關病毒的敘述，何者正確？","options":["(A) 愛滋病毒（human immunodeficiency virus）之酵素均由被感染細胞的基因轉譯製造","(B) 茲卡病毒（Zika virus）為負股(-) RNA病毒","(C) 新型冠狀病毒（SARS-CoV-2）之複製在細胞質中進行","(D) 腸病毒（enterovirus）具有外套膜，為RNA病毒"],"answer":2,"image":""},{"id":"md2-111-2-11","subject":"md2","topic":"病毒學","meta":"111年第2次第11題","year":111,"session":2,"number":11,"question":"下列那幾種病毒可經由動物暨節肢動物而傳播？①漢他病毒（hantavirus） ②日本腦炎病毒（Japanese encephalitis virus） ③黃熱病病毒（yellow fever virus） ④狂犬病病毒（rabies virus）","options":["(A) ①②","(B) ②③","(C) ③④","(D) ②④"],"answer":1,"image":""},{"id":"md2-111-2-12","subject":"md2","topic":"病毒學","meta":"111年第2次第12題","year":111,"session":2,"number":12,"question":"下列何者不是Bunyavirus與Arenavirus共同具有的特性？","options":["(A) 為人畜共同傳染（zoonoses）的病毒","(B) 基因體為片段RNA組成（segmented RNA genome）","(C) 可能造成出血熱（hemorrhagic fever）","(D) 二者病毒顆粒（virion）中都沒有包裹核糖體（ribosome）"],"answer":3,"image":""},{"id":"md2-111-2-13","subject":"md2","topic":"病毒學","meta":"111年第2次第13題","year":111,"session":2,"number":13,"question":"下列何者不是負股RNA病毒（negative-sense RNA virus）？","options":["(A) 流感病毒（influenza virus）","(B) 伊波拉病毒（Ebola virus）","(C) 狂犬病毒（rabies virus）","(D) 登革熱病毒（dengue virus）"],"answer":3,"image":""},{"id":"md2-111-2-14","subject":"md2","topic":"病毒學","meta":"111年第2次第14題","year":111,"session":2,"number":14,"question":"下列人類疾病何者不是由痘科病毒（Poxvirus）引起？","options":["(A) 天花","(B) 傳染性軟疣（molluscum contagiosum）造成的皮膚病灶","(C) 手指頭上的Orf病灶","(D) 疱疹性膿性指頭疽（whitlow）"],"answer":3,"image":""},{"id":"md2-111-2-15","subject":"md2","topic":"藥理-化學治療","meta":"111年第2次第15題","year":111,"session":2,"number":15,"question":"下列那一種藥物，主要抑制C型肝炎病毒（hepatitis C virus）的聚合酶（polymerase）？","options":["(A) 索華迪（sofosbuvir）","(B) 波普瑞韋（boceprevir）","(C) 拉米夫定（lamivudine）","(D) 聚乙二醇干擾素（pegylated interferon）"],"answer":0,"image":""},{"id":"md2-111-2-16","subject":"md2","topic":"細菌學","meta":"111年第2次第16題","year":111,"session":2,"number":16,"question":"近年來基質輔助雷射脫附飛行時間質譜儀（matrix-assisted laser desorption ionization-time of flight mass spectrometry, MALDI-TOF MS）廣泛應用在微生物的鑑定上，其主要的偵測標的物為何？","options":["(A) 蛋白質","(B) 核酸","(C) 粒線體","(D) 微量元素"],"answer":0,"image":""},{"id":"md2-111-2-17","subject":"md2","topic":"真菌學","meta":"111年第2次第17題","year":111,"session":2,"number":17,"question":"下列何者具有寬大菌絲，且沒有或較少細胞中隔（septum）？","options":["(A) Fusarium spp.","(B) Trichosporon spp.","(C) Rhizopus spp.","(D) Scedosporium spp."],"answer":2,"image":""},{"id":"md2-111-2-18","subject":"md2","topic":"免疫學","meta":"111年第2次第18題","year":111,"session":2,"number":18,"question":"下列何者最可以聯結先天免疫及後天免疫作用之抗原呈獻細胞（antigen-presenting cell）？","options":["(A) NK cell","(B) basophil","(C) neutrophil","(D) dendritic cell"],"answer":3,"image":""},{"id":"md2-111-2-19","subject":"md2","topic":"免疫學","meta":"111年第2次第19題","year":111,"session":2,"number":19,"question":"王小弟今年13歲，因鼻腔內長了膿包並有持續擴大的跡象，而到醫院就診。醫生檢查結果有類似慢性發炎的現象，問診發現以往王小弟也常有類似感染後，很緩慢痊癒的情況。經由詳細檢查發現他的CD8 T細胞數量異常的低，而其MHC class I分子在細胞上的表現量也極少，因此醫生分析後認為王小弟最有可能得了：","options":["(A) chronic granulomatous disease","(B) MHC class I deficiency","(C) MHC class II deficiency","(D) leukocyte adhesion deficiency"],"answer":1,"image":""},{"id":"md2-111-2-20","subject":"md2","topic":"免疫學","meta":"111年第2次第20題","year":111,"session":2,"number":20,"question":"T細胞的抗原受體（T cell receptor, TCR）在發育過程中會產生多樣性，下列何種機制和TCR多樣性有關？ ①V region由數個基因片段（gene segments）組成 ②V(D)J DNA重組 ③RAG1和RAG2基因表現 ④AIRE基因表現 ⑤terminal deoxynucleotidyl transferase（TdT）基因表現 ⑥類型轉換重組（class switch recombination） ⑦N-nucleotide addition","options":["(A) ①②③⑤⑦","(B) ①③⑤⑥⑦","(C) ①②③④⑤","(D) ①②③⑤⑥"],"answer":0,"image":""},{"id":"md2-111-2-21","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"111年第2次第21題","year":111,"session":2,"number":21,"question":"毒殺性CD8 T細胞（cytotoxic CD8 T cells）所執行細胞凋亡之內在徑路（intrinsic pathway），下列何者為主要調節抑制的分子？","options":["(A) Bcl-2 family","(B) Bax family","(C) caspase-3","(D) p53"],"answer":0,"image":""},{"id":"md2-111-2-22","subject":"md2","topic":"免疫學","meta":"111年第2次第22題","year":111,"session":2,"number":22,"question":"我國目前嬰幼兒常規肺炎鏈球菌疫苗接種為結合型疫苗（pneumococcal conjugate vaccine, PCV），此疫苗是將莢膜多醣（capsular polysaccharide）結合白喉毒素蛋白來施打，未滿一歲嬰幼兒常規接種是採用2+1（2劑基礎劑，1劑追加劑）共3劑接種。下列有關肺炎鏈球菌疫苗接種的敘述何者錯誤？","options":["(A) 接種後如果嬰幼兒產生良好的免疫反應，血清可以測到對抗莢膜多醣及抗白喉蛋白的專一性抗體","(B) 主要是對抗莢膜多醣專一性抗體能夠保護嬰幼兒不被肺炎鏈球菌感染","(C) 抗莢膜多醣抗體的產生，主因是專一性辨識莢膜多醣的CD4輔助T細胞（T helper cells）先產生之後，幫助B細胞進一步分化成漿細胞（plasma cells）","(D) 莢膜多醣和白喉毒素蛋白必須以共價鍵（covalent bond）連結在一起，方能有效引發高親和力的抗體產生"],"answer":2,"image":""},{"id":"md2-111-2-23","subject":"md2","topic":"免疫學","meta":"111年第2次第23題","year":111,"session":2,"number":23,"question":"口服耐受性（oral tolerance）最可能經由下列何種細胞激素（cytokine）來達成？","options":["(A) TGF-β","(B) TNF-α","(C) IL-2","(D) IL-5"],"answer":0,"image":""},{"id":"md2-111-2-24","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第2次第24題","year":111,"session":2,"number":24,"question":"3歲的小美已在幼兒園一年的時間，她的父母因為相信施打MMR疫苗可能引起自閉症的說法而拒絕讓她接種MMR疫苗，不過在這之前她已經先接種了DTP疫苗。請問小美雖與一群小朋友朝夕相處很長的時間，但至今仍沒感染麻疹的最有可能原因為何？","options":["(A) 小美對麻疹抗原不會引起免疫反應","(B) 幼兒園的其他小朋友均有接種MMR疫苗而提供了她群體免疫力（herd immunity）","(C) 小美接受的DTP疫苗對麻疹具有交互免疫保護（cross-protective immunity）的功能","(D) 小美雖被麻疹病毒感染，但因服用抗生素所以沒有發病"],"answer":1,"image":""},{"id":"md2-111-2-25","subject":"md2","topic":"免疫學","meta":"111年第2次第25題","year":111,"session":2,"number":25,"question":"已開發國家中第一型過敏性疾病（如氣喘與季節性鼻炎等）的盛行率逐年升高，研究發現環境因子扮演重要角色，下列那一項理論最能解釋這一個現象？","options":["(A) 群體免疫（herd immunity）","(B) 衛生假說（hygiene hypothesis）","(C) 連結辨識（linked recognition）","(D) 正向篩選（positive selection）"],"answer":1,"image":""},{"id":"md2-111-2-26","subject":"md2","topic":"免疫學","meta":"111年第2次第26題","year":111,"session":2,"number":26,"question":"假設有種臨床藥物X，某群孩童經過多年使用治療相關症狀後，皆出現類似自體免疫疾病之副作用，例如：脾臟及淋巴結腫大、出現自體抗體等，最近的研究顯示藥物X可能藉由干擾某個分子的正常功能，而導致這些副作用，請選出最不可能的分子？","options":["(A) CTLA-4","(B) FasL","(C) FoxP3","(D) CD23"],"answer":3,"image":""},{"id":"md2-111-2-27","subject":"md2","topic":"病毒學","meta":"111年第2次第27題","year":111,"session":2,"number":27,"question":"預防子宮頸癌發生是用下列那一種血清型（serotype）的人類乳突病毒（human papilloma virus, HPV )疫苗？","options":["(A) HPV-1","(B) HPV-4","(C) HPV-8","(D) HPV-16"],"answer":3,"image":""},{"id":"md2-111-2-28","subject":"md2","topic":"藥理-化學治療","meta":"111年第2次第28題","year":111,"session":2,"number":28,"question":"針對慢性骨髓白血病（chronic myeloid leukemia）有很好的標靶藥物，是因為該藥物作用於下列何種標的物？","options":["(A) Bcr-Ab1酪胺酸激酶（tyrosine kinase）","(B) p53蛋白","(C) Ras蛋白","(D) Her-2/neu抗原"],"answer":0,"image":""},{"id":"md2-111-2-29","subject":"md2","topic":"寄生蟲學","meta":"111年第2次第29題","year":111,"session":2,"number":29,"question":"下列何種寄生蟲重度感染幼童時，最有可能造成異位性移行（ectopic migration）寄生？","options":["(A) 菲律賓毛線蟲（Capillaria philippinensis）","(B) 蟯蟲（Enterobius vermicularis）","(C) 蛔蟲（Ascaris lumbricoides）","(D) 鞭蟲（Trichuris trichiura）"],"answer":2,"image":""},{"id":"md2-111-2-30","subject":"md2","topic":"寄生蟲學","meta":"111年第2次第30題","year":111,"session":2,"number":30,"question":"李先生經常往返臺灣及非洲經商，在非洲有時會喝到沒煮沸的水，最近他腳踝皮膚出現潰瘍，醫師從潰瘍處拉出100公分長的寄生蟲，您認為李先生最有可能感染下列何種寄生蟲？","options":["(A) 鉤蟲（hookworm）","(B) 羅阿絲蟲（Loa loa）","(C) 蟠尾絲蟲（Onchocerca volvulus）","(D) 麥地那線蟲（Dracunculus medinensis）"],"answer":3,"image":""},{"id":"md2-111-2-31","subject":"md2","topic":"寄生蟲學","meta":"111年第2次第31題","year":111,"session":2,"number":31,"question":"人類是下列何種寄生蟲的終宿主也是中間宿主？","options":["(A) 短小包膜絛蟲（Hymenolepis nana）","(B) 豬肉絛蟲（Taenia solium）","(C) 曼森裂頭絛蟲（Spirometra mansonoides）","(D) 牛肉絛蟲（Taenia saginata）"],"answer":1,"image":""},{"id":"md2-111-2-32","subject":"md2","topic":"寄生蟲學","meta":"111年第2次第32題","year":111,"session":2,"number":32,"question":"下列何者為吸蟲之共同特徵？","options":["(A) 生活史中需要二個中間宿主","(B) 雄性成蟲具抱雌溝","(C) 蟲卵皆具有卵蓋","(D) 均須經由螺類傳播"],"answer":3,"image":""},{"id":"md2-111-2-33","subject":"md2","topic":"寄生蟲學","meta":"111年第2次第33題","year":111,"session":2,"number":33,"question":"有關黑熱病（kala-azar）的敘述，下列何者正確？","options":["(A) 主要致病原是熱帶利什曼原蟲（Leishmania tropica）","(B) 引起該疾病之利什曼原蟲無鞭毛體（amastigote），可以做為分類上的主要依據","(C) 晚期會出現肝脾腫大（hepatosplenomegaly）、黑尿及發熱的症狀，故稱為黑熱病","(D) 有部分患者皮膚會出現紅腫及結節（depigmented nodule）的後黑熱病（post-kala-azar）症狀"],"answer":3,"image":""},{"id":"md2-111-2-34","subject":"md2","topic":"寄生蟲學","meta":"111年第2次第34題","year":111,"session":2,"number":34,"question":"下列何者是傳播蟠尾絲蟲（Onchocerca volvulus）之主要病媒？","options":["(A) 蚋（Simulium spp.）","(B) 蠓（Culicoides spp.）","(C) 虻（Chrysops spp.）","(D) 蚊（mosquito）"],"answer":0,"image":""},{"id":"md2-111-2-35","subject":"md2","topic":"寄生蟲學","meta":"111年第2次第35題","year":111,"session":2,"number":35,"question":"下列何時期之恙蟎屬（Leptotrombidium spp.）為人類感染恙蟲病（tsutsugamushi disease）之主要媒介？","options":["(A) 幼蟎（larvae）","(B) 稚（若）蟎（nymph）","(C) 雌蟎（female）","(D) 雄蟎（male）"],"answer":0,"image":""},{"id":"md2-111-2-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第2次第36題","year":111,"session":2,"number":36,"question":"若欲探討「是否吸菸」與「肺功能是否正常」兩者是不是有相關，下列敘述何者最不恰當？","options":["(A) 可以利用卡方檢定來檢定兩者之間是否有相關性","(B) 可以利用檢定勝算比值（odds ratio）是否為1來檢定兩者之間是否有相關性","(C) 可以建立檢定勝算比值（odds ratio）的95%信賴區間，並據以檢定兩者之間是否有相關性","(D) 卡方檢定的檢定統計量越大，表示計算出來的檢定勝算比值（odds ratio）越大"],"answer":3,"image":""},{"id":"md2-111-2-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第2次第37題","year":111,"session":2,"number":37,"question":"下列有關相關係數（correlation coefficient）之敘述，何者最不恰當？","options":["(A) 若體重與血壓之相關係數為0.6，可以推論體重與血壓有顯著正相關","(B) 衡量體重（單位：Kg）與薪資水準（分為低、中、高）之相關性，可以採用Spearman相關係數","(C) Pearson相關係數為0，表示兩變項不具有線性相關","(D) Pearson相關係數之數值介於 -1到1之間"],"answer":0,"image":""},{"id":"md2-111-2-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第2次第38題","year":111,"session":2,"number":38,"question":"相較於病例對照研究法，下列何者是世代研究的最大優點？","options":["(A) 適用於稀有疾病","(B) 研究時間較短","(C) 較可建構時序關係","(D) 所需族群樣本數較少"],"answer":2,"image":""},{"id":"md2-111-2-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第2次第39題","year":111,"session":2,"number":39,"question":"在傳染病傳播的過程中，何謂潛伏期（incubation period）？","options":["(A) 從接觸指標病例到被感染的期間","(B) 從被感染到開始出現臨床症狀的期間","(C) 從開始出現臨床症狀到第一次就醫的期間","(D) 從接觸指標病例到第一次就醫的期間"],"answer":1,"image":""},{"id":"md2-111-2-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"111年第2次第40題","year":111,"session":2,"number":40,"question":"下列關於游離性輻射對人體的作用或傷害的敘述，何者最不恰當？","options":["(A) 游離性輻射可能造成原子的離子化，而造成生物體內分子的破壞","(B) 不同輻射線的種類，所產生的生物效應不一樣，實務上以1侖目迦馬線或X射線所產生的生物效應作為1雷德","(C) 游離輻射劑量大時，會造成對細胞分裂的抑制，甚至使該生物立即死亡（1萬侖目以上時）","(D) 游離性輻射長期暴露可誘發癌症，通常細胞分裂能力愈強者愈容易"],"answer":1,"image":""},{"id":"md2-111-2-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"111年第2次第41題","year":111,"session":2,"number":41,"question":"有關環境毒性物質對呼吸道的影響，下列敘述何者最不恰當？","options":["(A) 二氧化硫容易在上呼吸道被吸收，引起呼吸道刺激反應","(B) 隨著微粒粒徑愈小，被吸入體內沉積於肺泡的比例愈高","(C) 吸入環境中的花粉、孢子造成氣喘，機轉為過敏性反應引起支氣管收縮","(D) 長期暴露於臭氧、氮氧化物，會破壞支持肺泡及支氣管等結構之彈力纖維，減弱換氣功能"],"answer":1,"image":""},{"id":"md2-111-2-42","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第2次第42題","year":111,"session":2,"number":42,"question":"「週一早上的心絞痛（Monday morning angina）」，亦即經週末的休息，週一血中下列物質濃度最低時引起心絞痛，甚至心肌梗塞，最可能的職場暴露物質是：","options":["(A) 二硫化碳","(B) 氟氯碳化物","(C) 有機硝化物","(D) 一氧化碳"],"answer":2,"image":""},{"id":"md2-111-2-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"111年第2次第43題","year":111,"session":2,"number":43,"question":"下列何者的過量暴露，會造成骨軟化症，俗稱之「痛痛病」？","options":["(A) 鎘","(B) 鉛","(C) 鉻","(D) 汞"],"answer":0,"image":""},{"id":"md2-111-2-44","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"111年第2次第44題","year":111,"session":2,"number":44,"question":"根據Hancock以及Duhl（1986）對健康城市（healthy city）的定義，下列何者最不恰當？","options":["(A) 健康城市是擴展社區的資源","(B) 健康城市是健康促進的結果","(C) 健康城市是改善城市中的物理環境","(D) 健康城市是改善城市中的社會環境"],"answer":1,"image":""},{"id":"md2-111-2-45","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第2次第45題","year":111,"session":2,"number":45,"question":"有關個人層次社會經濟地位的指標，下列何者最恰當？","options":["(A) 失業率","(B) 低收入戶比率","(C) 職業位階","(D) 公共資源"],"answer":2,"image":""},{"id":"md2-111-2-46","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"111年第2次第46題","year":111,"session":2,"number":46,"question":"政府部門邀請當紅偶像歌手拍攝校園拒菸宣導影片，並透過各種媒體傳送，以提升青少年的拒菸信念與行為。此策略主要是應用下列何種理論？","options":["(A) 創新擴散","(B) 風險溝通","(C) 同儕壓力","(D) 社會學習"],"answer":3,"image":""},{"id":"md2-111-2-47","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"111年第2次第47題","year":111,"session":2,"number":47,"question":"有關青少年成癮性物質的使用，下列敘述何者最恰當？","options":["(A) 物質成癮的發展與遺傳因子應無關聯性","(B) 青少年的藥物濫用防制策略，首重減少青少年菸酒的使用","(C) 男性與女性青少年使用成癮性物質的盛行率差距越來越大","(D) 父母親的社經地位與青少年使用菸品的盛行率無關"],"answer":1,"image":""},{"id":"md2-111-2-48","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"111年第2次第48題","year":111,"session":2,"number":48,"question":"影響醫療保健服務需求，最常用到的模式之一就是健康服務利用行為模式，此為社會學者Andersen於1968年所提出。下列何者不屬於影響病人利用醫療服務的因素？","options":["(A) 前置因素（predisposition factors）","(B) 能力因素（enabling factors）","(C) 心理因素（psychological factors）","(D) 需要因素（need）"],"answer":2,"image":""},{"id":"md2-111-2-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"111年第2次第49題","year":111,"session":2,"number":49,"question":"下列何項為健保傳統論量計酬支付方式的主要缺點？","options":["(A) 醫療提供者容易減少必要的醫療服務","(B) 費用的給付不容易反映病人的複雜度","(C) 缺乏節約的誘因","(D) 易被醫療提供者接受"],"answer":2,"image":""},{"id":"md2-111-2-50","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"111年第2次第50題","year":111,"session":2,"number":50,"question":"民眾出入醫院時戴外科口罩自我保護，此時戴口罩對下列那一種傳染途徑的預防最有效？","options":["(A) 血液傳染","(B) 蟲媒傳染","(C) 懸浮氣膠傳染","(D) 食入污染的水或食物傳染"],"answer":2,"image":""},{"id":"md2-111-2-51","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第2次第51題","year":111,"session":2,"number":51,"question":"Warfarin在人體內的代謝主要受到下列那兩種基因的多型性變異（polymorphism）影響？","options":["(A) CYP2C19和VKORC1（vitamin K epoxide reductase complex subunit 1）","(B) CYP2C9和VKORC1","(C) CYP2D6和VKORC1","(D) CYP2B6和CYP2C19"],"answer":1,"image":""},{"id":"md2-111-2-52","subject":"md2","topic":"藥理-化學治療","meta":"111年第2次第52題","year":111,"session":2,"number":52,"question":"因肺炎鏈球菌感染導致的腦膜炎，下列藥物何者不適用？","options":["(A) cefuroxime","(B) cefotaxime","(C) ceftriaxone","(D) vancomycin"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第52題一律給分 (原公告答案 A)"},{"id":"md2-111-2-53","subject":"md2","topic":"藥理-化學治療","meta":"111年第2次第53題","year":111,"session":2,"number":53,"question":"下列何者為抗微小管藥物（anti-microtubule drug），可抑制癌細胞分裂而產生抗癌作用？","options":["(A) capecitabine","(B) cabazitaxel","(C) cladribine","(D) chlorambucil"],"answer":1,"image":""},{"id":"md2-111-2-54","subject":"md2","topic":"藥理-化學治療","meta":"111年第2次第54題","year":111,"session":2,"number":54,"question":"下列治療乳癌的藥物中，何者可與乳癌細胞膜上之human epidermal growth factor 2（HER-2）受體結合而抑制癌細胞生長？","options":["(A) anastrozole","(B) doxorubicin","(C) pertuzumab","(D) tamoxifen"],"answer":2,"image":""},{"id":"md2-111-2-55","subject":"md2","topic":"藥理-化學治療","meta":"111年第2次第55題","year":111,"session":2,"number":55,"question":"抗癌藥合併療法CHOP治療non-Hodgkin's lymphoma，其中對細胞週期M期有專一性的抗癌藥物是：","options":["(A) cyclophosphamide","(B) doxorubicin","(C) prednisone","(D) vincristine"],"answer":3,"image":""},{"id":"md2-111-2-56","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第2次第56題","year":111,"session":2,"number":56,"question":"抗血小板凝集的藥物中，下列何者可阻斷血小板上的ADP受體？","options":["(A) aspirin","(B) ticlopidine","(C) tirofiban","(D) dipyridamole"],"answer":1,"image":""},{"id":"md2-111-2-57","subject":"md2","topic":"免疫學","meta":"111年第2次第57題","year":111,"session":2,"number":57,"question":"有關免疫抑制劑之敘述，下列何者錯誤？","options":["(A) mycophenolate mofetil因抑制inosine monophosphate dehydrogenase，進而抑制T淋巴球增生","(B) sirolimus與細胞內FKBP-12結合成的複合體會活化mTOR，進而抑制T淋巴球增生","(C) daclizumab因抑制IL-2受體，可減緩器官移植後的排斥反應","(D) azathioprine能干擾核酸的合成，抑制淋巴細胞的生長"],"answer":1,"image":""},{"id":"md2-111-2-58","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第2次第58題","year":111,"session":2,"number":58,"question":"有關治療血脂異常（dyslipidemia）藥物之作用及機制敘述，下列何者錯誤？","options":["(A) atrovastatin：抑制HMG-CoA reductase","(B) fenofibrate：增加lipoprotein lipase活性","(C) colestipol：減少膽酸的吸收","(D) niacin：活化peroxisome proliferator-activated receptor alpha"],"answer":3,"image":""},{"id":"md2-111-2-59","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第2次第59題","year":111,"session":2,"number":59,"question":"下列何種狀況比較不適合用octreotide治療？","options":["(A) 胃泌素瘤","(B) 食道靜脈瘤出血","(C) 急性便秘","(D) 胰島素瘤"],"answer":2,"image":""},{"id":"md2-111-2-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第2次第60題","year":111,"session":2,"number":60,"question":"蔡小姐因為下肢無力被送到醫院急診，發現有高血壓與低血鉀的情況；進一步檢查後診斷為腎上腺腫瘤造成的原發性高醛固酮症（primary aldosteronism）。在接受手術之前，下列何種藥物較能改善她的症狀？","options":["(A) prednisolone","(B) spironolactone","(C) furosemide","(D) dexamethasone"],"answer":1,"image":""},{"id":"md2-111-2-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第2次第61題","year":111,"session":2,"number":61,"question":"酗酒且患有第二型糖尿病的病人應避免使用metformin治療，因為metformin和酒精一起使用很容易造成：","options":["(A) 肥胖","(B) 乳酸中毒","(C) 低血糖","(D) 高血壓"],"answer":1,"image":""},{"id":"md2-111-2-62","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第2次第62題","year":111,"session":2,"number":62,"question":"下列抗心律不整藥物中，何者不具有抑制交感神經的作用？","options":["(A) amiodarone","(B) esmolol","(C) lidocaine","(D) sotalol"],"answer":2,"image":""},{"id":"md2-111-2-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第2次第63題","year":111,"session":2,"number":63,"question":"下列有關ranolazine的藥理作用機轉，何者錯誤？","options":["(A) 可抑制late sodium current","(B) 可直接抑制鈉鈣交換sodium-calcium exchanger","(C) 可降低細胞內鈣離子濃度","(D) 對無long QT syndrome，但有冠狀動脈疾病患者會延長QT interval"],"answer":1,"image":""},{"id":"md2-111-2-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"111年第2次第64題","year":111,"session":2,"number":64,"question":"治療慢性心衰竭時，若病人沒有水腫或嚴重腎衰竭，下列何種藥物能有效減緩心室擴大（ventricular dilation）？","options":["(A) angiotensin-converting enzyme inhibitors","(B) natriuretic peptide","(C) calcium channel blockers","(D) digitalis"],"answer":0,"image":""},{"id":"md2-111-2-65","subject":"md2","topic":"藥理-總論與自主神經","meta":"111年第2次第65題","year":111,"session":2,"number":65,"question":"下列何者是一種前驅藥（prodrug），經酵素水解後的產物成為選擇性alpha-1交感受體致效劑（selective α1- receptor agonist）？","options":["(A) oxymetazoline","(B) ephedrine","(C) midodrine","(D) ritodrine"],"answer":2,"image":""},{"id":"md2-111-2-66","subject":"md2","topic":"藥理-總論與自主神經","meta":"111年第2次第66題","year":111,"session":2,"number":66,"question":"下列藥物中，何者對M3蕈毒性受體（M3 muscarinic receptor）的選擇性最高，因有較長半衰期，故一天只需服藥一次即可用於治療成人尿失禁（urinary incontinence）？","options":["(A) darifenacin","(B) tolterodine","(C) oxybutynin","(D) trospium"],"answer":0,"image":""},{"id":"md2-111-2-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第2次第67題","year":111,"session":2,"number":67,"question":"急性腦損傷的病人常會發生壓力性潰瘍（stress ulcer），以致出現胃出血或胃痛等症狀，此時應優先考慮給與下列何種藥物，以快速改善病人胃痛或出血症狀？","options":["(A) pantoprazole","(B) ketoprofen","(C) pilocarpine","(D) meclizine"],"answer":0,"image":""},{"id":"md2-111-2-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第2次第68題","year":111,"session":2,"number":68,"question":"兒童急性氣喘發作呼吸困難至急診，使用下列何種藥物療效最佳也最快？","options":["(A) salmeterol","(B) zafirlukast","(C) albuterol","(D) ipratropium"],"answer":2,"image":""},{"id":"md2-111-2-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第2次第69題","year":111,"session":2,"number":69,"question":"下列何種藥物對冷所引起的蕁麻疹（cold-induced urticaria）及類癌瘤（carcinoid tumor）的平滑肌症狀，具有改善的作用？","options":["(A) ketanserin","(B) ritanserin","(C) cyproheptadine","(D) ondansetron"],"answer":2,"image":""},{"id":"md2-111-2-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第2次第70題","year":111,"session":2,"number":70,"question":"下列何種藥物與mifepristone（RU-486）合併使用，可以做為懷孕初期的墮胎藥（terminate early pregnancy）？","options":["(A) treprostinil","(B) misoprostol","(C) epoprostenol","(D) latanoprost"],"answer":1,"image":""},{"id":"md2-111-2-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"111年第2次第71題","year":111,"session":2,"number":71,"question":"第一代與第二代antihistamines的區分，主要是根據下列何者而來？","options":["(A) 與H1-receptor的親和力","(B) 通過血腦屏障（blood brain barrier）的能力","(C) 產生antiadrenergic activity的強弱","(D) 與H3-receptor的親和力"],"answer":1,"image":""},{"id":"md2-111-2-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"111年第2次第72題","year":111,"session":2,"number":72,"question":"Haloperidol和clozapine皆為治療思覺失調症的藥物，但clozapine較不會引起錐體外症候群（extrapyramidal syndrome），因為clozapine具有下列那一個特性？","options":["(A) 對多巴胺受體（D2）具有較低的阻斷作用","(B) 對蕈毒鹼（muscarine）受體具有較強的阻斷作用","(C) 對α-腎上腺素受體具有較強的阻斷作用","(D) 對蕈毒鹼（muscarine）受體具有較低的阻斷作用"],"answer":0,"image":""},{"id":"md2-111-2-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"111年第2次第73題","year":111,"session":2,"number":73,"question":"有關抗憂鬱藥物作用的敘述，下列何者正確？","options":["(A) amitriptyline較不會造成口乾、便秘等副作用，適合用於老年人","(B) trazodone為5-HT2受體的拮抗劑，除抗憂鬱的作用外亦具有安眠的作用","(C) mirtazapine為突觸前α2腎上腺素受體的作用劑，增加norepinephrine和5-HT的釋放","(D) venlafaxine為單胺氧化酶B的選擇性抑制劑，增加突觸norepinephrine的含量"],"answer":1,"image":""},{"id":"md2-111-2-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"111年第2次第74題","year":111,"session":2,"number":74,"question":"服用下列那一個藥物後，飲酒時會導致皮膚潮紅、噁心、嘔吐及劇烈頭痛等身體不適的反應？","options":["(A) disulfiram","(B) acamprosate","(C) naltrexone","(D) lorazepam"],"answer":0,"image":""},{"id":"md2-111-2-75","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"111年第2次第75題","year":111,"session":2,"number":75,"question":"下列何者是甲醇（methanol）中毒之最佳解毒劑？","options":["(A) esmolol","(B) fomepizole","(C) flumazenil","(D) acetylserine"],"answer":1,"image":""},{"id":"md2-111-2-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"111年第2次第76題","year":111,"session":2,"number":76,"question":"下列何者之典型病理變化，最不可能是肉芽腫性發炎（granulomatous inflammation）？","options":["(A) 痳瘋（leprosy）","(B) 類肉瘤（sarcoidosis）","(C) 潰瘍性大腸炎（ulcerative colitis）","(D) 結核（tuberculosis）"],"answer":2,"image":""},{"id":"md2-111-2-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"111年第2次第77題","year":111,"session":2,"number":77,"question":"下列何者不是化生（metaplasia）的例子？","options":["(A) 抽菸刺激下，支氣管上皮被鱗狀上皮取代","(B) 胃食道逆流時，食道上皮被柱狀上皮取代","(C) 膀胱感染時，膀胱上皮被移行上皮取代","(D) 酸性環境下，子宮內頸上皮被鱗狀上皮取代"],"answer":2,"image":""},{"id":"md2-111-2-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"111年第2次第78題","year":111,"session":2,"number":78,"question":"關於體染色體遺傳疾病（autosomal inheritable disease）的敘述，下列何者正確？","options":["(A) 酵素蛋白缺陷所引起的遺傳性疾病以顯性遺傳疾病（autosomal dominant disease）為主","(B) 家族性高膽固醇血症（familial hypercholesterolemia）為LDL蛋白結構異常所致，以顯性遺傳疾病為主","(C) 高雪氏症（Gaucher disease）以隱性（recessive）遺傳為主，為葡萄糖腦苷脂（glucocerebroside）接受器（receptor）蛋白結構異常所致","(D) 埃勒斯–丹洛斯症候群（Ehlers-Danlos syndromes）因是纖維性膠原蛋白（fibrillar collagen）結構或合成異常所致，所以顯性或隱性遺傳兼具"],"answer":3,"image":""},{"id":"md2-111-2-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"111年第2次第79題","year":111,"session":2,"number":79,"question":"有關傳染性單核白血球增多症（infectious mononucleosis）的敘述，下列何者正確？","options":["(A) 巨細胞病毒（cytomegalovirus）也會造成類似臨床表現與出現非典型淋巴細胞","(B) 引起的淋巴濾泡（lymphoid follicle）大量增生是造成肝脾腫大的主因","(C) t(8;14)染色體轉位主要可在增生的T淋巴細胞中出現","(D) 引起的竇組織細胞增生症（sinus histiocytosis）是造成淋巴結腫大的主因"],"answer":0,"image":""},{"id":"md2-111-2-80","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"111年第2次第80題","year":111,"session":2,"number":80,"question":"暴露於下列物質，何者最不易引起周邊及中樞神經的病變？","options":["(A) Acrylamide","(B) Ketones","(C) Formaldehyde","(D) Mercury"],"answer":2,"image":""},{"id":"md2-111-2-81","subject":"md2","topic":"病理-免疫感染遺傳","meta":"111年第2次第81題","year":111,"session":2,"number":81,"question":"下列基因的變異，何者與遺傳性非息肉病大腸癌（hereditary nonpolyposis colon cancer）較無關？","options":["(A) MSH2","(B) MSH6","(C) APC","(D) MLH1"],"answer":2,"image":""},{"id":"md2-111-2-82","subject":"md2","topic":"病理-呼吸消化","meta":"111年第2次第82題","year":111,"session":2,"number":82,"question":"一個過去身體健康的25歲女性，懷孕在某醫院婦產科定期接受產前檢查，檢查結果都正常，她後來自然產生出一個足月男嬰，但在生產後她很快出現呼吸急促、心跳加快、發紺（cyanosis）與血壓下降，接著出現痙攣與失去意識，請問下列情形是最可能出現在此病人的情況？","options":["(A) 肺動脈血管管腔出現空氣阻塞","(B) 肺動脈血管管腔出現骨髓（bone marrow）","(C) 肺動脈血管管腔中出現鱗狀上皮細胞（squamous epithelial cells）","(D) 肺動脈血管管腔出現血栓栓塞（thromboembolism）"],"answer":2,"image":""},{"id":"md2-111-2-83","subject":"md2","topic":"病理-心血管血液","meta":"111年第2次第83題","year":111,"session":2,"number":83,"question":"60歲男性因為心肌梗塞（myocardial infarct）引起的心肌破裂而死亡，心肌破裂的最常見時間與當時的顯微鏡下變化為何？","options":["(A) 心肌梗塞後1天，心肌細胞出現凝固性壞死（coagulation necrosis）","(B) 心肌梗塞後3天，心肌細胞出現凝固性壞死與嗜中性白血球（neutrophil）浸潤","(C) 心肌梗塞後7天，心肌細胞出現凝固性壞死與巨噬細胞（macrophage）浸潤","(D) 心肌梗塞後10天，肉芽組織（granulation tissue）形成"],"answer":1,"image":""},{"id":"md2-111-2-84","subject":"md2","topic":"病理-心血管血液","meta":"111年第2次第84題","year":111,"session":2,"number":84,"question":"下列何種出血性疾病，最可能造成微血管病性溶血性貧血（microangiopathic hemolytic anemia）？","options":["(A) 血栓性血小板減少性紫斑症（thrombotic thrombocytopenic purpura）","(B) 馮維勒布蘭德病（von Willebrand disease）","(C) 慢性免疫性血小板減少性紫斑症（chronic immune thrombocytopenic purpura）","(D) 急性免疫性血小板減少性紫斑症（acute immune thrombocytopenic purpura）"],"answer":0,"image":""},{"id":"md2-111-2-85","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"111年第2次第85題","year":111,"session":2,"number":85,"question":"12歲男孩因腹痛求診，影像檢查發現迴盲區（ileocecal region）腫瘤導致腸套疊，腫瘤切片顯示瀰漫浸潤的中等大小淋巴球，且有散布的巨噬細胞形成星空樣模式（starry-sky pattern），腫瘤細胞表現CD20及CD10，但並未表現BCL2及TdT。此種腫瘤最常有下列何種基因轉位？","options":["(A) MYC","(B) ALK","(C) BCL2","(D) BCL6"],"answer":0,"image":""},{"id":"md2-111-2-86","subject":"md2","topic":"病理-呼吸消化","meta":"111年第2次第86題","year":111,"session":2,"number":86,"question":"下列有關肺水腫之敘述何者錯誤？","options":["(A) 可見到源自淋巴球之心衰竭細胞","(B) 可由肺泡壁微血管損傷引起","(C) 可由肺部靜水壓升高引起","(D) 可造成肺部感染"],"answer":0,"image":""},{"id":"md2-111-2-87","subject":"md2","topic":"病理-呼吸消化","meta":"111年第2次第87題","year":111,"session":2,"number":87,"question":"有關特發性肺纖維化（idiopathic pulmonary fibrosis）的敘述，下列何者錯誤？","options":["(A) 常出現於雙側肺葉","(B) 男性比女性常見","(C) 患者以小於50歲的年輕人居多","(D) 後期可見蜂巢樣纖維化"],"answer":2,"image":""},{"id":"md2-111-2-88","subject":"md2","topic":"病理-呼吸消化","meta":"111年第2次第88題","year":111,"session":2,"number":88,"question":"60歲女性有抽菸史，主訴咳嗽、胸痛及體重下降。胸部X-ray顯示，有一陰影，組織圖如下，其最可能的診斷為：","options":["(A) 小細胞癌","(B) 腺癌","(C) 鱗狀上皮細胞癌","(D) 分化不良癌"],"answer":2,"image":"md2-111-2-88.jpeg"},{"id":"md2-111-2-89","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"111年第2次第89題","year":111,"session":2,"number":89,"question":"承上題，其癌細胞最有可能轉移至何處？","options":["(A) 皮膚","(B) 心臟","(C) 肝臟","(D) 脾臟"],"answer":2,"image":""},{"id":"md2-111-2-90","subject":"md2","topic":"病理-呼吸消化","meta":"111年第2次第90題","year":111,"session":2,"number":90,"question":"關於Alpha1-antitrypsin deficiency的敘述，下列何者錯誤？","options":["(A) 肝細胞含有periodic acid-Schiff（PAS）染色陽性的圓形細胞質球狀內含物（globular inclusions），此球狀內含物可被澱粉酶分解（PAS-positive and diastase-sensitive）","(B) 最常見的突變是PiZ，PiZZ homozygotes的血中的Alpha1-antitrypsin僅為正常值的10％","(C) 可能以新生兒肝炎來表現，可能發展為膽汁淤積，壞死，慢性肝炎","(D) 與肺氣腫相關"],"answer":0,"image":""},{"id":"md2-111-2-91","subject":"md2","topic":"病理-呼吸消化","meta":"111年第2次第91題","year":111,"session":2,"number":91,"question":"以下何者與大腸癌發生的風險最無關？","options":["(A) 絨毛狀腺瘤（villous adenoma）","(B) 增生性息肉（hyperplastic polyp）","(C) 家族性腺瘤樣息肉症（familial adenomatous polyposis）","(D) 青少年息肉症候群（juvenile polyposis syndrome）"],"answer":1,"image":""},{"id":"md2-111-2-92","subject":"md2","topic":"病理-呼吸消化","meta":"111年第2次第92題","year":111,"session":2,"number":92,"question":"下列何者是最常見的唾液腺良性腫瘤？","options":["(A) 多形性腺瘤（pleomorphic adenoma）","(B) Warthin腫瘤（Warthin tumor）","(C) 嗜酸細胞瘤（oncocytoma）","(D) 基底細胞腺瘤（basal cell adenoma）"],"answer":0,"image":""},{"id":"md2-111-2-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"111年第2次第93題","year":111,"session":2,"number":93,"question":"40歲女性，十年前因經常頭痛而自行購買含phenacetin複方止痛藥，且常合併服用阿斯匹靈（aspirin），目前腎功能下降，病理巨觀發現腎乳突脫落，有關此病患的相關病理變化中，下列何者最不正確？","options":["(A) 病灶常見鈣化","(B) 腎乳突壞死","(C) 會引起慢性腎小管間質性腎炎","(D) 超過90%的病患合併有尿路感染"],"answer":3,"image":""},{"id":"md2-111-2-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"111年第2次第94題","year":111,"session":2,"number":94,"question":"65歲男病人呈現嚴重的蛋白尿。腎臟切片檢查顯示腎絲球病變中並無免疫複合體或補體沉積。根據本題圖示及病人臨床表現，下列腎病中何者是最可能的病理診斷？","options":["(A) membranous nephropathy","(B) diabetic glomerulopathy","(C) minimal change nephropathy","(D) IgA nephropathy"],"answer":1,"image":"md2-111-2-94.jpeg"},{"id":"md2-111-2-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"111年第2次第95題","year":111,"session":2,"number":95,"question":"下列何種睪丸的情況，可出現典型的橡皮腫（gumma）？","options":["(A) 輸精管結紮","(B) 梅毒","(C) 結核病","(D) 淋病"],"answer":1,"image":""},{"id":"md2-111-2-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"111年第2次第96題","year":111,"session":2,"number":96,"question":"下列有關尖狀濕疣（condyloma acuminatum）的敘述，何者較不正確？","options":["(A) 為一良性（benign）疾病，且不被認為是癌前期（precancerous）病灶","(B) 與人類乳突狀病毒（human papillomavirus）的感染有關","(C) 臨床上，其病灶可以是單個，但多個病灶的情形較為常見","(D) 在病灶上皮的基底層部位，會出現所謂的空泡狀異常（koilocytic atypia）"],"answer":[0,3],"image":"","answer_note":"更正:第96題答Ａ或Ｄ或AD者均給分"},{"id":"md2-111-2-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"111年第2次第97題","year":111,"session":2,"number":97,"question":"下列何種乳癌的預後最差？","options":["(A) 化生癌（metaplastic carcinoma）","(B) 侵襲性小葉癌（invasive lobular carcinoma）","(C) 管狀癌（tubular carcinoma）","(D) 黏液癌（mucinous carcinoma）"],"answer":0,"image":""},{"id":"md2-111-2-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"111年第2次第98題","year":111,"session":2,"number":98,"question":"16歲女生最近在右小腿靠近膝關節處有腫脹及疼痛感。電腦斷層掃描發現在右脛骨（tibia）上端有一疑似腫瘤病灶，其具有膨脹性溶解病變（expansile lytic lesion）且外覆一層薄的骨密質（thin shell of reactive bone）。病理切片檢查顯示其組成包括含有血之囊腫（blood-filled cystic space）混雜著纖維組織、fibroblast、woven bone和類似蝕骨細胞之巨細胞（osteoclast-like giant cell）。根據上述，該病人最可能罹患的疾病是：","options":["(A) 海綿狀血管瘤（cavernous hemangioma）","(B) 骨母細胞瘤（osteoblastoma）","(C) 骨巨細胞瘤（giant cell tumor of bone）","(D) 動脈瘤樣骨性囊腫（aneurysmal bone cyst）"],"answer":3,"image":""},{"id":"md2-111-2-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"111年第2次第99題","year":111,"session":2,"number":99,"question":"包涵體肌炎（inclusion body myositis）患者之肌肉切片在Gomori trichrome stain下觀察到的包涵體（cytoplasmic inclusion）稱為：","options":["(A) Hirano body","(B) rimmed vacuole","(C) Negri body","(D) nemaline rod"],"answer":1,"image":""},{"id":"md2-111-2-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"111年第2次第100題","year":111,"session":2,"number":100,"question":"眼睛的惡性黑色素瘤（Malignant melanoma）發生於下列何處時，通常會有較慢的發展進程（indolent course）？","options":["(A) 虹膜（iris）","(B) 視網膜（retina）","(C) 脈絡膜（choroid）","(D) 睫狀體（ciliary body）"],"answer":0,"image":""},{"id":"md2-112-1-1","subject":"md2","topic":"細菌學","meta":"112年第1次第1題","year":112,"session":1,"number":1,"question":"一個5歲小男孩被診斷出細菌性肺炎，從檢體培養出主要具有alpha溶血能力、觸酶（catalase）陰性，且帶有莢膜（capsule）的細菌，最可能是下列何種細菌？","options":["(A) 化膿性鏈球菌（Streptococcus pyogenes）","(B) 肺炎鏈球菌（Streptococcus pneumoniae）","(C) 表皮葡萄球菌（Staphylococcus epidermidis）","(D) 金黃色葡萄球菌（Staphylococcus aureus）"],"answer":1,"image":""},{"id":"md2-112-1-2","subject":"md2","topic":"藥理-化學治療","meta":"112年第1次第2題","year":112,"session":1,"number":2,"question":"肺炎黴漿菌（Mycoplasma pneumoniae）對於β-內醯胺（β-lactam）類藥物如碳青黴烯（carbapenems）具有抗藥性，最有可能的原因為何？","options":["(A) 青黴素結合蛋白質（penicillin-binding protein）產生突變","(B) 不具有胜肽聚糖（peptidoglycan）結構","(C) 能分泌強力β-內醯胺酶（β-lactamase）","(D) 能有效地將藥物排出菌體外"],"answer":1,"image":""},{"id":"md2-112-1-3","subject":"md2","topic":"細菌學","meta":"112年第1次第3題","year":112,"session":1,"number":3,"question":"有關砂眼的敘述，下列何者最不適當？","options":["(A) 通常由血清型（serovars）A, B, Ba, C砂眼披衣菌（Chlamydia trachomatis）感染造成","(B) 最嚴重會導致角膜結痂，並可能造成失明的併發症","(C) 除了眼睛分泌物，亦可透過帶菌的呼吸道飛沫或糞便傳染","(D) 症狀消除後一般即可痊癒，不會再復發"],"answer":3,"image":""},{"id":"md2-112-1-4","subject":"md2","topic":"細菌學","meta":"112年第1次第4題","year":112,"session":1,"number":4,"question":"一位上班族抱怨左上腹疼痛，醫生開立呼氣測試，主要目的是測試病人是否感染下列何種細菌？該菌具有何種酵素的活性？應偵測何種氣體？","options":["(A) 傷寒沙門氏菌（Salmonella Typhi），蛋白酶（protease），氧氣（O2）","(B) 空腸彎曲桿菌（Campylobacter jejuni），尿素酶（urease），二氧化碳（CO2）","(C) 胃幽門桿菌（Helicobacter pylori），尿素酶（urease），二氧化碳（CO2）","(D) 大腸桿菌（Escherichia coli），蛋白酶（protease），氧氣（O2）"],"answer":2,"image":""},{"id":"md2-112-1-5","subject":"md2","topic":"細菌學","meta":"112年第1次第5題","year":112,"session":1,"number":5,"question":"關於退伍軍人菌屬（Legionella）的敘述，下列何者最不適當？","options":["(A) 雖為革蘭氏陰性（Gram-negative）桿菌，但不易以常規染劑染色","(B) 為兼性細胞內寄生菌，可寄生在宿主巨噬細胞（macrophage）內並繁殖","(C) 主要存在水域環境，如天然湖泊及人工的供水系統內","(D) 對生長條件不挑剔，可使用血培養基（blood agar）加以培養分離"],"answer":3,"image":""},{"id":"md2-112-1-6","subject":"md2","topic":"細菌學","meta":"112年第1次第6題","year":112,"session":1,"number":6,"question":"一位25歲婦女因為高燒、頭痛、手腳胸口都有紅色斑丘疹（erythematous maculopapular rash）住院，培養血液樣本發現只有以加強營養成分的巧克力瓊脂（enriched chocolate agar）可以培養出該菌，染色後發現是革蘭氏陰性球菌，此婦女最可能感染的是下列何種細菌？","options":["(A) 金氏金氏菌（Kingella kingae）","(B) 淋病雙球菌（Neisseria gonorrhoeae）","(C) 侵蝕愛啃菌（Eikenella corrodens）","(D) 腦膜敗血伊莉莎白菌（Elizabethkingia meningoseptica）"],"answer":1,"image":""},{"id":"md2-112-1-7","subject":"md2","topic":"細菌學","meta":"112年第1次第7題","year":112,"session":1,"number":7,"question":"下列何種細菌產生之A-B毒素（A-B toxin）會造成腹痛、腹瀉等症狀？","options":["(A) 金黃色葡萄球菌（Staphylococcus aureus）之腸毒素（enterotoxins）","(B) 產氣莢膜梭狀芽孢桿菌（Clostridium perfringens）之α毒素（α toxin）","(C) 霍亂弧菌（Vibrio cholerae）之霍亂毒素（cholera toxin）","(D) 單核細胞增多性李斯特菌（Listeria monocytogenes）之李斯特菌溶血素O（listeriolysin O）"],"answer":2,"image":""},{"id":"md2-112-1-8","subject":"md2","topic":"細菌學","meta":"112年第1次第8題","year":112,"session":1,"number":8,"question":"有關破傷風桿菌（Clostridium tetani）的敘述，下列何者最不適當？","options":["(A) 破傷風類毒素（toxoid）可當做有效的疫苗","(B) 有群體免疫（herd immunity）的現象存在，可降低感染罹病的機會","(C) 造成痙攣性的肌肉麻痺","(D) 此菌可產生內孢子（endospore）"],"answer":1,"image":""},{"id":"md2-112-1-9","subject":"md2","topic":"細菌學","meta":"112年第1次第9題","year":112,"session":1,"number":9,"question":"下列何者細菌屬於生長緩慢、菌落無色素（nonpigmented colonies），顯微鏡下呈聚集現象（aggregation）的抗酸性（acid-fast）桿菌？","options":["(A) 金黃色葡萄球菌（Staphylococcus aureus）","(B) 結核分枝桿菌（Mycobacterium tuberculosis）","(C) 綠膿桿菌（Pseudomonas aeruginosa）","(D) 鬆脆類桿菌（Bacteroides fragilis）"],"answer":1,"image":""},{"id":"md2-112-1-10","subject":"md2","topic":"藥理-化學治療","meta":"112年第1次第10題","year":112,"session":1,"number":10,"question":"抗C型肝炎病毒（HCV）的藥物雷巴威林（Ribavirin），是抑制該病毒複製的那一項步驟？","options":["(A) 接觸（attachment）","(B) 穿過細胞膜及解散外殼","(C) 病毒RNA的生合成","(D) 蛋白質合成"],"answer":2,"image":""},{"id":"md2-112-1-11","subject":"md2","topic":"病毒學","meta":"112年第1次第11題","year":112,"session":1,"number":11,"question":"下列有關沙狀病毒（arenavirus）的敘述何者最不適當？","options":["(A) 病毒顆粒中含核糖體（ribosome）","(B) 病毒經由蚊子傳播","(C) 病毒可經由空氣傳播","(D) 病毒感染會造成腦膜炎及出血性症狀"],"answer":1,"image":""},{"id":"md2-112-1-12","subject":"md2","topic":"免疫學","meta":"112年第1次第12題","year":112,"session":1,"number":12,"question":"下列何種檢驗結果可以用來區分「未曾感染過但曾經接種B型肝炎病毒疫苗」與「曾經感染B型肝炎病毒但已經康復」的個體？","options":["(A) Anti-HBc抗體陽性","(B) Anti-HBs抗體陽性","(C) HBs抗原陰性","(D) HBe抗原陰性"],"answer":0,"image":""},{"id":"md2-112-1-13","subject":"md2","topic":"病毒學","meta":"112年第1次第13題","year":112,"session":1,"number":13,"question":"下列何者不屬於小RNA病毒科（Picornaviridae）？","options":["(A) Poliovirus","(B) B19 virus","(C) Hepatitis A virus","(D) Rhinovirus"],"answer":1,"image":""},{"id":"md2-112-1-14","subject":"md2","topic":"病毒學","meta":"112年第1次第14題","year":112,"session":1,"number":14,"question":"有關登革熱病毒（Dengue virus）的敘述，下列何者最不適當？","options":["(A) 是一個arbovirus","(B) 與茲卡病毒（Zika virus）屬相同病毒科（family）","(C) 患者將獲終身免疫","(D) 感染後可能引起出血熱（hemorrhagic fever）"],"answer":2,"image":""},{"id":"md2-112-1-15","subject":"md2","topic":"病毒學","meta":"112年第1次第15題","year":112,"session":1,"number":15,"question":"有關人類D型肝炎病毒（human hepatitis D virus）的敘述，下列何者正確？","options":["(A) 主要藉由糞口傳染","(B) 可藉由施打B型肝炎疫苗來預防感染","(C) D型肝炎病毒感染會促進HBsAg的抗體陽轉反應（positive conversion）","(D) 需要B型肝炎病毒的HBc蛋白質，才能產生具感染性的病毒顆粒"],"answer":1,"image":""},{"id":"md2-112-1-16","subject":"md2","topic":"藥理-化學治療","meta":"112年第1次第16題","year":112,"session":1,"number":16,"question":"麴菌（Aspergillus）CYP51A基因突變是產生下列何種藥物抗藥性的主要原因？","options":["(A) 三唑（triazole）","(B) 棘白菌素（echinocandin）","(C) 多烯（polyene）","(D) 烯丙胺（allylamines）"],"answer":0,"image":""},{"id":"md2-112-1-17","subject":"md2","topic":"真菌學","meta":"112年第1次第17題","year":112,"session":1,"number":17,"question":"在HIV/AIDS患者血液培養分離到一株真菌，此菌在25℃呈絲狀（filamentous），並產生鮮紅色的色素滲入培養基，35℃下菌落為酵母菌狀（yeasts），最有可能是下列何者？","options":["(A) Emergomyces pasteurianus","(B) Scedosporium apiospermum","(C) Paracoccidioides brasiliensis","(D) Talaromyces marneffei"],"answer":3,"image":""},{"id":"md2-112-1-18","subject":"md2","topic":"免疫學","meta":"112年第1次第18題","year":112,"session":1,"number":18,"question":"大部分的免疫細胞都是由骨髓中的造血幹細胞發育而來，這些免疫細胞又可以依據它們的發育源頭進一步分成骨髓系（myeloid lineage）或淋巴系（lymphoid lineage），下列那一種細胞可以由骨髓系及淋巴系前驅細胞產生？","options":["(A) 樹突細胞（dendritic cell）","(B) 先天淋巴細胞（innate lymphoid cell, ILC）","(C) 紅血球（red blood cell）","(D) 巨噬細胞（macrophage）"],"answer":0,"image":""},{"id":"md2-112-1-19","subject":"md2","topic":"免疫學","meta":"112年第1次第19題","year":112,"session":1,"number":19,"question":"發炎通常是在局部感染或受傷初期所產生的免疫反應，有關發炎的敘述下列何者錯誤？","options":["(A) 產生發炎的目的是藉由免疫效應分子（immune effector molecule）的增加去攻擊病原菌並促進傷口的癒合","(B) 發炎所伴隨的紅、腫、熱、痛是由病原菌在複製過程中所釋放的毒力因子（virulence factor）直接造成的結果","(C) 發炎會增加血管壁的通透性，使血液中的補體成分進入發炎組織中，促進宿主的免疫反應清除病原菌","(D) 如果病原菌透過血液傳播至各個器官而引發全身性細菌感染或敗血症（sepsis）時，則會因過度發炎反應產生大量TNF-α而導致敗血性休克（septic shock）"],"answer":1,"image":""},{"id":"md2-112-1-20","subject":"md2","topic":"免疫學","meta":"112年第1次第20題","year":112,"session":1,"number":20,"question":"下列何種蛋白與MHC class II分子的抗原呈獻過程有重要關聯？","options":["(A) Calnexin","(B) Calreticulin","(C) Invariant chain","(D) Transporters associated with antigen processing（TAPs）"],"answer":2,"image":""},{"id":"md2-112-1-21","subject":"md2","topic":"免疫學","meta":"112年第1次第21題","year":112,"session":1,"number":21,"question":"下列何者是T細胞發育過程“positive selection”的最適當敘述？","options":["(A) 胸腺上皮細胞表現AIRE，此蛋白可以促進組織特異性抗原（tissue-specific antigens）在胸腺中表現","(B) 當胸腺細胞辨識到胸腺上皮細胞表面的MHC-peptide，如果引發中等以上的TCR訊號，則可以被選擇出來繼續發育","(C) 當胸腺細胞無法辨識到胸腺上皮細胞表面的MHC-peptide，則可以被選擇出來繼續發育","(D) 當胸腺細胞辨識到自己的MHC分子時，胸腺細胞就會進行細胞凋亡（apoptosis）"],"answer":1,"image":""},{"id":"md2-112-1-22","subject":"md2","topic":"免疫學","meta":"112年第1次第22題","year":112,"session":1,"number":22,"question":"在注射利什曼原蟲（Leishmania major）小鼠的實驗中，可藉由注射拮抗型IL-4抗體（anti-IL-4 antibody）而明顯增加感染小鼠存活率，此機轉主要是抑制何種免疫反應？","options":["(A) TH1 response","(B) TH17 response","(C) TH2 response","(D) chemotaxis response"],"answer":2,"image":""},{"id":"md2-112-1-23","subject":"md2","topic":"免疫學","meta":"112年第1次第23題","year":112,"session":1,"number":23,"question":"胸腺依賴性（thymus-dependent）抗原（TD抗原）及非胸腺依賴性（thymus-independent）抗原（TI抗原）都可以活化B細胞產生抗體反應，有關TD及TI抗原的敘述何者錯誤？","options":["(A) 蛋白質抗原屬於TD抗原，而且B細胞的完全活化需要兩個訊號，第一個訊號由B細胞的MHC-peptide和T細胞的TCR結合後所傳遞。第二個訊號則是由B細胞的CD40和T細胞的CD40配體（CD40 ligand）結合後所傳遞","(B) 脂多醣（lipopolysaccharide, LPS）不需要T細胞的幫忙也可以活化B細胞，是屬於第一型TI抗原（TI-1）。高劑量的LPS會引起非專一性的抗體反應。相反的，低劑量的LPS則引起專一性抗體反應","(C) TD抗原和TI-2抗原都是藉由BCR來辨識，但TI-1抗原則可以由BCR或非BCR來辨識","(D) 嬰兒容易受到具有莢膜的肺炎球菌的感染，其可能原因是嬰兒體內的B細胞尚未成熟的關係所導致"],"answer":0,"image":""},{"id":"md2-112-1-24","subject":"md2","topic":"細菌學","meta":"112年第1次第24題","year":112,"session":1,"number":24,"question":"下列有關人體內共生菌相（commensal microbiota）的敘述，何者最正確？","options":["(A) 每一個人體內不同部位的菌種都是一致的","(B) 這些菌種很特別，對抗生素具有抗藥性","(C) 體內免疫系統完全不會對這些共生菌有免疫反應","(D) 可以協助產出維生素K1與短鏈脂肪酸"],"answer":3,"image":""},{"id":"md2-112-1-25","subject":"md2","topic":"免疫學","meta":"112年第1次第25題","year":112,"session":1,"number":25,"question":"HIV會造成慢性感染而且引起後天免疫不全症（acquired immune deficiency syndrome, AIDS）造成許多人死亡，有關HIV慢性感染的原因，下列何者錯誤？","options":["(A) 在HIV感染的過程中，重要的效應細胞及分子（effector cell / molecule），如毒殺型CD8 T細胞及對HIV有專一性的抗體都沒有產生","(B) HIV在複製的過程中會導致基因的突變，使得原本有效的免疫反應失去作用","(C) HIV的病毒因子會抑制第一型MHC（MHC class I）在被感染細胞的表現，以逃脫毒殺型CD8 T（cytotoxic CD8 T）細胞的攻擊","(D) HIV會感染免疫細胞包含CD4 T細胞、樹突細胞及巨噬細胞，且造成CD4 T細胞數目的減少"],"answer":0,"image":""},{"id":"md2-112-1-26","subject":"md2","topic":"免疫學","meta":"112年第1次第26題","year":112,"session":1,"number":26,"question":"下列何種自我免疫耐受性（self-tolerance）機制的作用位置發生在發炎處？","options":["(A) central tolerance","(B) antigen segregation","(C) negative selection","(D) regulatory T cells"],"answer":3,"image":""},{"id":"md2-112-1-27","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第1次第27題","year":112,"session":1,"number":27,"question":"有關雷帕黴素（rapamycin）之作用，下列何者錯誤？","options":["(A) 與FK結合蛋白（FK-binding protein）結合","(B) 促進白血球凋亡（apoptosis）","(C) 抑制白血球增生（proliferation）","(D) 降低調節性T細胞（regulatory T cell）數目"],"answer":3,"image":""},{"id":"md2-112-1-28","subject":"md2","topic":"免疫學","meta":"112年第1次第28題","year":112,"session":1,"number":28,"question":"利用基因工程製備嵌合抗原受體T細胞（chimeric antigen receptor T cells, CAR-T）作為免疫細胞治療方式已經成功用來治療ALL（acute lymphocytic leukemia），在此嵌合分子之組成中不包括下列何者？","options":["(A) anti-CD19","(B) CTLA-4","(C) 4-1 BB","(D) CD3ζ chain"],"answer":1,"image":""},{"id":"md2-112-1-29","subject":"md2","topic":"寄生蟲學","meta":"112年第1次第29題","year":112,"session":1,"number":29,"question":"下列有關棘頜口線蟲（Gnathostoma spinigerum）感染的敘述，何者錯誤？","options":["(A) 成蟲可寄生於貓的胃壁","(B) 完成生活史需2個中間宿主","(C) 感染人體後只侵犯皮下組織","(D) 食入未熟帶蟲之淡水魚而被感染"],"answer":2,"image":""},{"id":"md2-112-1-30","subject":"md2","topic":"寄生蟲學","meta":"112年第1次第30題","year":112,"session":1,"number":30,"question":"下列何種寄生蟲感染，最有可能造成一種咽喉型的病症（halzoun），導致咽喉劇烈疼痛、出血及呼吸困難？","options":["(A) 牛羊肝吸蟲（Fasciola hepatica）","(B) 貓肝吸蟲（Opisthorchis felineus）","(C) 槍狀肝吸蟲（Dicrocoelium dendriticum）","(D) 泰國肝吸蟲（Opisthorchis viverrini）"],"answer":0,"image":""},{"id":"md2-112-1-31","subject":"md2","topic":"寄生蟲學","meta":"112年第1次第31題","year":112,"session":1,"number":31,"question":"下列何種寄生蟲感染會導致人類肺部的病變？","options":["(A) 犬複殖器絛蟲（Dipylidium caninum）","(B) 顆粒性包生絛蟲（Echinococcus granulosus）","(C) 廣節裂頭絛蟲（Diphyllobothrium latum）","(D) 短小包膜絛蟲（Hymenolepis nana）"],"answer":1,"image":""},{"id":"md2-112-1-32","subject":"md2","topic":"寄生蟲學","meta":"112年第1次第32題","year":112,"session":1,"number":32,"question":"有關利什曼原蟲（Leishmania spp.）的敘述，下列何者正確？","options":["(A) 前鞭毛體（promastigote）在脊椎動物宿主體內會被巨噬細胞（macrophage）吞噬後形成無鞭毛體（amastigote）","(B) 在中間宿主體內，會因為氧氣分壓降低而導致蟲體外型鞭毛縮短，轉變成為無鞭毛體","(C) 有關利什曼原蟲的分類，可以借助中間宿主的種株（species）來決定","(D) 當無鞭毛體進入中間宿主腸道後段時，會受到腸道內皮細胞的影響，轉化變形成為循環後期錐鞭毛體（metacyclic trypomastigote）"],"answer":0,"image":""},{"id":"md2-112-1-33","subject":"md2","topic":"寄生蟲學","meta":"112年第1次第33題","year":112,"session":1,"number":33,"question":"下列症狀中何者與枯西氏錐蟲（Trypanosoma cruzi）之感染症無關？","options":["(A) 單側眼瞼水腫（Romaña's sign）","(B) 心肌炎（myocarditis）","(C) 巨結腸（megacolon）","(D) 黑熱病（kala-azar）"],"answer":3,"image":""},{"id":"md2-112-1-34","subject":"md2","topic":"寄生蟲學","meta":"112年第1次第34題","year":112,"session":1,"number":34,"question":"有關瘧原蟲（Plasmodium spp.）在病媒蚊體內之發育，下列敘述何者錯誤？","options":["(A) 瘧蚊叮咬感染宿主而吸入雌或雄配子母細胞（gametocyte）","(B) 受精合子（zygote）發育成具活性卵動子（ookinete）","(C) 卵動子鑽入蚊唾液腺發育成孢子體（sporozoites）","(D) 依瘧原蟲種類不同，在蚊體內生長發育約8～35日不等時程"],"answer":2,"image":""},{"id":"md2-112-1-35","subject":"md2","topic":"寄生蟲學","meta":"112年第1次第35題","year":112,"session":1,"number":35,"question":"下列何者為曾經流行於臺澎金馬及中國南方地區之班氏絲蟲（Wuchereria bancrofti）的主要傳播病媒？","options":["(A) 埃及斑蚊（Aedes aegypti）","(B) 白線斑蚊（Aedes albopictus）","(C) 熱帶家蚊（Culex quinquefasciatus / C. fatigans）","(D) 微小瘧蚊（Anopheles minimus）"],"answer":2,"image":""},{"id":"md2-112-1-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第1次第36題","year":112,"session":1,"number":36,"question":"假設某研究利用100人之樣本評估12歲兒童的智力測驗分數（IQ，範圍80～140分）與產前暴露到多氯聯苯（Polychlorinated biphenyls, PCBs，範圍500～1800 ng/g of Fat）之關係，建構其迴歸模式如下：ÎQ=125.7- 2 0.02×PCBs，迴歸模式之判定係數（R）為0.4。下列敘述何者最正確？","options":["(A) IQ與PCBs的Pearson相關係數為 -0.02，呈負相關","(B) 此模式之依變項（dependent variable）為PCBs，自變項（independent variable）為IQ","(C) 若PCBs增加了500個單位，則IQ估計值下降1分","(D) 2判定係數（R）為0.4，顯示IQ之變異約40%無法被PCBs解釋"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第36題一律給分 (原公告答案 C)"},{"id":"md2-112-1-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第1次第37題","year":112,"session":1,"number":37,"question":"過去研究曾發現X1因素會導致胰臟癌的風險增加，然而X1因素暴露者亦有較高X2因素的暴露，由於X2因素已知是胰臟癌的危險因子，在統計分析時控制X2因素後，X1因素與胰臟癌的相關性消失，則X2因素對於X1因素與胰臟癌關係中扮演何種角色？","options":["(A) 致病因子","(B) 干擾因子","(C) 隨機因子","(D) 促使因子"],"answer":1,"image":""},{"id":"md2-112-1-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第1次第38題","year":112,"session":1,"number":38,"question":"一研究發現各國的乳癌發生率與女性高血脂盛行率呈現正向關係，因此判定女性若高血脂容易導致乳癌。此推論最可能犯下何種問題？","options":["(A) 型一錯誤（type I error）","(B) 生態謬誤（ecological fallacy）","(C) 訊息偏差（information bias）","(D) 干擾（confounding）"],"answer":1,"image":""},{"id":"md2-112-1-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第1次第39題","year":112,"session":1,"number":39,"question":"醫療檢測數據呈現明顯右偏分布，下列何組指標最適合測量此群資料之集中與分散狀況？","options":["(A) 平均值，標準差","(B) 平均值，標準誤","(C) 中位數，四分位距","(D) 中位數，全距"],"answer":2,"image":""},{"id":"md2-112-1-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"112年第1次第40題","year":112,"session":1,"number":40,"question":"下列關於臭氧在全球環境變遷的敘述，何者最為恰當？","options":["(A) 臭氧層的稀薄連帶使得地表臭氧濃度降低","(B) 溫室效應可能造成地表臭氧濃度增加","(C) 臭氧稀薄現象最早發現在北極地區","(D) 導致臭氧稀薄的主因是氟氯碳化物中的氟原子與臭氧產生連鎖反應"],"answer":1,"image":""},{"id":"md2-112-1-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"112年第1次第41題","year":112,"session":1,"number":41,"question":"鉛目前仍然為我國工業使用量最大的有毒重金屬之一，其進入環境的分布也是最廣泛的，自從公元2000年我國停用含鉛汽油（高級汽油）後，一般民眾血液內的鉛濃度就降下來，在環境衛生與職業衛生上，下列敘述何者最不恰當？","options":["(A) 急性鉛中毒可分為有機鉛與無機鉛中毒，主要症狀不同。其中無機鉛急性中毒主要在中樞神經系統，嚴重者會有幻覺","(B) 鉛中毒的預防重點在職業衛生，避免工人暴露鉛粉塵作業","(C) 如果玩具品質不良，其上的色料可能成為兒童鉛暴露的來源","(D) 老舊的建築，其中的水管可能有含鉛的原料"],"answer":0,"image":""},{"id":"md2-112-1-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"112年第1次第42題","year":112,"session":1,"number":42,"question":"要預防人因性（ergonomics）危害，下列何者最無相關？","options":["(A) 良好物料搬運習慣","(B) 正確姿勢","(C) 避免重複性的工作內容","(D) 避免同儕間之肢體暴力與語言暴力"],"answer":3,"image":""},{"id":"md2-112-1-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"112年第1次第43題","year":112,"session":1,"number":43,"question":"針對職業衛生中所稱「短時間時量平均容許濃度」，下列何者為最常使用之評估時間長度？","options":["(A) 1分鐘","(B) 15分鐘","(C) 30分鐘","(D) 60分鐘"],"answer":1,"image":""},{"id":"md2-112-1-44","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第1次第44題","year":112,"session":1,"number":44,"question":"衛生福利部國民健康署為了預防青少年吸電子煙對健康造成影響，請當紅偶像明星拍攝拒吸電子煙的影片進行宣導，青少年仿效偶像明星拒吸電子煙的行動，進而降低其吸電子煙比率。上述是運用何項行為改變策略？","options":["(A) 社會支持","(B) 自我監測","(C) 訊息回饋","(D) 觀察學習"],"answer":3,"image":""},{"id":"md2-112-1-45","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第1次第45題","year":112,"session":1,"number":45,"question":"下列關於健康的敘述，何者最不恰當？","options":["(A) 健康的定義就是身體沒有疾病","(B) 社會角色與功能健全是健康的要素","(C) 根據聯合國人權宣言，健康是基本人權的一環","(D) 根據1974年加拿大拉朗德報告（Lalonde Report），健康行為和生活型態是影響健康的重要元素，而不應該過度依賴醫療"],"answer":0,"image":""},{"id":"md2-112-1-46","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第1次第46題","year":112,"session":1,"number":46,"question":"進行吸菸者戒菸衛教時，先讓吸菸者觀看吸菸造成身體健康危害的恐怖影片後，接著告知吸菸者戒菸的好處。前述情形最符合下列那一種說服理論？","options":["(A) 恐懼訴求","(B) 情感利益訴求","(C) 啟發性訴求","(D) 理性訴求"],"answer":1,"image":""},{"id":"md2-112-1-47","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"112年第1次第47題","year":112,"session":1,"number":47,"question":"依據長期照顧服務法，團體家屋（group home）屬於下列何種長期照顧服務類型？","options":["(A) 家庭照顧者支持服務","(B) 社區式服務","(C) 居家式服務","(D) 機構住宿式服務"],"answer":1,"image":""},{"id":"md2-112-1-48","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"112年第1次第48題","year":112,"session":1,"number":48,"question":"下列何者為健康保險論質計酬（pay for performance）的主要缺點？","options":["(A) 缺乏節約的誘因","(B) 不易被醫療供給者接受","(C) 醫療服務生產力降低","(D) 提供挑選輕症病人的誘因"],"answer":3,"image":""},{"id":"md2-112-1-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"112年第1次第49題","year":112,"session":1,"number":49,"question":"下列對於臺灣衛生福利行政組織的敘述，何者最不恰當？","options":["(A) 臺灣衛生行政組織分為二級：中央、直轄市及縣（市）","(B) 我國衛生行政體系並非為「一條鞭制」","(C) 有關中藥藥品查驗，是屬於衛生福利部食品藥物管理署的權責範圍","(D) 衛生福利部國民健康署的權責主要是負責國民健康業務，但不包含傳染病防疫"],"answer":2,"image":""},{"id":"md2-112-1-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"112年第1次第50題","year":112,"session":1,"number":50,"question":"平衡計分卡（balanced scorecard）是醫院管理當中的那一種管理方法？","options":["(A) 策略管理","(B) 財務管理","(C) 人力資源管理","(D) 資材管理"],"answer":0,"image":""},{"id":"md2-112-1-51","subject":"md2","topic":"藥理-總論與自主神經","meta":"112年第1次第51題","year":112,"session":1,"number":51,"question":"下列何者在固定濃度下，無法被持續增高濃度的致效劑（agonist）逆轉其效能（efficacy）？","options":["(A) 競爭性拮抗劑（competitive antagonist）","(B) 非競爭性拮抗劑（noncompetitive antagonist）","(C) 反促效劑（inverse agonist）","(D) 部分促效劑（partial agonist）"],"answer":1,"image":""},{"id":"md2-112-1-52","subject":"md2","topic":"藥理-化學治療","meta":"112年第1次第52題","year":112,"session":1,"number":52,"question":"關於rifampin產生的作用，下列敘述何者錯誤？","options":["(A) 抗藥性產生可能是結合到DNA聚合酶的能力降低","(B) 於開放性肺結核病，必須與isoniazid併用，以預防抗藥性的發生","(C) 會加速methadone或anticoagulants排除，是因為能誘發細胞色素P450（cytochrome P450）","(D) 與其他rifamycin類的藥物會有交叉抗藥性（cross-resistance）產生"],"answer":0,"image":""},{"id":"md2-112-1-53","subject":"md2","topic":"藥理-化學治療","meta":"112年第1次第53題","year":112,"session":1,"number":53,"question":"下列抗癌藥物與其主要產生毒性之配對，何者錯誤？","options":["(A) doxorubicin－心臟毒性","(B) oxaliplatin－周邊感覺神經病變","(C) vincristine－肺纖維化","(D) cyclophosphamide－出血性膀胱炎"],"answer":2,"image":""},{"id":"md2-112-1-54","subject":"md2","topic":"藥理-化學治療","meta":"112年第1次第54題","year":112,"session":1,"number":54,"question":"Pembrolizumab為免疫檢查點抑制劑（immune checkpoint inhibitor），可用於治療癌症，下列何者為此單株抗體專一性結合的蛋白？","options":["(A) epidermal growth factor receptor（EGFR）","(B) programmed death-1 receptor（PD-1）","(C) programmed death ligand 1（PD-L1）","(D) cytotoxic T-lymphocyte-associated antigen 4（CTLA-4）"],"answer":1,"image":""},{"id":"md2-112-1-55","subject":"md2","topic":"藥理-化學治療","meta":"112年第1次第55題","year":112,"session":1,"number":55,"question":"林先生因車禍受傷，傷口已化膿才就醫，經檢驗為β-lactamase positive金黃色葡萄球菌（Staphylococcus aureus）感染，下列何種抗生素最適合用於治療？","options":["(A) ampicillin","(B) dicloxacillin","(C) penicillin G","(D) piperacillin"],"answer":1,"image":""},{"id":"md2-112-1-56","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"112年第1次第56題","year":112,"session":1,"number":56,"question":"有關預防性抗血栓藥物（antithrombotic drug）rivaroxaban之相關敘述，下列何者錯誤？","options":["(A) 主要機制為抑制凝血因子Xa作用","(B) 可用於治療靜脈血栓症","(C) 年長者使用時，應注意此藥物之半衰期會縮短","(D) 目前andexanet alfa為直接性解毒劑"],"answer":2,"image":""},{"id":"md2-112-1-57","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第1次第57題","year":112,"session":1,"number":57,"question":"下列關於可刺激子宮肌肉收縮（oxytocic action）自泌素及其相關藥物之敘述，何者錯誤？","options":["(A) PGE2及PGF2α具強效收縮作用","(B) misoprostol具類似PGF2α之作用","(C) dinoprostone具類似PGE2之作用","(D) carboprost具類似PGF2α之作用"],"answer":1,"image":""},{"id":"md2-112-1-58","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"112年第1次第58題","year":112,"session":1,"number":58,"question":"Simvastatin主要療效在於降低血中LDL含量，同時具有緩解血管發炎及粥狀動脈形成的作用。此藥物主要之作用機制為何？","options":["(A) 活化PPAR-α受體","(B) 抑制HMG-CoA reductase活性","(C) 抑制腸道運輸蛋白NPC1L1","(D) 與膽酸（bile acid）結合"],"answer":1,"image":""},{"id":"md2-112-1-59","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第1次第59題","year":112,"session":1,"number":59,"question":"下列何種藥物的主要作用對象，不是G蛋白耦合受體（G protein-couple receptor, GPCR）？","options":["(A) somatotropin","(B) bromocriptine","(C) desmopressin","(D) leuprolide"],"answer":0,"image":""},{"id":"md2-112-1-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第1次第60題","year":112,"session":1,"number":60,"question":"下列何種藥物主要作用對象為雌激素受體，可治療停經後婦女的骨質疏鬆？","options":["(A) omeprazole","(B) denosumab","(C) raloxifene","(D) prednisolone"],"answer":2,"image":""},{"id":"md2-112-1-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第1次第61題","year":112,"session":1,"number":61,"question":"下列何種腎上腺皮質素拮抗劑的作用，係透過抑制膽固醇（cholesterol）轉換成孕烯醇酮（pregnenolone）的作用，來阻斷皮質醇和皮質酮的生合成？","options":["(A) aminoglutethimide","(B) metyrapone","(C) mifepristone","(D) trilostane"],"answer":0,"image":""},{"id":"md2-112-1-62","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"112年第1次第62題","year":112,"session":1,"number":62,"question":"下列何者具有在中樞轉換成α-methylnorepinephrine的作用，可以適用於腎功能不全的高血壓患者？","options":["(A) clonidine","(B) captopril","(C) methyldopa","(D) minoxidil"],"answer":2,"image":""},{"id":"md2-112-1-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"112年第1次第63題","year":112,"session":1,"number":63,"question":"下列降血壓藥何者具有ATP-sensitive K-channel活化作用，會使動脈血管擴張，但會抑制insulin釋放？","options":["(A) fenoldopam","(B) captopril","(C) diazoxide","(D) minoxidil"],"answer":2,"image":""},{"id":"md2-112-1-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"112年第1次第64題","year":112,"session":1,"number":64,"question":"下列關於sacubitril的敘述，何者錯誤？","options":["(A) 可活化brain natriuretic peptide受體","(B) 可和valsartan合併使用","(C) 可引起血管擴張","(D) 用於治療慢性心臟衰竭"],"answer":0,"image":""},{"id":"md2-112-1-65","subject":"md2","topic":"藥理-總論與自主神經","meta":"112年第1次第65題","year":112,"session":1,"number":65,"question":"下列局部點眼藥中，何者無法降低眼壓，對隅角開放性青光眼（open-angle glaucoma）也沒有改善效果？","options":["(A) latanoprost","(B) apraclonidine","(C) timolol","(D) atropine"],"answer":3,"image":""},{"id":"md2-112-1-66","subject":"md2","topic":"藥理-總論與自主神經","meta":"112年第1次第66題","year":112,"session":1,"number":66,"question":"肉毒桿菌毒素（botulinum toxin）可局部注射於皮下，用以消除皺紋，其作用是透過下列何種機制而產生？","options":["(A) 抑制運動神經細胞的鈉離子通道（sodium channel）","(B) 抑制骨骼肌細胞的鈉離子通道","(C) 阻斷骨骼肌細胞的菸鹼性受體（nicotinic receptor）","(D) 抑制突觸囊泡（synaptic vesicle）釋放乙醯膽鹼"],"answer":3,"image":""},{"id":"md2-112-1-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第1次第67題","year":112,"session":1,"number":67,"question":"下列何者是metoclopramide的主要副作用？","options":["(A) 胃食道逆流（gastroesophageal reflux）","(B) 錐體外症狀（extrapyramidal symptom）","(C) 嗜睡","(D) 嘔吐"],"answer":1,"image":""},{"id":"md2-112-1-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第1次第68題","year":112,"session":1,"number":68,"question":"使用吸入型皮質類固醇仍無法有效控制氣喘時，最適合併用下列何種藥物以預防氣喘發作？","options":["(A) ephedrine","(B) formoterol","(C) roflumilast","(D) zileuton"],"answer":1,"image":""},{"id":"md2-112-1-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第1次第69題","year":112,"session":1,"number":69,"question":"若患者有腸躁症合併便秘時，使用下列何種藥物來治療的效果最佳？","options":["(A) tegaserod","(B) cisapride","(C) fluoxetine","(D) ritanserin"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第69題一律給分 (原公告答案 A)"},{"id":"md2-112-1-70","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"112年第1次第70題","year":112,"session":1,"number":70,"question":"下列何種藥物最適合用來治療男性勃起障礙（erectile dysfunction）？","options":["(A) epoprostenol","(B) treprostinil","(C) misoprostol","(D) alprostadil"],"answer":3,"image":""},{"id":"md2-112-1-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第1次第71題","year":112,"session":1,"number":71,"question":"關於氣喘的藥物中，下列何者的作用機轉是透過抑制支氣管平滑肌上leukotriene受體的作用而來的？","options":["(A) zafirlukast","(B) misoprostol","(C) zileuton","(D) iloprost"],"answer":0,"image":""},{"id":"md2-112-1-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"112年第1次第72題","year":112,"session":1,"number":72,"question":"以levodopa治療帕金森氏症時，可併用selegiline增強levodopa的療效，下列何者為selegiline的藥理作用機制？","options":["(A) 抑制單胺氧化酶B（monoamine oxidase B）","(B) 抑制兒茶酚-O-甲基轉移酶（catechol-O-methyltransferase）","(C) 抑制多巴脫羧基酶（dopa decarboxylase）","(D) 促進腦部神經末梢釋放多巴胺（dopamine）"],"answer":0,"image":""},{"id":"md2-112-1-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"112年第1次第73題","year":112,"session":1,"number":73,"question":"下列那一個治療癲癇發作的藥物，多數患者長期使用造成顯著的體重降低，目前與phentermine作成複方用於肥胖治療？","options":["(A) topiramate","(B) valproic acid","(C) gabapentin","(D) levetiracetam"],"answer":0,"image":""},{"id":"md2-112-1-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"112年第1次第74題","year":112,"session":1,"number":74,"question":"關於麻醉藥propofol作用的敘述，下列何者錯誤？","options":["(A) 具有鎮痛效果","(B) 降低血壓，在老年人更明顯","(C) 起效快，可用於誘導麻醉","(D) 具有止吐作用"],"answer":0,"image":""},{"id":"md2-112-1-75","subject":"md2","topic":"藥理-總論與自主神經","meta":"112年第1次第75題","year":112,"session":1,"number":75,"question":"下列何種藥物使用過量或中毒，採用血液透析解毒效果最差？","options":["(A) digoxin","(B) lithium","(C) theophylline","(D) carbamazepine"],"answer":0,"image":""},{"id":"md2-112-1-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"112年第1次第76題","year":112,"session":1,"number":76,"question":"傷口有過多膠原蛋白（collagen）堆積，生長超出原始傷口的邊界，並且不消退，稱為：","options":["(A) 蟹足腫（keloid）","(B) 肥厚疤（hypertrophic scar）","(C) 肉芽腫（granuloma）","(D) 肉芽組織（granulation tissue）"],"answer":0,"image":""},{"id":"md2-112-1-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"112年第1次第77題","year":112,"session":1,"number":77,"question":"下列何項器官或組織的再生能力最強？","options":["(A) 肺","(B) 肌肉","(C) 胰","(D) 肝"],"answer":3,"image":""},{"id":"md2-112-1-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"112年第1次第78題","year":112,"session":1,"number":78,"question":"關於唐氏症候群（Down syndrome）的敘述，下列何者最適當？","options":["(A) 單核苷酸多態性（single nucleotide polymorphism）基因分型法是最適合用來診斷唐氏症的工具","(B) 95%的個案是由於細胞多出的一條第21號染色體轉位到第14號染色體所致","(C) 可利用螢光原位雜交法（fluorescence in situ hybridization）診斷唐氏症","(D) 異常細胞鑲嵌（mosaicism）型唐氏症是由於第21號染色體的短臂鑲嵌到其它染色體內所致"],"answer":2,"image":""},{"id":"md2-112-1-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"112年第1次第79題","year":112,"session":1,"number":79,"question":"關於過敏性疾病的敘述，下列何者最適當？","options":["(A) 鼻瘜肉（nasal polyp）一般被認為與IgE媒介所引發的外因性過敏性鼻炎或鼻竇炎（atopic allergic rhinitis or sinusitis）有關","(B) 運動引發的過敏一般被認為主要是與TH2細胞的過度反應有關","(C) 發炎性腸道疾病（inflammatory bowel disease）一般被認為主要與TH2細胞的過度反應有關","(D) 全身過敏性反應（systemic anaphylaxis）的臨床症狀一般被認為與被活化的肥大細胞（mast cells）釋放一些引起血管活化調節物質有關"],"answer":3,"image":""},{"id":"md2-112-1-80","subject":"md2","topic":"病理-呼吸消化","meta":"112年第1次第80題","year":112,"session":1,"number":80,"question":"下列關於胃的原發性黏膜相關淋巴瘤（mucosa-associated lymphoid tissue lymphoma, MALToma）之敘述，何者最不適當？","options":["(A) 屬於B-cell lymphoma","(B) 與其關係最密切之微生物為Helicobacter pylori","(C) cytotoxin-associated gene A（CagA）為其相關微生物之重要致病基因","(D) 當其發生轉移時，最常出現之染色體變化為t(11;14)"],"answer":3,"image":""},{"id":"md2-112-1-81","subject":"md2","topic":"病理-呼吸消化","meta":"112年第1次第81題","year":112,"session":1,"number":81,"question":"下列造成腹水（ascites）的原因中，何種原因的積液所含的蛋白質濃度最高？","options":["(A) 細菌性腹膜炎（peritonitis）","(B) 腎病症候群（nephrotic syndrome）","(C) 肝硬化（liver cirrhosis）","(D) 營養不良（malnutrition）"],"answer":0,"image":""},{"id":"md2-112-1-82","subject":"md2","topic":"病理-心血管血液","meta":"112年第1次第82題","year":112,"session":1,"number":82,"question":"下列疾病容易引起血栓（thrombosis），但何者除外？","options":["(A) 肝素引起血小板低下（heparin-induced thrombocytopenia）","(B) 抗磷脂質抗體症候群（antiphospholipid antibody syndrome）","(C) Protein S缺乏（protein S deficiency）","(D) Von Willebrand disease"],"answer":3,"image":""},{"id":"md2-112-1-83","subject":"md2","topic":"病理-心血管血液","meta":"112年第1次第83題","year":112,"session":1,"number":83,"question":"72歲男性呈現心臟衰竭，右心壁肥厚及左心肥大，心肌切片檢查顯示在心肌間質有細絲狀物質沉積，此絲狀物直徑約10～12微米並呈無分支狀結構。下列何者最符合上述的病理變化？","options":["(A) endocardial fibroelastosis","(B) ischemic interstitial fibrosis","(C) transthyretin amyloidosis","(D) postirradiation fibrosis"],"answer":2,"image":""},{"id":"md2-112-1-84","subject":"md2","topic":"病理-免疫感染遺傳","meta":"112年第1次第84題","year":112,"session":1,"number":84,"question":"45歲女性，鼻腔腫瘤切片發現中等大小異常淋巴球浸潤，且有明顯的血管侵犯（angioinvasion）及組織壞死，免疫染色顯示腫瘤細胞表現CD56，此腫瘤最可能與何種病毒有關？","options":["(A) 人類嗜T淋巴球病毒第一型（human T-lymphotropic virus 1）","(B) Epstein-Barr病毒（Epstein-Barr virus）","(C) 人類免疫缺乏病毒（human immunodeficiency virus）","(D) 人類疱疹病毒第八型（human herpesvirus 8）"],"answer":1,"image":""},{"id":"md2-112-1-85","subject":"md2","topic":"病理-心血管血液","meta":"112年第1次第85題","year":112,"session":1,"number":85,"question":"6歲男童兩週來出現面色蒼白、精神不佳。病童血液中紅血球、血小板、白血球數目減少。男童之前曾有類似感冒症狀，也服用過抗生素與退燒藥。骨髓切片檢查發現骨髓中約80%～90%都是脂肪組織，造血母細胞（blast cells）數目並未明顯增加。造血細胞形態大致正常。下列有關病人的敘述，何者最適當？","options":["(A) 最常見的感染性病因是黴漿菌感染","(B) 此類疾病以原發性（idiopathic）引起的最多","(C) 此類病人大多會因為脾臟出現造血功能而腫大","(D) 化療藥物中以taxol類為最常見病因"],"answer":1,"image":""},{"id":"md2-112-1-86","subject":"md2","topic":"病理-呼吸消化","meta":"112年第1次第86題","year":112,"session":1,"number":86,"question":"有關肺的鱗狀細胞癌（squamous cell carcinoma）的敘述，下列何者最適當？","options":["(A) 女性比男性多","(B) 通常發生於肺部周邊區域","(C) EGFR有高度表現且常合併突變","(D) 相對於其它組織形態，最常出現高鈣血症"],"answer":3,"image":""},{"id":"md2-112-1-87","subject":"md2","topic":"病理-呼吸消化","meta":"112年第1次第87題","year":112,"session":1,"number":87,"question":"α1-抗胰蛋白酶缺乏症（α1-antitrypsin deficiency）造成之肺氣腫類型多屬於下列何者？","options":["(A) 全腺泡型肺氣腫（panacinar emphysema）","(B) 中心型肺氣腫（centriacinar emphysema）","(C) 遠端腺泡型肺氣腫（distal acinar emphysema）","(D) 不規則型肺氣腫（irregular emphysema）"],"answer":0,"image":""},{"id":"md2-112-1-88","subject":"md2","topic":"病理-呼吸消化","meta":"112年第1次第88題","year":112,"session":1,"number":88,"question":"肺泡玻璃樣膜（hyaline membranes of alveoli）與下列何種病變最為相關？","options":["(A) 慢性支氣管炎（chronic bronchitis）","(B) 氣喘（asthma）","(C) 急性呼吸窘迫症候群（ARDS）","(D) 肺氣腫（emphysema）"],"answer":2,"image":""},{"id":"md2-112-1-89","subject":"md2","topic":"病理-呼吸消化","meta":"112年第1次第89題","year":112,"session":1,"number":89,"question":"下列關於胰臟癌的敘述，何者最不適當？","options":["(A) 腺泡細胞癌（acinar cell carcinoma）是最常見的胰臟癌類型","(B) 胰腺癌（ductal carcinoma）預後不良","(C) 胰腺癌（ductal carcinoma）經常發現CDKN2A inactivation和KRAS突變","(D) 大部分的胰腺癌（ductal carcinoma）發生在胰臟頭部（pancreatic head）"],"answer":0,"image":""},{"id":"md2-112-1-90","subject":"md2","topic":"病理-呼吸消化","meta":"112年第1次第90題","year":112,"session":1,"number":90,"question":"下列何處的鱗狀細胞癌（squamous cell carcinoma）與人類乳突瘤病毒（human papillomavirus）最為相關？","options":["(A) 牙齦（gingiva）","(B) 頰黏膜（buccal mucosa）","(C) 口咽（oropharynx）","(D) 食道（esophagus）"],"answer":2,"image":""},{"id":"md2-112-1-91","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第1次第91題","year":112,"session":1,"number":91,"question":"有關肝臟的威爾森氏病（Wilson disease），下列何種生化檢查的診斷價值最低？","options":["(A) 血清的銅離子濃度","(B) 血清的銅藍蛋白（ceruloplasmin）濃度","(C) 肝臟的銅離子濃度","(D) 尿液的銅離子濃度"],"answer":0,"image":""},{"id":"md2-112-1-92","subject":"md2","topic":"病理-免疫感染遺傳","meta":"112年第1次第92題","year":112,"session":1,"number":92,"question":"下列何種炎症細胞最不可能出現在硬化性後腹腔纖維化（sclerosing retroperitoneal fibrosis）的病灶中？","options":["(A) 淋巴球","(B) IgG4陽性漿細胞","(C) 嗜酸性白血球","(D) 嗜中性白血球"],"answer":3,"image":""},{"id":"md2-112-1-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第1次第93題","year":112,"session":1,"number":93,"question":"有關腎臟微小病變（minimal-change disease）之特徵，下列敘述何者最適當？","options":["(A) 最主要的病理變化為腎小球中的壁上皮細胞（parietal epithelial cells）的足突消失","(B) 腎小球的基底膜變厚","(C) 近側腎小管上皮有脂質沉積","(D) 在人類此疾病已證實與血管新生因子（angiopoietin-like 1）有密切關係"],"answer":2,"image":""},{"id":"md2-112-1-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第1次第94題","year":112,"session":1,"number":94,"question":"最常造成原發性副甲狀腺功能亢進症（primary hyperparathyroidism）的原因是：","options":["(A) primary hyperplasia","(B) parathyroid carcinoma","(C) multiple parathyroid adenomas","(D) solitary parathyroid adenoma"],"answer":3,"image":""},{"id":"md2-112-1-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第1次第95題","year":112,"session":1,"number":95,"question":"下列有關人類乳突狀病毒（human papillomavirus）與子宮頸癌或鱗狀前驅病灶（squamous cervical precursor lesions）的敘述，何者最不適當？","options":["(A) 大部分的鱗狀上皮內病灶（squamous intraepithelial lesion）不論是低度（low-grade）或高度（high-grade）都與人類乳突狀病毒的感染有關","(B) 大部分的低度鱗狀上皮內病灶與低危險性人類乳突狀病毒（low-risk human papillomavirus）的感染有關","(C) 大部分的高度鱗狀上皮內病灶與高危險性人類乳突狀病毒（high-risk human papillomavirus）的感染有關","(D) 在低度鱗狀上皮內病灶中，人類乳突狀病毒的病毒量，在表面成熟上皮較基底層上皮為高"],"answer":1,"image":""},{"id":"md2-112-1-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第1次第96題","year":112,"session":1,"number":96,"question":"卵巢腫瘤中，最常見的是源自於穆勒氏上皮（Müllerian epithelium）的上皮性腫瘤，下列有關卵巢上皮性腫瘤的敘述，何者最不適當？","options":["(A) 主要的組織型包括漿液性（serous）、黏液性（mucinous）與子宮內膜樣性（endometrioid）","(B) 卵巢漿液性癌（serous carcinoma）為最常見的卵巢上皮癌，兩側卵巢皆被侵犯的比例很低，低於20%","(C) 卵巢漿液性癌（serous carcinoma）可以分為高惡性度（high-grade）與低惡性度（low-grade）","(D) 卵巢上皮癌中，第二常見組織型為子宮內膜樣癌（endometrioid carcinoma）"],"answer":1,"image":""},{"id":"md2-112-1-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第1次第97題","year":112,"session":1,"number":97,"question":"根據卵巢上皮癌的發生機轉，可區分為第一型（type I）與第二型（type II）腫瘤，下列何者為第二型（type II）腫瘤？","options":["(A) 子宮內膜樣癌（endometrioid carcinoma）","(B) 亮細胞癌（clear cell carcinoma）","(C) 低惡性度漿液性癌（low-grade serous carcinoma）","(D) 高惡性度漿液性癌（high-grade serous carcinoma）"],"answer":3,"image":""},{"id":"md2-112-1-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"112年第1次第98題","year":112,"session":1,"number":98,"question":"非創傷性蜘蛛網膜下出血（subarachnoid hemorrhage）最常見之成因是：","options":["(A) arteriovenous malformation血管破裂","(B) cavernous hemangioma血管破裂","(C) arteriolar sclerosis血管破裂","(D) saccular aneurysm in the circle of Willis血管破裂"],"answer":3,"image":""},{"id":"md2-112-1-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"112年第1次第99題","year":112,"session":1,"number":99,"question":"庫賈氏症（Creutzfeldt-Jakob disease）患者大腦主要的病理變化是：","options":["(A) demyelinated plaque","(B) ring hemorrhage","(C) TH17 T cell infiltrate","(D) spongiform encephalopathy"],"answer":3,"image":""},{"id":"md2-112-1-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"112年第1次第100題","year":112,"session":1,"number":100,"question":"14歲男童於橋腦（pons）處有一經病理切片診斷為diffuse glioma, WHO grade II。針對brain stem glioma往往具有某特殊的基因變化，現已被歸屬成另外單獨類別之glioma，此特殊的基因變化是：","options":["(A) ATRX loss","(B) H3.1 or H3.3 K27M mutation","(C) MGMT hypermethylation","(D) 1p/19q co-deletion"],"answer":1,"image":""},{"id":"md2-112-2-1","subject":"md2","topic":"免疫學","meta":"112年第2次第1題","year":112,"session":2,"number":1,"question":"關於類結核型痲瘋病（tuberculoid leprosy）與腫瘤型痲瘋病（lepromatous leprosy）的敘述，下列何者最不適當？","options":["(A) 兩種病人都會對痲瘋菌素（lepromin）有高度的免疫反應","(B) 類結核型痲瘋病體內免疫球蛋白量是正常的","(C) 腫瘤型痲瘋病會出現結節性紅斑（erythema nodosum）","(D) 腫瘤型痲瘋病傳染力比較高"],"answer":0,"image":""},{"id":"md2-112-2-2","subject":"md2","topic":"細菌學","meta":"112年第2次第2題","year":112,"session":2,"number":2,"question":"33歲患者反覆高燒入院，發現有細菌性肝膿瘍（liver abscess），從引流出來組織液培養細菌，在馬康機瓊脂（MacConkey agar）上產生粉紅色菌落，且表面具有高度黏性的特質。這株菌最有可能是：","options":["(A) 大腸桿菌（Escherichia coli）","(B) 創傷弧菌（Vibrio vulnificus）","(C) 霍亂弧菌（Vibrio cholerae）","(D) 克雷伯氏菌（Klebsiella pneumoniae）"],"answer":3,"image":""},{"id":"md2-112-2-3","subject":"md2","topic":"藥理-化學治療","meta":"112年第2次第3題","year":112,"session":2,"number":3,"question":"革蘭氏陰性菌其DNA旋轉酶的A次單元（gyrase-A subunit）出現突變，則此菌株最有可能對何種抗生素降低敏感性或抗藥性之特性？","options":["(A) 環丙沙星（ciprofloxacin）","(B) 安比西林（ampicillin）","(C) 頭芽孢菌素（cephalosporin）","(D) 克林黴素（clindamycin）"],"answer":0,"image":""},{"id":"md2-112-2-4","subject":"md2","topic":"細菌學","meta":"112年第2次第4題","year":112,"session":2,"number":4,"question":"下列何種機制通常與革蘭氏陰性菌產生抗藥性無關？","options":["(A) 分泌酵素水解特定抗生素，使抗生素失去活性","(B) 於特定基因出現突變，使抗生素失去作用標的","(C) 加速抗生素由菌體內排出，使抗生素無法達到作用濃度","(D) 形成內孢子停止代謝活性，使抗生素失去作用標的"],"answer":3,"image":""},{"id":"md2-112-2-5","subject":"md2","topic":"細菌學","meta":"112年第2次第5題","year":112,"session":2,"number":5,"question":"下列何者是最適合用於分離退伍軍人菌屬（Legionella）的培養基？","options":["(A) Buffered charcoal yeast extract agar","(B) Caffeic acid agar","(C) Regan-Lowe agar","(D) Cystine-tellurite agar"],"answer":0,"image":""},{"id":"md2-112-2-6","subject":"md2","topic":"細菌學","meta":"112年第2次第6題","year":112,"session":2,"number":6,"question":"金黃色葡萄球菌（Staphylococcus aureus）分泌之腸毒素（enterotoxin）所造成之食物中毒，下列敘述何者最適當？","options":["(A) 腸毒素不具耐熱性","(B) 應使用大量抗生素治療","(C) 疾病潛伏期平均約4小時","(D) 通常症狀至少持續4至5天"],"answer":2,"image":""},{"id":"md2-112-2-7","subject":"md2","topic":"細菌學","meta":"112年第2次第7題","year":112,"session":2,"number":7,"question":"下列何者最不可能經由性行為傳染之致病菌？","options":["(A) 淋病雙球菌（Neisseria gonorrhoeae）","(B) 梅毒螺旋體（Treponema pallidum）","(C) 砂眼披衣菌（Chlamydia trachomatis）","(D) 單核細胞增多性李斯特菌（Listeria monocytogenes）"],"answer":3,"image":""},{"id":"md2-112-2-8","subject":"md2","topic":"細菌學","meta":"112年第2次第8題","year":112,"session":2,"number":8,"question":"下列有關細菌呼吸作用（respiration）之敘述，何者最不適當？","options":["(A) 有氧呼吸（aerobic respiration）較發酵作用產生更多的ATP","(B) 有氧呼吸的電子傳遞鏈位於細菌細胞膜","(C) 兼性厭氧細菌（facultative anaerobes）可行無氧呼吸（anaerobic respiration）","(D) 無氧呼吸較有氧呼吸產生更多的ATP"],"answer":3,"image":""},{"id":"md2-112-2-9","subject":"md2","topic":"細菌學","meta":"112年第2次第9題","year":112,"session":2,"number":9,"question":"下列何者不是敗血梭狀芽胞桿菌（Clostridium septicum）的特徵？","options":["(A) 常從土壤中分離出來，對氧氣有耐受性","(B) 可見於潛藏性大腸癌（occult colon cancer）病人","(C) 於血液瓊脂培養基上，菌落呈游走狀（swarming）散布","(D) 導致非外傷性肌肉壞死（nontraumatic myonecrosis）"],"answer":0,"image":""},{"id":"md2-112-2-10","subject":"md2","topic":"病毒學","meta":"112年第2次第10題","year":112,"session":2,"number":10,"question":"下列有關病毒的敘述，何者最適當？","options":["(A) RNA病毒複製時，基因體的複製錯誤率大於DNA病毒","(B) 病毒複製的速率是以等比級數方式增加","(C) 流感病毒（influenza virus）對環境的耐受性比腸病毒（enterovirus）強","(D) 所有RNA病毒均在寄主細胞質中完成複製工作"],"answer":0,"image":""},{"id":"md2-112-2-11","subject":"md2","topic":"免疫學","meta":"112年第2次第11題","year":112,"session":2,"number":11,"question":"下列那一個最有可能是病毒感染引發「全身性類感冒症狀（flu-like systemic symptom）」之因子？","options":["(A) T細胞","(B) 干擾素","(C) 抗體","(D) 免疫複合物（immune complex）"],"answer":1,"image":""},{"id":"md2-112-2-12","subject":"md2","topic":"病毒學","meta":"112年第2次第12題","year":112,"session":2,"number":12,"question":"下列有關布尼亞科（bunyaviridae）病毒的敘述，何者最適當？","options":["(A) 為正股(+)RNA病毒","(B) 病毒在細胞核中進行複製","(C) 漢他病毒（hantavirus）主要以老鼠為媒介傳播","(D) 以人傳人方式傳播"],"answer":2,"image":""},{"id":"md2-112-2-13","subject":"md2","topic":"病毒學","meta":"112年第2次第13題","year":112,"session":2,"number":13,"question":"下列何種疾病與EB病毒（Epstein-Barr virus）感染較無關？","options":["(A) 愛滋病患者的口腔毛狀白斑（hairy oral leukoplakia）","(B) 新生兒的先天性聽力受損","(C) 鼻咽癌","(D) 單核球增多症（mononucleosis）"],"answer":1,"image":""},{"id":"md2-112-2-14","subject":"md2","topic":"病毒學","meta":"112年第2次第14題","year":112,"session":2,"number":14,"question":"有關反轉錄病毒（retrovirus）的敘述，何者最不適當？","options":["(A) 原病毒（provirus）只出現在其宿主細胞染色體固定的位置","(B) 反轉錄時利用宿主的tRNA為引子（primer）","(C) 在病毒顆粒中基因體具有兩套（two copies）單股RNA","(D) 病毒顆粒中帶有反轉錄病毒酶（reverse transcriptase）"],"answer":0,"image":""},{"id":"md2-112-2-15","subject":"md2","topic":"病毒學","meta":"112年第2次第15題","year":112,"session":2,"number":15,"question":"新型冠狀病毒（SARS-CoV2）最初是如何被鑑定出是一個與蝙蝠冠狀病毒相近的病毒？","options":["(A) 電子顯微鏡的影像證明","(B) 病人檢體中的病毒序列與蝙蝠冠狀病毒序列有極高的相似度","(C) 病人的臨床症狀","(D) 病人與蝙蝠的抗體會交叉反應（cross react）"],"answer":1,"image":""},{"id":"md2-112-2-16","subject":"md2","topic":"藥理-化學治療","meta":"112年第2次第16題","year":112,"session":2,"number":16,"question":"下列抗黴菌藥物中，何者在菌體上的作用部位與其他藥物不同？","options":["(A) 三唑（triazole）","(B) 棘白菌素（echinocandin）","(C) 烯丙胺（allylamine）","(D) 多烯（polyenes）"],"answer":1,"image":""},{"id":"md2-112-2-17","subject":"md2","topic":"真菌學","meta":"112年第2次第17題","year":112,"session":2,"number":17,"question":"下列何者會合成類胡蘿蔔素色素（carotenoid pigments），使菌落呈粉紅至紅色？","options":["(A) Trichosporon spp.","(B) Rhodotorula spp.","(C) Cryptococcus spp.","(D) Malassezia spp."],"answer":1,"image":""},{"id":"md2-112-2-18","subject":"md2","topic":"免疫學","meta":"112年第2次第18題","year":112,"session":2,"number":18,"question":"大明希望推廣免疫科普知識，當他使用人體模型介紹周邊免疫組織／器官時，指向下列何處組織／器官時為錯誤示範？","options":["(A) tonsil","(B) lymph node","(C) spleen","(D) thymus"],"answer":3,"image":""},{"id":"md2-112-2-19","subject":"md2","topic":"免疫學","meta":"112年第2次第19題","year":112,"session":2,"number":19,"question":"下列何項先天免疫作用分子是利用直接破壞病原菌細胞膜之方式達到殺菌效果？","options":["(A) cytokine","(B) C reactive protein（CRP）","(C) Toll-like receptor（TLR）","(D) defensin"],"answer":3,"image":""},{"id":"md2-112-2-20","subject":"md2","topic":"免疫學","meta":"112年第2次第20題","year":112,"session":2,"number":20,"question":"關於T細胞的TCR抗原結合位置（complementary determining region, CDR）具最大變異度主要為何者？","options":["(A) CDR1","(B) CDR2","(C) CDR3","(D) CDR4"],"answer":2,"image":""},{"id":"md2-112-2-21","subject":"md2","topic":"免疫學","meta":"112年第2次第21題","year":112,"session":2,"number":21,"question":"T細胞和B細胞的抗原接受器（antigen receptor）是兩種適應性免疫細胞用來辨識抗原的重要工具，有關這兩種細胞抗原接受器的敘述何者錯誤？","options":["(A) T細胞抗原接受器（TCR）由α和β鏈構成，而B細胞抗原接受器（BCR）由兩組重鏈（heavy chain）和輕鏈（light chain）構成。兩種抗原接受器都具有變異區（variable region）及固定區（constant region），而且和抗原結合的位置都是在變異區","(B) T細胞抗原接受器（TCR）只有一個抗原結合位，B細胞抗原接受器（BCR）則有兩個。TCR只有表現在細胞膜上，而BCR則可以表現在細胞膜上或是以抗體的形式分泌出去","(C) BCR就是在B細胞膜表面的抗體，因此BCR的功能和抗體一樣，除了Fab可以和抗原結合外，Fc可以活化不同的效用功能（effector functions）","(D) TCR必須同時辨識MHC及抗原胜肽，由於病原菌的胜肽會被MHC所呈獻，因此T細胞具有能力去偵測病原菌的感染"],"answer":2,"image":""},{"id":"md2-112-2-22","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第2次第22題","year":112,"session":2,"number":22,"question":"口服FTY720（fingolimod）為一新型免疫抑制劑，可以用來治療人類多發性硬化症，其免疫調節機轉為何？","options":["(A) 阻斷自體抗體產生，引起之ADCC（antibody-dependent cell-mediated cytotoxicity）","(B) 減少IL-2產生，抑制T細胞之增生","(C) 阻斷IL-6-IL6 receptor之JAK/STAT徑路，抑制T細胞之活化","(D) 競爭T細胞之S1PR1徑路，讓T淋巴細胞無法活化，進而凋亡"],"answer":3,"image":""},{"id":"md2-112-2-23","subject":"md2","topic":"免疫學","meta":"112年第2次第23題","year":112,"session":2,"number":23,"question":"下列何者不是抗體分子Fc部分的功能？","options":["(A) 活化補體","(B) 中和（neutralization）作用","(C) 調理（opsonization）作用","(D) 促進mast cell釋放顆粒內物質（degranulation）"],"answer":1,"image":""},{"id":"md2-112-2-24","subject":"md2","topic":"免疫學","meta":"112年第2次第24題","year":112,"session":2,"number":24,"question":"下列有關oral tolerance的敘述何者正確？","options":["(A) 食物經過消化成為小分子，所以不易刺激免疫反應的發生","(B) 食物經過消化的小分子胜肽，會表現在胸腺而將相關的T細胞去除","(C) 所有的食物都會引發oral tolerance","(D) 可能與分泌TGF-β的T輔助細胞有關"],"answer":3,"image":""},{"id":"md2-112-2-25","subject":"md2","topic":"免疫學","meta":"112年第2次第25題","year":112,"session":2,"number":25,"question":"下列何種情況與第一型過敏反應疾病的發生最有相關？","options":["(A) 嬰幼兒時期成長於很乾淨的家中","(B) 2歲前常發生細菌性感染症","(C) 有麻疹病毒（measles）或A型肝炎病毒感染史","(D) 病人體內常具有針對某種蛋白質有特異性之高濃度IgG2a"],"answer":0,"image":""},{"id":"md2-112-2-26","subject":"md2","topic":"免疫學","meta":"112年第2次第26題","year":112,"session":2,"number":26,"question":"紅斑性狼瘡（SLE）病人因細胞核裂解產生對抗dsDNA自體抗體（anti-dsDNA Ab）所導致的免疫致病機轉主要活化何種Toll-like receptor（TLR）？","options":["(A) TLR-1","(B) TLR-4","(C) TLR-7","(D) TLR-9"],"answer":3,"image":""},{"id":"md2-112-2-27","subject":"md2","topic":"病理-免疫感染遺傳","meta":"112年第2次第27題","year":112,"session":2,"number":27,"question":"器官移植後的慢性排斥（chronic rejection）作用，下列何情況最可能出現？","options":["(A) 活化的異體反應性natural killer（NK）cells經由血管進入移植體，而破壞植體組織結構","(B) 植體內圓周型的小血管內皮細胞損壞，細胞浸潤，血管壁及血管硬化，植體蒼白缺血","(C) 血液中的抗植體血型抗體造成血管發炎反應及血管完全阻塞，植體黑紫腫脹","(D) 接受移植者本身體內出現突變的植體抗原，造成產生對抗異體抗原的抗體反應，進而破壞植體組織結構"],"answer":1,"image":""},{"id":"md2-112-2-28","subject":"md2","topic":"免疫學","meta":"112年第2次第28題","year":112,"session":2,"number":28,"question":"下列關於anti-CTLA-4應用於腫瘤免疫療法之原理，何者正確？","options":["(A) CTLA-4蛋白質是結合樹突細胞（dendritic cell）之主要組織相容複合體（major histocompatibility complex, MHC）","(B) CTLA-4蛋白質是結合樹突細胞（dendritic cell）上的PD-1","(C) CTLA-4蛋白質是結合樹突細胞（dendritic cell）上的CD80/CD86","(D) CTLA-4蛋白質是結合樹突細胞（dendritic cell）上的CD11b"],"answer":2,"image":""},{"id":"md2-112-2-29","subject":"md2","topic":"寄生蟲學","meta":"112年第2次第29題","year":112,"session":2,"number":29,"question":"下列何種寄生蟲最不可能引起眼睛的病變？","options":["(A) 犬蛔蟲（Toxocara canis）","(B) 廣東住血線蟲（Angiostrongylus cantonensis）","(C) 羅阿絲蟲（Loa loa）","(D) 海獸胃線蟲（Anisakis spp.）"],"answer":3,"image":""},{"id":"md2-112-2-30","subject":"md2","topic":"寄生蟲學","meta":"112年第2次第30題","year":112,"session":2,"number":30,"question":"邱先生買了一塊農地種菜，經常弄得手腳滿是污泥，最近手臂發癢並出現延伸的紅斑，下列敘述那一項最不適當？","options":["(A) 皮膚搔癢（pruritus）可能是寄生蟲引起的過敏反應","(B) 可能是搔癢抓破皮引起的細菌性感染","(C) 可能是東方毛線蟲（Trichostrongylus orientalis）感染造成的","(D) 可能罹患鉤蟲爬行疹（creeping eruption）"],"answer":2,"image":""},{"id":"md2-112-2-31","subject":"md2","topic":"寄生蟲學","meta":"112年第2次第31題","year":112,"session":2,"number":31,"question":"關於埃及血吸蟲（Schistosoma haematobium）的敘述，下列何者正確？","options":["(A) 蟲卵具一個尖銳的側棘（lateral spine）","(B) 成蟲寄生於人的下腸繫膜靜脈叢","(C) 被認為是在埃及和非洲其他地區導致膀胱癌的主要原因","(D) 治療首選藥物是metronidazole"],"answer":2,"image":""},{"id":"md2-112-2-32","subject":"md2","topic":"寄生蟲學","meta":"112年第2次第32題","year":112,"session":2,"number":32,"question":"有關弓蟲症（toxoplasmosis）的敘述，下列何者錯誤？","options":["(A) 腸道外期（extraintestinal stage）感染主要是肇因於食入含有緩殖子（bradyzoite）的食物所致","(B) 免疫力正常的患者，通常無明顯症狀，有時與一般感冒（flu）無異","(C) 急性感染期（acute infection）時，患者會出現大量腹水","(D) 慢性感染期（chronic infection）時，患者會因為膠質細胞（glial cell）形成結節（nodule）而出現慢性腦炎的症狀"],"answer":2,"image":""},{"id":"md2-112-2-33","subject":"md2","topic":"寄生蟲學","meta":"112年第2次第33題","year":112,"session":2,"number":33,"question":"有關阿米巴之敘述，下列何者最正確？","options":["(A) 自營生活的阿米巴（free-living amebae）所造成的腦部感染均與游泳有關","(B) 在福氏內格里阿米巴（Naegleria fowleri）患者的組織切片中，可同時發現滋養體（trophozoites）及囊體（cysts）","(C) 如未及時診治，原發性阿米巴腦膜腦炎（primary amebic meningoencephalitis）患者通常會在症狀出現後3～6天內死亡","(D) 棘阿米巴性角膜炎（Acanthamoeba keratitis）患者都必需進行角膜移植恢復視力"],"answer":2,"image":""},{"id":"md2-112-2-34","subject":"md2","topic":"寄生蟲學","meta":"112年第2次第34題","year":112,"session":2,"number":34,"question":"下列何種節肢動物已被確認可以導致兒童過敏及氣喘（asthma）之主要致敏原（allergen）？","options":["(A) 疥蟎（scabies mite）","(B) 塵蟎（dust mite）","(C) 毛囊蟎（follicle mite）","(D) 恙蟎（chigger mite）"],"answer":1,"image":""},{"id":"md2-112-2-35","subject":"md2","topic":"細菌學","meta":"112年第2次第35題","year":112,"session":2,"number":35,"question":"王先生上週赴美國東部之波士頓市（Boston）旅遊及參與田園野營活動，依其自敘曾被不明蟲體叮咬，返國後陸續出現頭痛及急性高燒病症，經住院檢查發現白血球減少（leukopenia）及血小板減少（thrombocytopenia），並在血液抹片（blood smear）發現其中性球（neutrophils）內有菌體感染，請依其旅遊史及臨床病癥判斷，最有可能感染下列何種病媒傳染病？","options":["(A) 人巴貝氏原蟲症（human babesiosis）","(B) 人艾利希體症（human ehrlichiosis）","(C) 人體萊姆病（human Lyme disease）","(D) 人巴東菌症（human bartonellosis）"],"answer":1,"image":""},{"id":"md2-112-2-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第2次第36題","year":112,"session":2,"number":36,"question":"一般在進行隨機對照試驗（randomized controlled trial, RCT）前必須先估算樣本數。若要執行一RCT比較兩種藥物（A, B）降血壓（單位：mmHg）之效果，令虛無假設：兩種藥物降血壓效果相同vs. 對立假設：兩種藥物降血壓效果不同，採用雙樣本t檢定（two-sample t-test）方式估計總樣本數（假設兩組樣本數相同），在其他條件不變下，下列何種條件的改變會使估計之樣本數增加？","options":["(A) 設定之型一誤差（type 1 error）由0.05增加到0.1","(B) 兩種藥物降低之平均血壓值預期差異或效應值（effect size）由5 mmHg增加到10 mmHg","(C) 預期血壓之標準差（standard deviation）由12 mmHg增加到16 mmHg","(D) 預期檢定之檢定力（power）由0.9降至0.85"],"answer":2,"image":""},{"id":"md2-112-2-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第2次第37題","year":112,"session":2,"number":37,"question":"甲地的心血管疾病粗發生率（crude incidence rate）高於乙地，但年齡標準化發生率（age-standardized incidence rate）卻是低於乙地，下列敘述何者最恰當？","options":["(A) 甲地心血管疾病的危險因子比乙地多","(B) 甲地心血管疾病的死亡分率高於乙地","(C) 甲地的人口老化程度高於乙地","(D) 甲地心血管疾病的盛行率高於乙地"],"answer":2,"image":""},{"id":"md2-112-2-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第2次第38題","year":112,"session":2,"number":38,"question":"若發現X與Y兩變項的相關係數為0.8，下列敘述何者最恰當？","options":["(A) X越大的時候Y越小","(B) X是導致Y的原因","(C) 相關係數最大為1，最小為0","(D) 相關係數是看X與Y的線性相關程度"],"answer":3,"image":""},{"id":"md2-112-2-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第2次第39題","year":112,"session":2,"number":39,"question":"下列何者是公共衛生評估一個國家健康水平常用的指標？","options":["(A) 流產率","(B) 嬰兒死亡率","(C) 總生育率","(D) 離婚率"],"answer":1,"image":""},{"id":"md2-112-2-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"112年第2次第40題","year":112,"session":2,"number":40,"question":"腎臟對於化學毒性易感，下列敘述何者最不恰當？","options":["(A) 腎臟是人體各器官中，相對血流量較大的器官","(B) 鎘與汞中毒，易引起急性腎小管壞死","(C) 由於腎臟的濃縮作用，可凝聚外來的毒性物質","(D) 化學物質經腎臟過濾後，由尿液排出，不會影響輸尿管、膀胱、尿道等器官"],"answer":3,"image":""},{"id":"md2-112-2-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"112年第2次第41題","year":112,"session":2,"number":41,"question":"下列有關重金屬砷危害，何者敘述最不恰當？","options":["(A) 砷暴露為半導體晶圓及光電產業重要職業危害","(B) 在臺灣過去煉銅廠周遭，有砷環境暴露危害","(C) 要測量長期砷暴露量，血中砷濃度較毛髮中砷濃度適宜作為指標","(D) 砷暴露會增加肺癌風險"],"answer":2,"image":""},{"id":"md2-112-2-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"112年第2次第42題","year":112,"session":2,"number":42,"question":"飲用水之加氯消毒可以去除水中的細菌，但其最主要缺點為何？","options":["(A) 成本較高","(B) 處理的時間費時","(C) 對於配水管線再受汙染時，沒有保護能力","(D) 會與飲水中有機物作用，產生鹵化有機物"],"answer":3,"image":""},{"id":"md2-112-2-43","subject":"md2","topic":"藥理-總論與自主神經","meta":"112年第2次第43題","year":112,"session":2,"number":43,"question":"血中膽鹼酯酶活性下降，最可能是因為暴露於下列何種危害物所造成？","options":["(A) 四氯化碳","(B) 二甲基甲醯胺","(C) 鉻酸","(D) 有機磷"],"answer":3,"image":""},{"id":"md2-112-2-44","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"112年第2次第44題","year":112,"session":2,"number":44,"question":"「公共衛生」賦予國家保障民眾健康的權利與義務，在歷史發展上，下列那一個國家於1848年訂定「公共衛生法」（Public Health Act）？","options":["(A) 日本","(B) 美國","(C) 英國","(D) 德國"],"answer":2,"image":""},{"id":"md2-112-2-45","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第2次第45題","year":112,"session":2,"number":45,"question":"「個體取向」的預防疾病策略，是找出高風險的個體給予預防性介入。相較下，針對整個群體的「群體取向」觀點，則是試圖改變整體族群的暴露風險，可能更為有效。關於「群體取向」，下列敘述何者最不恰當？","options":["(A) 減少整體人群的鹽分攝取量來減少心血管疾病","(B) 找出高血脂的病人，給予治療，減少心血管疾病死亡率","(C) 增加學童戶外活動時間以降低近視發生","(D) 目前我國菸害防制採取禁止菸品廣告的政策，是群體取向的一種作法"],"answer":1,"image":""},{"id":"md2-112-2-46","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"112年第2次第46題","year":112,"session":2,"number":46,"question":"如果一再服用安非他命，使人體對藥物效用產生抗拒性，後續必須增加安非他命劑量才能達到原先較低劑量所出現效果，這是藥物成癮者常見的那一種特徵？","options":["(A) 重覆性","(B) 耐受性","(C) 戒斷現象","(D) 強化現象"],"answer":1,"image":""},{"id":"md2-112-2-47","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"112年第2次第47題","year":112,"session":2,"number":47,"question":"關於醫藥分業的敘述，下列何者最不恰當？","options":["(A) 醫師在醫療急迫情形或無藥事人員執業的偏鄉地區，可以調劑藥品","(B) 醫藥分業是醫師專司診斷、鑑別診斷、處置、治療及開立處方箋，而不調劑","(C) 藥事人員調劑應符合優良藥品調劑作業規範，以提供專業藥事調劑服務","(D) 醫師法中之「交付藥劑」，與藥事法中之「調劑」應等同視之，為醫師調劑權之法源依據"],"answer":3,"image":""},{"id":"md2-112-2-48","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"112年第2次第48題","year":112,"session":2,"number":48,"question":"下列何項呼吸道疾病的防治方法是屬於預防醫學三段預防當中的第二段預防？","options":["(A) 均衡飲食，規律運動","(B) 不吸菸或戒菸","(C) 針對無呼吸道症狀者進行胸部X光檢查","(D) 接種卡介苗"],"answer":2,"image":""},{"id":"md2-112-2-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"112年第2次第49題","year":112,"session":2,"number":49,"question":"衛生計畫的評估準則中，下列那一個準則最符合「衛生資源的可近性、可用性及民眾對衛生服務的認知」之說明？","options":["(A) 衛生計畫的合法性","(B) 衛生計畫的可接受性","(C) 衛生計畫的重要性","(D) 衛生計畫的充分性"],"answer":1,"image":""},{"id":"md2-112-2-50","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"112年第2次第50題","year":112,"session":2,"number":50,"question":"對於人口特質的描述，常應用某一時間點觀察所得的指標，下列那一項不是此類型的人口統計指標？","options":["(A) 人口分布","(B) 人口推估","(C) 人口組成","(D) 人口數量"],"answer":1,"image":""},{"id":"md2-112-2-51","subject":"md2","topic":"藥理-總論與自主神經","meta":"112年第2次第51題","year":112,"session":2,"number":51,"question":"下列何種給藥方式之藥物生體可用率（bioavailability）最高？","options":["(A) 口服（oral）","(B) 直腸給藥（rectal）","(C) 吸入型給藥（inhalation）","(D) 靜脈注射（intravenous）"],"answer":3,"image":""},{"id":"md2-112-2-52","subject":"md2","topic":"藥理-化學治療","meta":"112年第2次第52題","year":112,"session":2,"number":52,"question":"有關cephalosporins類抗生素之敘述，下列何者錯誤？","options":["(A) cephalexin對綠膿桿菌（P aeruginosa）效用差，但通常能用於治療革蘭氏陽性菌的感染","(B) cefuroxime能用於流感嗜血桿菌（H influenzae）的感染治療","(C) cefoperazone與ceftazidime都無法使用在綠膿桿菌（P aeruginosa）感染治療","(D) ceftriaxone應避免使用在腸桿菌屬（Enterobacter sp）感染，主要是因為容易產生抗藥性"],"answer":2,"image":""},{"id":"md2-112-2-53","subject":"md2","topic":"藥理-化學治療","meta":"112年第2次第53題","year":112,"session":2,"number":53,"question":"關於抗癌藥物doxorubicin之敘述，下列何者錯誤？","options":["(A) 屬於天然抗生素的抗癌藥","(B) 可抑制topoisomerase I而產生抗癌作用","(C) 於心肌細胞內可能產生自由基而致心臟毒性","(D) 是對細胞週期無專一性藥物（cell cycle-nonspecific agent）"],"answer":1,"image":""},{"id":"md2-112-2-54","subject":"md2","topic":"藥理-化學治療","meta":"112年第2次第54題","year":112,"session":2,"number":54,"question":"下列抗生素中，何者可以抑制癌細胞之細胞週期（cell cycle）進行，於臨床上主要作為抗癌藥物？","options":["(A) bleomycin","(B) gentamicin","(C) telithromycin","(D) daptomycin"],"answer":0,"image":""},{"id":"md2-112-2-55","subject":"md2","topic":"藥理-化學治療","meta":"112年第2次第55題","year":112,"session":2,"number":55,"question":"有關抗癌藥物之敘述，下列何者正確？","options":["(A) 6-mercaptopurine為azathioprine之衍生物，可以作為免疫增強劑","(B) CHOP組合治療lymphoma，其中C是指cisplatin","(C) cyclophosphamide須經過cytochrome P450 oxidase代謝後，才具DNA alkylating作用","(D) methotrexate之抗癌機制為抑制topoisomerase II之活性"],"answer":2,"image":""},{"id":"md2-112-2-56","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第2次第56題","year":112,"session":2,"number":56,"question":"關於免疫抑制劑cyclosporine之敘述，下列何者錯誤？","options":["(A) 抑制calcineurin活性","(B) 減少NF-AT轉錄因子作用","(C) 減少interleukin-1產生","(D) 可誘發腎毒性或高血壓"],"answer":2,"image":""},{"id":"md2-112-2-57","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"112年第2次第57題","year":112,"session":2,"number":57,"question":"抗血小板藥物abciximab的相關敘述，下列何者錯誤？","options":["(A) 屬於單株抗體藥物","(B) 作用點在於抗glycoprotein IIIb/IIa","(C) 抑制fibrinogen相關血小板凝集反應","(D) 與tirofiban作用機制類似"],"answer":1,"image":""},{"id":"md2-112-2-58","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"112年第2次第58題","year":112,"session":2,"number":58,"question":"Oprelvekin為interleukin-11重組性藥物，其主要運用於緩解化學治療所導致的血小板缺乏症（thrombocytopenia），下列有關此藥物之敘述，何者錯誤？","options":["(A) 可刺激megakaryocyte增殖及提高周邊血小板數量","(B) 可刺激多種淋巴及骨髓細胞（lymphoid/myeloid）增殖","(C) 可減少周邊嗜中性白血球（neutrophil）數量","(D) 常見副作用為疲憊、頭痛及心房心律不整"],"answer":2,"image":""},{"id":"md2-112-2-59","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第2次第59題","year":112,"session":2,"number":59,"question":"下列何種藥物的主要作用標的為雌激素受體（estrogen receptor），用於乳癌的輔助治療？","options":["(A) progesterone","(B) ketoconazole","(C) tamoxifen","(D) danazol"],"answer":2,"image":""},{"id":"md2-112-2-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第2次第60題","year":112,"session":2,"number":60,"question":"下列何種降血糖藥物必須用注射方式給與？","options":["(A) acarbose","(B) saxagliptin","(C) liraglutide","(D) rosiglitazone"],"answer":2,"image":""},{"id":"md2-112-2-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第2次第61題","year":112,"session":2,"number":61,"question":"有位45歲男性因患有腎上腺腫瘤而呈現Cushing's syndrome，下列何種藥物可減輕此病人的症狀？","options":["(A) triamcinolone","(B) betamethasone","(C) fludrocortisone","(D) ketoconazole"],"answer":3,"image":""},{"id":"md2-112-2-62","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"112年第2次第62題","year":112,"session":2,"number":62,"question":"下列藥物何者可以經由抑制腎素renin的作用，用於治療高血壓？","options":["(A) aliskiren","(B) captopril","(C) eplerenone","(D) losartan"],"answer":0,"image":""},{"id":"md2-112-2-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"112年第2次第63題","year":112,"session":2,"number":63,"question":"下列抗心律不整藥物，何者具有抑制thyroxine（T4）轉變成triiodothyronine（T3）的作用？","options":["(A) adenosine","(B) amiodarone","(C) lidocaine","(D) dronedarone"],"answer":1,"image":""},{"id":"md2-112-2-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"112年第2次第64題","year":112,"session":2,"number":64,"question":"下列何者屬於口服型vasopressin（ADH）antagonists利尿劑？","options":["(A) conivaptan","(B) metolazone","(C) triamterene","(D) tolvaptan"],"answer":3,"image":""},{"id":"md2-112-2-65","subject":"md2","topic":"藥理-總論與自主神經","meta":"112年第2次第65題","year":112,"session":2,"number":65,"question":"膀胱過度活動症（overactive bladder）的病人，可以使用下列何種藥物來治療，其作用機轉是透過β3 adrenoceptor？","options":["(A) sibutramine","(B) lorcaserin","(C) mirabegron","(D) buspirone"],"answer":2,"image":""},{"id":"md2-112-2-66","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"112年第2次第66題","year":112,"session":2,"number":66,"question":"下列有關varenicline藥理性質的敘述，何者錯誤？","options":["(A) 是中樞神經細胞蕈毒鹼受體拮抗劑（muscarinic receptor antagonist）","(B) 其最主要的臨床用途為協助菸癮者戒菸（smoking cessation）","(C) 可能的副作用是引起焦慮（anxiety）和憂鬱（depression）","(D) 用於戒菸時，其效用（efficacy）優於bupropion"],"answer":0,"image":""},{"id":"md2-112-2-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第2次第67題","year":112,"session":2,"number":67,"question":"下列何者是zafirlukast治療氣喘之作用機轉？","options":["(A) 拮抗adenosine receptor","(B) 抑制leukotriene receptor","(C) 減少cAMP降解","(D) 減少組織胺釋放"],"answer":1,"image":""},{"id":"md2-112-2-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第2次第68題","year":112,"session":2,"number":68,"question":"住院接受腸道手術之病人常出現術後腸阻塞（postoperative ileus）現象，可考慮於術前及術後給與alvimopan，以改善腸阻塞問題。有關使用此藥之注意事項，下列何者正確？","options":["(A) 屬於鴉片受體拮抗劑，可能產生心血管毒性","(B) 易進入中樞神經系統，術後給藥不可超過七日","(C) 不可與鴉片類止痛劑併用，以免拮抗其止痛效果","(D) 只能注射給藥，因此只限住院病人使用"],"answer":0,"image":""},{"id":"md2-112-2-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第2次第69題","year":112,"session":2,"number":69,"question":"下列何種藥物是屬於5-HT4 agonist，可用於治療胃食道逆流（gastroesophageal reflux）？","options":["(A) tegaserod","(B) cisapride","(C) fluoxetine","(D) ritanserin"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第69題一律給分 (原公告答案 B)"},{"id":"md2-112-2-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第2次第70題","year":112,"session":2,"number":70,"question":"下列何種藥物最適合用來作為懷孕婦女的引產藥（induce labor）？","options":["(A) dinoprostone","(B) alprostadil","(C) iloprost","(D) latanoprost"],"answer":0,"image":""},{"id":"md2-112-2-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"112年第2次第71題","year":112,"session":2,"number":71,"question":"下列何種藥物最適合用來治療輕度到中度的氣喘（asthma）？","options":["(A) misoprostol","(B) ibuprofen","(C) zileuton","(D) indomethacin"],"answer":2,"image":""},{"id":"md2-112-2-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"112年第2次第72題","year":112,"session":2,"number":72,"question":"下列神經傳遞物質，何者與fluoxetine抗憂鬱的作用機制最有關聯性？","options":["(A) norepinephrine","(B) serotonin","(C) glutamate","(D) acetylcholine"],"answer":1,"image":""},{"id":"md2-112-2-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"112年第2次第73題","year":112,"session":2,"number":73,"question":"有關抗癲癇藥物phenytoin的敘述，下列何者錯誤？","options":["(A) 具有延長鈉離子管道不反應期的作用","(B) 會抑制肝臟微粒體酵素的活性，因此會減少其他藥物的代謝作用","(C) 與albumin具有高度的親和力","(D) 溶解度較fosphenytoin差"],"answer":1,"image":""},{"id":"md2-112-2-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"112年第2次第74題","year":112,"session":2,"number":74,"question":"鴉片類藥物經長期使用後，許多作用會逐漸產生耐受性，下列藥理作用何者最不容易產生耐受性？","options":["(A) 瞳孔縮小（miosis）","(B) 鎮痛（analgesia）","(C) 咳嗽抑制（cough suppression）","(D) 欣快感（euphoria）"],"answer":0,"image":""},{"id":"md2-112-2-75","subject":"md2","topic":"藥理-化學治療","meta":"112年第2次第75題","year":112,"session":2,"number":75,"question":"下列何種藥物主要是用於治療鐵（iron）中毒？","options":["(A) dimercaprol","(B) penicillamine","(C) melarsoprol","(D) deferoxamine"],"answer":3,"image":""},{"id":"md2-112-2-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"112年第2次第76題","year":112,"session":2,"number":76,"question":"大腦梗塞數月後，電腦斷層出現4公分囊性（cystic）區域，該處最可能發生何種病理變化？","options":["(A) 液化壞死（liquefactive necrosis）","(B) 凝固性壞死（coagulative necrosis）","(C) 乾酪性壞死（caseous necrosis）","(D) 凋亡（apoptosis）"],"answer":0,"image":""},{"id":"md2-112-2-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"112年第2次第77題","year":112,"session":2,"number":77,"question":"組織纖維化（fibrosis），與下列何者最有關？","options":["(A) transforming growth factor-β","(B) interleukin-1","(C) selectin","(D) histamine"],"answer":0,"image":""},{"id":"md2-112-2-78","subject":"md2","topic":"病毒學","meta":"112年第2次第78題","year":112,"session":2,"number":78,"question":"下列病毒中，何者引起的主要臨床表徵是因其會造成潛伏感染（latent infection），感染並潛藏在感覺神經元細胞內所致？①單純疱疹病毒（Herpes simplex virus） ②脊髓灰質炎病毒（Poliovirus） ③水痘帶狀皰疹病毒（Varicella zoster virus）","options":["(A) ①②③","(B) 僅①②","(C) 僅②③","(D) 僅①③"],"answer":3,"image":""},{"id":"md2-112-2-79","subject":"md2","topic":"寄生蟲學","meta":"112年第2次第79題","year":112,"session":2,"number":79,"question":"象腿症（elephantiasis）最可能出現於：","options":["(A) 猩紅熱（scarlet fever）","(B) 弓漿蟲病（toxoplasmosis）","(C) 膿痂疹（impetigo）","(D) 絲蟲病（filariasis）"],"answer":3,"image":""},{"id":"md2-112-2-80","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"112年第2次第80題","year":112,"session":2,"number":80,"question":"下列惡性腫瘤之細胞形態特徵，何者最不可能出現在良性細胞？","options":["(A) Atypical mitoses","(B) High nuclear/cytoplasmic ratio","(C) Hyperchromasia","(D) Pleomorphism"],"answer":0,"image":""},{"id":"md2-112-2-81","subject":"md2","topic":"病理-心血管血液","meta":"112年第2次第81題","year":112,"session":2,"number":81,"question":"在心肌病變（cardiomyopathy）以心臟收縮功能障礙（systolic dysfunction）為主要致病機制的疾病中，下列何者是可能的致病原因？①酒精成癮 ②doxorubicin治療 ③TTN基因突變 ④類澱粉沉積（amyloidosis）","options":["(A) 僅①②","(B) ①②③","(C) 僅②③","(D) 僅③④"],"answer":1,"image":""},{"id":"md2-112-2-82","subject":"md2","topic":"病理-心血管血液","meta":"112年第2次第82題","year":112,"session":2,"number":82,"question":"下列何種疾病通常會增加部分凝血活酶時間（partial thromboplastin time）？①A型血友病（Hemophilia A） ②栓塞性血小板低下紫斑（Thrombotic thrombocytopenic purpura） ③Von Willebrand disease ④Glanzmann thrombasthenia","options":["(A) 僅①②","(B) 僅①③","(C) 僅①④","(D) ①③④"],"answer":1,"image":""},{"id":"md2-112-2-83","subject":"md2","topic":"病理-免疫感染遺傳","meta":"112年第2次第83題","year":112,"session":2,"number":83,"question":"胸腺的淋巴濾泡增生（thymic follicular hyperplasia）最常見於何種疾病？","options":["(A) 類風濕性關節炎（rheumatoid arthritis）","(B) 重症肌無力（myasthenia gravis）","(C) 葛瑞夫茲病（Graves disease）","(D) 硬皮症（scleroderma）"],"answer":1,"image":""},{"id":"md2-112-2-84","subject":"md2","topic":"病理-免疫感染遺傳","meta":"112年第2次第84題","year":112,"session":2,"number":84,"question":"下列何種腫瘤，最常併發純紅血球再生不良（pure red cell aplasia）？","options":["(A) 畸胎瘤（teratoma）","(B) 胸腺瘤（thymoma）","(C) 腦膜瘤（meningioma）","(D) 生殖細胞瘤（germinoma）"],"answer":1,"image":""},{"id":"md2-112-2-85","subject":"md2","topic":"病理-心血管血液","meta":"112年第2次第85題","year":112,"session":2,"number":85,"question":"下列那一種貧血與藥物之使用最不相關？","options":["(A) 葡萄糖-6-磷酸脫氫酶（glucose-6-phosphate dehydrogenase, G6PD）缺乏併發貧血","(B) 大球性貧血（macrocytic anemia）","(C) 再生不良性貧血（aplastic anemia）","(D) 小球性貧血（microcytic anemia）"],"answer":3,"image":""},{"id":"md2-112-2-86","subject":"md2","topic":"病理-呼吸消化","meta":"112年第2次第86題","year":112,"session":2,"number":86,"question":"45歲以下，不抽菸的年輕女性，下列何者是最常見的原發性肺癌？","options":["(A) 鱗狀細胞癌（squamous cell carcinoma）","(B) 腺癌（adenocarcinoma）","(C) 小細胞癌（small cell carcinoma）","(D) 大細胞癌（large cell carcinoma）"],"answer":1,"image":""},{"id":"md2-112-2-87","subject":"md2","topic":"病理-呼吸消化","meta":"112年第2次第87題","year":112,"session":2,"number":87,"question":"下列何者不屬於瀰漫性阻塞性肺疾病？","options":["(A) 肺氣腫（emphysema）","(B) 慢性支氣管炎（chronic bronchitis）","(C) 支氣管擴張（bronchiectasis）","(D) 急性呼吸窘迫症候群（ARDS）"],"answer":3,"image":""},{"id":"md2-112-2-88","subject":"md2","topic":"病理-呼吸消化","meta":"112年第2次第88題","year":112,"session":2,"number":88,"question":"下列有關氣喘的敘述，何者最不適當？","options":["(A) 與第二型輔助T細胞（TH2 cells）活化有關","(B) 屬於第二型過敏反應","(C) 可見到嗜酸性白血球增加","(D) 支氣管黏液中有Curschmann spirals"],"answer":1,"image":""},{"id":"md2-112-2-89","subject":"md2","topic":"病理-呼吸消化","meta":"112年第2次第89題","year":112,"session":2,"number":89,"question":"下列何者不是常見的造成急性胰臟炎的原因？","options":["(A) 酗酒","(B) 胰管阻塞","(C) 高三酸甘油脂血症","(D) 低血鈣"],"answer":3,"image":""},{"id":"md2-112-2-90","subject":"md2","topic":"病理-呼吸消化","meta":"112年第2次第90題","year":112,"session":2,"number":90,"question":"有關唾液腺腫瘤的敘述，下列何者最不適當？","options":["(A) 多形性腺瘤（pleomorphic adenoma）是最常見的唾液腺良性腫瘤","(B) 鱗狀細胞癌（squamous cell carcinoma）是最常見的唾液腺惡性腫瘤","(C) 黏液表皮樣癌（mucoepidermoid carcinoma）常見MAML2的基因轉位","(D) 腺樣囊狀癌（adenoid cystic carcinoma）常可見神經周圍侵犯（perineural invasion）"],"answer":1,"image":""},{"id":"md2-112-2-91","subject":"md2","topic":"病理-呼吸消化","meta":"112年第2次第91題","year":112,"session":2,"number":91,"question":"60歲男性發現右耳前、下頜骨（mandible）上方有一圓形界線明顯的腫瘤，手術切下腫瘤在顯微鏡下可見狹窄的囊狀裂縫上覆蓋兩層上皮細胞，並有豐富的淋巴細胞，局部區域出現淋巴生成中心（germinal center），下列關於此腫瘤之敘述，何者最不適當？","options":["(A) 最常發生在腮腺","(B) 約10%為雙側性","(C) 具有明顯上皮及間質的分化，常出現軟骨樣的物質","(D) 抽菸者罹患比率較非吸菸者高"],"answer":2,"image":""},{"id":"md2-112-2-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第2次第92題","year":112,"session":2,"number":92,"question":"Brunn巢（Brunn nests）最常位於膀胱的那一部位？","options":["(A) 固有層","(B) 內層肌肉","(C) 外層肌肉","(D) 外膜層"],"answer":0,"image":""},{"id":"md2-112-2-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第2次第93題","year":112,"session":2,"number":93,"question":"腎臟之血管平滑肌脂肪瘤（angiomyolipoma）之重要臨床意義在於：","options":["(A) 有25%左右的腫瘤在5至10年後會有惡性轉變","(B) 易發生自發性出血","(C) 早期便出現腎衰竭","(D) 一半以上之散發性病例為雙側性"],"answer":1,"image":""},{"id":"md2-112-2-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第2次第94題","year":112,"session":2,"number":94,"question":"關於腦下垂體腺瘤之敘述，下列何者最適當？","options":["(A) 如有腫瘤細胞浸潤至腦組織則可診斷為腦下垂體癌","(B) 相較於正常垂體，腫瘤中含明顯的網狀纖維","(C) 細胞的形態學變化是判斷腫瘤的良惡性極為可靠的指標","(D) 體積較大的腫瘤常出現腫瘤內出血及壞死"],"answer":3,"image":""},{"id":"md2-112-2-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第2次第95題","year":112,"session":2,"number":95,"question":"下列有關子宮內膜異位症（endometriosis）敘述，何者最不適當？","options":["(A) 子宮內膜異位症是指異位性（ectopic）子宮內膜組織出現於子宮外的位置","(B) 子宮內膜異位症最常見的位置是卵巢","(C) 子宮內膜異位症會增加不孕症的發生","(D) 和子宮內膜異位症有關的卵巢癌主要是漿液性癌"],"answer":3,"image":""},{"id":"md2-112-2-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第2次第96題","year":112,"session":2,"number":96,"question":"有關源於子宮肌層的腫瘤（tumors of myometrium），下列敘述何者最不適當？","options":["(A) 最常見的腫瘤為平滑肌瘤（leiomyoma）","(B) 大部分的平滑肌瘤具有異常且複雜的染色體核型（karyotype）","(C) 大部分的平滑肌瘤具有MED12基因的基因突變","(D) 平滑肌瘤（leiomyoma）很少惡性轉化成平滑肌肉瘤（leiomyosarcoma）"],"answer":1,"image":""},{"id":"md2-112-2-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"112年第2次第97題","year":112,"session":2,"number":97,"question":"下列有關卵巢亮細胞癌（clear cell carcinoma）的敘述，何者最不適當？","options":["(A) 良性（benign）或交界性（borderline tumor）卵巢亮細胞腫瘤比亮細胞癌常見","(B) 治療與其他卵巢上皮癌相似","(C) 常見的基因改變與子宮內膜樣癌（endometrioid carcinoma）相似","(D) 晚期病人預後相當不好"],"answer":0,"image":""},{"id":"md2-112-2-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"112年第2次第98題","year":112,"session":2,"number":98,"question":"下列何種感染較不會引起周邊神經病變？","options":["(A) 結核分枝桿菌（Mycobacterium tuberculosis）","(B) 白喉（diphtheria）","(C) 水痘–帶狀皰疹（varicella-zoster）","(D) 痲瘋（leprosy）"],"answer":0,"image":""},{"id":"md2-112-2-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"112年第2次第99題","year":112,"session":2,"number":99,"question":"對於第三、第四級星狀神經膠細胞瘤（astrocytoma, WHO grade III-IV）患者而言，下列何種基因突變相較於wild-type具有較好之存活率？","options":["(A) NF1","(B) TP53","(C) IDH1","(D) EGFR"],"answer":2,"image":""},{"id":"md2-112-2-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"112年第2次第100題","year":112,"session":2,"number":100,"question":"45歲女性被發現有多顆腦瘤，切片檢查時，病理醫師施以thyroid transcription factor 1（TTF-1）免疫組織化學染色，其目的是想了解：","options":["(A) 是良性或惡性","(B) 腫瘤細胞分裂的快慢","(C) 是否肺腺癌轉移","(D) 是否為非上皮性腫瘤"],"answer":2,"image":""},{"id":"md2-113-1-1","subject":"md2","topic":"細菌學","meta":"113年第1次第1題","year":113,"session":1,"number":1,"question":"一位牧場工人手臂上出現丘疹（papule），快速演變成潰瘍進而結痂壞死（necrotic eschar），淋巴腺亦出現病變及水腫，經細菌分離，發現是一株會產孢子的細菌。此工人最有可能是受何菌感染？","options":["(A) 枯草桿菌（Bacillus subtilis）","(B) 破傷風梭菌（Clostridium tetani）","(C) 肉毒桿菌（Clostridium botulinum）","(D) 炭疽桿菌（Bacillus anthracis）"],"answer":3,"image":""},{"id":"md2-113-1-2","subject":"md2","topic":"細菌學","meta":"113年第1次第2題","year":113,"session":1,"number":2,"question":"傷寒瑪莉是一位無症狀的傷寒沙門氏桿菌（Salmonella Typhi）帶原者，通常這株菌最常躲在帶原者的何種器官中？","options":["(A) 肝臟","(B) 膽囊","(C) 胰臟","(D) 大腸"],"answer":1,"image":""},{"id":"md2-113-1-3","subject":"md2","topic":"細菌學","meta":"113年第1次第3題","year":113,"session":1,"number":3,"question":"一位8歲孩童在吃過漢堡及生菜沙拉後48小時，出現出血性腹瀉症狀，到醫院後又發現其有溶血性尿毒症（hemolytic uremic syndrome），最有可能的病原菌是：","options":["(A) 侵襲性大腸桿菌EIEC（enteroinvasive E. coli）","(B) 腸道凝集性大腸桿菌EAEC（enteroaggregative E. coli）","(C) 病原性大腸桿菌EPEC（enteropathogenic E. coli）","(D) 產志賀氏毒素大腸桿菌STEC（Shiga toxin-producing E. coli）"],"answer":3,"image":""},{"id":"md2-113-1-4","subject":"md2","topic":"藥理-化學治療","meta":"113年第1次第4題","year":113,"session":1,"number":4,"question":"有關 β-內醯胺酶抑制劑（β-lactamase inhibitor）之敘述，下列何者最適當？","options":["(A) 具有高度殺菌活性（bactericidal activity）","(B) 為窄效型（narrow spectrum）抑制細胞壁生合成之抗生素","(C) 與青黴素（penicillin）合併使用可達到藥物協同作用（synergistic effect）","(D) 可用於治療耐甲氧西林金黃色葡萄球菌（methicillin-resistant Staphylococcus aureus）"],"answer":2,"image":""},{"id":"md2-113-1-5","subject":"md2","topic":"細菌學","meta":"113年第1次第5題","year":113,"session":1,"number":5,"question":"下列有關脂多醣體（lipopolysaccharide）之敘述，何者最適當？","options":["(A) 脂多醣體與脂胞壁酸（lipoteichoic acid）皆為革蘭氏陰性菌細胞壁特有之結構","(B) 又稱為內毒素（endotoxin），核心多醣體（core polysaccharide）結構為其毒素毒性的來源","(C) 具有引發發炎反應之活性","(D) 煮沸加熱可去除其活性"],"answer":2,"image":""},{"id":"md2-113-1-6","subject":"md2","topic":"細菌學","meta":"113年第1次第6題","year":113,"session":1,"number":6,"question":"下列有關細菌構造之敘述，何者最適當？","options":["(A) 僅革蘭氏陽性菌具有壁膜間隙（periplasmic space）之構造","(B) 胜肽聚醣（peptidoglycan）為革蘭氏陰性菌才有之結構","(C) 細菌具有粒線體，為產生ATP之重要胞器","(D) 部分細菌具有鞭毛（flagellum）"],"answer":3,"image":""},{"id":"md2-113-1-7","subject":"md2","topic":"細菌學","meta":"113年第1次第7題","year":113,"session":1,"number":7,"question":"培養流行性嗜血桿菌（Haemophilus influenzae）時，通常會使用何種培養基，以提供這細菌的生長？","options":["(A) 甘露醇鹽瓊脂（mannitol salt agar）","(B) 巧克力瓊脂（chocolate agar）","(C) 馬康機瓊脂（MacConkey agar）","(D) 血液培養基（blood agar）"],"answer":1,"image":""},{"id":"md2-113-1-8","subject":"md2","topic":"細菌學","meta":"113年第1次第8題","year":113,"session":1,"number":8,"question":"產氣莢膜桿菌（Clostridium perfringens）菌株，依其所產生的毒素可分成不同型別；最常引起壞疽性腸炎（necrotizing enteritis）的是屬於那一型？","options":["(A) A型","(B) B型","(C) C型","(D) D型"],"answer":2,"image":""},{"id":"md2-113-1-9","subject":"md2","topic":"藥理-化學治療","meta":"113年第1次第9題","year":113,"session":1,"number":9,"question":"下列那一種抗生素主要不是作用於細菌細胞壁？","options":["(A) 異菸鹼醯（isoniazid）","(B) 乙胺丁醇（ethambutol）","(C) 利奈唑胺（linezolid）","(D) 萬古黴素（vancomycin）"],"answer":2,"image":""},{"id":"md2-113-1-10","subject":"md2","topic":"病毒學","meta":"113年第1次第10題","year":113,"session":1,"number":10,"question":"下列有關普里昂（prion）的敘述，何者最不適當？","options":["(A) 病人被普里昂感染只能在腦部測到其存在","(B) 一般對抗病毒的化學及物理方法無法抑制普里昂的活性","(C) 普里昂感染之病人腦內會產生海綿狀腦病變","(D) 普里昂是以蛋白質的形式進行感染"],"answer":0,"image":""},{"id":"md2-113-1-11","subject":"md2","topic":"病毒學","meta":"113年第1次第11題","year":113,"session":1,"number":11,"question":"有關parvovirus B19的敘述，下列何者最適當？","options":["(A) 為雙股DNA病毒","(B) 主要傳播途徑為糞口傳染","(C) 感染並引起紅血球的先驅細胞（erythroid precursor）溶解","(D) 感染兒童時，造成嬰兒玫瑰疹CSC"],"answer":2,"image":""},{"id":"md2-113-1-12","subject":"md2","topic":"病毒學","meta":"113年第1次第12題","year":113,"session":1,"number":12,"question":"藉由血清學的方式無法檢驗出正常的prion（PrP）與異常的prion（PrP）的差異。一種新的檢驗方式稱作SC “real-time quaking-induced conversion（RT-QuIC）”，可以快速檢驗出檢體內是否含有PrP。這是利用prion的那一種特性？C","options":["(A) PrP會聚集成纖絲（prion fibril）SC","(B) PrP會聚集成纖絲（prion fibril）CSCC","(C) PrP會將PrP轉換成PrP SCC","(D) PrP的蛋白質半衰期較PrP短"],"answer":1,"image":""},{"id":"md2-113-1-13","subject":"md2","topic":"病毒學","meta":"113年第1次第13題","year":113,"session":1,"number":13,"question":"痘病毒（poxvirus）與大多數其他人類DNA病毒主要之差異為：","options":["(A) 在細胞質複製","(B) 其基因體為線型雙股DNA","(C) 有自己的DNA聚合酶","(D) 利用strand-displacement的方式複製其DNA"],"answer":0,"image":""},{"id":"md2-113-1-14","subject":"md2","topic":"藥理-化學治療","meta":"113年第1次第14題","year":113,"session":1,"number":14,"question":"有關病毒感染治療藥物之敘述，下列何者最不適當？","options":["(A) 茚地那韋（indinavir）常用來治療單純疱疹病毒（herpes simplex virus）之感染","(B) 利巴韋林（ribavirin）合併干擾素（interferon）可用於治療C型肝炎病毒之感染","(C) 被狂犬病動物咬到之病人，必須施打馬或人之抗狂犬病病毒血清或免疫球蛋白","(D) 金剛烷胺（amantadine）可抑制A型流行性感冒病毒（influenza A virus）"],"answer":0,"image":""},{"id":"md2-113-1-15","subject":"md2","topic":"病毒學","meta":"113年第1次第15題","year":113,"session":1,"number":15,"question":"在托育中心的一歲男嬰，持續兩天水瀉並嘔吐，且有輕微發燒現象，之後因為脫水而住院。他最可能受到下列何種病毒的感染？","options":["(A) 輪狀病毒（rotavirus）","(B) 流感病毒（influenza virus）","(C) B型肝炎病毒（hepatitis B virus）","(D) EB病毒（Epstein-Barr virus）"],"answer":0,"image":""},{"id":"md2-113-1-16","subject":"md2","topic":"真菌學","meta":"113年第1次第16題","year":113,"session":1,"number":16,"question":"關於Emergomyces之敘述，下列何者最不適當？","options":["(A) 為溫度雙型性真菌，即25℃培養呈絲狀（mold form），37℃培養呈酵母狀（yeast form）","(B) 主要經由呼吸道吸入孢子感染，常出現皮膚病灶","(C) 多數被感染者都是健康人，並無明顯免疫不全的症狀","(D) 可使用amphotericin B和triazole治療"],"answer":2,"image":""},{"id":"md2-113-1-17","subject":"md2","topic":"真菌學","meta":"113年第1次第17題","year":113,"session":1,"number":17,"question":"一般而言，棘白菌素（Echinocandin）對下列何種真菌感染的治療效果最好？","options":["(A) 毛黴菌（Mucormycetes spp.）","(B) 隱球菌（Cryptococcus spp.）","(C) 鐮孢菌（Fusarium spp.）","(D) 麴菌（Aspergillus spp.）"],"answer":3,"image":""},{"id":"md2-113-1-18","subject":"md2","topic":"免疫學","meta":"113年第1次第18題","year":113,"session":1,"number":18,"question":"經由造血作用（hematopoiesis）產生免疫細胞的過程，最不可能在動物體內何處發生？","options":["(A) yolk sac","(B) fetal liver","(C) fetal heart","(D) bone marrow"],"answer":2,"image":""},{"id":"md2-113-1-19","subject":"md2","topic":"免疫學","meta":"113年第1次第19題","year":113,"session":1,"number":19,"question":"關於第一型干擾素（type I interferon），下列敘述何者最不適當？","options":["(A) 病毒感染有核細胞後，會刺激第一型干擾素的產生","(B) 第一型干擾素可以直接參與分解病毒","(C) 第一型干擾素可以活化細胞內基因以破壞病毒mRNA及抑制病毒蛋白的轉譯","(D) 第一型干擾素可以誘導細胞第一型MHC分子的表達，增加感染的細胞呈獻抗原給CD8毒殺T細胞"],"answer":1,"image":""},{"id":"md2-113-1-20","subject":"md2","topic":"免疫學","meta":"113年第1次第20題","year":113,"session":1,"number":20,"question":"下列有關T細胞或B細胞抗原受體的敘述，何者最不適當？","options":["(A) TCR α chain和TCR β chain形成配對，而TCR γ chain和TCR δ chain形成配對","(B) 氫鍵與凡德瓦力參與受體與抗原的結合過程","(C) clonal expansion是指淋巴細胞於胸腺或骨髓的發育過程中，其細胞表面上的抗原受體與外來抗原結合後，引起細胞大量增殖","(D) MHC restriction是指成熟T細胞的TCR只能夠辨識自身細胞MHC分子呈獻的抗原，不會辨識其他MHC分子呈獻的相同抗原"],"answer":2,"image":""},{"id":"md2-113-1-21","subject":"md2","topic":"免疫學","meta":"113年第1次第21題","year":113,"session":1,"number":21,"question":"有關B細胞、樹突細胞及巨噬細胞之敘述，下列何者最適當？","options":["(A) 三者皆會表現MHC class II及B7分子，所以被稱為抗原呈獻細胞","(B) 三者皆會表現MHC class II，但不表現MHC class I","(C) 三者皆會活化T細胞，但以B細胞最易活化naïve T細胞","(D) 三者平常皆維持不成熟狀態在周邊巡邏，遇到抗原後會分化進入成熟狀態，遷移至附近淋巴組織中"],"answer":0,"image":""},{"id":"md2-113-1-22","subject":"md2","topic":"免疫學","meta":"113年第1次第22題","year":113,"session":1,"number":22,"question":"有關抗體之敘述，下列何者最適當？","options":["(A) IgA可穿過胎盤，讓胎兒獲得被動免疫力","(B) IgE是活化補體的最主要抗體","(C) IgM是B細胞活化後最早分泌出來的抗體","(D) IgG是活化mast cells的最主要抗體"],"answer":2,"image":""},{"id":"md2-113-1-23","subject":"md2","topic":"免疫學","meta":"113年第1次第23題","year":113,"session":1,"number":23,"question":"當病原菌入侵腸道時，腸道上皮細胞最不可能利用下列何種分子來幫助清除病原菌？","options":["(A) TLRs","(B) NOD1及NOD2","(C) PGE2","(D) MIC-A及MIC-B"],"answer":2,"image":""},{"id":"md2-113-1-24","subject":"md2","topic":"免疫學","meta":"113年第1次第24題","year":113,"session":1,"number":24,"question":"先天性免疫缺失疾病（primary immunodeficiency diseases）經常是因為與免疫細胞發育或是功能相關的基因缺陷造成。下列疾病與其缺陷基因之配對，何者最不適當？","options":["(A) X-linked SCID：IL-2 receptor common gamma chain","(B) Wiskott-Aldrich syndrome：NF-κB","(C) Bruton's X-linked agammaglobulinemia：BTK","(D) DiGeorge syndrome：TBX1"],"answer":1,"image":""},{"id":"md2-113-1-25","subject":"md2","topic":"免疫學","meta":"113年第1次第25題","year":113,"session":1,"number":25,"question":"下列何者屬於IgE介導的第一型過敏反應疾病？","options":["(A) 麩質病（celiac disease）","(B) 血清病（serum sickness）","(C) 過敏性鼻結膜炎（allergic rhinoconjunctivitis）","(D) 過敏性接觸性皮膚炎（allergic contact dermatitis）"],"answer":2,"image":""},{"id":"md2-113-1-26","subject":"md2","topic":"免疫學","meta":"113年第1次第26題","year":113,"session":1,"number":26,"question":"IL-10基因剔除小鼠（gene knockout mice）最可能引發下列何種自體免疫疾病？","options":["(A) 發炎性腸道疾病（inflammatory bowel disease）","(B) 類紅斑性狼瘡（lupus-like syndrome）","(C) 淋巴細胞增生性疾病（lymphoproliferative disease）","(D) 類風濕性關節炎（rheumatoid arthritis）"],"answer":0,"image":""},{"id":"md2-113-1-27","subject":"md2","topic":"免疫學","meta":"113年第1次第27題","year":113,"session":1,"number":27,"question":"腫瘤抗原根據其特徵可以分為腫瘤相關抗原（tumor associated antigen, TAA）與腫瘤特異性抗原（tumor specific antigen, TSA），下列關於腫瘤抗原的描述，何者最不適當？","options":["(A) TAA這類抗原在正常組織與癌細胞中都可能表現，但在癌細胞中的表現量通常比正常組織要高","(B) TSA因為是基因突變、基因重組或病毒感染所產生的抗原，使用全外顯子定序（whole exome sequence, WES）是目前最常用來鑑定TSA的方法","(C) 目前CAR-T所針對的抗原，主要是TAA為主，少部分常見的TSA，亦可成為CAR-T的目標","(D) 使用單細胞轉錄體定序（single cell transcriptome sequence），是目前最常用來鑑定TAA的方法"],"answer":3,"image":""},{"id":"md2-113-1-28","subject":"md2","topic":"免疫學","meta":"113年第1次第28題","year":113,"session":1,"number":28,"question":"下列何種腫瘤目前可以注射疫苗來預防？","options":["(A) non-Hodgkin's lymphoma","(B) breast cancer with overexpression the receptor of HER-2/neu","(C) metastatic melanoma","(D) HPV-16 related cervical cancer"],"answer":3,"image":""},{"id":"md2-113-1-29","subject":"md2","topic":"寄生蟲學","meta":"113年第1次第29題","year":113,"session":1,"number":29,"question":"寄生蟲感染人體所造成之症狀，下列敘述何者正確？ћ犬蛔蟲（Toxocara canis）可造成眼部幼蟲移行症（ocular larva migrans） ќ班氏絲蟲（Wuchereria bancrofti）的慢性感染可造成下肢象皮病（elephantiasis） ѝ免疫低下之病患受到鞭蟲（Trichuris trichiura）感染必造成死亡 ў蛔蟲（Ascaris lumbricoides）感染可能出現異位寄生（ectopic parasitism）","options":["(A) 僅ћѝ","(B) 僅ќў","(C) 僅ћќў","(D) ћќѝў"],"answer":2,"image":""},{"id":"md2-113-1-30","subject":"md2","topic":"寄生蟲學","meta":"113年第1次第30題","year":113,"session":1,"number":30,"question":"人類感染下列何種寄生蟲，必須先經由心肺移行，才能到達小腸發育為成蟲？","options":["(A) 犬蛔蟲（Toxocara canis）","(B) 海獸胃線蟲（Anisakis spp.）","(C) 十二指腸鉤蟲（Ancylostoma duodenale）","(D) 有棘頜口線蟲（Gnathostoma spinigerum）"],"answer":2,"image":""},{"id":"md2-113-1-31","subject":"md2","topic":"寄生蟲學","meta":"113年第1次第31題","year":113,"session":1,"number":31,"question":"下列有關血吸蟲（blood flukes）之致病機制敘述，何者最適當？","options":["(A) 曼森血吸蟲（Schistosoma mansoni）成蟲主要寄生於人體之膀胱靜脈叢","(B) 埃及血吸蟲（Schistosoma haematobium）成蟲主要寄生於人體之腸繫膜靜脈叢","(C) 血吸蟲蟲卵經血流、異位陷入（ectopic trapped）腎臟而導致肉芽腫（granuloma）","(D) 日本血吸蟲（Schistosoma japonicum）成蟲之每日產卵量（egg deposition）最多可超過3000顆"],"answer":3,"image":""},{"id":"md2-113-1-32","subject":"md2","topic":"寄生蟲學","meta":"113年第1次第32題","year":113,"session":1,"number":32,"question":"水生植物可當何種寄生蟲之中間宿主？ћ牛羊肝吸蟲（Fasciola hepatica） ќ薑片蟲（Fasciolopsis buski） ѝ中華肝吸蟲（Clonorchis sinensis） ў槍狀肝吸蟲（Dicrocoelium dendriticum）","options":["(A) ћќ","(B) ѝў","(C) ћѝ","(D) ќў"],"answer":0,"image":""},{"id":"md2-113-1-33","subject":"md2","topic":"寄生蟲學","meta":"113年第1次第33題","year":113,"session":1,"number":33,"question":"一位臺商近日因腹部腫脹及發燒從中國回來臺灣就醫，經醫師檢查發現有貧血（anemia）及肝脾腫大（hepatosplenomegaly），住院後進行骨髓穿刺可見巨噬細胞內有寄生蟲。依據上述結果，這位臺商最可能感染下列何種寄生蟲？","options":["(A) 枯西氏錐蟲（Trypanosoma cruzi）","(B) 熱帶利什曼原蟲（Leishmania tropica）","(C) 布氏岡比亞錐蟲（Trypanosoma brucei gambiense）","(D) 杜氏利什曼原蟲（Leishmania donovani）"],"answer":3,"image":""},{"id":"md2-113-1-34","subject":"md2","topic":"寄生蟲學","meta":"113年第1次第34題","year":113,"session":1,"number":34,"question":"有關諾氏瘧原蟲（Plasmodium knowlesi）的敘述，下列何者錯誤？","options":["(A) 宿主專一性不強，可感染人類或非人靈長類","(B) 並不限定入侵年輕或老的紅血球","(C) 生活史中的裂殖體週期（schizogonic cycle）僅需24小時","(D) 會在肝臟形成隱眠小體（hypnozoites）"],"answer":3,"image":""},{"id":"md2-113-1-35","subject":"md2","topic":"寄生蟲學","meta":"113年第1次第35題","year":113,"session":1,"number":35,"question":"下列何種病媒（vector）最常在人的皮膚傷口產卵孵化成幼蟲寄生在組織中？","options":["(A) 白蛉","(B) 跳蚤","(C) 蝨","(D) 綠蠅"],"answer":3,"image":""},{"id":"md2-113-1-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"113年第1次第36題","year":113,"session":1,"number":36,"question":"吳醫師想利用假說檢定來探討某個降血壓藥物是否能有效降低血壓，經隨機抽取100位高血壓病患，測量其服藥前的血壓收縮壓，服藥滿三個月後再測量其血壓收縮壓，共得到200筆血壓收縮壓資料。下列敘述何者最恰當？","options":["(A) 因為是隨機抽樣的高血壓病患，所以收集到的200筆資料為互相獨立的資料","(B) 可以利用成對樣本的t（paired-t）檢定藥物是否有效，檢定的自由度為100+100-2=198","(C) 吳醫師的假說檢定不管是單尾或是雙尾檢定，都不會影響檢定統計值（test-statistic）","(D) 要完成吳醫師的假說檢定必須先假設高血壓病患的血壓收縮壓服從常態分布"],"answer":2,"image":""},{"id":"md2-113-1-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"113年第1次第37題","year":113,"session":1,"number":37,"question":"某醫師分析200位成年人手部握力（grip strength，單位：Kg）與年齡（age，單位：歲）的關係，以手部握力為依變項（dependent variable），年齡為自變項（independent variable），估計簡單線性迴歸模式其截距項為26.8，斜率為 -0.25，則估計之簡單線性迴歸模式為何？","options":["(A) 手部握力=(26.8/200)-0.25×年齡","(B) 年齡=-0.25+26.8×手部握力","(C) 手部握力=26.8-0.25×年齡","(D) 年齡=26.8-0.25×手部握力"],"answer":2,"image":""},{"id":"md2-113-1-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"113年第1次第38題","year":113,"session":1,"number":38,"question":"某流感快篩的敏感度為60%，特異度為70%，對發燒病人篩檢的陰性預測值為80%，此流感快篩之陰性反應的人中估計得到流感的百分比為多少？","options":["(A) 40%","(B) 30%","(C) 20%","(D) 無法判斷"],"answer":2,"image":""},{"id":"md2-113-1-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"113年第1次第39題","year":113,"session":1,"number":39,"question":"為執行一項臨床試驗，採丟銅板或電腦隨機分組方式，以決定病人接受新的或傳統治療方式進行研究。此隨機分組有助於達成下列何項目的？","options":["(A) 降低測量誤差的發生","(B) 使干擾因子在兩組有相似或相同的分布","(C) 提高測量的準確度","(D) 提高觀察結果的再現性"],"answer":1,"image":""},{"id":"md2-113-1-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"113年第1次第40題","year":113,"session":1,"number":40,"question":"下列何者不是全球環境變遷對公共衛生的衝擊？","options":["(A) 全球暖化造成病媒蚊、蝙蝠繁殖地點改變，擴大傳染病蔓延的可能性","(B) 臭氧層破壞導致紫外線暴露增加，提高罹患皮膚癌的風險","(C) 二氧化碳排放增加導致溫室效應，造成海平面上升","(D) 畜牧業畜養牛隻增加，其排泄物造成二氧化硫濃度上升"],"answer":3,"image":""},{"id":"md2-113-1-41","subject":"md2","topic":"藥理-總論與自主神經","meta":"113年第1次第41題","year":113,"session":1,"number":41,"question":"關於毒化物體內代謝之敘述，下列何者最不恰當？","options":["(A) 肝臟是最主要的代謝器官","(B) 由尿液排泄之代謝物大多具較低極性（polar）的物質","(C) 第二階段代謝（Phase II）主要為複合反應（conjugation）","(D) 代謝物可作為暴露評估之應用"],"answer":1,"image":""},{"id":"md2-113-1-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"113年第1次第42題","year":113,"session":1,"number":42,"question":"關於空氣品質，我國從2016年12月開始實施的空氣品質監測標準，採取空氣品質指標（air quality index，簡稱AQI）。下列有關AQI之敘述，何者最不恰當？","options":["(A) 測量的污染項目包含六種，分別是臭氧（O3）、細懸浮微粒（PM2.5）、懸浮微粒（PM10）、一氧化碳（CO）、二氧化硫（SO2）及二氧化氮（NO2）","(B) AQI係依據空氣污染物的監測資料，將當日空氣污染物濃度值，以其對人體健康之影響程度，換算出各污染物之副指標值","(C) AQI是以當日各污染物副指標值中之最小值，做為該測站當日之空氣品質指標值","(D) 當AQI值大於100時，表示空氣品質不良，對呼吸系統不好且較敏感之人會使其症狀惡化"],"answer":2,"image":""},{"id":"md2-113-1-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"113年第1次第43題","year":113,"session":1,"number":43,"question":"有關作業環境測定，下列敘述何者最不恰當？","options":["(A) 8小時日時量平均容許濃度的意義是指在該濃度下，大部分的正常年輕人，每天工作8小時，每週工作5天，終其一生不會發生不良的健康效應的濃度","(B) 我國短時間時量平均容許濃度，是指任何一次連續15分鐘內的時量平均容許濃度不得超過的標準","(C) 最高容許濃度是指任何時間均不能超過的最高容許濃度","(D) 作業環境測定標準的意義，是作為職業病診斷標準"],"answer":3,"image":""},{"id":"md2-113-1-44","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"113年第1次第44題","year":113,"session":1,"number":44,"question":"公共衛生也需要社會行銷，「4P」是社會行銷組合的核心概念，下列何者不包括在「4P」中？","options":["(A) 促銷（promotion）","(B) 通路（place）","(C) 政治（politics）","(D) 定價（price）"],"answer":2,"image":""},{"id":"md2-113-1-45","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"113年第1次第45題","year":113,"session":1,"number":45,"question":"47歲劉太太近日接到衛生所寄發之通知，邀其去做免費的乳房攝影檢查。縱使家裡距離衛生所設置的乳攝車很近，劉太太還是不想去。經衛生所護士去電瞭解後，才知原來劉太太第一次檢查的經驗有疼痛感，因不想再經歷，所以這次決定不去了。請根據健康信念模式，選擇最適合解釋劉太太不想去做乳房攝影檢查的因素？","options":["(A) 行動的利益與障礙","(B) 疾病的易感受性","(C) 行動的線索","(D) 自我效能"],"answer":0,"image":""},{"id":"md2-113-1-46","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"113年第1次第46題","year":113,"session":1,"number":46,"question":"下列何者不是渥太華憲章（The Ottawa Charter）所提出的五大行動綱領之一？","options":["(A) 制定健康的公共政策","(B) 強化社會行銷內涵","(C) 發展個人技能","(D) 創造支持性環境"],"answer":1,"image":""},{"id":"md2-113-1-47","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"113年第1次第47題","year":113,"session":1,"number":47,"question":"衛生福利部組織中「疾病管制署」，前身是由衛生署組織架構的那些單位合併改制而來？","options":["(A) 防疫處、疫情指揮中心、預防醫學研究所、慢性病防治局","(B) 防疫處、熱帶醫學研究所、預防醫學研究所、慢性病防治局","(C) 防疫處、檢疫總所、預防醫學研究所、慢性病防治局","(D) 血清疫苗製造所、檢疫總所、預防醫學研究所、慢性病防治局"],"answer":2,"image":""},{"id":"md2-113-1-48","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"113年第1次第48題","year":113,"session":1,"number":48,"question":"下列何種支付制度最不容易控制醫療費用上漲？","options":["(A) 總額預算（global budget）","(B) 論量計酬（fee for service）","(C) 論病例計酬（case payment）","(D) 論人計酬（capitation）"],"answer":1,"image":""},{"id":"md2-113-1-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"113年第1次第49題","year":113,"session":1,"number":49,"question":"世界衛生組織（WHO）為了評估醫療照護體系的績效，建構三大目標，下列何項並不屬於這三大目標之一？","options":["(A) 健康水準","(B) 醫療提供者滿意度","(C) 病人滿意及可近性","(D) 病人家庭財務負擔"],"answer":1,"image":""},{"id":"md2-113-1-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"113年第1次第50題","year":113,"session":1,"number":50,"question":"依照病人自主權利法，病人雖然已經有預立醫療決定，但下列何種臨床條件，醫療機構或醫師不得依其預立醫療決定終止、撤除或不施行維持生命治療或人工營養及流體餵養之全部或一部？","options":["(A) 癌症末期病人","(B) 處於不可逆轉之昏迷狀況","(C) 永久植物人狀態","(D) 所有程度的失智症患者 -"],"answer":3,"image":""},{"id":"md2-113-1-51","subject":"md2","topic":"藥理-總論與自主神經","meta":"113年第1次第51題","year":113,"session":1,"number":51,"question":"pKa=6的弱酸性藥物，在pH值為4的酸性環境下，其離子型與非離子型藥物（[A]：[HA]）的比例為何？","options":["(A) 1：10","(B) 10：1","(C) 1：100","(D) 100：1"],"answer":2,"image":""},{"id":"md2-113-1-52","subject":"md2","topic":"藥理-化學治療","meta":"113年第1次第52題","year":113,"session":1,"number":52,"question":"下列何者為肺囊蟲肺炎（pneumocystis pneumonia）之首選治療藥物組合？","options":["(A) trimethoprim - sulfamethoxazole","(B) vancomycin - gentamicin","(C) penicillin V - streptomycin","(D) amoxicillin - clavulanic acid"],"answer":0,"image":""},{"id":"md2-113-1-53","subject":"md2","topic":"藥理-化學治療","meta":"113年第1次第53題","year":113,"session":1,"number":53,"question":"長春花生物鹼類（vinca alkaloids）抗腫瘤藥物中，vincristine較vinblastine更容易出現下列何種副作用？","options":["(A) 骨髓抑制","(B) 禿頭","(C) 心臟毒性","(D) 周邊神經病變"],"answer":3,"image":""},{"id":"md2-113-1-54","subject":"md2","topic":"藥理-化學治療","meta":"113年第1次第54題","year":113,"session":1,"number":54,"question":"下列關於癌症治療之敘述，何者錯誤？","options":["(A) 具有KRAS突變的大腸直腸癌，以FOLFOX與cetuximab併用可以得到顯著療效","(B) 治療晚期或無法手術切除的肝癌，一般以sorafenib作為單一藥物進行治療","(C) gemcitabine可使用於治療轉移性胰臟癌","(D) erlotinib、afatinib及osimertinib皆可用於治療EGFR突變的非小細胞肺癌"],"answer":0,"image":""},{"id":"md2-113-1-55","subject":"md2","topic":"藥理-總論與自主神經","meta":"113年第1次第55題","year":113,"session":1,"number":55,"question":"下列關於血清素（serotonin）受體之敘述，何者錯誤？","options":["(A) 活化5-HT1B或5-HT1D可減少cAMP生成","(B) 活化腸道神經系統5-HT4可增加腸道蠕動","(C) 活化5-HT2受體與chemoreceptor reflex作用有關 ++","(D) 5-HT3受體是ligand-gated Na/K channel"],"answer":2,"image":""},{"id":"md2-113-1-56","subject":"md2","topic":"藥理-化學治療","meta":"113年第1次第56題","year":113,"session":1,"number":56,"question":"下列治療癌症抗體藥物之敘述，何者錯誤？","options":["(A) avelumab主要結合在癌細胞上的PD-L1表面蛋白","(B) nivolumab主要結合在T淋巴細胞上的PD-1表面蛋白","(C) panitumumab主要結合在大腸癌細胞表面的EGFR蛋白","(D) pertuzumab主要結合在乳癌細胞表面的VEGFR蛋白"],"answer":3,"image":""},{"id":"md2-113-1-57","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"113年第1次第57題","year":113,"session":1,"number":57,"question":"有關erythropoietin之敘述，下列何者錯誤？","options":["(A) 人體貧血時erythropoietin合成會增加","(B) 用於慢性腎疾和部分化療引發之貧血患者","(C) 會產生血栓的副作用","(D) 高血壓控制不良之患者可使用"],"answer":3,"image":""},{"id":"md2-113-1-58","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"113年第1次第58題","year":113,"session":1,"number":58,"question":"下列直接性凝血酶抑制劑（direct thrombin inhibitors）中，何者可口服方式給藥，以降低非瓣膜性心房顫動併發腦中風及系統性栓塞之風險？","options":["(A) lepirudin","(B) bivalirudin","(C) dabigatran","(D) argatroban"],"answer":2,"image":""},{"id":"md2-113-1-59","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第1次第59題","year":113,"session":1,"number":59,"question":"下列關於repaglinide之敘述，何者錯誤？","options":["(A) 用於控制餐後血糖波動","(B) 可用於對硫（sulfur）或磺脲類(sulfonylurea）藥物嚴重過敏的第2型糖尿病患者","(C) 可單獨使用或與雙胍類（biguanides）藥物併用，以治療糖尿病","(D) 不宜用於腎功能不全的患者和老年人"],"answer":3,"image":""},{"id":"md2-113-1-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第1次第60題","year":113,"session":1,"number":60,"question":"下列藥物中，何者在長期使用後可能導致骨質疏鬆症？","options":["(A) bazedoxifene","(B) calcitonin","(C) strontium ranelate","(D) anastrozole"],"answer":3,"image":""},{"id":"md2-113-1-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第1次第61題","year":113,"session":1,"number":61,"question":"長期使用類固醇，會導致醫源性庫欣氏症候群（iatrogenic Cushing syndrome），下列何者是比較少出現的症狀？","options":["(A) 月亮臉","(B) 軀幹肥胖","(C) 多毛","(D) 低血糖"],"answer":3,"image":""},{"id":"md2-113-1-62","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"113年第1次第62題","year":113,"session":1,"number":62,"question":"下列何者為furosemide產生利尿作用的主要機轉？ ++–","options":["(A) 在亨利氏環上升支，抑制Na/K/2Cl共同運送系統 +–","(B) 在亨利氏環上升支，抑制Na/Cl共同運送系統 ++–","(C) 在近端腎小管，抑制Na/K/2Cl共同運送系統 +–","(D) 在近端腎小管，抑制Na/Cl共同運送系統"],"answer":0,"image":""},{"id":"md2-113-1-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"113年第1次第63題","year":113,"session":1,"number":63,"question":"下列藥物中，何者不是藉由增加細胞內cGMP，而使血管擴張？","options":["(A) molsidomine","(B) bosentan","(C) sodium nitroprusside","(D) tadalafil +"],"answer":1,"image":""},{"id":"md2-113-1-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"113年第1次第64題","year":113,"session":1,"number":64,"question":"下列抗心律不整藥物中，何者不抑制K channel？","options":["(A) adenosine","(B) amiodarone","(C) disopyramide","(D) dofetilide"],"answer":0,"image":""},{"id":"md2-113-1-65","subject":"md2","topic":"藥理-總論與自主神經","meta":"113年第1次第65題","year":113,"session":1,"number":65,"question":"Scopolamine最不適用於下列何種情況？","options":["(A) 需要散瞳時","(B) 暈車","(C) 排尿困難","(D) 腹痛腹瀉"],"answer":2,"image":""},{"id":"md2-113-1-66","subject":"md2","topic":"藥理-總論與自主神經","meta":"113年第1次第66題","year":113,"session":1,"number":66,"question":"下列藥物中，何者不具有降低血壓的效果？","options":["(A) doxazosin","(B) clonidine","(C) midodrine","(D) betaxolol"],"answer":2,"image":""},{"id":"md2-113-1-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第1次第67題","year":113,"session":1,"number":67,"question":"下列吸入性類固醇藥物中，何者需經由氣管酯解酶（esterase）代謝後產生活性物質，因此較不易產生口腔念珠菌病（candidiasis）的副作用？","options":["(A) budesonide","(B) ciclesonide","(C) flunisolide","(D) mometasone"],"answer":1,"image":""},{"id":"md2-113-1-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第1次第68題","year":113,"session":1,"number":68,"question":"下列藥物中，何者最適合用於改善住院病人急性結腸假性阻塞（acute colonic pseudo-obstruction）的症狀？","options":["(A) sucralfate","(B) bismuth","(C) neostigmine","(D) metoclopramide"],"answer":2,"image":""},{"id":"md2-113-1-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第1次第69題","year":113,"session":1,"number":69,"question":"下列藥物中，何者最不適用於緩解腹瀉型腸躁症（irritable bowel syndrome with diarrhea）的腹痛與腹瀉症狀？","options":["(A) alosetron","(B) scopolamine","(C) octreotide","(D) linaclotide"],"answer":3,"image":""},{"id":"md2-113-1-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第1次第70題","year":113,"session":1,"number":70,"question":"下列藥物中，何者不能抑制IL-1訊息傳遞路徑，因此無法用於治療關節炎？","options":["(A) apremilast","(B) anakinra","(C) canakinumab","(D) rilonacept"],"answer":0,"image":""},{"id":"md2-113-1-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第1次第71題","year":113,"session":1,"number":71,"question":"下列cyclooxygenase（COX）的抑制藥物中，何者對COX-2的選擇性最低？","options":["(A) celecoxib","(B) etodolac","(C) piroxicam","(D) meloxicam"],"answer":2,"image":""},{"id":"md2-113-1-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"113年第1次第72題","year":113,"session":1,"number":72,"question":"下列何者最不適合用於治療bipolar disorders之mania？","options":["(A) valproic acid","(B) lithium","(C) carbamazepine","(D) fluoxetine"],"answer":3,"image":""},{"id":"md2-113-1-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"113年第1次第73題","year":113,"session":1,"number":73,"question":"下列嗎啡類藥物（opioids）及其受體的敘述，何者錯誤？","options":["(A) mu（μ）opioid receptors是Gi/o protein-coupled receptors","(B) opioid receptors可以出現在pre-synaptic site或是post-synaptic site","(C) endorphins和dynorphins兩者都是內生性的opioids","(D) tramadol是kappa（κ）opioid receptor agonist"],"answer":3,"image":""},{"id":"md2-113-1-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"113年第1次第74題","year":113,"session":1,"number":74,"question":"Paroxetine可用於憂鬱症的治療，下列何者為該藥物主要的作用機制？","options":["(A) 抑制serotonin的回收","(B) 抑制norepinephrine的回收","(C) 阻斷dopamine D2受體","(D) 阻斷5-HT2受體"],"answer":0,"image":""},{"id":"md2-113-1-75","subject":"md2","topic":"藥理-總論與自主神經","meta":"113年第1次第75題","year":113,"session":1,"number":75,"question":"β-blockers類藥物過量導致心搏過緩及低血壓時，最適合用下列何種藥物解毒？","options":["(A) theophylline","(B) caffeine","(C) metaproterenol","(D) glucagon"],"answer":3,"image":""},{"id":"md2-113-1-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"113年第1次第76題","year":113,"session":1,"number":76,"question":"心肌梗塞使用溶栓治療，可以恢復冠狀動脈血流。血流恢復後，最可能會發生下列何種細胞變化，而使心肌受損程度更加嚴重？","options":["(A) 細胞內中間絲（intermediate filament）減少","(B) 增加自由基（free radical）的形成","(C) 粒線體（mitochondria）腫脹","(D) 蛋白質合成減少"],"answer":1,"image":""},{"id":"md2-113-1-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"113年第1次第77題","year":113,"session":1,"number":77,"question":"細胞凋亡（apoptosis）最常出現下列何種現象？","options":["(A) 細胞脹腫（swelling）","(B) 細胞內鈣離子明顯增加","(C) 嗜中性球浸潤","(D) 染色質濃縮（chromatin condensation）"],"answer":3,"image":""},{"id":"md2-113-1-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"113年第1次第78題","year":113,"session":1,"number":78,"question":"關於馬凡氏症候群（Marfan syndrome）的敘述，下列何者最適當？","options":["(A) 最主要出現病變的器官為心臟血管系統、骨骼系統與神經系統","(B) 致病原因為形成第一型膠原纖維相關的基因COL1A1和COL1A2產生突變而引起","(C) 轉化生長因子-β（transforming growth factor-β, TGF-β）的過度活化是馬凡氏症候群的成因之一","(D) 螢光原位雜交法（fluorescent in situ hybridization）是最適合用來診斷馬凡氏症候群的檢驗工具"],"answer":2,"image":""},{"id":"md2-113-1-79","subject":"md2","topic":"免疫學","meta":"113年第1次第79題","year":113,"session":1,"number":79,"question":"下列疾病中，何者一般被認為大部分是與TH2細胞的作用或反應有關？ћ蠕蟲類寄生蟲感染 ќ外因性過敏性鼻炎（allergic rhinitis） ѝ肉芽腫性發炎（granulomatous inflammation）","options":["(A) ћќѝ","(B) 僅ћќ","(C) 僅ќѝ","(D) 僅ћѝ"],"answer":1,"image":""},{"id":"md2-113-1-80","subject":"md2","topic":"病理-免疫感染遺傳","meta":"113年第1次第80題","year":113,"session":1,"number":80,"question":"下列病理變化中，何者最類似腎臟移植後的超急性排斥（hyperacute rejection）之病變？","options":["(A) 腎絲球內微血管出現血小板與凝血纖維微小栓塞、嗜中性白血球浸潤與缺血性傷害","(B) 淋巴細胞性腎臟間質血管炎","(C) 淋巴細胞性腎小管炎（tubulitis）","(D) 腎絲球內與腎小管周圍微血管炎、腎絲球炎"],"answer":0,"image":""},{"id":"md2-113-1-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"113年第1次第81題","year":113,"session":1,"number":81,"question":"紫外線（UV light）之致癌作用，主要是對於DNA造成下列何種損傷？","options":["(A) 形成嘧啶二聚體（pyrimidine dimer）","(B) 雙股DNA斷裂（double-stranded DNA break）","(C) 染色體非平衡性轉位（chromosome unbalanced translocation）","(D) 基因擴增（gene amplification）"],"answer":0,"image":""},{"id":"md2-113-1-82","subject":"md2","topic":"病理-免疫感染遺傳","meta":"113年第1次第82題","year":113,"session":1,"number":82,"question":"70歲男性吃了生牛肉兩天後出現發燒、腹痛與出血性腹瀉，數天後他表現出少尿、水腫、出血、血尿與急性腎衰竭，糞便細菌培養出大腸桿菌，此大腸桿菌的血清型經鑑定後確定是O157:H7。關於這個疾病，下列敘述何者最適當？","options":["(A) 血液中的ADAMTS13下降是主要致病機制","(B) 血管內皮細胞受傷是致病主因","(C) 凝血活酶時間（partial thromboplastin time）延長是疾病初期常見的變化","(D) 此病是因為產生Von Willebrand factor的抗體所導致"],"answer":1,"image":""},{"id":"md2-113-1-83","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"113年第1次第83題","year":113,"session":1,"number":83,"question":"梗塞（infarct）在病理檢查下可分成紅色梗塞（red infarct）與白色梗塞（white infarct），下列何種是屬於白色梗塞？","options":["(A) 睪丸扭轉（testicular tortion）","(B) 肺臟梗塞","(C) 小腸梗塞","(D) 腎臟梗塞"],"answer":3,"image":""},{"id":"md2-113-1-84","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第1次第84題","year":113,"session":1,"number":84,"question":"下列何種疾病最可能藉由抑制前列腺素E2（prostaglandin E2）來治療？","options":["(A) 開放動脈導管（patent ductus arteriosus）","(B) 心房中膈缺損（atrial septal defect）","(C) 心室中膈缺損（ventricular septal defect）","(D) 主動脈閉鎖（aortic atresia）"],"answer":0,"image":""},{"id":"md2-113-1-85","subject":"md2","topic":"病理-心血管血液","meta":"113年第1次第85題","year":113,"session":1,"number":85,"question":"在骨髓切片中，骨髓母細胞（myeloblasts）占比為25%，病理診斷為何？","options":["(A) 原發性骨髓纖維化（primary myelofibrosis）","(B) 慢性骨髓性白血病（chronic myelogenous leukemia）","(C) 急性骨髓性白血病（acute myeloid leukemia）","(D) 骨髓化生不良症候群（myelodysplastic syndrome）"],"answer":2,"image":""},{"id":"md2-113-1-86","subject":"md2","topic":"病理-呼吸消化","meta":"113年第1次第86題","year":113,"session":1,"number":86,"question":"下列何者是造成鬱血性脾腫大（congestive splenomegaly）最常見的原因？","options":["(A) 心臟衰竭（heart failure）","(B) 門靜脈血栓（portal vein thrombosis）","(C) 脾靜脈血栓（splenic vein thrombosis）","(D) 肝硬化（liver cirrhosis）"],"answer":3,"image":""},{"id":"md2-113-1-87","subject":"md2","topic":"病理-呼吸消化","meta":"113年第1次第87題","year":113,"session":1,"number":87,"question":"下列有關惡性間皮瘤（malignant mesothelioma）的敘述，何者錯誤？","options":["(A) 與石棉暴露關係密切","(B) 常見BAP1突變","(C) 最常發生於胸膜","(D) 常造成遠端轉移"],"answer":3,"image":""},{"id":"md2-113-1-88","subject":"md2","topic":"病理-呼吸消化","meta":"113年第1次第88題","year":113,"session":1,"number":88,"question":"下列何者最不可能為氣胸（pneumothorax）的併發症？","options":["(A) 縱膈腔偏移（shifting）","(B) 肺部瘢痕形成（scarring）","(C) 肺癌（lung cancer）","(D) 肺部積膿（empyema）"],"answer":2,"image":""},{"id":"md2-113-1-89","subject":"md2","topic":"病理-呼吸消化","meta":"113年第1次第89題","year":113,"session":1,"number":89,"question":"下列何者為最常見之良性肺臟腫瘤？","options":["(A) 錯構瘤（hamartoma）","(B) 孤立性纖維瘤（solitary fibrous tumor）","(C) 血管瘤（hemangioma）","(D) 平滑肌瘤（leiomyoma）"],"answer":0,"image":""},{"id":"md2-113-1-90","subject":"md2","topic":"病理-呼吸消化","meta":"113年第1次第90題","year":113,"session":1,"number":90,"question":"關於自體免疫性肝炎（autoimmune hepatitis），下列何者錯誤？","options":["(A) IgG或γ-球蛋白增高","(B) 第二型自體免疫性肝炎較常發生於老年人","(C) 病理切片下可見許多的漿細胞（plasma cells）浸潤，可能進展至肝硬化","(D) 通常用類固醇或免疫抑制劑治療可改善發炎"],"answer":1,"image":""},{"id":"md2-113-1-91","subject":"md2","topic":"病理-呼吸消化","meta":"113年第1次第91題","year":113,"session":1,"number":91,"question":"下列關於胰臟炎的敘述何者錯誤？","options":["(A) 嚴重的急性胰臟炎是一種醫療急症。可導致瀰散性血管內凝血、水腫、急性呼吸窘迫、休克及急性腎小管壞死","(B) PRSS1和SPINK1突變可誘導胰臟炎","(C) 在組織學中，慢性胰臟炎經常呈現廣泛的纖維化和殘留的蘭氏小島和導管","(D) 慢性胰臟炎是一種可逆的變化"],"answer":3,"image":""},{"id":"md2-113-1-92","subject":"md2","topic":"病理-呼吸消化","meta":"113年第1次第92題","year":113,"session":1,"number":92,"question":"68歲女性，這些年來因膝關節炎疼痛的緣故必須服用大量非類固醇類抗發炎藥（NSAIDs）。最近幾天她感覺上腹痛並會噁心、嘔吐，這天因有吐血的情形而至急診室求診，下列那一項最可能造成上述表現？","options":["(A) 急性胃炎","(B) 腺癌","(C) 幽門桿菌感染","(D) 增生性息肉"],"answer":0,"image":""},{"id":"md2-113-1-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"113年第1次第93題","year":113,"session":1,"number":93,"question":"在長期之第二型糖尿病患，其胰島最有可能有下列何種物質之沉積？","options":["(A) 脂褐質","(B) 類澱粉","(C) 鈣質","(D) 鋅"],"answer":1,"image":""},{"id":"md2-113-1-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"113年第1次第94題","year":113,"session":1,"number":94,"question":"下列何種細胞基因異常最不可能發生在腎臟之乳突狀癌（papillary carcinoma）？","options":["(A) 染色體3p缺失（3p deletions）","(B) 三染色體7（trisomy 7）","(C) 三染色體17（trisomy 17）","(D) 男性病患之Y染色體丟失（loss of Y）"],"answer":0,"image":""},{"id":"md2-113-1-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"113年第1次第95題","year":113,"session":1,"number":95,"question":"下列有關乳房放射狀疤痕（radial scar）的敘述，何者最適當？","options":["(A) 與第一型糖尿病（type 1 diabetes）相關","(B) 常見於外傷或手術後","(C) 乳頭含血分泌物（bloody nipple discharge）","(D) 形狀不規則，會與乳癌混淆"],"answer":3,"image":""},{"id":"md2-113-1-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"113年第1次第96題","year":113,"session":1,"number":96,"question":"下列何者為診斷原位乳癌之最重要病理特徵？","options":["(A) 有完整肌上皮層（myoepithelial layer）","(B) 明顯的纖維化及纖維母細胞（fibroblast）增生","(C) 沒有明顯的淋巴球漿細胞（lymphoplasma cell）浸潤","(D) 雌激素受體（estrogen receptor）陽性"],"answer":0,"image":""},{"id":"md2-113-1-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"113年第1次第97題","year":113,"session":1,"number":97,"question":"根據臨床資料與分子研究，子宮內膜癌可區分為第一型（type I）與第二型（type II），下列有關子宮內膜癌（endometrial carcinoma）的敘述，何者最不適當？","options":["(A) 一般而言，第一型子宮內膜癌比第二型子宮內膜癌發生年齡較早","(B) 第一型子宮內膜癌的組織型為子宮內膜樣腺癌（endometrioid adenocarcinoma），其前驅病灶（precursor lesion）為子宮內膜增生（endometrial hyperplasia）","(C) 第二型子宮內膜癌的組織型中包括漿液性癌（serous carcinoma）。漿液性癌罕見相關之前驅病灶","(D) 一般而言，第二型子宮內膜癌比第一型子宮內膜癌臨床表現更為惡性（aggressive）"],"answer":2,"image":""},{"id":"md2-113-1-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"113年第1次第98題","year":113,"session":1,"number":98,"question":"大約三分之一的血管炎（vasculitis）之患者同時有周邊神經病變，其最常見的周邊神經病變表現型態是：","options":["(A) polyneuropathy","(B) mononeuropathy","(C) polyradiculoneuropathy","(D) mononeuritis multiplex"],"answer":3,"image":""},{"id":"md2-113-1-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"113年第1次第99題","year":113,"session":1,"number":99,"question":"圖中所示是一個具有高度傳染性的腦組織鏡下所見，罹患該病的患者容易有下列何種情形？","options":["(A) 長出惡性腦瘤","(B) 自發性蜘蛛膜下腔大出血","(C) 快速進行性失智","(D) 出現腦膜炎"],"answer":2,"image":"md2-113-1-99.jpeg"},{"id":"md2-113-1-100","subject":"md2","topic":"病理-心血管血液","meta":"113年第1次第100題","year":113,"session":1,"number":100,"question":"圖示是腦底Willis氏環，其中有一處病變，最可能引發下列何者？","options":["(A) 痴呆","(B) 步態不穩、共濟失調","(C) 舞蹈症","(D) 自發性蜘蛛膜下腔出血"],"answer":3,"image":"md2-113-1-100.jpeg"},{"id":"md2-113-2-1","subject":"md2","topic":"細菌學","meta":"113年第2次第1題","year":113,"session":2,"number":1,"question":"一般使用結核菌素試驗（tuberculin skin test）測試是否感染結核桿菌，當無法區分是感染者或施打bacillus Calmette-Guérin（BCG）疫苗後的反應，通常會加做下列何種測試以進一步確認？","options":["(A) 反轉錄聚合酶鏈鎖反應（reverse transcriptase-PCR）","(B) 丙型干擾素釋放試驗（IFN-γ release assays）","(C) 北方點墨法（northern blotting）","(D) 腫瘤壞死因子釋放試驗（TNF-α release assays）"],"answer":1,"image":""},{"id":"md2-113-2-2","subject":"md2","topic":"細菌學","meta":"113年第2次第2題","year":113,"session":2,"number":2,"question":"經何種細菌汙染的蜂蜜，嬰兒誤食後，最有可能因細菌產生的毒素，導致乏力性麻痺甚至呼吸困難？","options":["(A) 艱難梭菌（Clostridium difficile）","(B) 破傷風梭菌（Clostridium tetani）","(C) 肉毒桿菌（Clostridium botulinum）","(D) 產氣莢膜梭菌（Clostridium perfringens）"],"answer":2,"image":""},{"id":"md2-113-2-3","subject":"md2","topic":"藥理-化學治療","meta":"113年第2次第3題","year":113,"session":2,"number":3,"question":"青黴素結合蛋白質（Penicillin-binding proteins）的突變，最不可能造成細菌對下列何類藥物出現抗藥性？","options":["(A) 頭芽孢菌素（cephalosporins）","(B) 碳青黴烯（carbapenems）","(C) 單酰胺菌素（monobactams）","(D) 磺胺類藥物（sulfonamides）"],"answer":3,"image":""},{"id":"md2-113-2-4","subject":"md2","topic":"細菌學","meta":"113年第2次第4題","year":113,"session":2,"number":4,"question":"關於退伍軍人菌屬（Legionella）感染的敘述，下列何者最不適當？","options":["(A) BCYE agar常用於培養退伍軍人菌屬","(B) 退伍軍人菌屬為革蘭氏陽性桿菌","(C) 好發於夏末至秋天，天氣溫暖的季節","(D) 可造成龐提亞克熱（Pontiac fever）"],"answer":1,"image":""},{"id":"md2-113-2-5","subject":"md2","topic":"細菌學","meta":"113年第2次第5題","year":113,"session":2,"number":5,"question":"下列何種細菌毒素經短暫100℃加熱後較易失去活性？","options":["(A) 大腸桿菌（E. coli）內毒素（endotoxin）","(B) 金黃色葡萄球菌（Staphylococcus aureus）毒性休克症候群毒素-1（Toxic Shock Syndrome Toxin-1）","(C) 破傷風梭狀芽孢桿菌（Clostridium tetani）破傷風痙攣毒素（tetanospasmin）","(D) 腦膜炎雙球菌（Neisseria meningitidis）脂寡糖（lipooligosaccharide）"],"answer":2,"image":""},{"id":"md2-113-2-6","subject":"md2","topic":"細菌學","meta":"113年第2次第6題","year":113,"session":2,"number":6,"question":"下列有關細菌結構及其於致病過程中所扮演角色，何者敘述最不適當？","options":["(A) 鞭毛（flagellum）為細菌運動相關構造","(B) 莢膜（capsule）與細菌抵禦吞噬作用有關","(C) 細菌生物膜（biofilm）結構可協助細菌黏附於組織或醫用器材","(D) 纖毛（fimbriae）是比鞭毛（flagellum）直徑更大的毛髮狀結構，並與細菌之黏附（adhesion）能力有關"],"answer":3,"image":""},{"id":"md2-113-2-7","subject":"md2","topic":"細菌學","meta":"113年第2次第7題","year":113,"session":2,"number":7,"question":"肺纖維性囊腫病人的痰中常有綠膿桿菌（Pseudomonas aeruginosa），下列那個毒力因子最能幫助此菌在宿主形成聚落（colonization）？","options":["(A) 絲氨酸蛋白酶（serine protease）","(B) 海藻酸鹽（alginate）","(C) 綠膿桿菌素（pyocyanin）","(D) 鋅金屬基質蛋白酶（zinc metalloprotease）"],"answer":1,"image":""},{"id":"md2-113-2-8","subject":"md2","topic":"細菌學","meta":"113年第2次第8題","year":113,"session":2,"number":8,"question":"有關化膿性鏈球菌（Streptococcus pyogenes）毒力因子（virulence factors）的敘述，下列何者最不適當？","options":["(A) M蛋白質（M protein）可協助此菌躲避吞噬作用（phagocytosis）","(B) 猩紅熱（scarlet fever）會出現皮膚紅疹（rash），主要是因為鏈球菌激酶（streptokinase）所導致","(C) 鏈球菌溶血素O（Streptolysin O）具抗原性，且易被氧破壞","(D) 去氧核糖核酸酶（deoxyribonuclease, DNase）可助長細菌在宿主組織內散播"],"answer":1,"image":""},{"id":"md2-113-2-9","subject":"md2","topic":"藥理-化學治療","meta":"113年第2次第9題","year":113,"session":2,"number":9,"question":"有關甲硝唑（metronidazole）之敘述，下列何者最適當？","options":["(A) 可有效治療霍亂","(B) 進入菌體內直接造成毒性","(C) 可治療鬆脆類桿菌（Bacteroides fragilis）感染症","(D) 對好氧菌很有效"],"answer":2,"image":""},{"id":"md2-113-2-10","subject":"md2","topic":"病毒學","meta":"113年第2次第10題","year":113,"session":2,"number":10,"question":"病毒感染時最常利用下列何種蛋白質進入細胞內？","options":["(A) 基質蛋白（matrix protein）","(B) 蛋白水解酶（protease）","(C) 醣蛋白（glycoprotein）","(D) 核心蛋白（core protein）"],"answer":2,"image":""},{"id":"md2-113-2-11","subject":"md2","topic":"病毒學","meta":"113年第2次第11題","year":113,"session":2,"number":11,"question":"下列何種病毒感染人類引發疾病後，比較不會直接造成細胞增生形成腫瘤？","options":["(A) B型肝炎病毒（HBV）","(B) 人類嗜淋巴球病毒一型（HTLV-1）","(C) 人類乳突瘤病毒（HPV）","(D) 人類免疫缺陷病毒（HIV）"],"answer":3,"image":""},{"id":"md2-113-2-12","subject":"md2","topic":"病毒學","meta":"113年第2次第12題","year":113,"session":2,"number":12,"question":"郵輪上的一群人出現了上吐下瀉的症狀，未經治療，症狀在2～3天都獲得緩解。他們最可能感染了下列何種病毒？","options":["(A) 腺病毒40型（Adenovirus 40）","(B) 諾羅病毒（Norovirus）","(C) 輪狀病毒（Rotavirus group A）","(D) 腸病毒D68（Enterovirus D68）"],"answer":1,"image":""},{"id":"md2-113-2-13","subject":"md2","topic":"病毒學","meta":"113年第2次第13題","year":113,"session":2,"number":13,"question":"下列臨床症狀，何者與麻疹病毒感染較無關？","options":["(A) 腦炎（encephalitis）","(B) 畏光（photophobia）","(C) 口腔出現科氏斑點（Koplik spots）","(D) 進行性多灶性白質腦病（Progressive multifocal leukoencephalopathy, PML）"],"answer":3,"image":""},{"id":"md2-113-2-14","subject":"md2","topic":"病毒學","meta":"113年第2次第14題","year":113,"session":2,"number":14,"question":"有關人類中東呼吸症候群（MERS）病毒，下列敘述何者最適當？","options":["(A) 被感染的病人會產生出血及休克之病徵","(B) 遺傳基因為正股(+)RNA","(C) 主要是以果子狸為中間宿主而傳播","(D) 喜歡在室溫25℃複製生長"],"answer":1,"image":""},{"id":"md2-113-2-15","subject":"md2","topic":"病毒學","meta":"113年第2次第15題","year":113,"session":2,"number":15,"question":"有關人類免疫缺陷病毒（HIV）的敘述，下列何者最不適當？","options":["(A) 病毒之蛋白酶（protease）主要作用於宿主細胞蛋白質","(B) 病毒Rev蛋白質可調控病毒mRNA轉送至細胞質","(C) 病毒Tat蛋白質為一極強的轉活化因子（transactivator）","(D) 在複製的早期會產生多種剪接（spliced）的mRNA"],"answer":0,"image":""},{"id":"md2-113-2-16","subject":"md2","topic":"真菌學","meta":"113年第2次第16題","year":113,"session":2,"number":16,"question":"下列何種念珠菌對fluconazole最具有先天的抗藥性？","options":["(A) Candida albicans","(B) Candida tropicalis","(C) Candida krusei","(D) Candida parapsilosis"],"answer":2,"image":""},{"id":"md2-113-2-17","subject":"md2","topic":"真菌學","meta":"113年第2次第17題","year":113,"session":2,"number":17,"question":"造成全身感染之真菌中，下列何者會在感染組織中較常形成酵母團（spherule）？","options":["(A) 莢膜組織胞漿菌（Histoplasma capsulatum）","(B) 皮炎芽生黴菌（Blastomyces dermatitidis）","(C) 巴西副球黴菌（Paracoccidioides brasiliensis）","(D) 粗球黴菌（Coccidioides immitis）"],"answer":3,"image":""},{"id":"md2-113-2-18","subject":"md2","topic":"免疫學","meta":"113年第2次第18題","year":113,"session":2,"number":18,"question":"人類的免疫系統由造血幹細胞分化而來，若有一病人缺乏了淋巴前驅細胞（common lymphoid progenitor），你預測此病人體內那一個部分的免疫系統會受到最大的影響？","options":["(A) 先天性免疫系統","(B) 後天性免疫系統","(C) 先天性以及後天性免疫系統同時受到相同程度的影響","(D) 血液凝結系統"],"answer":1,"image":""},{"id":"md2-113-2-19","subject":"md2","topic":"免疫學","meta":"113年第2次第19題","year":113,"session":2,"number":19,"question":"有關補體系統參與先天性免疫防禦之敘述，下列何者最不適當？","options":["(A) 補體分子C5活化下游C6-C9組成膜攻擊複合體（membrane-attack complex）裂解病原菌","(B) 補體活化僅能由抗體啟動而非病原菌表面分子","(C) 活化補體分子可以經由調理作用（opsonization）促進吞噬反應","(D) 活化補體分子C3a及C5a可以活化肥大細胞（mast cells）促進發炎反應"],"answer":1,"image":""},{"id":"md2-113-2-20","subject":"md2","topic":"免疫學","meta":"113年第2次第20題","year":113,"session":2,"number":20,"question":"關於T細胞所辨識的抗原，下列敘述何者最不適當？","options":["(A) T細胞所辨識的抗原，通常是短片段的胜肽","(B) 抗原需被呈獻在MHC上，才能被T細胞所辨識","(C) 抗原需摺疊成複雜的立體結構，才能被T細胞所辨識","(D) T細胞經胸腺教育的階段，可區隔自體與外來抗原，以避免產生自體免疫反應"],"answer":2,"image":""},{"id":"md2-113-2-21","subject":"md2","topic":"免疫學","meta":"113年第2次第21題","year":113,"session":2,"number":21,"question":"下列關於B細胞發育的敘述，何者最不適當？","options":["(A) 免疫球蛋白基因的V(D)J重組，先從重鏈（heavy chain）開始","(B) μ重鏈（μ heavy chain）與VpreB及λ5組成的pre-BCR，對pre-B細胞繼續發育是必要的","(C) Bruton's tyrosine kinase（Btk）是pre-BCR或BCR下游訊息傳遞的必要蛋白，缺乏Btk會造成X-linked agammaglobulinemia（XLA）","(D) 表現IgM的immature B細胞如果辨識到抗原，就會開始細胞分裂（clonal expansion）"],"answer":3,"image":""},{"id":"md2-113-2-22","subject":"md2","topic":"免疫學","meta":"113年第2次第22題","year":113,"session":2,"number":22,"question":"下列何種CD4效應T細胞（effector CD4 T cells）所分泌的細胞激素（cytokines）或產生的表面分子（surface molecule）與促進B細胞抗體類型轉換（isotype class switch）的作用相關性最高？","options":["(A) IL-2","(B) IL-10","(C) CD40 ligand","(D) CD28"],"answer":2,"image":""},{"id":"md2-113-2-23","subject":"md2","topic":"免疫學","meta":"113年第2次第23題","year":113,"session":2,"number":23,"question":"下列有關肺炎鏈球菌多醣體疫苗之敘述，何者最不適當？","options":["(A) 是多醣體連結蛋白質形成的疫苗","(B) 以thymus-independent方式活化B細胞","(C) 誘發出來的抗多醣體抗體可降低病菌感染","(D) 可誘發記憶B細胞的產生"],"answer":1,"image":""},{"id":"md2-113-2-24","subject":"md2","topic":"免疫學","meta":"113年第2次第24題","year":113,"session":2,"number":24,"question":"疫苗接種（vaccination）是公共衛生常用以預防傳染病的手段。下列何者最不適合用於先天性免疫不全的病人？","options":["(A) B型肝炎（hepatitis B）疫苗","(B) 沙賓（Sabin）小兒麻痺疫苗","(C) 白喉、破傷風、百日咳三合一（DPT）疫苗","(D) 注射型流行性感冒（influenza）疫苗"],"answer":1,"image":""},{"id":"md2-113-2-25","subject":"md2","topic":"病理-免疫感染遺傳","meta":"113年第2次第25題","year":113,"session":2,"number":25,"question":"免疫性血小板缺乏症（immune thrombocytopenia）最主要是由下列何種過敏反應（hypersensitivity）所導致？","options":["(A) type I過敏反應","(B) type II過敏反應","(C) type III過敏反應","(D) type IV過敏反應"],"answer":1,"image":""},{"id":"md2-113-2-26","subject":"md2","topic":"免疫學","meta":"113年第2次第26題","year":113,"session":2,"number":26,"question":"自體免疫疾病是由於免疫系統針對自體抗原產生一系列免疫反應而產生的疾病。自體免疫疾病的形成，必須突破多重免疫耐受的機制。下列有關自體免疫的敘述，何者最不適當？","options":["(A) 免疫豁免部位，例如眼、子宮等器官，若遭受創傷導致組織特異抗原得以被周邊免疫細胞偵測時，可能引發自體免疫疾病","(B) 調節型T細胞（regulatory T cell）主要以細胞毒殺的方式，移除其辨識的自體細胞","(C) 周邊免疫失能（peripheral anergy）指的是當免疫細胞在周邊組織接收到抗原刺激時，若沒有受到共同刺激（costimulation）的訊號，則會產生免疫抑制","(D) 中樞免疫耐受性的建立，主要在初級免疫器官骨髓以及胸腺中進行"],"answer":1,"image":""},{"id":"md2-113-2-27","subject":"md2","topic":"免疫學","meta":"113年第2次第27題","year":113,"session":2,"number":27,"question":"目前有許多癌症治療是透過給與免疫細胞或激活免疫系統而達成，關於癌症免疫治療，下列敘述何者最不適當？","options":["(A) mRNA癌症疫苗需先找到腫瘤的基因突變，根據病人的HLA預測新生抗原（neoantigen），再根據預測結果合成mRNA，透過脂質奈米粒包覆mRNA，注射疫苗後激活腫瘤特異性細胞的免疫反應","(B) 細胞激素激活殺手細胞（cytokine-induced killer, CIK），是將T細胞在含有多種促發炎細胞激素（pro- inflammatory cytokines）的環境下，進行體外培養，再回輸至病患體內，此種細胞，具有高度腫瘤特異性","(C) 單核球衍生樹突細胞（monocyte-derived dendritic cell, MoDC）透過體外培養，將單核球轉變成抗原呈獻細胞，此種細胞會捕捉體內腫瘤抗原，並刺激與活化腫瘤特異性T細胞，以達到腫瘤毒殺作用","(D) 嵌合抗原受體T細胞（chimeric antigen receptor-T, CAR-T），是透過病毒將CAR分子基因送入T細胞，此CAR分子具有辨認腫瘤抗原與活化T細胞的特性"],"answer":1,"image":""},{"id":"md2-113-2-28","subject":"md2","topic":"病理-免疫感染遺傳","meta":"113年第2次第28題","year":113,"session":2,"number":28,"question":"超急性排斥反應（hyperacute rejection）通常是在移植手術後多久發生？","options":["(A) 數分鐘內","(B) 2～5天","(C) 7～21天","(D) 1～3個月"],"answer":0,"image":""},{"id":"md2-113-2-29","subject":"md2","topic":"寄生蟲學","meta":"113年第2次第29題","year":113,"session":2,"number":29,"question":"一名外籍移工剛至臺灣的第3天，於醫院接受腸道寄生蟲檢查，醫檢師發現其糞便內有許多肝毛線蟲（Capillaria hepatica）蟲卵，下列敘述何者最適當？","options":["(A) 該外籍移工在母國因為嗜食魚的肝臟，而受到肝毛線蟲蟲卵的感染（egg infection）","(B) 該外籍移工在母國因為嗜食鼠的肝臟，而受到肝毛線蟲幼蟲的感染（larval infection）","(C) 該外籍移工在母國因為嗜食鵝的肝臟，而受到肝毛線蟲蟲卵的感染（egg infection）","(D) 該外籍移工其實是一種假性感染（spurious infection）"],"answer":3,"image":""},{"id":"md2-113-2-30","subject":"md2","topic":"寄生蟲學","meta":"113年第2次第30題","year":113,"session":2,"number":30,"question":"下列有關蟯蟲（Enterobius vermicularis）感染的敘述，何者錯誤？","options":["(A) 感染後易於夜間導致睡眠病（sleeping sickness）","(B) 蟲卵可藉空氣傳播感染人體","(C) 婦女感染後有可能引起慢性骨盆腔腹膜炎（pelvic peritonitis）","(D) 最正確的診斷方式為肛圍擦拭法（perianal swab）檢查是否有蟲卵"],"answer":0,"image":""},{"id":"md2-113-2-31","subject":"md2","topic":"寄生蟲學","meta":"113年第2次第31題","year":113,"session":2,"number":31,"question":"下列有關血吸蟲的敘述，何者錯誤？","options":["(A) 雌雄同體，具口吸盤和腹吸盤","(B) 中間宿主釋出之尾動幼蟲（cercaria）可以穿透人的皮膚","(C) 曼森血吸蟲（Schistosoma mansoni）的分布地區最廣","(D) 致病機轉主要來自宿主對蟲卵的免疫反應"],"answer":0,"image":""},{"id":"md2-113-2-32","subject":"md2","topic":"寄生蟲學","meta":"113年第2次第32題","year":113,"session":2,"number":32,"question":"人類感染下列何種寄生蟲之主要途徑，不是經由飲用受污染的水所致？","options":["(A) 環孢子蟲（Cyclospora cayetanensis）","(B) 弓蟲（Toxoplasma gondii）","(C) 梨形鞭毛蟲（Giardia lamblia / G. intestinalis）","(D) 隱孢子蟲（Cryptosporidium spp.）"],"answer":1,"image":""},{"id":"md2-113-2-33","subject":"md2","topic":"寄生蟲學","meta":"113年第2次第33題","year":113,"session":2,"number":33,"question":"有關間日瘧原蟲（Plasmodium vivax），下列敘述何者錯誤？","options":["(A) 其裂殖子（merozoite）主要侵犯年輕的紅血球，如網狀紅血球（reticulocyte）","(B) Duffy血型抗原是該瘧原蟲的附著部位","(C) 由間日瘧原蟲造成的瘧疾在西非最為常見","(D) 因紅血球破裂，大量裂殖子（merozoite）、細胞殘骸及血紅素釋出，造成畏寒、發燒的臨床症狀"],"answer":2,"image":""},{"id":"md2-113-2-34","subject":"md2","topic":"寄生蟲學","meta":"113年第2次第34題","year":113,"session":2,"number":34,"question":"有關隱孢子蟲（Cryptosporidium spp.），下列敘述何者錯誤？","options":["(A) 人隱孢子蟲（C. hominis）及小隱孢子蟲（C. parvum）最常感染人類","(B) 僅存在於宿主腸道上皮刷狀緣","(C) 隱孢子蟲症主要是經水傳播","(D) 可在腹瀉患者糞便中找到大量活動體（trophozoites）"],"answer":[1,3],"image":"","answer_note":"更正:第34題答Ｂ或Ｄ或BD者均給分"},{"id":"md2-113-2-35","subject":"md2","topic":"寄生蟲學","meta":"113年第2次第35題","year":113,"session":2,"number":35,"question":"下列何種疾病的主要病媒（vector）不是體蝨（body louse）？","options":["(A) 流行性斑疹傷寒（epidemic typhus）","(B) 回歸熱（relapsing fever）","(C) 地方性斑疹傷寒（endemic typhus）","(D) 戰壕熱（trench fever）"],"answer":2,"image":""},{"id":"md2-113-2-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"113年第2次第36題","year":113,"session":2,"number":36,"question":"下列有關信賴區間（confidence interval）的敘述何者最不恰當？","options":["(A) 信賴區間是一種區間估計的方法","(B) 95%的信賴區間代表95%的樣本落在該區間","(C) 90%信賴區間的寬度會比95%信賴區間的寬度還窄","(D) 信賴區間也可以用來檢定假說"],"answer":1,"image":""},{"id":"md2-113-2-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"113年第2次第37題","year":113,"session":2,"number":37,"question":"收集100位下背痛病人在接受復健治療前及治療後的疼痛分數（範圍0～100分，分數越高越痛），利用此資料欲評估復健治療是否改善下背痛之疼痛狀況，應該採用下列何種統計方法分析最恰當？","options":["(A) 卡方檢定（Chi-square test）","(B) 麥內瑪關聯樣本檢定（McNemar's test）","(C) 雙樣本t檢定（Two-sample t-test）","(D) 配對t檢定（Paired t-test）"],"answer":3,"image":""},{"id":"md2-113-2-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"113年第2次第38題","year":113,"session":2,"number":38,"question":"某新興傳染病爆發之後，對疑似病人採檢後進行兩種不同方法的檢驗，並將其中任一次檢驗呈現陽性反應定義為陽性感染者，主要目的為：","options":["(A) 可增加檢驗敏感度","(B) 可增加檢驗特異度","(C) 可同時增加檢驗敏感度與特異度","(D) 維持檢驗敏感度與特異度"],"answer":0,"image":""},{"id":"md2-113-2-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"113年第2次第39題","year":113,"session":2,"number":39,"question":"某醫學期刊的一則廣告提到「2000名喉嚨痛的病人在接受本公司的新藥治療後的第4天，大約有94%病人的症狀緩解了」。此廣告也宣稱該公司的新藥對於治療喉嚨痛具有療效，您認為下列有關該公司新藥療效的相關敘述何者最恰當？","options":["(A) 該公司的宣稱是恰當的","(B) 該公司的宣稱可能不恰當，因為統計數據沒有考量觀察人年數來計算「率（rate）」","(C) 該公司的宣稱可能不恰當，因為該研究沒有考慮樣本長期的藥物反應","(D) 該公司的宣稱可能不恰當，因為該研究沒有使用對照組"],"answer":3,"image":""},{"id":"md2-113-2-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"113年第2次第40題","year":113,"session":2,"number":40,"question":"某化學物質在人體內代謝半衰期為24小時。某次暴露後體內殘量為原暴露量0.125倍時，則距離暴露已經過多久時間？","options":["(A) 42小時","(B) 48小時","(C) 72小時","(D) 96小時"],"answer":2,"image":""},{"id":"md2-113-2-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"113年第2次第41題","year":113,"session":2,"number":41,"question":"行政院環境保護署使用的空氣品質指標（AQI），常以顏色表示空氣污染程度。AQI中最嚴重的程度，以何種顏色表示？","options":["(A) 褐紅色（或咖啡色）","(B) 紫色","(C) 紅色","(D) 橙色"],"answer":0,"image":""},{"id":"md2-113-2-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"113年第2次第42題","year":113,"session":2,"number":42,"question":"下列環境荷爾蒙或疑似物質，何者最不可能是持久性有機污染物？","options":["(A) 滴滴涕（DDT）","(B) 鄰苯二甲酸酯類（Phthalates）","(C) 戴奧辛（Dioxins）","(D) 多氯聯苯（PCBs）"],"answer":1,"image":""},{"id":"md2-113-2-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"113年第2次第43題","year":113,"session":2,"number":43,"question":"有關環境毒物學的劑量反應評估，閾值（threshold）的敘述，下列何者最不恰當？","options":["(A) 如果具有閾值，則可推估參考劑量（reference dose, RfD）","(B) 可以透過動物實驗或流行病學資料蒐集來判斷有毒物質是否具有閾值效應","(C) 如果不具有閾值，可透過資料庫查詢得到其斜率因子，來做為風險計算的基礎","(D) 根據閾值所計算出來的危害指數（hazard index），若大於1，預期將不會造成危害"],"answer":3,"image":""},{"id":"md2-113-2-44","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"113年第2次第44題","year":113,"session":2,"number":44,"question":"公共心理衛生所強調的重點，下列何者最不恰當？","options":["(A) 強調社會環境對疾病成因的影響","(B) 強調留置病人於醫院或療養院接受治療","(C) 強調對精神病患的保護、諮商與治療，使其回歸社區","(D) 目標為全體民眾的心理健康"],"answer":1,"image":""},{"id":"md2-113-2-45","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"113年第2次第45題","year":113,"session":2,"number":45,"question":"風險溝通（risk communication）是指個人、團體或組織對於風險訊息進行意見交換過程。一般認為影響風險溝通成功與否的因素，不包括下列何者？","options":["(A) 風險知覺（risk perception）","(B) 樂觀偏誤（optimistic bias）","(C) 信任（trust）","(D) 知識（knowledge）"],"answer":3,"image":""},{"id":"md2-113-2-46","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"113年第2次第46題","year":113,"session":2,"number":46,"question":"為評估醫院推動社區減重計畫成效，下列那一種作法最不恰當？","options":["(A) 於社區內張貼海報、請地方電台廣播及鄰里長等協助宣傳以招募過重或肥胖的民眾參與","(B) 為了提高民眾參與，可以設計獎勵措施","(C) 於計畫介入前先詢問參與民眾過去一個月內的飲食與運動行為，由醫師、衛教師與營養師等提供相關的專業諮詢","(D) 為了瞭解計畫成效，只需要比較計畫前後體重變化"],"answer":3,"image":""},{"id":"md2-113-2-47","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"113年第2次第47題","year":113,"session":2,"number":47,"question":"下列有關預防醫學三段五級的傷害防制模式和介入策略的敘述，何者最不恰當？","options":["(A) 提高送醫前的急救處置和緊急救護系統的效率為第二段預防","(B) 配備汽車安全帶、安全氣囊或機車安全帽等裝置為第一段第1級安全促進","(C) 透過在環境、材質、設備等設計和製造時的修飾等工程介入，可達到減少傷害的目的","(D) 立法規範廠商在通過玩具安全標準和檢驗程序才得貼合格標籤販售為第一段預防"],"answer":1,"image":""},{"id":"md2-113-2-48","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"113年第2次第48題","year":113,"session":2,"number":48,"question":"下列關於平衡計分卡（Balanced Scorecard）的敘述，何者最不恰當？","options":["(A) 基本精神在於將策略轉換成具體行動，以達成公司的願景及策略","(B) 主要包含四個構面：財務、顧客、企業內部流程、學習與成長","(C) 在非營利事業單位應考量「員工被授權的程度」之構面","(D) 臺灣尚未引入平衡計分卡作為醫院管理的工具"],"answer":3,"image":""},{"id":"md2-113-2-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"113年第2次第49題","year":113,"session":2,"number":49,"question":"下列何項不是社會保險的基本原理特質？","options":["(A) 講求個人的自由公平","(B) 風險或危險共同分擔","(C) 避免引導道德危害","(D) 大數法則"],"answer":0,"image":""},{"id":"md2-113-2-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"113年第2次第50題","year":113,"session":2,"number":50,"question":"下列有關臺灣醫療照護供給體系的敘述，何者最恰當？","options":["(A) 臺灣的醫院家數主要是以私立醫院居多","(B) 臺灣的醫院數目逐年增加","(C) 目前臺灣每萬人口醫師數約為8人","(D) 目前臺灣的每萬人口醫院一般病床數目約為20床"],"answer":0,"image":""},{"id":"md2-113-2-51","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"113年第2次第51題","year":113,"session":2,"number":51,"question":"下列有關新藥臨床試驗之敘述，何者錯誤？","options":["(A) 臨床一期試驗一般情況下不納入病人，旨在檢驗人體對試驗藥物之最大容忍安全劑量","(B) 臨床二期試驗納入病人，旨在檢驗藥物的功效，不需與現行臨床使用的有效藥物做比較","(C) 臨床三期試驗納入較多病人，大都只採用單一藥物劑量","(D) 臨床四期試驗在藥物上市後才開始"],"answer":1,"image":""},{"id":"md2-113-2-52","subject":"md2","topic":"藥理-化學治療","meta":"113年第2次第52題","year":113,"session":2,"number":52,"question":"下列關於trimethoprim與sulfamethoxazole（TMP-SMZ）之敘述，何者正確？","options":["(A) 皆能抑制二氫蝶酸合成酶（dihydropteroate synthase）以阻斷DNA合成","(B) TMP：SMZ=1：5配方是因為TMP脂溶性較高","(C) 可使用在泌尿道感染，但無法用於治療肺囊蟲肺炎（P jirovecii pneumonia）","(D) TMP-SMZ藥物的多數副作用主要來自於TMP"],"answer":1,"image":""},{"id":"md2-113-2-53","subject":"md2","topic":"藥理-化學治療","meta":"113年第2次第53題","year":113,"session":2,"number":53,"question":"下列有關抗癌藥oxaliplatin之敘述，何者錯誤？","options":["(A) 病人對carboplatin產生抗藥性時，對oxaliplatin也會產生交叉抗藥性（cross-resistance）","(B) 為FOLFOX合併用藥之一，可治療轉移性大腸直腸癌","(C) 主要的劑量限制毒性（dose-limiting toxicity）為產生神經毒性","(D) 可用於治療實質固態瘤（solid tumor）"],"answer":0,"image":""},{"id":"md2-113-2-54","subject":"md2","topic":"藥理-化學治療","meta":"113年第2次第54題","year":113,"session":2,"number":54,"question":"下列癌症標靶治療藥物（targeted anticancer agents）與其機轉配對，何者正確？","options":["(A) carfilzomib—抑制Bcr-Abl tyrosine kinase的活性","(B) dasatinib—抑制26S proteosome的活性","(C) lapatinib—抑制PI3K的活性","(D) sunitinib—抑制VEGFR的活性"],"answer":3,"image":""},{"id":"md2-113-2-55","subject":"md2","topic":"藥理-化學治療","meta":"113年第2次第55題","year":113,"session":2,"number":55,"question":"下列藥物中，何者可抑制黴菌的squalene epoxidase，使sterol squalene堆積於菌體內而達殺菌作用？","options":["(A) griseofulvin","(B) nystatin","(C) terbinafine","(D) voriconazole"],"answer":2,"image":""},{"id":"md2-113-2-56","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第2次第56題","year":113,"session":2,"number":56,"question":"下列藥物中，何者主要與活化態淋巴球表面之CD25結合，而拮抗IL-2受體，可用於預防腎臟移植患者發生急性器官排斥？","options":["(A) basiliximab","(B) canakinumab","(C) dupilumab","(D) omalizumab"],"answer":0,"image":""},{"id":"md2-113-2-57","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"113年第2次第57題","year":113,"session":2,"number":57,"question":"下列藥物中，何者能促進plasminogen活化形成plasmin，以促進血栓分解？","options":["(A) bivalirudin","(B) tenecteplase","(C) apixaban","(D) vorapaxar"],"answer":1,"image":""},{"id":"md2-113-2-58","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"113年第2次第58題","year":113,"session":2,"number":58,"question":"下列何種降血脂藥，可藉由抑制microsomal triglyceride transfer protein（MTP），而阻斷肝臟生成及釋放VLDL？","options":["(A) lomitapide","(B) cholestyramine","(C) fenofibrate","(D) mipomersen"],"answer":0,"image":""},{"id":"md2-113-2-59","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第2次第59題","year":113,"session":2,"number":59,"question":"131碘-131（I）常用於治療甲狀腺毒症（thyrotoxicosis），下列關於此藥之敘述，何者錯誤？","options":["(A) 釋放β射線，破壞甲狀腺組織","(B) 孕婦禁用","(C) 哺餵母乳婦女可以減量使用","(D) 併用potassium iodide會降低其療效"],"answer":2,"image":""},{"id":"md2-113-2-60","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"113年第2次第60題","year":113,"session":2,"number":60,"question":"下列何者為醛固酮拮抗劑（aldosterone antagonist），可用於治療高血壓和心肌梗塞後之心衰竭？","options":["(A) eplerenone","(B) etoposide","(C) mestranol","(D) oxandrolone"],"answer":0,"image":""},{"id":"md2-113-2-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第2次第61題","year":113,"session":2,"number":61,"question":"下列降血糖藥與作用機轉的配對，何者錯誤？","options":["(A) pioglitazone—peroxisome proliferator-activated receptor gamma（PPAR-γ）agonist","(B) metformin—AMP-activated protein kinase（AMPK）activator","(C) exenatide—glucagon-like peptide-1（GLP-1）receptor agonist","(D) empagliflozin—sodium-glucose co-transporter 2（SGLT2）activator"],"answer":3,"image":""},{"id":"md2-113-2-62","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"113年第2次第62題","year":113,"session":2,"number":62,"question":"下列何種利尿劑，高血鉀病患不宜使用？","options":["(A) amiloride","(B) metolazone","(C) indapamide","(D) bumetanide"],"answer":0,"image":""},{"id":"md2-113-2-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"113年第2次第63題","year":113,"session":2,"number":63,"question":"下列藥物中，何者為phosphodiesterase type 3之抑制劑，可用於治療心衰竭？","options":["(A) empagliflozin","(B) tadalafil","(C) riociguat","(D) milrinone"],"answer":3,"image":""},{"id":"md2-113-2-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"113年第2次第64題","year":113,"session":2,"number":64,"question":"下列降血壓藥物中，何者最容易引起反射性心律加快（reflex tachycardia）的現象？","options":["(A) carvedilol","(B) diltiazem","(C) nifedipine","(D) propranolol"],"answer":2,"image":""},{"id":"md2-113-2-65","subject":"md2","topic":"藥理-總論與自主神經","meta":"113年第2次第65題","year":113,"session":2,"number":65,"question":"Atropine過量時，最不容易出現下列何種情況？","options":["(A) 心跳加快","(B) 唾液大量分泌","(C) 瞳孔放大","(D) 尿液滯留"],"answer":1,"image":""},{"id":"md2-113-2-66","subject":"md2","topic":"藥理-總論與自主神經","meta":"113年第2次第66題","year":113,"session":2,"number":66,"question":"使用dopamine靜脈輸注時，最不會產生下列何種作用？","options":["(A) 活化D1 receptor達到利鈉（natriuresis）效果","(B) 活化D2 receptor加快腸蠕動","(C) 活化β1 adrenergic receptor加快心跳","(D) 活化α1 adrenergic receptor提升血壓"],"answer":1,"image":""},{"id":"md2-113-2-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第2次第67題","year":113,"session":2,"number":67,"question":"下列何種藥物用於治療氣喘發作時，最需監測血中濃度，以避免產生噁心、嘔吐和心律不整副作用？","options":["(A) ipratropium","(B) corticosteroid","(C) theophylline","(D) albuterol"],"answer":2,"image":""},{"id":"md2-113-2-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第2次第68題","year":113,"session":2,"number":68,"question":"下列鴉片類藥物loperamide與diphenoxylate之比較，何者正確？","options":["(A) 兩者皆具有耐藥性（tolerance）","(B) 兩者皆可通過血腦屏障（blood-brain barrier）","(C) 長期使用時，兩者皆有成癮性（addiction）","(D) 兩者皆不具止痛作用（analgesia）"],"answer":3,"image":""},{"id":"md2-113-2-69","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"113年第2次第69題","year":113,"session":2,"number":69,"question":"Sumatriptan治療偏頭痛的作用機制為何？","options":["(A) 阻斷血管平滑肌的鈣離子通道使血管舒張","(B) 抑制環氧酶（cyclooxygenase）而減少前列腺素生成","(C) 拮抗血清素（serotonin）受體，以減少神經末梢釋放血管舒張物質","(D) 產生直接血管收縮作用，且減少對痛覺神經末梢的刺激"],"answer":3,"image":""},{"id":"md2-113-2-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第2次第70題","year":113,"session":2,"number":70,"question":"下列藥物何者是前列腺素的衍生物，具有子宮平滑肌收縮作用，臨床上可用來引產？","options":["(A) oxytocin","(B) dinoprostone","(C) ergonovine","(D) fasudil"],"answer":1,"image":""},{"id":"md2-113-2-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"113年第2次第71題","year":113,"session":2,"number":71,"question":"下列關於非固醇類抗發炎藥（NSAIDs）之敘述，何者錯誤？","options":["(A) 降低血管對緩激肽（bradykinin）和組織胺（histamine）的敏感性","(B) 重複給藥後，藥物可出現於關節滑液（synovial fluid）中，以治療關節炎","(C) 藥物會增強發炎所導致的血管舒張作用","(D) 選擇性COX-2抑制劑會增加水腫、高血壓或心肌梗塞的發生率"],"answer":2,"image":""},{"id":"md2-113-2-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"113年第2次第72題","year":113,"session":2,"number":72,"question":"下列有關局部麻醉劑的敘述，何者錯誤？","options":["(A) lidocaine的作用是抑制sodium channels","(B) bupivacaine的作用是興奮opioid receptors","(C) cocaine會產生血管收縮的效果","(D) benzocaine會產生methemoglobinemia的副作用"],"answer":1,"image":""},{"id":"md2-113-2-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"113年第2次第73題","year":113,"session":2,"number":73,"question":"請排序下列抗憂鬱藥物（antidepressants）的分類，依序為selective serotonin reuptake inhibitor、serotonin-norepinephrine reuptake inhibitor、tricyclic antidepressant及unicyclic antidepressant：","options":["(A) citalopram、duloxetine、imipramine、bupropion","(B) duloxetine、citalopram、bupropion、imipramine","(C) citalopram、imipramine、duloxetine、bupropion","(D) duloxetine、bupropion、imipramine、citalopram"],"answer":0,"image":""},{"id":"md2-113-2-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"113年第2次第74題","year":113,"session":2,"number":74,"question":"下列何者為鴉片衍生物，具有明顯止咳作用，且最不具有成癮性？","options":["(A) methadone","(B) dextromethorphan","(C) codeine","(D) loperamide"],"answer":1,"image":""},{"id":"md2-113-2-75","subject":"md2","topic":"藥理-化學治療","meta":"113年第2次第75題","year":113,"session":2,"number":75,"question":"下列藥物中，何者可抑制alcohol dehydrogenase，用於治療甲醇中毒？","options":["(A) flumazenil","(B) fomepizole","(C) pralidoxime","(D) physostigmine"],"answer":1,"image":""},{"id":"md2-113-2-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"113年第2次第76題","year":113,"session":2,"number":76,"question":"跌倒2週後，瘀青處做切片檢查，發現黃棕色之色素，最可能為：","options":["(A) 脂褐素（lipofuscin）","(B) 膽紅素（bilirubin）","(C) 黑色素（melanin）","(D) 血鐵素（hemosiderin）"],"answer":3,"image":""},{"id":"md2-113-2-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"113年第2次第77題","year":113,"session":2,"number":77,"question":"某病人有腎臟病變，組織表現為壞死現象，細胞質內胞器消失，細胞核溶解，但組織外形完整，且與周圍正常組織分界清楚，此為何類壞死？","options":["(A) 液化性壞死","(B) 乾酪化壞死","(C) 類纖維蛋白性壞死","(D) 凝固性壞死"],"answer":3,"image":""},{"id":"md2-113-2-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"113年第2次第78題","year":113,"session":2,"number":78,"question":"下列遺傳疾病，何者較適合利用重覆引子聚合酶連鎖反應法（repeat-primer polymerase chain reaction）進行篩檢再配合南方轉漬分析（Southern blot），則可以得到較確定的診斷？","options":["(A) 透納氏症候群（Turner syndrome）","(B) 狄喬治氏症候群（DiGeorge syndrome）","(C) X染色體脆折症（Fragile X syndrome）","(D) 尼曼匹克症（Niemann-Pick disease）"],"answer":2,"image":""},{"id":"md2-113-2-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"113年第2次第79題","year":113,"session":2,"number":79,"question":"下列有關結核菌素試驗（tuberculin test）原理之敘述，何者正確？","options":["(A) 主要是藉由刺激巨噬細胞（macrophages），釋放出伽瑪干擾素（γ-interferon）","(B) 主要是藉由刺激T淋巴細胞（lymphocytes），釋放出伽瑪干擾素（γ-interferon）","(C) 主要是藉由刺激巨噬細胞（macrophages），釋放出腫瘤壞死因子（tumor necrotic factor）","(D) 主要是藉由刺激T淋巴細胞（lymphocytes），釋放出腫瘤壞死因子（tumor necrotic factor）"],"answer":1,"image":""},{"id":"md2-113-2-80","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"113年第2次第80題","year":113,"session":2,"number":80,"question":"下列何者與鎘（cadmium）中毒之相關性較低？","options":["(A) 肺癌（lung cancer）","(B) 骨質疏鬆（osteoporosis）","(C) 畸胎瘤（teratoma）","(D) 腎損傷（kidney injury）"],"answer":2,"image":""},{"id":"md2-113-2-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"113年第2次第81題","year":113,"session":2,"number":81,"question":"下列何者是用來判定為惡性腫瘤可靠性最高的指標？","options":["(A) 細胞的分化差或未分化","(B) 生長速度快及有絲分裂","(C) 局部侵襲","(D) 轉移至其它器官"],"answer":3,"image":""},{"id":"md2-113-2-82","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"113年第2次第82題","year":113,"session":2,"number":82,"question":"下列抑癌蛋白何者最不具有直接調控細胞週期的功能？","options":["(A) RB","(B) p53","(C) E-cadherin","(D) p16/INK4a"],"answer":2,"image":""},{"id":"md2-113-2-83","subject":"md2","topic":"病理-心血管血液","meta":"113年第2次第83題","year":113,"session":2,"number":83,"question":"下列血管炎何者於顯微鏡下最少出現肉芽腫性發炎（granulomatous inflammation）？","options":["(A) Churg-Strauss syndrome","(B) Microscopic polyangiitis","(C) 川崎氏症（Kawasaki disease）","(D) Buerger disease"],"answer":[1,2,3],"image":"","answer_note":"更正:第83題答Ｂ或Ｃ或Ｄ或BC或BD或CD或BCD者均給分"},{"id":"md2-113-2-84","subject":"md2","topic":"病理-心血管血液","meta":"113年第2次第84題","year":113,"session":2,"number":84,"question":"馬凡氏症候群（Marfan syndrome）的病人在心臟瓣膜上最常出現的病理變化為何？","options":["(A) 主動脈瓣連合處融合（commissural fusion of aortic valve）","(B) 主動脈瓣鈣化","(C) 二尖瓣出現黏液性變性（myxomatous degeneration）","(D) 二尖瓣連合處融合（commissural fusion of mitral valve）"],"answer":2,"image":""},{"id":"md2-113-2-85","subject":"md2","topic":"病理-心血管血液","meta":"113年第2次第85題","year":113,"session":2,"number":85,"question":"下列何者最可能引起次發性骨髓化生不良症候群（secondary myelodysplastic syndrome）？","options":["(A) 長期缺乏鈣質","(B) 接受抗癌化學治療","(C) 接受骨質疏鬆藥物治療","(D) 服用抗結核藥物"],"answer":1,"image":""},{"id":"md2-113-2-86","subject":"md2","topic":"病理-心血管血液","meta":"113年第2次第86題","year":113,"session":2,"number":86,"question":"有關脾梗塞（splenic infarct）的敘述，下列何者正確？","options":["(A) 脾臟有豐富的側枝循環（collateral circulation），所以極少發生梗塞","(B) 脾腫大（splenomegaly）不是造成脾梗塞的好發因子","(C) 在正常大小的脾臟，最常造成脾梗塞的原因是心臟來的栓子（emboli）","(D) 脾梗塞經常造成大量的腹腔內出血"],"answer":2,"image":""},{"id":"md2-113-2-87","subject":"md2","topic":"病理-心血管血液","meta":"113年第2次第87題","year":113,"session":2,"number":87,"question":"下列何者為影響肺栓塞（pulmonary embolism）嚴重度最重要的因素？","options":["(A) 造成栓塞（embolism）的原因","(B) 栓子（embolus）的成分","(C) 栓子（embolus）的大小","(D) 栓子（embolus）的來源"],"answer":2,"image":""},{"id":"md2-113-2-88","subject":"md2","topic":"病理-呼吸消化","meta":"113年第2次第88題","year":113,"session":2,"number":88,"question":"造成病毒性肺炎的病原，下列何者最不常見？","options":["(A) 輪狀病毒（rotavirus）","(B) 副流感病毒（parainfluenza virus）","(C) 流感病毒（influenza virus）","(D) 腺病毒（adenovirus）"],"answer":0,"image":""},{"id":"md2-113-2-89","subject":"md2","topic":"病理-呼吸消化","meta":"113年第2次第89題","year":113,"session":2,"number":89,"question":"有關慢性支氣管炎的特徵，下列何者最不適當？","options":["(A) 黏液分泌過多（hypersecretion of mucus）","(B) 嗜酸性白血球增加（eosinophilia）","(C) 支氣管上皮杯狀細胞化生（goblet cell metaplasia）","(D) 抽菸（cigarette smoking）為最重要危險因子"],"answer":1,"image":""},{"id":"md2-113-2-90","subject":"md2","topic":"病理-呼吸消化","meta":"113年第2次第90題","year":113,"session":2,"number":90,"question":"下列疾病與檢驗配對之敘述，何者最不適當？","options":["(A) primary biliary cirrhosis病人90%以上的病人有anti-mitochondrial抗體","(B) antinuclear antibody（ANA）及anti-smooth muscle antibody為第一型自體免疫性肝炎的血清指標","(C) 第二型自體免疫性肝炎的血清指標為anti-liver kidney microsomal antibodies（anti-LKM1）","(D) 約在65%的primary sclerosing cholangititis病人可檢測出cytoplasmic antineutrophil cytoplasmic antibodies（cANCA）"],"answer":3,"image":""},{"id":"md2-113-2-91","subject":"md2","topic":"病理-呼吸消化","meta":"113年第2次第91題","year":113,"session":2,"number":91,"question":"關於膽囊膽固醇結石（cholesterol stone）產生機制，下列敘述何者錯誤？","options":["(A) 膽汁中鈣離子過飽和","(B) 膽囊運動不足（hypomotility）","(C) 加速膽固醇晶體成核（nucleation）","(D) 黏液分泌過多"],"answer":0,"image":""},{"id":"md2-113-2-92","subject":"md2","topic":"病理-呼吸消化","meta":"113年第2次第92題","year":113,"session":2,"number":92,"question":"30歲男性因健康檢查時發現迴腸末端有一個1公分的黏膜下腫瘤因而接受手術。病理醫師檢查該腫瘤的切面是黃色的，在顯微鏡下觀察如附圖，細胞含chromogranin及synaptophysin。下列何者為最可能的診斷？","options":["(A) 增生性息肉（hyperplastic polyp）","(B) 小管狀腺瘤（tubular adenoma）","(C) 神經內分泌腫瘤（neuroendocrine tumor）","(D) 腺癌（adenocarcinoma）"],"answer":2,"image":"md2-113-2-92.jpeg"},{"id":"md2-113-2-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"113年第2次第93題","year":113,"session":2,"number":93,"question":"毒物引起之急性腎小管壞死其壞死部位最不可能發生在：","options":["(A) 近曲小管（proximal convoluted tubules）","(B) 亨耳氏環上升支（ascending limbs of Henle's loop）","(C) 近曲小管直部（straight segments of proximal tubules）","(D) 集尿管（collecting ducts）"],"answer":3,"image":""},{"id":"md2-113-2-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"113年第2次第94題","year":113,"session":2,"number":94,"question":"最常造成次發性副甲狀腺功能亢進症（Secondary hyperparathyroidism）的原因是：","options":["(A) MEN1 mutation","(B) CCND1 gene inversion","(C) Renal failure","(D) Multiple endocrine neoplasia"],"answer":2,"image":""},{"id":"md2-113-2-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"113年第2次第95題","year":113,"session":2,"number":95,"question":"最常造成腦下垂體機能亢進的原因是：","options":["(A) 前葉腺瘤","(B) 前葉增生","(C) 前葉癌","(D) 下視丘疾病"],"answer":0,"image":""},{"id":"md2-113-2-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"113年第2次第96題","year":113,"session":2,"number":96,"question":"測量血清中前列腺特定抗原（prostatic-specific antigen, PSA）的濃度已經被廣泛用來協助診斷或處理前列腺癌（prostate cancer），下列有關前列腺特定抗原或其改良型測量方法的敘述，何者最不適當？","options":["(A) 前列腺特定抗原為前列腺上皮所生成","(B) 除了前列腺癌外，良性前列腺增生症、前列腺炎等情況，都會造成血清中前列腺特定抗原濃度上升","(C) 有關前列腺特定抗原上升速率（PSA velocity），一般而言，前列腺癌病人的上升速率高於沒有前列腺癌的病人","(D) 游離與總前列腺特異抗原比值（free PSA/total PSA），一般而言，前列腺癌病人的比值高於良性前列腺疾病的病人"],"answer":3,"image":""},{"id":"md2-113-2-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"113年第2次第97題","year":113,"session":2,"number":97,"question":"20歲女生最近覺得下腹部腹脹不舒服，超音波檢查發現右側卵巢有一個約7公分大的腫瘤，經手術切取後腫瘤外觀表面平滑，腫瘤切面觀察有固體部分也有壞死及出血區域，同時含有毛髮及像牙齒一樣的物質。切片下出現一些像胚胎時期的神經上皮細胞（neuroepithelium），則下列何者為最有可能之診斷？","options":["(A) 成熟畸胎瘤（mature teratoma）","(B) 漿液性囊狀腺癌（serous cystadenocarcinoma）","(C) 未成熟畸胎瘤（immature teratoma）","(D) 胚胎性癌（embryonal carcinoma）"],"answer":2,"image":""},{"id":"md2-113-2-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"113年第2次第98題","year":113,"session":2,"number":98,"question":"下列那一種分子是由造骨母細胞（osteoblasts）或骨間質細胞（stromal cells）所製造分泌，並用來結合RANK ligand（RANKL），進而阻礙RANKL與蝕骨細胞（osteoclast precursors）上的RANK作用？","options":["(A) Wnt","(B) LRP5/6","(C) osteoprotegerin","(D) RUNX2"],"answer":2,"image":""},{"id":"md2-113-2-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"113年第2次第99題","year":113,"session":2,"number":99,"question":"下列有關軸突性周邊神經病變（peripheral axonal neuropathy）之敘述，何者錯誤？","options":["(A) 破壞解離的髓鞘可形成myelin ovoids","(B) Wallerian degeneration起自周邊神經傷害處近端，往神經元細胞體中心進行","(C) 修復過程有時會產生traumatic neuroma","(D) 再生之軸突髓鞘（myelin sheath）比未受病變前之髓鞘細薄"],"answer":1,"image":""},{"id":"md2-113-2-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"113年第2次第100題","year":113,"session":2,"number":100,"question":"因腦壓太高造成的herniation，導致的Duret hemorrhage，發生於何處？","options":["(A) 大腦灰質","(B) 大腦白質","(C) 腦幹","(D) 小腦"],"answer":2,"image":""},{"id":"md2-114-1-1","subject":"md2","topic":"細菌學","meta":"114年第1次第1題","year":114,"session":1,"number":1,"question":"細菌若具有攝取並利用外源性胸腺嘧啶（exogenous thymidine）之能力，通常對於下列何種抗生素具有抗藥性？","options":["(A) 甲氧苄啶（trimethoprim）","(B) 立汎黴素（rifampin）","(C) 克林黴素（clindamycin）","(D) 安比西林（ampicillin）"],"answer":0,"image":""},{"id":"md2-114-1-2","subject":"md2","topic":"細菌學","meta":"114年第1次第2題","year":114,"session":1,"number":2,"question":"下列有關原生質體（protoplast）之敘述，何者最適當？","options":["(A) 具有莢膜（capsule）結構之菌體","(B) 細胞壁（cell wall）結構缺損之菌體","(C) 只發生在革蘭氏陽性菌","(D) 能生長於嚴苛環境（如高溫、高鹽等環境）的古細菌（archaea）"],"answer":1,"image":""},{"id":"md2-114-1-3","subject":"md2","topic":"細菌學","meta":"114年第1次第3題","year":114,"session":1,"number":3,"question":"下列與細菌有關的構造及衍生物，何種較能防止抗生素清除細菌的作用？","options":["(A) 鞭毛（flagellum）","(B) 線毛（pilus）","(C) 生物膜（biofilm）","(D) 莢膜（capsule）"],"answer":2,"image":""},{"id":"md2-114-1-4","subject":"md2","topic":"細菌學","meta":"114年第1次第4題","year":114,"session":1,"number":4,"question":"結核菌素皮膚測試（tuberculin skin test）所使用的purified protein derivatives（PPDs）是從結核桿菌何處純化出來的結合蛋白質？","options":["(A) 細菌細胞壁","(B) 宿主細胞核","(C) 細菌染色體","(D) 細菌質體"],"answer":0,"image":""},{"id":"md2-114-1-5","subject":"md2","topic":"細菌學","meta":"114年第1次第5題","year":114,"session":1,"number":5,"question":"下列那一株菌會污染海鮮，並產生熱穩定溶血素（thermostable direct hemolysin, Kanagawa hemolysin）引起食物中毒？","options":["(A) 大腸桿菌（Escherichia coli）","(B) 霍亂弧菌（Vibrio cholera）","(C) 腸炎弧菌（Vibrio parahaemolyticus）","(D) 金黃色葡萄球菌（Staphylococcus aureus）"],"answer":2,"image":""},{"id":"md2-114-1-6","subject":"md2","topic":"細菌學","meta":"114年第1次第6題","year":114,"session":1,"number":6,"question":"細菌的超級抗原（superantigens）主要具有下列何種特性？","options":["(A) 能在真核細胞的細胞膜上打洞","(B) 不需經抗原處理（antigen processing），本身就可活化免疫細胞","(C) 可抑制巨噬細胞（macrophages）的吞噬作用","(D) 可抑制巨噬細胞內的顆粒釋放內容物（degranulation）"],"answer":1,"image":""},{"id":"md2-114-1-7","subject":"md2","topic":"細菌學","meta":"114年第1次第7題","year":114,"session":1,"number":7,"question":"有關以色列放線菌（Actinomyces israelii）之敘述，下列何者最適當？","options":["(A) 屬絕對需氧菌","(B) 具臼齒（molar）狀菌落","(C) 通常對青黴素（penicillin）具抗性","(D) 和丙酸桿菌（Propionibacterium）皆為革蘭氏陰性菌"],"answer":1,"image":""},{"id":"md2-114-1-8","subject":"md2","topic":"細菌學","meta":"114年第1次第8題","year":114,"session":1,"number":8,"question":"超級抗藥性結核菌（extensively drug-resistant TB, XDR-TB）的定義是多重抗藥性結核菌（multidrug- resistant Mycobacterium tuberculosis , MDR-TB），除對卡納黴素（kanamycin）、阿米卡星（amikacin）與捲曲黴素（capreomycin）三種藥物中任一種具有抗藥性，且對下列那一類藥物具有抗藥性？","options":["(A) 他唑巴坦（tazobactam）","(B) 伊曲康唑（itraconazole）","(C) 氟喹諾酮（fluoroquinolone）","(D) 米替福新（miltefosine）"],"answer":2,"image":""},{"id":"md2-114-1-9","subject":"md2","topic":"細菌學","meta":"114年第1次第9題","year":114,"session":1,"number":9,"question":"關於普氏立克次體（Rickettsia prowazekii）的敘述，下列何者最不適當？","options":["(A) 是造成流行性斑疹傷寒（epidemic typhus）的病原菌","(B) 能透過人類體蝨（human body louse）叮咬而傳染","(C) 病原菌不會潛伏於人體","(D) 血清學診斷可以用微免疫螢光試驗（microimmunofluorescence, MIF）為參考方法"],"answer":2,"image":""},{"id":"md2-114-1-10","subject":"md2","topic":"病毒學","meta":"114年第1次第10題","year":114,"session":1,"number":10,"question":"下列有關病毒感染細胞之病變機制，何者最適當？","options":["(A) 單純疱疹病毒（herpes simplex virus）感染之細胞核內可形成Cowdry type A包涵體（Cowdry type A inclusion body）","(B) 腸病毒（enterovirus）感染之細胞會發生細胞融合（syncytia）現象","(C) 德國麻疹病毒（rubella virus）感染之細胞質會形成Negri包涵體（Negri body）","(D) 腺病毒（adenovirus）主要是透過與細胞膜的融合入侵細胞"],"answer":0,"image":""},{"id":"md2-114-1-11","subject":"md2","topic":"病毒學","meta":"114年第1次第11題","year":114,"session":1,"number":11,"question":"抗流感病毒（influenza virus）藥物金剛烷胺（amantadine），其主要作用是抑制該病毒複製的何項步驟？","options":["(A) 接觸（attachment）","(B) 穿過細胞膜進入細胞及解散外殼","(C) 病毒轉錄","(D) 蛋白質合成"],"answer":1,"image":""},{"id":"md2-114-1-12","subject":"md2","topic":"病毒學","meta":"114年第1次第12題","year":114,"session":1,"number":12,"question":"下列那一個肝炎病毒感染最有可能在一般人造成約1%～2%的致死率，但在懷孕婦女則可能有高達20%的致死率？","options":["(A) Hepatitis A virus","(B) Hepatitis C virus","(C) Hepatitis D virus","(D) Hepatitis E virus"],"answer":3,"image":""},{"id":"md2-114-1-13","subject":"md2","topic":"病毒學","meta":"114年第1次第13題","year":114,"session":1,"number":13,"question":"有關水痘病毒的敘述，下列何者最不適當？","options":["(A) 水痘病毒會復發（reactivation），但終身只會得到一次帶狀疱疹","(B) 有治療水痘病毒感染的抗病毒藥物","(C) 有水痘病毒疫苗","(D) 潛伏在神經細胞中"],"answer":0,"image":""},{"id":"md2-114-1-14","subject":"md2","topic":"病毒學","meta":"114年第1次第14題","year":114,"session":1,"number":14,"question":"有關腸病毒（enterovirus）的敘述，何者最不適當？","options":["(A) 腸病毒只在腸胃道細胞複製","(B) 屬於小RNA病毒科（Picornaviridae）","(C) 糞口為主要傳染管道","(D) 大部分的腸病毒感染不會造成如肢體麻痺（paralytic disease）等重症"],"answer":0,"image":""},{"id":"md2-114-1-15","subject":"md2","topic":"病毒學","meta":"114年第1次第15題","year":114,"session":1,"number":15,"question":"關於狂犬病病毒（Rabies virus）的敘述，下列何者最適當？","options":["(A) 感染後，病毒不會在肌肉細胞複製","(B) 被帶有狂犬病病毒的狗咬傷後立刻施打抗病毒免疫球蛋白，再配合疫苗施打，可有效防止狂犬病的發生","(C) 狂犬病病毒的基因體為環狀DNA","(D) 犬類是狂犬病病毒的唯一宿主"],"answer":1,"image":""},{"id":"md2-114-1-16","subject":"md2","topic":"真菌學","meta":"114年第1次第16題","year":114,"session":1,"number":16,"question":"下列何種念珠菌芽管測試（germ tube test）為陽性？","options":["(A) Candida tropicalis","(B) Candida albicans","(C) Candida parapsilosis","(D) Candida krusei"],"answer":1,"image":""},{"id":"md2-114-1-17","subject":"md2","topic":"真菌學","meta":"114年第1次第17題","year":114,"session":1,"number":17,"question":"下列那一種抗真菌（anti-fungal）藥物，主要抑制真菌細胞麥角固醇（ergosterol）的合成？","options":["(A) 華光黴素Z（nikkomycin Z）","(B) 卡泊芬淨（caspofungin）","(C) 酮康唑（ketoconazole）","(D) 制黴菌素（nystatin）"],"answer":2,"image":""},{"id":"md2-114-1-18","subject":"md2","topic":"免疫學","meta":"114年第1次第18題","year":114,"session":1,"number":18,"question":"下列有關先天性免疫系統對抗病原菌感染的敘述，何者最適當？","options":["(A) 先天性免疫細胞只有監測身體的功能，無法有效移除病原體","(B) 先天性免疫細胞無法提供專一性的保護力，且缺乏有效的記憶反應","(C) 先天性免疫細胞摧毀它們所遇到的一切，需要後天性免疫來調節抑制這個過程","(D) 先天性免疫細胞分泌的細胞激素和趨化因子在沒有後天性免疫的情況下具有毒性"],"answer":1,"image":""},{"id":"md2-114-1-19","subject":"md2","topic":"免疫學","meta":"114年第1次第19題","year":114,"session":1,"number":19,"question":"病原菌感染時，在感染處引起先天性免疫發炎反應，吸引下列何種血液中的免疫細胞最快來到感染處？","options":["(A) B細胞","(B) NK細胞","(C) 嗜中性白血球","(D) CD8毒殺T細胞"],"answer":2,"image":""},{"id":"md2-114-1-20","subject":"md2","topic":"免疫學","meta":"114年第1次第20題","year":114,"session":1,"number":20,"question":"下列對於MHC分子的描述，何者最不適當？","options":["(A) MHC class I及MHC class II分子是由多個基因所表達（polygenic）","(B) MHC class III的基因產物在免疫系統中不具功能","(C) 每一個表達MHC class I及MHC class II分子的基因是具有基因多型性（polymorphism）","(D) MHC class II分子間的差異大部分是在β1 region上的胺基酸序列"],"answer":1,"image":""},{"id":"md2-114-1-21","subject":"md2","topic":"免疫學","meta":"114年第1次第21題","year":114,"session":1,"number":21,"question":"下列關於B細胞發育的敘述，何者最不適當？","options":["(A) 骨髓是B細胞開始進行發育的器官","(B) 會辨識自體抗原的B細胞可以在骨髓中被清除","(C) 會辨識自體抗原的B細胞可以在脾臟中被清除","(D) 無法表現替代輕鏈（surrogate light chain）的B細胞，發育時會停滯在immature B細胞時期"],"answer":3,"image":""},{"id":"md2-114-1-22","subject":"md2","topic":"免疫學","meta":"114年第1次第22題","year":114,"session":1,"number":22,"question":"T淋巴細胞生成與發育的位置為何？","options":["(A) 肺臟","(B) 脾臟","(C) 淋巴結","(D) 胸腺"],"answer":3,"image":""},{"id":"md2-114-1-23","subject":"md2","topic":"病理-免疫感染遺傳","meta":"114年第1次第23題","year":114,"session":1,"number":23,"question":"慢性感染Mycobacterium tuberculosis時，病人肺部常形成肉芽腫（granuloma），是一種群聚巨噬細胞及其他免疫細胞的病理組織，下列有關肉芽腫的敘述何者最不適當？","options":["(A) 巨噬細胞無法有效清除感染的Mycobacterium tuberculosis","(B) 被感染的巨噬細胞形成融合在一起的現象","(C) 常見TH17細胞圍繞在融合的巨噬細胞周圍","(D) 常見於病人帶有NADPH oxidase基因突變"],"answer":2,"image":""},{"id":"md2-114-1-24","subject":"md2","topic":"免疫學","meta":"114年第1次第24題","year":114,"session":1,"number":24,"question":"有關體細胞超突變（somatic hypermutation），下列敘述何者最不適當？","options":["(A) 主要發生在germinal center的B細胞中","(B) 由activation-induced cytidine deaminase（AID）在抗體的Fc region造成點突變","(C) 為促進親和力成熟（affinity maturation）的主要機制","(D) 可增加抗體的多樣性（diversity）"],"answer":1,"image":""},{"id":"md2-114-1-25","subject":"md2","topic":"細菌學","meta":"114年第1次第25題","year":114,"session":1,"number":25,"question":"肺結核是由Mycobacterium tuberculosis感染後引起的慢性傳染病。下列何者是造成該細菌長期潛伏於被感染的細胞內的最主要因素？","options":["(A) 複製繁殖力高","(B) 抵抗吞噬體的作用","(C) 抑制樹突細胞抗原呈獻","(D) 抗原變異性大"],"answer":1,"image":""},{"id":"md2-114-1-26","subject":"md2","topic":"免疫學","meta":"114年第1次第26題","year":114,"session":1,"number":26,"question":"下列何種自體免疫疾病，最主要是由T細胞攻擊組織，進而影響中樞神經系統功能？","options":["(A) 類風濕性關節炎","(B) 多發性硬化症","(C) 克隆氏症","(D) 紅斑性狼瘡"],"answer":1,"image":""},{"id":"md2-114-1-27","subject":"md2","topic":"免疫學","meta":"114年第1次第27題","year":114,"session":1,"number":27,"question":"在腫瘤微環境（tumor microenvironment）中，下列何者是最不具免疫抑制性的分子或細胞？","options":["(A) programmed death-1（PD-1）","(B) 調節性T細胞（regulatory T cell, Treg）","(C) M1巨噬細胞（M1 macrophage）","(D) interleukin 10（IL-10）"],"answer":2,"image":""},{"id":"md2-114-1-28","subject":"md2","topic":"免疫學","meta":"114年第1次第28題","year":114,"session":1,"number":28,"question":"以PD-L1單株抗體作為免疫癌症療法最主要的機轉，是阻斷下列何種細胞表現的PD-L1與PD-1的結合？","options":["(A) 巨噬細胞","(B) 樹突細胞","(C) T細胞","(D) 腫瘤細胞"],"answer":3,"image":""},{"id":"md2-114-1-29","subject":"md2","topic":"寄生蟲學","meta":"114年第1次第29題","year":114,"session":1,"number":29,"question":"關於馬來絲蟲（Brugia malayi），下列敘述何者正確？","options":["(A) 成蟲會侵犯患者眼睛造成失明","(B) 自皮膚切片（skin snips）發現成蟲為主要診斷方法","(C) 患者可能出現鼠蹊懸垂（hanging groin）","(D) 於患者血液之微絲蟲（microfilaria）尾端出現尾核"],"answer":3,"image":""},{"id":"md2-114-1-30","subject":"md2","topic":"寄生蟲學","meta":"114年第1次第30題","year":114,"session":1,"number":30,"question":"關於鞭蟲（Trichuris trichiura），下列敘述何者正確？①雌雄成蟲蟲體皆為前端細長，後端粗大 ②蟲卵兩端具透明卵塞（egg plug） ③慢性感染可造成貧血或脫肛（rectal prolapse） ④蟲卵形態與肝毛線蟲（Capillaria hepatica）蟲卵極為相似，須進行鑑別診斷","options":["(A) 僅①④","(B) ①③④","(C) ①②③","(D) ②③④"],"answer":2,"image":""},{"id":"md2-114-1-31","subject":"md2","topic":"寄生蟲學","meta":"114年第1次第31題","year":114,"session":1,"number":31,"question":"下列何種寄生蟲之蟲卵於小腸孵化後，可以藉由自體感染（autoinfection）方式重新感染同一宿主？","options":["(A) 短小包膜絛蟲（Hymenolepis nana）","(B) 縮小包膜絛蟲（Hymenolepis diminuta）","(C) 顆粒性包生絛蟲（Echinococcus granulosus）","(D) 犬複殖器絛蟲（Dipylidium caninum）"],"answer":0,"image":""},{"id":"md2-114-1-32","subject":"md2","topic":"寄生蟲學","meta":"114年第1次第32題","year":114,"session":1,"number":32,"question":"豬肉絛蟲（Taenia solium）比牛肉絛蟲（Taenia saginata）對人類造成的病變更為嚴重，最主要原因是：","options":["(A) 前者的頭節具額嘴（rostellum）及小鉤，對腸黏膜的破壞較大","(B) 前者吸收較多營養，導致宿主衰弱","(C) 前者分泌的毒素（toxin）作用較強，造成宿主產生病變","(D) 前者會造成人類的囊尾幼蟲症（human cysticercosis）"],"answer":3,"image":""},{"id":"md2-114-1-33","subject":"md2","topic":"寄生蟲學","meta":"114年第1次第33題","year":114,"session":1,"number":33,"question":"有關枯西氏錐蟲（Trypanosoma cruzi）及其造成的疾病，下列敘述何者最為適當？","options":["(A) 當病媒椿象（triatoma bug）叮咬人類後，無鞭毛體（amastigote）會進入體內，藉由連續分裂方式形成偽囊體（pseudocyst）後留在組織中","(B) 患者會出現眼瞼浮腫、結膜腫大，臨床上稱為後頸淋巴結腫大（Winterbottom's sign）","(C) 患者出現的巨食道症（megaesophagus）或是巨結腸症（megacolon）等症狀，係肇因於補體（complement）攻擊神經節後的結果","(D) 性行為與輸血均可傳播本疾病"],"answer":3,"image":""},{"id":"md2-114-1-34","subject":"md2","topic":"寄生蟲學","meta":"114年第1次第34題","year":114,"session":1,"number":34,"question":"有關寄生於人體腸道之鞭毛蟲，下列敘述何者最為適當？","options":["(A) 生活史中只需要一個宿主，且經口感染","(B) 均寄生於小腸","(C) 感染型（infective form）都是囊體期（cyst stage）","(D) 人腸道滴蟲（Pentatrichomonas hominis）之副基體（parabasal body）是其粒線體核酸集中的區域"],"answer":0,"image":""},{"id":"md2-114-1-35","subject":"md2","topic":"寄生蟲學","meta":"114年第1次第35題","year":114,"session":1,"number":35,"question":"下列有關病媒（vector）的敘述，何者最為適當？","options":["(A) 蒼蠅主要藉由經卵傳播（transovarial transmission）而媒介病原體","(B) 腮腺炎是藉由昆蟲為媒介而傳染","(C) 節肢動物的馬氏管（Malpighian tubules）主要負責移除含氮廢物","(D) 防治病媒蚊無法遏阻登革熱的流行"],"answer":2,"image":""},{"id":"md2-114-1-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第1次第36題","year":114,"session":1,"number":36,"question":"已知某一個隨機試驗須利用自由度為18的t檢定（t-test）評估利尿劑（diuretic）是否有效，α=0.01，經過計算後統計檢定力為0.27（power=0.27）。下列敘述何者正確？","options":["(A) 此試驗的顯著水準是5％","(B) 在對立假說為真的情況下，此試驗p值小於1％的機率為0.27","(C) 此試驗虛無假設的可能性為0.27","(D) 此試驗的型二錯誤為0.27"],"answer":1,"image":""},{"id":"md2-114-1-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第1次第37題","year":114,"session":1,"number":37,"question":"為了解大學生之平均BMI為何（假設母體BMI標準差為2），A研究者自母體隨機抽取100位大學生得其平均BMI為21.5，B研究者自母體隨機抽取225位大學生得其平均BMI為22.5。A、B研究者利用自己收集之資料計算母體平均BMI之95％信賴區間（confidence interval, CI），下列敘述何者最恰當？","options":["(A) A研究者計算之95％ CI意義為約95％的大學生之BMI可能出現之範圍","(B) A研究者計算之95％ CI寬度會是B研究者計算之95％ CI寬度的1.5倍","(C) 因信心水準皆為95％，故A研究者計算之95％ CI寬度會與B研究者計算之95％ CI寬度相同","(D) A研究者計算之95％ CI中點會與B研究者計算之95％ CI中點相同"],"answer":1,"image":""},{"id":"md2-114-1-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第1次第38題","year":114,"session":1,"number":38,"question":"某篩檢工具同時在A、B兩個年齡類似的族群進行女性乳癌篩檢。篩檢數據顯示，A族群偽陽性（false- positive）個案在所有A族群陽性個案中的占比（proportion），明顯高於B族群中偽陽性個案在所有B族群陽性個案中的占比。下列敘述用於解釋這樣的現象何者最恰當？","options":["(A) 該篩檢工具於A族群使用時其特異度（specificity）較低","(B) 該篩檢工具於A族群使用時其敏感度（sensitivity）較低","(C) A族群的乳癌盛行率明顯低於B族群的可能性非常高","(D) A族群的乳癌發生率明顯高於B族群的可能性非常高"],"answer":2,"image":""},{"id":"md2-114-1-39","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"114年第1次第39題","year":114,"session":1,"number":39,"question":"有關我國職業病認定的描述，下列何者最不適當？","options":["(A) 職業病的認定以「勞工保險職業病種類表」正面表列為原則，表中沒有列的疾病，原則上不認定為職業病","(B) 「勞工保險職業病種類表」表中沒有列的疾病，經醫師認定由工作引起，可以視為職業病而接受勞工保險職業災害補償","(C) 精神疾病與執行職務有相當因果關係者，可以視為職業病而接受勞工保險職業災害補償","(D) 勞工原有高血壓，因短期內過度超時工作而促發腦出血，可以視為職業病而接受勞工保險職業災害補償"],"answer":1,"image":""},{"id":"md2-114-1-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"114年第1次第40題","year":114,"session":1,"number":40,"question":"毒性及關注化學物質管理，公告列管毒性化學物質，下列何者錯誤？","options":["(A) 第一類，致癌物質","(B) 第二類，慢毒性物質","(C) 第三類，急毒性物質","(D) 第四類，疑似毒化物"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第40題一律給分 (原公告答案 A)"},{"id":"md2-114-1-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"114年第1次第41題","year":114,"session":1,"number":41,"question":"肉品高溫處理過程中，最可能產生下列何種有害物質？","options":["(A) 異環胺","(B) 砷","(C) 黃麴毒素","(D) 三聚氰胺"],"answer":0,"image":""},{"id":"md2-114-1-42","subject":"md2","topic":"細菌學","meta":"114年第1次第42題","year":114,"session":1,"number":42,"question":"白喉桿菌可為生物氣膠而導致疾病發生，主要的機制為何？","options":["(A) 桿菌對寄主的侵襲力","(B) 桿菌對寄主的過敏性","(C) 桿菌內毒素毒性影響","(D) 桿菌外毒素毒性影響"],"answer":3,"image":""},{"id":"md2-114-1-43","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第1次第43題","year":114,"session":1,"number":43,"question":"有關健康促進與衛生教育介入方案策略的敘述，下列何者最不恰當？","options":["(A) 推動各項策略之前，應事先規劃及選擇想要改變的個人、人際、組織和社區的決定因素","(B) 根據過往的經驗顯示，不應期望單一的策略投入會對健康行為產生重大的持久影響","(C) 計畫執行需運用多元策略，因此在策略規劃時不需將特定的個人素質因素納入考量","(D) 一個成功的健康促進與衛生教育計畫必須選擇適當的策略去執行，以達成計畫目標"],"answer":2,"image":""},{"id":"md2-114-1-44","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第1次第44題","year":114,"session":1,"number":44,"question":"下列針對健康促進計畫常見需要評價（evaluation）面向的描述，何者正確？ ①忠誠（fidelity）：確認內部員工和夥伴有發揮其責任 ②涵蓋（inclusion）：在計畫當中，每位工作夥伴都有負責其適當的工作 ③多元性（multiplicity）：評價者需確定計畫的方向或對於優先族群需求的合適程度 ④達成（reach）：優先族群有機會參與計畫、活動或服務的百分比 ⑤回應（response）：優先族群的受益百分比，或是計畫介入策略的執行頻率與強度 ⑥計量（dose）：優先族群確實參與計畫、活動或服務的百分比 ⑦方向性（orientation）：意指計畫需要被有企圖地執行或按部就班地執行 ⑧判斷（justification）：計畫、服務或活動被相關利益者所執行或認可，並且藉由需求評估資料與分析進行判斷的程度","options":["(A) ②④⑧","(B) ①④⑧","(C) ③⑤⑥","(D) ⑥⑦⑧"],"answer":0,"image":""},{"id":"md2-114-1-45","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"114年第1次第45題","year":114,"session":1,"number":45,"question":"我國於2006年起透過政策鼓勵醫院調整過去醫療為主的思維，改以健康促進為服務導向，先後推動「健康促進醫院」與「健康醫院」認證，下列相關敘述，何者錯誤？","options":["(A) 健康醫院認證目前已邁入2.0版","(B) 我國已加入世界衛生組織（WHO）健康促進醫院國際網絡，成為國家／區域網絡會員","(C) 氣候行動非為目前健康醫院認證的標準項目","(D) 醫院為符合認證健康醫院的基本資格，在願景與目標中要能呈現可見具承諾性的臨床健康促進政策"],"answer":2,"image":""},{"id":"md2-114-1-46","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"114年第1次第46題","year":114,"session":1,"number":46,"question":"進入社區進行健康營造工作者，最不宜扮演下列何種角色？","options":["(A) 促成者","(B) 考核者","(C) 協調者","(D) 執行者"],"answer":1,"image":""},{"id":"md2-114-1-47","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第1次第47題","year":114,"session":1,"number":47,"question":"我國推行新生兒篩檢政策，屬於公共衛生三段五級預防策略中那一級？","options":["(A) 第一級預防策略","(B) 第二級預防策略","(C) 第三級預防策略","(D) 第四級預防策略"],"answer":2,"image":""},{"id":"md2-114-1-48","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"114年第1次第48題","year":114,"session":1,"number":48,"question":"全民健保的支付制度中，總額預算的一般預算的公式，包含協商因子和非協商因子，下列何者不屬於協商因子？","options":["(A) 新藥新科技","(B) 推動支付制度改革","(C) 醫療服務成本","(D) 品質獎勵金（品質保證保留款）"],"answer":2,"image":""},{"id":"md2-114-1-49","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第1次第49題","year":114,"session":1,"number":49,"question":"有關我國在愛滋病防治的敘述，何者最不適當？","options":["(A) 主要法源依據之一為傳染病防治法","(B) 在2030年前達成國際消除愛滋90-90-90目標","(C) 提高感染者知道自己感染狀態的比率是目標指標之一","(D) 鼓勵在暴露愛滋病毒前進行預防性投藥"],"answer":1,"image":""},{"id":"md2-114-1-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"114年第1次第50題","year":114,"session":1,"number":50,"question":"下列何項不是由政府衛生主管機關規範或辦理之醫療品質提升制度？","options":["(A) 訂立醫療機構設置標準","(B) 發展臨床路徑和參加ISO品質認證","(C) 辦理醫院評鑑","(D) 建立醫事人員執業登記及繼續教育辦法"],"answer":1,"image":""},{"id":"md2-114-1-51","subject":"md2","topic":"藥理-總論與自主神經","meta":"114年第1次第51題","year":114,"session":1,"number":51,"question":"下列何種拮抗作用（antagonism）完全不需與受體（receptors）結合即可產生？","options":["(A) competitive antagonism","(B) allosteric antagonism","(C) chemical antagonism","(D) physiologic antagonism"],"answer":2,"image":""},{"id":"md2-114-1-52","subject":"md2","topic":"藥理-化學治療","meta":"114年第1次第52題","year":114,"session":1,"number":52,"question":"下列抗生素中，何者長期使用最容易造成8歲以下兒童產生牙齒、骨骼之傷害？","options":["(A) erythromycin","(B) omadacycline","(C) clindamycin","(D) cephalexin"],"answer":1,"image":""},{"id":"md2-114-1-53","subject":"md2","topic":"藥理-化學治療","meta":"114年第1次第53題","year":114,"session":1,"number":53,"question":"下列抗病毒藥物中，何者可對抗HIV病毒，用於治療愛滋病？","options":["(A) amantadine","(B) ganciclovir","(C) acyclovir","(D) zidovudine"],"answer":3,"image":""},{"id":"md2-114-1-54","subject":"md2","topic":"免疫學","meta":"114年第1次第54題","year":114,"session":1,"number":54,"question":"下列免疫檢查點抑制劑（immune checkpoint inhibitor），何者不是作用在T細胞？","options":["(A) pembrolizumab","(B) basiliximab","(C) atezolizumab","(D) ipilimumab"],"answer":2,"image":""},{"id":"md2-114-1-55","subject":"md2","topic":"藥理-化學治療","meta":"114年第1次第55題","year":114,"session":1,"number":55,"question":"下列抗癌藥物與其作用機轉之配對，何者正確？","options":["(A) etoposide—抑制thymidylate synthase","(B) irinotecan—抑制topoisomerase I","(C) pemetrexed—抑制topoisomerase II","(D) vinorelbine—抑制dihydrofolate reductase"],"answer":1,"image":""},{"id":"md2-114-1-56","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"114年第1次第56題","year":114,"session":1,"number":56,"question":"下列藥物中，何者為長效型凝血因子IX的製劑，用以預防或治療B型血友病（hemophilia B）病人出血的問題？","options":["(A) eloctate","(B) idelvion","(C) humate-P","(D) vonicog alfa"],"answer":1,"image":""},{"id":"md2-114-1-57","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"114年第1次第57題","year":114,"session":1,"number":57,"question":"下列藥物中，何者可增加血液循環中血小板的數量，最適合用於治療慢性免疫性血小板低下症（chronic immune thrombocytopenia）？","options":["(A) plerixafor","(B) pteroylglutamic acid","(C) romiplostim","(D) hydroxocobalamin"],"answer":2,"image":""},{"id":"md2-114-1-58","subject":"md2","topic":"免疫學","meta":"114年第1次第58題","year":114,"session":1,"number":58,"question":"當病人器官移植，使用免疫抑制劑mycophenolate mofetil（MMF）以緩解排斥作用發生，下列敘述何者正確？","options":["(A) MMF抑制淋巴細胞的pyrimidine生合成","(B) mycophenolic acid為不具活性之代謝成分","(C) MMF主要由CYP450 3A代謝","(D) 使用MMF可能產生嗜中性白血球低下症（neutropenia）之副作用"],"answer":3,"image":""},{"id":"md2-114-1-59","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第1次第59題","year":114,"session":1,"number":59,"question":"下列關於finasteride之敘述，何者錯誤？","options":["(A) 可用於早期雄性禿治療","(B) 可用於良性攝護腺肥大治療","(C) 可口服使用","(D) 是雄激素受體阻斷劑"],"answer":3,"image":""},{"id":"md2-114-1-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第1次第60題","year":114,"session":1,"number":60,"question":"下列何者為RANK ligand（RANKL）單株抗體製劑，可作為治療骨質疏鬆症之藥物？","options":["(A) adalimumab","(B) infliximab","(C) romosozumab","(D) denosumab"],"answer":3,"image":""},{"id":"md2-114-1-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第1次第61題","year":114,"session":1,"number":61,"question":"下列藥物中，何者具有礦物性皮質固醇（mineralocorticoid）活性，可治療腎上腺皮質機能不全症所導致之鹽類流失？","options":["(A) fludrocortisone","(B) paramethasone","(C) hydrocortisone","(D) betamethasone"],"answer":0,"image":""},{"id":"md2-114-1-62","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"114年第1次第62題","year":114,"session":1,"number":62,"question":"下列關於neprilysin inhibitor的敘述，何者錯誤？","options":["(A) 可減少brain natriuretic peptide（BNP）之降解","(B) 可使血管擴張","(C) 減少交感神經活性","(D) 不適合與valsartan併用於治療心衰竭"],"answer":3,"image":""},{"id":"md2-114-1-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"114年第1次第63題","year":114,"session":1,"number":63,"question":"下列關於nitrates之敘述，何者錯誤？","options":["(A) 青光眼病人當腦內壓高時，不宜使用nitrates","(B) 連續使用長效型nitroglycerin時，兩劑間隔需至少8小時，以預防產生耐藥性","(C) 長時間使用nitroprusside易產生耐藥性","(D) 爆裂性化學工廠工人的“Monday disease”消失係因其對nitrates產生耐藥性"],"answer":2,"image":""},{"id":"md2-114-1-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"114年第1次第64題","year":114,"session":1,"number":64,"question":"下列何種藥物作用於dopamine D1 receptor，可使周邊血管平滑肌舒張，靜脈注射用於治療嚴重性高血壓？","options":["(A) candesartan","(B) fenoldopam","(C) clonidine","(D) minoxidil"],"answer":1,"image":""},{"id":"md2-114-1-65","subject":"md2","topic":"藥理-總論與自主神經","meta":"114年第1次第65題","year":114,"session":1,"number":65,"question":"下列關於pralidoxime的敘述，何者最不適當？","options":["(A) 可幫助被磷酸化的acetylcholinesterase恢復活性","(B) 不可作為carbamate類cholinesterase抑制劑的解毒劑","(C) 與diacetylmonoxime相比，其中樞神經系統的穿透力較強","(D) 過量時可能導致肌肉無力"],"answer":2,"image":""},{"id":"md2-114-1-66","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"114年第1次第66題","year":114,"session":1,"number":66,"question":"陳先生清晨上廁所時昏倒，家人量血壓時發現收縮壓只有76 mmHg，而被送來醫院。就診時病人已清醒，血壓為100/70 mmHg，心跳規則，每分鐘70下，無其它不適。醫師評估後，認為是藥物引起的暫時性低血壓。下列陳先生平常服用的藥物中，何者與他的血壓下降關聯最低？","options":["(A) tamsulosin","(B) verapamil","(C) carvedilol","(D) pseudoephedrine"],"answer":3,"image":""},{"id":"md2-114-1-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第1次第67題","year":114,"session":1,"number":67,"question":"在H2 antagonists中，何者的first-pass hepatic metabolism最小？","options":["(A) cimetidine","(B) nizatidine","(C) ranitidine","(D) famotidine"],"answer":1,"image":""},{"id":"md2-114-1-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第1次第68題","year":114,"session":1,"number":68,"question":"下列何種抗體藥物之標的為IL-5，用於治療嚴重型嗜酸性（eosinophilic）氣喘？","options":["(A) reslizumab","(B) omalizumab","(C) dupilumab","(D) alemtuzumab"],"answer":0,"image":""},{"id":"md2-114-1-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第1次第69題","year":114,"session":1,"number":69,"question":"下列藥物中，何者最不適用於便秘的治療？","options":["(A) 氧化鎂（MgO）","(B) lactulose糖漿","(C) prucalopride","(D) palonosetron"],"answer":3,"image":""},{"id":"md2-114-1-70","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"114年第1次第70題","year":114,"session":1,"number":70,"question":"關於預防或治療偏頭痛的藥物，下列敘述何者正確？","options":["(A) aspirin及ibuprofen對於偏頭痛無明顯鎮痛作用","(B) lasmiditan可作為偏頭痛急性發作的用藥，且較sumatriptan無血管收縮之副作用","(C) 結合calcitonin gene-related peptide（CGRP）或其受體的抗體可用於治療偏頭痛","(D) 可口服的小分子calcitonin gene-related peptide（CGRP）受體拮抗劑ubrogepant可預防偏頭痛"],"answer":1,"image":""},{"id":"md2-114-1-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第1次第71題","year":114,"session":1,"number":71,"question":"下列何者為前列腺素製劑，可與mifepristone合併使用，作為早期懷孕人工流產之藥物？","options":["(A) latanoprost","(B) treprostinil","(C) misoprostol","(D) alprostadil"],"answer":2,"image":""},{"id":"md2-114-1-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"114年第1次第72題","year":114,"session":1,"number":72,"question":"下列有關全身麻醉劑的敘述，何者錯誤？","options":["(A) isoflurane及nitrous oxide為吸入型麻醉藥","(B) propofol及midazolam為靜脈注射型麻醉藥","(C) etomidate具有安眠效果，但無止痛作用","(D) propofol藥效短的主要原因是其肝臟代謝快"],"answer":3,"image":""},{"id":"md2-114-1-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"114年第1次第73題","year":114,"session":1,"number":73,"question":"下列何者不是治療Huntington舞蹈症的主要藥物？","options":["(A) tetrabenazine","(B) haloperidol","(C) fluphenazine","(D) ropinirole"],"answer":3,"image":""},{"id":"md2-114-1-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"114年第1次第74題","year":114,"session":1,"number":74,"question":"下列那一個治療癲癇發作的藥物，其作用機制為抑制鈉離子通道，亦可改善癲癇病人的憂鬱症？","options":["(A) lamotrigine","(B) tiagabine","(C) clonazepam","(D) ethosuximide"],"answer":0,"image":""},{"id":"md2-114-1-75","subject":"md2","topic":"藥理-化學治療","meta":"114年第1次第75題","year":114,"session":1,"number":75,"question":"下列金屬離子螯合劑中，何者最不適合用於治療慢性重金屬中毒？","options":["(A) unithiol","(B) deferasirox","(C) succimer","(D) dimercaprol"],"answer":3,"image":""},{"id":"md2-114-1-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"114年第1次第76題","year":114,"session":1,"number":76,"question":"下列何者是由脂質和磷脂的聚合物與蛋白質複合而成，標誌著細胞所經歷之自由基損傷和脂質過氧化？","options":["(A) chloasma","(B) lipofuscin","(C) hemosiderin","(D) ochronosis"],"answer":1,"image":""},{"id":"md2-114-1-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"114年第1次第77題","year":114,"session":1,"number":77,"question":"下列何者最可能為可逆性細胞核的變化？","options":["(A) 核溶解（karyolysis）","(B) 細胞核碎裂（karyorrhexis）","(C) 核濃縮（pyknosis）","(D) 核質凝聚（chromatin clumping）"],"answer":3,"image":""},{"id":"md2-114-1-78","subject":"md2","topic":"寄生蟲學","meta":"114年第1次第78題","year":114,"session":1,"number":78,"question":"下列何者不是蚊子作為媒介的傳染病？","options":["(A) 茲卡病毒（Zika virus）感染","(B) 瘧疾（malaria）","(C) 淋巴絲蟲病（lymphatic filariasis）","(D) 卡格氏症（Chagas disease）"],"answer":3,"image":""},{"id":"md2-114-1-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"114年第1次第79題","year":114,"session":1,"number":79,"question":"有關漢生病（Hansen disease, leprosy）的特徵描述，下列何者錯誤？","options":["(A) 顯微鏡下，病灶常沿著神經分布","(B) tuberculoid leprosy比起lepromatous leprosy有較強的Th1反應（Th1 response）","(C) tuberculoid leprosy的病理特色是含有脂肪的巨噬細胞吞噬許多細菌","(D) 溫度較低的皮膚適合Mycobacterium leprae增生"],"answer":2,"image":""},{"id":"md2-114-1-80","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"114年第1次第80題","year":114,"session":1,"number":80,"question":"下列何者不是p53的主要功能之一？","options":["(A) 促進細胞衰老（senescence）","(B) 結合並抑制MDM2","(C) 使細胞週期（cell cycle）停滯於G1 phase（G1 arrest）","(D) 引發細胞凋亡（apoptosis）的內在路徑（intrinsic pathway）"],"answer":1,"image":""},{"id":"md2-114-1-81","subject":"md2","topic":"免疫學","meta":"114年第1次第81題","year":114,"session":1,"number":81,"question":"下列何種分子的過度表現最不可能使腫瘤細胞逃避免疫攻擊（immune evasion）？","options":["(A) TGF-β","(B) CTLA-4","(C) PD-L1","(D) MHC molecules"],"answer":3,"image":""},{"id":"md2-114-1-82","subject":"md2","topic":"病理-免疫感染遺傳","meta":"114年第1次第82題","year":114,"session":1,"number":82,"question":"40歲男性，發燒就診，影像檢查發現雙側肺部開洞性結節，鼻竇黏膜發炎潰瘍，合併腎功能異常。各種病原菌檢驗結果都為陰性，腎臟切片發現新月型腎絲球腎炎（crescentic glomerulonephritis），有關最有可能的診斷，下列何者錯誤？","options":["(A) 通常抽血可發現抗嗜中性球細胞質抗體（PR3-ANCA）上升","(B) 呼吸道切片典型可見肉芽腫性發炎（granulomatous inflammation）及組織壞死","(C) 通常會對免疫抑制的治療有良好反應","(D) 若不治療，大多數病人也會自行康復"],"answer":3,"image":""},{"id":"md2-114-1-83","subject":"md2","topic":"病理-心血管血液","meta":"114年第1次第83題","year":114,"session":1,"number":83,"question":"有關動脈粥狀硬化的病灶特性，下列何者錯誤？","options":["(A) 病灶通常是以同心圓方式造成整圈血管壁增厚","(B) 血液亂流處較易形成動脈粥狀硬化的斑塊","(C) 動脈粥狀硬化產生的斑塊可能會破裂，導致血栓形成並阻塞血管腔","(D) 動脈粥狀硬化的風險因子包括低密度脂蛋白受器（LDL receptor）基因突變"],"answer":0,"image":""},{"id":"md2-114-1-84","subject":"md2","topic":"病理-心血管血液","meta":"114年第1次第84題","year":114,"session":1,"number":84,"question":"下列何種腫瘤最容易進展成急性骨髓性白血病（acute myeloid leukemia）？","options":["(A) 真性紅血球增多症（polycythemia vera）","(B) 原發性血小板增多症（essential thrombocythemia）","(C) 骨髓化生不良症候群（myelodysplastic syndrome）","(D) 慢性淋巴球性白血病（chronic lymphocytic leukemia）"],"answer":2,"image":""},{"id":"md2-114-1-85","subject":"md2","topic":"病理-心血管血液","meta":"114年第1次第85題","year":114,"session":1,"number":85,"question":"有關急性淋巴母細胞性白血病（acute lymphoblastic leukemia）的敘述，下列何者最適當？","options":["(A) 臨床表現與急性骨髓性白血病（acute myeloid leukemia）相似","(B) 病人多數為40歲以上的成年人","(C) 大多數腫瘤會有MYC基因的轉位，造成MYC的過度表現","(D) 腫瘤細胞不會有BCR-ABL融合基因"],"answer":0,"image":""},{"id":"md2-114-1-86","subject":"md2","topic":"病理-呼吸消化","meta":"114年第1次第86題","year":114,"session":1,"number":86,"question":"下列有關肺炎的敘述，何者錯誤？","options":["(A) 結核菌及黴菌為慢性肺炎（chronic pneumonia）常見的致病原","(B) 肺膿瘍（lung abscess）是慢性肺炎的一種，病理上可見到壞死性肉芽腫性發炎（necrotizing granulomatous inflammation）","(C) 病毒性肺炎病理變化為間質淋巴球浸潤（interstitial lymphocytic infiltration）","(D) 病毒性肺炎嚴重可造成急性呼吸窘迫症候群（acute respiratory distress syndrome）"],"answer":1,"image":""},{"id":"md2-114-1-87","subject":"md2","topic":"病理-呼吸消化","meta":"114年第1次第87題","year":114,"session":1,"number":87,"question":"下列有關特發性肺纖維化（idiopathic pulmonary fibrosis, IPF）的敘述，何者錯誤？","options":["(A) 臨床表現為慢性漸進性纖維化的間質性肺炎，疾病常進展至呼吸衰竭","(B) 好發族群為中老年人，年輕人較罕見","(C) 肺纖維化常以下肺葉較為嚴重","(D) 胸部電腦斷層呈現中央小葉型結節（centrilobular nodules）"],"answer":3,"image":""},{"id":"md2-114-1-88","subject":"md2","topic":"細菌學","meta":"114年第1次第88題","year":114,"session":1,"number":88,"question":"下列何者為社區型細菌性肺炎最常見之病原？","options":["(A) 肺炎鏈球菌（Streptococcus pneumoniae）","(B) 嗜血流感桿菌（Haemophilus influenzae）","(C) 金黃色葡萄球菌（Staphylococcus aureus）","(D) 肺炎克雷伯氏菌（Klebsiella pneumoniae）"],"answer":0,"image":""},{"id":"md2-114-1-89","subject":"md2","topic":"病毒學","meta":"114年第1次第89題","year":114,"session":1,"number":89,"question":"關於B型肝炎病毒（Hepatitis B virus），下列敘述何者最不適當？","options":["(A) HBeAg是病毒包膜醣蛋白（envelope glycoproteins）","(B) HBcAg是病毒核衣殼蛋白（nucleocapsid protein）","(C) HBx有轉錄反式活化因子（transcriptional transactivator）功能","(D) HBV polymerase（Pol）具有反轉錄酶活性（reverse transcriptase activity）"],"answer":0,"image":""},{"id":"md2-114-1-90","subject":"md2","topic":"病理-呼吸消化","meta":"114年第1次第90題","year":114,"session":1,"number":90,"question":"對於自體免疫性萎縮性胃炎（autoimmune atrophic gastritis）的相關敘述，下列敘述何者最不適當？","options":["(A) 與其他自體免疫疾病相關，例如：甲狀腺炎、糖尿病、Graves氏病（Graves disease）","(B) 與惡性貧血（pernicious anemia）有關","(C) 迴腸（ileum）維生素B12吸收缺陷","(D) 常見到內分泌細胞萎縮減少（atrophy and decrease of endocrine cells）"],"answer":3,"image":""},{"id":"md2-114-1-91","subject":"md2","topic":"病理-呼吸消化","meta":"114年第1次第91題","year":114,"session":1,"number":91,"question":"關於慢性胰臟炎（chronic pancreatitis），下列敘述何者最不適當？","options":["(A) 慢性胰臟炎最常見的原因是長期飲酒","(B) 纖維化細胞激素（fibrogenic cytokines）在慢性胰臟炎中扮演重要角色","(C) 轉化生長因子-β（TGF-β）和血小板衍生生長因子（PDGF）誘導胰臟星狀細胞（pancreatic stellate cells）的活化","(D) 病理下典型特徵為蘭氏小島（islets of Langerhans）因發炎破壞消失，而胰腺泡（pancreatic acini）相對保存良好"],"answer":3,"image":""},{"id":"md2-114-1-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第1次第92題","year":114,"session":1,"number":92,"question":"最常造成息肉性膀胱炎（polypoid cystitis）的原因為下列何者？","options":["(A) 長期放置尿管","(B) 長期吸食K他命（ketamine）","(C) 細菌感染，以大腸桿菌最為常見","(D) 人類乳突病毒（human papillomavirus）感染"],"answer":0,"image":""},{"id":"md2-114-1-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第1次第93題","year":114,"session":1,"number":93,"question":"腎透明細胞癌（renal clear cell carcinoma）最常轉移至下列何處？","options":["(A) 周邊淋巴結","(B) 腎上腺","(C) 肝臟","(D) 肺臟"],"answer":3,"image":""},{"id":"md2-114-1-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第1次第94題","year":114,"session":1,"number":94,"question":"經由電子顯微鏡檢查，下列腎絲球疾病所產生免疫沉澱物主要沉著的位置，下列何者錯誤？","options":["(A) IgA nephropathy沉著於膈細胞（mesangial cell）周圍","(B) membranous nephropathy沉著在上皮細胞下方（subepithelial deposits）","(C) dense deposit disease沉著在基底膜之內（intramembranous deposits）","(D) acute postinfectious glomerulonephritis沉著在內皮細胞下方（subendothelial deposits），形成駝峰狀隆起（humps）"],"answer":3,"image":""},{"id":"md2-114-1-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第1次第95題","year":114,"session":1,"number":95,"question":"區分子宮平滑肌瘤（leiomyoma）與平滑肌肉瘤（leiomyosarcoma），下列何者最不具有鑑別能力？","options":["(A) MED12突變","(B) 有絲分裂數量","(C) 腫瘤壞死","(D) 非典型細胞核（nuclear atypia）"],"answer":0,"image":""},{"id":"md2-114-1-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第1次第96題","year":114,"session":1,"number":96,"question":"Gleason grade是用來評估下列何種癌症的治療選擇與評估預後（prognosis）？","options":["(A) 腎細胞癌（renal cell carcinoma）","(B) 膀胱腺癌（adenocarcinoma of urinary bladder）","(C) 前列腺癌（prostatic adenocarcinoma）","(D) 陰莖鱗狀上皮癌（penile squamous cell carcinoma）"],"answer":2,"image":""},{"id":"md2-114-1-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第1次第97題","year":114,"session":1,"number":97,"question":"完全性葡萄胎（complete hydatidiform mole）最常見的染色體核型為：","options":["(A) 46,XX","(B) 69,XXY","(C) 69,XXX","(D) 92,XXXY"],"answer":0,"image":""},{"id":"md2-114-1-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"114年第1次第98題","year":114,"session":1,"number":98,"question":"下列關於眼睛疾病的敘述，何者最不適當？","options":["(A) Fuchs dystrophy主要是因為角膜endothelium缺損所致","(B) pinguecula和pterygium都與日光造成的結膜受損有關","(C) herpes stromal keratitis主要是因免疫作用造成角膜受損","(D) keratoconus主要的病理特徵是Descemet membrane斷裂"],"answer":3,"image":""},{"id":"md2-114-1-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"114年第1次第99題","year":114,"session":1,"number":99,"question":"下列何種病理變化，較少見於類風濕性關節炎（rheumatoid arthritis）？","options":["(A) 骨贅（osteophyte）","(B) 血管翳（pannus）","(C) 骨性關節強直（bony ankylosis）","(D) 關節滑液膜細胞絨毛狀增生（synovial villous hyperplasia）"],"answer":0,"image":""},{"id":"md2-114-1-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"114年第1次第100題","year":114,"session":1,"number":100,"question":"以直接免疫螢光法（direct immunofluorescence）檢查天皰瘡（pemphigus vulgaris）所引起的水泡，可以發現IgG免疫球蛋白主要沉積於什麼位置？","options":["(A) 表皮層鱗狀上皮細胞之間（intercellular regions of epidermal cells）","(B) 表皮層下之基底膜（basement membrane）","(C) 血管壁（vascular walls）","(D) 汗腺管（eccrine ducts）之基底膜"],"answer":0,"image":""},{"id":"md2-114-2-1","subject":"md2","topic":"細菌學","meta":"114年第2次第1題","year":114,"session":2,"number":1,"question":"下列那一種細菌是兼性厭氧菌（facultative anaerobes）？","options":["(A) 大腸桿菌（Escherichia coli）","(B) 結核桿菌（Mycobacteria tuberculosis）","(C) 破傷風桿菌（Clostridium tetani）","(D) 肉毒桿菌（Clostridium botulinum）"],"answer":0,"image":""},{"id":"md2-114-2-2","subject":"md2","topic":"細菌學","meta":"114年第2次第2題","year":114,"session":2,"number":2,"question":"大腸桿菌O157:H7常引起出血性腹瀉，H7的H指的是細菌的那一部分？","options":["(A) 鞭毛（flagella）","(B) 脂多醣（lipopolysaccharide）","(C) 核心多醣（core polysaccharide）","(D) 莢膜（capsule）"],"answer":0,"image":""},{"id":"md2-114-2-3","subject":"md2","topic":"細菌學","meta":"114年第2次第3題","year":114,"session":2,"number":3,"question":"關於鈎端螺旋體病（leptospirosis）之敘述，下列何者最不適當？","options":["(A) 病原體是Leptospira interrogans，為絕對嗜氧菌（obligate aerobe），容易培養","(B) 雖具有主動穿透黏膜的能力，但不會透過性行為傳染","(C) 通常以doxycycline治療或預防","(D) 嚙齒類動物是主要的保菌宿主（reservoir），其帶菌的尿液會污染土壤"],"answer":0,"image":""},{"id":"md2-114-2-4","subject":"md2","topic":"藥理-化學治療","meta":"114年第2次第4題","year":114,"session":2,"number":4,"question":"廣泛性抗藥結核桿菌（extensively drug-resistant Mycobacteria tuberculosis, XDR TB）的定義，是指多重抗藥結核桿菌（MDR TB）不只對氟喹諾酮（fluoroquinolones）具抗性，且對下列何種第二線抗生素也具抗性？","options":["(A) 胺基糖苷（aminoglycoside）","(B) 四環黴素（tetracycline）","(C) beta-內酰胺（beta-lactam）","(D) 紅黴素（erythromycin）"],"answer":0,"image":""},{"id":"md2-114-2-5","subject":"md2","topic":"細菌學","meta":"114年第2次第5題","year":114,"session":2,"number":5,"question":"下列何種產氣莢膜梭狀芽孢桿菌（Clostridium perfringens）的毒素，主要會造成氣狀壞疽（gas gangrene）？","options":["(A) alpha毒素","(B) beta毒素","(C) epsilon毒素","(D) iota毒素"],"answer":0,"image":""},{"id":"md2-114-2-6","subject":"md2","topic":"免疫學","meta":"114年第2次第6題","year":114,"session":2,"number":6,"question":"溶菌酶（lysozyme）為人類淚液或唾液中常見之蛋白質，具有抵禦細菌感染的功能，其預防細菌感染最主要之機制為：","options":["(A) 破壞細菌細胞膜完整性","(B) 抑制細菌電子傳遞鏈運作","(C) 分解胜肽聚醣（peptidoglycan）造成細菌細胞壁損壞","(D) 切割線毛（pili）使細菌無法黏附於宿主組織或細胞"],"answer":2,"image":""},{"id":"md2-114-2-7","subject":"md2","topic":"細菌學","meta":"114年第2次第7題","year":114,"session":2,"number":7,"question":"下列細菌與氧分子（O2）相關之敘述，何者最不適當？","options":["(A) 兼性厭氧菌（facultative anaerobic bacteria）雖可在無氧條件下存活，但無法在有氧環境下生長","(B) 在一般的大氣環境下，微需氧菌（microaerophilic bacteria）無法正常的生長","(C) 氧分子代謝過程中產生的過氧化氫（hydrogen peroxide），為對細菌有害的代謝產物","(D) 絕對厭氧菌（obligate anaerobic bacteria）產生的孢子，可在有氧的環境下留存，並在合適的環境轉變為具有生長活性之細菌"],"answer":0,"image":""},{"id":"md2-114-2-8","subject":"md2","topic":"細菌學","meta":"114年第2次第8題","year":114,"session":2,"number":8,"question":"下列何種疾病最不可能經由蜱（tick）媒介傳染？","options":["(A) 洛磯山斑疹熱（Rocky Mountain spotted fever）","(B) 地方性回歸熱（Endemic relapsing fever）","(C) 斑疹傷寒（Scrub typhus）","(D) 萊姆病（Lyme disease）"],"answer":2,"image":""},{"id":"md2-114-2-9","subject":"md2","topic":"細菌學","meta":"114年第2次第9題","year":114,"session":2,"number":9,"question":"下列那種感染症與無乳鏈球菌（Streptococcus agalactiae）最無關連？","options":["(A) 新生兒腦膜炎（neonatal meningitis）","(B) 新生兒肺炎（neonatal pneumonia）","(C) 懷孕婦女的泌尿道感染（urinary tract infection）","(D) 新生兒筋膜炎（neonatal fasciitis）"],"answer":3,"image":""},{"id":"md2-114-2-10","subject":"md2","topic":"病毒學","meta":"114年第2次第10題","year":114,"session":2,"number":10,"question":"下列有關病毒複製之敘述，何者最不適當？","options":["(A) 病毒的基因體複製是在病毒結構蛋白合成之後才開始進行","(B) 所有病毒複製過程中均需合成RNA","(C) B型肝炎病毒之外套膜來自寄主細胞之細胞膜","(D) 在隱蝕期（eclipse period）時可測到極少量之感染性病毒"],"answer":0,"image":""},{"id":"md2-114-2-11","subject":"md2","topic":"病毒學","meta":"114年第2次第11題","year":114,"session":2,"number":11,"question":"下列有關致癌性病毒（oncogenic virus）的敘述，何者最適當？","options":["(A) 多瘤病毒（polyomavirus, SV40）之T抗原可與寄主細胞中之腫瘤抑制蛋白結合","(B) 多瘤病毒（polyomavirus, SV40）可在人類形成腫瘤","(C) 乳突瘤病毒（papillomavirus）之E7蛋白可與寄主細胞中之p53蛋白結合","(D) 腺病毒（adenovirus）之E1B可與寄主細胞中之p105RB蛋白結合"],"answer":0,"image":""},{"id":"md2-114-2-12","subject":"md2","topic":"病毒學","meta":"114年第2次第12題","year":114,"session":2,"number":12,"question":"下列那一個肝炎病毒尚未有疫苗可預防其感染，但已經可以經由抗病毒藥物治療病患使其痊癒？","options":["(A) HAV","(B) HBV","(C) HCV","(D) HDV"],"answer":2,"image":""},{"id":"md2-114-2-13","subject":"md2","topic":"病毒學","meta":"114年第2次第13題","year":114,"session":2,"number":13,"question":"有關流行性感冒病毒蛋白neuraminidase（NA）的敘述，下列何者最不適當？","options":["(A) 為一種酵素，能幫助病毒離開宿主細胞","(B) A型流感病毒具有多種NA亞型","(C) 為抗病毒藥物金剛烷胺類（amantadine）主要抑制對象","(D) 在病毒外套膜上形成四倍體（tetramer）"],"answer":2,"image":""},{"id":"md2-114-2-14","subject":"md2","topic":"病毒學","meta":"114年第2次第14題","year":114,"session":2,"number":14,"question":"有關輪狀病毒（rotaviruses）的特色，下列敘述何者最不適當？","options":["(A) 是一個雙股RNA（double-stranded RNA）病毒","(B) 被蛋白酶降解後形成的intermediate subviral particle（ISVP）不具感染力","(C) 基因體（genome）由多段的RNA組成","(D) 對腸胃道環境的耐受性很高"],"answer":1,"image":""},{"id":"md2-114-2-15","subject":"md2","topic":"病毒學","meta":"114年第2次第15題","year":114,"session":2,"number":15,"question":"關於麻疹（Measles）的敘述，下列何者最適當？","options":["(A) 其致病原麻疹病毒屬黏液病毒（Myxovirus）","(B) 麻疹病毒之基因體為八段單股的RNA","(C) 麻疹病毒具有多種血清型","(D) 病毒感染時，體內T細胞會攻擊被病毒感染的上皮細胞，造成病人身上的大塊紅斑（maculopapular measles rash）"],"answer":3,"image":""},{"id":"md2-114-2-16","subject":"md2","topic":"病毒學","meta":"114年第2次第16題","year":114,"session":2,"number":16,"question":"在2015～2016年間爆發茲卡（Zika）病毒大流行，下列有關該病毒的敘述何者最不適當？","options":["(A) 猴子是茲卡病毒的宿主之一","(B) 不需要蚊子的媒介，病毒可以直接人傳人","(C) 該病毒的遺傳基因為負股(-)RNA","(D) 懷孕婦女被茲卡病毒感染會造成胎兒小腦症（microcephaly）"],"answer":2,"image":""},{"id":"md2-114-2-17","subject":"md2","topic":"真菌學","meta":"114年第2次第17題","year":114,"session":2,"number":17,"question":"下列何種馬拉色菌（Malassezia）可以在不含脂質的培養基上生長？","options":["(A) Malassezia pachydermatis","(B) Malassezia furfur","(C) Malassezia globosa","(D) Malassezia japonica"],"answer":0,"image":""},{"id":"md2-114-2-18","subject":"md2","topic":"免疫學","meta":"114年第2次第18題","year":114,"session":2,"number":18,"question":"若不小心吃到了一份被沙門氏菌（Salmonella enterica）污染的沙拉，出現了腹瀉的反應，下列何者最有可能是首先辨識並對該病原體產生反應的身體部位？","options":["(A) 脾臟","(B) 胸腺","(C) 腸黏膜相關淋巴組織","(D) 肝臟"],"answer":2,"image":""},{"id":"md2-114-2-19","subject":"md2","topic":"免疫學","meta":"114年第2次第19題","year":114,"session":2,"number":19,"question":"在抗體與抗原的交互作用中，下列那個作用力參與最少？","options":["(A) 范德瓦爾斯力（van der Waals force）","(B) 氫鍵（hydrogen bond）","(C) 偶極－偶極力（dipole-dipole force）","(D) 共價鍵（covalent bond）"],"answer":3,"image":""},{"id":"md2-114-2-20","subject":"md2","topic":"免疫學","meta":"114年第2次第20題","year":114,"session":2,"number":20,"question":"主要組織相容性複合體（major histocompatibility complex, MHC）為T細胞辨識抗原過程中重要的分子，關於MHC的敘述，下列何者最不適當？","options":["(A) MHC class I呈獻的抗原胜肽較短，而MHC class II呈獻的抗原胜肽較長","(B) MHC class I呈獻抗原給CD8 T細胞，而MHC class II呈獻抗原給CD4 T細胞","(C) 組成MHC class II的分子有兩個，分別是α chain與β chain，其中β chain的變化性（variability）遠高於α chain","(D) MHC class I與class II都有分子不會接觸到抗原，class I中是β2-microglobulin，而class II中是α chain"],"answer":3,"image":""},{"id":"md2-114-2-21","subject":"md2","topic":"免疫學","meta":"114年第2次第21題","year":114,"session":2,"number":21,"question":"下列有關pre-B細胞受體（pre-B cell receptor）的敘述，何者最不適當？","options":["(A) 具有免疫球蛋白輕鏈之κ鏈（κ chain）","(B) 可以傳遞存活訊號使pre-B細胞繼續發育","(C) 具有Igα和Igβ兩個訊號傳遞蛋白","(D) 可以傳遞訊號抑制免疫球蛋白重鏈（heavy chain）基因進行重組（rearrangement）"],"answer":0,"image":""},{"id":"md2-114-2-22","subject":"md2","topic":"免疫學","meta":"114年第2次第22題","year":114,"session":2,"number":22,"question":"下列何者最不可能高度表現於調節性T細胞（Treg）？","options":["(A) CD25","(B) IL-10","(C) CTLA-4","(D) B7"],"answer":3,"image":""},{"id":"md2-114-2-23","subject":"md2","topic":"免疫學","meta":"114年第2次第23題","year":114,"session":2,"number":23,"question":"在沒有病原菌感染的情況下，人體腸胃道組織中的樹突細胞（dendritic cell）最常見的特徵是：","options":["(A) 會分泌大量細胞激素IL-12","(B) 細胞表面有高量B7-1分子，是高效能的抗原呈獻細胞","(C) 腸道中的TGF-β與IL-10會增進樹突細胞對共生菌的耐受性","(D) 可製造A酸（retinoic acid）並增進T毒殺細胞功能"],"answer":2,"image":""},{"id":"md2-114-2-24","subject":"md2","topic":"免疫學","meta":"114年第2次第24題","year":114,"session":2,"number":24,"question":"革蘭氏陽性細菌細胞壁的peptidoglycan最主要是經由下列何種受體被辨識？","options":["(A) Toll-like receptor 2","(B) Toll-like receptor 4","(C) Toll-like receptor 8","(D) Toll-like receptor 9"],"answer":0,"image":""},{"id":"md2-114-2-25","subject":"md2","topic":"免疫學","meta":"114年第2次第25題","year":114,"session":2,"number":25,"question":"自體免疫疾病一但建立之後，通常會逐漸演化成長期且持續的疾病，在治療上面也缺乏具有特異性且有效的治療方式。下列有關自體免疫疾病難以治癒的原因，何者最不適當？","options":["(A) 自體免疫疾病的病程中，免疫系統不斷接受抗原的刺激，形成一個正回饋的發炎反應","(B) 治療上無法移除自身抗原","(C) 表位擴散（epitope spreading）的特性造成更多辨識自身抗原的免疫細胞活化","(D) 自體免疫疾病的病人都有調節型T細胞（regulatory T cell）的異常"],"answer":3,"image":""},{"id":"md2-114-2-26","subject":"md2","topic":"免疫學","meta":"114年第2次第26題","year":114,"session":2,"number":26,"question":"有關腫瘤免疫反應的敘述，下列何者最適當？","options":["(A) 有腫瘤特異性抗原的呈獻，可產生並存在著腫瘤專一性T淋巴球","(B) 免疫細胞無法進入腫瘤組織內，因而無法抑制腫瘤細胞的生長","(C) 腫瘤細胞不斷生長增加時，亦產生性質變異，表現突變的細胞表面分子，進而造成免疫細胞的死亡","(D) 因腫瘤細胞性質的變異，表現出腫瘤抑制基因（tumor suppressor gene）的產物，引起了腫瘤抑制自然殺手細胞的效果"],"answer":0,"image":""},{"id":"md2-114-2-27","subject":"md2","topic":"免疫學","meta":"114年第2次第27題","year":114,"session":2,"number":27,"question":"下列何種移植最容易發生graft-versus-host disease（GVHD）？","options":["(A) 肝臟","(B) 骨髓","(C) 腎臟","(D) 肺臟"],"answer":1,"image":""},{"id":"md2-114-2-28","subject":"md2","topic":"免疫學","meta":"114年第2次第28題","year":114,"session":2,"number":28,"question":"腫瘤如黑色素瘤（melanoma）會產生骨髓衍生性抑制細胞（MDSCs），最主要透過分泌下列何種細胞激素以利腫瘤細胞生長？","options":["(A) IL-1","(B) IL-10","(C) TNF-α","(D) IFN-γ"],"answer":1,"image":""},{"id":"md2-114-2-29","subject":"md2","topic":"寄生蟲學","meta":"114年第2次第29題","year":114,"session":2,"number":29,"question":"下列那些寄生蟲具有口部、咽管、食道、腸道與肛門之完整消化系統？①縮小包膜絛蟲（Hymenolepis diminuta） ②蛔蟲（Ascaris lumbricoides） ③美洲鉤蟲（Necator americanus） ④糞小桿線蟲（Strongyloides stercoralis） ⑤亞洲絛蟲（Taenia asiatica）","options":["(A) ①②③","(B) ②③④","(C) ③④⑤","(D) ①③⑤"],"answer":1,"image":""},{"id":"md2-114-2-30","subject":"md2","topic":"寄生蟲學","meta":"114年第2次第30題","year":114,"session":2,"number":30,"question":"一位五歲的小朋友血液中嗜伊紅性白血球（eosinophil）異常增加，同時檢查出肝臟腫大，他最有可能感染下列何種寄生蟲？","options":["(A) 旋毛蟲（Trichinella spiralis）","(B) 蟯蟲（Enterobius vermicularis）","(C) 廣東住血線蟲（Angiostrongylus cantonensis）","(D) 犬蛔蟲（Toxocara canis）"],"answer":3,"image":""},{"id":"md2-114-2-31","subject":"md2","topic":"寄生蟲學","meta":"114年第2次第31題","year":114,"session":2,"number":31,"question":"下列有關人類包生囊蟲病（hydatid disease）之敘述，何者正確？①人類因食入受污染肉類而感染 ②肺泡包生囊症（alveolar echinococcosis）最具致病危險性 ③歐洲地區以豬為人類主要感染源 ④囊體破裂將在人體導致過敏性休克（anaphylactic shock）","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":3,"image":""},{"id":"md2-114-2-32","subject":"md2","topic":"寄生蟲學","meta":"114年第2次第32題","year":114,"session":2,"number":32,"question":"李同學於暑假期間赴香港旅遊，期間遍嚐各種魚類美食，返國後因腹部嚴重不適就醫，經醫師診斷疑似膽囊炎住院，隨後經糞便鏡檢而確認診斷，據此病史最可能感染下列何種寄生蟲？","options":["(A) 日本血吸蟲（Schistosoma japonicum）","(B) 衛氏肺吸蟲（Paragonimus westermani）","(C) 薑片蟲（Fasciolopsis buski）","(D) 中華肝吸蟲（Clonorchis sinensis）"],"answer":3,"image":""},{"id":"md2-114-2-33","subject":"md2","topic":"寄生蟲學","meta":"114年第2次第33題","year":114,"session":2,"number":33,"question":"臨床上，免疫妥協（immunocompromised）患者嚴重腹瀉的症狀，主要不是由下列何種寄生蟲引起？①微孢子蟲（Enterocytozoon bieneusi） ②肺孢子蟲（Pneumosystis carinii或Pneumosystis jirovecii） ③ 貝氏等孢子蟲（Isospora belli） ④弓蟲（Toxoplasma gondii）","options":["(A) ①②","(B) ③④","(C) ①③","(D) ②④"],"answer":3,"image":""},{"id":"md2-114-2-34","subject":"md2","topic":"寄生蟲學","meta":"114年第2次第34題","year":114,"session":2,"number":34,"question":"下列何種單細胞原蟲不是感染人類的血鞭毛蟲（hemoflagellate）？","options":["(A) 布氏羅德西亞錐蟲（Trypanosoma brucei rhodesiense）","(B) 枯西氏錐蟲（Trypanosoma cruzi）","(C) 唇形鞭毛蟲（Chilomastix mesnili）","(D) 熱帶利什曼原蟲（Leishmania tropica）"],"answer":2,"image":""},{"id":"md2-114-2-35","subject":"md2","topic":"寄生蟲學","meta":"114年第2次第35題","year":114,"session":2,"number":35,"question":"下列有關病媒（vector）及其媒介疾病之關係，何者錯誤？","options":["(A) 體蝨（body louse）；戰壕熱（trench fever）","(B) 軟蜱（soft tick）；日本斑疹熱（Japanese spotted fever）","(C) 采采蠅（tsetse fly）；非洲睡眠病（African sleeping sickness）","(D) 虻（Chrysops spp.）；羅阿絲蟲病（loaiasis）"],"answer":1,"image":""},{"id":"md2-114-2-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第2次第36題","year":114,"session":2,"number":36,"question":"配對（matching）是臨床流行病學方法學中常用的技巧，下列何項是使用配對時可能會出現的錯誤？","options":["(A) 在病例對照研究中，將病例和對照的年齡性別加以配對，能增加研究效率","(B) 採用密度配對（density matching）時，是指除了配對年齡性別等因子外，還會加入時間做配對","(C) 配對是使病例和對照的特性（如年齡性別）具有可比性的研究技巧，不適用於世代研究與病例交叉研究（case crossover design）","(D) 病例組和對照組的年齡被配對後，年齡對於疾病風險的主效果就會被降低"],"answer":2,"image":""},{"id":"md2-114-2-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第2次第37題","year":114,"session":2,"number":37,"question":"已知抽菸可導致肺活量降低，亦即香菸攝取量越高，則未來肺活量下降越多，兩者之間有因果關係。若某一研究者想要檢定抽菸與肺活量無關的虛無假說（H0：抽菸與肺活量獨立），隨機抽樣30人並完成一次試驗後，由於統計檢定未達顯著水準，P值（p-value）大於0.05，統計決策是不拒絕虛無假說，並總結抽菸與肺活量並無統計上顯著的相關性。則此試驗結果為下列那一項？","options":["(A) 型一錯誤（Type Ⅰ error）","(B) 型二錯誤（Type Ⅱ error）","(C) 真陰性（True Negative）","(D) 真陽性（True Positive）"],"answer":1,"image":""},{"id":"md2-114-2-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第2次第38題","year":114,"session":2,"number":38,"question":"某研究探討吸菸與腎臟癌症間的相關性，研究者從多家醫院蒐集腎臟癌症新發生個案，並進行性別、年齡（± 5歲）、種族以及居住所在鄰里等變項之匹配，選取無任何癌症病史的其他住院病人為對照組個案。該研究之研究數據如下表所示。下列有關吸菸與腎臟癌症相關性的相關分析數據中何者最恰當？","options":["(A) 曾經吸菸的人，腎臟癌的發生率為800/1513","(B) 腎臟癌症病人曾經吸菸的勝算（odds）為800/1157","(C) 腎臟癌症病人曾經吸菸的勝算大於沒有任何癌症病史住院病人的吸菸勝算，也就是（800/357）＞ （713/444）","(D) 吸菸與腎臟癌症發生的相對危險性估計值為（800/1513）/（357/801）"],"answer":2,"image":"md2-114-2-38.jpeg"},{"id":"md2-114-2-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第2次第39題","year":114,"session":2,"number":39,"question":"分析抽菸與口腔癌的關係，針對有酗酒者，抽菸的相對危險性（relative risk）為4；無酗酒者，抽菸的相對危險性為2，若將有或無酗酒者合併則抽菸的相對危險性為1。有關酗酒與抽菸及口腔癌關係的敘述，下列何者最恰當？","options":["(A) 是干擾因子而非修飾因子","(B) 是修飾因子而非干擾因子","(C) 既是干擾因子也是修飾因子","(D) 既非干擾因子也非修飾因子"],"answer":2,"image":""},{"id":"md2-114-2-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"114年第2次第40題","year":114,"session":2,"number":40,"question":"下列何者最可能為噪音所致之非聽覺健康影響？","options":["(A) 耳鳴","(B) 聽力損失","(C) 聽覺毛細胞喪失","(D) 心血管疾病"],"answer":3,"image":""},{"id":"md2-114-2-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"114年第2次第41題","year":114,"session":2,"number":41,"question":"光化學評估監測站主要是監測下列何種空氣污染物質及其前驅物之濃度？","options":["(A) 臭氧","(B) 二氧化硫","(C) 鉛","(D) 戴奧辛"],"answer":0,"image":""},{"id":"md2-114-2-42","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"114年第2次第42題","year":114,"session":2,"number":42,"question":"風險評估中，苯為已知人類致癌物質，有關其致癌風險的估計，下列敘述何者最恰當？","options":["(A) 應用具閾值模式，斜率因子單位為mg/kg-day","(B) 應用無閾值模式，斜率因子單位為mg/kg-day -1","(C) 應用具閾值模式，斜率因子單位為（mg/kg-day） -1","(D) 應用無閾值模式，斜率因子單位為（mg/kg-day）"],"answer":3,"image":""},{"id":"md2-114-2-43","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"114年第2次第43題","year":114,"session":2,"number":43,"question":"有關疫苗注射，下列敘述何者最不適當？","options":["(A) 有的疫苗一生只要接受一劑就夠了","(B) B型肝炎疫苗不但能預防B型肝炎，也能預防肝癌","(C) 各種疫苗都是全民接種最符合公眾利益","(D) 經過核准上市的疫苗（非緊急授權），一般來說，較少發生過敏"],"answer":2,"image":""},{"id":"md2-114-2-44","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"114年第2次第44題","year":114,"session":2,"number":44,"question":"家庭對個人發展的影響至深且遠，學者Duvall指出，家庭也有其生命週期，並將之劃分為八個階段，每個階段都有其發展任務，對身處在其中的家人的健康也會受到發展任務的影響。關於家庭生命週期階段會如何影響家人健康之敘述，下列何者最不恰當？","options":["(A) 在初為父母階段，新生兒報到是喜悅的事，這時候的家庭是壓力最小的時期","(B) 在子女學齡階段，需要建立與孩子的學校、同學家長以及社區的連結，家庭與工作需要取得平衡，以維護身心健康","(C) 子女青少年階段的家庭，孩子追求獨立，如何避免孩子涉及危害健康的行為（例如：抽菸），往往需要父母多付出心力","(D) 在老齡化的家庭，夫妻雙方因老化而出現病痛的情形增多，對於老化容易引致的疾病以及醫療資源需要有更多了解"],"answer":0,"image":""},{"id":"md2-114-2-45","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"114年第2次第45題","year":114,"session":2,"number":45,"question":"當今影響人們健康的因素中，下列何因素影響最大？","options":["(A) 人的生物特性","(B) 環境因素","(C) 健康照護體系良窳","(D) 生活型態因素"],"answer":3,"image":""},{"id":"md2-114-2-46","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"114年第2次第46題","year":114,"session":2,"number":46,"question":"近年來新興傳染病對全球健康造成影響，為了進行傳染病防治工作，由中央政府統籌、明訂各部會（內政部、衛生福利部、教育部、勞動部、文化部、經濟部等）共同合作、投入傳染病防治，此一作法最符合渥太華憲章健康促進行動綱領中的那一項？","options":["(A) 調整健康服務方向","(B) 強化社區行動","(C) 發展個人技能","(D) 建立健康的公共政策"],"answer":3,"image":""},{"id":"md2-114-2-47","subject":"md2","topic":"細菌學","meta":"114年第2次第47題","year":114,"session":2,"number":47,"question":"下列有關食品中毒的敘述，何者最不適當？","options":["(A) 必須至少有三人或三人以上攝取相同的食品而發生相似的症狀","(B) 沙門氏桿菌造成的食品中毒屬於細菌性病因","(C) 引起仙人掌桿菌食品中毒的來源食品可能為米飯等澱粉類製品","(D) 受糞便污染的食品或水源可能引起病原性大腸桿菌食品中毒"],"answer":0,"image":""},{"id":"md2-114-2-48","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"114年第2次第48題","year":114,"session":2,"number":48,"question":"下列何者是全國食安專線，提供整合跨部會的食安檢舉與諮詢的服務窗口？","options":["(A) 1919","(B) 1966","(C) 1922","(D) 1950"],"answer":0,"image":""},{"id":"md2-114-2-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"114年第2次第49題","year":114,"session":2,"number":49,"question":"有關菸害防制法的敘述，何者最不適當？","options":["(A) 滿十八歲之人，方可吸菸","(B) 孕婦或未滿三歲兒童在場之室內場所不得吸菸","(C) 菸品容器標示吸菸有害健康之警示圖不得低於百分之五十的面積","(D) 攜帶已點燃的菸品視同吸菸行為"],"answer":0,"image":""},{"id":"md2-114-2-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"114年第2次第50題","year":114,"session":2,"number":50,"question":"醫療服務有別於其他商品的特性之一為「外部性（externality）」，下列何者具有外部性？","options":["(A) 醫病雙方間的資訊不對稱","(B) 代理人問題","(C) 傳染病疫苗接種","(D) 疾病治療方式的不確定性"],"answer":2,"image":""},{"id":"md2-114-2-51","subject":"md2","topic":"藥理-總論與自主神經","meta":"114年第2次第51題","year":114,"session":2,"number":51,"question":"在藥物研發的臨床試驗過程中，那一階段主要是確定藥物的治療效能，及藥物的治療劑量範圍？","options":["(A) 第一階段（phase 1）","(B) 第二階段（phase 2）","(C) 第三階段（phase 3）","(D) 第四階段（phase 4）"],"answer":1,"image":""},{"id":"md2-114-2-52","subject":"md2","topic":"藥理-化學治療","meta":"114年第2次第52題","year":114,"session":2,"number":52,"question":"5-Fluorouracil為臨床常用的抗腫瘤藥物，下列何者為其抗癌作用機轉？","options":["(A) 與DNA進行烷基化結合（alkylating）","(B) 抑制topoisomerase II","(C) 抑制thymidylate synthase","(D) 抑制dihydrofolate reductase"],"answer":2,"image":""},{"id":"md2-114-2-53","subject":"md2","topic":"藥理-化學治療","meta":"114年第2次第53題","year":114,"session":2,"number":53,"question":"下列抗腫瘤藥物中，何者造成之腎毒性最強？","options":["(A) carboplatin","(B) dacarbazine","(C) temozolomide","(D) mechlorethamine"],"answer":0,"image":""},{"id":"md2-114-2-54","subject":"md2","topic":"真菌學","meta":"114年第2次第54題","year":114,"session":2,"number":54,"question":"下列藥物中，何者可抑制squalene epoxidase，其主要臨床用途為治療指甲癬（onychomycosis）？","options":["(A) nystatin","(B) terbinafine","(C) voriconazole","(D) itraconazole"],"answer":1,"image":""},{"id":"md2-114-2-55","subject":"md2","topic":"藥理-化學治療","meta":"114年第2次第55題","year":114,"session":2,"number":55,"question":"下列關於抗生素應用之敘述，何者錯誤？","options":["(A) cefepime可單獨用於對penicillin G產生抗藥性的鏈球菌（streptococci）感染","(B) ceftolozane-tazobactam可併用於抗藥性革蘭氏陰性菌株的感染","(C) ceftazidime可單獨用來治療能產生碳青黴烯酶（carbapenemase）的菌種感染","(D) ceftazidime-avibactam需合併metronidazole以用於治療複雜性腹腔內感染"],"answer":2,"image":""},{"id":"md2-114-2-56","subject":"md2","topic":"藥理-化學治療","meta":"114年第2次第56題","year":114,"session":2,"number":56,"question":"下列藥物中，何者為anti-CD19 chimeric antigen receptor (CAR) T cells產品，用於治療relapsed large B-cell lymphoma？","options":["(A) abatacept","(B) siponimod","(C) teriflunomide","(D) tisagenlecleucel"],"answer":3,"image":""},{"id":"md2-114-2-57","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"114年第2次第57題","year":114,"session":2,"number":57,"question":"下列何種藥物無法治療血小板缺乏症（thrombocytopenia）？","options":["(A) romiplostim","(B) oprelvekin","(C) eltrombopag","(D) plerixafor"],"answer":3,"image":""},{"id":"md2-114-2-58","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"114年第2次第58題","year":114,"session":2,"number":58,"question":"鐮刀型紅血球疾病（sickle cell disease）屬於溶血性貧血症，下列有關此疾病治療藥物hydroxyurea之敘述，何者錯誤？","options":["(A) 可抑制ribonucleotide reductase而產生抗癌作用","(B) 可減少紅血球內β-hemoglobin S的聚合反應","(C) 可減低靜脈內栓塞現象（veno-occlusive events）","(D) 可減少fetal hemoglobin γ生成，而緩解症狀"],"answer":3,"image":""},{"id":"md2-114-2-59","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第2次第59題","year":114,"session":2,"number":59,"question":"下列何者為降血糖藥物canagliflozin的主要作用機轉？","options":["(A) dipeptidyl peptidase 4（DPP-4）抑制劑","(B) glucagon-like peptide-1（GLP-1）受體致效劑","(C) sodium-glucose co-transporter 2（SGLT2）抑制劑","(D) α-glucosidase抑制劑"],"answer":2,"image":""},{"id":"md2-114-2-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第2次第60題","year":114,"session":2,"number":60,"question":"下列關於thioamides藥理機制之敘述，何者錯誤？","options":["(A) 抑制甲狀腺過氧化酶（thyroid peroxidase）和阻斷碘的有機化過程（iodine organification）","(B) propylthiouracil可抑制周邊T4的去碘作用，減少T3生成","(C) 抑制甲狀腺素釋放","(D) 降低碘酪胺酸（iodotyrosines）之偶合反應"],"answer":2,"image":""},{"id":"md2-114-2-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第2次第61題","year":114,"session":2,"number":61,"question":"下列關於維生素D與其相關活性產物的敘述，何者錯誤？","options":["(A) 可能產生高血鈣症之副作用","(B) 可用於改善骨質疏鬆症","(C) paricalcitol可治療慢性腎臟疾病引起的副甲狀腺機能亢進","(D) 可使血液中的磷濃度下降"],"answer":3,"image":""},{"id":"md2-114-2-62","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"114年第2次第62題","year":114,"session":2,"number":62,"question":"下列關於thiazide類利尿劑的敘述，何者錯誤？","options":["(A) 可用於改善骨質疏鬆症（osteoporosis）","(B) 可用於治療高鈣尿症（hypercalciuria）","(C) 可用於治療高尿酸血症（hyperuricemia）","(D) 可用於治療腎因性尿崩症（nephrogenic diabetes insipidus）"],"answer":2,"image":""},{"id":"md2-114-2-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"114年第2次第63題","year":114,"session":2,"number":63,"question":"Sotalol可用於治療心律不整，其最主要的作用機制為何？","options":["(A) 抑制氯離子通道","(B) 抑制鈉離子通道","(C) 抑制鉀離子通道","(D) 抑制鈣離子通道"],"answer":2,"image":""},{"id":"md2-114-2-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"114年第2次第64題","year":114,"session":2,"number":64,"question":"下列藥物產生療效之主要作用機制，何者正確？","options":["(A) ranolazine：抑制鈣離子通道以舒張動脈","(B) nitroprusside：抑制phosphodiesterase以增加cGMP","(C) nitroglycerin：舒張靜脈以減少心臟前負荷（preload）","(D) nicardipine：增加鉀離子傳導以降低周邊血管阻力"],"answer":2,"image":""},{"id":"md2-114-2-65","subject":"md2","topic":"藥理-總論與自主神經","meta":"114年第2次第65題","year":114,"session":2,"number":65,"question":"Neostigmine最不適合用於下列何種疾病的治療？","options":["(A) 重症肌無力（myasthenia gravis）","(B) 術後癱瘓性腸阻塞（paralytic ileus）","(C) 心搏過緩（bradycardia）","(D) 術後之尿液滯留（urinary retention）"],"answer":2,"image":""},{"id":"md2-114-2-66","subject":"md2","topic":"藥理-總論與自主神經","meta":"114年第2次第66題","year":114,"session":2,"number":66,"question":"70歲王先生在接受白內障開刀手術時，出現了虹膜鬆脫症候群（floppy iris syndrome），經檢視王先生平時服用的藥物，推測最可能是由下列何者所造成？","options":["(A) 降血壓藥atenolol","(B) 降血糖藥sitagliptin","(C) 慢性阻塞性肺病用藥ipratropium","(D) 良性攝護腺肥大用藥tamsulosin"],"answer":3,"image":""},{"id":"md2-114-2-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第2次第67題","year":114,"session":2,"number":67,"question":"下列胃腸道藥物中，何者對女性腸躁症伴隨腹瀉，最有療效？","options":["(A) tegaserod","(B) alosetron","(C) prucalopride","(D) granisetron"],"answer":1,"image":""},{"id":"md2-114-2-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第2次第68題","year":114,"session":2,"number":68,"question":"有位70歲老人，患有心臟病及慢性阻塞肺部疾病，常伴隨著偶發性氣管痙攣的症狀。下列何者可以有效解除此病人的氣管痙攣症狀，且較不易引發心律不整的副作用？","options":["(A) prednisone","(B) salmeterol","(C) zafirlukast","(D) ipratropium"],"answer":3,"image":""},{"id":"md2-114-2-69","subject":"md2","topic":"藥理-化學治療","meta":"114年第2次第69題","year":114,"session":2,"number":69,"question":"下列那一個藥物應避免使用於HLA-B*5801基因變異的痛風病人？","options":["(A) colchicine","(B) allopurinol","(C) meclofenamate","(D) febuxostat"],"answer":1,"image":""},{"id":"md2-114-2-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第2次第70題","year":114,"session":2,"number":70,"question":"下列關於組織胺（histamine）受體的敘述，何者最適當？","options":["(A) epinephrine藉由拮抗組織胺H1受體以治療急性過敏反應（anaphylaxis）","(B) 組織胺H1受體拮抗劑常用於治療氣喘","(C) 第一代組織胺H1受體拮抗劑可用於協助入眠","(D) 組織胺H2受體拮抗劑常用於治療過敏性鼻炎"],"answer":2,"image":""},{"id":"md2-114-2-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"114年第2次第71題","year":114,"session":2,"number":71,"question":"癌症病人做化療時易引起噁心嘔吐，若在化療開始前先給與下列何種藥物，則可以有效緩解該噁心嘔吐的症狀？","options":["(A) ketanserin","(B) cyproheptadine","(C) ritanserin","(D) ondansetron"],"answer":3,"image":""},{"id":"md2-114-2-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"114年第2次第72題","year":114,"session":2,"number":72,"question":"下列關於sodium channel blockers類之抗癲癇藥物的敘述，何者錯誤？","options":["(A) phenytoin是結合在inactivated state的sodium channel，使其快速進入resting state","(B) lamotrigine具有use-dependent blocking的作用，對高頻放電的神經產生比較強的抑制作用","(C) oxcarbazepine會加重Dravet syndrome的癲癇反應","(D) carbamazepine可能會引發Stevens-Johnson syndrome，而產生生命危險"],"answer":0,"image":""},{"id":"md2-114-2-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"114年第2次第73題","year":114,"session":2,"number":73,"question":"下列局部麻醉劑中，何者為長效型醯胺類（amide）且具有較明顯的心臟毒性？","options":["(A) bupivacaine","(B) procaine","(C) lidocaine","(D) cocaine"],"answer":0,"image":""},{"id":"md2-114-2-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"114年第2次第74題","year":114,"session":2,"number":74,"question":"Entacapone併用levodopa來治療巴金森氏病，主要因為該藥具有下列何種作用？","options":["(A) 抑制腦部monoamine oxidase B，增加腦部levodopa的含量","(B) 抑制周邊組織catechol-O-methyltransferase，延長levodopa的作用","(C) 增加周邊組織3-O-methyldopa的含量，加強levodopa的作用","(D) 促進中樞神經末梢dopamine的釋放"],"answer":1,"image":""},{"id":"md2-114-2-75","subject":"md2","topic":"藥理-化學治療","meta":"114年第2次第75題","year":114,"session":2,"number":75,"question":"Acetylcysteine可用於治療acetaminophen中毒，下列何者為其解毒之主要作用機制？","options":["(A) 抑制轉胺酵素（aminotransferase）活性","(B) 增加肝臟cytochrome P450酵素活性","(C) 增加肝臟內glutathione含量","(D) 抑制促發炎酵素cyclooxygenase-2表現"],"answer":2,"image":""},{"id":"md2-114-2-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"114年第2次第76題","year":114,"session":2,"number":76,"question":"下列何者於顯微鏡檢死亡之細胞時，通常會呈現「強烈嗜酸性的紅色細胞質，模糊或微紅色之細胞核」等特徵？","options":["(A) liquefactive necrosis","(B) caseous necrosis","(C) fibrinoid necrosis","(D) coagulative necrosis"],"answer":3,"image":""},{"id":"md2-114-2-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"114年第2次第77題","year":114,"session":2,"number":77,"question":"下列何者出現時，表示細胞已經進入不可逆的損傷（irreversible damage）？","options":["(A) leakage of mitochondrial proteins","(B) endoplasmic reticulum dilation","(C) rapid glycogen depletion","(D) endoplasmic reticulum ribosomes detachment"],"answer":0,"image":""},{"id":"md2-114-2-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"114年第2次第78題","year":114,"session":2,"number":78,"question":"有關馬凡氏症候群（Marfan syndrome）的描述，下列何者正確？","options":["(A) 膠原蛋白（collagen）異常所引起的疾病","(B) 體染色體隱性遺傳疾病","(C) 身材矮小","(D) 主動脈根部擴大"],"answer":3,"image":""},{"id":"md2-114-2-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"114年第2次第79題","year":114,"session":2,"number":79,"question":"天皰瘡（pemphigus vulgaris）的致病機轉與下列何者最有關係？","options":["(A) 第一型過敏反應","(B) 第二型過敏反應","(C) 第三型過敏反應","(D) 第四型過敏反應"],"answer":1,"image":""},{"id":"md2-114-2-80","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"114年第2次第80題","year":114,"session":2,"number":80,"question":"慢性一氧化碳中毒主要造成中樞神經何處缺氧？","options":["(A) 大腦半球（cerebral hemisphere）","(B) 小腦（cerebellum）","(C) 基底核（basal ganglia）","(D) 胼胝體（corpus callosum）"],"answer":2,"image":""},{"id":"md2-114-2-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"114年第2次第81題","year":114,"session":2,"number":81,"question":"用以判斷腫瘤為惡性的特徵，下列何者最不可靠？","options":["(A) 生長快速","(B) 分化不良","(C) 不典型有絲分裂","(D) 遠端轉移"],"answer":0,"image":""},{"id":"md2-114-2-82","subject":"md2","topic":"病理-心血管血液","meta":"114年第2次第82題","year":114,"session":2,"number":82,"question":"先天性心臟病中，長期處於下列何種狀況最容易造成肺高壓？","options":["(A) 明顯的心室中隔缺損（ventricular septal defect）","(B) 典型的Fallot氏四合症（classic tetralogy of Fallot）","(C) 成人型導管後主動脈狹窄（adult form postductal coarctation of aorta）","(D) 單獨的肺動脈瓣狹窄（isolated pulmonary stenosis）"],"answer":0,"image":""},{"id":"md2-114-2-83","subject":"md2","topic":"病理-心血管血液","meta":"114年第2次第83題","year":114,"session":2,"number":83,"question":"下列會造成凝血功能異常的狀況，何者主要不是由於血小板功能的缺失？","options":["(A) von Willebrand氏病（von Willebrand disease）","(B) 尿毒症（uremia）","(C) 血友病（hemophilia）","(D) 使用阿斯匹靈（aspirin）藥物"],"answer":2,"image":""},{"id":"md2-114-2-84","subject":"md2","topic":"病理-免疫感染遺傳","meta":"114年第2次第84題","year":114,"session":2,"number":84,"question":"下列何種惡性淋巴瘤，在組織切片中腫瘤細胞通常只占所有細胞的小部分？","options":["(A) 瀰漫性大B細胞淋巴瘤（diffuse large B-cell lymphoma）","(B) 退行性大細胞淋巴瘤（anaplastic large cell lymphoma）","(C) 何杰金氏淋巴瘤（Hodgkin lymphoma）","(D) Burkitt氏淋巴瘤（Burkitt lymphoma）"],"answer":2,"image":""},{"id":"md2-114-2-85","subject":"md2","topic":"病理-心血管血液","meta":"114年第2次第85題","year":114,"session":2,"number":85,"question":"下列何種貧血，骨髓中的造血細胞量（cellularity）最可能比正常少？","options":["(A) 缺鐵性貧血（iron deficiency anemia）","(B) 巨母紅血球性貧血（megaloblastic anemia）","(C) 地中海型貧血（thalassemia）","(D) 再生不良性貧血（aplastic anemia）"],"answer":3,"image":""},{"id":"md2-114-2-86","subject":"md2","topic":"病理-呼吸消化","meta":"114年第2次第86題","year":114,"session":2,"number":86,"question":"下列有關鼻咽癌的敘述，何者錯誤？","options":["(A) 與高風險人類乳突病毒（high-risk human papillomavirus, HR-HPV）有關","(B) 臺灣與中國東南方的盛行率高於美國及歐洲","(C) 形態學上主要分為角化（keratinizing）、非角化（nonkeratinizing）或類基底（basaloid）鱗狀細胞癌","(D) 頸部腫塊、聽力障礙或閉塞感、痰中或鼻涕中帶血、鼻塞、頭痛是常見症狀"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第86題一律給分 (原公告答案 A)"},{"id":"md2-114-2-87","subject":"md2","topic":"病理-呼吸消化","meta":"114年第2次第87題","year":114,"session":2,"number":87,"question":"下列有關小細胞肺癌（small cell carcinoma）的敘述，何者錯誤？","options":["(A) 與抽菸有強烈相關性","(B) 在臺灣，小細胞肺癌有三成帶有EGFR突變","(C) 大多數小細胞肺癌帶有TP53與RB基因突變","(D) 小細胞肺癌也會有副贅瘤症候群（paraneoplastic syndromes）"],"answer":1,"image":""},{"id":"md2-114-2-88","subject":"md2","topic":"病理-呼吸消化","meta":"114年第2次第88題","year":114,"session":2,"number":88,"question":"下列有關塵肺病（pneumoconiosis）的敘述，何者錯誤？","options":["(A) 成因可為無機物或有機物，多與職業或工作環境有關","(B) 矽肺病是目前最常見的塵肺病，成因為吸入silica，形成的肺結節多出現在上肺葉","(C) 矽肺病患者停止接觸矽塵暴露後肺功能通常會逐漸恢復，惟嚴重者需接受肺移植治療","(D) 矽肺病的肺結節常出現嚴重纖維化且有whorled collagen fibers，在偏光顯微鏡下可看到silica沉積"],"answer":2,"image":""},{"id":"md2-114-2-89","subject":"md2","topic":"病理-呼吸消化","meta":"114年第2次第89題","year":114,"session":2,"number":89,"question":"下列有關口腔癌的敘述，何者錯誤？","options":["(A) 白斑（leukoplakia）與紅斑（erythroplakia）是可觀察到的早期病變","(B) 紅斑（erythroplakia）病理上大多數是嚴重異生（severe dysplasia）或原位癌（carcinoma in situ）","(C) 口腔癌最常突變的基因有TP53、CDKN2A、PIK3CA，與肺腺癌類似，目前已有多種有效的標靶藥物","(D) 口腔癌的危險因子包含抽菸、喝酒、檳榔，定期篩檢若能早期診斷則可提高患者預後"],"answer":2,"image":""},{"id":"md2-114-2-90","subject":"md2","topic":"病理-呼吸消化","meta":"114年第2次第90題","year":114,"session":2,"number":90,"question":"關於肝細胞核因子1-α失活的肝細胞腺瘤（HNF1α-inactivated hepatocellular adenoma），下列敘述何者最不適當？","options":["(A) 與成熟型青少年糖尿病3型（maturity onset diabetes of the young, type 3）相關","(B) 好發於女性","(C) 轉化為肝細胞癌的風險極小","(D) 免疫組織化學染色下，腫瘤細胞的liver fatty acid binding protein（LFABP）會高度表達"],"answer":3,"image":""},{"id":"md2-114-2-91","subject":"md2","topic":"病理-呼吸消化","meta":"114年第2次第91題","year":114,"session":2,"number":91,"question":"關於急性膽囊炎，下列敘述何者最不適當？","options":["(A) 大多數的病例是由於結石阻塞膽囊頸或膽囊管而引發","(B) 因前列腺素釋放的減少而導致黏膜和膽囊壁發炎","(C) 急性非結石性膽囊炎（acute acalculous cholecystitis）可由缺血而引起","(D) 急性非結石性膽囊炎（acute acalculous cholecystitis）的危險因子包括敗血症"],"answer":1,"image":""},{"id":"md2-114-2-92","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第2次第92題","year":114,"session":2,"number":92,"question":"腎嗜酸細胞瘤（renal oncocytoma）在電子顯微鏡下觀察，腫瘤細胞含大量何種結構，而造成染色成嗜酸性？","options":["(A) 粒線體","(B) 高基氏體","(C) 溶酶體","(D) 粗糙內質網"],"answer":0,"image":""},{"id":"md2-114-2-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第2次第93題","year":114,"session":2,"number":93,"question":"黃瘤肉芽腫性腎盂腎炎（xanthogranulomatous pyelonephritis）與下列何種細菌感染最為密切？","options":["(A) Streptococcus pneumoniae","(B) Mycobacterium tuberculosis","(C) Proteus mirabilis","(D) Salmonella enterica"],"answer":2,"image":""},{"id":"md2-114-2-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第2次第94題","year":114,"session":2,"number":94,"question":"下列何者為腎細胞癌最顯著之危險因子？","options":["(A) 抽菸","(B) 高血壓","(C) 石綿之暴露","(D) 肥胖之男性"],"answer":0,"image":""},{"id":"md2-114-2-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第2次第95題","year":114,"session":2,"number":95,"question":"與放射線治療最相關的乳房惡性腫瘤為：","options":["(A) 血管肉瘤（angiosarcoma）","(B) 惡性葉狀瘤（malignant phyllodes tumor）","(C) 肌纖維母細胞瘤（myofibroblastoma）","(D) 平滑肌肉瘤（leiomyosarcoma）"],"answer":0,"image":""},{"id":"md2-114-2-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第2次第96題","year":114,"session":2,"number":96,"question":"下列何種乳房病變，發生侵襲性乳癌的風險最高？","options":["(A) 非典型小葉增生（atypical lobular hyperplasia）","(B) 硬化性腺病（sclerosing adenosis）","(C) 複雜性硬化病變（complex sclerosing lesion）","(D) 複雜性纖維腺瘤（fibroadenoma with complex features）"],"answer":0,"image":""},{"id":"md2-114-2-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"114年第2次第97題","year":114,"session":2,"number":97,"question":"62歲女性，子宮頸抹片檢查後，接受子宮頸病理切片（如圖所示）。下列何者為最適合的診斷？","options":["(A) 高度鱗狀上皮內病灶（high-grade squamous intraepithelial lesion）","(B) 鱗狀上皮癌（squamous cell carcinoma）","(C) 原位腺癌（adenocarcinoma in situ）","(D) 低度鱗狀上皮內病灶（low-grade squamous intraepithelial lesion）"],"answer":0,"image":"md2-114-2-97.jpeg"},{"id":"md2-114-2-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"114年第2次第98題","year":114,"session":2,"number":98,"question":"有關骨骼疾病的病理機轉，下列那一組合與蝕骨細胞（osteoclasts）活性異常較有關係？①osteopetrosis ②senile osteoporosis ③post-menopausal osteoporosis ④osteomalacia ⑤Paget disease（osteitis deformans）","options":["(A) ①②④","(B) ①③⑤","(C) ②③⑤","(D) ③④⑤"],"answer":1,"image":""},{"id":"md2-114-2-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"114年第2次第99題","year":114,"session":2,"number":99,"question":"下列皮膚病變皆可能與感染有關，何者在皮膚病灶處最有可能培養出致病微生物？","options":["(A) erythema multiforme","(B) erythema induratum","(C) erythema nodosum","(D) erythema migrans"],"answer":3,"image":""},{"id":"md2-114-2-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"114年第2次第100題","year":114,"session":2,"number":100,"question":"關於感染性關節炎，下列敘述何者最不適當？","options":["(A) 兩歲以下幼兒最常見的化膿性關節炎病原體是沙門氏桿菌（Salmonella）","(B) 成年人的化膿性關節炎最常見之病原體是金黃色葡萄球菌（Staphylococcus aureus）","(C) 結核病關節炎（mycobacterial arthritis）最常感染承重的關節，如髖關節與膝關節","(D) 淋病關節炎（gonococcal arthritis）好發於補體C5-C9功能缺損的病人"],"answer":0,"image":""},{"id":"md2-115-1-1","subject":"md2","topic":"藥理-化學治療","meta":"115年第1次第1題","year":115,"session":1,"number":1,"question":"有關胺基醣苷類（aminoglycosides）抗生素之敘述，下列何者最不適當？","options":["(A) 此類抗生素可抑制細菌蛋白質生合成，進而達到殺菌或抑制細菌生長之作用","(B) 降低抗生素進入細菌內可能會導致細菌對此類抗生素出現抗藥性","(C) 此類抗生素需在厭氧環境下，方可穿過細胞膜，因此厭氧菌對此類抗生素具有感受性（susceptible）","(D) 卡納黴素（kanamycin）與阿米卡星（amikacin）為此類常見抗生素"],"answer":2,"image":""},{"id":"md2-115-1-2","subject":"md2","topic":"藥理-化學治療","meta":"115年第1次第2題","year":115,"session":1,"number":2,"question":"磺胺類藥物（sulfonamides）可抑制細菌所需葉酸（folic acid）之合成，因此具有抑菌或殺菌作用，但對哺乳類動物細胞不具有顯著毒性的最主要原因為何？","options":["(A) 哺乳類動物細胞合成葉酸之相關酵素與磺胺類藥物親合力低，較不受影響","(B) 哺乳類動物細胞不自行合成葉酸，因此不受磺胺類藥物影響","(C) 在使用磺胺類藥物的情況下，哺乳類動物細胞可合成類似葉酸之衍生物作為替代","(D) 葉酸並不會被哺乳類動物細胞所利用"],"answer":1,"image":""},{"id":"md2-115-1-3","subject":"md2","topic":"細菌學","meta":"115年第1次第3題","year":115,"session":1,"number":3,"question":"關於細菌莢膜（capsule）的敘述，下列何者最不適當？","options":["(A) 莢膜對細菌的生長是絕對必要的結構","(B) 炭疽桿菌（Bacillus anthracis）產生多肽莢膜（polypeptide capsule）","(C) 莢膜具有抵抗免疫細胞吞噬作用（phagocytosis）的能力","(D) 莢膜能促進細菌與其他細菌或宿主組織表面的黏附作用"],"answer":0,"image":""},{"id":"md2-115-1-4","subject":"md2","topic":"免疫學","meta":"115年第1次第4題","year":115,"session":1,"number":4,"question":"若先天interferon-γ受體基因缺陷的病人感染結核分枝桿菌，最可能導致下列何種結果？","options":["(A) 病人將在沒有症狀的情況下清除結核分枝桿菌的感染","(B) 病人將產生更強的免疫反應，並降低活動性結核病的風險","(C) 病人罹患播散性結核病的風險將增加","(D) 病人將具有完全抵抗結核分枝桿菌感染的免疫力"],"answer":2,"image":""},{"id":"md2-115-1-5","subject":"md2","topic":"細菌學","meta":"115年第1次第5題","year":115,"session":1,"number":5,"question":"關於廣泛抗藥性結核（extensively drug-resistant tuberculosis, XDR TB）的敘述，下列何者最適當？","options":["(A) XDR TB是一種多重抗藥性結核病（multidrug-resistant tuberculosis），同時對氟喹諾酮類藥物（fluoroquinolones）和至少一種二線藥物具有額外的抗藥性","(B) XDR TB只發生在AIDS患者身上，尚非全球性的問題","(C) XDR TB感染者目前無抗生素可治療，因此只能隔離","(D) XDR TB接觸者，應給與預防性抗生素治療"],"answer":0,"image":""},{"id":"md2-115-1-6","subject":"md2","topic":"細菌學","meta":"115年第1次第6題","year":115,"session":1,"number":6,"question":"患者性行為數週後，腹股溝淋巴結疼痛腫大並於皮膚表面形成瘻管，最可能是受到下列何種微生物的感染？","options":["(A) 奈瑟氏淋病菌（Neisseria gonorrhoeae）","(B) 砂眼披衣菌（Chlamydia trachomatis）","(C) 肉芽腫克雷伯氏菌（Klebsiella granulomatis）","(D) 杜克氏嗜血桿菌（Haemophilus ducreyi）"],"answer":1,"image":""},{"id":"md2-115-1-7","subject":"md2","topic":"細菌學","meta":"115年第1次第7題","year":115,"session":1,"number":7,"question":"孕婦感染下列何種細菌可引起類流感症狀，並最可能導致流產或新生兒疾病？","options":["(A) 化膿性鏈球菌（Streptococcus pyogenes）","(B) 紅斑丹毒絲菌（Erysipelothrix rhusiopathiae）","(C) 單核細胞增生性李斯特菌（Listeria monocytogenes）","(D) 流行性嗜血桿菌（Haemophilus influenzae）"],"answer":2,"image":""},{"id":"md2-115-1-8","subject":"md2","topic":"藥理-化學治療","meta":"115年第1次第8題","year":115,"session":1,"number":8,"question":"關於抗病毒藥物的敘述，下列何者最適當？","options":["(A) 高效抗反轉錄病毒療法（Highly Active Antiretroviral Therapy, HAART）通常使用單一藥物進行治療，主要是為了減少副作用","(B) C型肝炎病毒（Hepatitis C virus, HCV）抗病毒藥物可有效清除體內病毒，而其成分皆針對病毒RNA聚合酶（RNA polymerase）","(C) 抗病毒藥物只能對單一種病毒有效，無法用於治療不同種類的病毒感染","(D) Zidovudine（Retrovir）是一種反轉錄酶（reverse transcriptase）抑制劑，可用來針對人類免疫缺乏病毒"],"answer":3,"image":""},{"id":"md2-115-1-9","subject":"md2","topic":"病毒學","meta":"115年第1次第9題","year":115,"session":1,"number":9,"question":"下列關於各類型肝炎病毒的敘述中，何者最適當？","options":["(A) C型肝炎病毒（HCV）目前有有效的疫苗可預防，並且可以通過食物和水傳播","(B) D型肝炎病毒（HDV）無法獨立複製，必須依賴B型肝炎病毒（HBV），並且主要通過血液與性接觸傳播","(C) A型肝炎病毒（HAV）主要通過血液與性接觸傳播，並且目前有有效疫苗可預防","(D) 除D型肝炎病毒（HDV）基因體屬於DNA外，其他皆屬於RNA病毒"],"answer":1,"image":""},{"id":"md2-115-1-10","subject":"md2","topic":"真菌學","meta":"115年第1次第10題","year":115,"session":1,"number":10,"question":"一般情況下，下列何種念珠菌僅以單細胞型式存在，不產生假菌株或真菌絲？","options":["(A) Candida krusei","(B) Candida tropicalis","(C) Candida glabrata","(D) Candida parapsilosis"],"answer":2,"image":""},{"id":"md2-115-1-11","subject":"md2","topic":"真菌學","meta":"115年第1次第11題","year":115,"session":1,"number":11,"question":"在吞噬細胞內呈現裂殖酵母（fission yeasts）是下列何種感染的主要特徵？","options":["(A) Emergomycosis","(B) Coccidioidomycosis","(C) Histoplasmosis","(D) Talaromycosis"],"answer":3,"image":""},{"id":"md2-115-1-12","subject":"md2","topic":"細菌學","meta":"115年第1次第12題","year":115,"session":1,"number":12,"question":"下列何種細菌的系統主要用於保護染色體不受噬菌體（bacteriophage）與外源質體的嵌合作用（integration）？","options":["(A) SOS反應（SOS response）","(B) 規律間隔重複短迴文序列簇／CRISPR相關蛋白系統（clustered regularly interspaced short palindromic repeats/CRISPR associated proteins）","(C) 易誤修復（error-prone repair）","(D) 裁除式修復（excision repair）"],"answer":1,"image":""},{"id":"md2-115-1-13","subject":"md2","topic":"細菌學","meta":"115年第1次第13題","year":115,"session":1,"number":13,"question":"下列何種毒素的作用機轉與霍亂毒素（cholera toxin）類似？","options":["(A) 白喉毒素（diphtheria toxin）","(B) 大腸桿菌（Escherichia coli）的第一型熱不穩定毒素（LT-Ⅰ）","(C) 副溶血弧菌（Vibrio parahaemolyticus）的溶血素（hemolysin）","(D) 痢疾志賀氏桿菌（Shigella dysenteriae）的侵入素（invasin）"],"answer":1,"image":""},{"id":"md2-115-1-14","subject":"md2","topic":"藥理-化學治療","meta":"115年第1次第14題","year":115,"session":1,"number":14,"question":"下列關於Sofosbuvir、Oseltamivir、Darunavir、Raltegravir藥物的比較何者最適當？","options":["(A) Darunavir、Raltegravir皆為人類免疫不全病毒（human immunodeficiency virus）的抗病毒藥物","(B) Oseltamivir抑制病毒進入細胞（entry），Darunavir抑制病毒的釋放（release）","(C) Sofosbuvir為B型肝炎病毒（hepatitis B virus）的抗病毒藥物，Oseltamivir為流感病毒（influenza virus）的抗病毒藥物","(D) Sofosbuvir、Raltegravir皆為蛋白酶抑制劑（protease inhibitor）"],"answer":0,"image":""},{"id":"md2-115-1-15","subject":"md2","topic":"免疫學","meta":"115年第1次第15題","year":115,"session":1,"number":15,"question":"下列何種情況會使患者更容易受到伊科病毒（echovirus）感染呼吸道和胃腸道而引起嚴重疾病？","options":["(A) 低伽瑪球蛋白血症（hypogammaglobulinemia）","(B) 鐮狀細胞貧血（sickle cell anemia）","(C) 發炎性腸道疾病（inflammatory bowel disease）","(D) 消化性潰瘍（peptic ulcer）"],"answer":0,"image":""},{"id":"md2-115-1-16","subject":"md2","topic":"病毒學","meta":"115年第1次第16題","year":115,"session":1,"number":16,"question":"有一種正股RNA病毒（positive-sense RNA virus）具有二十面體病毒殼體（capsid），無套膜（envelope），經糞口傳播，在罕見病例中會引起癱瘓。此病毒屬於那一病毒科？","options":["(A) 腺病毒科（Adenoviridae）","(B) 小RNA病毒科（Picornaviridae）","(C) 呼腸孤病毒科（Reoviridae）","(D) 披衣病毒科（Togaviridae）"],"answer":1,"image":""},{"id":"md2-115-1-17","subject":"md2","topic":"病毒學","meta":"115年第1次第17題","year":115,"session":1,"number":17,"question":"第一型干擾素（interferon）α及β做為抗病毒藥物，最主要是抑制病毒複製的下列何項步驟？","options":["(A) 病毒的入侵","(B) 病毒轉錄","(C) 病毒蛋白質合成","(D) 病毒的組裝"],"answer":2,"image":""},{"id":"md2-115-1-18","subject":"md2","topic":"免疫學","meta":"115年第1次第18題","year":115,"session":1,"number":18,"question":"後天性免疫反應需較長時間建立，從接觸病原後需數天到數週才達到高峰。然而，這些反應比先天性免疫反應更具特異性，且能產生免疫記憶，增強面臨相同病原體時的保護，下列何者最符合此種應用？","options":["(A) 疫苗","(B) 抗生素","(C) 抗過敏反應藥物","(D) 免疫抑制劑"],"answer":0,"image":""},{"id":"md2-115-1-19","subject":"md2","topic":"免疫學","meta":"115年第1次第19題","year":115,"session":1,"number":19,"question":"痛風（gout）是尿酸結晶（urate crystals）沉澱在關節組織後所引起的發炎症。下列那一種先天性免疫活化途徑最可能參與上述發炎反應？","options":["(A) NLRP1","(B) NLRP3","(C) MDA5","(D) cGAS"],"answer":1,"image":""},{"id":"md2-115-1-20","subject":"md2","topic":"免疫學","meta":"115年第1次第20題","year":115,"session":1,"number":20,"question":"關於major histocompatibility complex（MHC）polymorphism與抗病毒免疫反應，下列敘述何者最具相關性？","options":["(A) 增加可被MHC呈獻的抗原種類，有利於抑制病毒在族群中傳播","(B) 呈獻出最容易被T細胞記憶的主要抗原點（predominant epitope）","(C) 確保沒有年齡別的抗病毒免疫力差異性","(D) 避免T細胞在毒殺病毒時造成過度的自體免疫反應"],"answer":0,"image":""},{"id":"md2-115-1-21","subject":"md2","topic":"免疫學","meta":"115年第1次第21題","year":115,"session":1,"number":21,"question":"下列何種CD4效應T細胞（effector CD4 T cells）分泌的細胞激素（cytokines），扮演最重要的免疫抑制功能？","options":["(A) IL-4","(B) IL-10","(C) IL-12","(D) TNF-α"],"answer":1,"image":""},{"id":"md2-115-1-22","subject":"md2","topic":"免疫學","meta":"115年第1次第22題","year":115,"session":1,"number":22,"question":"下列那些基因缺失會造成抗體無法進行類型轉換（class switch）？①activation-induced cytidine deaminase（AID） ②adenosine deaminase（ADA） ③CD40 ④CD40 ligand ⑤RAG1","options":["(A) ①③④","(B) ②④⑤","(C) ①②⑤","(D) ③④⑤"],"answer":0,"image":""},{"id":"md2-115-1-23","subject":"md2","topic":"免疫學","meta":"115年第1次第23題","year":115,"session":1,"number":23,"question":"每一顆B細胞只表現一種專一性（specificity）抗原受體，其最主要的機制為：","options":["(A) RNA選擇性剪接（alternative splicing）","(B) DNA重組（rearrangement）","(C) 等位基因排除（allelic exclusion）","(D) 類型轉換重組（class switch recombination）"],"answer":2,"image":""},{"id":"md2-115-1-24","subject":"md2","topic":"免疫學","meta":"115年第1次第24題","year":115,"session":1,"number":24,"question":"呼吸道剛被病毒感染時，最不可能產生下列何種分子？","options":["(A) type I interferon","(B) type II interferon","(C) CCL2","(D) IL-18"],"answer":1,"image":""},{"id":"md2-115-1-25","subject":"md2","topic":"細菌學","meta":"115年第1次第25題","year":115,"session":1,"number":25,"question":"Streptococcus pneumoniae是一種胞外菌（extracellular bacteria）。下列何者最有可能幫助S. pneumoniae逃脫免疫偵測？","options":["(A) 產生大量的lipopolysaccharide（LPS），毒殺免疫細胞","(B) 形成孢子，躲避免疫偵測","(C) 減少基因表達，避免刺激免疫反應","(D) 細菌表面的莢膜多醣（capsular polysaccharide），干擾補體活化反應"],"answer":3,"image":""},{"id":"md2-115-1-26","subject":"md2","topic":"免疫學","meta":"115年第1次第26題","year":115,"session":1,"number":26,"question":"2018年諾貝爾生醫獎，由James Allison與Tasuku Honjo共同獲得，表彰他們發展出利用免疫檢查點抑制劑（immune checkpoint inhibitor, ICI）對抗癌療法的突破性研究，下列關於免疫檢查點抑制劑的描述，何者最不適當？","options":["(A) ICI在癌症治療取得突破性的結果，如：黑色素瘤（melanoma）獲得較好的反應","(B) Pembrolizumab與Nivolumab是兩種常見的PD-1抗體藥物，其治療反應率優於CTLA-4抗體藥物","(C) Ipilimumab是CTLA-4抗體藥物，其治療副作用率高於PD-1抗體藥物","(D) 對於急性淋巴細胞白血病（acute lymphocytic leukemia, ALL），除了CAR-T療法外，ICI亦有顯著的療效"],"answer":3,"image":""},{"id":"md2-115-1-27","subject":"md2","topic":"免疫學","meta":"115年第1次第27題","year":115,"session":1,"number":27,"question":"移植前所進行捐贈者與受贈者之淋巴細胞混合反應（mixed lymphocyte reaction, MLR），最主要評估下列何者之相容程度？","options":["(A) HLA-A","(B) HLA-DR","(C) H2-D","(D) H2-K"],"answer":1,"image":""},{"id":"md2-115-1-28","subject":"md2","topic":"免疫學","meta":"115年第1次第28題","year":115,"session":1,"number":28,"question":"抗CD20抗體（Rituximab）可治療非霍奇金氏淋巴瘤（non-Hodgkin's lymphoma）。主要是經由下列何種機轉引起B細胞的凋亡，達到抗腫瘤效果？","options":["(A) ADCC（經由活化Fc receptor）","(B) immunotoxin（抗體 + toxin）","(C) 抗體結合chemotherapeutic drug","(D) 免疫檢查點阻斷方法（immune checkpoint blockade）"],"answer":0,"image":""},{"id":"md2-115-1-29","subject":"md2","topic":"寄生蟲學","meta":"115年第1次第29題","year":115,"session":1,"number":29,"question":"下列何種寄生蟲感染人體後，其第三期幼蟲會在橫紋肌形成囊體，臨床上此時期亦為診斷期（diagnostic stage）？","options":["(A) 犬蛔蟲（Toxocara canis）","(B) 廣東住血線蟲（Angiostrongylus cantonensis）","(C) 菲律賓毛線蟲（Capillaria philippinensis）","(D) 旋毛蟲（Trichinella spiralis）"],"answer":3,"image":""},{"id":"md2-115-1-30","subject":"md2","topic":"寄生蟲學","meta":"115年第1次第30題","year":115,"session":1,"number":30,"question":"王先生赴中國江浙地區經商，期間經常食用醉蟹菜餚，返國一段時間後出現發燒、咳嗽且帶血稠痰，隨後經痰液及糞便鏡檢而確診，據此病史最可能感染下列何種寄生蟲？","options":["(A) 中華肝吸蟲（Clonorchis sinensis）","(B) 衛氏肺吸蟲（Paragonimus westermani）","(C) 薑片蟲（Fasciolopsis buski）","(D) 橫川氏吸蟲（Metagonimus yokogawai）"],"answer":1,"image":""},{"id":"md2-115-1-31","subject":"md2","topic":"寄生蟲學","meta":"115年第1次第31題","year":115,"session":1,"number":31,"question":"李先生因頭痛、肌肉痙攣及視力急速減退而就醫，血液檢查有輕微的嗜伊紅性白血球（eosinophil）上升，糞便檢查未發現任何寄生蟲蟲卵或蟲體，電腦斷層掃描（CT）和磁振造影（MRI）在腦實質組織、腦室發現許多囊體（直徑4～15毫米），患者先前曾被公司派駐墨西哥一年，他最可能罹患下列何種疾病？","options":["(A) 幼裂絛蟲症（sparganosis）","(B) 囊尾幼蟲症（cysticercosis）","(C) 廣節裂頭絛蟲症（diphyllobothriasis latum）","(D) 縮小包膜絛蟲症（hymenolepiasis diminuta）"],"answer":1,"image":""},{"id":"md2-115-1-32","subject":"md2","topic":"寄生蟲學","meta":"115年第1次第32題","year":115,"session":1,"number":32,"question":"下列有關陰道滴蟲症（vaginal trichomoniasis）之敘述，何者最不適當？","options":["(A) 主要經由性行為傳播","(B) 男性患者通常無明顯症狀，但有可能引起攝護腺炎","(C) metronidazole為常用的有效治療藥物","(D) 新生兒不會感染此症"],"answer":3,"image":""},{"id":"md2-115-1-33","subject":"md2","topic":"寄生蟲學","meta":"115年第1次第33題","year":115,"session":1,"number":33,"question":"人巴貝氏原蟲症（human babesiosis）感染之最佳治療用藥為何？①青黴素（penicillin） ②四環素（tetracycline） ③克林達黴素（clindamycin） ④奎寧（quinine）","options":["(A) ①②","(B) ②③","(C) ②④","(D) ③④"],"answer":3,"image":""},{"id":"md2-115-1-34","subject":"md2","topic":"寄生蟲學","meta":"115年第1次第34題","year":115,"session":1,"number":34,"question":"李先生到非洲旅遊時遭到某種蠅類叮咬，不久叮咬處發生下疳（chancre），後來併有發燒、後頸淋巴結腫大等症狀，晚期於腦脊髓液中檢出的寄生蟲數亦高，他最可能感染下列何種寄生蟲？","options":["(A) 杜氏利什曼原蟲（Leishmania donovani）","(B) 枯西氏錐蟲（Trypanosoma cruzi）","(C) 布氏岡比亞錐蟲（Trypanosoma brucei gambiense）","(D) 惡性瘧原蟲（Plasmodium falciparum）"],"answer":2,"image":""},{"id":"md2-115-1-35","subject":"md2","topic":"寄生蟲學","meta":"115年第1次第35題","year":115,"session":1,"number":35,"question":"有關黑水熱（blackwater fever）的敘述，下列何者最為適當？","options":["(A) 為長期罹患瘧疾的臨床症狀，以卵形瘧原蟲（Plasmodium ovale）感染最為顯著","(B) 因肝臟細胞受到瘧原蟲寄生，間接造成血小板低下（thrombocytopenia）所致","(C) 血管內大量溶血併發血紅素尿（hemoglobinuria）所造成的症狀","(D) 與患者體內IFN-γ受體損傷有關"],"answer":2,"image":""},{"id":"md2-115-1-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第1次第36題","year":115,"session":1,"number":36,"question":"某大型汽車公司的3,000名員工從1980年就開始接受了初步健康檢查。從1980年後該公司每三年提供一次員工健康檢查，並可透過健康檢查結果與追蹤結果找出員工是否有罹患肝癌。研究者使用該公司之上述相關數據來探討肝癌與該公司工廠中接觸油漆之間的相關性。上述描述最有可能是下列何種研究設計？","options":["(A) 隨機對照試驗","(B) 世代研究","(C) 病例對照研究","(D) 橫斷性研究"],"answer":1,"image":""},{"id":"md2-115-1-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第1次第37題","year":115,"session":1,"number":37,"question":"下列何項說明，是探討交互作用（interaction）的最主要目的？","options":["(A) 探討疾病的發生率是否受到干擾因子的影響","(B) 探討疾病的發生率是否受到中介因子的影響","(C) 探討疾病的發生率是否受到兩個以上危險因子的影響","(D) 探討疾病的發生率是否受到危險因子、干擾因子以及中介因子的影響"],"answer":2,"image":""},{"id":"md2-115-1-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第1次第38題","year":115,"session":1,"number":38,"question":"對某國小一年級學童進行齲齒調查，發現每百名男學童有24人齲齒，每百名女學童有12人齲齒，因此推論男學童的齲齒發生率是女學童的2倍。上述推論不適當，其最主要原因為何？","options":["(A) 不知道調查總人數","(B) 此為盛行率，並非發生率","(C) 沒有進行年齡調整","(D) 未進行統計檢定"],"answer":1,"image":""},{"id":"md2-115-1-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第1次第39題","year":115,"session":1,"number":39,"question":"某研究者想探討某基因多型性（AA／AG組相對GG組）是否與口腔癌的發生有關，收集200名口腔癌患者與200名沒有口腔癌的健康者的資料，但該研究者懷疑該基因型與口腔癌的關聯性是否因抽菸狀態不同而不一樣，下列那一個考量或處理最能幫助該研究者解決此問題？","options":["(A) 檢定抽菸與基因型對口腔癌的交互作用（interaction）","(B) 將抽菸狀態的變項加入羅吉斯（logistic）迴歸模式中做調整即可解決","(C) 確認抽菸狀態是否對基因型鑑定（genotyping）判讀造成偏差（bias）","(D) 增加病例與對照組的樣本數即可不用擔心"],"answer":0,"image":""},{"id":"md2-115-1-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"115年第1次第40題","year":115,"session":1,"number":40,"question":"一般原水經自來水廠處理及加氯消毒後，可控制許多水媒傳染病，但對下列何者的效果最不理想？","options":["(A) 梨形鞭毛蟲（Giardia）","(B) 大腸桿菌（Escherichia coli）","(C) 沙門氏菌（Salmonella）","(D) 志賀桿菌（Shigella）"],"answer":0,"image":""},{"id":"md2-115-1-41","subject":"md2","topic":"寄生蟲學","meta":"115年第1次第41題","year":115,"session":1,"number":41,"question":"埃及斑蚊為臺灣登革熱主要病媒蚊，下列何者最不符合埃及斑蚊之生態習性描述？","options":["(A) 喜歡棲息在戶外","(B) 在攝氏17度以下活性低","(C) 警覺性高，易受驚動","(D) 中斷式吸血"],"answer":0,"image":""},{"id":"md2-115-1-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"115年第1次第42題","year":115,"session":1,"number":42,"question":"工業使用汞的量非常大，曾經造成環境與職業衛生的問題。關於汞的敘述，下列何者最不恰當？","options":["(A) 早期牙醫補牙，填充齲齒使用含汞材料","(B) 環境的汞污染曾造成極大的公害事件，例如日本的水俁病（Minamata disease）","(C) 腦部是一個對慢性汞暴露的敏感部位，可能產生皮質部的海綿性退化（spongeous degeneration）","(D) 一般而言，土壤中的汞可由植物吸收，人或動物食入植物的莖葉或果實而導致汞中毒"],"answer":3,"image":""},{"id":"md2-115-1-43","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第1次第43題","year":115,"session":1,"number":43,"question":"有關疾病的篩檢，下列敘述何者最不適當？","options":["(A) 對盛行率高的族群進行，效率較高","(B) 只是用來將受檢族群區分為可能有病與可能沒有病的兩群人","(C) 篩檢結果呈現陽性的人真正有病的比例稱為敏感度","(D) 比較適用於沒有明顯相關症狀的人"],"answer":2,"image":""},{"id":"md2-115-1-44","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"115年第1次第44題","year":115,"session":1,"number":44,"question":"下列敘述何者是一種「健康不平等」？","options":["(A) 老年人的新冠病毒肺炎死亡率高於年輕人","(B) 偏鄉地區的平均壽命低於都會地區","(C) 高學歷者的平均收入高於低學歷者","(D) 吸菸者得到肺癌的機率高於非吸菸者"],"answer":1,"image":""},{"id":"md2-115-1-45","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"115年第1次第45題","year":115,"session":1,"number":45,"question":"「設計思考（design thinking）」為健康促進創意宣導策略之一。下列針對設計思考的描述何者最不恰當？","options":["(A) 設計思考強調「創意」的問題解決方法，其核心是以人為本","(B) 設計思考的第一步驟為「定義」，即是將收集到的資料收斂成一個問題","(C) 在設計思考的過程中有一項核心的任務，就是瞭解「使用者的經驗」","(D) 在定義出問題後，可在「發展」階段針對問題尋找創新的解決方法"],"answer":1,"image":""},{"id":"md2-115-1-46","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"115年第1次第46題","year":115,"session":1,"number":46,"question":"下列有關健康識能（health literacy）的敘述，何者最恰當？","options":["(A) 健康識能較佳者，做出適當健康決策之能力較佳","(B) 健康識能不足與高血壓等慢性病的發生有負向關係","(C) 個人健康識能的高低，與預防性的健康服務利用度無關","(D) 個人健康識能的高低，取決其獲取健康資訊之積極程度"],"answer":0,"image":""},{"id":"md2-115-1-47","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"115年第1次第47題","year":115,"session":1,"number":47,"question":"衛生福利部組織架構包含6處10司，10個司中何者不是在民國106年之後成立的？","options":["(A) 長期照顧司","(B) 社會救助及社工司","(C) 心理健康司","(D) 口腔健康司"],"answer":1,"image":""},{"id":"md2-115-1-48","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"115年第1次第48題","year":115,"session":1,"number":48,"question":"臺灣針對傳染病訂有五類傳染病通報的分級，其中有關通報時間的敘述何者最不恰當？","options":["(A) 第一類傳染病必須立刻通報","(B) 第二類傳染病應於3天內通報","(C) 第三類傳染病應於1週內通報，必要時中央主管機關得調整之","(D) 第四類傳染病依中央主管機關公告之期限及規定"],"answer":1,"image":""},{"id":"md2-115-1-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"115年第1次第49題","year":115,"session":1,"number":49,"question":"長期照護服務種類繁多，為了協助民眾使用適當服務，由專門人員負責發掘社區中需要服務的個案，進行個案評估、擬定服務計畫、協助引進服務、監測服務的提供與評估服務成效，這個服務制度稱之為：","options":["(A) 照顧管理","(B) 居家照護","(C) 居家醫療","(D) 連續照護"],"answer":0,"image":""},{"id":"md2-115-1-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"115年第1次第50題","year":115,"session":1,"number":50,"question":"下列何者不是我國全民健保財源籌措的主要來源？","options":["(A) 政府的一般稅收","(B) 民眾繳納的罰款","(C) 雇主保險費的分擔","(D) 被保險人保險費"],"answer":1,"image":""},{"id":"md2-115-1-51","subject":"md2","topic":"藥理-總論與自主神經","meta":"115年第1次第51題","year":115,"session":1,"number":51,"question":"下列何者不屬於肝臟代謝藥物的phase II反應？","options":["(A) acetylation","(B) glycine conjugation","(C) sulfation","(D) hydrolysis"],"answer":3,"image":""},{"id":"md2-115-1-52","subject":"md2","topic":"藥理-化學治療","meta":"115年第1次第52題","year":115,"session":1,"number":52,"question":"下列抗腫瘤藥物中，何者可與微小管蛋白tubulin結合，進而阻斷tubulin聚合成小管，抑制腫瘤細胞生長？","options":["(A) cisplatin","(B) cytarabine","(C) vinorelbine","(D) docetaxel"],"answer":2,"image":""},{"id":"md2-115-1-53","subject":"md2","topic":"藥理-化學治療","meta":"115年第1次第53題","year":115,"session":1,"number":53,"question":"下列關於aminoglycosides抗生素之敘述，何者錯誤？","options":["(A) 可藉由併用ampicillin增加藥物穿透細菌的能力，以增強治療enterococcal endocarditis效用","(B) 作用強度及毒殺細菌速度與使用劑量呈正相關","(C) 可產生後抗生素效應（postantibiotic effect），因此單日使用單一高劑量會比多次低劑量效用更好","(D) 靜脈注射給藥後在腦脊髓液的濃度比在腎臟皮質中的濃度高"],"answer":3,"image":""},{"id":"md2-115-1-54","subject":"md2","topic":"藥理-化學治療","meta":"115年第1次第54題","year":115,"session":1,"number":54,"question":"下列治療癌症之抗體藥物中，何者可與乳癌細胞之HER2受體結合，而達到抗癌作用？","options":["(A) bevacizumab","(B) necitumumab","(C) panitumumab","(D) pertuzumab"],"answer":3,"image":""},{"id":"md2-115-1-55","subject":"md2","topic":"藥理-化學治療","meta":"115年第1次第55題","year":115,"session":1,"number":55,"question":"下列藥物中，何者可抑制黴菌之cytochrome P450酵素，進而抑制細胞膜麥角脂醇（ergosterol）生成？","options":["(A) amphotericin B","(B) fluconazole","(C) griseofulvin","(D) terbinafine"],"answer":1,"image":""},{"id":"md2-115-1-56","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"115年第1次第56題","year":115,"session":1,"number":56,"question":"下列藥物中，何者與warfarin合併使用時，最可能產生出血的風險？","options":["(A) cholestyramine","(B) chlorthalidone","(C) benzodiazepines","(D) amiodarone"],"answer":3,"image":""},{"id":"md2-115-1-57","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"115年第1次第57題","year":115,"session":1,"number":57,"question":"下列藥物中，何者最適合用於治療第八凝血因子缺乏之血友病（hemophilia A）？","options":["(A) deferoxamine","(B) desmopressin","(C) oprelvekin","(D) ferumoxytol"],"answer":1,"image":""},{"id":"md2-115-1-58","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"115年第1次第58題","year":115,"session":1,"number":58,"question":"下列有關大分子抗體藥物evolocumab改善高血脂之敘述，何者錯誤？","options":["(A) 具抑制proprotein convertase subtilisin/kexin type 9（PCSK9）之作用","(B) 促使LDL含量明顯下降","(C) 促使apoB-100明顯上升","(D) 具有類流感症狀（flu-like symptoms）之副作用"],"answer":2,"image":""},{"id":"md2-115-1-59","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第1次第59題","year":115,"session":1,"number":59,"question":"下列何者不是屬於促進胰島素分泌的藥物？","options":["(A) nateglinide","(B) glimepiride","(C) sulpiride","(D) repaglinide"],"answer":2,"image":""},{"id":"md2-115-1-60","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第1次第60題","year":115,"session":1,"number":60,"question":"下列關於糖皮質素（glucocorticoids）之副作用，何者錯誤？","options":["(A) 肌肉量和肌力下降","(B) 低血糖","(C) 骨質疏鬆","(D) 消化性潰瘍"],"answer":1,"image":""},{"id":"md2-115-1-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第1次第61題","year":115,"session":1,"number":61,"question":"下列口服利尿劑中，何者屬於loop diuretics？","options":["(A) bumetanide","(B) acetazolamide","(C) indapamide","(D) tolvaptan"],"answer":0,"image":""},{"id":"md2-115-1-62","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第1次第62題","year":115,"session":1,"number":62,"question":"下列關於testosterone cypionate之敘述，何者錯誤？","options":["(A) 可使用肌肉注射","(B) 會有黃疸（jaundice）的副作用","(C) 可增加HDL及降低LDL之血中濃度","(D) 會有男性乳房增大之副作用"],"answer":2,"image":""},{"id":"md2-115-1-63","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"115年第1次第63題","year":115,"session":1,"number":63,"question":"Sacubitril可與valsartan併用治療心衰竭，下列有關其作用機轉之敘述，何者錯誤？","options":["(A) sacubitril會抑制BNP及ANP的代謝","(B) sacubitril會增加angiotensin I及angiotensin II的含量，因此需要與valsartan合用","(C) valsartan抑制AT1受體後，有利於AT2受體的活化","(D) sacubitril不會增加bradykinin累積而產生angioedema"],"answer":3,"image":""},{"id":"md2-115-1-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"115年第1次第64題","year":115,"session":1,"number":64,"question":"下列鈣離子通道阻斷劑（calcium channel blocker）中，何者半衰期最短，且無法口服使用於降低血壓？","options":["(A) amlodipine","(B) diltiazem","(C) clevidipine","(D) verapamil"],"answer":2,"image":""},{"id":"md2-115-1-65","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第1次第65題","year":115,"session":1,"number":65,"question":"下列關於ipratropium的敘述，何者最不適當？","options":["(A) 為muscarinic cholinergic receptor的拮抗劑","(B) 最常用的劑型為吸入劑型與霧化劑型","(C) 常用於慢性阻塞性肺病（chronic obstructive pulmonary disease），幫助支氣管擴張","(D) 常用於青光眼（glaucoma），幫助房水（aqueous humor）排出"],"answer":3,"image":""},{"id":"md2-115-1-66","subject":"md2","topic":"藥理-總論與自主神經","meta":"115年第1次第66題","year":115,"session":1,"number":66,"question":"病人使用clonidine時，最不容易出現下列何種效果？","options":["(A) 血壓降低","(B) 口乾舌燥","(C) 嚴重腹瀉","(D) 更年期熱潮紅（menopausal hot flushes）減輕"],"answer":2,"image":""},{"id":"md2-115-1-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第1次第67題","year":115,"session":1,"number":67,"question":"下列呼吸道治療藥物中，何者亦可治療慢性復發蕁麻疹（chronic recurrent urticaria）及花生過敏？","options":["(A) albuterol","(B) dupilumab","(C) roflumilast","(D) omalizumab"],"answer":3,"image":""},{"id":"md2-115-1-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第1次第68題","year":115,"session":1,"number":68,"question":"下列何種胃腸道藥物是cystic fibrosis transmembrane conductance regulator抑制劑，最適合用於治療HIV藥物引起的腹瀉？","options":["(A) linaclotide","(B) crofelemer","(C) diphenoxylate","(D) docusate"],"answer":1,"image":""},{"id":"md2-115-1-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第1次第69題","year":115,"session":1,"number":69,"question":"下列何者為PGE1衍生物，可用來治療便秘型腸躁症（irritable bowel syndrome with constipation）？","options":["(A) linaclotide","(B) prucalopride","(C) lubiprostone","(D) bimatoprost"],"answer":2,"image":""},{"id":"md2-115-1-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第1次第70題","year":115,"session":1,"number":70,"question":"下列治療類風濕性關節炎的藥物中，何者不是經由直接抑制TNF-α的作用而產生療效？","options":["(A) infliximab","(B) etanercept","(C) adalimumab","(D) abatacept"],"answer":3,"image":""},{"id":"md2-115-1-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第1次第71題","year":115,"session":1,"number":71,"question":"下列何種藥物可併用opioid來減低病人術後的疼痛，但不建議使用超過5天？","options":["(A) belimumab","(B) tramadol","(C) ketorolac","(D) ibuprofen"],"answer":2,"image":""},{"id":"md2-115-1-72","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"115年第1次第72題","year":115,"session":1,"number":72,"question":"下列關於ethosuximide之敘述，何者錯誤？","options":["(A) 突然停藥可能會加重absence seizure","(B) 可抑制丘腦皮質神經細胞之T-type calcium channels","(C) 合併使用valproate時，ethosuximide之療效會降低","(D) 最常見的副作用為胃腸不適"],"answer":2,"image":""},{"id":"md2-115-1-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"115年第1次第73題","year":115,"session":1,"number":73,"question":"下列治療阿茲海默症（Alzheimer disease）的藥物，何者的藥理作用機制與其他三個藥物不同？","options":["(A) memantine","(B) donepezil","(C) rivastigmine","(D) galantamine"],"answer":0,"image":""},{"id":"md2-115-1-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"115年第1次第74題","year":115,"session":1,"number":74,"question":"下列藥物中，何者可經由拮抗orexin受體產生安眠作用？","options":["(A) tasimelteon","(B) suvorexant","(C) midazolam","(D) buspirone"],"answer":1,"image":""},{"id":"md2-115-1-75","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第1次第75題","year":115,"session":1,"number":75,"question":"下列何種天然藥物因其具有提高T cell活性的免疫調節作用，可用於治療上呼吸道感染（upper respiratory infection）？","options":["(A) St. John's wort","(B) Echinacea","(C) Vinca alkaloids","(D) Ginkgo"],"answer":1,"image":""},{"id":"md2-115-1-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"115年第1次第76題","year":115,"session":1,"number":76,"question":"下列何種磷脂質於細胞凋亡後，會由細胞膜的內層翻轉出來到細胞膜的外層，被巨噬細胞識別以進行吞噬作用？","options":["(A) phosphatidylcholine","(B) phosphatidylserine","(C) sphingomyelin","(D) glycolipid"],"answer":1,"image":""},{"id":"md2-115-1-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"115年第1次第77題","year":115,"session":1,"number":77,"question":"下列那一路徑之活化，被認為是生理性肥大（physiologic hypertrophy）中最重要的機制？","options":["(A) PI3K/AKT路徑","(B) Bax/Bc1-2路徑","(C) EGFR/RAS/RAF路徑","(D) Wnt/β-catenin路徑"],"answer":0,"image":""},{"id":"md2-115-1-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"115年第1次第78題","year":115,"session":1,"number":78,"question":"有關病毒感染與疾病的關係，下列何者錯誤？","options":["(A) human papillomavirus與毛樣白斑病（hairy leukoplakia）","(B) human herpesvirus 8與原發性體液淋巴瘤（primary effusion lymphoma）","(C) Epstein-Barr virus與淋巴結外鼻腔型自然殺手／T細胞淋巴瘤（extranodal nasal type NK/T-cell lymphoma）","(D) JC polyomavirus與進行性多灶性白質腦病（progressive multifocal leukoencephalopathy）"],"answer":0,"image":""},{"id":"md2-115-1-79","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第1次第79題","year":115,"session":1,"number":79,"question":"腎臟移植後腎臟切片發現腎臟間質、腎小管上皮細胞間與血管內皮有淋巴細胞浸潤，有小血管壁出現壞死現象，未出現間質纖維化與腎小管萎縮，螢光染色未發現有抗體或C4d補體沉積。下列何者為最可能的診斷？","options":["(A) 慢性排斥（chronic rejection）","(B) 超急性排斥（hyperacute rejection）","(C) 急性細胞排斥（acute cellular rejection）","(D) 急性抗體媒介排斥（acute antibody-mediated rejection）"],"answer":2,"image":""},{"id":"md2-115-1-80","subject":"md2","topic":"病理-呼吸消化","meta":"115年第1次第80題","year":115,"session":1,"number":80,"question":"癩皮病（pellagra）最主要是缺乏何種營養因子所引起？","options":["(A) vitamin B1（thiamine）","(B) vitamin B2（riboflavin）","(C) niacin","(D) vitamin B6（pyridoxine）"],"answer":2,"image":""},{"id":"md2-115-1-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"115年第1次第81題","year":115,"session":1,"number":81,"question":"60歲男性突然發生心肌梗塞，於心肌梗塞發生後三小時死亡，解剖時肉眼檢查心臟最可能會看到什麼？","options":["(A) 看不出變化","(B) 梗塞區域的心肌較為暗紅色，質地較軟","(C) 梗塞區域呈現黃色，質地較軟","(D) 邊界清楚的凹陷區域，質地較硬"],"answer":0,"image":""},{"id":"md2-115-1-82","subject":"md2","topic":"病理-心血管血液","meta":"115年第1次第82題","year":115,"session":1,"number":82,"question":"下列造成水腫的原因中，何者的主要致病機轉與血中的滲透壓下降最無相關？","options":["(A) 肝硬化（liver cirrhosis）","(B) 腎病症候群（nephrotic syndrome）","(C) 營養不良（malnutrition）","(D) 鬱血性心衰竭（congestive heart failure）"],"answer":3,"image":""},{"id":"md2-115-1-83","subject":"md2","topic":"病理-心血管血液","meta":"115年第1次第83題","year":115,"session":1,"number":83,"question":"關於巨細胞動脈炎（giant cell arteritis）的臨床病理特徵，下列何者正確？","options":["(A) 主要影響頭部的血管","(B) 冠狀動脈（coronary artery）出現動脈瘤（aneurysm）是此疾病常見的併發症","(C) 嗜伊紅性白血球（eosinophil）出現在發炎的血管是此疾病的重要病理表現","(D) 此疾病多出現在35歲以前的年輕人，可能會造成視力減退"],"answer":0,"image":""},{"id":"md2-115-1-84","subject":"md2","topic":"病理-心血管血液","meta":"115年第1次第84題","year":115,"session":1,"number":84,"question":"在缺鐵性貧血（iron deficiency anemia）的病人，下列何者最可能高於正常值？","options":["(A) 血比容（hematocrit）","(B) 紅血球的平均血紅素濃度（mean cell hemoglobin concentration）","(C) 血漿的總鐵結合力（total iron-binding capacity）","(D) 血清中的鐵蛋白（ferritin）"],"answer":2,"image":""},{"id":"md2-115-1-85","subject":"md2","topic":"病理-免疫感染遺傳","meta":"115年第1次第85題","year":115,"session":1,"number":85,"question":"葡萄糖-6-磷酸鹽去氫酶（glucose-6-phosphate dehydrogenase, G6PD）缺乏症是何種遺傳？","options":["(A) 體染色體顯性（autosomal dominant）遺傳","(B) 體染色體隱性（autosomal recessive）遺傳","(C) 性聯顯性（X-linked dominant）遺傳","(D) 性聯隱性（X-linked recessive）遺傳"],"answer":3,"image":""},{"id":"md2-115-1-86","subject":"md2","topic":"病理-呼吸消化","meta":"115年第1次第86題","year":115,"session":1,"number":86,"question":"關於乳糜瀉（celiac disease），下列敘述何者最不適當？","options":["(A) 又稱麩質敏感腸病（gluten-sensitive enteropathy）","(B) 與HLA-DQ2或HLA-DQ8等位基因有關","(C) 組織病理學特徵包含上皮內淋巴球增多（intraepithelial lymphocytosis）","(D) 最常發生的惡性腫瘤是腸病相關B細胞淋巴瘤（enteropathy-associated B-cell lymphoma）"],"answer":3,"image":""},{"id":"md2-115-1-87","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"115年第1次第87題","year":115,"session":1,"number":87,"question":"高惡性度漿液性卵巢癌（high-grade ovarian serous carcinoma）最常突變的基因為：","options":["(A) TP53","(B) KRAS","(C) BRAF","(D) ESR1"],"answer":0,"image":""},{"id":"md2-115-1-88","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"115年第1次第88題","year":115,"session":1,"number":88,"question":"多重系統退化症（multiple system atrophy）患者中，下列何種細胞最易見到α-突觸核蛋白（α- synuclein）包涵體？","options":["(A) 星狀細胞（astrocyte）","(B) 寡樹突細胞（oligodendrocyte）","(C) 微膠細胞（microglia）","(D) 血管內皮細胞（endothelial cell）"],"answer":1,"image":""},{"id":"md2-115-1-89","subject":"md2","topic":"病理-免疫感染遺傳","meta":"115年第1次第89題","year":115,"session":1,"number":89,"question":"下列何者對於類風濕性關節炎（rheumatoid arthritis）發生機轉的重要性最為明確，且已有專一性拮抗劑用於治療？","options":["(A) rheumatoid factor","(B) IL-2","(C) IFN-α","(D) TNF"],"answer":3,"image":""},{"id":"md2-115-1-90","subject":"md2","topic":"病理-呼吸消化","meta":"115年第1次第90題","year":115,"session":1,"number":90,"question":"下列有關肺高壓（pulmonary hypertension）的敘述，何者錯誤？","options":["(A) 左心衰竭可造成肺高壓","(B) 間質性肺病（interstitial lung disease）可造成肺高壓","(C) 從主肺動脈到小動脈都會受影響而出現medial hypertrophy及intimal fibrosis","(D) 小動脈的plexiform lesion為肺高壓早期出現的病理特徵"],"answer":3,"image":""},{"id":"md2-115-1-91","subject":"md2","topic":"病理-呼吸消化","meta":"115年第1次第91題","year":115,"session":1,"number":91,"question":"下列有關細菌性肺炎的敘述，何者錯誤？","options":["(A) 可造成支氣管肺炎（bronchopneumonia）或大葉性肺炎（lobar pneumonia）","(B) 大葉性肺炎（lobar pneumonia）病理上變化依序可分為充血期（congestion）、灰色肝變期（gray hepatization）、紅色肝變期（red hepatization）、消解期（resolution）","(C) Streptococcus pneumoniae、Haemophilus influenzae、Moraxella catarrhalis、Staphylococcus aureus為常見造成社區型肺炎的致病菌","(D) Pseudomonas aeruginosa常見於院內感染肺炎"],"answer":1,"image":""},{"id":"md2-115-1-92","subject":"md2","topic":"病理-呼吸消化","meta":"115年第1次第92題","year":115,"session":1,"number":92,"question":"支氣管擴張症與下列何項症狀相關性較低？","options":["(A) 膿痰（mucopurulent sputum）","(B) 重度持續咳嗽（severe persistent cough）","(C) 咳血（hemoptysis）","(D) 過度換氣（hyperventilation）"],"answer":3,"image":""},{"id":"md2-115-1-93","subject":"md2","topic":"病理-呼吸消化","meta":"115年第1次第93題","year":115,"session":1,"number":93,"question":"關於自體免疫性肝炎（autoimmune hepatitis），下列敘述何者最不適當？","options":["(A) 與HLA等位基因DR3、DR4及DRB1密切相關","(B) 第1型自體免疫性肝炎的典型特徵是存在抗核抗體（ANA）和抗平滑肌肌動蛋白（SMA）抗體","(C) 第2型疾病的典型特徵是抗肝腎微粒體1（LKM-1）抗體","(D) 血清IgM升高為自體免疫性肝炎之典型表現"],"answer":3,"image":""},{"id":"md2-115-1-94","subject":"md2","topic":"病理-呼吸消化","meta":"115年第1次第94題","year":115,"session":1,"number":94,"question":"關於潰瘍性結腸炎（ulcerative colitis），下列敘述何者最不適當？","options":["(A) 發炎通常僅限於黏膜（mucosa）","(B) 大多會涉及結腸與迴腸（colon and ileum）兩者的嚴重慢性發炎","(C) 常有假性息肉（pseudopolyps）","(D) 可能會造成毒性巨結腸（toxic megacolon）"],"answer":1,"image":""},{"id":"md2-115-1-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第1次第95題","year":115,"session":1,"number":95,"question":"下列何者為不依賴ACTH（ACTH-independent）Cushing氏症候群（Cushing syndrome）最常見的原因？","options":["(A) small cell carcinoma of the lung","(B) adrenocortical adenoma","(C) adrenocortical carcinoma","(D) primary cortical hyperplasia"],"answer":1,"image":""},{"id":"md2-115-1-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第1次第96題","year":115,"session":1,"number":96,"question":"關於局部節段型腎絲球硬化症（focal segmental glomerulosclerosis, FSGS），下列敘述何者正確？","options":["(A) 該疾病為造成小孩（小於18歲）腎病症候群（nephrotic syndrome）最常見的原因","(B) 原發性FSGS腎絲球病變最先發生於近髓質（juxtamedullary）腎絲球","(C) 電子顯微鏡下的變化主要為大量免疫沉澱物堆積在膈細胞（mesangial cell）區域造成硬化","(D) 一般而言，以類固醇治療FSGS的效果極佳"],"answer":1,"image":""},{"id":"md2-115-1-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第1次第97題","year":115,"session":1,"number":97,"question":"橋本氏甲狀腺炎（Hashimoto thyroiditis）病患較常出現下列那些自體免疫抗體？","options":["(A) antithyroglobulin antibody和antithyroid peroxidase antibody","(B) antithyroglobulin antibody和anti-TSH receptor antibody","(C) antinuclear antibody和antithyroid peroxidase antibody","(D) antimitochondrial antibody和anti-TSH receptor antibody"],"answer":0,"image":""},{"id":"md2-115-1-98","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第1次第98題","year":115,"session":1,"number":98,"question":"與乳房乳突瘤（papilloma）的乳突比較，乳突狀原位癌（papillary ductal carcinoma in situ）其乳突的病理特徵中，最有鑑別力者為：","options":["(A) 無肌上皮細胞","(B) 缺乏纖維血管組織","(C) 有出血現象","(D) 有組織壞死"],"answer":0,"image":""},{"id":"md2-115-1-99","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第1次第99題","year":115,"session":1,"number":99,"question":"侵犯性乳癌，其腫瘤細胞之雌激素受體（estrogen receptor, ER），助孕素受體（progesterone receptor, PR），人類表皮生長因子受體2（HER2）表現，下列何種組合最為常見？","options":["(A) ER陽性，PR陽性，HER2陰性","(B) ER陰性，PR陰性，HER2陽性","(C) ER陽性，PR陽性，HER2陽性","(D) ER陰性，PR陰性，HER2陰性"],"answer":0,"image":""},{"id":"md2-115-1-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"115年第1次第100題","year":115,"session":1,"number":100,"question":"杜雷特氏出血（Duret hemorrhage）與下列何種腦部脫疝（herniation）最有關係？","options":["(A) 大腦鎌下脫出（subfalcine herniation）","(B) 扣帶脫出（cingulate herniation）","(C) 經小腦天幕脫出（transtentorial herniation）","(D) 小腦扁桃體脫出（tonsillar herniation）"],"answer":2,"image":""},{"id":"md2-115-2-1","subject":"md2","topic":"細菌學","meta":"115年第2次第1題","year":115,"session":2,"number":1,"question":"65歲罹患糖尿病的男性因長期咳嗽、體重減輕及夜間盜汗就醫。經胸部X光檢查發現雙側肺上葉有空洞性病變，痰液抹片檢查顯示抗酸性染色（acid-fast stain）為陽性。醫師進一步詢問病史，發現該患者年輕時曾與肺結核患者有密切接觸。下列何種免疫機制最可能使該患者在年輕時感染無明顯症狀，而經過多年後才發病？","options":["(A) 大型乾酪化肉芽腫（caseous granulomas）的形成因而抑制細菌的清除","(B) 結核分枝桿菌的抗原快速突變以逃脫免疫系統辨識","(C) 結核分枝桿菌誘導嗜中性白血球過度活化因而導致肺部組織損傷","(D) B淋巴球對結核分枝桿菌的抗原產生耐受性"],"answer":0,"image":""},{"id":"md2-115-2-2","subject":"md2","topic":"細菌學","meta":"115年第2次第2題","year":115,"session":2,"number":2,"question":"下列何種立克次體（Rickettsia）以人類為其主要的傳染窩（reservoir）？","options":["(A) Rickettsia akari","(B) Rickettsia rickettsii","(C) Rickettsia prowazekii","(D) Rickettsia typhi"],"answer":2,"image":""},{"id":"md2-115-2-3","subject":"md2","topic":"細菌學","meta":"115年第2次第3題","year":115,"session":2,"number":3,"question":"下列有關細菌染色體之敘述，何者最不適當？","options":["(A) 大多數的細菌具有環狀染色體","(B) 多數僅有一個複製起始點（oriC）","(C) 位於細胞質中且無核膜包覆","(D) 為雙倍體（diploid）並經半保留方式（semiconservative）進行複製"],"answer":3,"image":""},{"id":"md2-115-2-4","subject":"md2","topic":"病毒學","meta":"115年第2次第4題","year":115,"session":2,"number":4,"question":"關於病毒的致病機轉，下列何者錯誤？","options":["(A) 干擾素與細胞激素可能引起類流感症狀","(B) 大量抗原和抗體的存在可能形成免疫複合物，進而引發第三型過敏反應（type Ⅲ hypersensitivity）","(C) 伊波拉與登革病毒都可造成出血熱（hemorrhagic fever），主要機轉都是由病毒蛋白直接破壞細胞（cytopathic damage）而引起","(D) 在病毒感染的潛伏期（incubation period），病毒已開始複製，但尚未造成疾病"],"answer":2,"image":""},{"id":"md2-115-2-5","subject":"md2","topic":"真菌學","meta":"115年第2次第5題","year":115,"session":2,"number":5,"question":"有關新型隱球菌（Cryptococcus neoformans）之敘述，下列何者最適當？","options":["(A) 以頭孢菌素（cephalosporins）治療","(B) 主要造成尿道感染","(C) 主要由昆蟲媒介傳染","(D) 具多醣體莢膜（polysaccharide capsule）"],"answer":3,"image":""},{"id":"md2-115-2-6","subject":"md2","topic":"藥理-化學治療","meta":"115年第2次第6題","year":115,"session":2,"number":6,"question":"細菌的核糖體發生突變，下列那一種抗生素最不容易造成細菌產生抗藥性？","options":["(A) 康黴素（kanamycin）","(B) 阿奇黴素（azithromycin）","(C) 米諾四環素（minocycline）","(D) 左旋氧氟沙星（levofloxacin）"],"answer":3,"image":""},{"id":"md2-115-2-7","subject":"md2","topic":"藥理-化學治療","meta":"115年第2次第7題","year":115,"session":2,"number":7,"question":"細菌之青黴素結合蛋白質（penicillin-binding protein）超量表現或發生點突變時，最有可能使細菌對下列那一類抗生素出現抗藥性？","options":["(A) 頭孢子素類（cephalosporins）","(B) 大環內酯類（macrolides）","(C) 磺胺類（sulfonamides）","(D) 胺基醣苷類（aminoglycosides）"],"answer":0,"image":""},{"id":"md2-115-2-8","subject":"md2","topic":"免疫學","meta":"115年第2次第8題","year":115,"session":2,"number":8,"question":"破傷風免疫球蛋白（tetanus immunoglobulin）在臨床治療破傷風的最主要目的為何？","options":["(A) 刺激神經傳導物質的釋放","(B) 中和未結合的破傷風毒素","(C) 誘導長期免疫力","(D) 殺死破傷風梭菌"],"answer":1,"image":""},{"id":"md2-115-2-9","subject":"md2","topic":"細菌學","meta":"115年第2次第9題","year":115,"session":2,"number":9,"question":"下列關於梅毒檢驗之敘述，何者錯誤？","options":["(A) VDRL與RPR都屬於nontreponemal test，通常用於篩檢","(B) Nontreponemal test具有高敏感性的優點，但在下疳（chancre）時期常呈陰性","(C) 紅斑性狼瘡（systemic lupus erythematosus）患者nontreponemal test和treponemal test都可能出現偽陽性結果","(D) 血清treponemal test在治療後抗體轉陰（seroreversion）的比例較nontreponemal test高，適合做為疾病治療成效的指標"],"answer":3,"image":""},{"id":"md2-115-2-10","subject":"md2","topic":"藥理-化學治療","meta":"115年第2次第10題","year":115,"session":2,"number":10,"question":"金黃色葡萄球菌（Staphylococcus aureus）對萬古黴素（vancomycin）高度抗藥性的主要機制為何？","options":["(A) 獲得vanA操縱組（operon），產生對萬古黴素低親和力的細胞壁肽聚糖（peptidoglycan）末端D- alanine-D-lactate","(B) 利用外排泵（efflux pump）主動將萬古黴素自細菌細胞質排出","(C) 孔蛋白（porin）突變而減少萬古黴素進入細菌","(D) 產生萬古黴素水解酶分解萬古黴素"],"answer":0,"image":""},{"id":"md2-115-2-11","subject":"md2","topic":"細菌學","meta":"115年第2次第11題","year":115,"session":2,"number":11,"question":"關於肺炎黴漿菌（Mycoplasma pneumoniae）的敘述，下列何者最不適當？","options":["(A) 為可獨立生存（free-living）的細菌","(B) 為兼性厭氧菌（facultative anaerobe）","(C) 感染常見於學齡兒童及青年（young adult）","(D) 常見的感染症是氣管支氣管炎（tracheobronchitis）"],"answer":1,"image":""},{"id":"md2-115-2-12","subject":"md2","topic":"病毒學","meta":"115年第2次第12題","year":115,"session":2,"number":12,"question":"下列何者可以在人類造成癌症？①腺病毒（adenovirus） ②單純疱疹病毒（herpes simplex virus） ③ 人類疱疹病毒4型（human herpesvirus 4） ④人類疱疹病毒8型（human herpesvirus 8） ⑤痘病毒（poxviruses） ⑥人類嗜T淋巴細胞病毒1型（human T-lymphotropic virus 1）","options":["(A) ①③⑥","(B) ②④⑤","(C) ③④⑥","(D) ①④⑤"],"answer":2,"image":""},{"id":"md2-115-2-13","subject":"md2","topic":"病毒學","meta":"115年第2次第13題","year":115,"session":2,"number":13,"question":"下列對肝炎病毒之敘述，何者最適當？","options":["(A) B型肝炎病毒容易透過口糞傳染，主要來自受污染之海鮮食品","(B) C型肝炎基因體與茲卡病毒（Zika virus）屬同一病毒家族","(C) D型肝炎病毒需要與E型肝炎病毒在共同感染下誘發猛爆性肝炎","(D) A型肝炎病毒感染容易誘發孕婦死亡"],"answer":1,"image":""},{"id":"md2-115-2-14","subject":"md2","topic":"病毒學","meta":"115年第2次第14題","year":115,"session":2,"number":14,"question":"下列何組病毒屬於相同病毒科（family）？","options":["(A) A型肝炎病毒（hepatitis A virus）、B型肝炎病毒（hepatitis B virus）","(B) C型肝炎病毒（hepatitis C virus）、登革病毒（dengue virus）","(C) 單純疱疹病毒（herpes simplex virus）、猴痘病毒（monkeypox virus）","(D) 呼吸道融合病毒（respiratory syncytial virus）、A型流感病毒（influenza A virus）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第14題一律給分 (原公告答案 B)"},{"id":"md2-115-2-15","subject":"md2","topic":"病毒學","meta":"115年第2次第15題","year":115,"session":2,"number":15,"question":"下列關於病毒構造的敘述，何者錯誤？","options":["(A) 腸病毒（enterovirus）由殼體（capsid）包覆，因此酒精對其殺滅效果不佳","(B) 杯狀病毒科（caliciviridae）之基因組為雙股線性DNA（double-stranded linear DNA）","(C) 病毒套膜（envelope）的組成包含脂質、蛋白質、醣蛋白","(D) 彈狀病毒科（rhabdoviridae）之基因組為負股RNA（negative-sense RNA）"],"answer":1,"image":""},{"id":"md2-115-2-16","subject":"md2","topic":"病毒學","meta":"115年第2次第16題","year":115,"session":2,"number":16,"question":"下列有關病毒致病性的敘述，何者最適當？","options":["(A) 病毒之潛伏性感染（latent infection）造成細胞之衰老（senescence）","(B) 病毒流產性的感染（abortive infection）會造成細胞的死亡","(C) 病毒感染，被轉型（transformation）的細胞即成為永生（immortalization）細胞","(D) 只有DNA病毒才有可能將被感染的細胞轉型"],"answer":2,"image":""},{"id":"md2-115-2-17","subject":"md2","topic":"真菌學","meta":"115年第2次第17題","year":115,"session":2,"number":17,"question":"Malassezia furfur是造成變色糠疹（pityriasis versicolor）的致病菌，若要進行培養，最適合在培養基中加入何種成分以利生長？","options":["(A) olive oil","(B) thiamine","(C) nicotinic acid","(D) inositol"],"answer":0,"image":""},{"id":"md2-115-2-18","subject":"md2","topic":"免疫學","meta":"115年第2次第18題","year":115,"session":2,"number":18,"question":"有關先天性免疫（innate immunity）反應，下列敘述何者最不適當？","options":["(A) 先天性免疫反應可利用吞噬細胞及補體來攻擊病原菌","(B) 辨識病原菌的先天性免疫受體分子的基因不會重組","(C) 先天性免疫反應在感染處常可因產生細胞激素引起發炎反應","(D) 先天性免疫反應具有抗原特異性的免疫記憶"],"answer":3,"image":""},{"id":"md2-115-2-19","subject":"md2","topic":"免疫學","meta":"115年第2次第19題","year":115,"session":2,"number":19,"question":"關於major histocompatibility complex（MHC，包括class I與class II），下列敘述何者最適當？","options":["(A) 它們都是由單一基因（monogeny）構成","(B) 具有三種主要的MHC class I基因","(C) 具有allelic exclusion的特點","(D) IL-5可以促進MHC class II表現在抗原呈獻細胞表面上"],"answer":1,"image":""},{"id":"md2-115-2-20","subject":"md2","topic":"免疫學","meta":"115年第2次第20題","year":115,"session":2,"number":20,"question":"過量表現細胞激素BAFF的個體，發生自體免疫疾病Sjögren's syndrome（又名乾燥症）的機率會上升，乾燥症以破壞人體外分泌腺體，如淚腺及唾液腺的症狀最顯著。檢查BAFF過量之乾燥症患者的免疫系統及血液，預期最可能發現下列何種異狀？","options":["(A) 骨髓內發育中的pre-B細胞增加","(B) 從骨髓製造出來的immature B細胞增加","(C) 血液中自體反應性（autoreactive）的成熟B細胞增加","(D) 血液中自體反應性（autoreactive）的成熟T細胞增加"],"answer":2,"image":""},{"id":"md2-115-2-21","subject":"md2","topic":"免疫學","meta":"115年第2次第21題","year":115,"session":2,"number":21,"question":"有關T細胞次群生成及其轉錄因子的配對，下列何者最適當？","options":["(A) TH1：Tbet","(B) TH2：RORγt","(C) TFH：GATA3","(D) Treg：Bcl-6"],"answer":0,"image":""},{"id":"md2-115-2-22","subject":"md2","topic":"免疫學","meta":"115年第2次第22題","year":115,"session":2,"number":22,"question":"A型肝炎病毒藉由糞口傳染途徑，造成病人急性肝炎症狀。檢測病人血液中專一性對抗A型肝炎病毒的抗體，當發現下列何種類型的抗體濃度最高，最可能顯示該病人剛遭受該病毒感染？","options":["(A) IgA","(B) IgE","(C) IgG","(D) IgM"],"answer":3,"image":""},{"id":"md2-115-2-23","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第2次第23題","year":115,"session":2,"number":23,"question":"生物製劑（Biologics）已成為治療類風濕性關節炎的主要藥物，下列何種治療類風濕性關節炎的生物製劑是屬於融合蛋白型式？","options":["(A) Infliximab","(B) Abatacept","(C) Tocilizumab","(D) Omalizumab"],"answer":1,"image":""},{"id":"md2-115-2-24","subject":"md2","topic":"免疫學","meta":"115年第2次第24題","year":115,"session":2,"number":24,"question":"不同類型的抗體具有不同的功能，而這些抗體是經由抗體類型轉換（isotype switch）的機制產生，下列敘述何者最不適當？","options":["(A) 活化的B細胞在生發中心（germinal center）進行抗體類型轉換，而且這個過程需要AID（activation- induced cytidine deaminase）酵素的參與進行DNA重組","(B) 施打疫苗的目的除了增加抗體的質和量外，也促進抗體從IgM轉換到IgG及其他的抗體類型，提升免疫力","(C) 活化的B細胞在進行抗體類型轉換的過程會受到細胞激素的影響，比如IFN-γ會促進IgG3及IgG2a的轉換，而IL-4則是促進IgG1及IgA的轉換","(D) B細胞和輔助型T細胞的交互作用對於抗體類型轉換的發生十分重要，如果CD40L或是CD40的缺失會造成B細胞和T細胞無法交互作用而引起IgM過多症候群（hyper IgM syndrome）"],"answer":2,"image":""},{"id":"md2-115-2-25","subject":"md2","topic":"免疫學","meta":"115年第2次第25題","year":115,"session":2,"number":25,"question":"下列何者不屬於mucosa-associated lymphoid tissue（MALT）？","options":["(A) gut-associated lymphoid tissue（GALT）","(B) nasal-associated lymphoid tissue（NALT）","(C) bronchus-associated lymphoid tissue（BALT）","(D) oral-associated lymphoid tissue（OALT）"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第25題一律給分 (原公告答案 D)"},{"id":"md2-115-2-26","subject":"md2","topic":"免疫學","meta":"115年第2次第26題","year":115,"session":2,"number":26,"question":"大明去爬山，一時興起用手去觸摸路旁植物的葉子，第2天之後，發現手背很癢，並開始出現一些水泡與紅腫現象，醫師診斷出是過敏反應，下列何者是最適當的敘述？","options":["(A) 屬於第三型過敏反應","(B) 過度活化之TH1與CD8 T細胞所致","(C) IL-4與IL-5這兩種細胞激素被大量分泌","(D) 葉片上油脂物質即為抗原，直接活化體內免疫反應所致"],"answer":1,"image":""},{"id":"md2-115-2-27","subject":"md2","topic":"免疫學","meta":"115年第2次第27題","year":115,"session":2,"number":27,"question":"自主性免疫調節因子（AIRE）是一種轉錄調節因子，它能夠促進胸腺基質細胞表達某些「組織特異性」蛋白質。在T細胞的發育過程中，這個機制提供了T細胞對這些組織特異自體抗原建立中樞免疫耐受性。在AIRE中發生缺失突變的病患（一種稱為APECED的疾病）會出現一系列症狀，其中一些涉及到自體免疫攻擊分泌腺體。從這樣的分析觀察中，下列敘述何者最適當？","options":["(A) AIRE所調控的基因表現，對於中樞免疫耐受性移除對某些組織產生反應的自體免疫T細胞上至關重要","(B) 受到自體免疫攻擊的分泌腺體肇因於由AIRE所調控的高量自體抗原表現","(C) AIRE的表現抑制T細胞的發育","(D) AIRE過度表現時直接造成T細胞的活化，因此引發自體免疫的症狀"],"answer":0,"image":""},{"id":"md2-115-2-28","subject":"md2","topic":"免疫學","meta":"115年第2次第28題","year":115,"session":2,"number":28,"question":"有關毒殺T細胞抗原4（CTLA-4）之作用，下列敘述何者最不適當？","options":["(A) 與CD28競爭相同的配體（ligand）","(B) 可以傳遞共同刺激訊息（co-stimulatory signals）到細胞內","(C) 可與CD80結合","(D) 可與CD86結合"],"answer":1,"image":""},{"id":"md2-115-2-29","subject":"md2","topic":"寄生蟲學","meta":"115年第2次第29題","year":115,"session":2,"number":29,"question":"赤腳踏在泥土田埂上享受稻香的芬芳，最容易被下列何種寄生蟲的絲狀（filarial form）幼蟲經皮膚鑽入造成感染？","options":["(A) 十二指腸鉤蟲（Ancylostoma duodenale）","(B) 犬蛔蟲（Toxocara canis）","(C) 肝毛線蟲（Capillaria hepatica）","(D) 有棘頜口線蟲（Gnathostoma spinigerum）"],"answer":0,"image":""},{"id":"md2-115-2-30","subject":"md2","topic":"寄生蟲學","meta":"115年第2次第30題","year":115,"session":2,"number":30,"question":"下列何種寄生蟲曾在臺灣東部、南部造成地方性流行，可能侵犯患者眼睛導致病變？","options":["(A) 廣東住血線蟲（Angiostrongylus cantonensis）","(B) 旋毛蟲（Trichinella spiralis）","(C) 犬鉤蟲（Ancylostoma caninum）","(D) 蟠尾絲蟲（Onchocerca volvulus）"],"answer":0,"image":""},{"id":"md2-115-2-31","subject":"md2","topic":"寄生蟲學","meta":"115年第2次第31題","year":115,"session":2,"number":31,"question":"陳先生接受民俗療法以搗碎蛙肉塗敷眼睛周圍，藉以消腫，經數週後眼睛周圍呈現水腫及局部發炎症狀，據此病史最可能為下列何種寄生蟲感染？","options":["(A) 短小包膜絛蟲（Hymenolepis nana）","(B) 縮小包膜絛蟲（Hymenolepis diminuta）","(C) 曼森裂頭絛蟲（Spirometra mansonoides）","(D) 顆粒性包生絛蟲（Echinococcus granulosus）"],"answer":2,"image":""},{"id":"md2-115-2-32","subject":"md2","topic":"寄生蟲學","meta":"115年第2次第32題","year":115,"session":2,"number":32,"question":"李小姐於赴日本旅遊期間曾多次生食鮭魚，返國後因腹瀉及腹部疼痛而就醫，臨床檢驗呈現嗜伊紅性白血球增多症（eosinophilia），但無貧血病徵，經寄生蟲學專家進行糞便鏡檢而確診，據此病史最可能感染下列何種寄生蟲？","options":["(A) 中華肝吸蟲（Clonorchis sinensis）","(B) 衛氏肺吸蟲（Paragonimus westermani）","(C) 橫川氏吸蟲（Metagonimus yokogawai）","(D) 異形異形吸蟲（Heterophyes heterophyes）"],"answer":2,"image":""},{"id":"md2-115-2-33","subject":"md2","topic":"寄生蟲學","meta":"115年第2次第33題","year":115,"session":2,"number":33,"question":"有關痢疾阿米巴（Entamoeba histolytica）的診斷，下列何者錯誤？","options":["(A) 針對肝膿瘍患者可選擇使用已商品化之ELISA抗體診斷試劑組合","(B) 於急性下痢患者的糞便中主要發現具有感染性的囊體（cysts）","(C) 利用PCR技術可鑑別該寄生蟲及迪斯帕阿米巴（E. dispar）","(D) 可於患者肛門潰瘍周圍組織切片發現活動體（trophozoites）"],"answer":1,"image":""},{"id":"md2-115-2-34","subject":"md2","topic":"寄生蟲學","meta":"115年第2次第34題","year":115,"session":2,"number":34,"question":"有關非洲錐蟲（African trypanosomes）的敘述，下列何者最為適當？","options":["(A) 有關布氏羅德西亞錐蟲（Trypanosoma brucei rhodesiense）的毒力（virulence）決定於寄生蟲與受感染人類的基因型（genotype）之交互作用","(B) 受感染者會在頸部與鼠蹊部位出現淋巴結的水腫，臨床稱為Jericho boil","(C) 當錐蟲被病媒（vector）攝入後，蟲體細胞膜上的前環素蛋白（procyclin）會被變異表面醣蛋白（variant surface glycoprotein）所取代，以逃避宿主的免疫攻擊","(D) 在許多人類罹患非洲錐蟲症的案例中，蟲體入侵神經系統大多發生在感染初期，因此導致昏睡症（sleeping sickness）"],"answer":0,"image":""},{"id":"md2-115-2-35","subject":"md2","topic":"細菌學","meta":"115年第2次第35題","year":115,"session":2,"number":35,"question":"上週隔壁老王去蘭嶼旅遊回來後，生了一場大病，醫師懷疑是蟎（mite）叮咬而致病，他最可能罹患下列何種疾病？","options":["(A) 犬心絲蟲症（dirofilariasis）","(B) 瘧疾（malaria）","(C) 黃熱病（yellow fever）","(D) 恙蟲病（scrub typhus）"],"answer":3,"image":""},{"id":"md2-115-2-36","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第2次第36題","year":115,"session":2,"number":36,"question":"兩個獨立樣本之樣本數分別為19與27，變異數（variance）分別為1.5與1.7。若此二獨立樣本之母體的變異數相等，則母體變異數的估計值最接近下列何者？","options":["(A) 1.6","(B) 2.0","(C) 2.6","(D) 2.7"],"answer":0,"image":""},{"id":"md2-115-2-37","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第2次第37題","year":115,"session":2,"number":37,"question":"依據我國111年死亡統計結果，惡性腫瘤、心臟疾病與嚴重特殊傳染性肺炎（COVID-19）居主要死因前三位，嚴重特殊傳染性肺炎（COVID-19）由110年19名往前至第3名。111年死亡人數計20萬8,438人，較110年增加2萬4,266人；死亡率為每十萬人口893.8人，增加13.9％；以WHO 2000年世界人口結構調整後之標準化死亡率為每十萬人口443.9人，增加9.5％。增加原因在於老年人口增加以及新進入之死因影響。下列何者錯誤？","options":["(A) 111年度總死亡率為該年度死亡人數除以年初人口數","(B) 標準化死亡率是指以特定的人口結構以及各年齡層死亡率來計算調整後死亡率","(C) 111年度死亡率較110年度增加的原因主要受COVID-19疫情及人口老化影響","(D) 疾病別死亡率是指該年度死於特定疾病別的死亡率"],"answer":0,"image":""},{"id":"md2-115-2-38","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第2次第38題","year":115,"session":2,"number":38,"question":"臨床試驗中，實施盲性程序（blinding or masking）是一項重要的執行技巧，藥廠規劃盲性之主要目的為何？","options":["(A) 去除介入組和對照組執行上的系統性偏差，以保證兩組的執行程序可比","(B) 去除介入組的霍桑效應（Hawthorne effect）","(C) 針對試驗醫師及護理師實施盲性，稱為雙盲（double blinding）","(D) 盲性能保證介入組和對照組在基線背景特性上的可比性"],"answer":0,"image":""},{"id":"md2-115-2-39","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第2次第39題","year":115,"session":2,"number":39,"question":"收集800位胃食道逆流症病人資料，調查其胃食道逆流症類型（分為A、B、C三類型）與肥胖狀態（分為非肥胖、肥胖），利用此資料欲分析胃食道逆流症類型與肥胖之關係，採用下列何者統計方法分析最適當？","options":["(A) 變異數分析（Analysis of Variance, ANOVA）","(B) 對數等級檢定（Log rank test）","(C) 卡方檢定（Chi-square test）","(D) 雙樣本t檢定（Two-sample t-test）"],"answer":2,"image":""},{"id":"md2-115-2-40","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"115年第2次第40題","year":115,"session":2,"number":40,"question":"氣候變遷下各氣象因子變化會影響空氣污染物生成與轉化，其中若因雲層量減少及紫外線入射量增加，會加速光化作用產生下列何種污染物？","options":["(A) 臭氧","(B) 一氧化碳","(C) 全氟碳化物","(D) 氫氟碳化物"],"answer":0,"image":""},{"id":"md2-115-2-41","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"115年第2次第41題","year":115,"session":2,"number":41,"question":"環境毒理學中，四氯化碳是最典型的直接性肝毒性物質，下列敘述何者最不適當？","options":["(A) 可造成肝臟化學性傷害的環境毒物","(B) 主要由受暴露者的特異體質而引起","(C) 屬於內因性（intrinsic）的毒性物質","(D) 對人類或動物產生的肝臟傷害，型態類似"],"answer":1,"image":""},{"id":"md2-115-2-42","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"115年第2次第42題","year":115,"session":2,"number":42,"question":"「職業病」的定義有很多種，根據世界衛生組織（World Health Organization, WHO）的標準，下列敘述何者最不適當？","options":["(A) 在工作環境中有一個以上的人有相同症狀者（cases clustering）","(B) 職業為致病因子中具有因果關係者（one of the causal factors）","(C) 職業為致病因素中的貢獻因子（a contributing factor in complex situations）","(D) 職業為既有疾病之加重因素者（may aggravate pre-existing disease）"],"answer":0,"image":""},{"id":"md2-115-2-43","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"115年第2次第43題","year":115,"session":2,"number":43,"question":"關於環境毒性化學物質的敘述，下列何者最不適當？6+3+","options":["(A) Cr的毒性通常較Cr強","(B) 三氯乙烯廣泛用於乾洗劑","(C) 四氯化碳具有肝臟毒性","(D) 甲苯的分子量較苯為大，所以毒性也比苯更強"],"answer":3,"image":""},{"id":"md2-115-2-44","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"115年第2次第44題","year":115,"session":2,"number":44,"question":"社會學家高夫曼（Goffman）1963年提出「污名化（stigma）」的概念，指它是一種不被社會完全接受的個人情境，並區分了三種污名化的情形，包括身體的、人格的以及種族國家的等。下列有關污名化的敘述，何者最不適當？","options":["(A) 對精神病患者的污名是屬於一種人格的污名","(B) 以「東亞病夫」稱呼中國人，是一種身體的污名","(C) 受污名化的人常需要隱藏或掩飾自己","(D) 受社會污名的人在適應過程中，可能會回過頭來影響自己而致自我污名"],"answer":1,"image":""},{"id":"md2-115-2-45","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第2次第45題","year":115,"session":2,"number":45,"question":"「計畫行為理論」定義行為時，考量行為的相容性原則（the principle of compatibility），行為須包含下述那些一致性的特質？","options":["(A) 決控、社會關係及場域的一致","(B) 行動、他人態度及時間的一致","(C) 目標、發生場域及時間的一致","(D) 目標、行動及社會關係的一致"],"answer":2,"image":""},{"id":"md2-115-2-46","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"115年第2次第46題","year":115,"session":2,"number":46,"question":"提供65歲以上年長者公費肺炎鏈球菌疫苗注射，屬於公共衛生三段五級預防策略中那一級？","options":["(A) 第一級預防策略","(B) 第二級預防策略","(C) 第三級預防策略","(D) 第四級預防策略"],"answer":1,"image":""},{"id":"md2-115-2-47","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第2次第47題","year":115,"session":2,"number":47,"question":"下列有關健康促進與衛生教育介入方案「評價（evaluation）」的敘述，何者最不適當？","options":["(A) 進行評價工作，需要與計畫的目標呼應，其結果有助於瞭解計畫的效用（effectiveness）、效率（efficiency）與功效（efficacy）","(B) 依據PRECEDE-PROCEED模式，評價可以分為過程評價（process evaluation）、衝擊評價（impact evaluation）及結果評價（outcome evaluation）","(C) 總結性評價（summative evaluation）是從計畫擬定、發展一直到計畫執行結束所進行的一系列監測","(D) 相較於結果評價（outcome evaluation），衝擊評價（impact evaluation）所需要的時間較短，可以觀察到計畫的立即效果，如認知或信念的改變"],"answer":2,"image":""},{"id":"md2-115-2-48","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"115年第2次第48題","year":115,"session":2,"number":48,"question":"關於物質使用疾患的敘述，下列何者最不適當？","options":["(A) 物質使用疾患的自然史通常是：接觸藥物或暴露之機會→開始使用→持續使用→正增強或避免負向效果→成癮、濫用","(B) 在物質使用疾患的發展過程中，個體可能從暴露機會到成癮濫用的任一個階段發生物質使用傷害","(C) 物質使用相關疾患的發展往往需要多次的物質使用，才會造成濫用或依賴","(D) 根據物質使用的入門理論（gateway theory），海洛因經常是第一個被嘗試的藥物"],"answer":3,"image":""},{"id":"md2-115-2-49","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"115年第2次第49題","year":115,"session":2,"number":49,"question":"我國健保在門急診和住院所採用的部分負擔類型，不含下列何者？","options":["(A) 定額部分負擔","(B) 定率部分負擔","(C) 部分負擔上限","(D) 自負額制"],"answer":3,"image":""},{"id":"md2-115-2-50","subject":"md2","topic":"公衛-衛生行政法規倫理","meta":"115年第2次第50題","year":115,"session":2,"number":50,"question":"當代健康正義議題的三大類主流理論聚焦於正義的分配原則，下列何者不屬於正義三大理論？","options":["(A) 功利主義","(B) 平等主義","(C) 原則主義","(D) 社群主義"],"answer":2,"image":""},{"id":"md2-115-2-51","subject":"md2","topic":"藥理-總論與自主神經","meta":"115年第2次第51題","year":115,"session":2,"number":51,"question":"關於嬰兒與年輕成人的藥物動力學反應差異，下列敘述何者錯誤？","options":["(A) 身體組織的水分組成比例嬰兒較成人高","(B) 脂溶性藥物在脂肪組織之分布嬰兒較成人高","(C) 嬰兒肝臟代謝藥物之能力較成人低","(D) 嬰兒腎臟排除藥物之能力較成人低"],"answer":1,"image":""},{"id":"md2-115-2-52","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第2次第52題","year":115,"session":2,"number":52,"question":"下列何者是降血糖藥物sulfonylureas於胰臟β細胞膜上的作用標的？","options":["(A) potassium channel","(B) calcium channel","(C) glucose transporter 2","(D) sodium-glucose co-transporter 2"],"answer":0,"image":""},{"id":"md2-115-2-53","subject":"md2","topic":"藥理-總論與自主神經","meta":"115年第2次第53題","year":115,"session":2,"number":53,"question":"下列關於pilocarpine的敘述，何者最不適當？","options":["(A) 口服使用易產生腹瀉的副作用","(B) 可刺激睫狀體（ciliary body）收縮，幫助房水（aqueous humor）排出，因此可用於治療青光眼（glaucoma）","(C) 可刺激唾液分泌，可用於緩解Sjögren syndrome病患的症狀","(D) 口服可治療膀胱過動症"],"answer":3,"image":""},{"id":"md2-115-2-54","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"115年第2次第54題","year":115,"session":2,"number":54,"question":"下列有關骨骼肌鬆弛劑作用機轉之敘述，何者錯誤？","options":["(A) diazepam活化中樞神經之GABAA receptor","(B) baclofen活化中樞神經之GABAB receptor","(C) tizanidine拮抗中樞神經之α2-adrenoceptor","(D) dantrolene抑制骨骼肌細胞內之ryanodine receptor channel"],"answer":2,"image":""},{"id":"md2-115-2-55","subject":"md2","topic":"藥理-化學治療","meta":"115年第2次第55題","year":115,"session":2,"number":55,"question":"Ampicillin常與下列何種藥物併用，用以治療對β-lactamase有抗藥性的金黃色葡萄球菌（S. aureus）感染？","options":["(A) amoxicillin","(B) penicillin G","(C) cephalexin","(D) clavulanic acid"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第55題一律給分 (原公告答案 D)"},{"id":"md2-115-2-56","subject":"md2","topic":"藥理-化學治療","meta":"115年第2次第56題","year":115,"session":2,"number":56,"question":"下列關於治療乳癌第二期或第三期病患之敘述，何者錯誤？","options":["(A) 術後之停經婦女可以先使用tamoxifen，之後接續以anastrozole治療","(B) cyclophosphamide、methotrexate、fluorouracil可做為輔助性化療（adjuvant chemotherapy）","(C) 在癌組織過度表現HER-2情況下，trastuzumab可增加anthracycline及taxane輔助性化療效益","(D) letrozole及anastrozole皆能輔助治療缺乏雌激素受體及黃體素受體表現的癌組織"],"answer":3,"image":""},{"id":"md2-115-2-57","subject":"md2","topic":"藥理-化學治療","meta":"115年第2次第57題","year":115,"session":2,"number":57,"question":"下列關於惡性瘧原蟲（P. falciparum）用藥之敘述，何者錯誤？","options":["(A) chloroquine不宜用於乾癬症病患","(B) chloroquine避免與含鈣及鎂制酸劑同時服用","(C) 對chloroquine產生抗藥性之惡性瘧原蟲，可用mefloquine治療","(D) 對於已經投與mefloquine治療原蟲者，可併用quinine加強治療效益"],"answer":3,"image":""},{"id":"md2-115-2-58","subject":"md2","topic":"藥理-化學治療","meta":"115年第2次第58題","year":115,"session":2,"number":58,"question":"下列何者不是抗癌藥物vincristine之副作用？","options":["(A) 姿勢性低血壓","(B) 腹瀉","(C) 周邊神經毒性","(D) 抗利尿激素分泌不當症候群（SIADH）"],"answer":1,"image":""},{"id":"md2-115-2-59","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"115年第2次第59題","year":115,"session":2,"number":59,"question":"下列藥物中，何者為ADP P2Y12 receptor拮抗劑，可抑制血小板凝集活性？","options":["(A) abciximab","(B) alteplase","(C) dipyridamole","(D) ticagrelor"],"answer":3,"image":""},{"id":"md2-115-2-60","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"115年第2次第60題","year":115,"session":2,"number":60,"question":"下列何種藥物引發出血問題時，最適合使用andexanet alfa反轉（reversal）其抗凝血作用？","options":["(A) apixaban","(B) dabigatran","(C) heparin","(D) warfarin"],"answer":0,"image":""},{"id":"md2-115-2-61","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第2次第61題","year":115,"session":2,"number":61,"question":"下列治療多發性硬化症（multiple sclerosis）藥物中，何者之主要作用機制為調節細胞上的鞘胺酸1–磷酸鹽（sphingosine 1-phosphate）受體，以阻斷淋巴球由淋巴結滲出，並減低淋巴球細胞在中樞神經系統之數量？","options":["(A) interferon beta","(B) glatiramer acetate","(C) natalizumab","(D) fingolimod hydrochloride"],"answer":3,"image":""},{"id":"md2-115-2-62","subject":"md2","topic":"藥理-化學治療","meta":"115年第2次第62題","year":115,"session":2,"number":62,"question":"下列何者為芳香環酶抑制劑（aromatase inhibitor），可減少雌激素生成，常用於治療乳癌？","options":["(A) letrozole","(B) fulvestrant","(C) toremifene","(D) clomiphene"],"answer":0,"image":""},{"id":"md2-115-2-63","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第2次第63題","year":115,"session":2,"number":63,"question":"下列何種藥物不適合用於治療甲狀腺風暴（thyroid storm）？","options":["(A) propranolol","(B) propylthiouracil","(C) levothyroxine","(D) potassium iodide"],"answer":2,"image":""},{"id":"md2-115-2-64","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"115年第2次第64題","year":115,"session":2,"number":64,"question":"下列關於chlorothiazide的敘述，何者錯誤？","options":["(A) 主要作用部位在近端腎小管 +–","(B) 可抑制Na/Cl共同運送系統","(C) 可增加鈣離子再吸收","(D) 具有碳酸酐酶的抑制作用"],"answer":0,"image":""},{"id":"md2-115-2-65","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"115年第2次第65題","year":115,"session":2,"number":65,"question":"下列治療高血壓藥物中，何者的作用機制為抑制血管收縮素轉化酶（angiotensin-converting enzyme）？","options":["(A) candesartan","(B) enalapril","(C) hydralazine","(D) minoxidil"],"answer":1,"image":""},{"id":"md2-115-2-66","subject":"md2","topic":"藥理-心血管腎臟血液","meta":"115年第2次第66題","year":115,"session":2,"number":66,"question":"下列有關強心劑digitalis的敘述，何者錯誤？","options":["(A) 除心律不整的副作用外，也會產生噁心、嘔吐、腹瀉等問題","(B) 可能引發動作電位出現early after-depolarizations","(C) 治療指數（therapeutic index）小","(D) 與loop diuretics合用時，易產生心臟毒性"],"answer":1,"image":""},{"id":"md2-115-2-67","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第2次第67題","year":115,"session":2,"number":67,"question":"活化下列何種受體（receptor）能夠最有效地幫助支氣管擴張？","options":["(A) α1 adrenergic receptor","(B) β2 adrenergic receptor","(C) M3 cholinergic receptor","(D) serotonin 5-HT3 receptor"],"answer":1,"image":""},{"id":"md2-115-2-68","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第2次第68題","year":115,"session":2,"number":68,"question":"下列藥物中，何者屬於methylxanthines，能導致氣管平滑肌舒張，但不會拮抗adenosine之作用？","options":["(A) tiotropium","(B) enprofylline","(C) theophylline","(D) cromolyn"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第68題一律給分 (原公告答案 B)"},{"id":"md2-115-2-69","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第2次第69題","year":115,"session":2,"number":69,"question":"病人做大腸內視鏡檢查前，下列何種藥物最常配合polyethylene glycol，用來清理大腸？","options":["(A) bisacodyl","(B) erythromycin","(C) lubiprostone","(D) octreotide"],"answer":0,"image":""},{"id":"md2-115-2-70","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第2次第70題","year":115,"session":2,"number":70,"question":"下列藥物中，何者可將尿酸（uric acid）轉變成allantoin而排出，用於治療痛風？","options":["(A) probenecid","(B) pegloticase","(C) sulfinpyrazone","(D) febuxostat"],"answer":1,"image":""},{"id":"md2-115-2-71","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第2次第71題","year":115,"session":2,"number":71,"question":"下列藥物中，何者是第二代bradykinin B2 receptor拮抗劑，具有治療遺傳血管性水腫（hereditary angioedema）的作用？","options":["(A) aliskiren","(B) captopril","(C) icatibant","(D) aprotinin"],"answer":2,"image":""},{"id":"md2-115-2-72","subject":"md2","topic":"藥理-內分泌腸胃呼吸發炎","meta":"115年第2次第72題","year":115,"session":2,"number":72,"question":"下列何種藥物，若用於治療小孩因病毒感染所引起的發燒，最容易產生Reye syndrome？","options":["(A) acetaminophen","(B) ibuprofen","(C) celecoxib","(D) aspirin"],"answer":3,"image":""},{"id":"md2-115-2-73","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"115年第2次第73題","year":115,"session":2,"number":73,"question":"下列關於benzodiazepines之敘述，何者錯誤？","options":["(A) 作用在type A GABA受體上","(B) 與GABA受體之結合位點是在α subunit和β subunit之間","(C) 於GABA不存在的情況下，無法直接開啟GABA受體","(D) flurazepam的血中半衰期比alprazolam長"],"answer":1,"image":""},{"id":"md2-115-2-74","subject":"md2","topic":"藥理-中樞神經與麻醉","meta":"115年第2次第74題","year":115,"session":2,"number":74,"question":"下列何種藥物成癮的風險性（risk of addiction）最低？","options":["(A) ketamine","(B) cannabinoids","(C) alcohol","(D) nicotine"],"answer":0,"image":""},{"id":"md2-115-2-75","subject":"md2","topic":"公衛-環境職業預防醫學","meta":"115年第2次第75題","year":115,"session":2,"number":75,"question":"下列何種重金屬中毒時，會導致顫抖、牙齦口炎、肢痛病、周邊神經病變，甚至肺炎？","options":["(A) 無機鉛","(B) 有機鉛","(C) 汞元素","(D) 無機砷鹽"],"answer":2,"image":""},{"id":"md2-115-2-76","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"115年第2次第76題","year":115,"session":2,"number":76,"question":"下列何種細胞適應（cell adaptation）與細胞的惡性變化（malignant transformation）之相關性最密切？","options":["(A) hypertrophy","(B) aplasia","(C) metaplasia","(D) atrophy"],"answer":2,"image":""},{"id":"md2-115-2-77","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"115年第2次第77題","year":115,"session":2,"number":77,"question":"下列何種類型的癌，於顯微鏡檢下較容易看到砂粒體（psammoma body）？","options":["(A) papillary carcinoma of thyroid","(B) ductal carcinoma of breast","(C) acinar cell carcinoma of pancreas","(D) mucinous carcinoma of colon"],"answer":0,"image":""},{"id":"md2-115-2-78","subject":"md2","topic":"病理-免疫感染遺傳","meta":"115年第2次第78題","year":115,"session":2,"number":78,"question":"薛格連氏症候群（Sjögren syndrome）具備下列何種特徵？","options":["(A) 腎絲球病變是常見的病變","(B) anti-SS-A或anti-SS-B抗體是此病的專一性自體抗體","(C) 最常見併發的惡性淋巴瘤是T細胞淋巴瘤","(D) 類風濕因子（rheumatoid factor）陽性常見於此病"],"answer":3,"image":""},{"id":"md2-115-2-79","subject":"md2","topic":"病理-免疫感染遺傳","meta":"115年第2次第79題","year":115,"session":2,"number":79,"question":"下列何種疾病的致病機制與第二型過敏反應最有關？","options":["(A) 重症肌無力（myasthenia gravis）","(B) 狼瘡腎炎（lupus nephritis）","(C) 血清病（serum sickness）","(D) 接觸性皮膚炎（contact dermatitis）"],"answer":0,"image":""},{"id":"md2-115-2-80","subject":"md2","topic":"公衛-生物統計與流行病學","meta":"115年第2次第80題","year":115,"session":2,"number":80,"question":"臺灣這20年來，子宮頸癌死亡率逐年穩定下降的最重要原因是：","options":["(A) 子宮頸抹片（Pap smear）檢查的普及","(B) 人類乳突病毒（human papillomavirus）疫苗的發展","(C) 口服避孕藥的使用","(D) 全民健康保險的實施"],"answer":0,"image":""},{"id":"md2-115-2-81","subject":"md2","topic":"病理-細胞傷害發炎腫瘤","meta":"115年第2次第81題","year":115,"session":2,"number":81,"question":"急性心肌梗塞後打通血管達到再灌流（reperfusion）時，下列敘述何者錯誤？","options":["(A) 肌鈣蛋白（troponin）持續上升","(B) 自由基增加","(C) 白血球聚集","(D) 不再損失心肌細胞"],"answer":3,"image":""},{"id":"md2-115-2-82","subject":"md2","topic":"病理-心血管血液","meta":"115年第2次第82題","year":115,"session":2,"number":82,"question":"一般情況下，下列何種心內膜炎的增殖體（vegetation）中含有最少量的發炎細胞？","options":["(A) 非細菌性血栓性心內膜炎（nonbacterial thrombotic endocarditis）","(B) 細菌造成的感染性心內膜炎","(C) 人工瓣膜的感染性心內膜炎","(D) Libman-Sacks氏心內膜炎（Libman-Sacks disease）"],"answer":0,"image":""},{"id":"md2-115-2-83","subject":"md2","topic":"病理-心血管血液","meta":"115年第2次第83題","year":115,"session":2,"number":83,"question":"下列何者並非已知可能造成擴大性心肌病變（dilated cardiomyopathy）的原因？","options":["(A) 酒精成癮","(B) 心肌炎的後遺症","(C) 放射線治療造成之纖維化","(D) 先天基因突變"],"answer":2,"image":""},{"id":"md2-115-2-84","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"115年第2次第84題","year":115,"session":2,"number":84,"question":"55歲男性，臨床表現為肌肉無力，抽血測得對抗乙醯膽鹼受器的自體抗體（anti-acetylcholine receptor autoantibody），電腦斷層掃描發現前縱隔腫瘤，此腫瘤最可能是下列何者？","options":["(A) 鱗狀細胞癌（squamous cell carcinoma）","(B) 畸胎瘤（teratoma）","(C) 胸腺瘤（thymoma）","(D) 類癌（carcinoid）"],"answer":2,"image":""},{"id":"md2-115-2-85","subject":"md2","topic":"病理-心血管血液","meta":"115年第2次第85題","year":115,"session":2,"number":85,"question":"有關骨髓化生不良症候群（myelodysplastic syndrome）的敘述，下列何者最適當？","options":["(A) 10％～40％的病人會進展成急性骨髓性白血病（acute myeloid leukemia）","(B) 病人多數為兒童及青少年","(C) 血液中的紅血球、白血球及血小板通常會比正常人多","(D) 骨髓中的造血細胞（hematopoietic cells）形態正常"],"answer":0,"image":""},{"id":"md2-115-2-86","subject":"md2","topic":"病理-呼吸消化","meta":"115年第2次第86題","year":115,"session":2,"number":86,"question":"下列有關惡性間皮細胞瘤（malignant mesothelioma）的敘述，何者錯誤？","options":["(A) 可發生在臟側肋膜（visceral pleura）或體側肋膜（parietal pleura）","(B) 大多數病人可存活超過兩年","(C) 鑑別診斷包含轉移到肋膜的肺腺癌，可用免疫組織化學染色來幫助診斷","(D) 常見突變的基因有CDKN2A、BAP1、NF2"],"answer":1,"image":""},{"id":"md2-115-2-87","subject":"md2","topic":"病理-呼吸消化","meta":"115年第2次第87題","year":115,"session":2,"number":87,"question":"下列有關孤立性纖維瘤（solitary fibrous tumor）的敘述，何者正確？","options":["(A) 角質蛋白（keratin）的免疫組織化學染色呈陽性","(B) CD34的免疫組織化學染色呈陰性","(C) 與石綿暴露關係密切","(D) 最常見於肋膜"],"answer":3,"image":""},{"id":"md2-115-2-88","subject":"md2","topic":"病理-呼吸消化","meta":"115年第2次第88題","year":115,"session":2,"number":88,"question":"有關大葉性肺炎（lobar pneumonia）進展之四個時期，按先後順序排列，下列何者正確？①灰色肝變期（gray hepatization） ②紅色肝變期（red hepatization） ③充血期（congestion） ④緩解期（resolution）","options":["(A) ①③②④","(B) ③②①④","(C) ③①②④","(D) ②③①④"],"answer":1,"image":""},{"id":"md2-115-2-89","subject":"md2","topic":"病理-呼吸消化","meta":"115年第2次第89題","year":115,"session":2,"number":89,"question":"關於幽門螺旋桿菌相關性胃炎，下列敘述何者最不適當？","options":["(A) 通常胃體（body）比胃竇（antrum）更容易有幽門螺旋桿菌感染","(B) 與增生性息肉及發炎息肉（hyperplastic polyp and inflammatory polyp）有關","(C) 幽門螺旋桿菌體集中在表面和頸部區域（surface and neck regions）上皮細胞上的表面黏液","(D) 與十二指腸潰瘍有關"],"answer":0,"image":""},{"id":"md2-115-2-90","subject":"md2","topic":"病理-呼吸消化","meta":"115年第2次第90題","year":115,"session":2,"number":90,"question":"關於胃淋巴瘤，下列敘述何者最不適當？","options":["(A) 胃最常見的淋巴瘤種類是淋巴結外邊緣區B細胞淋巴瘤（extranodal marginal zone B-cell lymphoma）","(B) 幽門螺旋桿菌感染是胃MALT瘤（MALToma）最常見的誘發因素","(C) 胃MALT瘤（MALToma）轉化為瀰漫性大B細胞淋巴瘤（diffuse large B-cell lymphoma）的情況通常與p53及p16的失活（inactivation）有關","(D) 胃MALT瘤（MALToma）相關的最常見基因易位是t(9;22)(q21;q21)"],"answer":3,"image":""},{"id":"md2-115-2-91","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第2次第91題","year":115,"session":2,"number":91,"question":"下列對於第一型自體免疫胰臟炎（type 1 autoimmune pancreatitis）的敘述，何者最不適當？","options":["(A) 常出現CFTR或PRSS1的突變","(B) 許多漿細胞（plasma cell）浸潤及纖維化","(C) 常見靜脈炎（phlebitis）的表現","(D) 與IgG4相關疾病（IgG4-related disease）有關"],"answer":0,"image":""},{"id":"md2-115-2-92","subject":"md2","topic":"病毒學","meta":"115年第2次第92題","year":115,"session":2,"number":92,"question":"多瘤病毒（polyomavirus）最常感染腎臟中下列何種細胞，並產生核內包涵體（intranuclear inclusion）？","options":["(A) 腎小管上皮細胞（tubular epithelial cells）","(B) 足細胞（podocytes）","(C) 單核球細胞（monocytes）","(D) 膈細胞（mesangial cells）"],"answer":0,"image":""},{"id":"md2-115-2-93","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第2次第93題","year":115,"session":2,"number":93,"question":"膀胱扁平原位癌（flat carcinoma in situ）最常見下列那些基因的突變？","options":["(A) TSC1和TSC2","(B) RAS和FGFR3","(C) EWS和FLI-1","(D) TP53和RB"],"answer":3,"image":""},{"id":"md2-115-2-94","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第2次第94題","year":115,"session":2,"number":94,"question":"關於原發性膜性腎病變（membranous nephropathy），下列敘述何者正確？","options":["(A) 原發性膜性腎病變中，大多數病人體內可測到針對磷脂酶A2受體（phospholipase A2 receptor）自體抗體","(B) 次發性膜性腎病變，誘發原因包含感染、惡性腫瘤、藥物等，大多數病人體內可偵測到針對基底膜的自體抗體","(C) 光學顯微鏡下可見腎絲球血管壁呈現銳角狀分叉，並合併有膈細胞（mesangial cells）明顯增生","(D) 電子顯微鏡下可見免疫沉澱物主要沉著於膈細胞（mesangial cells）下方，造成基底膜增厚"],"answer":0,"image":""},{"id":"md2-115-2-95","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第2次第95題","year":115,"session":2,"number":95,"question":"有關睪丸腫瘤的描述，下列何者正確？","options":["(A) 單側隱睪症病人的雙側睪丸罹患生殖細胞腫瘤的風險增加","(B) 大於60歲的男性，最常見的睪丸腫瘤是精原細胞性腫瘤（spermatocytic tumor）","(C) 兒童的睪丸畸胎瘤（teratoma）病灶常可見到原位生殖細胞瘤（germ cell neoplasia in situ）","(D) 畸胎瘤（teratoma）是兒童最常見的生殖細胞腫瘤"],"answer":[0,3],"image":"","answer_note":"更正:第95題答Ａ或Ｄ或AD者均給分"},{"id":"md2-115-2-96","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第2次第96題","year":115,"session":2,"number":96,"question":"關於無排卵週期（anovulatory cycle），下列敘述何者最不適當？","options":["(A) 無排卵週期肇因於輕微的內分泌失衡（subtle hormonal imbalance），所以在停經後（postmenopausal）最常看到","(B) 內分泌系統的病變也可能引起無排卵週期，例如甲狀腺疾病、腦垂腺腫瘤等","(C) 卵巢病灶亦會造成無排卵週期，例如多囊性卵巢（polycystic ovary）等","(D) 排卵失敗會造成子宮內膜過度的動情激素（estrogen）刺激"],"answer":0,"image":""},{"id":"md2-115-2-97","subject":"md2","topic":"病理-腎泌尿內分泌生殖","meta":"115年第2次第97題","year":115,"session":2,"number":97,"question":"完全性葡萄胎（complete mole）最常見的核型是：","options":["(A) 46,XX","(B) 46,XY","(C) 69,XXY","(D) 92,XXXY"],"answer":0,"image":""},{"id":"md2-115-2-98","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"115年第2次第98題","year":115,"session":2,"number":98,"question":"下列皮膚水泡性疾病，何者是以IgA沿表皮與真皮層交界分布為主要診斷特徵？","options":["(A) pemphigus","(B) bullous pemphigoid","(C) epidermolysis bullosa","(D) dermatitis herpetiformis"],"answer":[0,1,2,3],"image":"","answer_note":"送分:第98題一律給分 (原公告答案 D)"},{"id":"md2-115-2-99","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"115年第2次第99題","year":115,"session":2,"number":99,"question":"下列有關庫魯斑塊（Kuru plaques）的敘述，何者最不適當？","options":["(A) 最常為Aβ蛋白質沉積","(B) 可能與克雅氏病（Creutzfeldt-Jakob disease）有關","(C) 剛果紅（Congo red）染色可呈現陽性反應","(D) 較常發現於小腦"],"answer":0,"image":""},{"id":"md2-115-2-100","subject":"md2","topic":"病理-神經肌骨皮膚","meta":"115年第2次第100題","year":115,"session":2,"number":100,"question":"下列有關腦膜瘤（meningioma）的敘述，何者最不適當？","options":["(A) 大多屬於良性腫瘤","(B) 較少見於小孩","(C) 懷孕時受到黃體素（progesterone）影響，腫瘤生長較慢","(D) 可能與第22對染色體缺失有關"],"answer":2,"image":""}];
